COLLDATA("nasai","ur",[[2121,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے رمضان کا ذکر کیا تو فرمایا: \"تم روزہ نہ رکھو یہاں تک کہ چاند دیکھ لو، اور روزہ رکھنا بند کرو یہاں تک کہ (چاند) دیکھ لو، (اور) اگر فضا ابر آلود ہو تو اس کا حساب لگا لو\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے رمضان المبارک کا ذکر فرمایا تو فرمانے لگے: ’’جب تک چاند نہ دیکھ لو، روزے رکھنا شروع نہ کرو۔ اسی طرح روزے رکھنا بند نہ کرو جب تک (شوال کا) چاند نہ دیکھ لو۔ اگر بادل ہوں (اور چاند نظر نہ آئے) تو اس مہینے کو تیس دن کا فرض کرو۔‘‘"}],[2122,"عبداللہ بن عمر رضی اللہ عنہما روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تم (رمضان کے) روزے نہ رکھو یہاں تک کہ (چاند) دیکھ لو اور نہ ہی روزے رکھنا بند کرو یہاں تک کہ (عید الفطر کا چاند) دیکھ لو (اور) اگر آسمان میں بادل ہوں تو اس (مہینے) کا حساب لگا لو\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے منقول ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’تم روزے رکھنا شروع نہ کرو حتیٰ کہ (رمضان المبارک کا) چاند دیکھ لو اور روزے رکھنا بند نہ کرو حتیٰ کہ (شوال کا) چاند دیکھ لو۔ اگر چاند نظر نہ آئے تو مہینہ تیس کا بناؤ۔‘‘"}],[2123,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے چاند کا ذکر کیا تو فرمایا: \"جب تم اسے (یعنی رمضان کا چاند) دیکھ لو تو روزہ رکھو، اور جب اسے(یعنی عید الفطر کا چاند) دیکھ لو تو روزہ بند کر دو، (اور) اگر آسمان میں بادل ہوں تو تیس دن پورے شمار کرو\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے چاند کا ذکر کیا تو فرمایا: ’’جب تم چاند دیکھو تو روزے رکھنا شروع کر دو اور جب تم چاند دیکھو تو روزے رکھنا بند کر دو اور اگر بادل ہوں (اور چاند نظر نہ آئے) تو تیس دن پورے کرو۔"}],[2124,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اسے (رمضان کا چاند) دیکھ کر روزہ رکھو، اور اسے (عید الفطر کا چاند) دیکھ کر روزہ بند کرو، (اور) اگر تم پر بادل چھائے ہوں تو تیس کی گنتی پوری کرو\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جاند دیکھ کر روزے رکھو اور چاند دیکھ کر عید کرو۔ اگر چاند چھپ جائے (نظر نہ آئے) تو اس مہینے کی گنتی تیس دن مکمل کرو۔‘‘"}],[2125,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں: مجھے حیرت ہوتی ہے اس شخص پر جو مہینہ شروع ہونے سے پہلے (ہی) روزہ رکھنے لگتا ہے، حالانکہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم (رمضان کا) چاند دیکھ لو تو روزہ رکھو، (اسی طرح) جب (عید الفطر کا چاند) دیکھ لو تو روزہ رکھنا بند کرو، (اور) جب تم پر بادل چھائے ہوں تو تیس کی گنتی پوری کرو\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ مجھے اس شخص پر تعجب ہے جو ماہ رمضان شروع ہونے سے پہلے روزہ رکھتا ہے جبکہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: ’’جب تم چاند دیکھو تو پھر روزہ رکھو اور جب اگلا چاند دیکھو تو روزے رکھنا چھوڑ دو۔ اگر چاند چھپ جائے (نظر نہ آئے) تو مہینے کی گنتی تیس دن پوری کرو۔‘‘","f2":"’’تعجب ہے‘‘ یعنی رمضان المبارک کا چاند نظر آنے سے پہلے مشکوک (شعبان کے تیسویں) دن کا روزہ نہیں رکھنا چاہیے کہ یہ تکلف اور تشدد ہے۔ صحیح روایات میں اس دن کا روزہ رکھنا رسول اللہ صلی اللہ علیہ وسلم کی نافرمانی بتلایا گیا ہے۔ جن اہل علم نے احتیاطاً نفل روزہ رکھنے کی اجازت دی ہے شاید انہوں نے ان الفاظ کی سختی پر غور نہیں فرمایا۔ باقی رہی فرض اور نفل کی تفریق (کہ فرض منع ہے نفل جائز ہے) تو یہ بات حدیث سے ثابت نہیں ہوتی۔ جب اللہ تعالیٰ نے چاند دکھانے میں احتیاط نہیں فرمائی تو ہمیں خواہ مخواہ اس احتیاط کی کیا ضرورت ہے؟ رَضِینَا بِاللّٰہِ رَبًّا"}],[2126,"حذیفہ بن یمان رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم رمضان کے مہینہ پر سبقت نہ کرو ۱؎ یہاں تک کہ (روزہ رکھنے سے)پہلے چاند دیکھ لو، یا (شعبان کی) تیس کی تعداد پوری کر لو، پھر روزہ رکھو، یہاں تک کہ (عید الفطر کا) چاند دیکھ لو، یا اس سے پہلے رمضان کی تیس کی تعداد پوری کر لو\"۔\n§وضاحت\n۱؎: یعنی رمضان کا مہینہ شروع ہونے سے پہلے روزہ نہ رکھو۔","الألباني: صحيح",{"u2":"حضرت حذیفہ بن یمان رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ماہ رمضان سے پہلے روزہ نہ رکھو حتیٰ کہ روزہ رکھنے سے پہلے (رمضان المبارک کا) چاند دیکھ لو، ورنہ (شعبان کے) تیس دن پورے کر کے روزہ رکھو، پھر تم روزے رکھتے رہو حتیٰ کہ (شوال کا) چاند دیکھ لو یا چاند دیکھنے سے پہلے تیس دن پورے کر لو۔‘‘","f2":"اس روایت میں صراحتاً چاند نظر آنے سے پہلے روزہ رکھنے سے روکا گیا ہے۔ اور اسی پر عمل چاہیے۔"}],[2127,"ایک صحابی رسول رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم رمضان کے مہینہ پر سبقت نہ کرو یہاں تک کہ شعبان کی گنتی پوری کر لو، یا رمضان کا چاند دیکھ لو پھر روزہ رکھو، اور نہ روزہ بند کرو یہاں تک کہ تم عید الفطر کا چاند دیکھ لو، یا رمضان کی تیس (دن) کی گنتی پوری کر لو\"۔ حجاج بن ارطاۃ نے اسے مرسلاً روایت کیا ہے۔","الألباني: صحيح",{"u2":"نبی صلی اللہ علیہ وسلم کے ایک صحابی رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ماہ رمضان المبارک سے پہلے روزے رکھنا شروع نہ کرو حتیٰ کہ (شعبان) کے تیس دن پورے کرو یا (رمضان کا) چاند دیکھ لو، پھر روزے رکھتے رہو اور روزے رکھنے بند نہ کرو حتیٰ کہ (شوال کا) چاند دیکھ لو یا (رمضان المبارک کے) تیس روزے پورے کر لو۔‘‘\nحجاج بن ارطاۃ نے اس روایت کو مرسل ذکر کیا ہے (کہ انہوں نے صحابی کا واسطہ ہی ختم کر دیا اور اسے ربعی کی روایت بنا دیا، حالانکہ وہ صحابی نہیں)","f2":"چونکہ قمری مہینہ تیس دن سے زائد ہوتا ہی نہیں، لہٰذا تیس دن پورے ہونے کے بعد چاند دیکھنا ضروری نہیں۔"}],[2128,"ربعی کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم (رمضان کا) چاند دیکھ لو تو روزہ رکھو، اور جب اسے (عید الفطر کا چاند) دیکھ لو تو روزہ بند کر دو،(اور) اگر تم پر بادل چھا جائیں تو شعبان کے تیس دن پورے کرو، مگر یہ کہ اس سے پہلے چاند دیکھ لو، پھر رمضان کے تیس روزے رکھو، مگر یہ کہ اس سے پہلے چاند دیکھ لو\"۔","الألباني: صحيح لغيره",{"u2":"حضرت ربعی سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم (رمضان المبارک کا) چاند دیکھ لو تو روزے شروع کرو اور جب تم (شوال کا) چاند دیکھ لو تو روزے رکھنا بند کر دو۔ اگر بادل ہوں (اور تمہیں چاند نظر نہ آئے) تو شعبان کے تیس دن پورے کرو، الا یہ کہ تم اس سے پہلے چاند دیکھ لو، پھر تیس دن روزے رکھو، الا یہ کہ اس سے پہلے چاند دیکھ لو۔"}],[2129,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اسے (رمضان کے چاند کو) دیکھ کر روزہ رکھو، اور اسے (یعنی عید الفطر کے چاند کو) دیکھ کر روزہ بند کرو، (اور) اگر تمہارے اور اس کے بیچ بدلی حائل ہو جائے تو تیس کی گنتی پوری کرو، اور (ایک یا دو دن پہلے سے رمضان کے) مہینہ کا استقبال نہ کرو\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ بیان فرماتے ہیں، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’چاند دیکھ کر روزے رکھو اور چاند دیکھ کر روزے ختم کرو۔ اگر تمہارے اور چاند کے درمیان بادل حائل ہو جائیں (اور چاند نظر نہ آئے) تو معروف گنتی (تیس دن) پوری کرو اور ماہ رمضان المبارک کے شروع ہونے سے پہلے روزہ نہ رکھو۔‘‘","f2":"اگرچہ روایت سنداً ضعیف ہے لیکن کثیر شواہد ومتابعات کی وجہ سے متن حدیث صحیح ہے۔"}],[2130,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"رمضان سے پہلے روزہ مت رکھو، چاند دیکھ کر روزہ رکھو، اور (چاند) دیکھ کر(روزہ) بند کرو، (پس) اگر چاند سے ورے بادل حائل ہو جائے تو تیس (دن) پورے کرو\"۔\n§وضاحت\n۱؎: \"رمضان سے پہلے\" سے مراد شعبان کا آخری دن ہے، مطلب یہ ہے کہ صرف یہ خیال کر کے روزہ مت شروع کر دو کہ آج ۲۹ شعبان ہے تو ممکن ہے کہ کل سے رمضان شروع ہو جائے گا، بلکہ یقینی طور پر چاند دیکھ کر ہی روزہ شروع کرو، یا پھر تیس کی گنتی پوری کرو۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’رمضان المبارک شروع ہونے سے پہلے روزہ نہ رکھو بلکہ چاند دیکھ کر روزہ رکھو اور چاند دیکھ کر ہی روزے رکھنے بند کرو۔ اگر چاند نظر آنے میں بادل رکاوٹ بن جائیں تو تیس دن پورے کرو۔‘‘","f2":"اس مفہوم کی روایات کی اس قدر تکرار بعض اسنادی اختلاف ظاہر کرنے کے لیے ہے جن کا علم مذکورہ روایات کی سندوں کے گہرے جائزے سے ہوگا، البتہ اس اختلاف کا حدیث کے متن پر کوئی منفی اثرات نہیں پڑتا کیونکہ متن متفق علیہ ہے، بلکہ اس تکرار سے متن کو تقویت حاصل ہوتی ہے کہ وہ کثیر صحابہ اور بہت زیادہ راویوں سے مروی ہے۔ یہ بات بھی یاد رکھنے کی ہے کہ اختلاف سے مراد ہر جگہ غلطی نہیں ہوتی بلکہ بہت سے مقامات پر اختلاف کا مطلب یہ بھی ہوتا ہے کہ یہ حدیث ان تمام صحابہ اور تابعین وغیرہ سے آتی ہے اور یہ سب سندیں صحیح ہیں۔"}],[2131,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے قسم کھائی کہ ایک ماہ (تک) اپنی بیویوں کے پاس نہیں جائیں گے، چنانچہ آپ انتیس دن ٹھہرے رہے، تو میں نے عرض کیا: کیا آپ نے ایک مہینے کی قسم نہیں کھائی تھی؟ میں نے شمار کیا ہے، ابھی انتیس دن (ہوئے) ہیں، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مہینہ انتیس دن کا بھی ہوتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ (ایک دفعہ) رسول اللہ صلی اللہ علیہ وسلم نے (ناراضی کی بنا پر) قسم کھا لی کہ اپنی بیویوں کے پاس ایک مہینہ تک نہیں جاؤں گا۔ آپ انتیس دن تک اسی حال میں رہے۔ (پھر میرے پاس تشریف لائے) میں نے (یاد دہانی کے طورپر) عرض کیا کہ آپ نے ایک ماہ کی قسم نہیں کھائی تھی میں نے تو انتیس دن شمار کیے ہیں؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مہینہ انتیس دن کا بھی ہوتا ہے۔‘‘","f2":"(۱) اختلاف یہ ہے کہ زہری کے بعض شاگردوں نے اس حدیث کو حضرت عائشہ رضی اللہ عنہا کی طرف منسوب کیا ہے اور بعض نے حضرت ابن عباس رضی اللہ عنہ کی طرف، تاہم یہ اختلاف ضرر رساں نہیں، حدیث دونوں سے صحیح طور پر ثابت ہے۔ (۲)’’قسم کھالی۔‘‘ اس طرح کی قسم کو شرعی زبان میں ’’ایلائ‘‘ کہتے ہیں۔ خاوند بیوی میں اگر کوئی ناچاقی ہو جائے تو خاوند اپنی بیوی سے وقتی طور پر تعلقات منقطع کر سکتا ہے مگر گھر میں رہنا ضروری ہے تاکہ عورت کوئی غلط قدم نہ اٹھائے۔ یہ کیفیت زیادہ سے زیادہ چار ماہ تک رہ سکتی ہے۔ اگر قسم اس سے زیادہ کی ہو تو قسم توڑنا فرض ہے اور چار ماہ کے بعد فوراً تعلقات قائم کرنا ضروری ہے ورنہ اسے طلاق دینا پڑے گی۔ وہ دونوں میں سے کوئی بھی کام نہ کرے تو قاضی یا حاکم اپنی طرف سے اسے مصاحبت پر مجبور کرے گا یا طلاق نافذ کر دے گا اور وہ عورت اس سے مستقل طور پر جدا ہو جائے گی۔ اگر مدت کم ہو تو قسم پوری کر سکتا ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے صرف ایک ماہ کی قسم کھائی تھی، لہٰذا آپ نے قسم پوری کی۔ اس واقعے کی تفصیل ان شاء اللہ آگے آئے گی۔ (۳)’’مہینہ انتیس دن کا بھی ہوتا ہے۔‘‘ یعنی قمری مہینہ جو احکام اسلامی میں معتبر ہے، تیس دن کا بھی ہوتا ہے اور انتیس کا بھی، لہٰذا انتیس دن کو بھی کامل مہینہ شمار کیا جائے گا۔ ایک مہینے کی قسم شرعاً انتیس دن کے لیے ہوگی۔ یہ اس جملے کا صحیح مفہوم ہے۔ بعض اہل علم نے یوں معنی کیا ہے کہ ’’یہ مہینہ انتیس کا ہے۔‘‘ گویا اپ نے پہلی تاریخ کا چاند دیکھ کر قسم کھائی اور اگلا چاند دیکھ کر داخل ہوئے، مگر یہ بہت بعید بات ہے کہ آپ نے ناراضی کے باوجود چاند دیکھنے تک انتظار کیا اور پھر قسم کھائی اور پھر اگلا چاند دیکھتے ہی آپ داخل ہوئے۔ کیا جھگڑا عین چاند والے دن ہوا تھا؟ کسی حدیث میں اس کی صراحت نہیں۔ نہ یہ معنی دل کو لگتا ہے جبکہ پہلا معنی بالکل واضح ہے۔ واللہ اعلم"}],[2132,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں: مجھے برابر اس بات کا اشتیاق رہا کہ عمر بن خطاب رضی اللہ عنہ سے رسول اللہ صلی اللہ علیہ وسلم کی ان دونوں بیویوں کے بارے میں پوچھوں جن کا ذکر اللہ تعالی نے آیت کریمہ: «إن تتوبا إلى اللہ فقد صغت قلوبكما» \"اگر تم دونوں اللہ تعالی سے توبہ کر لو (تو بہتر ہے)یقیناً تمہارے دل جھک پڑے ہیں\" (التحریم: ۴) میں کیا ہے، پھر پوری حدیث بیان کی، اس میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنی بیویوں سے انتیس راتوں تک اس بات کی وجہ سے جو حفصہ رضی اللہ عنہا نے عائشہ رضی اللہ عنہا سے ظاہر کر دی تھی کنارہ کشی اختیار کر لی، عائشہ رضی اللہ عنہا کہتی ہیں: آپ نے اپنی اس ناراضگی کی وجہ سے جو آپ کو اپنی عورتوں سے اس وقت ہوئی تھی جب اللہ تعالی نے ان کی بات آپ کو بتلائی یہ کہہ دیا تھا کہ میں ان کے پاس ایک مہینہ تک نہیں جاؤں گا، تو جب انتیس راتیں گزر گئیں تو آپ سب سے پہلے عائشہ رضی اللہ عنہا کے پاس آئے تو انہوں نے آپ سے عرض کیا: اللہ کے رسول! آپ نے تو ایک مہینے تک ہمارے پاس نہ آنے کی قسم کھائی تھی، اور ہم نے (ابھی) انتیسویں رات کی (ہی) صبح کی ہے، ہم ایک ایک کر کے اسے گن رہے ہیں؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مہینہ انتیس راتوں کا بھی ہوتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے کہ میں عرصہ دراز سے خواہش مند تھا کہ میں حضرت عمر بن خطاب رضی اللہ عنہ سے رسول اللہ صلی اللہ علیہ وسلم کی ازواج مطہرات میں سے ان دو عورتوں کے بارے میں پوچھوں جن کے بارے میں اللہ تعالیٰ نے فرمایا: {اِِنْ تَتُوْبَا اِِلَی اللّٰہِ فَقَدْ صَغَتْ قُلُوْبُکُمَا} ’’اگر تم اللہ تعالیٰ کی طرف رجوع کرو تو یہ نہایت مناسب ہے کیونکہ تمہارے دل کج (ٹیڑھے) ہوگئے ہیں۔‘‘ پھر حضرت ابن عباس رضی اللہ عنہ نے پوری حدیث بیان فرمائی۔ اس تفصیلی حدیث میں حضرت عمر رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم اس بات کی وجہ سے جسے حضرت حفصہ رضی اللہ عنہا نے حضرت عائشہ رضی اللہ عنہا کے سامنے فاش (ظاہر) کر دیا تھا، انتیس دن تک اپنی بیویوں سے جدا رہے۔ حضرت عائشہ رضی اللہ عنہا نے فرمایا: آپ نے (قسم کھا کر) فرمایا تھا: ’’میں اپنی بیویوں کے پاس ایک مہینے تک نہیں آؤں گا۔‘‘ جس وقت اللہ تعالیٰ نے آپ کو یہودیوں کی بات بتائی تو آپ ان پر سخت ناراض ہوگئے تھے جب انتیس دن گزر گئے تو سب سے پہلے آپ حضرت عائشہ رضی اللہ عنہا کے پاس تشریف لے گئے۔ حضرت عائشہ رضی اللہ عنہا کہنے لگیں: اے اللہ کے رسول! آپ نے تو قسم کھائی تھی کہ ایک ماہ تک ہمارے پاس تشریف نہ لائیں گے اور آج تو انتیسویں دن کی صبح ہے۔ ہم نے یہ دن گن گن کر گزارے ہیں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مہینہ انتیس کا بھی ہوتا ہے۔‘‘","f2":"(۱)ناراضی کے واقعے کی پوری تفصیل تو ان شاء اللہ اپنے مقام پر آئے گی لیکن اتنا جان لینا کافی ہے کہ آپ نے ایک راز حضرت حفصہ رضی اللہ عنہا کے حوالے کیا تھا اور تاکید فرمائی تھی کہ کسی تک یہ راز نہ پہنچے مگر وہ اپنی فطری کمزوری کی بنا پر راز کو راز نہ رکھ سکیں۔ حضرت عائشہ رضی اللہ عنہا کو بتا بیٹھیں اور ہوتے ہوتے یہ بات سب ازواج مطہرات رضی اللہ عنہم تک پہنچ گئی جس سے آپ صلی اللہ علیہ وسلم کو دکھ اٹھانا پڑا۔ ایک دو واقعات اور بھی ہوئے، ان تمام وجوہ سے آپ کی ناراضی شدید ہوگئی۔ (۲) جب محسوس ہو کہ آدمی قسم توڑ رہا ہے تو اسے یاد کرایا جا سکتا ہے۔"}],[2133,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"میرے پاس جبرائیل علیہ السلام آئے اور انہوں نے کہا: مہینہ انتیس دن کا بھی ہوتا ہے\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’میرے پاس حضرت جبریل علیہ السلام آئے اور بتایا کہ مہینہ انتیس دن کا بھی ہوتا ہے۔"}],[2134,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مہینہ انتیس دن کا بھی ہوتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مہینہ انتیس دن کا بھی ہوتا ہے۔‘‘"}],[2135,"سعد بن ابی وقاص رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے اپنا (ایک) ہاتھ دوسرے ہاتھ پر مارا اور فرمایا: \"مہینہ اس طرح ہے، اس طرح ہے، اور اس طرح ہے\"، اور تیسری بار میں ایک انگلی دبا لی ۱؎۔\n§وضاحت\n۱؎: یعنی آپ نے دونوں ہاتھوں کی دسوں انگلیوں سے دو بار اشارہ کیا، اور تیسری بار میں ایک انگلی گرا لی، تو یہ کل انتیس دن ہوئے۔","الألباني: صحيح",{"u2":"حضرت سعد بن ابی وقاص رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے ایک دست مبارک کو دوسرے پر مارا اور فرمایا: ’’کبھی مہینہ اتنا، اتنا اور اتنا بھی ہوتا ہے اور تیسری دفعہ آپ نے ایک انگلی کم کر لی۔‘‘ (یعنی انتیس)۔"}],[2136,"سعد بن ابی وقاص رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مہینہ اس طرح ہے، اس طرح ہے اور اس طرح ہے\"، یعنی انتیس دن کا بھی ہوتا ہے۔ اسے یحیی بن سعید وغیرہ نے اسماعیل سے، انہوں نے محمد بن سعد بن ابی وقاص سے، اور محمد بن سعد نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کیا ہے۔","الألباني: صحيح",{"u2":"حضرت سعد رضی اللہ عنہ سے مروی ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’مہینہ کبھی اتنا، اتنا اور اتنا بھی ہوتا ہے۔‘‘ (یعنی انتیس دن کا)۔\nیحییٰ بن سعید وغیرہ نے اس روایت کو بواسطہ اسماعیل، محمد بن سعد سے (صحابی رسول سعد بن ابی وقاص رضی اللہ عنہ کے واسطے کے بغیر) نبی اکرم صلی اللہ علیہ وسلم سے بیان کیا ہے، یعنی مرسلاً۔"}],[2137,"محمد بن سعد بن ابی وقاص کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مہینہ اس طرح ہے، اس طرح ہے، اور اس طرح ہے\"۔ اور محمد بن عبید نے اپنے دونوں ہاتھوں کو تین بار ملا کر بتلایا، پھر تیسری بار میں بائیں ہاتھ کا انگوٹھا بند کر لیا، یحیی بن سعید کہتے ہیں: میں نے اسماعیل بن ابی خالد سے «عن أبیہ» کی زیادتی کے بارے میں پوچھا، تو انہوں نے کہا: نہیں۔","الألباني: صحيح",{"u2":"حضرت محمد بن سعد بن ابی وقاص سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مہینہ اتنا، اتنا اور اتنا بھی ہوتا ہے۔‘‘ (حدیث کے راوی) محمد بن عبید نے اپنے دونوں ہاتھوں کی ہتھیلیاں کھول کر سامنے کیں۔ تین دفعہ ایسے کیا اور تیسری دفعہ بائیں ہاتھ کے انگوٹھے کو بند کر لیا۔\nیحییٰ بن سعید کہتے ہیں: میں نے اسماعیل سے پوچھا: کیا محمد بن سعد نے اس روایت کو اپنے باپ (سعد بن ابی وقاص) سے بیان کیا ہے؟ انہوں نے کہا: نہیں (بلکہ مرسلاً بیان کیا ہے)۔","f2":"اس روایت میں تابعی حضرت محمد بن سعد کہہ رہے ہیں: قَالَ رَسُوْلُ اللّٰہِ… الخ، صحابی کا واسطہ نہیں، لہٰذا یہ روایت مرسل ہے۔"}],[2138,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مہینہ (کبھی) انتیس دن کا ہوتا ہے، اور (کبھی) تیس دن کا، اور جب تم (چاند) دیکھ لو تو روزہ رکھو اور جب اسے دیکھ لو تو روزہ رکھنا بند کرو، (اور) اگر تم پر بادل چھا جائیں تو (تیس کی) گنتی پوری کرو\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مہینہ کبھی انتیس دن کا اور کبھی تیس دن کا ہوتا ہے۔ جب تم چاند دیکھو تو روزے رکھنا شروع کرو اور جب تم چاند دیکھو تو روزے رکھنا بند کر دو اور اگر بادل ہوں (اور چاند نظر نہ آئے) تو (تیس دن کی) گنتی پوری کرو۔‘‘"}],[2139,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"مہینہ انتیس دن کا بھی ہوتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’مہینہ انتیس کا (بھی ہوتا) ہے۔‘‘"}],[2140,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہم «اُمّی» لوگ ہیں، نہ ہم لکھتے پڑھتے ہیں اور نہ حساب کتاب کرتے ہیں، مہینہ اس طرح ہے، اس طرح ہے، اور اس طرح ہے\"، (ایسا تین بار کیا) یہاں تک کہ انتیس دن کا ذکر کیا۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’ہم امی لوگ ہیں۔ ہم حساب کتاب نہیں جانتے۔ مہینہ اتنا، اتنا اور اتنا ہوتا ہے۔‘‘ تین دفعہ ہاتھوں سے اشارہ فرمایا حتیٰ کہ انتیس ہوگئے۔","f2":"’’امی لوگ‘‘ یعنی ہم تو فطری علم سے آسنا ہیں جس میں غلطی کا امکان نہیں۔ ہم نے حساب کتاب نہیں پڑھا، لہٰذا ہم علم ریاضی، علم نجوم وہیئت وغیرہ سے واقف نہیں۔ نہ ہمارے ماہ وسال ہی کا حساب ان علوم سے ہے بلکہ ہم چاند کو دیکھ کر مہینے کا حساب لگاتے ہیں جو کبھی تیس کا ہوتا ہے، کبھی انتیس کا اور یہی حقیقی مہینہ ہے۔ بخلاف شمسی مہینے کے کہ وہ فرضی ہے۔ اس میں کوئی ظاہری علامت نہیں۔"}],[2141,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم آپ نے فرمایا: \"ہم «اُمّی» لوگ ہیں، نہ تو ہم لکھتے ہیں، اور نہ حساب کتاب کرتے ہیں، مہینہ اس طرح ہے، اس طرح ہے اور اس طرح ہے\"، اور تیسری بار انگوٹھا بند کر لیا، \"مہینہ اس طرح ہے، اس طرح ہے، اور اس طرح ہے، پورے تیس دن\" ۱؎۔\n§وضاحت\n۱؎: یعنی مہینہ کبھی ۲۹ دن کا ہوتا ہے، اور کبھی تیس دن کا۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ بیان فرماتے ہیں، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’ہم امی لوگ ہیں، ہم حساب کتاب نہیں جانتے۔ کبھی مہینہ اتنا، اتنا اور اتنا ہوتا ہے۔‘‘ تیسری دفعہ آپ نے انگوٹھا بند فرما لیا (یعنی انتیس دن کا)۔ ’’اور کبھی مہینہ اتنا، اتنا اور اتنا ہوتا ہے۔‘‘ یعنی پورے تیس دن کا۔","f2":"مہینہ انتیس کا ہو یا تیس کا، بہر صورت وہ کامل ہوتا ہے، احکام میں بھی اور ثواب میں بھی۔"}],[2142,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"مہینہ اس طرح ہے\"۔ شعبہ نے جبلہ سے نقل کیا، انہوں نے ابن عمر رضی اللہ عنہما سے کہ مہینہ انتیس دن کا (بھی) ہوتا ہے، اس طرح کہ انہوں نے دو بار اپنے دونوں ہاتھوں کی انگلیوں سے اشارہ کیا، اور تیسری بار ایک انگلی دبا لی۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’مہینہ کبھی اتنا ہوتا ہے۔‘‘ شعبہ نے جبلہ بن سحیم کی نقل کی اور انہوں نے حضرت عبداللہ بن عمر رضی اللہ عنہ کی کہ مہینہ انتیس دن کا (بھی) ہوتا ہے۔ انہوں نے اس طرح سے بیان کیا کہ وہ دو دفعہ آپ نے دونوں ہاتھوں کی پوری انگلیاں کھولیں اور تیسری دفعہ ایک انگلی کم (بند) کر لی۔"}],[2143,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مہینہ انتیس دن کا بھی ہوتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مہینہ انتیس کا بھی ہوتا ہے۔‘‘","f2":"لہٰذا ایک مہینے کی قسم انتیس دن میں پوری ہو جاتی ہے۔ (اس قدر تکرار کا فائدہ کیا ہے؟ دیکھئے، حدیث: ۲۱۳۲)"}],[2144,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سحری کھاؤ، کیونکہ سحری میں برکت ہے\"۔ عبیداللہ بن سعید نے اسے موقوفاً روایت کیا ہے۔","الألباني: حسن صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سحری کھایا کرو، بلا شبہ سحری کھانے میں برکت ہے۔‘‘\nعبیداللہ بن سعید نے اس روایت کو موقوف بیان کیا ہے۔","f2":"(۱) سحری کھانا مستحب ہے کیونکہ اس سے روزہ نبھانا آسان ہوگا، جسمانی قوت برقرار ہے گی اور پھر روزے کی نیت سے کھانے کی وجہ سے ثواب بھی ہوگا، گویا کہ ہم خرما وہم ثواب۔ لیکن یہ روزے کے لیے واجب ہے نہ شرط، البتہ افضل ہے کیونکہ رسول اللہ صلی اللہ علیہ وسلم کی سنت ہے، نیز اہل کتاب کے روزے سے ہمارے روزے کا امتیاز سحری ہی سے ہے۔ سحری کی وجہ سے نیت بر وقت ہوگی اور صبح کے وقت جاگنے کا موقع ملے گا جو دعا وتہجد کا وقت ہے۔ غرض بہت سے دنیوی اور اخروی فوائد ہیں۔ برکت سے مراد یہ سب کچھ ہے۔ (۲) برکت کے لفظ سے بھی معلوم ہوتا ہے کہ سحری واجب نہیں، مستحب ہے۔"}],[2145,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں: سحری کھاؤ۔ عبیداللہ کہتے ہیں: میں نہیں جانتا کہ اس کے الفاظ کیا تھے؟","",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ فرماتے ہیں، سحری کھاؤ۔ (راوی حدیث) عبیداللہ نے کہا: میں نہیں جانتا اس کے (صحیح) الفاظ کیا ہیں؟","f2":"مقصد یہ ہے کہ یہ روایت موقوف بھی آئی ہے، یعنی صحابی کا اپنا قول، رسول اللہ صلی اللہ علیہ وسلم کا ذکر کیے بغیر۔"}],[2146,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سحری کھاؤ، کیونکہ سحری میں برکت ہے\"۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سحری کھایا کرو، یقینا اس میں برکت ہے۔‘‘"}],[2147,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سحری کھاؤ، کیونکہ سحری میں برکت ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سحری کھایا کرو، بلا شبہ سحری کھانے میں برکت ہے۔‘‘"}],[2148,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ سحری کھاؤ، کیونکہ سحری میں برکت ہے۔ ابن ابی لیلی نے اسے مرفوعاً بیان کیا ہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ سحری کھاؤ، بلا شبہ سحری کھانے میں برکت ہے۔ حضرت ابن ابی لیلیٰ نے اس روایت کو مرفوع بیان کیا ہے۔","f2":"گو حضرت ابوہریرہ رضی اللہ عنہ سے یہ روایت موقوف بھی آتی ہے مگر اس سے اس کے مرفوع ہونے میں کوئی نقص نہ آئے گا۔ نبی صلی اللہ علیہ وسلم کے فرمان کو صحابی خود بھی دہرا سکتے ہیں، یہ کوئی بعید نہیں۔"}],[2149,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"سحری کھاؤ، کیونکہ سحری میں برکت ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’سحری کھاؤ، بلا شبہ سحری کھانے میں برکت ہے۔‘‘"}],[2150,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سحری کھاؤ، کیونکہ سحری میں برکت ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سحری کھاؤ، بلا شبہ سحری کھانے میں برکت ہے۔"}],[2151,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سحری کھاؤ، کیونکہ سحری میں برکت ہے\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: یحیی بن سعید کی اس حدیث کی سند تو حسن ہے، مگر یہ منکر ہے، اور مجھے محمد بن فضیل کی طرف سے غلطی کا اندیشہ ہے ۱؎۔\n§وضاحت\n۱؎: یعنی: «عطاء عن أبي هريرة» کی بجائے «أبو سلمة عن أبي هريرة» محمد بن فضیل کی غلطی معلوم ہوتی ہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: سحری کھاؤ، یقینا سحری کھانے میں برکت ہے۔‘‘\nامام ابوعبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ یحییٰ بن سعید کی اس حدیث کی سند حسن ہے لیکن یہ روایت منکر (غلط) ہے۔ مجھے خدشہ ہے کہ یہ غلطی محمد بن فضیل سے ہوئی ہوگی۔","f2":"امام نسائی رحمہ اللہ کا مقصود یہ ہے کہ اس روایت میں ابو سلمہ کے بجائے عطاء ہی درست ہے۔"}],[2152,"زر حبیش کہتے ہیں کہ ہم نے حذیفہ رضی اللہ عنہ سے پوچھا: آپ نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ کس وقت سحری کھائی ہے؟ تو انہوں نے کہا: (تقریباً)دن ۱؎ مگر سورج ۲؎ نکلا نہیں تھا۔\n§وضاحت\n۱؎: دن سے مراد شرعی دن ہے جو طلوع صبح صادق سے شروع ہوتا ہے۔ ۲؎: سورج سے مراد طلوع فجر ہے، مطلب یہ ہے کہ آپ سحر اس وقت کھاتے جب طلوع فجر قریب ہو جاتی۔ حذیفہ رضی اللہ عنہ کی اگلی روایت سے یہی معنی متعین ہوتا ہے، نہ یہ کہ دن کا سورج نکلنے کے قریب ہونا۔","الألباني: حسن الإسناد",{"u2":"حضرت زر بیان کرتے ہیں کہ ہم نے حضرت حذیفہ رضی اللہ عنہ سے پوچھا کہ آپ نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ سحری کس وقت کھائی؟ انہوں نے فرمایا: دن شروع ہونے ہی کو تھا، بس سورج طلوع نہ ہوا تھا۔"}],[2153,"زر بن حبیش کہتے ہیں: میں نے حذیفہ رضی اللہ عنہ کے ساتھ سحری کھائی، پھر ہم نماز کے لیے نکلے، تو جب ہم مسجد پہنچے تو دو رکعت سنت پڑھی ہی تھی کہ نماز شروع ہو گئی، اور ان دونوں کے درمیان ذرا سا ہی وقفہ رہا۔","الألباني: صحيح الإسناد",{"u2":"حضرت زر بن حبیش بیان کرتے ہیں کہ میں نے حضرت حذیفہ رضی اللہ عنہ کے ساتھ سحری کھائی، پھر ہم نماز کے لیے نکلے۔ جب ہم مسجد میں آئے تو دو رکعتیں پڑھیں۔ اتنے میں جماعت کھڑی ہوگئی۔ سنتوں اور اقامت کے درمیان بالکل معمولی فاصلہ تھا۔","f2":"(۱) یہ روایت ضعیف ہے، بشرط صحت اس حدیث میں ’’دن‘‘ سے ’’شرعی دن‘‘ مراد ہوگا جو طلوع فجر سے شروع ہوتا ہے۔ حضرت حذیفہ رضی اللہ عنہ کا مقصود یہ ہے کہ سحری طلوع فجر کے بالکل قریب کھانی چاہیے تاکہ سحری کے مقاصد مکمل طور پر حاصل ہوں۔ بہت پہلے سحری کھانے سے روزہ نبھانا مشکل ہو جاتا ہے اور اگر سحری کے بعد نیند آگئی تو تہجد تو ایک طرف، فرض نماز بھی رہ جائے گی۔ (۲) سَحْری، سحَْر سے ہے جس کے معنی ہیں: رات کا آخری حصہ لہٰذا سحری ہے ہی وہ جو رات کے آخری حصے یعنی طلوع فجر سے عین پہلے ہو، زیادہ دیر پہلے کھانا عام کھانا ہوگا، سحری نہ ہوگا۔"}],[2154,"صلہ بن زفر کہتے ہیں: میں نے حذیفہ رضی اللہ عنہ کے ساتھ سحری کھائی، پھر ہم مسجد کی طرف نکلے، اور ہم نے فجر کی دونوں رکعتیں پڑھیں، (اتنے میں) نماز کھڑی کر دی گئی تو ہم نے نماز پڑھی۔","الألباني: صحيح الإسناد",{"u2":"حضرت صلہ بن زفر بیان کرتے ہیں کہ میں نے حضرت حذیفہ رضی اللہ عنہ کے ساتھ سحری کھائی۔ پھر ہم مسجد کو چلے۔ ہم نے فجر کی دو سنتیں پڑھیں، اتنے میں نماز فجر کی اقامت ہوگئی تو ہم نے فرض نماز پڑھی۔"}],[2155,"انس رضی اللہ عنہ سے روایت ہے کہ زید بن ثابت رضی اللہ عنہ کہتے ہیں: ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ سحری کھائی، پھر ہم اٹھ کر نماز کے لیے گئے، انس کہتے ہیں: میں نے پوچھا: ان دونوں کے درمیان کتنا (وقفہ) تھا؟ تو انہوں نے کہا: اس قدر جتنے میں ایک آدمی پچاس آیتیں پڑھ لے۔","الألباني: صحيح",{"u2":"حضرت زید بن ثابت رضی اللہ عنہ سے منقول ہے کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ سحری کھائی، پھر ہم نماز کے لیے اٹھے۔ حضرت انس رضی اللہ عنہ نے فرمایا: میں نے پوچھا کہ درمیان میں کتنا فاصلہ تھا؟ انہوں نے فرمایا: اتنا کہ آدمی پجاس آیتیں پڑھ سکے۔","f2":"(۱) سکون کے ساتھ پچاس آیات پڑھنے کے لیے بھی کم سے کم دس منٹ ضروری ہیں۔ (۲) حسن ادب ہمہ وقت انسان کے پیش نظر رہنا چاہیے۔ صحابہ رضی اللہ عنہم نے یہ نہیں کہا ہم نے اور رسول اللہ صلی اللہ علیہ وسلم نے سحری کھائی بلکہ کہا کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ سحری کھائی کیونکہ اس میں تبعیت کی طرف اشارہ ہے۔"}],[2156,"انس رضی اللہ عنہ سے روایت ہے کہ زید بن ثابت رضی اللہ عنہ کہتے ہیں کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ سحری کی، پھر ہم نماز کے لیے کھڑے ہوئے، میں نے پوچھا (کہا جاتا کہ «قلت» کا قائل انس ہیں ۱؎): ان دونوں کے درمیان کتنا (وقفہ) تھا؟ انہوں نے کہا: اس قدر کہ جتنے میں ایک آدمی پچاس آیتیں پڑھ لے۔\n§وضاحت\n۱؎: یہ جملہ معترضہ ہے جو قول اور مقولہ کے درمیان واقع ہے۔","الألباني: صحيح",{"u2":"حضرت زید بن ثابت رضی اللہ عنہ بیان کرتے ہیں کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ سحری کھائی، پھر ہم نماز کے لیے اٹھے۔ میں نے کہا… خیال کیا جاتا ہے کہ کہنے والے حضرت انس رضی اللہ عنہ ہیں… درمیان میں کتنا فاصلہ تھا؟ انہوں (زید رضی اللہ عنہ) نے فرمایا: اتنا کہ آدمی پچاس آیات پڑھ سکے۔"}],[2157,"انس رضی اللہ عنہ کہتے ہیں: رسول اللہ صلی اللہ علیہ وسلم اور زید بن ثابت نے سحری کھائی، پھر وہ دونوں اٹھے، اور جا کر نماز فجر پڑھنی شروع کر دی۔ قتادہ کہتے ہیں: ہم نے انس رضی اللہ عنہ سے پوچھا: ان دونوں کے (سحری سے) فارغ ہونے اور نماز شروع کرنے میں کتنا (وقفہ) تھا؟ تو انہوں نے کہا: اس قدر کہ جتنے میں ایک آدمی پچاس آیتیں پڑھ لے۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اور حضرت زید بن ثابت رضی اللہ عنہ نے (اکٹھے) سحری کھائی، پھر وہ دونوں کھڑے ہوئے اور صبح کی نماز پڑھنے لگے۔ (قتادہ نے کہا:) میں نے حضرت انس رضی اللہ عنہ سے پوچھا: سحری سے فارغ ہونے اور نماز شروع کرنے کے درمیان کتنا فاصلہ تھا؟ انہوں نے فرمایا: اتنا کہ انسان پچاس آیات پڑھ سکے۔","f2":"اس روایت سے معلوم ہوتا ہے کہ سائل حضرت قتادہ ہیں اور جواب دینے والے حضرت انس رضی اللہ عنہ۔ جبکہ پہلی دو روایات سے معلوم ہوتا ہے کہ سائل حضرت انس رضی اللہ عنہ ہیں اور جواب دینے والے حضرت زید بن ثابت رضی اللہ عنہ، مگر بعید نہیں کہ دونوں درست ہوں، یعنی حضرت انس رضی اللہ عنہ نے حضرت زید بن ثابت رضی اللہ عنہ سے پوچھا اور حضرت انس رضی اللہ عنہ سے ان کے شاگرد حضرت قتادہ رحمہ اللہ نے۔ دونوں واقاعات میں کوئی منافات نہیں۔ واللہ اعلم"}],[2158,"ابوعطیہ وادعی ہمدانی کہتے ہیں کہ میں نے ام المؤمنین عائشہ رضی اللہ عنہا سے کہا: ہم میں نبی اکرم صلی اللہ علیہ وسلم کے اصحاب میں سے دو آدمی ہیں ان دونوں میں سے ایک افطار میں جلدی کرتا ہے، اور سحری میں تاخیر، اور دوسرا افطار میں تاخیر کرتا ہے، اور سحری میں جلدی، انہوں نے پوچھا: ان دونوں میں کون ہے جو افطار میں جلدی کرتا ہے، اور سحری میں تاخیر؟ میں نے کہا: وہ عبداللہ بن مسعود رضی اللہ عنہ ہیں، اس پر انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم اسی طرح کرتے تھے۔","الألباني: صحيح",{"u2":"حضرت ابو عطیہ سے روایت ہے کہ میں نے حضرت عائشہ رضی اللہ عنہا سے عرض کیا: ہم میں نبی صلی اللہ علیہ وسلم کے دو صحابی موجود ہیں۔ ان میں سے ایک روزہ جلدی (آفتاب غروب ہوتے ہی) کھولتے ہیں اور سحری تاخیر سے (آخر وقت میں) کھاتے ہیں اور دوسرے صحابی (احتیاطاً) افطار دیر سے کرتے ہیں اور سحری جلدی کھا لیتے ہیں۔ وہ فرمانے لگیں: ان میں سے افطار اول وقت اور سحری آخر وقت کرنے والا کون ہے؟ میں نے کہا: حضرت عبداللہ بن مسعود رضی اللہ عنہ۔ انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم کا معمول بھی یہی تھا۔","f2":"دوسرے صحابی حضرت ابوموسیٰ اشعری رضی اللہ عنہ تھے، وہ احتیاطاً افطار میں دیر اور سحری میں جلدی فرماتے تھے، مگر احتیاط اتنی لمبی نہیں چاہیے کہ مسنون عمل میں تبدیلی آجائے، احتیاط تو چند منٹ کی ہوتی ہے، البتہ اس حدیث کا یہ مطلب نہیں کہ سورج غروب ہونے کا یقین کیے بغیر جلدی روزہ کھول لیا جائے یا صبح کی اذان کے دوران میں بھی سحری کھانے کی عادت ڈال لی جائے۔ کیونکہ اس طرح روزہ ضائع ہو سکتا ہے۔ بعض جلد باز حضرات غلط سلط کلینڈروں کو دیکھ کر سیکنڈوں کے حساب سے روزہ کھولتے ہیں، حالانکہ ضروری ہے کہ کلینڈر محکمہ موسیمات اور صدگاہوں کے ماہرین کا تصدیق شدہ ہو یا پھر کلینڈر کو سورج دیکھ کر مصدقہ بنا لیا جائے۔ کلینڈروں میں دوسرے شہروں کے اوقات میں فرق یکساں نہیں ہوتا، مثلاً: لاہور سے فیصل آباد کا فرق کسی کلینڈر میں دس منٹ، کسی میں نوی، کسی میں آٹھ، کسی میں چھ، کسی میں پانچ منٹ لکھا ہوتا ہے، لہٰذا کلینڈر کی رو سے روزہ افطار کرنے والے حضرات غیر معیاری کلینڈروں سے اپنا روزہ ضائع نہ کریں۔ جب تک غروب کا یقین نہ ہو، روزہ نہیں کھولنا چاہیے۔ یقین سے مراد آنکھوں سے سورج عین افق میں غروب ہوتا دیکھنا ہے، جبکہ مطلع صاف ہو۔ یا پھر سب سے آخری کلینڈر پر عمل کرنا ہے۔ اس طرح تین چار منٹ کی تاخیر سے اول وقت افطار گزر نہیں جائے گا۔ تاخیر (جو مکروہ ہے) سے مراد ستارے نظر آنے کا انتظار ہے جو یہودی کرتے ہیں نہ کہ غروب کے یقین کا انتظار۔ افسوس! کہ آج کل تو مقابلے میں اذانیں کہی جاتی ہیں کہ جلدی اذان کہو، کہیں فلاں مسجد کی اذان ہم سے پہلے یا ہمارے برابر نہ ہو جائے۔ اس طرح لوگوں کے روزے خراب کیے جاتے ہیں۔ جو یقینا گناہ ہے اور جلدی کے شوق میں کیا جاتا ہے۔ واللہ المستعان"}],[2159,"ابوعطیہ وادعی ہمدانی کہتے ہیں کہ میں نے ام المؤمنین عائشہ رضی اللہ عنہا سے کہا: ہم میں دو آدمی ہیں ان میں سے ایک افطار جلدی اور سحری تاخیر سے کرتے ہیں، اور دوسرے افطار تاخیر سے کرتے ہیں اور سحری جلدی، انہوں نے پوچھا: کون ہیں جو افطار میں جلدی اور سحری میں تاخیر کرتے ہیں؟ میں نے کہا: وہ عبداللہ بن مسعود رضی اللہ عنہ ہیں انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم ایسا ہی کرتے تھے۔","الألباني: صحيح",{"u2":"حضرت ابو عطیہ رضی اللہ عنہ سے منقول ہے کہ میں نے حضرت عائشہ رضی اللہ عنہا سے عرض کیا: ہم میں دو حضرات ہیں۔ ان میں سے ایک افطاری اول وقت اور سحری آخر وقت کرتے ہیں اور دوسرے صاحب افطاری دیر سے اور سحری جلدی کر لیتے ہیں۔ آپ نے فرمایا: ان میں سے افطاری اول وقت اور سحری آخر وقت میں کون کرتا ہے؟ میں نے کہا: حضرت عبداللہ بن مسعود رضی اللہ عنہ۔ انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم اسی طرح کیا کرتے تھے۔"}],[2160,"ابوعطیہ وادعی ہمدانی کہتے ہیں: میں اور مسروق دونوں ام المؤمنین عائشہ رضی اللہ عنہا کے پاس گئے، مسروق نے ان سے کہا: رسول اللہ صلی اللہ علیہ وسلم کے اصحاب میں سے دو شخص ہیں، یہ دونوں نیک کام میں کوتاہی نہیں کرتے، (لیکن) ان میں سے ایک نماز اور افطار دونوں میں تاخیر کرتے ہیں، اور دوسرے نماز اور افطار دونوں میں جلدی کرتے ہیں، ام المؤمنین عائشہ رضی اللہ عنہا نے پوچھا: کون ہیں جو نماز اور افطار دونوں میں جلدی کرتے ہیں؟ مسروق نے کہا: وہ عبداللہ بن مسعود رضی اللہ عنہ ہیں، تو عائشہ رضی اللہ عنہا نے کہا: رسول اللہ صلی اللہ علیہ وسلم ایسا ہی کرتے ہیں۔","الألباني: صحيح",{"u2":"حضرت ابو عطیہ فرماتے ہیں کہ میں اور حضرت مسروق دونوں حضرت عائشہ رضی اللہ عنہا کی خدمت میں حاضر ہوئے تو حضرت مسروق نے ان سے عرض کیا: رسول اللہ صلی اللہ علیہ وسلم کے صحابہ میں سے دو آدمی ہیں، ان میں سے کوئی بھی نیکی میں کوتاہی نہیں کرتا مگر ان میں سے ایک افطاری اور نماز مغرب میں تاخیر کرتے ہیں اور دوسرے صاحب افطاری اور نماز مغرب میں جلدی کرتے ہیں۔ حضرت عائشہ رضی اللہ عنہا نے پوچھا: ان میں سے کون نماز مغرب اور افطاری میں جلدی کرتے ہیں؟ حضرت مسروق نے کہا: حضرت عبداللہ بن مسعود رضی اللہ عنہ نے۔ حضرت عائشہ رضی اللہ عنہا نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم اسی طرح کیا کرتے تھے۔"}],[2161,"ابوعطیہ وادعی ہمدانی کہتے ہیں: میں اور مسروق دونوں ام المؤمنین عائشہ رضی اللہ عنہا کے پاس گئے، ہم نے ان سے کہا: ام المؤمنین! محمد صلی اللہ علیہ وسلم کے اصحاب میں سے دو آدمی ہیں، ان میں سے ایک افطار میں جلدی کرتے ہیں اور نماز میں بھی جلدی کرتے ہیں، اور دوسرے افطار میں تاخیر کرتے ہیں اور نماز میں بھی تاخیر کرتے ہیں، انہوں نے پوچھا: کون ہیں جو افطار میں جلدی کرتے اور نماز میں بھی جلدی کرتے ہیں؟ ہم نے کہا: وہ عبداللہ بن مسعود رضی اللہ عنہ ہیں، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم ایسا ہی کرتے تھے۔ (دوسرے شخص ابوموسی اشعری رضی اللہ عنہ تھے۔)","الألباني: صحيح",{"u2":"حضرت ابو عطیہ سے مروی ہے کہ میں اور حضرت مسروق حضرت عائشہ رضی اللہ عنہا کے پاس حاضر ہوئے اور ہم نے ان سے کہا: اے ام المومنین! اصحاب محمد صلی اللہ علیہ وسلم میں سے دو آدمی ہیں۔ ان میں سے ایک افطاری اور نماز مغرب جلدی ادا کرتے ہیں اور دوسرے افطاری اور نماز مغرب میں تاخیر کرتے ہیں۔ فرمانے لگیں: ان میں سے کون افطاری اور نماز مغرب میں جلدی کرتے ہیں؟ ہم نے کہا: حضرت عبداللہ بن مسعود رضی اللہ عنہ۔ انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم کا طرز عمل یہی تھا۔ دوسرے صحابی رضی اللہ عنہ حضرت ابو موسیٰ اشعری رضی اللہ عنہ تھے۔"}],[2162,"نبی اکرم صلی اللہ علیہ وسلم کے اصحاب میں سے ایک شخص کہتے ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، آپ اس وقت سحری کھا رہے تھے، آپ نے فرمایا:\"یہ برکت ہے جس سے اللہ تعالی نے تمہیں دی ہے تو تم اسے مت چھوڑو\"۔","الألباني: صحيح",{"u2":"ایک صحابی رسول رضی اللہ عنہ سے روایت ہے کہ میں نبی صلی اللہ علیہ وسلم کے پاس حاضر ہوا تو آپ سحری تناول فرما رہے تھے۔ آپ نے فرمایا: ’’بلا شبہ سحری برکت ہے جو اللہ تعالیٰ نے تمہیں عطا فرمائی ہے، لہٰذا تم اسے نہ چھوڑو۔‘‘","f2":"’’تمہیں عطا فرمائی ہے۔‘‘ یعنی خاص تمہارے لیے رعایت ہے، ورنہ یہودی اور عیسائی اس نعمت سے محروم ہیں، لہٰذا اسے امتیاز سمجھ کر اختیار کرو، امتیازات چھوڑے نہیں جاتے، اس لیے اسے نہ چھوڑو۔ سحری کھائی جائے تاکہ یہودیوں اور عیسائیوں کے روزے سے مشابہت نہ ہو۔ مجبوراً سحری چھوٹ جائے تو کوئی حرج نہیں۔ مثلاً بیدار نہ ہو سکے۔ (مزید تفصیل کے لیے دیکھئے، حدیث: ۲۱۴۶)"}],[2163,"عرباض بن ساریہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا: آپ رمضان کے مہینہ میں سحری کھانے کے لیے بلا رہے تھے، اور فرما رہے تھے: \"آؤ صبح کے مبارک کھانے پر\"۔","الألباني: صحيح",{"u2":"حضرت عرباض بن ساریہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو رمضان المبارک میں سحری کی دعوت دیتے سنا۔ آپ فرما رہے تھے: ’’آؤ اس مبارک کھانے کی طرف۔‘‘"}],[2164,"مقدام بن معد یکرب رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تم صبح کا کھانا (سحری کو) لازم پکڑو، کیونکہ یہ مبارک کھانا ہے\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت مقدام بن معدیکرب رضی اللہ عنہ سے روایت ہے، نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’سحری کا کھانا کھایا کرو کیونکہ یہ بابرکت کھانا ہے۔‘‘","f2":"غذا اس کھانے کو کہا جاتا ہے جو دن کے آغاز میں کھایا جاتا ہے۔ روزے دار کے لیے چونکہ سحری ہی دن کے کھانے کے قائم مقام ہے، لہٰذا اسے حدیث مبارکہ میں غذا بھی کہا گیا ہے، جیسے ہم اپنی زبان میں سحری کو ناشتہ کہہ لیں۔(مزید دیکھئے، حدیث: ۲۱۴۶)"}],[2165,"(تابعی) خالد بن معدان کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص سے کہا: \"صبح کے مبارک کھانے یعنی سحری کے لیے آؤ\"۔","الألباني: صحيح",{"u2":"حضرت خالد بن میدان رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے ایک آدمی سے فرمایا: ’’اس بابرکت کھانے، یعنی سحری کے لیے آؤ۔‘‘"}],[2166,"عمرو بن العاص رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہمارے اور اہل کتاب کے صیام میں جو فرق ہے، (وہ ہے) سحری کھانا\"۔","الألباني: صحيح",{"u2":"حضرت عمرو بن عاص رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ہمارے اور اہل کتاب کے روزے کے درمیان فرق، سحری کھانا ہے۔‘‘","f2":"فوائد کے لیے دیکھیے‘حدیث:2164۔"}],[2167,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سحری کے وقت فرمایا: \"اے انس! میں روزہ رکھنا چاہتا ہوں، مجھے کچھ کھلاؤ\"، تو میں کچھ کھجور اور ایک برتن میں پانی لے کر آپ کے پاس آیا، اور یہ بلال رضی اللہ عنہ کی اذان دینے کے بعد کا وقت تھا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اے انس! کسی اور شخص کو تلاش کرو جو میرے ساتھ (سحری) کھائے\"، تو میں نے زید بن ثابت رضی اللہ عنہ کو بلایا، چنانچہ وہ آئے (اور) کہنے لگے: میں نے ستو کا ایک گھونٹ پی لیا ہے، اور میں روزہ رکھنا چاہتا ہوں، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میں (بھی) روزہ رکھنا چاہتا ہوں\"، (پھر) زید بن ثابت رضی اللہ عنہ نے آپ کے ساتھ سحری کھائی، پھر آپ اٹھے، اور (فجر کی) دو رکعت (سنت) پڑھی، پھر آپ فرض نماز کے لیے نکل گئے۔","الألباني: صحيح الإسناد",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے سحری کے وقت فرمایا: ’’اے انس! میں روزہ رکھنا چاہتا ہوں، مجھے کچھ کھلاؤ۔‘‘ میں آپ کے پاس کچھ کھجوریں اور ایک پانی کا برتن لے کر آیا اور یہ حضرت بلال رضی اللہ عنہ کے اذان (اذان اول) کہنے کے بعد کی بات ہے، پھر آپ فرمانے لگے: ’’اے انس! کوئی آدمی دیکھو جو میرے ساتھ سحری کھائے۔‘‘ میں حضرت زید بن ثابت رضی اللہ عنہ کو بلا لایا، وہ آئے اور کہنے لگے: میں نے کچھ ستو پی لیے ہیں اور میرا ارادہ روزہ رکھنے کا ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میرا ارادہ بھی روزہ رکھنے کا ہے۔‘‘ تو انہوں نے آپ کے ساتھ سحری کھائی، پھر آپ صلی اللہ علیہ وسلم اٹھے، دو رکعتیں پڑھیں اور پھر نماز کے لیے نکل گئے۔","f2":"(۱)مذکورہ روایت کو مہقق کتاب نے سنداً ضعیف قرار دیا ہے جبکہ دوسرے معتبر محققین کے نزدیک بعض شواہد کی بنا پر قابل حجت ہے۔ تفصیل کے لیے دیکھئے (الموسوعۃ الحدیثیۃ مسند الامام احمد: ۲۰/ ۲۳۴، وذخیرۃ العقبی شرح سنن النسائی: ۲۰/۳۷۶، ۳۷۷، وصحیح سنن النسائی للالبانی: ۲/ ۱۰۸، ۱۰۹، رقم: ۲۱۶۶) (۲)حضرت بلال رضی اللہ عنہ طلوع فجر سے چند منٹ پہلے اذان کہا کرتے تھے۔ فجر کی اذان حضرت عبداللہ بن ام مکتوم رضی اللہ عنہ کہتے تھے جیسا کہ دیگر احادیث میں صراحت ہے، لہٰذا یہ وہم نہ کیا جائے کہ شاید رسول اللہ صلی اللہ علیہ وسلم نے فجر کی اذان کے بعد سحری کھائی۔ اس حدیث میں دوسری اذان کا ذکر نہیں۔"}],[2168,"براء بن عازب رضی اللہ عنہما سے روایت ہے کہ ان میں سے کوئی جب شام کا کھانا کھانے سے پہلے سو جاتا تو رات بھر اور دوسرے دن سورج ڈوبنے تک اس کے لیے کھانا پینا جائز نہ ہوتا، یہاں تک کہ آیت کریمہ: «وكلوا واشربوا» سے لے کر «الخيط الأسود» \"تم کھاتے پیتے رہو یہاں تک کہ صبح کی سیاہ دھاری سے سفید دھاری نظر آنے لگے\" تک نازل ہوئی، یہ آیت ابوقیس بن عمرو رضی اللہ عنہ کے بارے میں نازل ہوئی، (ہوا یہ کہ) وہ مغرب بعد اپنے گھر آئے، وہ روزے سے تھے، انہوں نے (گھر والوں سے) پوچھا: کچھ کھانا ہے؟ ان کی بیوی نے کہا: ہمارے پاس تو کچھ (بھی) نہیں ہے، لیکن میں جا کر آپ کے لیے رات کا کھانا ڈھونڈ کر لاتی ہوں، چنانچہ وہ نکل گئی، اور یہ اپنا سر رکھ کر سو گئے، وہ لوٹ کر آئی تو انہیں سویا ہوا پایا، (تو) انہیں جگایا (لیکن) انہوں نے کچھ (بھی) نہیں کھایا، اور (اسی حال میں) رات گزار دی، اور روزے ہی کی حالت) میں صبح کی یہاں تک کہ دوپہر ہوئی، تو ان پر غشی طاری ہو گئی، یہ اس آیت کے نازل ہونے سے پہلے کی بات ہے، اللہ تعالی نے (یہ آیت) انہیں کے سلسلہ میں اتاری۔","الألباني: صحيح",{"u2":"حضرت براء بن عازب رضی اللہ عنہ سے منقول ہے کہ (شروع شروع میں) مسلمانوں میں سے کوئی شخص جب رات کو کھانا کھانے سے پہلے سو جاتا تھا تو اس کے لیے کچھ بھی کھانا پینا جائز نہ ہوتا تھا، نہ اس رات اور نہ اگلے دن حتیٰ کہ سورج غروب ہو جائے۔ (یہی صورت حال رہی) حتیٰ کہ یہ آیت اتری: {وَکُلُوْا وَاشْرَبُوْا… مِنَ الْخَیْطِ الْاَسْوَدِ} ’’کھاؤ اور پیو حتیٰ کہ تمہارے لیے صبح کی سفید دھاری سیاہ دھاری سے واضہ (روشن) ہو جائے۔‘‘ یہ آیت حضرت ابو قیس بن عمرو رضی اللہ عنہ کے بارے میں اتری۔ وہ مغرب کی نماز کے بعد گھر والوں کے پاس آئے، ان کا روزہ تھا۔ کہنے لگے: کوئی کھانے کی چیز ہے؟ ان کی بیوی نے کہا: کھانے کی کوئی چیز بھی نہیں لیکن میں جا کر کھانا تلاش کرتی ہوں۔ وہ باہر چلی گئیں اور وہ لیٹ گئے، انہیں نیند آگئی۔ وہ واپس آئیں تو انہیں سوتے ہوئے پایا۔ انہیں جگایا لیکن وہ کچھ نہ کھا سکے، اسی طرح رات گزاری۔ اگلی صبح پھر روزہ تھا حتیٰ کہ دوپہر ہوئی تو وہ بے ہوش ہوگئے۔ اور یہ اس آیت کے اترنے سے پہلے کی بات ہے، تو اللہ تعالیٰ نے یہ آیت ان کے بارے میں اتاری۔","f2":"شروع میں مسلمان بھی اہل کتاب کی طرح شام سے شام تک روزہ رکھتے تھے، یا تو ان کی نقل کرتے ہوئے یا شاید رسول اللہ صلی اللہ علیہ وسلم نے ایسا حکم دیا ہو۔ جب چند لوگوں کو مندرجہ بالا یا اس سے ملتی جلتی صورت حال پیش ائی تو رعایت کر دی گئی۔ اور روزہ صبح سے شام تک ہوگیا۔ رات کو کھانا پینا اور بیوی سے حق زوجیت ادا کرنا جائز ہوگیا۔"}],[2169,"عدی بن حاتم رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے آیت کریمہ: «حتى يتبين لكم الخيط الأبيض من الخيط الأسود» کے متعلق سوال کیا، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \" «خيط الأسود» (سیاہ دھاری) رات کی تاریکی ہے، (اور «خيط الأسود» سفید دھاری) دن کا اجالا ہے\"۔","الألباني: صحيح",{"u2":"حضرت عدی بن حاتم رضی اللہ عنہ سے روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے اللہ تعالیٰ کے فرمان: {حَتّٰی یَتَبَیَّنَ لَکُمْ الْاَسْوَدِ} ’’حتیٰ کہ تمہارے لیے سفید دھاری سیاہ دھاری سے واضح ہو جائے۔‘‘ کے بارے میں پوچھا۔ اپ نے فرمایا: ’’اس سے رات کی سیاہی اور دن کی سفیدی مراد ہے۔‘‘","f2":"لفظ خَیْط کے معنی دھاگا دھاری کے ہیں مگر یہاں ظاہر معنی مراد نہیں جیسا کہ حضرت عدی رضی اللہ عنہ سمجھے، جب انہوں نے پوچھا تو آپ نے وضاحت فرما دی کہ مطلب یہ ہے کہ رات کے اندھیرے سے صبح کی روشنی نظر آنے لگے اور پھیل جائے۔ اسے طلوع فجر کہا جاتا ہے۔"}],[2170,"عبداللہ بن مسعود رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"بلال رات ہی میں اذان دیتے ہیں، تاکہ وہ تم میں سونے والوں کو ہوشیار کر دیں، (تہجد پڑھنے یا سحری کھانے کے لیے) اور تہجد پڑھنے والوں کو (گھر) لوٹا دیں، اور فجر اس طرح ظاہر نہیں ہوتی\"، انہوں اپنی ہتھیلی سے اشارہ کیا، \"بلکہ فجر اس طرح ظاہر ہوتی ہے\" انہوں نے اپنی دونوں شہادت کی انگلیوں سے اشارہ کیا۔","الألباني: صحيح",{"u2":"حضرت ابن مسعود رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’بلال رات کو اذان کہتے ہیں تاکہ سوئے ہوؤں کو جگائیں اور جاگے ہوؤں کو لوٹائیں اور فجر اس طرح نہیں ہوتی۔‘‘ اور آپ نے اپنی ہتھیلی سے (اوپر نیچے) اشارہ کیا۔ ’’بلکہ فجر اس طرح ہوتی ہے۔‘‘ اور آپ نے اپنی دونوں ہتھیلی سے (اوپر نیچے) اشارہ کیا۔ ’’بلکہ فجر اس طرح ہوتی ہے۔‘‘ اور آپ نے اپنی دونوں انگشت شہادت سے دائیں بائیں اشارہ فرمایا۔","f2":"(۱) حضرت بلال رضی اللہ عنہ کی اذان، فجر سے کچھ پہلے ہوتی تھی تاکہ لوگ جلدی اٹھ کھڑے ہوں اور بروقت مصروفیات سے فارغ ہو کر جماعت میں مل سکیں کیونکہ یہ قضائے حاجت اور غسل وغیرہ کا وقت ہوتا ہے۔ اگر عین طلوع فجر پر اٹھیں تو جماعت سے رہ جائیں گے۔ دوسری اذان میں عین طلوع فجر کے بعد ہوتی تھی۔ (بعد میں حضرت عثمان رضی اللہ عنہ نے غالباً اسی پر قیاس کرتے ہوئے جمعۃ المبارک کی بھی دو اذانیں جاری فرمائیں)۔ (۲) ’’جاگے ہوؤں کو لوٹائیں۔‘‘ یعنی وہ نماز تہجد کو مختصر کر کے کچھ آرام کر لیں تاکہ فجر کی نماز میں سستی لاحق نہ ہو۔ (۳) ’’فجر ایسے نہیں ہوتی۔‘‘ یعنی جب صرف چند شعاعیں نیچے سے اوپر کو اٹھتی ہوئی محسوس ہوں تو وہ فجر نہیں ہے۔ اسے فجر کاذب کہا جاتا ہے۔ (۴) ’’فجر ایسے ہوتی ہے۔‘‘ یعنی جب شعاعیں زیادہ ہو جائیں اور افق پر پھیل جائیں اور افق واضح طور پر روشن نظر آنے لگے۔ اسے صبح صادق کہتے ہیں۔ اس وقت حضرت عبداللہ بن ام مکتوم رضی اللہ عنہ اذان کہتے تھے اور اسی اذان سے نماز فجر اور روزے کا آغاز ہوتا تھا۔"}],[2171,"سمرہ بن جندب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بلال کی اذان تمہیں ہرگز دھوکہ میں نہ ڈالے، اور نہ یہ سفیدی یہاں تک کہ فجر کی روشنی اس طرح اور اس طرح\"، یعنی چوڑائی میں پھوٹ پڑے۔ ابوداؤد (طیالسی) کہتے ہیں: (شعبہ) نے اپنے دونوں ہاتھ دائیں بائیں بڑھا کر پھیلائے۔","الألباني: صحيح",{"u2":"حضرت سمرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بلال کی اذان اور اس سفیدی (فجر کاذب) سے تمہیں دھوکا نہ لگے حتیٰ کہ فجر اس طرح دائیں بائیں پھیل جائے۔‘‘ ابوداؤد (راوی) نے کہا: اور اس (استاد شعبہ) نے اپنے دونوں ہاتھ کھول کر دائیں بائیں کھینچ کر پھیلائے۔","f2":"حضرت بلال رضی اللہ عنہ کی اذان نہ تو تہجد کے لیے تھی کیونکہ نفل نماز کے لیے اذان نہیں اور نہ سحری کے لیے کیونکہ اذان نماز کے لیے ہوتی ہے، کھانے پینے کے لیے نہیں، بلکہ فجر کی نماز کے لیے ہی ہوتی ہے لیکن وقت سے کچھ پہلے، البتہ اس اذان سے کوئی شخص تہجد یا سحری کا فائدہ اٹھا سکتا ہے، جیسے مغرب کی اذان سے افطاری کا فائدہ اٹھا لیا جاتا ہے۔ رسول اللہ صلی اللہ علیہ وسلم کے دور میں اگرچہ ان دو اذانوں کے درمیان زیادہ فاصلہ نہ ہوتا تھا مگر چونکہ یہ فاصلہ مقرر نہیں، لہٰذا یہ زیادہ بھی ہو سکتا ہے۔"}],[2172,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"رمضان کا مہینہ (شروع ہونے) سے پہلے تم روزہ نہ رکھو، سوائے اس آدمی کے جو کسی خاص دن روزہ رکھتا ہو، اور (اتفاق سے) وہ دن رمضان کے روزہ سے پہلے آ پڑے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ماہ رمضان المبارک شروع ہونے سے پہلے کوئی روزہ نہ رکھوالا یہ کہ کوئی شخص پہلے خاص دن کا روزہ رکھتا ہو اور وہ دن ایسے موقع پر آجائے۔‘‘","f2":"یہ ہدایت شعبان کے آخری دنوں کے لیے ہے تاکہ نفل روزے فرض روزوں سے متصل نہ ہو جائیں، امتیاز رہے اور رمضان المبارک کی اہمیت اجاگر ہو، نیز شک والے دن (۳۰ شعبان) کا روزہ نہ رکھا جا سکے۔ ’’خاص دن کا روزہ رکھتا رہا ہو‘‘ اس کے ممانعت کے دن میں آجانے کی صورت یہ ہے کہ مثلاً: کوئی شخص ہر سوموار کو روزہ رکھتا ہو اور سوموار آخر شعبان کو آجائے جو مشکوک ہو کہ ۳۰ شعبان ہے یا یکم رمضان، تو اپنی سابقہ عادت کے مطابق اس دن روزہ رکھ سکتا ہے۔"}],[2173,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ماہ رمضان سے ایک دن یا دو دن پہلے کوئی روزہ نہ رکھے، البتہ جو اس سے پہلے (اس دن)روزہ رکھتا رہا ہو تو وہ رکھے\" ۱؎۔\n§وضاحت\n۱؎: مطلب یہ ہے کہ اس دن کا روزہ رکھنا اگر پہلے سے اس کے معمولات میں داخل ہو تو وہ رکھے کیونکہ یہ استقبال رمضان کے لیے نہیں ہے بلکہ یہ اس کے مستقل معمولات کا ایک حصہ ہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ نے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کوئی شخص رمضان المبارک سے ایک دو دن پہلے روزہ نہ رکھے مگر جو شخص پہلے سے کسی خاص دن کا روزہ رکھتا ہے، وہ رکھ سکتا ہے۔‘‘","f2":"ابوسلمہ کے شاگردوں کا اختلاف یہ ہے کہ یحییٰ بن ابی کثیر نے تو اس حدیث کو حضرت ابوہریرہ رضی اللہ عنہ کی روایت بتلایا ہے جبکہ محمد بن عمرو نے حضرت عبداللہ بن عباس رضی اللہ عنہ کی۔ محمد بن عمرو کو غلطی لگی ہے۔ اس کی دلیل یہ ہے کہ محمد بن عمرو نے یحییٰ بن ابی کثیر کی روایت کے موافق بھی روایت کی ہے۔ دیکھیے (ذخیرۃ العقبی: ۲۱/۵)"}],[2174,"عبداللہ بن عباس رضی اللہ عنہما سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"(رمضان) سے ایک دن یا دو دن پہلے روزہ مت رکھو، البتہ سوائے اس کے کہ یہ اس دن آ پڑے جس دن تم میں کا کوئی (پہلے سے) روزہ رکھتا رہا ہو\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: یہ سند غلط ہے۔","الألباني: حسن صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ماہ رمضان المبارک سے ایک دو دن پہلے روزہ نہ رکھو مگر یہ کہ اتفاقاً وہ دن آجائے جس کا کوئی شخص پہلے سے روزہ رکھنے کا عادی ہو۔‘‘\nابوعبدالرحمن (نسائی) رحمہ اللہ نے فرمایا: یہ غلطی ہے۔","f2":"امام نسائی رحمہ اللہ فرماتے ہیں کہ اس روایت میں حضرت ابوہریرہ رضی اللہ عنہ کے بجائے حضرت ابن عباس رضی اللہ عنہ کا ذکر راوی کی غلطی ہے۔ اور یہ بات درست ہے۔"}],[2175,"ام المؤمنین ام سلمہ رضی اللہ عنہا کہتی ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو کبھی لگاتار دو مہینہ روزے رکھتے نہیں دیکھا، البتہ آپ شعبان کو رمضان سے ملا دیتے تھے ۱؎۔\n§وضاحت\n۱؎: یعنی آپ شعبان میں برابر روزے رکھتے کہ وہ رمضان کے روزوں سے مل جاتا تھا، چونکہ آپ کو روحانی قوت حاصل تھی اس لیے روزے آپ کے لیے کمزوری کا سبب نہیں بنتا تھا، لیکن امت کے لیے حکم یہ ہے کہ وہ شعبان کے نصف ثانی میں روزہ نہ رکھیں، تاکہ ان کی قوت و توانائی رمضان کے فرض روزوں کے لیے برقرار رہے۔","الألباني: صحيح",{"u2":"ابو سلمہ کہتے ہیں کہ حضرت ام سلمہ رضی اللہ عنہا نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو پے در پے دو ماہ کے روزے رکھتے نہیں دیکھا، البتہ آپ شعبان (کے روزوں) کو رمضان المبارک (کے روزوں) سے ملا لیتے تھے۔","f2":"ظاہراً اس روایت سے معلوم ہوتا ہے کہ رسول اللہ صلی اللہ علیہ وسلم مکمل شعبان کے روزے رکھتے تھے مگر یہ درست نہیں بلکہ آپ آخر سے چند دن ناغہ فرما لیتے تھے۔ اس بات کی صراحت آگے حدیث نمبر ۲۱۷۹ اور ۲۱۸۰ میں آرہی ہے۔ چونکہ اکثر دنوں کے روزے رکھتے تھے، لہٰذا کہہ دیا گیا کہ سارا مہینہ روزے رکھتے تھے۔ لِلْأَکْثرِ حُکْمُ الْکُلِّ عرفاً کلام میں ایسے عام ہو جاتا ہے۔"}],[2176,"ام المؤمنین ام سلمہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم شعبان کو رمضان سے ملا دیتے تھے۔","الألباني: صحيح",{"u2":"حضرت ام سلمہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ رضی اللہ عنہ شعبان (کے روزوں) کو رمضان المبارک (کے روزوں) کے ساتھ ملا لیتے تھے۔"}],[2177,"ابوسلمہ بن عبدالرحمٰن بن عوف کہتے ہیں کہ میں نے ام المؤمنین عائشہ رضی اللہ عنہا سے رسول اللہ صلی اللہ علیہ وسلم کے روزوں کے متعلق سوال کیا، تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم (پے در پے اتنے) روزے رکھتے کہ ہم سمجھتے (اب) آپ روزہ رکھنا بند نہیں کریں گے، اور (پھر) اتنے دنوں تک بغیر روزے کے رہتے کہ ہم سمجھتے (اب) آپ روزے نہیں رکھیں گے، اور آپ (پورے) شعبان میں یا شعبان کے اکثر دنوں میں روزے رکھتے تھے۔","الألباني: حسن صحيح",{"u2":"حضرت ابو سلمہ بن عبدالرحمن نے حضرت عائشہ رضی اللہ عنہا سے رسول اللہ صلی اللہ علیہ وسلم کے (نفل) روزوں کے بارے میں پوچھا تو انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم کبھی (نفل) روزے رکھتے حتیٰ کہ ہم کہتے تھے: آپ ناغہ نہیں کریں گے۔ اور کبھی جھوڑے رہتے حتیٰ کہ ہم کہتے: آپ روزے نہیں رکھیں گے۔ آپ سارا شعبان یا اکثر شعبان روزے رکھتے تھے۔","f2":"(۱) نفل روزوں کے لیے کوئی ضابطہ مقرر نہیں بلکہ یہ انسان کے نشاط پر موقو ف ہے جب جی چاہے رکھے اور جتنے چاہے رکھے اور جب سستی محسوس کرے تو نہ رکھے اور جب تک چاہے ناغہ کرے۔ (مزید دیکھئے، حدیث: ۲۳۵۹) (۲) شعبان میں زیادہ روزے رکھنے کی وجہ رمضان المبارک کی قربت ہو سکتی ہے گویا رمضان المبارک کا پڑوسی ہونے کے لحاظ سے شعبان کو بھی خصوصی فضیلت حاصل ہوگئی۔ انبیاء وصلحاء کا جوار بھی عظیم فضیلت کا سبب ہے، دنیا میں ہو، آخرت میں یا قبر میں۔ (۳) ’’سارا شعبان‘‘ اس کی تفصیل کے لیے دیکھئے: (حدیث: ۲۱۷۷)"}],[2178,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں: ہم (ازواج مطہرات) میں سے کوئی رمضان میں (حیض کی وجہ سے) روزہ نہیں رکھتی تو اس کی قضاء نہیں کر پاتی یہاں تک کہ شعبان آ جاتا، رسول اللہ صلی اللہ علیہ وسلم کسی مہینے میں اتنے روزے نہیں رکھتے جتنا شعبان میں رکھتے تھے، آپ چند دن چھوڑ کر پورے ماہ روزے رکھتے، بلکہ(بسا اوقات) پورے (ہی) ماہ روزے رکھتے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے مروی ہے کہ ہم ازواجِ مطہرات میں سے کسی ایک کو رمضان المبارک کے کچھ روزے (حیض کی بنا پر) چھوڑنے پڑتے تھے، وہ ان کی قضا نہیں دے سکتی تھی حتیٰ کہ ماہ شعبان آجاتا۔ رسول اللہ صلی اللہ علیہ وسلم کسی مہینے میں اتنے روزے نہ رکھتے تھے جتنے شعبان میں رکھتے تھے، صرف چند دن چھوڑ کر باقی روزے رکھتے تھے بلکہ (یہی کہہ لیجئے کہ) سارا مہینہ ہی روزے رکھتے تھے۔","f2":"’’قضا نہیں دے سکتی تھی۔‘‘ اس خطرے کی بنا پر کہ ایسا نہ ہو رسول اللہ صلی اللہ علیہ وسلم کو ہماری ضرورت محسوس ہو اور ہم روزے سے ہوں کیونکہ آپ ہر روز عصر کے بعد یا کسی اور وقت میں سب ازواج مطہرات رضی اللہ عنہم کے گھروں میں جاتے تھے۔ باری کا تعلق تو صرف رات کی حد تک تھا دن کو آپ کسی گھر میں بھی جا سکتے تھے۔"}],[2179,"ابوسلمہ بن عبدالرحمٰن بن عوف کہتے ہیں کہ میں نے عائشہ رضی اللہ عنہا سے پوچھا، میں نے کہا: مجھے رسول اللہ صلی اللہ علیہ وسلم کے روزوں کے بارے میں بتائیے؟ تو انہوں نے کہا: آپ (اس تسلسل سے) روزے رکھتے کہ ہم سمجھتے اب آپ روزے ہی رکھتے رہیں گے، اور آپ (اس تسلسل سے) بلا روزے کے رہتے کہ ہم سمجھتے (اب) آپ بغیر روزے ہی کے رہیں گے، آپ کسی مہینے میں شعبان سے زیادہ روزے نہیں رکھتے، سوائے چند دنوں چھوڑ کے آپ پورے شعبان ہی روزے رکھتے۔","الألباني: صحيح",{"u2":"حضرت عائشہc فرماتی ہیں کہ: رسول اللہa سال کے کسی مہینے میں شعبان سے زیادہ (نفل) روزے نہ رکھتے تھے۔ (یوں سمجھئے کہ) پورا شعبان ہی روزے رکھتے تھے۔"}],[2180,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سال کے کسی مہینے میں شعبان سے زیادہ روزے نہیں رکھتے تھے، آپ (تقریباً) پورے شعبان ہی روزے رکھتے تھے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ: رسول اللہ صلی اللہ علیہ وسلم سال کے کسی مہینے میں شعبان سے زیادہ (نفل) روزے نہ رکھتے تھے۔ (یوں سمجھئے کہ) پورا شعبان ہی روزے رکھتے تھے۔"}],[2181,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم شعبان میں روزہ رکھتے تھے۔","الألباني: صحيح الإسناد",{"u2":"حضرت عائشہ رضی اللہ عنہا سے مروی ہے کہ نبی صلی اللہ علیہ وسلم شعبان میں (بہت زیادہ) روزے رکھتے تھے"}],[2182,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نہیں جانتی کہ رسول اللہ صلی اللہ علیہ وسلم نے کبھی ایک ہی رات میں سارا قرآن پڑھا ہو، یا پوری رات صبح تک قیام کیا ہو، یا رمضان کے علاوہ کسی مہینے کے پورے روزے رکھے ہوں۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے منقول ہے کہ میں تو نہیں جانتی کہ رسول اللہ صلی اللہ علیہ وسلم نے کبھی ایک رات میں مکمل قرآن مجید پڑھا ہو یا کسی رات (شروع سے آخر تک) مسلسل نماز پڑھتے رہے ہوں یا رمضان المبارک کے علاوہ کسی مہینے کے مکمل روزے رکھے ہوں۔","f2":"صحیح طریقہ اور سنت بھی یہی ہے کیونکہ عبادت کے ساتھ ساتھ اپنے جسم اور دیگر متعلقات کا خیال رکھنا بھی ضروری ہے۔ فرائض کی مکمل پابندی اور نوافل میں سہولت اور نشاط اور دوسرے فرائض کا لحاظ رکھنا ہی صحیح دین ہے۔ نفلی عبادت میں اعتدال انتہائی ضروری ہے۔ اللہ تعالیٰ نے فرائض میں بھی اعتدال رکھا ہے۔ انتہا پسندی نقصان دہ ہے۔"}],[2183,"عبداللہ بن شقیق کہتے ہیں: میں نے ام المؤمنین عائشہ رضی اللہ عنہا سے رسول اللہ صلی اللہ علیہ وسلم کے روزوں کے متعلق پوچھا: (تو) انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم (اس تسلسل سے) روزے رکھتے کہ ہم سمجھتے (اب) آپ روزے (ہی) رکھتے رہیں گے، اور (کبھی آپ اس تسلسل سے) بغیر روزے کے رہتے کہ ہم سمجھتے (اب) آپ بغیر روزے کے رہیں گے، اور آپ جب سے مدینہ آئے کبھی آپ نے پورے مہینے روزے نہیں رکھے سوائے اس کے کہ وہ رمضان ہو۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن شقیق سے منقول ہے کہ میں نے حضرت عائشہ رضی اللہ عنہا سے رسول اللہ صلی اللہ علیہ وسلم کے (نفل) روزوں کے بارے میں پوچھا تو انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم روزے رکھنے لگتے تو ہم کہتے کہ رکھتے ہی رہیں گے اور چھوڑتے تو ہم کہتے: چھوڑے ہی رہیں گے۔ اور آپ نے مدینہ منورہ تشریف آوری کے بعد رمضان المبارک کے علاوہ کبھی مسلسل ایک مہینہ روزے نہیں رکھے۔","f2":"’’مدینہ منورہ تشریف آوری کے بعد‘‘ کیونکہ حضرت عائشہ رضی اللہ عنہا کو اس کے بعد کے بارے میں ہی علم ہے، ورنہ یہ مطلب نہیں کہ مدینہ منورہ آنے سے پہلے آپ مسلسل روزے رکھتے تھے بلکہ پہلے بھی آپ کی عادت مبارک یہی تھی۔"}],[2184,"عبداللہ بن شقیق کہتے ہیں کہ میں نے ام المؤمنین عائشہ رضی اللہ عنہا سے سوال کیا: کیا رسول اللہ صلی اللہ علیہ وسلم صلاۃ الضحی (چاشت کی نماز) پڑھتے تھے؟ انہوں نے کہا: نہیں، الا یہ کہ سفر سے (لوٹ کر) آتے، (پھر) میں نے سوال کیا: کیا رسول اللہ صلی اللہ علیہ وسلم کبھی پورے ماہ روزے رکھتے تھے؟ تو انہوں نے کہا: نہیں، میں نہیں جانتی کہ آپ نے رمضان کے علاوہ کبھی پورے ماہ کے روزے رکھے ہوں، اور اور نہ ایسا ہی ہوتا کہ آپ پورے ماہ بغیر روزے کے رہے ہوں، کچھ نہ کچھ روزے ضرور رکھتے یہاں تک کہ آپ وفات پا گئے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن شقیق بیان کرتے ہیں کہ میں نے حضرت عائشہ رضی اللہ عنہا سے عرض کیا: کیا رسول اللہ صلی اللہ علیہ وسلم ضحی کی نماز پڑھا کرتے تھے؟ انہوں نے فرمایا: نہیں، مگر یہ کہ آپ سفر سے واپس تشریف لائیں۔ میں نے کہا: کیا رسول اللہ صلی اللہ علیہ وسلم کسی مہینے کے مکمل روزے رکھتے تھے؟ فرمایا: نہیں۔ میرے علم کے مطابق آپ نے کسی مہینے کے مکمل روزے رکھتے تھے؟ فرمایا: نہیں۔ میرے علم کے مطابق آپ نے کسی مہینے کے مکمل روزے نہیں رکھے علاوہ رمضان المبارک کے اور نہ کسی مہینے کے تمام دنوں کا ناغہ کیا بلکہ کچھ نہ کچھ ضرور روزے رکھتے تھے حتیٰ کہ فوت ہوگئے۔"}],[2185,"عبداللہ بن شقیق کہتے ہیں کہ میں نے ام المؤمنین عائشہ رضی اللہ عنہا سے پوچھا: کیا رسول اللہ صلی اللہ علیہ وسلم صلاۃ الضحی (چاشت کی نماز) پڑھتے تھے؟ انہوں نے کہا: نہیں، الا یہ کہ سفر سے (لوٹ کر) آتے، پھر میں نے پوچھا: کیا رسول اللہ صلی اللہ علیہ وسلم کا رمضان کے علاوہ کوئی متعین روزہ تھا؟ تو انہوں نے کہا: اللہ کی قسم آپ نے سوائے رمضان کے کسی خاص مہینے کے روزے نہیں رکھے حتی کہ آپ نے وفات پا لی، اور نہ ہی پورے ماہ بغیر روزے کے رہے، کچھ نہ کچھ روزے اس میں ضرور رکھتے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن شقیق سے روایت ہے کہ میں نے حضرت عائشہ رضی اللہ عنہا سے پوچھا: کیا رسول اللہ صلی اللہ علیہ وسلم ضحی کی نماز پڑھا کرتے تھے؟ انہوں نے فرمایا: نہیں مگر یہ کہ آپ کسی سفر سے واپس تشریف لائیں۔ میں نے عرض کیا: کیا رسول اللہ صلی اللہ علیہ وسلم رمضان المبارک کے علاوہ کسی معین مہینے کے روزے رکھتے تھے؟ انہوں نے فرمایا: اللہ کی قسم! آپ نے رمضان المبارک کے علاوہ کسی معین مہینے کے روزے نہیں رکھے حتیٰ کہ اللہ تعالیٰ کو پیارے ہوگئے اور نہ آپ نے کسی مہینے کے مکمل روزے چھوڑے، بلکہ کچھ نہ کچھ روزے رکھتے تھے۔","f2":"(۱) ’’سفر سے واپس تشریف لائیں۔‘‘ رسول اللہ صلی اللہ علیہ وسلم عموماً دن چڑھے مدینہ منورہ میں داخل ہوتے تھے اور سب سے پہلے مسجد میں تشریف لاتے اور دو رکعت پڑھتے تھے، چاہے اسے نماز ضحی کہہ لیں (وقت کی رعایت سے) یا تحیۃ المسجد (موقع کی مناسبت سے)۔ (۲) حضرت عائشہ رضی اللہ عنہا کے جواب سے معلوم ہوتا ہے کہ نبی صلی اللہ علیہ وسلم نماز ضحی نہیں پڑھتے تھے، لیکن یہ جواب ان کے اپنے علم کے مطابق ہے۔ جن لوگوں نے آپ کو نماز ضحی پڑھتے دیکھا، انہوں نے اس کو ثابت کیا ہے، لہٰذا ان کی بات کا اعتبار کیا جائے گا۔ ویسے بھی نماز ضحی کی فضیلت متعدد قولی احادیث سے ثابت ہے، اس لیے نماز ضحی کے استحباب میں کوئی شک نہیں۔ (صحیح البخاری، التہجد، حدیث: ۱۱۷۶۔ ۱۱۷۸، وصحیح مسلم، صلاۃ المسافرین، حدیث: ۷۲۰ ۷۲۲) نہ پڑھنے سے استحباب کی نفی نہیں ہوتی۔ اس مسئلے کی مزید تفصیل کے لیے دیکھئے: (ذخیرۃ العقبی شرح سنن النسائی: ۲۱/ ۲۳-۲۶)"}],[2186,"جبیر بن نفیر سے روایت ہے کہ ایک شخص نے ام المؤمنین عائشہ رضی اللہ عنہا سے روزوں کے متعلق پوچھا: تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم پورے شعبان روزے رکھتے، اور دو شنبہ (پیر) اور جمعرات کے روزے کا اہتمام فرماتے۔","الألباني: صحيح ق الشطر الأول فقط",{"u2":"حضرت جبیر بن نفیر سے منقول ہے کہ ایک آدمی نے حضرت عائشہ رضی اللہ عنہا سے (نفل) روزوں کے بارے میں سوال کیا تو انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم شعبان (کے تقریباً) سبھی روزے رکھتے تھے اور سوموار اور جمعرات کا روزہ قصداً رکھا کرتے تھے۔","f2":"ایک اور روایت میں سوموار اور جمعرات کے روزے کی وجہ نبی صلی اللہ علیہ وسلم نے یہ بیان فرمائی ہے کہ ان دو دنوں میں بندوں کے اعمال اللہ تعالیٰ کے سامنے پیش ہوتے ہیں اور میں چاہتا ہوں کہ میرے اعمال پیش ہوں تو میں روزے سے ہوں۔ دیکھئے (جامع الترمذی، الصوم، حدیث: ۷۴۷)"}],[2187,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم شعبان اور رمضان میں روزے رکھتے، اور پیر اور جمعرات کے روزے کا خاص خیال رکھتے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم شعبان اور رمضان المبارک کے مکمل روزے رکھتے تھے اور سوموار اور جمعرات کا روزہ قصداً رکھتے تھے۔"}],[2188,"صلہ بن زفر کہتے ہیں: ہم عمار رضی اللہ عنہ کے پاس تھے کہ ایک بھنی ہوئی بکری لائی گئی، تو انہوں نے کہا: آؤ تم لوگ بھی کھاؤ، تو لوگوں میں سے ایک شخص الگ ہٹ گیا، اور اس نے کہا: میں روزے سے ہوں، تو عمار رضی اللہ عنہ نے کہا: جس نے شک والے دن روزہ رکھا اس نے ابوالقاسم صلی اللہ علیہ وسلم کی نافرمانی کی۔","الألباني: صحيح",{"u2":"حضرت صلہ سے مروی ہے کہ ہم حضرت عمار رضی اللہ عنہ کے پاس تھے تو ان کے پاس بھنی ہوئی (سالم) بکری لائی گئی۔ انہوں نے (حاضرین سے) فرمایا: کھاؤ۔ لیکن کچھ لوگ ایک طرف ہوگئے اور کہنے لگے: ہمارا روزہ ہے۔ حضرت عمار رضی اللہ عنہ نے فرمایا: جس نے شک والے دن کا روزہ رکھا اس نے حضرت ابوالقاسم صلی اللہ علیہ وسلم کی نافرمانی کی۔","f2":"(۱) مذکورہ روایت کو مہقق کتاب نے سنداً ضعیف قرار دیا ہے جبکہ دیگر محققین نے اسے شواہد کی بنا پر صحیح قرار دیا ہے، محققین کی بحث سے راجح بات یہی معلوم ہوتی ہے کہ مذکورہ روایت سنداً ضعیف ہونے کے باوجود دیگر شواہد کی بنا پر قابل عمل ہو جاتی ہے۔ واللہ اعلم! مزید تفصیل کے لیے دیکھئے: (ذخیرۃ العقبی شرح سنن النسائی: ۲۱/ ۳۱-۳۸) (۲) ’’شک والے دن‘‘ سے مراد شعبان کی تیس تاریخ ہے کیونکہ اس دن امکان ہوتا ہے کہ شاید رمضان المبارک کی پہلی تاریخ ہو۔ بعض لوگ اس دن چاند نظر آئے بغیر احتیاطاً روزہ رکھ لیتے ہیں کہ شاید چاند طلوع ہوگیا ہو، مگر یہ احتیاط شریعت حقہ کی نافرمانی ہے۔ (مزید دیکھئے، حدیث: ۲۱۱۸- ۲۱۲۷) (۳) ’’ابوالقاسم‘‘ رسول اللہ صلی اللہ علیہ وسلم کی کنیت ہے۔ کبھی کبھار صحابہ کرام رضی اللہ عنہم آپ کو نام کے بجائے اس کنیت سے پکارتے تھے۔ عموماً رسول اللہ اور نبی اللہ صلی اللہ علیہ وسلم وغیرہ جلیل القدر الفاظ سے یاد کرتے تھے۔ (۴) ’’اس نے ابوالقاسم صلی اللہ علیہ وسلم کی نافرمانی کی۔‘‘ جس روایت میں صحابی اس قسم کے الفاظ کہے وہ حکماً مرفوع ہوتی ہے"}],[2189,"سماک کہتے ہیں: میں عکرمہ کے پاس ایک ایسے دن میں آیا جس کے بارے میں شک تھا کہ یہ رمضان کا ہے یا شعبان کا، وہ روٹی سبزی، اور دودھ کھا رہے تھے، انہوں نے مجھ سے کہا: آؤ کھاؤ، تو میں نے کہا: میں روزے سے ہوں، تو انہوں نے کہا: اللہ کی قسم! تم ضرور روزہ توڑو گے، تو میں نے دو مرتبہ سبحان اللہ کہا، اور جب میں نے دیکھا کہ وہ قسم پہ قسم کھائے جا رہے ہیں اور ان شاءاللہ نہیں کہہ رہے ہیں تو میں آگے بڑھا، اور میں نے کہا: اب لائیے جو آپ کے پاس ہے، انہوں نے کہا: میں نے ابن عباس رضی اللہ عنہما کو کہتے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: \"روزہ رکھو (چاند) دیکھ کر، اور افطار کرو (چاند) دیکھ کر، اور اگر تمہارے اور چاند کے بیچ کوئی بدلی یا سیاہی حائل ہو جائے تو شعبان کی تیس کی گنتی پوری کرو، اور ایک دن پہلے روزہ رکھ کر مہینے کا استقبال مت کرو، اور نہ رمضان کو شعبان کے کسی دن سے ملاؤ\"۔","الألباني: صحيح",{"u2":"حضرت سماک سے روایت ہے کہ میں حضرت عکرمہ کے پاس ایسے دن گیا جس کے بارے میں شک تھا کہ یہ شعبان کا دن ہے یا رمضان المبارک کا؟ آپ روٹی، سبزی اور دودھ تناول فرما رہے تھے۔ مجھے کہنے لگے: آؤ (کھانا کھاؤ)۔ میں نے کہا: میرا تو روزہ ہے۔ انہوں نے اللہ کی قسم کھا کر کہا کہ تجھے ضرور روزہ چھوڑنا پڑے گا۔ میں نے کہا: سبحان اللہ! دو دفعہ (میں نے ایسا کہا) جب میں نے دیکھا کہ وہ ان شاء اللہ پڑھے بغیر قسم کھا رہے ہیں تو میں آگے بڑھا اور عرض کیا: لائیے! جو آپ کے پاس ہے۔ (کھانا یا دلیل) انہوں نے کہا: میں نے ابن عباس رضی اللہ عنہ سے سنا، وہ بیان کر رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’چاند دیکھ کر روزے شروع کرو اور چاند دیکھ کر روزے رکھنے بند کرو۔ اگر بادل رکاوٹ بن جائے یا اندھرا چھا جائے۔ (اور چاند نظر نہ آئے) تو شعبان کے تیس دن پورے کرو۔ اور رمضان المبارک کے شروع ہونے سے پہلے روزہ نہ رکھو اور رمضان المبارک کو شعبان کے دن سے (روزہ رکھ کر) نہ ملاؤ۔‘‘","f2":"(۱) ’’لائیے جو آپ کے پاس ہے۔‘‘ زیادہ درست یہ ہے کہ جب انہوں نے حضرت عکرمہ کو اتنے جزم ویقین سے قسم کھاتے دیکھا تو وہ کھانا کھانے پر آمادہ ہوگئے کیونکہ انہیں یقین ہوگیا کہ آج واقعتا روزہ رکھنا درست نہیں، اس لیے کہا: لائیے کھانا۔ دوسرے معنی بھی مراد ہو سکتے ہیں کہ آپ جو اس قدر پختہ اور تاکیدی قسم کھا رہے ہیں، کوئی دلیل بھی دیجئے۔ واللہ اعلم (۲) شعبان کی تیس تاریخ کو شک نہ بھی ہو، تب بھی روزہ رکھنا منع ہے۔ اسی طرح انتیس تاریخ کو بھی منع ہے کیونکہ اس طرح رمضان اور شعبان کے روزے مل جائیں گے جبکہ آپ نے منع فرمایا ہے۔ الا یہ کہ کسی شخص کو کسی مخصوص دن، مثلاً: سوموار یا جمعرات کو روزہ رکھنے کی عادت ہو اور وہ دن اس تاریخ کو آجائے جیسا کہ پیچھے گزرا ہے۔"}],[2190,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کہتے تھے: \"سنو! رمضان کے مہینہ سے ایک یا دو روز پہلے روزہ مت رکھو، البتہ جو شخص پہلے سے روزہ رکھتا رہا ہو تو وہ رکھے\"۔","الألباني: صحيح",{"u2":"حضرت ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم فرمایا کرتے تھے: ’’خبردار! رمضان المبارک کے شروع ہونے سے ایک دو دن پہلے روزہ نہ رکھو، ہاں وہ شخص جو پہلے سے اس دن کا روزہ رکھتا تھا، وہ رکھ لے۔‘‘"}],[2191,"(تابعی) سعید بن مسیب کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے رمضان میں (رات کو) ایمان کے ساتھ اور ثواب چاہنے کے لیے قیام اللیل کیا، یعنی نماز تراویح پڑھی اس کے پچھلے گناہ بخش دئیے جائیں گے\"۔","الألباني: صحيح لغيره",{"u2":"حضرت سعید بن مسیب رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص ایمان کی حالت میں اور ثواب کی نیت سے رمضان المبارک (کی راتوں) میں نقل عبادت کرے (تراویح پڑھے) اس کے سب پہلے گناہ معاف کر دئیے جائیں گے۔‘‘"}],[2192,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں: رسول اللہ صلی اللہ علیہ وسلم لوگوں کو بغیر کوئی تاکیدی حکم دئیے رمضان (کی راتوں میں) قیام کی ترغیب دیتے، آپ فرماتے: \"جس نے رمضان میں (رات کو) ایمان کے ساتھ اور ثواب چاہنے کے لیے قیام کیا، یعنی نماز تراویح پڑھی اس کے پچھلے گناہ بخش دئیے جائیں گے\"۔","الألباني: حسن صحيح",{"u2":"نبی صلی اللہ علیہ وسلم کی زوجہ محترمہ حضرت عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ: بلا شبہ رسول اللہ صلی اللہ علیہ وسلم لوگوں کو رمضان المبارک (کی راتوں) میں نفل نماز (تراویح) کی ترغیب دیا کرتے تھے، بغیر اس کے کہ انہیں قطعی حکم دیں۔ آپ فرماتے تھے: ’’جو شخص ایمان کی حالت میں اور ثواب کی نیت سے رمضان المبارک (کی راتوں) میں نفل نماز (تراویح) پڑھے گا، اس کے سب پہلے گناہ معاف کر دیئے جائیں گے۔‘‘","f2":"(۱) ’’ایمان اور ثواب۔‘‘ یعنی روزہ رکھنے کی بنیاد ایمان ہو نہ کہ لوگوں کی دیکھا دیکھی یا ایک رسم کی پابندی یا صحت کا حصول۔ اور نیت ثواب حاصل کرنے کی ہو اور اللہ تعالیٰ کی اطاعت مقصود ہو، تعریف کا حصول اور لوگوں کی مذمت سے بچاؤ مقصود نہ ہو۔ (۲) ’’پہلے سب گناہ۔‘‘ بشرطیکہ وہ قابل معافی ہوں، یعنی حقوق العباد سے متعلق نہ ہوں اور شرک وغیرہ نہ ہو۔ واللہ اعلم (۳)امام زہری رحمہ اللہ کے شاگردوں کا اختلاف یہ ہے کہ آیا یہ حدیث مرسل ہے یا متصل؟ حضرت عائشہ رضی اللہ عنہا کی روایت ہے یا حضرت ابوہریرہ رضی اللہ عنہ کی روایت ہے؟ پھر زہری کے استاد کون ہے؟ سعید بن مسیب یا عروہ یا ابو سلمہ؟ ممکن ہے تینوں ہوں۔ بہر کیف اس سے صحت حدیث متاثر نہیں ہوتی۔"}],[2193,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں: رسول اللہ صلی اللہ علیہ وسلم آدھی رات کو نکلے، اور آپ نے مسجد میں نماز پڑھائی۔ راوی نے پوری حدیث بیان کی، اس میں یہ بھی تھا کہ انہوں نے کہا: ـ آپ صلی اللہ علیہ وسلم لوگوں کو بغیر کوئی تاکیدی حکم دیئے رمضان (کی راتوں میں) قیام یعنی صلاۃ تراویح پڑھنے کی ترغیب دیتے، اور فرماتے: \"جس نے شب قدر میں ایمان کے ساتھ اور ثواب چاہنے کے لیے قیام کیا، یعنی صلاۃ تراویح پڑھی اس کے پچھلے گناہ بخش دئیے جائیں گے\"، رسول اللہ صلی اللہ علیہ وسلم وفات پا گئے، اور معاملہ اسی پر قائم رہا ۱؎۔\n§وضاحت\n۱؎: یعنی تراویح واجب اور ضروری نہیں ہوئی۔","الألباني: صحيح الإسناد لكن قوله متوفى الخ مدرج إنما هو من قول الزهري",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ: (ایک دفعہ) رسول اللہ صلی اللہ علیہ وسلم آدھی رات کو گھر سے نکل کر مسجد میں نماز پڑھنے لگے اور لوگوں کو (نفل) نماز پڑھائی۔ اور راوی نے پوری حدیث بیان کی۔ اس حدیث میں یہ الفاظ بھی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم لوگوں کو قیام رمضان کی ترغیب دلایا کرتے تھے، بغیر اس کے کہ ان کو اس کا قطعی حکم دیں۔ اور فرماتے تھے: ’’جو شخص لیلۃ القدر میں ایمان کی بنیاد پر اور ثواب کی نیت سے نفل عبادت کرے گا، اس کے سب پہلے گناہ معاف کر دیئے جائیں گے۔‘‘ راوی نے کہا: رسول اللہ صلی اللہ علیہ وسلم فوت ہوئے تو صورت حال یہی تھی (کہ لوگ عموماً نفل نماز اکیلے اکیلے پڑھتے تھے۔ کوئی امام مقرر نہ تھا)۔"}],[2194,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو رمضان کے بارے میں فرماتے سنا: \"جس نے اس میں ایمان کے ساتھ اور ثواب کی نیت سے قیام کیا، یعنی صلاۃ تراویح پڑھی اس کے پچھلے گناہ بخش دئیے جائیں گے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ: میں نے رسول اللہ صلی اللہ علیہ وسلم کو رمضان المبارک کے بارے میں فرماتے سنا: ’’جو شخص ایمان کی بنا پر اور ثواب کے حصول کی نیت سے اس (رمضان المبارک) کا قیام کرے گا، اس کے سب پہلے گناہ معاف کر دیے جائیں گے۔‘‘"}],[2195,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں: رسول اللہ صلی اللہ علیہ وسلم آدھی رات کو نکلے تو مسجد میں نماز پڑھی۔ راوی نے پوری حدیث بیان کی، اس میں ہے: اور رسول اللہ صلی اللہ علیہ وسلم انہیں بغیر تاکیدی حکم دیئے رمضان میں قیام اللیل کرنے یعنی تہجد پڑھنے کی ترغیب دلاتے تھے، اور فرماتے تھے: \"جس نے ایمان کے ساتھ اور ثواب کی نیت سے رمضان میں قیام اللیل کیا یعنی تراویح پڑھی تو اس کے پچھلے گناہ بخش دئیے جائیں گے\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم (رمضان المبارک کے دوران میں) آدھی رات کو گھر سے نکل کر مسجد میں نماز پڑھنے لگے۔ اور (راوی نے) پوری حدیث بیان کی، اس میں یہ بھی کہا: رسول اللہa لوگوں کو قیام رمضان کی ترغیب دلایا کرتے تھے، بغیر اس کے کہ آپ ان کو اس کا قطعی حکم دیں۔ آپ فرماتے تھے: ’’جو شخص ایمان کی بنیاد پر اور ثواب کی نیت سے رمضان المبارک کی راتوں میں نفل نماز پڑھے گا، اس کے سب پہلے گناہ معاف کر دیے جائیں گے۔‘‘"}],[2196,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو رمضان کے متعلق فرماتے سنا: \"جس نے اس میں ایمان کے ساتھ اور ثواب کی نیت سے قیام اللیل کی، یعنی تہجد پڑھی تو اس کے پچھلے گناہ بخش دئیے جائیں گے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو رمضان المبارک کے بارے میں فرماتے سنا: ’’جو شخص ایمان کی بنا پر اور ثواب کی نیت سے اس کی راتوں کا قیام کرے گا (یعنی تراویح پڑھے گا) اس کے سب پہلے گناہ معاف کر کر دیے جائیں گے۔‘‘"}],[2197,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے رمضان میں ایمان کے ساتھ ثواب کی نیت سے قیام اللیل کیا یعنی تہجد پڑھی اس کے پچھلے گناہ بخش دئیے جائیں گے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص ایمان کے ساتھ اور ثواب حاصل کرنے کے لیے قیام رمضان کرے گا، اس کے سب پہلے گناہ معاف کر دیے جائیں گے۔‘‘"}],[2198,"ابوہریرہ رضی اللہ عنہ کہتے ہیں: رسول اللہ صلی اللہ علیہ وسلم لوگوں کو بغیر کوئی تاکیدی حکم دئیے، رمضان میں قیام اللیل کی ترغیب دلاتے تھے، (اور) فرماتے:\"جس نے ایمان کے ساتھ ثواب کی نیت سے رمضان میں قیام اللیل کی، یعنی نماز تراویح پڑھی اس کے پچھلے گناہ بخش دئیے جائیں گے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم قیامت رمضان میں رغبت دلایا کرتے تھے، بغیر اس کے کہ ان کو اس کا قطعی حکم دیں۔ آپ نے فرمایا: ’’جو شخص ایمان کی حالت میں اور ثواب حاصل کرنے کے لیے رمضان المبارک (کی راتوں) میں قیام کرے گا، اس کے سب پہلے گناہ معاف ہو جائیں گے۔‘‘"}],[2199,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے رمضان میں ایمان کے ساتھ ثواب کی نیت سے قیام اللیل کیا، یعنی نماز تراویح پڑھی اس کے پچھلے گناہ بخش دئیے جائیں گے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص نے ایمان کے جذبے سے اور حصول ثواب کی نیت سے رمضان المبارک (کی راتوں) میں نفل نماز (تراویح) پڑھی، اس کے سب پہلے گناہ معاف کر دیے جائیں گے۔‘‘"}],[2200,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے رمضان میں ایمان کے ساتھ ثواب کی نیت سے قیام اللیل کیا، یعنی نماز تراویح پڑھی اس کے پچھلے گناہ بخش دئیے جائیں\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، اور ثواب حاصل کرنے کی غرض سے رمضان المبارک کا قیام کرے گا، اس کے سابقہ تمام گناہ معاف کر دیے جائیں گے۔"}],[2201,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے رمضان میں ایمان کے ساتھ ثواب کی نیت سے قیام اللیل کیا، یعنی نماز تراویح پڑھی اس کے پچھلے گناہ بخش دئیے جائیں گے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص نے ایمان کی وجہ سے اور ثواب کی خاطر قیام رمضان کیا، اس کے سب پہلے گناہ معاف کر دیے جائیں گے۔‘‘"}],[2202,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس نے رمضان میں روزے رکھے، (اور قتیبہ کی روایت میں ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس نے رمضان کے مہینہ میں ایمان کے ساتھ ثواب کی نیت سے قیام اللیل کیا، یعنی نماز تراویح پڑھی، اس کے پچھلے گناہ بخش دئیے جائیں گے، اور جو شب قدر میں ایمان کے ساتھ ثواب کی نیت سے قیام اللیل کیا، یعنی نماز تراویح پڑھی، اس کے (بھی) پچھلے گناہ بخش دئیے جائیں گے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص نے رمضان المبارک کے روزے رکھے اور قیام کیا، ایمان کی بنا پر اور ثواب کی نیت سے، تو اس کے سب پہلے گناہ معاف کر دیے جائیں گے۔ اور جس شخص نے ایمان واحتساب کے ساتھ لیلۃ القدر کا قیام کیا، اس کے بھی سب پہلے گناہ معاف کر دیے جائیں گے۔‘‘"}],[2203,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس نے رمضان میں ایمان کے ساتھ ثواب کی نیت سے روزہ رکھا تو اس کے پچھلے گناہ بخش دئیے جائیں گے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص ایمان کی وجہ سے اور ثواب حاصل کرنے کے لیے رمضان المبارک کے روزے رکھے، اس کے سب پہلے گناہ معاف کر دیے جائیں گے۔‘‘"}],[2204,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے رمضان میں ایمان کے ساتھ ثواب کی نیت سے روزہ رکھا، اس کے پچھلے گناہ بخش دئیے جائیں گے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص نے ایمان کی حالت میں اور حصول ثواب کی خاطر رمضان المبارک کے روزے رکھے، اس کے سب پہلے گناہ معاف کر دیے جائیں گے۔‘‘"}],[2205,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے رمضان میں ایمان کے ساتھ ثواب کی نیت سے روزہ رکھا، اس کے پچھلے گناہ بخش دئیے جائیں گے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو آدمی ایمان واحتساب کے ساتھ رمضان المبارک کے روزے رکھے گا تو اس کے سب پہلے گناہ معاف کر دیے جائیں گے۔‘‘"}],[2206,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول صلی اللہ علیہ وسلم نے فرمایا: \"جس نے رمضان میں ایمان کے ساتھ ثواب کی نیت سے قیام کرے گا، اس کے پچھلے گناہ بخش دئیے جائیں گے، اور جو شب قدر میں ایمان کے ساتھ ثواب کی نیت سے قیام کرے گا اس کے (بھی) پچھلے گناہ بخش دئیے جائیں گے\"۔","الألباني: صحيح",{"u2":"حضرت ابو سلمہ کہتے ہیں کہ مجھ سے حضرت ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص ایمان کے جذبے سے اور ثواب کی نیت سے رمضان المبارک (کی راتوں) کا قیام کرے، اس کے سب پہلے گناہ معاف کر دیے جائیں گے۔ اور جو شخص ایمان کے جذبے سے اور ثواب کی نیت سے لیلۃ القدر کا قیام کرے، اس کے بھی سب پہلے گناہ معاف کر دیے جائیں گے۔‘‘"}],[2207,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول صلی اللہ علیہ وسلم نے فرمایا: \"جس نے رمضان کے مہینہ میں ایمان کے ساتھ ثواب کی نیت سے قیام اللیل کیا، یعنی نماز تراویح پڑھی، اس کے پچھلے گناہ بخش دیے جائیں گے، اور جو شب قدر میں ایمان کے ساتھ ثواب کی نیت سے (عبادت پر) کمربستہ ہو گا اس کے (بھی) پچھلے گناہ بخش دئیے جائیں گے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص ایمان واحتساب کے ساتھ رمضان المبارک کا قیام کرے گا، اس کے سب پہلے گناہ معاف کر دیے جائیں گے۔ اور جو شخص ایمان واحتساب کے ساتھ لیلۃ القدر کا قیام کرے گا، اس کے بھی سب پہلے گناہ معاف کر دیے جائیں گے۔‘‘"}],[2208,"نصر بن علی کہتے ہیں: مجھ سے نضر بن شیبان نے بیان کیا کہ وہ ابوسلمہ بن عبدالرحمٰن سے ملے، تو ان سے انہوں نے کہا: آپ نے ماہ رمضان کے سلسلے میں جو سب سے افضل قابل ذکر چیز سنی ہوا سے بیان کیجئے تو ابوسلمہ نے کہا: مجھ سے عبدالرحمٰن بن عوف رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کرتے ہوئے بیان کیا کہ آپ نے ماہ رمضان کا ذکر کیا تو اسے تمام مہینوں میں افضل قرار دیا اور فرمایا: \"جس نے رمضان میں ایمان کے ساتھ ثواب کی نیت سے قیام اللیل کیا، یعنی نماز تراویح پڑھی، تو وہ اپنے گناہوں سے ایسے ہی نکل جائے گا جیسے اس کی ماں نے اسے آج ہی جنا ہو\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: یہ غلط ہے «أبوسلمة حدثني عبدالرحمٰن» کے بجائے صحیح «أبوسلمة عن أبي هريرة» ہے۔","الألباني: ضعيف",{"u2":"حضرت نضر بن شیبان حضرت ابو سلمہ بن عبدالرحمن کو ملے اور عرض کیا: مجھے سب سے افضل حدیث بیان کیجئے جو آپ نے اپنے والد محترم سے رمضان المبارک کی فضیلت کے بارے میں سنی ہو۔ انہوں نے فرمایا: مجھ سے حضرت عبدالرحمن بن عوف رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے رمضان المبارک کا ذکر فرمایا اور اسے دوسرے تمام مہینوں پر فضیلت دی اور فرمایا: ’’جو شخص ایمان کی بنا پر اور ثواب کی نیت سے رمضان المبارک (کی راتوں) میں قیام کرے، وہ اپنے گناہوں سے اس طرح صاف ہو جاتا ہے جس طرح وہ اس دن تھا جس دن اس کی والدہ نے اسے جنم دیا تھا۔‘‘\nامام ابوعبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں: یہ غلط ہے۔ (یعنی عبدالرحمن بن عوف کا ذکر) درست ابو سلمہ عن ابی ہریرہ ہے۔","f2":"امام نسائی رحمہ اللہ بیان کرتے ہیں کہ اس حدیث میں حضرت عبدالرحمن بن عوف رضی اللہ عنہ کا ذکر صحیح نہیں ہے۔ ان کے بجائے حضرت ابوہریرہ رضی اللہ عنہ کا ذکر درست ہے۔ باب کا بھی یہی مقصد تھا کہ یحییٰ بن ابی کثیر اور نضر بن شیبان کا اختلاف واضح ہو، یحییٰ بن ابی کثیر نے تو اس روایت کو حضرت ابوہریرہ رضی اللہ عنہ کی روایت بتلایا ہے جبکہ نضر نے حضرت عبدالرحمن بن عوف کی۔ امام نسائی رحمہ اللہ نے نضر کی بات کو غلط جبکہ یحییٰ بن ابی کثیر کی بات کو درست قرار دیا ہے۔ واللہ اعلم"}],[2209,"اس سند سے بھی ابوسلمہ سے اسی کے مثل حدیث مروی ہے اس میں «من صامه وقامه إيمانا واحتسابا» ہے۔","الألباني: ضعيف",{"u2":"حضرت ابو سلمہ سے اسی طرح کی روایت آتی ہے جس میں یہ لفظ ہیں: ’’جس شخص نے ایمان واحتساب کے ساتھ رمضان المبارک کے روزے رکھے اور (راتوں کا) قیام کیا… الخ۔‘‘"}],[2210,"نضر بن شیبان کہتے ہیں: میں نے ابوسلمہ بن عبدالرحمٰن سے کہا کہ آپ مجھ سے ماہ رمضان کے متعلق کوئی ایسی بات بیان کریں جو آپ نے اپنے والد (عبدالرحمٰن بن عوف رضی اللہ عنہ) سے سنی ہو، اور اسے آپ کے والد نے رسول اللہ صلی اللہ علیہ وسلم سنا ہو، آپ کے والد اور رسول اللہ صلی اللہ علیہ وسلم کے بیچ کوئی اور حائل نہ ہو۔ انہوں نے کہا: اچھا سنو! مجھ سے میرے والد نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بیشک اللہ تبارک و تعالی نے تم پر رمضان کے روزے فرض کیے ہیں، اور میں نے تمہارے لیے اس میں قیام کرنے کو سنت قرار دیا ہے اس میں جو شخص ایمان کے ساتھ ثواب کی نیت سے روزہ رکھے گا اور (عبادت پر)کمربستہ ہو گا تو وہ اپنے گناہوں سے ایسے نکل جائے گا جیسے اس کی ماں نے اسے آج ہی جنا ہو\"۔","الألباني: ضعيف",{"u2":"حضرت نضر بن شیبان نے کہا: میں نے حضرت ابو سلمہ بن عبدالرحمن سے کہا: مجھے کوئی ایسی حدیث بیان کیجئے جو آپ نے اپنے والد محترم سے سنی ہو اور آپ کے باپ کے رسول اللہ صلی اللہ علیہ وسلم سے رمضان المبارک کے بارے میں بلا واسطہ سنی ہو۔ انہوں نے کہا: ہاں مجھے والد محتگرم نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بلاشبہ اللہ تعالیٰ نے تم پر رمضان المبارک کے روزے رکھنا فرض کیا ہے اور میں نے تمہارے لیے اس (کی راتوں) کا قیام مسنون کیا ہے، لہٰذا جو شخص ایمان رکھتے ہوئے اور ثواب کی نیت سے اس ماہ مقدس میں صیام وقیام کرے گا، وہ گناہوں سے اس طرح پاک ہو جائے گا جس طرح اسے اس کی ماں نہ گناہوں سے پاک جنا تھا۔‘‘","f2":"(۱)مذکورہ تینوں روایات (۲۲۱۰-۲۲۱۲) ضعیف ہیں، اس لیے کہ رمضان کے روزوں اور قیام کی فضیلت تو صحیح روایات سے ثابت ہے لیکن آخری حصہ ’’پاک جننے والا‘‘ صحیح نہیں ہے۔ (۲)رمضان المبارک کے روزوں کی فرضیت تو متفقہ مسئلہ ہے، الب تہ راتوں کا قیام نفل ہے، لیکن یہ نفل موکد ہیں۔ چونکہ یہ نوافل رمضان المبارک کی خصوصیت ہیں، لہٰذا انہیں ترک نہیں کرنا چاہیے کیونکہ امتیازات کی پابندی مؤکد ہوتی ہے، البتہ آپ کے دور میں رمضان کے نفلوں میں فرضیت کے ڈر سے مستقل جماعت سے اجتناب کیا گیا، صرف تین دن آپ نے جماعت کروائی ویسے لوگ ٹولیوں کی صورت میں آپ کے دور میں بھی پڑھا کرتے تھے۔ جب فرضیت کا خطرہ نہ رہا تو حضرت عمر رضی اللہ عنہ نے باقاعدہ جماعت کا دوبارہ آغاز فرما دیا، لہٰذا اب یہی سنت ہے کیونکہ خلفائے راشدین کی سنت پر عمل کرنا بھی ضروری ہے، نیز اس پر صحابہ اور مابعد ادوار کا اجماع ہے، لہٰذا کسی مسجد کو تراویح کی جماعت سے محروم نہیں رکھنا چاہیے، البتہ اگر کوئی حافظ قاری جماعت سے الگ پڑھنا چاہے تو وہ الگ بھی پڑھ سکتا ہے۔ عشاء کے فوراً بعد پڑھے یا تہجد کے وقت۔ ہاں، جماعت عشاء کے بعد ہی ہوگی۔ مسنون نماز تراویح گیارہ رکعات ہے کیونکہ جن دنوں آپ نے جماعت کروائی تھی، گیارہ رکعت ہی پڑھائی تھیں، نیز رمضان اور غیر رمضان آپ علیہ السلام اتنی نماز ہی پڑھتے تھے۔ نبی اکرم صلی اللہ علیہ وسلم یا کسی صحابی سے نماز تراویح کسی صحیح حدیث یا اثر سے گیارہ رکعات سے زائد ثابت نہیں، اس لیے اسی پر اکتفاء مسنون ومشروع ہے۔ جن صحابہ کرام رضی اللہ عنہم کے آثار کی روشنی میں گیارہ سے زائد نوافل (نماز تراویح) کا دعویٰ کیا جاتا ہے، وہ سب ضعیف اور محدثین کے ہاں ناقابل اعتبار ہیں۔ تفصیل کے لیے ملاحظہ فرمائیے: (صلاۃ التراویح للالبانی)"}],[2211,"علی بن ابی طالب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تبارک و تعالی کہتا ہے: روزہ میرے لیے ہے، اور میں ہی اس کا بدلہ دوں گا۔ اور روزے دار کے لیے دو خوشیاں ہیں: ایک جس وقت وہ روزہ کھولتا ہے، اور دوسری جس وقت وہ اپنے رب سے ملے گا، اور قسم ہے اس ذات کی جس کے ہاتھ میں میری جان ہے۔ روزے دار کے منہ کی بو اللہ کے نزدیک مشک کی بو سے بھی زیادہ پاکیزہ ہے\"۔","الألباني: صحيح لغيره",{"u2":"حضرت علی بن ابی طالب رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ تعالیٰ فرماتا ہے: بلاشبہ روزہ میرے لیے ہے اور میں ہی اس کا بدلہ دوں گا۔ روزے دار کے لیے دو وقت خوشی کے ہیں: جب وہ روزہ کھولتا ہے اور جب اپنے رب کو ملے گا۔ قسم اس ذات کی جس کے ہاتھ میں میری جان ہے! روزے دار کے منہ کی بو اللہ تعالیٰ کے نزدیک کستوری سے بھی زیادہ اچھی ہے۔‘‘","f2":"(۱)’’روزہ میرے لیے ہے۔‘‘ سب عبادات ہی اللہ تعالیٰ کے لیے ہوتی ہیں، مگر روزے کی تخصیص کی وجہ غالباً یہ ہے کہ روزے میں ریا کاری ممکن نہیں کیونکہ اس کی کوئی ظاہر علامت نہیں جسے کوئی دیکھ سکے روزے کے علاوہ باقی تمام عبادات میں لوگوں کی طرف سے تعریف ممکن ہے، مثلاً: نماز اور حج وغیرہ کیونکہ یہ عبادات لوگوں کو نظر آتی ہیں، جبکہ روزہ صرف اللہ تعالیٰ ہی کے علم میں ہوتا ہے۔ (۲)’’میں ہی اس کا بدلہ دوںـ گا۔‘‘ یعنی کوئی دوسرا اس کا بدلہ نہیں دے سکتا کیونکہ وہ اس کا ثواب جانتا ہی نہیں، صرف میں ہی جانتا ہوں، لہٰذا میں ہی اس کا بدلہ دوں گا جیسا کہ حدیث نبمبر (۲۲۱۷) میں ہے کہ ہر نیکی کا بدلہ دس سے سات سو گنا تک ہے۔ سوائے روزے کے کہ وہ بے حساب ہے، نیز روزے کا بدلہ جنت ہے اور جنت کوئی اور نہیں دے سکتا۔ (۳)’’جب روزہ کھولتا ہے۔‘‘ اس وقت خوشی اللہ تعالیٰ کے فریضے کی تکمیل کی وجہ سے ہوتی ہے یا طبعی خوشی مراد ہے جو ہر انسان کو کھانے سے حاصل ہو تی ہے۔ (۴)’’جب اپنے رب کو ملے گا۔‘‘ اس وقت خوشی ہوگی، اللہ تعالیٰ کی رضا مندی اور روزے کا ثواب دیکھ کر اور یہی حقیقی خوشی ہے۔ (۵)’’روزے دار کے منہ کی بو۔‘‘ جو معدہ خالی ہونے کی وجہ سے پیدا ہوتی ہے۔ دنیا میں انسان خوشبو والے شخص کو اپنے قریب کرتا ہے۔ اللہ تعالیٰ بھی روزے دار کو اپنے قریب فرمائے گا اور اس سے محبت فرمائے گا گویا یہ بو جو روزے کی حالت میں منہ سے آتی ہے، قیامت کے دن کستوری کی خوشبو کا تمثیل اختیار کرے گی۔ ممکن ہے دنیا ہی میں روزے کی حالت کی بو اللہ تعالیٰ یا فرشتوں کو کستوری سے بڑھ کر خوشبو دار معلوم ہوتی ہو۔ {اِنَّ اللّٰہَ بِکُلِّ شَیْئٍ عَلِیْمٌ} (الانفال: ۷۵) (۶)اللہ کی صفت کلام کا اثبات ہوتا ہے، نیز پتا چلتا ہے کہ اللہ کا کلام صرف قرآن مجید ہی نہیں بلکہ اللہ تعالیٰ جب چاہتا ہے اور جو چاہتا ہے کلام فرماتا ہے۔ مذکورہ بالا حدیث، حدیث قدسی ہے۔ حدیث قدسی دراصل اللہ ہی کا کلام ہوتا ہے۔ فرق صرف یہ ہے کہ اس کی بطور عبادت تلاوت نہیں کی جاتی۔"}],[2212,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ اللہ عزوجل فرماتا ہے: روزہ خاص میرے لیے ہے اور میں ہی اس کا بدلہ دوں گا، اور روزے دار کے لیے دو خوشیاں ہیں: ایک وقت وہ اپنے رب سے ملے گا، اور دوسری خوشی وہ جو اسے روزہ کھولنے کے وقت حاصل ہوتی ہے۔ اور روزے دار کے منہ کی بو اللہ کے نزدیک مشک کی بو سے بھی زیادہ پاکیزہ ہے۔","الألباني: صحيح الإسناد",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ اللہ عزوجل نے فرمایا: ’’روزہ میرے لیے ہے اور میں ہی اس کا بدلہ دوں گا۔ روزے دار کو دو خوشیاں نصیب ہیں: ایک خوشی جب وہ اپنے رب تعالیٰ سے ملے گا اور دوسری خوشی افطار کے وقت۔ اور روزے دار کے منہ کی بو اللہ تعالیٰ کے نزدیک کستوری سے بھی بڑھ کر خوشبودار ہے۔‘‘"}],[2213,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی کہتا ہے: روزہ میرے لیے ہے۔ اور میں ہی اس کا بدلہ دوں گا، اور روزہ دار کے لیے دو خوشیاں ہیں: ایک جب وہ افطار کرتا ہے تو خوش ہوتا ہے، اور (دوسری) جب وہ (قیامت میں) اللہ سے ملے گا اور وہ اسے بدلہ دے گا تو وہ خوش ہو گا، اور قسم ہے اس ذات کی جس کے ہاتھ میں محمد صلی اللہ علیہ وسلم کی جان ہے، روزہ دار کے منہ کی بو اللہ کے نزدیک مشک کی بو سے بھی زیادہ پاکیزہ ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابو سعید رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ تعالیٰ فرماتا ہے: روزہ میرے لیے ہے اور میں ہی اس کی حقیقی جزا دوں گا۔ روزے دار کے لیے دو خوشیاں ہیں: ایک، جب وہ روزہ کھولتا ہے تو خوش ہوتا ہے۔ دوسرا جب وہ اللہ تعالیٰ کو ملے گا، پھر اللہ اسے روزے کا بدلہ دے گا تو وہ خوش ہوگا۔ قسم اس ذات کی جس کے ہاتھ میں محمد کی جان ہے! روزے دار کے منہ کی بو اللہ تعالیٰ کے نزدیک کستوری کی خوشبو سے بھی پاکیزہ تر ہے۔‘‘"}],[2214,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"(اللہ تعالی فرماتا ہے:) روزہ میرے لیے ہے، اور میں ہی اس کا بدلہ دوں گا، روزہ دار دو بار خوش ہوتا ہے: ایک اپنے روزے کو کھولنے کے وقت، اور دوسرے جس دن وہ اللہ سے ملے گا، اور روزہ دار کے منہ کی بو اللہ کے یہاں مشک کی بو سے بھی زیادہ پاکیزہ ہے\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے (اللہ تعالیٰ سے حکایت کرتے ہوئے) فرمایا: ’’روزہ میرے لیے ہے اور میں ہی اس کا بدلہ دوں گا۔ روزے دار دو دفعہ خوش ہوگا: افطار کے وقت اور جب اللہ تعالیٰ کو ملے گا۔ اور روزے دار کے منہ کی بو اللہ تعالیٰ کے نزدیک کستوری کی مہک سے بھی زیادہ اچھی ہے۔‘‘"}],[2215,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ابن آدم جو بھی نیکی کرتا ہے ان اس کے لیے دس سے لے کر سات سو گنا تک بڑھا کر لکھی جاتی ہیں۔ اللہ عزوجل فرماتا ہے: سوائے روزے کے کیونکہ وہ میرے لیے ہے اور میں ہی اس کا بدلہ دوں گا، وہ اپنی شہوت اور اپنا کھانا پینا میری خاطر چھوڑتا ہے، روزہ ڈھال ہے، روزہ دار کے لیے دو خوشیاں ہیں۔ ایک خوشی اسے اپنے افطار کے وقت حاصل ہوتی ہے اور دوسری خوشی اسے اپنے رب سے ملنے کے وقت حاصل ہو گی، اور روزہ دار کے منہ کی بو اللہ کے نزدیک مشک کی بو سے زیادہ پاکیزہ ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’انسان جو نیکی کرتا ہے، وہ اس کے لیے دس گنا سے سات سو گنا تک لکھی جاتی ہے۔ اللہ تعالیٰ نے فرمایا: مگر روزہ کہ وہ میرے لیے ہے اور اس کا بدلہ میں ہی دوں گا۔ وہ میری وجہ سے اپنی شہوت اور کھانے پینے سے دست کش ہوتا ہے۔ روزہ ڈھال ہے۔ روزے دار کے حصے میں دو خوشیاں ہیں، ایک تو افطار کے وقت اور دوسری اپنے رب سے ملاقات کے وقت۔ اور روزے دار کے منہ کی بو اللہ تعالیٰ کے نزدیک کستوری کی خوشبو سے زیادہ عمدہ ہے۔‘‘","f2":"(۱) ’’دس گنا سے سات سو گنا تک۔‘‘ کم از کم دس گنا تو اللہ تعالیٰ کے مقرر کردہ وعدے کی بنا پر ہے: {مَنْ جَآئَ بِالْحَسَنَۃِ فَلَہٗ عَشْرُ اَمْثَالِہَا} (الانعام: ۱۶۰) ’’جو شخص ایک نیکی لائے گا اس کے لیے اس کا دس گنا (ثواب) ہے۔‘‘ اور زائد اپنے اپنے خلوص کی کمی بیشی کے لحاظ سے۔ (۲) ’’ڈھال ہے۔‘‘ یعنی گناہوں سے اور قیامت کے دن آگ سے ڈھال ہوگا۔ گناہوں سے مضبوط ڈھال بنا رہا تو آگ سے بھی مضبوط ڈھال ہوگا۔ یہاں کمزور ڈھال ثابت ہوا تو آخرت میں بھی کمزور ڈھال ہوگا، لہٰذا روزے کو ہر قسم کی کمزوری سے محفوظ رکھنا چاہیے۔"}],[2216,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ابن آدم کا ہر عمل اس کے لیے ہے سوائے روزے کے، وہ میرے لیے ہے اور میں ہی اس کا بدلہ دوں گا، روزہ ڈھال ہے، جب تم میں سے کسی کے روزے کا دن ہو تو فحش گوئی نہ کرے، شور و شغب نہ کرے، اگر کوئی اسے گالی دے یا اس سے مار پیٹ کرے تو اس سے کہہ دے (بھائی) میں روزے سے ہوں، (مار پیٹ گالی گلوچ کچھ نہیں کر سکتا) اور قسم ہے اس ذات کی جس کے ہاتھ میں محمد صلی اللہ علیہ وسلم کی جان ہے، روزہ دار کے منہ کی بو اللہ تعالی کے یہاں قیامت کے دن مشک کی بو سے زیادہ پاکیزہ ہو گی، روزہ دار کے لیے دو خوشیاں ہیں جن سے وہ خوش ہوتا ہے: ایک جب وہ روزہ کھولتا ہے تو اپنے روزہ کھولنے سے خوش ہوتا ہے، اور دوسری جب وہ اپنے بزرگ و برتر رب سے ملے گا تو اپنے روزہ (کا ثواب) دیکھ کر خوش ہو گا\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے (اللہ تعالیٰ سے حکایت کرتے ہوئے) فرمایا: ’’انسان کا ہرعمل اس کے لیے ہے سوائے روزے کے کہ وہ میرے لیے ہے اور میں ہی اس کا بدلہ دوں گا۔ اور روزہ ڈھال ہے۔ جب کسی دن تم میں سے کسی کا روزہ ہو تو نہ وہ کوئی شہوانی بات کرے، نہ شور وغل مچائے۔ اگر کوئی شخص اس سے گالی گلوچ یا لڑائی کرے تو وہ کہہ دے: میں روزے دار ہوں۔ قسم اس ذات کی جس کے ہاتھ میں محمد کی جان ہے! روزے دار کے منہ کی بو قیامت کے دن اللہ تعالیٰ کے نزدیک کستوری کی خوشبو سے بھی پاکیزہ تر ہوگی۔ روزے دار کے نصیب میں دو خوشیاں ہیں: جب روزہ کھولتا ہے تو افطار سے خوش ہوتا ہے اور جب اپنے رب تعالیٰ کو ملے گا تو اپنے روزے (کی جزا) سے خوش ہوگا۔‘‘","f2":"(۱) ’’ہر عمل اس کے لیے ہے۔‘‘ یعنی ہر عمل میں چاہے تو وہ مخلص ہو، چاہے تو اخلاص کو ختم کر دے، اس کا مدار اسی پر ہے اور اس کا اس کو مفاد ہو سکتا ہے، مثلاً: لوگ اس کی تعریف کریں یا اس کو کچھ بدلہ وعوض دیں کیونکہ وہ اعمال لوگوں کو نظر آتے ہیں مگر روزہ تو صرف اللہ تعالیٰ کو نظر آتا ہے، لہٰذا اس کا مکمل اجر تو اللہ تعالیٰ ہی دے گا۔ (۲) ’’نہ شہوانی بات کرے۔‘‘ گویا یہ چیزیں روزے کی ڈھال میں سوراخ کرنے والی ہیں جس سے ڈھال ناکارہ ہو جائے گی۔ (۳) ’’وہ کہہ دے۔‘‘ یعنی لڑائی کرنے والے سے کہے تاکہ اسے شرم آئے۔ یا اپنے دل میں کہے، اپنے آپ کو سمجھانے کے لیے، پہلا مفہوم الفاظ حدیث کے زیادہ قریب ہے۔"}],[2217,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی فرماتا ہے: ابن آدم کا ہر عمل اسی کے لیے ہوتا ہے سوائے روزے کے، وہ خالص میرے لیے ہے، اور میں خود ہی اسے اس کا بدلہ دوں گا، روزہ ڈھال ہے، تو جب تم میں سے کسی کے روزے کا دن ہو تو فحش اور لایعنی بات نہ کرے، اور نہ ہی شور و غل مچائے، اگر کوئی اس سے گالی گلوچ کرے یا اس کے ساتھ مار پیٹ کرے تو اس سے کہے: میں روزہ دار آدمی ہوں (گالی گلوچ مار پیٹ نہیں کر سکتا) قسم ہے اس ذات کی جس کے ہاتھ میں محمد کی جان ہے روزہ دار کے منہ کی بو اللہ کے نزدیک مشک کی بوسے زیادہ عمدہ ہے۔ یہ حدیث ابوہریرہ رضی اللہ عنہ سے سعید بن مسیب نے روایت کی ہے (جو آگے آ رہی ہے)۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ عزوجل نے فرمایا: انسان کا ہر عمل اس کے لیے ہے سوائے روزے کے کہ وہ میرے لیے ہے اور میں ہی اس کا بدلہ دوں گا۔ روزہ ڈھال ہے۔ جب تم میں سے کسی کا روزہ ہو تو نہ وہ کوئی شہوانی بات کرے اور نہ شور وغل کرے۔ اگر کوئی شخص اس سے گالی گلوچ یا لڑائی کرے تو وہ کہہ دے: میں روزے دار ہوں۔ قسم اس ذات کی جس کے ہاتھ میں محمد کی جان ہے! روزے دار کے منہ کی بو اللہ تعالیٰ کے نزدیک کستوری کی خوشبو سے بھی زیادہ اچھی ہے۔‘‘\nحضرت ابوہریرہ رضی اللہ عنہ سے سعید بن مسیب نے بھی یہ روایت بیان کی ہے۔"}],[2218,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"اللہ تعالی فرماتا ہے: آدمی کا ہر عمل اسی کے لیے ہے، سوائے روزہ کے وہ میرے لیے ہے، اور میں خود ہی اس کا بدلہ دوں گا اور قسم ہے اس ذات کی جس کے ہاتھ میں محمد صلی اللہ علیہ وسلم کی جان ہے، روزہ دار کے منہ کی بو اللہ کے نزدیک مشک کی بو سے بھی زیادہ پاکیزہ ہے\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’اللہ عزوجل فرماتا ہے: انسان کا ہر عمل اس کے لیے ہے مگر روزہ میرے لیے ہے اور میں ہی اس کا بدلہ دوں گا۔ قسم اس ذات کی جس کے ہاتھ میں محمد کی جان ہے! روزے دار کے منہ کی بو اللہ تعالیٰ کے نزدیک کستوری کی مہک سے بھی پاکیزہ تر ہے۔‘‘"}],[2219,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"(اللہ تعالی فرماتا ہے) ہر وہ نیکی جسے آدمی کرتا ہے تو اسے اس کے بدلے دس نیکیاں ملتی ہے، سوائے روزے کے، روزہ خاص میرے لیے ہے اور میں خود ہی اس کا بدلہ دوں گا\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، نبی صلی اللہ علیہ وسلم نے اللہ تعالیٰ سے بیان فرمایا: ’’ہر نیکی جو انسان کرتا ہے وہ اسے (ثواب کے لحاظ سے کم از کم) دس گنا ہو کر ملے گی مگر روزہ کہ وہ میرے لیے ہے اور میں ہی اس کا بدلہ دوں گا۔‘‘"}],[2220,"ابو امامہ رضی اللہ عنہ کہتے ہیں: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، اور آپ سے عرض کیا کہ مجھے کوئی ایسا حکم دیجئیے جسے میں آپ سے براہ راست اخذ کروں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اپنے اوپر روزہ لازم کر لو کیونکہ اس کے برابر کوئی (عبادت) نہیں ہے\" ۱؎۔\n§وضاحت\n۱؎: یعنی شہوت کے توڑنے اور نفس امارہ اور شیطان کے دفع کرنے کے سلسلہ میں روزے کے برابر کوئی عبادت نہیں، یا کثرت ثواب میں اس کے برابر کوئی عبادت نہیں۔","الألباني: صحيح",{"u2":"حضرت ابو امامہ رضی اللہ عنہ بیان کرتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوا اور عرض کیا: مجھے ایسی چیز کا حکم دیجئے جو میں آپ سے خصوصی طور پر حاصل کروں (اس پر عمل کروں)۔ آپ نے فرمایا: ’’روزہ رکھا کرو کیونکہ اس جیسی کوئی چیز نہیں۔‘‘","f2":"’’اس جیسی کوئی چیز نہیں۔‘‘ ثواب واجر کے لحاظ سے یا گناہ سے بچنے کے لیے؟ بعض نے اس روایت میں صوم سے مراد ہی تقویٰ لیا ہے کیونکہ صوم کے معنی ہیں، رک جانا، اور تقویٰ کے معنی بھی تقریباً یہی ہیں لیکن پہلے معنی ہی صحیح ہیں جو کہ مشہور ہیں لیکن یاد رہے کہ روزوں کا مقصد بھی تقویٰ کا حصول ہے۔"}],[2221,"ابوامامہ باہلی رضی اللہ عنہ کہتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! مجھے کسی ایسی چیز کا حکم دیجئیے جس سے اللہ تعالی مجھے فائدہ پہنچائے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"روزے کو لازم پکڑو کیونکہ اس کے برابر کوئی (عبادت) نہیں ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوامامہ باہلی رضی اللہ عنہ باین کرتے ہیں کہ میں نے عرض کیا: اے اللہ کے رسول! مجھے کسی ایسی چیز کا حکم دیجئے جس کے ساتھ اللہ تعالیٰ مجھے بہت فائدہ عطا فرمائے۔ آپ نے فرمایا: ’’روزے کو معمول بنا کیونکہ اس جیسی کوئی چیز نہیں۔‘‘"}],[2222,"ابوامامہ باہلی رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: کون سا عمل افضل ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"روزے کو لازم پکڑو کیونکہ اس کے برابر کوئی عمل نہیں ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابو امامہ رضی اللہ عنہ سے روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: کون سا عمل افضل ہے؟ آپ نے فرمایا: ’’روزے کی عادت ڈال کیونکہ کوئی اور کام اس کے برابر نہیں۔‘‘","f2":"اس روایت کے راوی کا لقب ضعیف ہے، روایت کے اعتبار سے ضعیف نہیں کیونکہ وہ کثرت عبادت سے کمزور ہوگئے تھے۔"}],[2223,"ابوامامہ باہلی رضی اللہ عنہ کہتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! مجھے کسی کام کا حکم فرمایئے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"روزے کو لازم پکڑو کیونکہ اس جیسا کوئی (عمل) نہیں ہے\"۔ میں نے (پھر) عرض کیا: اللہ کے رسول! مجھے کسی کام کا حکم دیجئیے! آپ صلی اللہ علیہ وسلم نے فرمایا: \"روزے کو لازم پکڑو کیونکہ اس کے برابر کوئی عمل نہیں ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوامامہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے عرض کیا: اے اللہ کے رسول! مجھے کسی کام کا حکم دیجئے۔ آپ نے فرمایا: ’’روزے رکھا کر کیونکہ اس جیسا کوئی کام نہیں۔‘‘ میں نے پھر کہا: اے اللہ کے رسول! مجھے کسی اور کام کا حکم دیجئے۔ آپ نے فرمایا: ’’روزے ہی رکھا کر، کوئی اور کام اس کے برابر نہیں۔‘‘"}],[2224,"معاذ بن جبل رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"روزہ ڈھال ہے\"۔","الألباني: صحيح",{"u2":"حضرت معاذ بن جبل رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’روزہ ڈھال ہے۔‘‘","f2":"دیکھیے فوائد حدیث نمبر 2217۔"}],[2225,"معاذ بن جبل رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"روزہ ڈھال ہے\" ۱؎۔\n§وضاحت\n۱؎: یعنی جہنم کی آگ سے بچاؤ کرتا ہے یا شیطان کے وار اور گناہوں کے ارتکاب سے بچاتا ہے جیسے ڈھال دشمن کے وار سے بچاتا ہے۔","الألباني: صحيح لغيره",{"u2":"حضرت معاذ بن جبل رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’روزہ ڈھال کی طرح بچاؤ کا ذریعہ ہے۔‘‘"}],[2226,"معاذ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"روزہ ڈھال ہے\"۔","الألباني: صحيح لغيره",{"u2":"حضرت معاذ رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’روزہ ڈھال ہے۔‘‘"}],[2227,"شعبہ کہتے ہیں کہ حکم نے مجھ سے کہا کہ میں نے یہ حدیث ان سے یعنی معاذ بن جبل رضی اللہ عنہ سے چالیس سال پہلے سنی تھی، پھر حکم نے کہا نیز مجھ سے اسے میمون بن ابی شبیب نے بیان کیا انہوں نے معاذ بن جبل رضی اللہ عنہ سے روایت کی۔"],[2228,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"روزہ ڈھال ہے\"۔","الألباني: صحيح",{"u2":"حضرت حکم نے کہا کہ مجھے اس (حضرت معاذ رضی اللہ عنہ کی) روایت کو اپنے استاد سے سنے، چالیس سال ہوگئے ہیں، پھر کہتے ہیں: مجھے یہ روایت معاذ بن جبل سے (عروہ کے علاوہ) میمون بن ابی شبیب نے بھی بیان کی ہے۔\nحضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’روزہ بچاؤ کا سامان ہے۔‘‘"}],[2229,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: \"روزہ ڈھال ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’روزہ ڈھال ہے۔‘‘"}],[2230,"بنی عامر بن صعصعہ کی اولاد میں سے مطرف نامی ایک شخص کہتے ہیں کہ عثمان بن ابی العاص رضی اللہ عنہ نے ان کے لیے دودھ منگوایا تاکہ وہ انہیں پلائیں تو مطرف نے کہا: میں تو روزے سے ہوں۔ تو عثمان رضی اللہ عنہ نے کہا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا ہے: \"روزہ ڈھال ہے جس طرح کہ لڑائی کے موقع پر تم میں سے کسی کے پاس ڈھال ہوتی ہے\"۔","الألباني: صحيح",{"u2":"حضرت عثمان بن ابی العاص رضی اللہ عنہ نے حضرت مطرف کے لیے دودھ منگوایا تاکہ وہ اسے پیے تو انہوں نے کہا: میں روزے سے ہوں۔ تو حضرت عثمان بن ابی العاص رضی اللہ عنہ کہنے لگے: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’روزہ ڈھال ہے جیسے تمہارے پاس جنگ میں ڈھال ہوتی ہے۔‘‘"}],[2231,"مطرف کہتے ہیں کہ میں عثمان بن ابی العاص رضی اللہ عنہ کے پاس آیا تو انہوں نے (میری ضیافت کے لیے) دودھ منگوایا، تو میں نے کہا: میں روزے سے ہوں، تو انہوں نے کہا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا ہے: \"روزہ آگ سے بچاؤ کے لیے کی ڈھال ہے جس طرح کہ تم میں سے کسی کے پاس لڑائی میں دشمن کے وار سے بچاؤ کے لیے ڈھال ہوتی ہے\"۔","الألباني: صحيح",{"u2":"حضرت مطرف کہتے ہیں کہ میں حضرت عثمان بن ابی العاص رضی اللہ عنہ کے پاس حاضر ہوا تو انہوں نے میرے لیے دودھ منگوایا۔ میں نے عرض کیا: بلاشبہ میں روزے سے ہوں۔ فرمانے لگے: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’روزہ (جہنم کی) آگ سے (بچاؤ کے لیے) ڈھال ہے جیسے تمہارے پاس جنگ میں (بچاؤ کے لیے) ڈھال ہوتی ہے۔‘‘"}],[2232,"سعید بن ابی ہند کہتے ہیں کہ مطرف عثمان رضی اللہ عنہ کے پاس آئے۔ آگے راوی نے اس طرح کی روایت بیان کی، یہ روایت مرسل ہے۔","الألباني: سكت عنه الشيخ",{"u2":"حضرت سعید بن ابی ہند سے بھی یہی واقعہ منقول ہے مگر وہ روایت مرسل ہے۔"}],[2233,"ابوعبیدہ عامر بن عبداللہ الجراح رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"روزہ ڈھال ہے جب تک کہ وہ اسے (جھوٹ و غیبت وغیرہ کے ذریعہ) پھاڑ نہ دے\"۔","الألباني: ضعيف",{"u2":"حضرت ابوعبیدہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’روزہ ڈھال ہے جب تک وہ (روزے دار) اسے پھاڑ نہ لے۔‘‘","f2":"ایک دوسری روایت میں غیبت کا لفظ ہے، یعنی غیبت اور اس قسم کے دوسرے گناہ روزے کو اتنا زخمی کر دیتے ہیں کہ وہ آگ سے بچاؤ کے کام نہ آسکے گا، جیسے ڈھال میں سوراخ ہوں تو وہ جنگ میں کام نہیں آتی۔ گویا روزہ جہنم کی آگ سے تبھی ڈھال بنے گا جب روزے دار نے اپنے روزے کے درمیان گناہوں سے اجتناب کیا ہو، ورنہ وہ ضائع ہو سکتا ہے۔"}],[2234,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"روزہ جہنم کی آگ سے بچنے کے لیے ڈھال ہے، جو شخص روزہ دار ہو کر صبح کرے تو وہ اس دن جہالت و نادانی کی کوئی بات نہ کرے، اور اگر کوئی شخص اس کے ساتھ جہالت و نادانی کی بات کرنے لگے تو اسے گالی نہ دے، برا بھلا نہ کہے۔ اس کے لیے مناسب ہو گا کہ وہ اس سے کہے، (بھائی) میں روزے سے ہوں، (میں تم سے لڑائی جھگڑا نہیں کر سکتا) قسم ہے اس ذات کی جس کے ہاتھ میں محمد (صلی اللہ علیہ وسلم) کی جان ہے، روزہ دار کے منہ کی بو مشک کی بو سے بھی زیادہ پاکیزہ ہے\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’روزہ آگ سے ڈھال ہے۔ جو شخص روزے سے ہو، اس دن وہ جہالت (بدتہذیبی) کا کوئی کام نہ کرے۔ اور اگر کوئی دوسرا شخص اس سے جہالت سے پیش آئے تو وہ اس سے گالی گلوچ نہ کرے بلکہ کہہ دے کہ میں روزے سے ہوں۔ قسم اس ذات کی جس کے ہاتھ میں محمد کی جان ہے! روزے دار کے منہ کی بو اللہ تعالیٰ کے نزدیک کستوری کی مہک ہے پاکیزہ تر ہے۔‘‘"}],[2235,"ابوعبیدہ بن الجراح رضی اللہ عنہ کہتے ہیں کہ روزہ ڈھال ہے جب تک کہ وہ اسے پھاڑ نہ دے۔","الألباني: صحيح الإسناد مقطوع",{"u2":"حضرت ابوعبیدہ رضی اللہ عنہ بیان کرتے ہیں: روزہ ڈھال ہے بشرطیکہ روزے دار اس کو پھاڑ نہ دے۔"}],[2236,"سہل بن سعد ساعدی رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"روزہ دار کے لیے جنت میں ایک دروازہ ہے جسے ریان کہا جاتا ہے، روزہ دار کے سوا کوئی اور اس دروازے سے داخل نہیں ہو گا، اور جب آخری روزہ دار دروازہ کے اندر پہنچ جائے گا تو دروازہ بند کر دیا جائے گا، جو وہاں پہنچ جائے گا وہ پئے گا اور جو پئے گا، وہ پھر کبھی پیاسا نہ ہو گا\"۔","الألباني: صحيح",{"u2":"حضرت سہل بن سعد رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’ض’جنت میں روزے داروں کے لیے ایک دروازہ مخصوص ہے جسے ’’ریان‘‘ کہا جاتا ہے۔ اس میں ان کے علاوہ کوئی اور داخل نہ ہوگا۔ جب آخری روزے دار داخل ہو جائے گا تو دروازہ بند کر دیا جائاے گا۔ جو شخص اس میں داخل ہوگا پیے گا اور جس نے ایک دفعہ پی لیا، کبھی پیاسا نہ ہوگا۔‘‘","f2":"(۱) اس روایت میں روزے داروں سے مراد نفلی روزے کے عادی لوگ ہیں کیونکہ فرض روزے دار تو سب مسلمان ہی ہیں۔ (۲) مخصوص دروازہ روزے داروں کو امتیاز عطا کرنے کے لیے ہے، جیسے مہمان خصوصی کے داخلے لیے دروازہ مخصوص کر دیا جاتا ہے۔ (۳) ’’ریان‘‘ معنی ہیں: سیرابی والا دروازہ۔ گویا اس دروازے سے داخل ہوتے ہی سیرابی حاصل ہوگی، چاہے دخول سے یا پینے سے۔ جبکہ باقی دروازوں کے ذریعے داخل ہونے والوں کو جنت کے اندر پانی ملے گا۔ (۴) ’’کبھی پیاسا نہ ہوگا۔‘‘ بعد میں پانی پینا لذت کے لیے ہوگا نہ کہ پیاس دور کرنے کے لیے۔ ان کی یہ فضیلت، اس لیے ہے کہ وہ اللہ تعالیٰ کی رضا کے لیے پیاسے رہے۔ روزے میں پیاس ہی زیادہ محسوس ہوتی ہے۔"}],[2237,"سہل رضی اللہ عنہ کہتے ہیں کہ جنت میں ایک دروازہ ہے جسے ریان کہا جاتا ہے، قیامت کے دن پکار کر کہا جائے گا، روزہ دارو! کہاں ہو؟ کیا تمہیں ریان کی طرف آنے کی رغبت ہے؟ جو شخص اس میں داخل ہو گا، اور (اس کے چشمے (ریان) کا پانی پئے گا) وہ پھر کبھی پیاسا نہ ہو گا، جب وہ داخل ہو جائیں گے تو وہ بند کر دیا جائے گا۔ اس دروازے سے روزہ دار کے سوا کوئی اور داخل نہ ہو گا۔","الألباني: صحيح الإسناد موقوف ق مرفوعا دون جملة الظمأ",{"u2":"حضرت سہل رضی اللہ عنہ بیان کرتے ہیں کہ جنت میں ایک دروازہ ہے جسے ریان کہا جاتا ہے۔ قیامت کے دن اعلان کیا جائے گا: کہاں ہیں روزے دار؟ کیا تمہیں ریان (سیرابی) دروازے کی خواہش ہے؟ جو اس سے جنت میں داخل ہوگا، کبھی پیاس محسوس نہ کرے گا۔ جب روزے دار داخل ہو جائیں گے، وہ دروازہ بند کر دیا جائے گا۔ ان کے علاوہ کوئی اور اس سے داخل نہ ہوگا۔"}],[2238,"ابوہریرہ رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص اللہ کی راہ میں جوڑا دے گا ۱؎ اسے جنت میں بلا کر پکارا جائے گا، اے اللہ کے بندے! یہ تیری نیکی ہے، تو جو شخص نمازی ہو گا وہ صلاۃ کے دروازے سے بلایا جائے گا، اور جو مجاہدین میں سے ہو گا وہ جہاد والے دروازہ سے بلایا جائے گا، اور جو صدقہ دینے والوں میں سے ہو گا وہ صدقہ والے دروازے سے بلایا جائے گا، اور جو روزہ داروں میں سے ہو گا وہ باب ریان سے بلایا جائے گا۔ ابوبکر صدیق رضی اللہ عنہ نے عرض کیا: اللہ کے رسول! کسی کے لیے ضرورت تو ۲؎ نہیں کہ وہ ان سبھی دروازوں سے بلایا جائے، لیکن کیا کوئی ان سبھی دروازوں سے بھی بلایا جائے گا؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہاں اور مجھے امید ہے کہ تم انہیں لوگوں میں سے ہو گے\"۔\n§وضاحت\n۱؎: ـ مثلاً دو دینار، دو گھوڑے، دو کپڑے، دو روٹیاں، دو غلام اور دو لونڈیاں وغیرہ وغیرہ دے گا۔ ۲؎: کیونکہ ایک دروازے سے بلایا جانا جنت میں داخل ہونے کے لیے کافی ہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص اللہ تعالیٰ کے راستے میں ایک جنس کی دو دو چیزیں خرچ کرے گا، اسے جنت میں آواز دی جائے گی: اے اللہ کے بندے! یہ دروازہ بہت اچھا ہے (اس سے داخل ہو) جو شخص نماز سے رغبت رکھنے والا ہوگا، اسے نماز والے دروازے سے آواز دی جائے گی۔ اور جو جہاد کا شائق (جہاد کرنے والا) ہوگا اسے جہاد والے دروازے سے بلایا جائے گا۔ اور جو صدقہ کرنے کا عادی (صدقہ دینے والا) ہوگا۔ اسے صدقے والے دروازے سے بلایا جائے گا۔ اور جو روزے کا رسیا ہوگا، اسے باب ریان سے دعوت دی جائے گی۔‘‘ حضرت ابوبکر صدیق رضی اللہ عنہ نے عرض کیا: اے اللہ کے رسول! کسی شخص کو ضرورت نہیں کہ اسے ہر دروازے سے آوازیں دی جائیں، مگر کیا کسی کو ان سب دروازوں سے بھی بلایا جائے گا؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ہاں اور مجھے امید ہے کہ تم بھی انہی (لوگوں) میں سے ہوگے۔‘‘","f2":"(۱) ’’یہ دروازہ بہت اچھا ہے۔‘‘ گویا اس نیکی کے لیے ایک مخصوص دروازہ ہے جہاں سے اس کے حاملین کو عزت کے ساتھ داخل کیا جائے گا۔ ’’فی سبیل اللہ‘‘ سے مراد ہر اچھی جگہ بھی ہو سکتی ہے اور خاص جہاد بھی کیونکہ قرآن مجید میں فی سبیل اللہ عام طور پر جہاد کے لیے استعمال ہوا ہے۔ (۲) اس حدیث میں جن میں نیکیوں (نماز، جہاد، صدقہ اور روزے) کا ذکر ہے، یہاں نفل مراد ہیں اور نفل بھی کثرت سے حتیٰ کہ وہ شخص اس نیکی میں معروف اور ممتاز ہو، ورنہ کچھ حد تک تو یہ نیکیاں ہر مسلمان میں پائی جاتی ہیں۔ (۳) ’’ہاں‘‘ ظاہر ہے جو شخص مجسمہ نیکی ہے اور نیکی میں ممتاز ہے، اس کا حق ہے کہ اسے ہر طرف سے عزت افزائی کے لیے بلایا جائے۔ لِمِثْلِ ھٰذَا فَلْیَعْمَلِ الْعَامِلُوْنَ اور حضرت ابوبکر صدیق رضی اللہ عنہ سے بڑھ کر امت میں کون اس اعزاز کا مستحق ہوگا؟ آخر وہ ثَانِیَ اثْنَیْنِ ہیں۔ (۴) نیکی کے تمام اعمال ایک آدمی میں یکساں نہیں ہوتے کسی کی طرف رغبت اور رجحان زیادہ ہوتا ہے اور کسی میں کم۔"}],[2239,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں: ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نکلے، اور ہم سب نوجوان تھے۔ ہم (جوانی کے جوش میں) کسی چیز پر قابو نہیں رکھ پاتے تھے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اے نوجوانوں کی جماعت! تم اپنے اوپر شادی کرنے کو لازم پکڑو کیونکہ یہ نظر کو نیچی اور شرمگاہ کو محفوظ رکھنے کا ذریعہ ہے، اور جو نہ کر سکتا ہو (یعنی نان، نفقے کا بوجھ نہ اٹھا سکتا ہو) وہ اپنے اوپر روزہ لازم کر لے کیونکہ یہ اس کے لیے بمنزلہ خصی بنا دینے کے ہے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ فرماتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ (مکہ مکرمہ سے) نکلے تو ہم نوجوان تھے اور ہم شادی وغیرہ کی وسعت نہیں رکھتے تھے۔ آپ نے فرمایا: ’’اے نوجوان لوگو! نکاح کرو کیونکہ نکاح نظر کو نیچا اور شرم گاہ کو محفوظ کرنے والی چیز ہے۔ جو شخص (فقر کی وجہ سے) نکاح کی طاقت نہ رکھے، وہ روزے رکھا کرے کیونکہ روزہ اس کی شہوت کو کچل دے گا۔‘‘","f2":"’’کچل دے گا‘‘ وافر اور اچھا کھانا پینا شہوت میں اضافہ کرتا ہے۔ روزہ نام ہے بھوک وپیاس کا۔ خوراک کی کمی شہوت کو توڑتی ہے، اس لیے غیر شادی شدہ نوجوانوں کے لیے روزہ مفید ہے۔ ویسے بھی روزہ گناہ سے بچاتا ہے۔ گویا روزے دار شخص خصی انسان کی طرح پر سکون رہتا ہے۔ گناہ سے بچنا مطلوب ہے۔ اور بعض صحابہ رضی اللہ عنہم نے اس (گناہ) سے بچنے کے لیے خصی بننے کی اجازت بھی طلب کی تھی، لہٰذا صحیح اور فطری طریق کی رہنمائی کی گئی، یعنی اسلام نے انسانوں کو خصی کرنے سے منع فرمایا مگر ساتھ متبادل بھی مہیا فرمایا۔"}],[2240,"علقمہ سے روایت ہے کہ ابن مسعود (رضی اللہ عنہ)، عثمان (رضی اللہ عنہ) سے عرفات میں ملے، تو وہ انہیں لے کر تنہائی میں چلے گئے اور ان سے باتیں کیں، عثمان رضی اللہ عنہ نے ابن مسعود رضی اللہ عنہ سے کہا: کیا آپ کو کسی دوشیزہ کی خواہش ہے کہ میں آپ کی اس سے شادی کرا دوں؟ تو عبداللہ بن مسعود رضی اللہ عنہ نے علقمہ کو بھی بلا لیا (آ جاؤ کوئی خاص بات نہیں ہے اور جب وہ آ گئے) تو انہوں نے عثمان رضی اللہ عنہ سے حدیث بیان کی کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا ہے: \"جو شخص تم میں سے نان و نفقہ کی طاقت رکھے اسے چاہیئے کہ وہ شادی کر لے کیونکہ یہ چیز نگاہ کو نیچی رکھنے اور شرمگاہ کو محفوظ رکھنے کا بہترین ذریعہ ہے، اور جو طاقت نہ رکھے، تو اسے چاہیئے کہ روزہ رکھے کیونکہ روزہ اس کے لیے «وجاء» ہے\" (یعنی وہ اسے خصی بنا دے گا، اس کی شہوت کو توڑ دے گا)۔","الألباني: صحيح",{"u2":"حضرت علقمہ سے منقول ہے کہ حضرت عبداللہ بن مسعود رضی اللہ عنہ عرفات میں حضرت عثمان رضی اللہ عنہ کو ملے۔ حضرت عثمان انہیں علیحدہ لے گئے۔ حضرت عثمان رضی اللہ عنہ نے حضرت ابن مسعود رضی اللہ عنہ سے کہا: کیا اپ کو خواہش ہے کہ میں کسی نوجوان لڑکی سے آپ کی شادی کر دوں؟ حضرت عبداللہ بن مسعود رضی اللہ عنہ نے حضرت علقمہ کو بھی بلا لیا اور ان سے بیان کیا کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’تم میں سے جو شخص نکاح (کے اخراجات) کی طاقت رکھتا ہو، اسے چاہیے کہ وہ نکاح کرے کیونکہ نکاح نظر کو نیچا اور شرم گاہ کو محفوظ رکھنے کی چیز ہے۔ اور جو طاقت نہ رکھے، وہ روزے رکھے کیونکہ روزہ اس کے لیے ڈھال ہے۔‘‘","f2":"(۱) یہ واقعہ حضرت عثمان رضی اللہ عنہ کے دور خلافت کا ہے۔ چونکہ اس وقت حضرت ابن مسعود رضی اللہ عنہ کو نکاح کی ضرورت نہ تھی، لہٰذا پیش کش قبول نہ فرمائی بلکہ علقمہ کو بلا لیا کیونکہ یہ کوئی راز کی بات نہ تھی اور حدیث بیان فرمائی۔ (۲) نکاح اس شخص کے لیے ضروری ہے جو اس کی ضرورت محسوس کرتا ہے، جو ضرورت محسوس نہ کرتا ہو، اس کے لیے نکاح ضروری نہیں، جیسے بوڑھا شخص۔"}],[2241,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص تم میں سے نان و نفقہ کی طاقت رکھے، تو وہ شادی کر لے اور جو نہ رکھے، وہ اپنے اوپر روزہ لازم کر لے، کیونکہ یہ اس کی شہوت کو توڑ دے گا\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم میں سے جو شخص نکاح (کے اخراجات) کی طاقت رکھے وہ شادی کرے اور جو اتنی وسعت نہ پائے، وہ روزے رکھے کیونکہ روزہ اس کی شہوت کو کچل دے گا۔‘‘"}],[2242,"عبدالرحمٰن بن یزید سے روایت ہے کہ ہم عبداللہ (عبداللہ بن مسعود رضی اللہ عنہ) کے پاس آئے اور ہمارے ساتھ علقمہ، اسود اور ایک جماعت تھی، تو انہوں نے ہم سے ایک حدیث بیان کی، اور میں سمجھتا ہوں کہ انہوں نے لوگوں کے سامنے وہ حدیث میرے ہی لیے بیان کی تھی کیونکہ میں ان لوگوں میں سب سے زیادہ نوعمر تھا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اے نوجوانوں کی جماعت! جو تم میں بیوی کے نان و نفقہ کی طاقت رکھتا ہو وہ نکاح کر لے، کیونکہ یہ نگاہ کو نیچی اور شرمگاہ کو محفوظ رکھنے والی ہے\"۔ علی بن ہاشم (راوی) کہتے ہیں کہ اعمش سے ابراہیم والی روایت کے بارے میں پوچھا گیا، سائل نے پوچھا: «عن إبراهيم عن علقمة عن عبداللہ» اسی کے مثل مروی ہے، اعمش نے کہا: ہاں۔","الألباني: صحيح",{"u2":"حضرت عبدالرحمن بن یزید بیان کرتے ہیں کہ ہم حضرت عبداللہ بن مسعود رضی اللہ عنہ کے پاس گئے۔ ہمارے ساتھ علقمہ، اسود اور کچھ دوسرے لوگ بھی تھے۔ تو حضرت عبداللہ بن مسعود رضی اللہ عنہ نے ہمیں حدیث بیان کی۔ میرا خیال ہے کہ آپ نے ان (ہمارے ساتھ والے) لوگوں کو یہ حدیث میری ہی وجہ سے بیان فرمائی کیونکہ میں ہی ان سب سے کم عمر نوجوان تھا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اے نوجوان لوگو! تم میں سے جو شخص نکاح کرنے کی طاقت رکھے وہ ضرور نکاح کرے کیونکہ نکاح نظر کو زیادہ نیچا اور شرم گاہ کو زیادہ محفوظ کرتا ہے۔‘‘\nراوی علی بن ہاشم کہتے ہیں کہ اعمش سے ’’ابراہیم عن علقمہ عن عبداللہ‘‘ کی روایت کے متعلق سوال کیا گیا کہ کیا یہ اس (عمارہ عن عبدالرحمن) جیسی ہی ہے؟ انہوں نے جواب دیا: ہاں۔"}],[2243,"علقمہ کہتے ہیں: میں ابن مسعود رضی اللہ عنہ کے ساتھ تھا اور وہ عثمان رضی اللہ عنہ کے پاس تھے تو ثمان رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم چند نوجوانوں کے پاس سے گزرے تو آپ نے فرمایا: \"تم میں سے جو شخص وسعت والا ہو وہ شادی کر لے۔ کیونکہ یہ چیز نگاہ کو نیچی اور شرمگاہ کو محفوظ رکھنے والی ہے، اور جو شخص ایسا نہ ہو تو روزہ اس کی شہوت کو کچل دینے کا ذریعہ ہے\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: سند میں مذکور ابومعشر کا نام زیاد بن کلیب ہے، وہ ثقہ ہیں اور وہ ابراہیم (نخعی) کے تلامذہ میں سے ہیں، اور ان سے منصور، مغیرہ اور شعبہ نے روایت کی ہے۔ اور (ایک دوسرے) ابومعشر جو مدنی ہیں ان کا نام نجیح (نجیح بن عبدالرحمٰن سندی) ہے، وہ ضعیف ہیں، اور ضعف کے ساتھ اختلاط کا شکار ہو گئے تھے ان کے یہاں کچھ منکر احادیث بھی ہیں جن میں سے ایک وہ ہے جو انہوں نے محمد بن عمرو سے، انہوں نے ابوسلمہ سے، ابوسلمہ نے ابوہریرہ رضی اللہ عنہ سے، اور ابوہریرہ رضی اللہ عنہ نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی ہے کہ آپ نے فرمایا: \"مشرق و مغرب کے درمیان جو ہے وہ قبلہ ہے\" ۱؎۔ نیز اسی میں سے ایک حدیث وہ ہے جو انہوں نے ہشام بن عروہ سے، ہشام نے اپنے والد عروہ سے، عروہ نے عائشہ رضی اللہ عنہا سے، اور عائشہ رضی اللہ عنہا نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"گوشت چھری سے نہ کاٹو بلکہ نوچ نوچ کر کھاؤ\" ۲؎۔\n§وضاحت\n۱؎: أخرجه الترمذي :(342 ) وابن ماجه :(1011 ) :(تحفة الأشراف 15124 ) :(حافظ ابن حجر النکت الظراف میں لکھتے ہیں کہ خلیلی نے ارشاد میں ایک دوسرے طریقے سے اسے بسند ابو معشر عن ہشام عن ابیہ عن عائشہ روایت کیا ہے، اس حدیث میں ابو معشر نجیح بن عبدالرحمٰن سندی ہیں، جو ضعیف راوی ہیں، اسی لیے حافظ ابن حجر نے ان کے بارے میں کہا: ضعیف أسن واختلط یعنی ضعیف ہیں، عمر دراز ہوئے اور اختلاط کا شکار ہوئے، اسی وجہ سے امام نسائی نے باب میں موجود ابو معشر زیاد بن کلیب کی توثیق کے بعد اسی کنیت کے دوسرے راوی یعنی نجیح بن عبدالرحمٰن سندی کا تذکرہ ان کی منکر احادیث کے ساتھ دیا تاکہ دونوں میں تمیز ہو جائے، اور یہ امام نسائی کی کتاب کی خوبی ہے کہ وہ اس طرح کے افادات رقم فرماتے ہیں، لیکن مذکور حدیث دوسرے طرق کی وجہ سے صحیح ہے، تفصیل کے ملاحظہ ہو: الإرواء: ۲۹۲ ) ۲؎: حدیث «لأستغفرن لك ما لم أنه عنك» اس کی تخریج ابوداؤد اور بیہقی نے سنن کبری میں کی ہے، اور شیخ البانی نے اسے ضعیف الجامع :(۶۲۵۶ ) میں داخل کیا ہے۔","الألباني: صحيح الإسناد",{"u2":"حضرت علقمہ بیان کرتے ہیں کہ میں حضرت ابن مسعود رضی اللہ عنہ کے ساتھ تھا جبکہ وہ حضرت عثمان رضی اللہ عنہ کے پاس تھے۔ حضرت عثمان رضی اللہ عنہ نے بیان کیا، رسول اللہ صلی اللہ علیہ وسلم کچھ نوجوانوں کے پاس تشریف لائے اور فرمایا: ’’تم میں سے جومالدار ہو، وہ شادی کرے کیونکہ یہ چیز اس کی نظر کو زیادہ نیچا اور شرم گاہ کو زیادہ محفوظ کر دے گی اور جو مالدار نہ ہو تو اس کی شہوت کا علاج روزہ ہے۔‘‘\nامام ابوعبدالرحمن (نسائی) رحمہ اللہ فرماتے ہیں کہ اس حدیث میں جو ابو معشر راوی ہے، اس کا نام زیاد بن کلیب ہے، وہ ثقہ ہے اور ابراہیم نخعی کا مصاحب (ساتھی) ہے۔ اس سے منصور، مغیرہ اور شعبہ نے روایت کیا ہے ایک ابو معشر مدینی ہے، اس کا نام نجیح ہے اور وہ ضعیف ہے۔ ضعیف ہونے کے ساتھ وہ اختلاط کا بھی شکار ہوگیا تھا۔ وہ منکر حدیثوں میں سے ایک وہ ہے جو اس نے محمد بن عمرو سے بیان کی، انہوں نے ابو سلمہ سے اور انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’مشرق اور مغرب کے درمیان قبلہ ہے۔‘‘ اور ایک وہ ہے جو اس نے ہشام بن عروہ سے روایت کی، انہوں نے اپنے باپ (عروہ) سے اور انہوں نے حضرت عائشہ رضی اللہ عنہا سے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’گوشت کو چھری سے مت کاٹو، (بلکہ) اسے دانتوں سے نوچ کر کھاؤ۔‘‘"}],[2244,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے اللہ کی راہ (یعنی جہاد یا اس کے سفر) میں ایک دن کا روزہ رکھا، اللہ تعالی اسے اس دن کے بدلے جہنم سے ستر سال کی دوری پر کر دے گا\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص اللہ کی راہ میں ایک دن روزہ رکھے، اللہ تعالیٰ اس ایک دن کی بدولت اس کے چہرے کو آگ سے ستر سال کے فاصلے تک دور کر دے گا۔‘‘","f2":"حدیث میں [فی سبیل اللہ] کے الفاظ ہیں ہر اس نیک عمل پر اس کا اطلاق ہوتا ہے جو خالصتاً اللہ تعالیٰ کے لیے کیا جائے، چونکہ قرآن مجید میں {فی سبیل اللہ} سے مراد عموماً جہاد ہوتا ہے، لہٰذا ترجمہ اس طرح بھی ہو سکتا ہے: ’’جو شخص جہاد کے دوران میں روزہ رکھے۔‘‘ نیز (فی سبیل اللہ) ’’اللہ تعالیٰ کے راستے میں‘‘ کے تحت طلب علم یا حج وعمرہ وغیرہ کے سفر میں روزہ رکھنا بھی آجاتا ہے۔ واللہ اعلم"}],[2245,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے اللہ کی راہ میں ایک دن روزہ رکھا اللہ تعالی اس دن کے بدلے اس کے اور جہنم کی آگ کے درمیان ستر سال کی دوری کر دے گا\"۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص اللہ تعالیٰ کی خوشنودی کے لیے ایک دن روزہ رکھے، اللہ تعالیٰ اس دن کی وجہ سے اس کے اور آگ کے درمیان ستر سال کا فاصلہ فرما دے گا۔‘‘"}],[2246,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے اللہ کی راہ میں ایک دن روزہ رکھا اللہ عزوجل اسے جہنم سے ستر سال کی دوری پر کر دے گا\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص اللہ تعالیٰ کے راستے میں ایک دن روزہ رکھے، اللہ تعالیٰ اس کے چہرے کو آگ سے ستر سال کے فاصلے تک دور فرما دے گا۔‘‘"}],[2247,"ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس نے اللہ کی راہ میں ایک دن روزہ رکھا اللہ تعالی اسے جہنم سے ستر سال کی دوری پر کر دے گا\"۔","الألباني: صحيح",{"u2":"حضرت ابو سعید رضی اللہ عنہ سے منقول ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جو آدمی اللہ تعالیٰ کے راستے میں ایک دن روزہ رکھے، اللہ تعالیٰ اس کے چہرے کو جہنم سے ستر سال کے فاصلے تک دور فرما دے گا۔‘‘"}],[2248,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"جس شخص نے بھی اللہ عزوجل کی راہ میں ایک دن کا روزہ رکھا، اللہ عزوجل اس دن کے بدلے اسے جہنم سے ستر سال کی دوری پر کر دے گا\"۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ سے روایت ہے، انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’جو شخص اللہ تعالیٰ عزوجل کے راستے میں ایک دن روزہ رکھے، اللہ تعالیٰ اس ایک دن (کے روزے) کی وجہ سے اس کے چہرے کو آگ سے ستر سال کے فاصلے تک دور فرما دے گا۔‘‘"}],[2249,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے اللہ کی راہ میں ایک دن روزہ رکھا، اللہ اسے جہنم سے ستر سال کی دوری پر کر دے گا\"۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص اللہ تعالیٰ کے راستے میں ایک دن روزہ رکھے، اللہ تعالیٰ اس کو آگ سے ستر سال کے فاصلے تک دور فرما دے گا۔‘‘"}],[2250,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"جو جس نے اللہ کی راہ میں ایک دن روزہ رکھے گا اللہ تعالی اسے آگ سے ستر سال کی دوری پر کر دے گا\"۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’جو شخص اللہ تبارک و تعالیٰ کے راستے میں ایک دن روزہ رکھے، اللہ تعالیٰ اس کے چہرے کو آگ سے ستر سال کے فاصلے تک دور کر دے گا۔‘‘"}],[2251,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو بندہ بھی اللہ کی راہ میں کسی دن کا روزہ رکھے گا اللہ تعالی اس دن کے بدلے اسے جہنم کی آگ سے ستر سال دوری پر کر دے گا\"۔","الألباني: صحيح",{"u2":"حضرت ابوسعید خدری رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو بندہ اللہ تعالیٰ کے راستے میں ایک دن روزہ رکھے، اللہ تعالیٰ اس ایک دن کی وجہ سے آگ کو اس کے چہرے سے ستر سال کے فاصلے تک دور فرما دے گا۔‘‘"}],[2252,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو اللہ کی راہ میں ایک دن کا روزہ رکھے گا، اللہ تعالی اس ایک دن کے بدلے اس سے جہنم کی گرمی کو ستر سال کی دوری پر کر دے گا\"۔","الألباني: صحيح",{"u2":"حضرت ابو سعیید خدری رضی اللہ عنہ سے مروی ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص ایک دن اللہ تعالیٰ کے راستے میں روزہ رکھے گا، اللہ تعالیٰ اس دن کی برکت سے جہنم کی تپش کو اس کے چہرے سے ستر سال کے فاصلے تک دور کر دے گا۔‘‘"}],[2253,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو اللہ کی راہ میں ایک دن روزہ رکھے گا اللہ تعالی اس دن کے بدلے اس سے جہنم کی آگ کو ستر سال دور کر دے گا\"۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص نے اللہ تعالیٰ کے راستے میں ایک دن روزہ رکھا، اللہ تعالیٰ اس دن کی بنا پر آگ کو اس کے چہرے سے ستر سال کے فاصلے تک دور رکھے گا۔‘‘"}],[2254,"عقبہ بن عامر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو اللہ کی راہ میں ایک دن کا روزہ رکھے گا اللہ تعالی اس سے جہنم کو سو سال کی مسافت کی دوری پر کر دے گا\"۔","الألباني: حسن",{"u2":"حضرت عقبہ بن عامر رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص اللہ عزوجل کے راستے میں ایک دن روزہ رکھے، اللہ تعالیٰ جہنم کو اس سے سو سال کی مسافت تک دور فرما دے گا۔‘‘","f2":"(۱) ’’سو سال‘‘ اس سے ماقبل تمام روایات میں ستر سال کا ذکر ہے۔ معلوم ہوتا ہے دونوں اعداد سے معین عدد مراد نہیں بلکہ کثرت مراد ہے، یعنی بہت دور فرما دے گا۔ ستر اور سو کا عدد عرف میں کثرت کے لیے عام بولا جاتا ہے۔ ان دو عددوں کو خاص کرنے کی وجہ یہ ہو سکتی ہے کہ انسانی عمر عموماً ستر کے قریب ہوتی ہے، بہت کم ہیں جو سو سال تک پہنچیں یا اس سے تجاوز کریں۔ بعض اہل علم نے یہ بھی کہا ہے کہ ممکن ہے پہلے اجر کم تھا، پھر اللہ تعالیٰ نے اپنے فضل سے اضافہ فرما دیا، یہ بھی کوئی بعید بات نہیں۔ (۲) اوپر والی روایات میں سال کو ’’خریف‘‘ کہا گیا ہے کیونکہ سال میں موسم خریف ایک ہی ہے لہٰذا کوئی فرق نہیں پڑتا۔ اس موسم کو خاص کرنے کی وجہ یہ ہے کہ یہ عرب میں فصلوں اور پھلوں کے پکنے، کاٹنے اور توڑنے کا موسم تھا، اس لیے عرب لوگ سن ہجری کے رواج سے پہلے تاریخ میں خریف ہی کے حوالے دیا کرتے تھے۔"}],[2255,"کعب بن عاصم رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"سفر میں روزہ رکھنا نیکی نہیں ہے\"۔","الألباني: صحيح",{"u2":"حضرت کعب بن عاصم رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’سفر میں روزہ رکھنا نیکی نہیں۔‘‘"}],[2256,"(تابعی) سعید بن مسیب کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سفر میں روزہ رکھنا نیکی نہیں ہے\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: یہ غلط ہے، صحیح روایت وہ ہے جو پہلے گزری ہے۔ ہم نہیں جانتے کہ کسی نے اس پر ابن محمد بن کثیر کی متابعت کی ہے۔","الألباني: صحيح لغيره",{"u2":"حضرت سعید بن مسیب سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سفر میں روزہ رکھنا نیکی نہیں۔‘‘\nامام ابوعبدالرحمن (نسائی) رحمہ اللہ فرماتے ہیں کہ یہ غلط ہے، درست اس سے پہلی (سند) ہے۔ ہمارے علم میں نہیں ہے کہ اس پر کسی نے ابن کثیر کی متابعت کی ہو۔","f2":"(۱) اس روایت میں سند کی غلطی ہے، یعنی روایت کا سعید بن مسیب سے مرسلاً مروی ہونا خطا ہے۔ درست صحابی کے ذکر کے ساتھ ہے۔ (۲)یہ روایت مختصر ہے، لہٰذا غلط فہمی ہو سکتی ہے کہ شاید سفر میں روزہ رکھنا اچھا نہیں، حالانکہ رسول اللہ صلی اللہ علیہ وسلم خود سفر میں روزے رکھتے رہے ہیں۔ صحابہ کرام رضی اللہ عنہم بھی آپ کے سامنے سفر میں روزے رکھتے تھے۔ دراصل اس روایت کا ایک خاص محل ہے اور وہ یہ کہ جب روزہ مسافر کے لیے انتہائی مشقت کا باعث ہو اور روزے دار دوسرے کے لیے بوجھ اور مصیبت بن جائے، وہ اسے اور اس کے کام کاج کو سنبھالتے پھریں تو ایسا روزہ واقعتا نیکی نہیں۔ لیکن اگر مسافر اسانی سمجھتا ہو اور روزہ دار برداشت کر سکے، اپنا کام خود کرے، دوسرے کے لیے پریشانی اور بوجھ کا سبب نہ بنے تو ایسے شخص کے لیے سفر میں روزہ رکھنا نہ صرف جائز بلکہ افضل ہے۔ آئندہ باب وحدیث میں اس کی طرف اشارہ ہے۔ غرض جو صورت بھی انسان کے لیے باعث سہولت اور آرام دہ ہو، اسے ہی اپنانا افضل ہے۔ مزید تفصیل کے لیے دیکھئے۔ (ذخیرۃ العقبی شرح سنن النسائ: ۲۱/ ۱۳۴-۱۴۱)"}],[2257,"جابر بن عبداللہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کچھ لوگوں کو ایک شخص کو گھیرے ہوئے دیکھا، تو آپ صلی اللہ علیہ وسلم نے پوچھا:(کیا بات ہے؟ کیوں لوگ اکٹھا ہیں؟) تو لوگوں نے کہا: ایک شخص ہے جسے روزہ نے نڈھال کر دیا ہے، تو آپ نے فرمایا: \"سفر میں روزہ رکھنا نیکی و تقوی نہیں ہے\"۔","الألباني: صحيح",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے لوگوں کو ایک شخص کے اردگرد جمع دیکھا تو پوچھا (کیا بات ہے؟) لوگوں نے کہا: ایک آدمی ہے جسے روزے کی وجہ سے سخت تکلیف ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سفر کے دوران میں (اس حد تک پہنچانے والا) روزہ رکھنا نیکی نہیں۔‘‘"}],[2258,"جابر بن عبداللہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ایک ایسے شخص کے پاس سے گزرے جو ایک درخت کے سایہ میں بیٹھا ہوا تھا اور اس پر پانی چھڑکا جا رہا تھا۔ آپ صلی اللہ علیہ وسلم نے پوچھا: \"تمہارے اس ساتھی کو کیا ہو گیا ہے؟\" لوگوں نے کہا: اللہ کے رسول! یہ روزہ دار ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہ نیکی و تقوی نہیں ہے کہ تم سفر میں روزہ رکھو، اللہ نے جو رخصت تمہیں دی ہے اسے قبول کرو\"۔","الألباني: صحيح",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ایک آدمی کے پاس سے گزرے جسے ایک درخت کے سائے تلے لٹایا گیا تھا اور اس (کے منہ) پر پانی کے چھینٹے مارے جا رہے تھے۔ آپ نے فرمایا: ’’تمہارے اس ساتھی کو کیا ہوا ہے؟‘‘ لوگوں نے کہا: اے اللہ کے رسول! اس نے روزہ رکھا ہے۔ آپ نے فرمایا: ’’یہ نیکی نہیں کہ تم سفر کے دوران میں (اس طرح کے) روزے رکھو، بلکہ جو اللہ تعالیٰ نے تمہیں رخصت دی ہے، اس سے فائدہ اٹھاؤ اور اسے قبول کرو۔‘‘"}],[2259,"یحیی کہتے ہیں مجھے محمد بن عبدالرحمٰن نے خبر دی، وہ کہتے ہیں: مجھ سے جس شخص نے جابر رضی اللہ عنہ سے سنا ہے اسی طرح بیان کیا ہے۔","",{"u2":"محمد بن عبدالرحمن بیان کرتے ہیں کہ مجھے ایک شخص نے ایسی ہی حدیث سنائی جس نے یہ حدیث حضرت جابر رضی اللہ عنہ سے سنی تھی۔"}],[2260,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سفر میں روزہ رکھنا نیکی نہیں ہے، اللہ عزوجل کی دی گئی رخصت (اجازت) کو لازم پکڑو اور اسے قبول کرو\"۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سفر کے دوران میں (اس قسم کا) روزہ رکھنا نیکی نہیں، بلکہ اللہ تعالیٰ کی رخصت سے فائدہ اٹھاؤ اور اسے قبول کرو۔‘‘"}],[2261,"جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سفر میں روزہ رکھنا نیکی نہیں ہے\"۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سفر کے دوران میں (مشقت والا) روزہ رکھنا نیکی نہیں۔‘‘"}],[2262,"محمد بن عبدالرحمٰن نے محمد بن عمرو بن حسن سے روایت کی، اور انہوں نے جابر بن عبداللہ رضی اللہ عنہما سے وہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص کو دیکھا کہ سفر میں اس کے اوپر سایہ کیا گیا ہے، تو آپ نے فرمایا: \"سفر میں روزہ رکھنا نیکی نہیں ہے\"۔\n§وضاحت\n۱؎: اوپر والی روایت میں مذکور «عن رجل» میں رجل سے مراد یہی محمد بن عمرو بن حسن ہیں۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک آدمی کو دیکھا جس پر سفر کے دوران میں سایہ کیا گیا تھا۔ آپ نے فرمایا: ’’سفر کے دوران (اس قسم کا) روزہ رکھنا نیکی نہیں۔‘‘","f2":"’’اس قسم کا‘‘ روزہ جس سے دوسرے لوگ بھی مصیبت میں پڑے رہیں۔ کوئی کپڑا اتارے، کوئی چھینٹے مارے وغیرہ۔"}],[2263,"جابر بن عبداللہ رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم فتح مکہ کے سال رمضان میں مکہ کے لیے نکلے، تو آپ نے روزہ رکھا، یہاں تک کہ آپ کراع الغمیم پر پہنچے، تو لوگوں نے بھی روزہ رکھ لیا، تو آپ کو خبر ملی کہ لوگوں پر روزہ دشوار ہو گیا ہے، تو آپ نے عصر کے بعد پانی سے بھرا ہوا پیالہ منگایا، پھر پانی پیا، اور لوگ دیکھ رہے تھے، تو (آپ کو دیکھ کر) بعض لوگوں نے روزہ توڑ دیا، اور بعض رکھے رہ گئے، آپ کو یہ بات پہنچی کہ کچھ لوگ روزہ رکھے ہوئے ہیں، تو آپ صلی اللہ علیہ وسلم نے فرمایا ـ: \"یہی لوگ نافرمان ہیں\"۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم فتح مکہ کے سال رمضان المبارک میں مکے کی طرف چلے اور روزے رکھتے رہے حتیٰ کہ کراع غمیم پہنچے۔ لوگوں نے روزہ رکھا ہوا تھا۔ آپ کو یہ بات پہنچی کہ لوگوں کے لیے روزہ نبھانا مشکل ہوگیا ہے۔ یہ عصر کے بعد کی بات ہے۔ آپ نے پانی کا پیالہ منگوایا اور پیا۔ لوگ دیکھ رہے تھے۔ کچھ لوگوں نے تو روزہ کھول لیا لیکن کچھ لوگوں نے روزہ قائم رکھا۔ آپ کو یہ بات پہنچی کہ کچھ لوگ ابھی تک روزے سے ہیں۔ تو آپ نے فرمایا: ’’یہ لوگ نافرمان ہیں۔‘‘","f2":"(۱)’’یہ لوگ نافرمان ہیں۔‘‘ اللہ کے رسول صلی اللہ علیہ وسلم نے محسوس فرمایا کہ آج روزہ مشقت والا ہے اور مشقت والا روزہ سفر میں جائز نہیں، لہٰذا آپ نے افطار فرما لیا۔ اگرچہ آپ کو مشقت نہ تھی، تاکہ آپ کی وجہ سے کسی کو مشقت برداشت نہ کرنی پڑے اسی علت کے پیش نظر ان لوگوں کو بھی افطار کر لینا چاہیے تھا، جنہیں زیادہ مشقت نہ تھی، تاکہ ان کی وجہ سے دوسروں کو افطار میں جھجک محسوس نہ ہو۔ جس طرح اپنی مشقت کا لحاظ ضروری ہے، اسی طرح دوسروں کی مشقت کا لحاظ بھی ضروری ہے۔ س بنا پر آپ نے افطار فرمایا۔ جن حضرات نے اس اصول کا لحاظ نہ رکھا بلکہ آپ کے علانیہ افطار کے باوجود فطار نہ کیا، انہوں نے فرمانی کی۔ (۲)اس حدیث سے یہ بھی معلوم ہوا کہ جس طرح آپ کا فرمان واجب الاتباع ہے، اسی طرح آپ کا وہ فعل جو آپ اس لیے کریں کہ لوگ بھی اس کی اقتدا کریں، بعینہٖ واجب الاتباع ہے ورنہ یہ نافرمانی ہوگی۔ (۳)رسول اللہ صلی اللہ علیہ وسلم سے بڑھ کر نیک اور متقی بننا زبردست غلطی ہے۔"}],[2264,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس مرالظہران (مکہ و مدینہ کے درمیان ایک مقام کا نام ہے) میں کھانا لایا گیا، تو آپ نے ابوبکر و عمر رضی اللہ عنہما سے فرمایا: \"تم دونوں قریب آ جاؤ اور کھاؤ\"، انہوں نے عرض کیا: ہم روزہ سے ہیں، تو آپ نے لوگوں سے کہا: \"اپنے دونوں ساتھیوں کے کجاوے کس دو، اور اپنے دونوں ساتھیوں کے کام کر دو\" ۱؎۔\n§وضاحت\n۱؎: اس سے سفر میں روزہ رکھنے کا جواز ثابت ہوا اور یہ بھی ثابت ہوا کہ روزہ دار کو سہولت پہنچائی جائے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم کے پاس مَرُّ الظَّہران مقام میں کھانا لایا گیا۔ آپ نے حضرت ابوبکر اور حضرت عمر رضی اللہ عنہ سے فرمایا: ’’قریب آؤ اور کھاؤ۔‘‘ ان دونوں نے کہا: ہم روزے سے ہیں۔ آپ نے دیگر صحابہ رضی اللہ عنہم سے فرمایا: ’’اپنے ان دو محترم ساتھیوں کے لیے سواریاں تم تیار کرنا اور ان کے دوسرے کام بھی تم کرنا۔‘‘","f2":"مذکورہ حدیث کو محقق کتاب نے سنداً ضعیف قرار دیا ہے جبکہ دیگر محققین نے اسے صحیح قرار دیا ہے۔ علاوہ ازیں شیخ البانی رحمہ اللہ نے اس پر سیر حاصل بحث کی ہے، جس سے تصحیح حدیث والی رائے ہی اقرب الی الصواب معلوم ہوتی ہے۔ واللہ اعلم، نیز شیخ البانی رحمہ اللہ نے اگلی دونوں روایتوں کو بھی صحیح قرار دیا ہے۔ تفصیل کے لیے دیکھئے: (ذخیرۃ العقبیٰ شرح سنن النسائی: ۲۱/ ۱۶۱۔۱۶۳، وسلسلۃ الاحادیث الصحیحۃ: ۱/ ۱۶۸۔ ۱۷۰، رقم: ۸۵ و صحیح سنن النسائی: ۲/ ۱۳۲، ۱۳۳، رقم: ۲۲۶۳-۲۲۶۵)"}],[2265,"ابوسلمہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم دوپہر کا کھانا کھا رہے تھے، آپ کے ساتھ ابوبکر و عمر رضی اللہ عنہما بھی تھے کہ اسی دوران آپ نے فرمایا:\"آؤ کھانا کھاؤ\" یہ روایت مرسل ہے۔","الألباني: صحيح لغيره",{"u2":"حضرت ابو سلمہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم ایک دفعہ مَرُّ الظَّہران مقام پر کھانا کھا رہے تھے۔ آپ کے ساتھ حضرت ابوبکر و عمر رضی اللہ عنہ تھے۔ آپ نے فرمایا: ’’تم بھی کھانا کھاؤ۔‘‘ یہ روایت مرسل ہے۔"}],[2266,"ابوسلمہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم ابوبکر و عمر رضی اللہ عنہما مرالظہران میں تھے یہ روایت مرسل ہے۔","الألباني: صحيح لغيره",{"u2":"حضرت ابو سلمہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم اور حضرت ابوبکر و عمر رضی اللہ عنہ مَرُّ الظَّہران مقام پر تھے۔ یہ روایت بھی مرسل ہے۔"}],[2267,"عمرو بن امیہ ضمری رضی اللہ عنہ کہتے ہیں کہ میں ایک سفر سے رسول اللہ صلی اللہ علیہ وسلم کے پاس پہنچا، آپ نے فرمایا: \"اے ابوامیہ! (بیٹھو) صبح کے کھانے کا انتظار کر لو\"، میں نے عرض کیا: میں روزے سے ہوں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"آؤ میرے قریب آ جاؤ، میں تمہیں مسافر سے متعلق بتاتا ہوں، اللہ عزوجل نے اس سے روزے معاف کر دیا ہے اور آدھی نماز بھی\" ۱؎۔\n§وضاحت\n۱؎: یعنی سفر کی حالت میں مسافر پر روزہ رکھنا ضروری نہیں، قرار دیا، بلکہ اسے اختیار دیا ہے کہ وہ چاہے تو روزہ رکھ لے :(اگر اس کی طاقت پاتا ہے تو ) یا چاہے تو ان کے بدلہ اتنے ہی روزے دوسرے دنوں میں رکھ لے، لیکن مسافر سے روزہ بالکل معاف نہیں ہے، ہاں چار رکعت والی نماز میں سے دو رکعت کی چھوٹ دی ہے، چاہے تو چار رکعت پڑھے اور چاہے تو دو رکعت، اور پھر اس کی قضاء نہیں ہے۔","الألباني: صحيح الإسناد",{"u2":"حضرت عمرو بن امیہ ضمری رضی اللہ عنہ بیان کرتے ہیں کہ میں ایک سفر سے واپس رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوا۔ آپ نے فرمایا: ’’اے ابو امیہ! کھانا آرہا ہے۔ ذرا ٹھہرو۔‘‘ میں نے عرض کیا: میں روزے سے ہوں۔ آپ نے فرمایا: ’’ادھر آؤ۔ میرے قریب ہوتا کہ میں تمہیں بتاؤں کہ اللہ تعالیٰ نے مسافر سے روزہ اور نصف نماز معاف کر دی ہے۔‘‘","f2":"(۱)رسول اللہ صلی اللہ علیہ وسلم کا مطلب یہ ہے کہ اللہ تعالیٰ نے مسافر سے فرض روزہ بھی وقتی طور پر معاف فرما دیا ہے، نفل روزے کی تو بات ہی کیا ہے، لہٰذا تو کھانا کھا سکتا ہے۔ یہ مطلب نہیں کہ سفر میں نفل روزہ نہیں رکھنا چاہیے۔ (۲)’’روزہ اور نصف نماز۔‘‘ مگر دونوں میں فرق ہے۔ فرض روزہ تو بعد میں رکھنا پڑے گا، اور یہ متفقہ مسئلہ ہے۔ مگر نصف نماز جو معاف ہے، وہ مستقل معاف ہے، یعنی اس کی قضا ادا نہیں کرنی پڑے گی۔ (۳) ’’معاف ہے۔‘‘ لیکن اس کا یہ مطلب نہیں کہ مسافر روزہ رکھ نہیں سکتا یا نماز پوری نہیں پڑھ سکتا بلکہ یہ اس کی مرضی پر موقوف ہے۔ یہ معاف رخصت کے معنی میں ہے۔ (۴) ہر نماز نصف معاف نہیں بلکہ صرف وہ نماز جو چار رکعت والی ہے۔ ظہر، عصر اور عشاء باقی دو نمازیں پوری پڑھنی ہوں گی۔"}],[2268,"عمرو بن امیہ ضمری رضی اللہ عنہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس پہنچا تو آپ نے مجھ سے فرمایا: \"اے امیہ! تم کیوں نہیں دوپہر کے کھانے کا انتظار کر لیتے\"، میں نے عرض کیا: میں روزے سے ہوں۔ تو آپ نے فرمایا: (میرے قریب) آ جاؤ۔ \"میں مسافر کے سلسلے میں تمہیں (شریعت کا حکم) بتاتا ہوں: اللہ تعالی نے اس سے روزہ کی چھوٹ دے دی ہے، اور نماز آدھی کر دی ہے\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت عمرو بن امیہ ضمری رضی اللہ عنہ فرماتے ہیں کہ میں (سفر سے واپسی پر) رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا۔ مجھ سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اے ابو امیہ! کیا تو کھانا آنے کا انتظار نہیں کرے گا؟‘‘ میں نے کہا: میرا تو روزہ ہے۔ آپ نے فرمایا: ’’ادھر آؤ، میں تمہیں بتاؤں کہ اللہ تعالیٰ نے مسافر سے روزہ اور نصف نماز معاف کر دی ہے۔‘‘"}],[2269,"ابوامیہ ضمری رضی اللہ عنہ کہتے ہیں کہ میں ایک سفر سے رسول اللہ صلی اللہ علیہ وسلم کے پاس پہنچا، تو میں نے آپ کو سلام کیا، پھر جب میں نکلنے لگا تو آپ نے فرمایا:\"اے ابوامیہ! دوپہر کے کھانے کا انتظار کر لو\"۔ میں نے عرض کیا: اللہ کے نبی! میں روزے سے ہوں، آپ نے فرمایا: \"آؤ میں تمہیں مسافر کے بارے میں بتاتا ہوں، اللہ تعالی نے اس سے روزے کی چھوٹ دے دی ہے، اور نماز آدھی کر دی ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابو امیہ ضمری سے مروی ہے، وہ کہتے ہیں کہ میں ایک سفر سے رسول اللہ صلی اللہ علیہ وسلم کے پاس واپس آیا۔ میں نے آپ کو سلام عرض کیا۔ جب میں اٹھنے لگا تو آپ نے فرمایا: ’’اے ابو امیہ! کھانا آنے تک ٹھہرو۔‘‘ میں نے کہا: اے اللہ کے نبی! میں تو روزے سے ہوں۔ آپ نے فرمایا۔ ’’ادھر آؤ، میں تمہیں بتاؤ کہ اللہ تعالیٰ نے مسافر سے روزہ اور نصف نماز معاف کر دی ہے۔‘‘"}],[2270,"ابوالمہاجر کہتے ہیں کہ مجھ سے ابوامیہ یعنی ضمری رضی اللہ عنہ نے بیان کیا ہے کہ وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے، پھر راوی نے اسی طرح کی روایت ذکر کی۔","",{"u2":"حضرت ابو امیہ ضمری سے روایت ہے کہ میں نبی صلی اللہ علیہ وسلم کے پاس آیا۔ اور مذکورہ بالا کی مانند حدیث بیان کی۔"}],[2271,"ابوقلابہ جرمی کا بیان ہے کہ ان سے ابوامیہ ضمری رضی اللہ عنہ نے بیان کیا کہ وہ ایک سفر سے رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، آپ نے ان سے کہا:\"ابوامیہ! دوپہر کے کھانے کا انتظار کر لو\" (کھا کر چلے جانا) میں نے کہا: میں روزے سے ہوں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"قریب آؤ، میں مسافر کے بارے میں تمہیں بتاتا ہوں: اللہ نے اس سے روزے کی چھوٹ دے دی ہے، اور نماز آدھی کر دی ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابو امیہ ضمری رضی اللہ عنہ بیان کرتے ہیں کہ میں ایک سفر سے رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوا۔ آپ نے فرمایا: ’’اے ابوامیہ! ٹھہرو کھانا آرہا ہے۔‘‘ میں نے عرض کیا: میرا تو روزہ ہے۔ آپ نے فرمایا: ’’ادھر آؤ، میں تمہیں بتاؤ کہ اللہ تعالیٰ نے مسافر کو روزہ اور نصف نماز معاف کر دی ہے۔‘‘"}],[2272,"ابوامیہ ضمری رضی اللہ عنہ کہتے ہیں کہ وہ سفر سے رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور وہ روزے سے تھے، تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے کہا:\"(تم جانا چاہتے ہو) کیا، تم دوپہر کے کھانے کا انتظار نہیں کرو گے\"، انہوں نے کہا: میں روزے سے ہوں، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"آؤ میں روزے سے متعلق تمہیں بتاتا ہوں۔ اللہ عزوجل نے مسافر کو روزے کی چھوٹ دی ہے اور نماز آدھی کر دی ہے\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابوامیہ ضمری رضی اللہ عنہ نے بتایا کہ میں ایک سفر سے (واپسی پر) رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوا۔ میں روزے سے تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا: ’’تم کھانے تک نہیں ٹھہرو گے؟‘‘ میں نے عرض کیا: میں تو روزے سے ہوں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ادھر آؤ، میں تمہیں بتاؤں کہ اللہ تعالیٰ نے مسافر کو روزہ اور آدھی نماز معاف کر دی ہے۔‘‘"}],[2273,"ابوامیہ رضی اللہ عنہ کہتے ہیں کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس سفر سے آئے، آگے راوی نے پوری روایت اسی طرح ذکر کی۔","",{"u2":"حضرت ابو امیہ رضی اللہ عنہ نے خبر دی کہ میں سفر سے واپس نبی صلی اللہ علیہ وسلم کے پاس آیا۔ مذکورہ بالا روایت کی مانند۔"}],[2274,"انس (قشیری) رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی نے مسافر سے آدھی نماز اور روزے کی چھوٹ دی ہے اور، حاملہ اور دودھ پلانے والی عورت کو بھی\" (روزے کی چھوٹ دی ہے)۔","الألباني: حسن",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ تعالیٰ نے مسافر کو آدھی نماز اور روزہ معاف کر دیا ہے۔ اور (اسی طرح) حاملہ اور دودھ پلانے والی عورت کو بھی۔‘‘","f2":"(۱)امام نسائی رحمہ اللہ نے مذکورہ حدیث انس کو بھی مذکورہ باب کے تحت ہی ذکر فرما دیا، حالانکہ اس پر الگ سے عنوان قائم کرنا زیادہ مناسب تھا جیسا کہ دیگر صحابہ کرام رضی اللہ عنہم سے مروی احادیث کے اسنادی اختلافات کے بیان میں کرتے ہیں۔ دیکھئے: (ذخیرۃ العقبیٰ شرح سنن النسائی: ۲۱/ ۱۷۲، ۱۷۳) (۲)حاملہ اور دودھ پلانے والی عورت کو اگر بچے کے نقصان کا اندیشہ ہو تو وہ روزہ چھوڑ سکتی ہے، بعد میں قضا ادا کرے یا بعض نے کہا ہے کہ فدیہ دے دے، یہی کافی ہے۔ بعض کہتے ہیں قضا کی ضرورت ہے نہ فدیہ کی، گویا کہ حقیقتاً معافی ہے، مگر جمہور اہل علم کے نزدیک پہلی بات ہی صحیح ہے کہ بعد میں قضا ادا کرنی ہوگی۔"}],[2275,"ایوب قبیلہ قشیر کے ایک شیخ سے، اور وہ قشیری اپنے چچا ۱؎ سے روایت کرتے ہیں، (ایوب کہتے ہیں) ہم سے حدیث بیان کی گئی، پھر ہم نے انہیں (شیخ قشیری کو) ان کے اونٹوں میں پایا، تو ان سے ابوقلابہ نے کہا: آپ ان سے (ایوب سے) حدیث بیان کیجئے تو (قشیری) شیخ نے کہا: مجھ سے میرے چچا نے بیان کیا کہ وہ اپنے اونٹوں میں گئے، اور نبی اکرم صلی اللہ علیہ وسلم کے پاس پہنچے، آپ کھانا کھا رہے تھے (راوی کو شک ہے «یا ٔکل» کہا یا «یطعم» کہا) آپ صلی اللہ علیہ وسلم نے فرمایا:\"قریب آؤ اور کھانا کھاؤ\" (راوی کو شک ہے «ادن فکل» کہا یا «ادن فاطعم» کہا) تو میں نے کہا: «مںَ صائم» ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا:\"اللہ تعالی نے مسافر کو آدھی نماز اور روزے کی چھوٹ دے دی ہے، اور حاملہ عورت اور دودھ پلانے والی عورت کو بھی\" ۲؎۔\n§وضاحت\n۱؎: ان کا نام انس بن مالک قشیری ہے۔ ۲؎: حاملہ اور مرضعہ کو روزے کی چھوٹ دی ہے، نہ کہ آدھی نماز کی، جیسا کہ متبادر ہو رہا ہے، ترمذی کی عبارت واضح ہے \" مسافر کو روزہ اور آدھی نماز کی چھوٹ دی ہے، اور حاملہ و مرضعہ کو روزے کی\"۔","الألباني: حسن",{"u2":"حضرت ایوب سے منقول ہے کہ ہمیں بتایا گیا کہ قشیر قبیلے کا ایک بزرگ اپنے صحابی چچا سے حدیث بیان کرتا ہے۔ (ہم گئے تو) ہم نے اس بزرگ کو اس کے اونٹوں میںپایا۔ (میرے ساتھ استاد محترم ابوقلابہ بھی تھے) تو حضرت ابوقلابہ نے اس (بزرگ) سے کہا کہ اسے وہ حدیث بیان کیجئے: تو اس بزرگ نے فرمایا کہ مجھے میرے چچا (انس بن مالک قشیری رضی اللہ عنہ) نے بیان فرمایا کہ میں اپنے اونٹوں (کے مطالبے) کے سلسلے میں نبی صلی اللہ علیہ وسلم کے پاس پہنچا۔ آپ اس وقت کھانا کھا رہے تھے۔ آپ نے فرمایا: ’’آؤ اور کھانا کھاؤ۔‘‘ میں نے عرض کیا: میرا روزہ ہے۔ آپ نے فرمایا: ’’اللہ تعالیٰ نے مسافر کو نصف نماز اور روزہ معاف کر دیا ہے۔ اسی طرح حاملہ اور مرضعہ (بچے کو دودھ پلانے والی) کو بھی۔‘‘"}],[2276,"ایوب کہتے ہیں کہ مجھ سے ابوقلابہ نے یہ حدیث بیان کی، پھر مجھ سے کہا: کیا آپ اس حدیث کے بیان کرنے والے سے ملنا چاہیں گے؟ پھر انہوں نے ان کی طرف میری رہنمائی کی، تو میں جا کر ان سے ملا، انہوں نے کہا: مجھ سے میرے ایک رشتہ دار نے جنہیں انس بن مالک کہا جاتا ہے نے بیان کیا کہ میں اپنے اونٹوں کے سلسلے میں جو پکڑ لیے گئے تھے رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، میں پہنچا تو آپ کھانا کھا رہے تھے، تو آپ نے مجھے اپنے کھانے میں شریک ہونے کے لیے بلایا۔ میں نے عرض کیا: میں روزے سے ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"قریب آؤ میں تمہیں اس کے متعلق بتاتا ہوں، (سنو) اللہ تعالی نے مسافر کو روزہ، اور آدھی نماز کی چھوٹ دی ہے\"۔","الألباني: حسن",{"u2":"حضرت ایوب بیان کرتے ہیں کہ مجھے یہ حدیث حضرت ابو قلابہ نے بیان فرمائی، پھر فرمانے لگے: کیا تم اس حدیث کے راوی سے ملنا چاہتے ہو؟ اور مجھے ان کا پتا بتایا۔ میں جا کر انہیں ملا تو انہوں نے فرمایا: مجھ سے میرے ایک رشتے دار، جنہیں انس بن مالک رضی اللہ عنہ کہا جاتا ہے، نے بیان کیا کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس اپنے اونٹوں کے مطالبے کے لیے حاضر ہوا جو (غلط فہمی کی بنا پر) پکڑ لیے گئے تھے۔ میں نے آپ کو کھانا کھاتے پایا۔ آپ صلی اللہ علیہ وسلم نے مجھے کھانے کی دعوت دی۔ میں نے کہا: میرا تو روزہ ہے۔ آپ نے فرمایا: ’’ادھر آؤ، میں تمہیں اس بارے میں بتاتا ہوں کہ اللہ تعالیٰ نے مسافر کو روزہ اور نصف نماز معاف کر دی ہے۔‘‘","f2":"(۱)یہ انس بن مالک قشیری ہیں۔ مشہور انس بن مالک خادم رسول اور ہیں… رضی اللہ عنہ … (۲)’’پکڑ لیے گئے تھے۔‘‘ رسول اللہ صلی اللہ علیہ وسلم کے لشکر نے یہ اونٹ پکڑے تھے۔ ان کا خیال تھا کہ یہ کفار کے ہیں‘ حالانکہ یہ اونٹ صحابی رسول حضرت انس بن مالک قشیری رضی اللہ عنہ کے تھے۔ تو حضرت انس رضی اللہ عنہ اپنے اونٹوں کے مطالبے کے لیے خدمت نبوی میں حاضر ہوئے تھے۔"}],[2277,"ایک صحابی کہتے ہیں: میں ایک ضرورت سے رسول اللہ صلی اللہ علیہ وسلم کے پاس پہنچا اتفاق کی بات آپ اس وقت دوپہر کا کھانا کھا رہے تھے، آپ نے کہا: آؤ کھانا میں شریک ہو جاؤ، میں نے عرض کیا: میں روزے سے ہوں، آپ نے فرمایا: آؤ میں تمہیں روزے کے متعلق بتاتا ہوں، اللہ تعالی نے مسافر کو آدھی نماز اور روزے کی چھوٹ دی ہے، اور حاملہ اور دودھ پلانے والی عورت کو بھی چھوٹ دی ہے ۱؎۔\n§وضاحت\n۱؎: اگر ان کے روزہ رکھنے سے پیٹ کے بچہ کو یا شیرخوار بچہ کو نقصان پہنچنے کا اندیشہ ہو تو اوہ روزہ نہ رکھیں۔","الألباني: حسن",{"u2":"حضرت ابو قلابہ ایک صحابی سے بیان کرتے ہیں کہ انہوں نے فرمایا: میں نبی صلی اللہ علیہ وسلم کے پاس کسی کام کے سلسلے میں حاضر ہوا۔ آپ صبح کا کھانا کھا رہے تھے۔ آپ نے فرمایا: ’’آؤ کھانا کھاؤ۔‘‘ میں نے عرض کیا: میں روزے سے ہوں۔ آپ نے فرمایا: ’’ادھر آؤ، میں تمہیں روزے کے بارے میں بتاتا ہوں کہ اللہ تعالیٰ نے مسافر کو نصف نماز اور روزہ معاف کر دیا ہے۔ اور حاملہ اور دودھ پلانے والی عورت کو بھی رخصت دی ہے۔‘‘"}],[2278,"ابو العلاء بن شخیر بھی ایک شخص سے اسی جیسی حدیث روایت کرتے ہیں۔","",{"u2":"حضرت ابو علاء بن شخیر نے بھی ایک شخص سے ایسی ہی روایت بیان کی ہے۔"}],[2279,"ہانی بن شخیر بلحریش کے ایک شخص سے اور وہ اپنے والد سے روایت کرتے ہیں، وہ کہتے ہیں کہ میں مسافر تھا تو میں نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، اور میں روزے سے تھا، اور آپ کھانا تناول فرما رہے تھے، آپ نے فرمایا: \"آؤ\" (کھانے میں شریک ہو جاؤ) میں نے عرض کیا: میں روزے سے ہوں۔ آپ نے فرمایا:\"ادھر آؤ، کیا تمہیں اس چیز کا علم نہیں جو اللہ تعالی نے مسافر کو چھوٹ دی ہے\"۔ میں نے کہا: اللہ نے مسافر کو کیا چھوٹ دی ہے؟ آپ نے فرمایا: روزے کی، اور آدھی نماز کی۔\n§وضاحت\n۱؎: بلحریش بنی الحریش کا مخفف ہے جیسے بلحارث بنی الحارث کا مخفف ہے۔","الألباني: صحيح لغيره",{"u2":"بلحریش (بنو الحریش) قبیلے کے ایک شخص نے اپنے والد سے بیان کیا، انہوں نے فرمایا: میں مسافر تھا۔ میں نبی صلی اللہ علیہ وسلم کے پاس آیا۔ میں اس وقت روزے سے تھا، اور آپ کھانا کھا رہے تھے۔ آپ نے فرمایا: ’’تم بھی آؤ۔‘‘ میں نے عرض کیا: میرا تو روزہ ہے۔ آپ نے فرمایا: ’’ادھر آؤ۔ کیا تم نہیں جانتے کہ اللہ تعالیٰ نے مسافر کو معافی دی ہے؟‘‘ میں نے کہا: کس چیز کی؟ فرمایا: ’’روزے اور نصف نماز کی۔‘‘"}],[2280,"ہانی بن عبداللہ بن شخیر بلحریش کے ایک شخص سے اور وہ اپنے والد سے روایت کرتے ہیں، وہ کہتے ہیں کہ جب تک اللہ تعالی کو منظور رہا ہم سفر کرتے رہے، پھر ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، آپ کھانا تناول فرما رہے تھے، آپ نے فرمایا: \"آؤ کھانا کھاؤ\"، میں نے عرض کیا: میں روزے سے ہوں۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: میں تمہیں روزے کے متعلق بتاتا ہوں: اللہ تعالی نے مسافر سے روزے کی چھوٹ دی ہے، اور آدھی نماز کی بھی۔","الألباني: صحيح لغيره",{"u2":"بلحریش (بنو الحریش) قبیلے کے ایک شخص نے اپنے والد محترم سے بیان کیا کہ ہم سفر کیا کرتے تھے جب تک اللہ تعالیٰ چاہتا۔ ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے تو آپ کھانا کھا رہے تھے۔ فرمایا: ’’آؤ کھانا کھاؤ۔‘‘ میں نے کہا: میرا تو روزہ ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میں تمہیں روزے کے بارے میں بیان کرتا ہوں کہ اللہ تعالیٰ نے مسافر کو روزہ اور آدھی نماز معاف کر دی ہے۔‘‘"}],[2281,"عبداللہ بن شخیر کہتے ہیں کہ میں مسافر تھا، رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، آپ کھانا کھا رہے تھے اور میں روزے سے تھا، آپ نے فرمایا: آؤ (کھانا کھا لو)میں نے کہا: میں روزے سے ہوں۔ آپ نے فرمایا: کیا تمہیں وہ چیز معلوم ہے جس کی اللہ نے مسافر کو چھوٹ دی ہے؟، میں نے کہا: کس چیز کی اللہ تعالی نے مسافر کو چھوٹ دی ہے؟، آپ صلی اللہ علیہ وسلم نے فرمایا: \"روزے اور آدھی نماز کی\"۔","الألباني: صحيح لغيره",{"u2":"حضرت ہانی بن بن عبداللہ بن شخیر اپنے والد محترم سے بیان کرتے ہیں کہ انہوں نے فرمایا: میں مسافر تھا۔ نبی صلی اللہ علیہ وسلم کے پاس آیا۔ آپ اس وقت کھانا کھا رہے تھے۔ اور میرا روزہ تھا۔ آپ نے فرمایا: ’’آؤ۔‘‘ میں نے کہا: میرا تو روزہ ہے۔ فرمایا: ’’کیا تم جانتے ہو کہ اللہ تعالیٰ نے مسافر کو کیا معاف کیا ہے؟‘‘ میں نے کہا: اللہ تعالیٰ نے مسافر کو کیا معاف کیا ہے؟ آپ نے فرمایا: ’’روزہ اور نصف نماز۔‘‘"}],[2282,"غیلان کہتے ہیں: میں ابوقلابہ کے ساتھ ایک سفر میں نکلا (کھانے کے وقت) انہوں نے کھانا میرے آگے بڑھایا تو میں نے کہا: میں تو روزے سے ہوں، اس پر انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم ایک سفر میں نکلے، آپ نے کھانا آگے بڑھاتے ہوئے ایک شخص سے کہا: \"قریب آ جاؤ کھانا کھاؤ\"، اس نے کہا: میں روزے سے ہوں، آپ صلی اللہ علیہ وسلم نے فرمایا ـ: \"اللہ تعالی نے مسافر کے لیے آدھی نماز کی اور سفر میں روزے کی چھوٹ دی ہے\"۔ تو اب آؤ کھاؤ، تو میں قریب ہو گیا، اور کھانے لگا۔","الألباني: صحيح",{"u2":"حضرت غیلان بیان کرتے ہیں کہ میں حضرت ابوقلابہ کے ساتھ ایک سفر میں گیا۔ انہوں نے کھانا میرے قریب کیا۔ میں نے کہا: میرا تو روزہ ہے۔ وہ کہنے لگے کہ رسول اللہ صلی اللہ علیہ وسلم (ایک دفعہ) سفر میں نکلے۔ آپ نے کھانا قریب کیا اور ایک آدمی سے فرمایا: ’’آؤ! کھانا کھاؤ۔‘‘ اس نے کہا: میں تو روزے سے ہوں۔ آپ نے فرمایا: ’’اللہ تعالیٰ نے مسافر کو نصف نماز اور روزہ سفر میں معاف کر دیا ہے، لہٰذا تم قریب آؤ اور کھاؤ۔‘‘ (غیلان نے کہا:) (یہ حدیث سن کر) میں قریب ہوا اور میں نے کھانا کھایا۔","f2":"(۱)ایک حدیث کی اس قدر تکرار کی وجوہات اس سے قبل مختلف مقامات پر ذکر ہو چکی ہیں، مثلاً حدیث: ۲۱۳۲ کے فوائد دیکھ لیں۔ (۲)روایات سے معلوم ہوتا ہے کہ مندرجہ بالا واقعہ ایک سے زائد صحابہ کے ساتھ پیش آیا اور یہ کوئی بعید بات نہیں۔"}],[2283,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ سفر میں تھے، ہم میں سے کچھ لوگ روزہ رکھے ہوئے تھے اور کچھ لوگ بغیر روزے کے تھے، ہم نے ایک گرم دن میں پڑاؤ کیا، اور ہم (چھولداریاں اور خیمے لگا لگا کر) سایہ کرنے لگے، تو روزہ دار (سخت گرمی کی تاب نہ لا کر) گر گر پڑے، اور روزہ نہ رہنے والے اٹھے، اور انہوں نے سواریوں کو پانی پلایا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"آج غیر روزہ دار ثواب مار لے گئے\"۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ سفر میں تھے۔ کسی نے روزہ رکھا ہوا تھا، کسی نے نہیں رکھا تھا۔ یہ سخت گرم دن تھے۔ ہم اترے اور سایہ حاصل کیا۔ روزے دار تو لیٹ گئے لیکن روزہ نہ رکھنے والے اٹھے اور انہوں نے ہماری سواریوں کے جانوروں کو پانی پلایا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’آج تو روزہ نہ رکھنے والے ثواب لے گئے۔‘‘","f2":"(۱)اتنی مشقت کے ساتھ نفل روزے سفر میں رکھنا کہ روزے دار اپنا کام بھی خود نہ کر سکے بلکہ دوسروں کو اس کا کام کرنا پڑے، بہتر نہیں۔ روزہ رکھنا سفر میں اس وقت بہتر ہے جب انسان عاجز نہ آئے اور لوگوں پر بوجھ نہ بنے۔ (۲)’’ثواب لے گئے۔‘‘ یعنی خدمت کا ثواب۔ ویسے یہ جملہ ترجیح کے موقع پر بولا جاتا ہے، گویا اس دن روزہ نہ رکھنے والے روزہ رکھنے والوں سے بڑھ گئے۔ واللہ اعلم (۳)جہاد میں ایک دوسرے کا تعاون کرنا بہت اجر والا کام ہے۔"}],[2284,"عبدالرحمٰن بن عوف رضی اللہ عنہ کہتے ہیں: کہا جاتا ہے سفر میں روزہ رکھنا ایسا ہے جیسے حضر میں افطار کرنا۔","الألباني: ضعيف موقوف",{"u2":"حضرت عبدالرحمن بن عوف رضی اللہ عنہ فرماتے ہیں: کہا جاتا ہے کہ سفر میں روزہ رکھنا گھر میں رہ کر روزہ نہ رکھنے کے برابر ہے۔"}],[2285,"عبدالرحمٰن بن عوف رضی اللہ عنہ کہتے ہیں: سفر میں روزہ رکھنے والا ایسا ہی ہے جیسے حضر میں روزہ نہ رکھنے والا۔","الألباني: ضعيف",{"u2":"حضرت عبدالرحمن بن عوف رضی اللہ عنہ نے فرمایا: سفر میں روزہ رکھنے والا گھر رہ کر روزہ نہ رکھنے والے کی طرح ہے۔"}],[2286,"عبدالرحمٰن بن عوف رضی اللہ عنہ کہتے ہیں: سفر میں روزہ رکھنے والا حضر میں افطار کرنے والے کی طرح ہے ۱؎۔\n§وضاحت\n۱؎: یعنی جس طرح حضر میں افطار کرنا گناہ ہے اس طرح سفر میں روزہ رکھنا بھی باعث گناہ ہے، مگر یہ صحابی کا قول ہے جو حدیث رسول صلی اللہ علیہ وسلم کے مخالف ہے :(یعنی مسافر کو چھوٹ ہے چاہے رکھے، چاہے نہ رکھے اور قضاء کرے )۔","الألباني: ضعيف",{"u2":"حضرت عبدالرحمن بن عوف رضی اللہ عنہ بیان کرتے ہیں کہ سفر میں روزہ رکھنے والا گھر رہ کر روزہ نہ رکھنے والے کی طرح ہے۔","f2":"یہ روایت زیادہ سے زیادہ موقوف (یعنی صحابی کا قول) ہے، علاوہ ازیں تینوں روایات سنداً ضعیف ہیں، نیز روایت: ۲۲۸۶ سے معلوم ہوتا ہے کہ اس قول کے قائل کا بھی علم نہیں کہ کون ہے۔ ویسے بھی اس قول کا مطلب مندرجہ بالا مرفوع احادیث کے مخالف نہیں لیا جا سکتا، یعنی اگر سفر میں روزہ انتہائی مشقت کا سبب ہو جس سے روزے دار عاجز آجائے اور دوسروں کے لیے مصیبت کا سبب بنے تب سفر میں روزہ رکھنا مناسب نہیں ورنہ جائز ہے جیسا کہ رسول اللہ صلی اللہ علیہ وسلم اور صحابہ کرام رضی اللہ عنہم کے فعل سے ثابت ہے۔ کسی قول کا ایسا مطلب نہیں لیا جا سکتا جو صریح حدیث کے خلاف ہو۔"}],[2287,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم رمضان کے مہینے میں سفر پر نکلے، تو آپ روزے سے رہے۔ یہاں تک کہ آپ قدید پہنچے، تو آپ کے سامنے دودھ کا ایک پیالہ لایا گیا، تو آپ نے پیا، اور آپ نے اور آپ کے صحابہ نے روزہ توڑ دیا۔\n§وضاحت\n۱؎: \"قدید\" مدینہ سے سات منزل کی دوری پر \"عسفان\" کے قریب ایک گاؤں ہے۔","الألباني: صحيح لغيره",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے منقول ہے کہ نبی صلی اللہ علیہ وسلم رمضان المبارک میں (فتح مکہ کے لیے) نکلے۔ آپ روزے رکھتے رہے حتیٰ کہ قُدَیْد مقام پر آئے تو آپ کے پا دودھ کا پیالہ لایا گیا۔ آپ نے پیا اور صحابہ سمیت روزہ کھول لیا۔"}],[2288,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مدینہ میں روزہ رکھا، (اور چلے) یہاں تک کہ آپ قدید آئے، پھر آپ نے روزہ توڑ دیا، اور مکہ پہنچنے تک بغیر روزہ کے رہے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم مدینہ منورہ سے چلے تو روزے رکھتے رہے حتیٰ کہ قدید کے مقام پر آگئے، پھر آپ نے روزے رکھنے بند کر دیئے حتیٰ کہ مکہ مکرمہ آگئے۔‘‘"}],[2289,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سفر میں روزہ رکھا یہاں تک کہ آپ قدید آئے، پھر آپ نے دودھ کا ایک پیالہ منگایا اور (اسے) پیا، اور آپ نے اور آپ کے اصحاب نے روزہ توڑ دیا۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم (فتح مکہ کے) سفر میں روزے رکھتے رہے حتیٰ کہ قدید مقام پر آئے تو دودھ کا پیالہ منگوایا اور پی لیا۔ اس طرح آپ نے اور آپ کے صحابہ نے روزہ کھول لیا۔","f2":"یہ روایت تفصیل سے پیچھے گزر چکی ہے۔ (دیکھئے، روایت: ۲۲۶۵) جس میں روزے کے افطار کی وجہ مشقت بیان کی گئی ہے۔ اس باب میں یہ بیان کیا گیا ہے کہ اس کے بعد مکہ مکرمہ تشریف لانے تک روزہ نہیں رکھا۔ اس کی وجہ مشقت کے علاوہ یہ بھی تھی کہ مکہ مکرمہ میں جنگ کا امکان تھا، لہٰذا آپ نے مناسب سمجھا کہ لوگ کچھ جسمانی قوت حاصل کر لیں، اس لیے حکماً روزے رکھنے سے روک دیا۔ گویا مخصوص حالت میں سفر کے دوران میں روزہ رکھنے سے روکا جا سکتا ہے۔"}],[2290,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم مکہ کے لیے نکلے، آپ روزہ رکھے ہوئے تھے۔ یہاں تک کہ آپ عسفان ۱؎ پہنچے، تو ایک پیالہ منگایا اور پیا۔ شعبہ کہتے ہیں: یہ واقعہ رمضان کے مہینے کا ہے، چنانچہ ابن عباس رضی اللہ عنہما کہتے تھے: سفر میں جو چاہے روزہ رکھے اور جو چاہے نہ رکھے۔\n§وضاحت\n۱؎: عسفان کے پاس ہی قدید ہے، یہ واقعہ وہی ہے جس کا تذکرہ اوپر روایتوں میں ہے، کسی راوی نے قدید کہا اور کسی نے عسفان۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم (فتح مکہ کے وقت) مکہ مکرمہ کو چلے تو روزے رکھتے رہے حتیٰ کہ عسفان مقام پر پہنچے تو پیالہ منگوایا اورپی لیا۔ اور یہ رمضان المبارک کی بات ہے۔ حضرت ابن عباس رضی اللہ عنہ (اس بنا پر) فرمایا کرتے تھے: (سفر میں) جو شخص چاہے روزہ رکھے، جو چاہے نہ رکھے۔","f2":"سابقہ روایات میں قدید کا ذکر ہے اور یہاں عسفان کا، اس میں کوئی تضاد نہیں۔ یہ دونوں مقام قریب قریب ہیں۔ ممکن ہے کہ افطار کی تعمیم (لوگوبں کی اطلاع) کے لیے دونوں جگہ نبی صلی اللہ علیہ وسلم نے پیا ہو۔"}],[2291,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے رمضان میں سفر کیا، اور آپ روزہ رکھے ہوئے تھے، یہاں تک کہ عسفان پہنچے تو آپ نے ایک برتن منگایا، تو دن ہی میں پی لیا، لوگ اسے دیکھ رہے تھے، پھر آپ بغیر روزہ کے رہے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے رمضان المبارک میں (فتح مکہ کا) سفر کیا۔ روزے رکھتے رہے حتیٰ کہ مقام عسفان میں پہنچے تو برتن منگوایا اور ابھی دن ہی تھا کہ آپ نے پی کر روزہ کھول لیا۔ سب لوگ آپ کو دیکھ رہے تھے۔","f2":"معلوم ہوا دورانِ فر میں شدید مشقت ہو تو روزہ کھولا جاسکتا ہے۔ اس میں کوئی کفارہ نہیں، ہاں قضا ادا کرنی ہوگی۔"}],[2292,"عوام بن حوشب کہتے ہیں کہ میں نے مجاہد سے سفر میں روزہ رکھنے کے بارے میں پوچھا تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم سفر میں روزہ رکھتے تھے اور نہیں بھی رکھتے تھے ۱؎۔\n§وضاحت\n۱؎: اپنی آسانی دیکھ کر جیسا مناسب سمجھے کرے، اللہ نے نہ رکھنے کی رخصت دی ہے۔","الألباني: صحيح لغيره",{"u2":"حضرت عوام بن حوشب سے روایت ہے کہ میں نے حضرت مجاہد سے سفر میں روزہ رکھنے کے بارے میں پوچھا تو انہوں نے فرمایا: رسول اللہ% (سفر کے دوران میں) روزہ رکھ بھی لیتے تھے اور چھوڑ بھی دیتے تھے۔"}],[2293,"مجاہد کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے رمضان کے مہینے میں روزے رکھے، اور سفر میں بغیر روزے کے رہے۔","الألباني: صحيح",{"u2":"حضرت مجاہد سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سفر کے دوران میں ماہ رمضان المبارک کے روزے رکھے بھی ہیں اور چھوڑے بھی۔"}],[2294,"حمزہ بن عمرو اسلمی رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سفر میں روزہ رکھنے کے بارے میں پوچھا تو آپ نے فرمایا: \"چاہو تو روزہ رکھو، اور چاہو تو نہ رکھو\"۔","الألباني: صحيح",{"u2":"حضرت حمزہ بن عمرو اسلمی رضی اللہ عنہ سے روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سفر کے دوران میں روزہ رکھنے کے بارے میں پوچھا۔ آپ نے فرمایا ’’اگر تو چاہے تو رکھ لے اور چاہے تو نہ رکھ۔‘‘"}],[2295,"سلیمان بن یسار سے روایت ہے کہ حمزہ بن عمرو رضی اللہ عنہ نے عرض کیا: اللہ کے رسول! آگے اوپر والی حدیث کے مثل ہے اور یہ حدیث مرسل ۲؎ ہے۔\n§وضاحت\n۱؎: مرسل سے مراد منقطع ہے کیونکہ سلیمان بن یسار اور حمزہ بن عمرو رضی اللہ عنہ کے درمیان ابو مرواح کا واسطہ چھوٹا ہوا ہے جیسا کہ حدیث نمبر ۲۳۰۴ :(جو آگے آ رہی ہے ) کی سند سے واضح ہے :(واللہ اعلم )۔","",{"u2":"حضرت سلیمان بن یسار سے روایت ہے کہ حضرت حمزہ بن عمرو نے کہا: اے اللہ کے رسول! پھر اسی کے مثل بیان کیا۔ یہ روایت مرسل (منقطع) ہے۔"}],[2296,"حمزہ بن عمرو رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سفر میں روزہ رکھنے کے بارے میں پوچھا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر تم روزہ رکھنا چاہو تو رکھو اور اگر نہ رکھنا چاہو تو نہ رکھو\"۔","الألباني: صحيح",{"u2":"حضرت حمزہ اسلمی رضی اللہ عنہ سے منقول ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے دوران سفر میں روزہ رکھنے کے بارے میں پوچھا تو آپ نے فرمایا: ’’اگر تو روزہ رکھنا چاہے تو روزہ رکھ لے اور اگر نہ رکھنا چاہے تو نہ رکھ۔‘‘"}],[2297,"حمزہ بن عمرو رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سفر میں روزہ رکھنے کے بارے میں پوچھا؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر تم روزہ رکھنا چاہو تو رکھو، اور اگر نہ رکھنا چاہو تو نہ رکھو\"۔","الألباني: صحيح",{"u2":"حضرت حمزہ بن عمرو رضی اللہ عنہ سے مروی ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سفر کی حالت میں روزہ رکھنے کے بارے میں پوچھا تو آپ نے فرمایا: ’’تو روزہ رکھنا چاہے تو روزہ رکھ سکتا ہے۔ نہ رکھنا چاہے تو چھوڑ بھی سکتا ہے۔‘‘"}],[2298,"حمزہ بن عمرو اسلمی رضی اللہ عنہ سے روایت ہے کہ انہوں نے کہا: اللہ کے رسول! میں سفر میں اپنے اندر روزہ رکھنے کی طاقت پاتا ہوں (تو کیا میں روزہ رکھوں؟)آپ نے فرمایا: \"اگر چاہو تو رکھو، اور چاہو تو نہ رکھو\"۔","الألباني: صحيح",{"u2":"حضرت حمزہ بن عمرو اسلمی رضی اللہ عنہ نے عرض کیا: اے اللہ کے رسول! یقینا میں سفر کی حالت میں روزہ رکھنے کی طاقت رکھتا ہوں (تو کیا میں روزہ رکھ لیا کروں) آپ نے فرمایا: ’’اگر چاہے تو رکھ لے، چاہے تو نہ رکھ۔‘‘"}],[2299,"حمزہ بن عمرو رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سفر میں روزہ رکھنے کے بارے میں پوچھا: تو آپ نے فرمایا: \"اگر رکھنا چاہو تو رکھو، اور اگر نہ رکھنا چاہو تو نہ رکھو\"۔","الألباني: صحيح",{"u2":"حضرت حمزہ بن عمرو رضی اللہ عنہ سے روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے دوران سفر میں روزہ رکھنے کے بارے میںپوچھا۔ آپ نے فرمایا: ’’اگر روزہ رکھنا چاہے تو رکھ لے اور اگر نہ رکھنا چاہے تو نہ رکھ۔‘‘"}],[2300,"حمزہ بن عمرو رضی اللہ عنہ کہتے ہیں: میں رسول اللہ صلی اللہ علیہ وسلم کے زمانہ میں مسلسل روزہ رکھتا تھا، تو میں نے عرض کیا: اللہ کے رسول! میں سفر میں مسلسل روزہ رکھوں؟ تو آپ نے فرمایا: \"اگر چاہو تو رکھو اور چاہو تو نہ رکھو\"۔","الألباني: صحيح",{"u2":"حضرت حمزہ بن عمرو رضی اللہ عنہ بیان کرتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے دور میں لگاتار نفل روزے رکھا کرتا تھا تو میں نے عرض کیا: اے اللہ کے رسول! میں سفر میں بھی لگاتار روزے رکھ لیتا ہوں (کوئی حرج تو نہیں؟) آپ نے فرمایا: ’’چاہے تو روزہ رکھ، چاہے تو نہ رکھ۔‘‘"}],[2301,"حمزہ بن عمرو رضی اللہ عنہ کہتے ہیں کہ میں نے عرض کیا: اللہ کے نبی! میں مسلسل روزہ رکھنے والا آدمی ہوں تو کیا میں سفر میں بھی برابر روزہ رکھوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر چاہو تو رکھو، اور اگر چاہو تو نہ رکھو\"۔","الألباني: صحيح",{"u2":"حضرت حمزہ (اسلمی) رضی اللہ عنہ فرماتے ہیں کہ میں نے عرض کیا: اے اللہ کے رسول صلی اللہ علیہ وسلم! میں مسلسل نفل روزے رکھتا ہوں تو کیا سفر میں بھی روزہ رکھ لیا کروں؟ آپ نے فرمایا: ’’جی چاہے تو رکھ لے، جی چاہے تو نہ رکھ۔‘‘"}],[2302,"حمزہ بن عمرو رضی اللہ عنہ کا بیان ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا وہ ایک ایسے آدمی تھے جو سفر میں روزہ رکھتے تھے تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر چاہو تو رکھو، اور اگر چاہو تو نہ رکھو\"۔","الألباني: صحيح",{"u2":"حضرت حمزہ بن عمرو رضی اللہ عنہ نے جو کہ سفر میں روزے رکھا کرتے تھے، رسول اللہ صلی اللہ علیہ وسلم سے (اس بارے میں) پوچھا تو آپ نے فرمایا: ’’چاہے تو روزہ رکھ، چاہے تو نہ رکھ۔‘‘"}],[2303,"حمزہ بن عمرو رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کیا: میں اپنے اندر سفر میں روزہ رکھنے کی طاقت پاتا ہوں، تو کیا (اگر میں روزہ رکھوں تو) مجھ پر گناہ ہو گا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ اللہ عزوجل کی جانب سے رخصت ہے، تو جس نے اس رخصت کو اختیار کیا تو یہ اچھا ہے، اور جو روزہ رکھنا چاہے تو اس پر کوئی حرج نہیں\"۔","الألباني: صحيح",{"u2":"حضرت حمزہ بن عمرو رضی اللہ عنہ سے منقول ہے، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کیا: میں اپنے آپ میں دوران سفر میں روزہ رکھنے کی طاقت پاتا ہوں تو کیا روزہ رکھنے میں مجھ پر کوئی گناہ ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’روزہ نہ رکھنا اللہ عزوجل کی طرف سے رخصت ہے۔ جو رخصت پر عمل کرے تو اچھی بات ہے اور جو روزہ رکھنا چاہے تو اس پر بھی کوئی گناہ نہیں۔‘‘","f2":"مندرجہ بالا روایت میں رسول اللہ صلی اللہ علیہ وسلم سے صراحتاً ثابت ہے کہ سفر میں روزہ رکھنا، نہ رکھنا برابر ہے۔ ہر مسافر اپنے حالات کے لحاظ سے دونوں میں سے کسی پر بھی عمل کر سکتا ہے۔ اگر مشقت نہ ہو تو فرض روزہ رکھ لینا بہتر اور افضل ہے کیونکہ بعد میں قضا میں رکاوٹ پیدا ہو سکتی ہے (اگرچہ نہ رکھنا بھی جائز ہے) اور اگر مشقت ہو تو روزہ نہ رکھنا بہتر ہے تاکہ روزہ اس کے اور اس کے ساتھیوں کے لیے مصیبت نہ بن جائے۔ نفلی روزے میں دونوں باتیں برابر ہیں۔ یہ مندرجہ بالا روایات کا خلاصہ ہے۔ اس طریقے سے تمام روایات پر عمل ہو جائے گا۔"}],[2304,"حمزہ بن عمرو اسلمی رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: میں سفر روزہ میں رکھوں؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:\"اگر چاہو تو رکھو، اور اگر چاہو تو نہ رکھو\"۔","الألباني: صحيح",{"u2":"حضرت حمزہ بن عمرو اسلمی رضی اللہ عنہ سے مروی ہے کہ میں سفر میں روزے رکھا کرتا تھا۔ (اس لیے) میں نے رسول اللہa سے پوچھا: کیا میں دوران سفر میں روزہ رکھ سکتا ہوں؟ آپ نے فرمایا: ’’اگر تو چاہے تو روزہ رکھ لے اور اگر چاہے تو نہ رکھ۔‘‘"}],[2305,"حمزہ بن عمرو رضی اللہ عنہ سے روایت ہے کہ انہوں نے عرض کیا: اللہ کے رسول! میں روزہ رکھنے والا آدمی ہوں، کیا میں سفر میں روزہ رکھوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر چاہو تو رکھو، اور اگر چاہو تو نہ رکھو\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ حضرت حمزہ بن عمرو اسلمی نے کہا: اے اللہ کے رسول! میں اکثر نفل روزے رکھتا ہوں تو کیا سفر میں بھی رکھ لیا کروں؟ آپ نے فرمایا: ’’اگر چاہے تو روزہ رکھ لے اور اگر چاہے تو نہ رکھ۔‘‘"}],[2306,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ حمزہ رضی اللہ عنہ نے عرض کیا: اللہ کے رسول! میں سفر میں روزہ رکھوں؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر چاہو تو رکھو اور اگر چاہو تو نہ رکھو\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ حضرت حمزہ (اسلمی) رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کیا: اے اللہ کے رسول! میں سفر میں روزہ رکھ لیا کروں؟ اور وہ اکثر (نفل) روزے رکھا کرتے تھے۔ تو رسول اللہa نے ان سے فرمایا: ’’اگر چاہے تو روزہ رکھ لے اور چاہے تو نہ رکھ۔‘‘"}],[2307,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ حمزہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کیا: اللہ کے رسول! سفر میں روزہ رکھوں؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر چاہو تو رکھو، اور اگر چاہو تو نہ رکھو\"۔","الألباني: حسن صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ حضرت حمزہ (اسلمی) رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے سوال کیا، کہا: اے اللہ کے رسول! کیا میں سفر میں روزہ رکھ لیا کروں؟ آپ نے فرمایا: ’’اگر جی چاہے تو روزہ رکھ لے اور اگر جی چاہے تو نہ رکھ۔‘‘"}],[2308,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ حمزہ اسلمی رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے سفر میں روزہ رکھنے کے بارے میں پوچھا وہ ایک ایسے آدمی تھے جو مسلسل روزہ رکھتے تھے، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر چاہو تو رکھو، اور اگر چاہو تو نہ رکھو\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے منقول ہے کہ حضرت حمزہ رضی اللہ عنہ اسلمی رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے دوران سفر روزہ رکھنے کے بارے میں سوال کیا اور یہ (اللہ کے بندے) لگاتار نفل روزے رکھا کرتے تھے۔ آپ نے فرمایا: ’’اگر تو چاہے تو روزہ رکھ لے اور اگر چاہے تو چھوڑ دے۔‘‘","f2":"روایات کی یہ تکرار بعض اسناد باریکیوں کی وضاحت کے لیے ہوتی ہے اور محدثین کے نزدیک یہ بہت مفیس اور دلچسپ چیز کی طرف کئی مقامات پر اشارہ ہو چکا ہے۔ (مثلاً دیکھئے، حدیث: ۲۱۳۲)"}],[2309,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ ہم رمضان میں (رسول اللہ صلی اللہ علیہ وسلم کے ساتھ) سفر کرتے تھے۔ ہم میں سے کوئی روزہ سے ہوتا تھا، اور کوئی بغیر روزہ کے، اور روزہ دار روزہ نہ رکھنے والوں کو عیب کی نظر سے نہیں دیکھتا اور نہ ہی روزہ نہ رکھنے والا روزہ رکھنے والے کو معیوب سمجھتا تھا۔","الألباني: صحيح",{"u2":"حضرت ابو سعید رضی اللہ عنہ بیان کرتے ہیں کہ ہم رمضان المبارک میں سفر کیا کرتے تھے۔ کوئی ہم میں سے روزے دار ہوتا تھا اور کسی کا روزہ نہیں ہوتا تھا۔ نہ روزے دار روزہ چھوڑنے والے پر اعتراض کرتا تھا اور نہ روزہ چھوڑنے والا روزہ دار پر۔‘‘"}],[2310,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ ہم نبی اکرم صلی اللہ علیہ وسلم کے ساتھ سفر کرتے تھے، تو ہم میں بعض روزہ دار ہوتے تھے اور بعض بغیر روزہ کے، اور روزہ دار روزہ نہ رکھنے والے کو عیب کی نظر سے نہیں دیکھتا تھا، اور نہ ہی روزہ نہ رکھنے والا روزہ دار کو عیب کی نظر سے دیکھتا تھا۔","الألباني: صحيح",{"u2":"حضرت ابو سعید رضی اللہ عنہ سے روایت ہے کہ ہم نبی صلی اللہ علیہ وسلم کے ساتھ سفر کیا کرتے تھے۔ ہم میں سے کوئی روزہ رکھتا تھا، کوئی نہیں رکھتا تھا۔ نہ تو روزہ رکھنے والا، نہ رکھنے والے پر اعتراض کرتا تھا اور نہ روزہ نہ رکھنے والا روزہ رکھنے والے پر کوئی اعتراض کرتا تھا۔"}],[2311,"جابر رضی اللہ عنہ کہتے ہیں کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ سفر کیا تو ہم میں سے بعض نے روزہ رکھے اور بعض نے نہیں۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ فرماتے ہیں کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ سفر کیا۔ ہم میں سے کسی نے روزہ رکھا تھا، کسی نے نہیں۔"}],[2312,"ابو سعید خدری اور جابر بن عبداللہ رضی اللہ عنہم سے روایت ہے کہ ان دونوں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ سفر کیا، تو روزہ رکھنے والا روزہ رکھتا، اور نہ رکھنے والا کھاتا پیتا، اور روزہ دار روزہ نہ رکھنے والے کو معیوب نہیں سمجھتا، اور روزہ نہ رکھنے والا روزہ دار کو معیوب نہیں سمجھتا۔","الألباني: صحيح",{"u2":"حضرت ابو سعید اور حضرت جابر رضی اللہ عنہما سے منقول ہے کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ سفر کیے کوئی روزہ رکھتا تھا، کوئی نہیں رکھتا تھا۔ نہ روزے دار روزہ چھوڑنے والے پر اعتراض کرتا تھا اور نہ روزہ چھوڑنے والا روزہ دار پر۔"}],[2313,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم رمضان میں فتح مکہ کے سال روزہ کی حالت میں نکلے۔ یہاں تک کہ جب کدید ۱؎ میں پہنچے تو آپ نے روزہ توڑ دیا۔\n§وضاحت\n۱؎: کَدِید یا قُدید یہ دونوں مقامات عسفان کے پاس ہیں، اس لیے رواۃ کبھی عسفان کہتے ہیں اور کبھی قُدید اور کبھی کَدِید، واقعہ ایک ہی ہے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم فتح مکہ والے سال رمضان المبارک میں روزے رکھتے ہوئے گئے، حتیٰ کہ جب مقام کدید میں پہنچے تو (اس دن کا) روزہ کھول لیا۔","f2":"(۱)یہ روایت مع فائدہ پیچھے گزر چکی ہے۔ دیکھئے حدیث ۲۲۹۱۔ (۲)اس روایت میں افطار کی جگہ کدید بتلائی گئی ہے جو کہ ژسفان اور قدید کے درمیان ہے، لہٰذا یہ روایت دوسری روایات سے مختلف نہیں۔ (دیکھئے، حدیث: ۲۲۹۲)۔ (۳)باب کا مقصد یہ ہے کہ اگر مسافر سفر میں روزہ رکھنے کو ترجیح دے تو ضروری نہیں کہ وہ سب روزے رکھے بلکہ کچھ رکھ لے کچھ نہ رکھے۔ بعد میں بھی رکھ لے تو کوئی حرج نہیں۔"}],[2314,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سفر کیا تو روزہ رکھا یہاں تک کہ عسفان پہنچے، پھر آپ نے (پانی سے بھرا) ایک برتن منگایا، اور دن ہی میں پیا، تاکہ لوگ آپ کو دیکھ لیں، پھر آپ بغیر روزہ کے رہے، یہاں تک کہ مکہ پہنچ گئے۔ تو آپ نے مکہ کو رمضان میں فتح کیا۔ عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے سفر میں روزہ رکھا، اور روزہ توڑ بھی دیا ہے، تو جس کا جی چاہے روزہ رکھے، اور جس کا جی چاہے نہ رکھے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے (فتح مکہ کا) سفر کیا تو روزے رکھتے گئے حتیٰ کہ عسفان مقام پر پہنچے تو برتن منگوایا اور دن ئھڑے پیا تاکہ لوگ بھی آپ کو دیکھ لیں (اور روزہ کھول لیں)۔ پھر آپ نے روزے نہیں رکھے حتیٰ کہ مکہ مکرمہ پہنچ گئے اور مکہ فتح کر لیا۔ یہ رمضان المبارک کی بات ہے۔ حضرت ابن عباس رضی اللہ عنہ فرماتے ہیں رسول اللہ صلی اللہ علیہ وسلم نے سفر میں روزہ رکھا بھی ہے اور کبھی نہیں بھی رکھا، لہٰذا جو شخص چاہے روزہ رکھے، جو چاہے نہ رکھے۔","f2":"امام نسائی رحمہ اللہ کا مقصد اس شخص کی تردید کرنا ہے جو اس مسافر کے لیے افطار کی رخصت کا قائل ہے جسے رمضان المبارک سفر کی حالت میں طلوع ہو، جس شخص کو رمضان المبارک کا آغاز گھر میں ہو جائے، وہ سفر میں روزہ چھوڑنے کا مجاز نہیں، نیز سفر شروع ہونے سے پہلے رکھا جانے والا روزہ سفر کے دوران میں افطار کرنا جائز نہیں۔ مذکورہ حدیث میں دونوں باتوں کا رد ہے۔"}],[2315,"انس بن مالک (قشیری) رضی اللہ عنہ سے روایت ہے کہ وہ مدینہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، آپ اس وقت دوپہر کا کھانا کھا رہے تھے، تو آپ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"آؤ کھانا کھاؤ\"۔ انہوں نے عرض کیا: میں روزہ دار ہوں، تو آپ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"اللہ عزوجل نے مسافر کو روزہ کی، اور آدھی نماز کی چھوٹ دے دی ہے، نیز حاملہ اور مرضعہ کو بھی روزہ نہ رکھنے کی چھوٹ دی گئی ہے\"۔","الألباني: حسن",{"u2":"حضرت انس بن مالک قشیری رضی اللہ عنہ سے منقول ہے کہ میں نبی صلی اللہ علیہ وسلم کے پاس مدینہ منورہ آیا۔ آپ کھانا تناول فرما رہے تھے۔ آپ نے مجھ سے فرمایا: ’’آو کھانا کھاؤ۔‘‘ میں نے عرض کیا: میں روزے سے ہوں۔ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ تعالیٰ نے مسافر کو روزہ اور نصاف نماز معاف فرما دی ہے۔ اور حاملہ اور بچے کو دودھ پلانے والی کو بھی۔‘‘","f2":"حاملہ اور مرضعہ کو اگر مشقت محسوس ہو یا اپنے بچے کا خطرہ ہو تو انہیں روزہ چھوڑنے اور اس کی جگہ کفارہ دینے کی رخصت ہے۔ اگرچہ اس مسئلے میں اختلاف ہے لیکن یہ موقف راجح ہے۔ ابن عباس اور ابن عمر دونوں صحابہ کرام رضی اللہ عنہم کا یہی فتویٰ ہے اور سند بھی صحیح ہے۔ دیکھئے (سنن الدارقطنی: ۲/ ۲۰۷، مع التعلیق المغنی، مزید دیکھیے: سبل السلام مع تعلیق الالبانی: ۲/ ۴۵۳) روایت کا صحیح مفہوم سمجھنے کے لیے دیکھئے احادیث: ۲۲۶۹، ۲۲۷۶۔"}],[2316,"سلمہ بن الاکوع رضی اللہ عنہ کہتے ہیں کہ جب آیت کریمہ: «وعلى الذين يطيقونه فدية طعام مسكين» \"جو لوگ اس کی طاقت رکھتے ہوں (اور وہ روزہ نہ رکھنا چاہیں) تو ان کا فدیہ یہ ہے کہ کسی مسکین کو دو وقت کا کھانا کھلائیں\" (البقرہ: ۱۸۴) نازل ہوئی تو ہم میں سے جو شخص چاہتا کہ وہ افطار کرے (کھائے پئے) اور فدیہ دیدے (تو وہ ایسا کر لیتا) یہاں کہ اس کے بعد والی آیت نازل ہوئی تو اس نے اسے منسوخ کر دیا ۱؎۔\n§وضاحت\n۱؎: بعد والی آیت سے مراد سورۃ البقرہ کی یہ آیت ہے «فمن شہد منکم الشھر فلیصمہ» یعنی \" تم میں سے جو بھی آدمی رمضان کا مہینہ پائے وہ روزہ رکھے \"۔","الألباني: صحيح",{"u2":"حضرت سلمہ بن اکوع رضی اللہ عنہ بیان کرتے ہیں کہ جب یہ آیت اتری: {وَ عَلَی الَّذِیْنَ یُطِیْقُوْنَہٗ فِدْیَۃٌ طَعَامُ مِسْکِیْنٍ} ’’جو لوگ روزہ کی طاقت رکھتے ہیں وہ فدیہ دیں ایک مسکین کا کھانا۔‘‘ تو ہم میں سے جو شخص روزے نہ رکھنا چاہتا، وہ فدیہ دے دیتا حتیٰ کہ اس کے بعد والی آیت اتری اور اس نے اسے منسوخ کر دیا۔","f2":"(۱)فرضیت روزہ کے ابتدائی دور میں روزہ فرض تو تھا مگر کوئی شخص بلا عذر روزہ چھوڑنا چاہتا تو اسے اجازت تھی کہ روزہ نہ رکھے مگر اسے فدیہ دینا پڑتا تھا، پھر بعد میں دوسری آیت اتری: {فَمَنْ شَہِدَ مِنْکُمُ الشَّہْرَ فَلْیَصُمْہُ} ’’تم میں سے جو شخص اس مہینے میں موجود ہو، وہ لازماً روزہ رکھے۔‘‘ تو اس سے فدیہ والی رخصت ختم ہوگئی اور ہر تندرست اور گھر میں موجود شخص کے لیے روزہ رکھنا لازم ہوگیا، البتہ یہ رخصت اس شخص کے لیے باقی ہے جو انتہائی ضعیف ہونے کی وجہ سے روزہ نبھا نہیں سکتا اور اس کی قوت وصحت کی بھی کوئی امید نہیں۔ (۲)قرآن میں نسخ ثابت ہے اور اس پر امت کا اجماع ہے۔ (۳)فرضت روزہ کا تدریجی حکم امت مسلمہ کی آسانی کے لیے تھا۔"}],[2317,"عبداللہ بن عباس رضی اللہ عنہما آیت کریمہ: «وعلى الذين يطيقونه» میں «يطيقونه» کی تفسیر میں کہتے ہیں معنی یہ ہے کہ جو لوگ روزہ رکھنے کے مکلف ہیں، (تو ہر روزہ کے بدلے) ان پر ایک مسکین کے دونوں وقت کے کھانے کا فدیہ ہے، (اور جو شخص ازراہ ثواب و نیکی و بھلائی) ایک سے زیادہ مسکین کو کھانا دے دیں تو یہ منسوخ نہیں ہے، (یہ اچھی بات ہے، اور زیادہ بہتر بات یہ ہے کہ روزہ ہی رکھے جائیں) یہ رخصت صرف اس شخص کے لیے ہے جو روزہ کی طاقت نہ رکھتا ہو، یا بیمار ہو اور اچھا نہ ہو پا رہا ہو۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے اللہ تعالیٰ کے فرمان:{وَ عَلَی الَّذِیْنَ یُطِیْقُوْنَہٗ فِدْیَۃٌ طَعَامُ مِسْکِیْنٍ} کے بارے میں منقول ہے کہ اس آیت میں {یُطِیْقُوْنَہٗ} سے مراد ہے کہ جو لوگ انتہائی مشقت محسوس کریں (یعنی انتہائی بوڑھے جن کی صحت کی امید نہیں) وہ (روزہ رکھنے کے بجائے) ایک مسکین کا کھانا بطوبر فدیہ دیں۔ اور اس سے اگلے الفاظ {فَمَنْ تَطَوَّعَ خَیْرًا فَہُوَ خَیْرٌ لَّہٗ} ’’جو شخص خوشی سے نیکی کرے تو اچھی بات ہے۔‘‘ سے مراد ہے کہ جو شخص ایک سے زائد مسکین کا کھانا فدیہ میں دے دے تو یہ بہت اچھا ہے۔ تو (اس معنی کے لحاظ سے) یہ آیت منسوخ نہیں۔ اور (انتہائی مشقت کے باوجود) کوئی شخص روزہ رکھے تو بہتر ہے، لہٰذا روزہ چھوڑنے اور فدیہ دینے کی رخصت صرف اس شخص کو ہے جو (انتہائی بڑھاپے کی وجہ سے) روزہ برداشت نہیں کر سکتا۔ یا وہ مریض جس کی صحت کی کوئی امید نہیں۔","f2":"(۱)آیت کا اصل مفہوم تو وہی ہے جو حدیث: ۲۳۱۸ کے تحت بیان ہوا مگر حضرت ابن عباس رضی اللہ عنہ چونکہ ذہین شخص تھے، نیز انہیں رسول اللہ صلی اللہ علیہ وسلم کی خصوصی دعا بھی تھی، لہٰذا انہوں نے یہ مفہوم بیان کیا ہے کہ [یُطِیْقُوْنَ] سے مراد وہ انتہائی بوڑھے یا دائمی بیمار ہیں جو روزہ برداشت نہیں کر سکتے اور اس کے بعد بھی ان کے لیے قوت اور صحت کی کوئی امید نہیں تو وہ روزہ نہ رکھیں اور فدیہ دے دیں۔ چونکہ یہ مسئلہ شریعت اسلامیہ میں الگ طور پر ثابت ہے اور لغت کی مدد سے یہ معنی اس آیت کے بھی بن سکتے ہیں، لہٰذا یہ معنی مراد لینے میں کوئی حرج نہیں۔ قرآن مجید کی بلاغت کا ایک اعجاز یہ بھی ہے کہ بعض آیات میں ایک جملے کے دو ایسے معنی مراد لیے جا سکتے ہیں جو ایک دوسرے مختلف ہیں (لیکن دونوں شرعاً صحیح ہیں) ایک معنی سیاق وسباق کے لحاظ سے اور دوسرے معنی لغت یا کسی اور لحاظ سے۔ لیکن یہ یاد رہے کہ ایسا اس وقت ہوگا جب وہ دونوں معانی الگ طور پر شرعاً ثابت ہوں اور ان کے ثبو ت کے لیے قرآن وحدیث میں دلائل موجود ہوں۔ ورنہ صرف لغت یا صرف سیاق وسباق کے لحاظ سے قرآن مجید کی تفسیر کرنا جبکہ اس تفسیر کا نصوص سے تعارض ہو، تفسیر بالرائے ہے جو انتہائی بڑا گناہ ہے اور اس پر ہمیشہ کے لیے جہنم کی وعید ہے۔ (۲) بہر صورت اس آیت کے دونوں معانی کا نتیجہ متفق علیہ ہے کہ جو شخص روزے کی طاقت رکھتا ہے، اب وہ روزہ نہیں چھوڑ سکتا کیونکہ اگر پہلے معنی مراد ہیں تو یہ آیت منسوخ ہے اور اس کی صراحت اسی حدیث میں ہے۔ اور اگر دوسرے معنی مراد ہیں تو اس آیت کو منسوخ کہنے کی ضرورت نہیں جیسا کہ حضرت ابن عباس رضی اللہ عنہ نے فرمایا۔ اب کوئی شخص یہ نہیں کر سکتا کہ ترجمہ تو پہلی حدیث والا کرے اور دوسرے حدیث کی بنا پر اسے غیر منسوخ کہے اور ہر شخص کو روزہ چھوڑنے اور فدیہ دینے کی اجازت دے دے کیونکہ یہ قرآن وحدیث اور اجماع امت کے خلاف ہے اور بددیانتی ہے۔"}],[2318,"معاذہ عدویہ سے روایت ہے کہ ایک عورت نے ام المؤمنین عائشہ رضی اللہ عنہا سے پوچھا: کیا عورت جب حیض سے پاک ہو جائے تو نماز کی قضاء کرے؟ انہوں نے کہا: کیا تو حروریہ ۱؎ ہے؟ ہم عورتیں رسول اللہ صلی اللہ علیہ وسلم کے زمانہ میں حیض سے ہوتی تھیں، پھر ہم پاک ہوتیں تو آپ ہمیں روزہ کی قضاء کا حکم دیتے تھے، اور نماز کی قضاء کے لیے نہیں کہتے تھے۔\n§وضاحت\n۱؎: حروریۃ حروراء کی طرف منسوب ہے، جو کوفہ کے قریب ایک جگہ ہے، چونکہ خوارج یہیں جمع تھے اس لیے اسی کی طرف منسوب کر کے حروری کہلاتے تھے، یہ لوگ حیض کے دنوں میں فوت شدہ نمازوں کی قضاء کو واجب قرار دیتے تھے۔","الألباني: صحيح",{"u2":"حضرت معاذہ عدویہ سے منقول ہے کہ ایک عورت نے حضرت عائشہ رضی اللہ عنہا سے پوچھا: کیا حیض والی عورت پاک ہونے کے بعد نماز کی قضا ادا کرے گی؟ حضرت عائشہ رضی اللہ عنہا نے فرمایا: کیا تو خارجی عورت ہے؟ ہمیں بھی رسول اللہ صلی اللہ علیہ وسلم کے دور مسعود میں حیض آتا تھا، پھر ہم پاک ہوتی تھیں تو رسول اللہ صلی اللہ علیہ وسلم ہمیں روزوں کی قضا ادا کرنے کا حکم تو دیتے تھے مگر نماز کی قضا اد کرنے کا حکم نہیں دیتے تھے۔","f2":"(۱)حیض کی حالت میں نماز اور روزے سے شرعاً روک دیا گیا ہے۔ نماز سے تو اس لیے کہ نماز کے لیے طہارت شرط ہے، البتہ روزے سے روکنے کی کوئی خصوصی وجہ بیان نہیں کی گئی، مگر یہ مسئلہ متفق علیہ اور قطعی ہے اور اس میں کوئی شک نہیں۔ (۲)حیض ختم ہونے کے بعد فرض روزے کی قضا ادا کرنا بھی قطعی مسئلہ ہے اور متفق علیہ ہے، لہٰذا معافی سے مراد وقتی معافی ہے، البتہ نماز کی قضا نہیں، شاید اس لیے کہ مدت حیض کی تمام نمازوذں کی مہر مہینے قضا ادا کرنا عورت کے لیے شدید مشکلات کا سبب بن سکتی ہے جبکہ چند روزوں کی قضا ادا کرنا سارے سال کے دوران میں آسان ہے اور شریعت لوگوں کی آسانی کو مدنظر رکھتی ہے۔ (۳)’’کیا تو خارجی عورت ہے؟‘‘ کیونکہ خوارج عورت پر حیض کے دنوں کی نمازوں کی قضا ادا کرنا ضروری خیال کرتے تھے۔ ’’خاجی‘‘ فرقہ انتہائی متشدد اور دینی حکمتوں سے بے بہرہ افراد کا گروہ تھا، جو صحابہ کے دور میں ظاہر ہوا۔ یہ اپنے آپ کو صحابہ کرام رضی اللہ عنہم سے بڑھ کر دین اسلام کا پابند اور محافظ سمجھتا تھا حتیٰ کہ ان بے وقوف لوگوں کے ہاتھوں کئی صحابہ شہید ہوئے اور انہوں نے کثیر صحابہ پر (جن میں حضرت عثمان اور حضرت علی رضی اللہ عنہ بھی شامل تھے) کفر کے فتوے لگائے۔ آخر کار امیرالمومنین حضرت علی رضی اللہ عنہ کو ان سے جنگ کرنی پڑی، تب ان کا زور ٹوٹا۔ (۴) خارجیوں کو ’’حروری‘‘ اس لیے کہا جاتا تھا کہ ان کے فتنے کی ابتدا کوفے کے قریب ایک بستی حرورا ء سے ہوئی۔ مجازاً پورے فرقے کو حروری کہہ لیا جاتا تھا۔"}],[2319,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ مجھ پر رمضان کے روزہ ہوتے تھے تو میں قضاء نہیں کر پاتی تھی یہاں تک کہ شعبان آ جاتا۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ مجھ پر رمضان المبارک کے کچھ روزے (حیض کی وجہ سے) واجب الادارہ جاتے تھے تو میں ان کی قضا ادا نہیں کر سکتی تھی، یہاں تک کہ شعبان آجاتا تھا۔","f2":"گویا دس ماہ بعد شعبان میں سابقہ رمضان المبارک کے رہ جانے والے روزوں کی قضا ادا کرتی تھیں۔ اس حدیث سے جہاں یہ معلوم ہوتا ہے کہ فرض روزوں کی قضا ادا کرنا فوراً ضروری نہیں، سارے سال میں کسی بھی وقت قضا ادا کرنا ممکن ہے، لیکن جلدی قضا کی ادائیگی کی کوشش کرنا ہی افضل ہے بیماری یا موت کا کوئی پتا ہے؟ وہاں یہ بھی ثابت ہوتا ہے کہ حائضہ کو قضا ادا کرنا معاف نہیں بلکہ وہ روزے بہر صورت بعد میں رکھنے ہوں گے۔ حضرت عائشہ رضی اللہ عنہا سے قضا ادا کرنے کی تاخیر کا سبب بھی منقول ہے کہ ایسا نہ ہو، نبی اکرم صلی اللہ علیہ وسلم کو میری ضرورت محسوس ہو اور میں روزے سے ہوں۔ شعبان میں رسول اللہ صلی اللہ علیہ وسلم بھی اکثر روزے سے ہوتے تھے۔ (مزید تفصیل کے لیے دیکھئے، حدیث: ۲۱۸۰)"}],[2320,"محمد بن صیفی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے عاشوراء کے دن فرمایا: \"کیا تم میں سے کسی نے آج کے دن کھایا ہے؟\" لوگوں نے کہا: ہم میں کچھ لوگ ایسے ہیں جن ہوں نے روزہ رکھا ہے، اور کچھ لوگوں نے نہیں رکھا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اپنا باقی دن (بغیر کھائے پیئے) پورا کرو ۱؎، اہل عروض ۲؎ کو خبر کرا دو کہ وہ بھی اپنا باقی دن (بغیر کھائے پئے) پورا کریں\"۔\n§وضاحت\n۱؎: اپنا باقی دن بغیر کھائے پیئے پورا کرو، اسی جملہ سے ترجمۃ الباب پر استدلال ہے، اس میں روزہ رکھنے والوں اور روزہ نہ رکھنے والوں دونوں کو اتمام کا حکم ہے۔ ۲؎: عروض کا اطلاق مکہ، مدینہ اور اس کے اطراف پر ہوتا ہے۔","الألباني: صحيح",{"u2":"حضرت محمد بن صیفی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے عاشورائ رضی اللہ عنہ (دس محرم الحرام) کے دن فرمایا: ’’کیا تم میں سے کسی نے آج کھانا کھایا ہے؟‘‘ لوگوں نے عرض کیا: کچھ لوگوں نے روزہ رکھا ہے اور کچھ نے نہیں۔ آپ نے فرمایا: ’’پھر باقی دن کچھ نہ کھانا، نیز مدینہ منورہ کے قرب وجوار بستیوں میں پیغام بھیج دو کہ وہ باقی دن کچھ نہ کھائیں پئیں۔‘‘","f2":"(۱)یوم عاشوراء سے متعلق مجموعی احادیث سے ثابت ہوتا ہے کہ اس دن کا روزہ فرض تھا کیونکہ رسول اللہ صلی اللہ علیہ وسلم سے مختلف احادیث میں اس کے منتعلق حکم منقول ہے۔ مزید تفصیل کے لیے ملاحظہ فرمائیے: (فتح الباری: ۴/ ۲۴۷) یہ اعلان آپ نے دن چڑھے فرمایا، شاید فرضیت کا حکم اسی وقت آیا ہو۔ (۲)’’باقی دن کچھ نہ کھانا‘‘ خواہ پہلے کھانا کھا ہی چکا ہو۔ اس صورت میں روزہ صحیح ہوگا، اور شرعاً قابل اعتبار، نیز اس کی جگہ بعد میں روزہ رکھنا ضروری نہیں، یہی موقف حق ہے کیونکہ اس کی قضا ادا کرنے کا حکم نہیں، جس روایت میں قضا کا حکم ہے وہ سنداً ناقابل حجت اور ضعیف ہے۔ دیکھئے: (سنن ابی داؤد، حدیث: ۲۴۴۷) جیسے بھول کر کھانے پینے والے کا شرعاً مؤاخذہ نہیں اور نہ اس کا روزہ ہی فاسد ہوتا ہے، یہی توجیہ زیر بحث مسئلے میں ہو سکتی ہے۔ واللہ اعلم! امام نسائی رحمہ اللہ نے حائضہ اور مسافر کو بھی اسی پر قیاس فرمایا ہے کہ اگر دن کے دوران میں ان کا عذر ختم ہو جائے تو وہ باقی دن کچھ نہ کھائیں پئیں، خواہ پہلے کچھ کھایا پیا ہو یا نہ۔ لیکن اب رکنا لازمی ہے۔ (۳)’’قرب وجوار بستیوں‘‘ عربی میں لفظ ’’عروض‘‘ استعمال ہوا ہے، جس سے مراد مکہ، مدینہ اور یمن کا تمام علاقہ ہے، لیکن ظاہر ہے اس وقت یہ اعلان اتنے علاقے میں تو نہیں ہو سکتا تھا، اس لیے مندرجہ بالا معنی کیے گئے کیونکہ اس وقت یہی ممکن تھا۔ (۴)طلوع فجر صادق سے قبل روزے کی نیت اس کے لیے ضروری ہے جسے علم ہو کہ صبح کو روزہ ہے۔ جسے پتا ہی دن کے وقت چلے کہ آج روزہ ہے، تو اگر اس نے طلوع فجر کے بعد اس وقت تک کچھ نہیں کھایا، وہ روزے کی نیت کر سکتا ہے اور اس کی دن کی نیت معتبر ہوگی۔"}],[2321,"سلمہ بن الاکوع رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص سے کہا: \"لوگوں میں عاشوراء کے دن اعلان کر دو: جس نے کھا لیا ہے وہ باقی دن (بغیر کھائے پیئے) پورا کرے، اور جس نے نہ کھایا ہو وہ روزہ رکھے\"۔","الألباني: صحيح",{"u2":"حضرت سلمہ رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے ایک آدمی کو عاشوراء کے دن حکم دیا کہ اعلان کرو: ’’جس نے کچھ کھا لیا ہے، وہ باقی دن نہ کھائے پیے اور جس نے کچھ نہیں کھایا، وہ روزہ رکھ لے۔‘‘","f2":"گویا امام نسائی رحمہ اللہ کے نزدیک عاشوراء کا روزہ مستحب ہے، تبھی تو انہوں نے اس حدیث سے ترجمۃ الباب کا مسئلہ استنباط کیا ہے کہ دن کے وقت بھی روزے کی نیت کر کے نفلی روزہ شروع کیا جا سکتا ہے (جیسا کہ حدیث: ۲۳۲۴ میں ہے) بشرطیکہ اس نے طلوع فجر کے بعد سے کچھ کھایا پیا نہ ہو۔ یہ استنباط تو درست ہے لیکن اس کے لیے مندرجہ بالا حدیث کو محل استشہاد بنانا درست نہیں کیونکہ راجح موقف کے مطابق عاشوراء شروع میں فرض تھا یہاں زیادہ سے زیادہ یہ کہا جا سکتا ہے کہ روزے کی فرضیت کا پتا نہ ہو تو جب بھی اطلاع ملے، اس وقت کچھ کھایا ہو یا نہ، رک جائے اور باقی دن روزے کی تکمیل کرے۔"}],[2322,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ایک دن میرے پاس آئے، اور پوچھا: \"کیا تمہارے پاس کچھ (کھانے کو) ہے؟\" تو میں نے کہا: نہیں، آپ نے فرمایا: \"تو میں روزہ سے ہوں\"، اس دن کے بعد پھر ایک دن آپ میرے پاس سے گزرے، اس دن میرے پاس تحفہ میں حیس ۱؎ آیا ہوا تھا، میں نے اس میں سے آپ کے لیے نکال کر چھپا رکھا تھا، آپ کو حیس بہت پسند تھا، انہوں نے عرض کیا: اللہ کے رسول! مجھے حیس تحفے میں دیا گیا ہے، میں نے اس میں سے آپ کے لیے چھپا کر رکھا ہے، آپ نے فرمایا: \"لاؤ حاضر کرو، اگرچہ میں نے صبح سے ہی روزہ کی نیت کر رکھی ہے\" (مگر کھاؤ گا) تو آپ صلی اللہ علیہ وسلم نے کھایا، پھر فرمایا: \"نفلی روزہ کی مثال اس آدمی کی سی ہے جو اپنے مال میں سے (نفلی) صدقہ نکالتا ہے، جی چاہا دے دیا، جی چاہا نہیں دیا، روک لیا\"۔\n§وضاحت\n۱؎: حیس ایک کھانا ہے جو کھجور، پنیر، گھی اور آٹے سے بنایا جاتا ہے۔","الألباني: حسن",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ ایک دن رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف لائے اور فرمایا: ’’کیا تمہارے پاس کوئی کھانے کی چیز ہے؟‘‘ میں نے کہا: نہیں۔ آپ نے فرمایا: ’’چلو میں روزہ رکھ لیتا ہوں۔‘‘ پھر کسی اور دن میرے پاس سے گزرے۔ اتفاقاً اس وقت مجھے حیس کا تحفہ آیا ہوا تھا اور میں نے آپ کے لیے کچھ رکھ چھوڑا تھا۔ آپ حیس کو بہت پسند فرماتے تھے۔ میں نے عرض کیا: اے اللہ کے رسول! ہمارے پاس حیس کا تحفہ آیا ہے اور میں نے آپ کے لیے کچھ محفوظ رکھا ہوا ہے۔ آپ نے فرمایا: ’’لاؤ پیش کرو۔ میں نے تو آج روزے کی نیت کر رکھی تھی۔‘‘ پھر آپ نے وہ حیس کھایا اور فرمایا: ’’نفل روزے کی مثال ایسی ہے جیسے آدمی اپنے مال سے صدقہ نکالے، پھر چاہے اسے خرچ کر دے، چاہے اپنے پاس رکھ لے۔‘‘","f2":"(۱) حیس یہ عربوں میں ایک معروف کھانا تھا جو کھجور، پنیر اور گھی وغیرہ سے تیار کیا جاتا تھا۔ چونکہ کھانے مختلف ہوتے ہیں اور ہر قوم کے اپنے اپنے کھانے ہوتے ہین، لہٰذا دوسری زبان میں ہر کھانے کا ترجمہ ممکن نہیں، خصوصاً جبکہ یہ کھانا ہمارے ہاں تیار ہی نہیں کیا جاتا تو اس کا نام کیسے ہوگا؟ (۲)نفل روزے کو بلا وجہ ختم کیا جا سکتا ہے کیونکہ نفل عبادت انسان کی اپنی مرضی پر موقوف ہوتی ہے۔ ایسے روزے کی قضا ادا کرنا واجب نہیں کیونکہ جب اصل روزہ ہی نفل ہے تو قضا ادا کرنی کیسے واجب ہو سکتی ہے؟ البتہ جواز میں کوئی شبہ نہیں، جیسے وتر کہ نبی اکرم صلی اللہ علیہ وسلم ان کی قضا ادا کیا کرتے تھے اور امت کو بھی اس کی ترغیب دی۔ (۳)بعض اہل علم نے نفل روزے کی نیت کو نصف النہار سے قبل ضروری قرار دیا ہے تاکہ اکثر روزہ نیت کے ساتھ ہو اور یہ معقول بات ہے۔ (۴)نبی اکرم صلی اللہ علیہ وسلم کائنات کے زاہد اور متقی ترین انسان تھے۔ آپ کی نظر دنیاوی ملذذات کے بجائے ہمیشہ اخروی نعمتوں پر ہوتی تھی… صلی اللہ علیہ وسلم … (۵) صحابہ کرام رضی اللہ عنہم طعام وشراب میں نبی اکرم صلی اللہ علیہ وسلم کو یاد رکھتے تھے۔ آپ صلی اللہ علیہ وسلم کو تحفے تحائف بھیج کر اپنی عقیدت ومحبت کا اظہار کرتے رہتے تھے۔ رضی اللہ عنہ م ورضواعنہ۔ (۶) اچھے واعظ کی نشانی ہے کہ وہ مثالوں سے اپنی بات سامعین کے ذہنوں میں اچھی طرح نقش کر دیتا ہے۔ مثال سے بات اچھی طرح سمجھ میں آجاتی ہے۔ (۷) کوئی چیز نفلی صدقے کی نیت سے علیحدہ کرنا اور پھر اسے صدقہ نہ کرنا جائز ہے۔"}],[2323,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ایک بار رسول اللہ صلی اللہ علیہ وسلم گھوم کر میرے پاس آئے اور پوچھا: \"تمہارے پاس کوئی چیز (کھانے کی) ہے؟\"میں نے عرض کیا، میرے پاس کوئی چیز نہیں ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"پھر تو میں روزہ رکھ لیتا ہوں\"، پھر ایک اور بار میرے پاس آئے، اس وقت ہمارے پاس حیس ہدیہ میں آیا ہوا تھا، تو میں اسے لے کر آپ کے پاس حاضر ہوئی تو آپ نے اسے کھایا، تو مجھے اس بات سے حیرت ہوئی، میں نے عرض کیا: اللہ کے رسول! آپ ہمارے پاس آئے تو روزہ سے تھے پھر بھی آپ صلی اللہ علیہ وسلم نے حیس کھا لیا؟ آپ نے فرمایا: \"ہاں عائشہ! جس نے کوئی روزہ رکھا لیکن وہ روزہ رمضان کا یا رمضان کی قضاء کا نہ ہو، یا نفلی روزہ ہو تو وہ اس شخص کی طرح ہے جس نے اپنے مال میں سے (نفلی) صدقہ نکالا، پھر اس میں سے جتنا چاہا سخاوت کر کے دے دیا اور جو بچ رہا بخیلی کر کے اسے روک لیا\" ۱؎۔\n§وضاحت\n۱؎: اس سے نفلی روزے کے توڑنے کا جواز ثابت ہوا، نیز یہ بھی معلوم ہوا کہ نفلی روزہ توڑ دینے پر اس کی قضاء واجب نہیں، جمہور کا مسلک یہی ہے۔","الألباني: حسن",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ ایک دفعہ رسول اللہ صلی اللہ علیہ وسلم نے میرے پاس چکر لگایا اور فرمایا: ’’تمہارے پاس کوئی کھانے کی چیز ہے؟‘‘ میں نے عرض کیا: میرے پاس کوئی چیز نہیں ہے۔ آپ نے فرمایا: ’’پھر میں روزہ رکھ لیتا ہوں۔‘‘ پھر (کسی دن) دوبارہ تشریف لائے۔ اتفاقاً ہمارے پاس حیس کا تحفہ آیا تھا۔ میں آپ کے پاس لائی تو آپ نے کھا لیا۔ مجھے اس پر تعجب ہوا۔ میں نے کہا: اے اللہ کے رسول! آپ تشریف لائے تو آپ کا روزہ تھا، پھر آپ نے حیس کھا لیا؟ آپ نے فرمایا: ’’عائشہ! ہاں۔ رمضان یا قضائے رمضان کے علاوہ نفل روزے رکھنے والے کی مثال تو اس شخص کی طرح ہے جس نے اپنے مال کا صدقہ نکالا تو جس قدر چاہا خرچ کر دیا اور اس کا ثواب حاصل کرل یا اور جتنا چاہا کنجوسی کرتے ہوئے رکھ لیا۔‘‘"}],[2324,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم تشریف لاتے تھے اور پوچھتے تھے: \"کیا تمہارے پاس کھانا ہے؟\" میں کہتی تھی: نہیں، تو آپ فرماتے تھے: \"میں روزہ سے ہوں\"، ایک دن آپ ہمارے پاس تشریف لائے، اس دن ہمارے پاس حیس کا ہدیہ آیا ہوا تھا، آپ نے کہا: \"کیا تم لوگوں کے پاس کھانے کی کوئی چیز ہے؟\" ہم نے کہا: جی ہاں ہے، ہمارے پاس ہدیہ میں حیس آیا ہوا ہے، آپ نے فرمایا: \"میں نے صبح روزہ رکھنے کا ارادہ کیا تھا\"، پھر آپ نے(اسے) کھایا۔ قاسم بن یزید نے ان کی یعنی ابوبکر حنفی کی مخالفت کی ہے ۱؎، (ان کی روایت آگے آ رہی ہے)۔\n§وضاحت\n۱؎: سند میں مخالفت اس طرح ہے کہ ابوبکر والی روایت میں طلحہ بن یحیی اور ام المؤمنین عائشہ رضی اللہ عنہا کے درمیان مجاہد کا واسطہ ہے اور قاسم کی روایت میں عائشہ بنت طلحہ کا، نیز دونوں روایتوں کے متن کے الفاظ بھی مختلف ہیں۔","الألباني: حسن صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ کبھی رسول اللہ صلی اللہ علیہ وسلم تشریف لاتے اور فرماتے: ’’تمہارے پاس کھانا ہے؟‘‘ میں عرض کرتی کہ نہیں۔ آپ فرماتے: ’’میں روزہ رکھ لیتا ہوں۔‘‘ آپ ایک دن ہمارے پاس تشریف لائے۔ اتفاقاً ہمارے پاس حیس کا تحفہ آیا تھا۔ آپ نے فرمایا: ’’کوئی کھانے کی چیز ہے؟‘‘ میں نے عرض کیا: جی ہاں۔ حیس کا تحفہ آیا ہوا ہے۔ آپ نے فرمایا: ’’آج میری نیت روزے کی تھی۔‘‘ پھر آپ نے (حیس) کھا لیا۔\nقاسم بن یزید نے (اپنے ساتھی ابوبکر کی) مخالفت کی ہے۔","f2":"اس کا بیان پیچھے ہو چکا ہے کہ قاسم نے طلحہ کا استاد مجاہد کے بجائے عائشہ بنت طلحہ بتایا ہے۔ آگے آنے والی ایک حدیث: (۲۳۳۰) میں دونوں مذکور ہیں، گویا کہ دونوں کا ذکر صحیح ہے۔ باب: ۶۷ کے تحت مذکور وضاحت ملاحظہ فرمائیے۔"}],[2325,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ایک دن رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف لائے، ہم نے عرض کیا: ہمارے پاس حیس کا تحفہ بھیجا گیا، ہم نے اس میں آپ کا (بھی) حصہ لگایا ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں روزہ سے ہوں\"، پھر آپ نے روزہ توڑ دیا۔","الألباني: حسن صحيح",{"u2":"حضرت عائشہ ام المومنین رضی اللہ عنہا فرماتی ہیں کہ ایک دن رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف لائے۔ میں نے کہا: ہمارے پاس حیس کا تحفہ آیا ہے۔ میں نے آپ کا حصہ سنبھال کر رکھا ہوا ہے۔ آپ نے فرمایا: ’’تحقیق میں نے روزے کی نیت کی ہوئی تھی۔‘‘ پھر آپ نے روزہ ختم کر دیا۔"}],[2326,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں: نبی اکرم صلی اللہ علیہ وسلم ان کے پاس آتے تھے اور آپ روزہ سے ہوتے تھے (اس کے باوجود) پوچھتے تھے: \"تمہارے پاس رات کی کوئی چیز ہے جسے تم مجھے کھلا سکو؟\" ہم کہتے نہیں۔ تو آپ صلی اللہ علیہ وسلم فرماتے: \"میں نے روزہ رکھ لیا\" پھر اس کے بعد ایک بار آپ ان کے پاس آئے، تو انہوں نے کہا: ہمارے پاس ہدیہ آیا ہوا ہے آپ نے پوچھا: \"کیا ہے؟\" انہوں نے عرض کیا: حیس ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں نے صبح روزہ کا ارادہ کیا تھا\" پھر آپ نے کھایا۔","الألباني: حسن صحيح",{"u2":"ام المومنین حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ بسا اوقات رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف لاتے۔ آپ کا روزہ ہوتا۔ آپ فرماتے: ’’تمہارے پاس کھانے کی کوئی چیز ہے؟‘‘ میں کہتی: نہیں۔ آپ فرماتے: ’’چلو، میرا روزہ ہے۔‘‘ پھر اس کے بعد ایک دن آئے تو میں نے کہا: آج ہمارے پاس تحفہ آیا ہے۔ آپ نے فرمایا: ’’کیا؟‘‘ میں نے کہا: حیس۔ آپ نے فرمایا: ’’میں نے آج صبح روزے کی نیت کی تھی۔‘‘ پھر آپ نے کھا لیا۔"}],[2327,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ایک دن میرے پاس تشریف لائے اور پوچھا: \"تمہارے پاس (کھانے کی) کوئی چیز ہے؟\" ہم نے کہا: نہیں۔ آپ نے فرمایا: \"تو میں روزہ سے ہوں\"۔","الألباني: حسن صحيح",{"u2":"ام المومنین حضرت عائشہ رضی اللہ عنہا سے مروی ہے کہ ایک دن رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف لائے اور فرمایا: ’’تمہارے پاس (کھانے کی) کوئی چیز ہے؟‘‘ ہم نے کہا: نہیں۔ آپ نے فرمایا: ’’میں روزہ رکھ لیتا ہوں۔‘‘"}],[2328,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ان کے پاس تشریف لائے، پوچھا: \"کیا تمہارے پاس کچھ کھانا ہے؟\" میں نے کہا: نہیں، آپ نے فرمایا: \"تو میں روزہ سے ہوں\"، پھر آپ ایک اور دن تشریف لائے، تو عائشہ رضی اللہ عنہا نے آپ سے کہا: اللہ کے رسول! ہمارے پاس ہدیہ میں حیس آیا ہوا ہے، تو آپ نے اسے منگوایا، اور فرمایا: \"میں نے صبح روزہ کی نیت کی تھی\"، پھر آپ نے کھایا۔","الألباني: حسن صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف لائے اور فرمانے لگے: ’’تمہارے پاس کھانا ہے؟‘‘ ہم نے کہا: نہیں۔ آپ نے فرمایا: ’’پھر میرا روزہ ہے۔‘‘ پھر ایک اور دن تشریف لائے۔ میں نے کہا: اے اللہ کے رسول! ہمارے پاس حیس کا تحفہ بھیجا گیا ہے۔ آپ نے منگوانا، پھر فرمایا: ’’بلا شبہ میں نے آج صبح روزے کی نیت کی تھی۔‘‘ پھر آپ نے کھا لیا۔"}],[2329,"مجاہد اور ام کلثوم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم ام المؤمنین عائشہ رضی اللہ عنہا کے پاس تشریف لے گئے، اور ان سے پوچھا: \"کیا تمہارے پاس کچھ کھانا ہے؟\" آگے اسی طرح ہے جیسے اس سے پہلی روایت میں ہے۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: اور اسے سماک بن حرب نے بھی روایت کیا ہے۔ وہ کہتے ہیں: مجھ سے ایک شخص نے روایت کی اور اس نے عائشہ بنت طلحہ سے روایت کی ہے (ان کی روایت آگے آ رہی ہے)۔","",{"u2":"حضرت مجاہد اور ام کلثوم سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم حضرت عائشہ رضی اللہ عنہا کے ہاں تشریف لے گئے اور فرمایا: ’’تمہارے پاس کچھ کھانا ہے؟‘‘ باقی روایت سابقہ روایت کی طرح ہے۔\nامام ابوعبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ سماک بن حرب نے اس روایت کو عن رجل عن عائشۃ بنت طلحۃ کے طریق سے بیان کیا ہے۔ (یعنی آدمی کو مبہم رکھا ہے۔ اگلی حدیث سماک ہی کی ہے۔ ملاحظہ فرمائیے۔"}],[2330,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ایک دن رسول اللہ صلی اللہ علیہ وسلم آئے اور پوچھا: \"کیا تمہارے پاس کچھ کھانا ہے؟\" میں نے عرض کیا: نہیں، آپ نے فرمایا: \"پھر تو میں روزہ رکھ لیتا ہوں\"، پھر دوسری بار آپ میرے پاس تشریف لے آئے تو میں نے عرض کیا: اللہ کے رسول! ہمارے پاس حیس کا ہدیہ آیا ہوا ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تب تو میں آج روزہ توڑ دوں گا حالانکہ میں نے روزہ کی نیت کر لی تھی\"۔","الألباني: صحيح لغيره",{"u2":"ام المومنین حضرت عائشہ رضی اللہ عنہا سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم ایک دن تشریف لائے اور فرمایا: ’’تمہارے پاس کوئی کھانا ہے؟‘‘ میں نے کہا: نہیں۔ آپ نے فرمایا: ’’تو پھر میں روزہ رکھ لیتا ہوں۔‘‘ حضرت عائشہ رضی اللہ عنہا کہتی ہیں کہ پھر ایک اور دفعہ آپ تشریف لائے تو میں نے عرض کیا: اے اللہ کے رسول! ہمارے ہاں حیس کا تحفہ آیا ہے۔ آپ نے فرمایا: ’’تو پھر آج میں روزہ کھول لیتا ہوں۔ ویسے میں نے روزے کی نیت کی ہوئی تھی۔‘‘"}],[2331,"ام المؤمنین حفصہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص طلوع فجر سے پہلے روزہ کی نیت نہ کرے تو اس کا روزہ نہ ہو گا\" ۱؎۔\n§وضاحت\n۱؎: یہ حکم فرض روزوں کے سلسلہ میں ہے یا قضاء اور کفارہ کے روزوں کے سلسلہ میں، نفلی روزے کے لیے رات میں نیت ضروری نہیں، جیسا کہ ابھی عائشہ رضی اللہ عنہا کی حدیث سے معلوم ہوا۔","الألباني: صحيح",{"u2":"حضرت حفصہ رضی اللہ عنہا سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص طلوع فجر سے پہلے رات کے وقت روزے کی نیت کرے تو اس کا روزہ نہیں ہوتا۔‘‘","f2":"(۱) مذکورہ روایت کو محقق کتاب نے سنداً ضعیف قرار دیا ہے جبکہ اسی مفہوم کی روایت: ۲۳۳۸ کو موقوفاً صحیح قرار دیا ہے۔ جس سے معلوم ہوتا ہے محقق کتاب کے نزدیک یہ روایت معناً صحیح ہے، نیز دیگر محققین نے بھی مذکورہ حدیث کو صحیح قرار دیا ہے اور ان کی تحقیق سے راجح بات یہی معلوم ہوتی ہے کہ مذکورہ روایت قابل عمل ہے۔ واللہ اعلم۔ مزید تفصیل کے لیے دیکھیے (ذخیرۃ العقبی شرح سنن النسائی: ۲۱/ ۲۴۷- ۲۵۱، وارواء الغلیل: ۴/ ۲۵-۳۰، رقم: ۹۱۴) (۲) اہل علم نے اس حدیث کو فرض یا اس کی قضا ادا کرنے اور دوسرے واجب روزوں پر محمول کیا ہے اور نفل روزے کو اس سے مستثنیٰ کیا ہے جیسا کہ مندرجہ بالاکثیر روایات سے صاف واضح ہوتا ہے۔ اس طریقے سے تمام احادیث میں تطبیق دی جا سکتی ہے، لہٰذا گردن کو پتا چلے کہ آج رمضان المبارک شروع ہو چکا ہے تو اسی وقت روزہ شروع کیا جا سکتا ہے، کچھ کھایا پیا ہو یا نہ۔"}],[2332,"ام المؤمنین حفصہ رضی اللہ عنہا کہتی ہیں نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس نے فجر سے پہلے روزہ کی نیت نہیں کی تو اس کا روزہ نہیں ہو گا\"۔","الألباني: صحيح",{"u2":"حضرت حفصہ رضی اللہ عنہا سے منقول ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص طلوع فجر سے قبل رات کو روزے کی نیت نہ کرے، اس کا روزہ نہیں ہوتا۔"}],[2333,"ام المؤمنین حفصہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص روزہ کا پختہ ارادہ طلوع فجر سے پہلے نہ کر لے تو وہ روزہ نہ رکھے\"۔","الألباني: صحيح",{"u2":"حضرت حفصہ رضی اللہ عنہا سے مروی ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص نے طلوع فجر سے پہلے روزے کی نیت نہ کی، وہ روزہ نہ رکھے۔"}],[2334,"ام المؤمنین حفصہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس نے روزہ کی نیت رات ہی میں نہ کر لی ہو تو اس کا روزہ نہیں\"۔","الألباني: صحيح",{"u2":"حضرت حفصہ رضی اللہ عنہا سے بیان ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص رات کے وقت روزے کی نیت نہ کرے، اس کا روزہ نہیں۔‘‘"}],[2335,"ام المؤمنین حفصہ رضی اللہ عنہا کہتی تھیں کہ جس نے رات ہی میں روزہ کی پختہ نیت نہ کر لی ہو تو وہ روزہ نہ رکھے۔","الألباني: صحيح موقوف وهو في حكم المرفوع",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے کہ حضرت حفصہ رضی اللہ عنہا فرمایا کرتی تھیں: جو شخص رات کے وقت روزے کی نیت نہ کرے، وہ روزہ نہ رکھے۔"}],[2336,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ ام المؤمنین حفصہ رضی اللہ عنہا کہتی ہیں: اس شخص کا روزہ نہیں جو فجر سے پہلے روزہ کی پختہ نیت نہ کر لے۔","الألباني: صحيح موقوف",{"u2":"حضرت حفصہ رضی اللہ عنہا جو کہ نبی صلی اللہ علیہ وسلم کی زوجہ مطہرہ تھیں‘ انہوں نے فرمایا: اس آدمی کا روزہ نہیں ہوتا جو طلوع فجر سے پہلے روزے کی نیت نہ کرے۔"}],[2337,"ام المؤمنین حفصہ رضی اللہ عنہا کہتی ہیں: اس شخص کا روزہ نہیں جو فجر سے پہلے روزہ کی پختہ نیت نہ کر لے۔","الألباني: صحيح موقوف",{"u2":"حضرت حفصہ رضی اللہ عنہا فرماتی ہیں کہ اس شخص کا روزہ نہیں ہوتا جو فجر سے پہلے روزے کی نیت نہیں کرتا۔"}],[2338,"ام المؤمنین حفصہ رضی اللہ عنہا کہتی ہیں کہ اس شخص کا روزہ نہیں جو فجر سے پہلے روزہ کی پختہ نیت نہ کر لے۔","الألباني: صحيح موقوف",{"u2":"حضرت حفصہ رضی اللہ عنہا فرماتی ہیں کہ جو شخص طلوع فجر سے پہلے روزے کی نیت نہیں کرتا، اس کا روزہ نہیں۔"}],[2339,"ام المؤمنین حفصہ رضی اللہ عنہا کہتی ہیں کہ اس شخص کا روزہ نہیں جو فجر سے پہلے روزہ کی پختہ نیت نہ کر لے۔","الألباني: صحيح موقوف",{"u2":"حضرت حفصہ رضی اللہ عنہا سے مروی ہے کہ جو شخص فجر سے پہلے روزے کا عزم نہیں کرتا، اس کا روزہ نہیں ہوتا۔"}],[2340,"ام المؤمنین حفصہ رضی اللہ عنہا کہتی ہیں کہ اس شخص کا روزہ نہیں جو فجر سے پہلے روزہ کی پختہ نیت نہ کر لے۔ مالک بن انس نے اسے مرسلاً روایت کیا ہے ۱؎۔\n§وضاحت\n۱؎: یعنی مالک نے اسے منقطعاً روایت کیا ہے، کیونکہ زہری نے عائشہ رضی اللہ عنہا کو نہیں پایا ہے۔","الألباني: صحيح موقوف",{"u2":"حضرت حفصہc فرماتی ہیں: اس شخص کا روزہ نہیں ہوتا جو طلوع فجر سے پہلے روزے کی نیت نہیں کرتا۔\nامام مالکk نے اس روایت کو مرسل (منقطع) بیان کیا ہے۔","f2":"انقطاع سے مراد یہ ہے کہ امام مالکk نے یہ روایت زہری عن عائشہ وحفصہd بیان کی ہے۔ ظاہر ہے کہ امام زہریk کا حضرت عائشہc سے سماع ہے ن حضرت حفصہc سے۔"}],[2341,"ام المؤمنین عائشہ و ام المؤمنین حفصہ رضی اللہ عنہما سے اسی کے مثل روایت ہے کہ صرف وہی شخص روزہ رکھے جو فجر سے پہلے روزہ کی پختہ نیت کر لے۔","الألباني: صحيح لغيره",{"u2":"حضرت عائشہ اور حضرت حفصہ رضی اللہ عنہا سے اسی کے مثل مروی ہے، انہوں نے فرمایا: وہ شخص روزہ نہ رکھے جس نے طلوع فجر سے قبل روزے کی نیت نہیں کی۔"}],[2342,"عبداللہ بن عمر رضی اللہ عنہ کہتے ہیں کہ جب آدمی نے رات ہی میں روزہ کی پختہ نیت نہ کی ہو تو وہ روزہ نہ رکھے۔","الألباني: صحيح موقوف",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے کہ جب کوئی شخص رات کو روزے کی نیت نہ کرے تو وہ روزہ نہ رکھے۔"}],[2343,"عبداللہ بن عمر رضی اللہ عنہما کہتے تھے کہ روزہ صرف وہی رکھے جس نے فجر سے پہلے روزہ کی پختہ نیت کر لی ہو۔","الألباني: صحيح موقوف",{"u2":"حضرت ابن عمر رضی اللہ عنہ فرمایا کرتے تھے: روزے نہ رکھے مگر وہ شخص جس نے طلوع فجر سے پہلے روزے کی نیت کر لی۔","f2":"(۱) مندرجہ بالا روایات سے معلوم ہوتا ہے کہ یہ روایت کبھی حضرت حفصہ رضی اللہ عنہا کا اپنا قول بتایا جاتا ہے، کبھی رسول اللہ صلی اللہ علیہ وسلم کا فرمان اور کبھی ابن عمر رضی اللہ عنہ کا قول، اس لیے اس حدیث کے بارے میں محدثین مختلف ہیں۔ مشہور ائمہ حدیث، مثلاً: امام بخاری، امام ابوداؤد، امام نسائی، امام ترمنذی اور امام احمد رحمہم اللہ اس روایت کو مقوفاً صحیح سمجھتے ہیں، یعنی یہ حضرت حفصہ یا حضرت ابن عمر رضی اللہ عنہم کا اپنا قول ہے، رسول اللہ صلی اللہ علیہ وسلم سے مروی نہیں، جبکہ امام ابن خزیمہ، امام ابن حبان، امام دارقطنی، امام ابن حزم اور امام حاکم رحمہم اللہ نے اسے مرفوع بھی صحیح قرار دیا ہے، یعنی یہ رسول اللہ صلی اللہ علیہ وسلم کا فرمان بھی ہے، بالفرض اگر اسے مرفوعاً صحیح تسلیم نہ بھی کیا جائے تب بھی یہ حکماً مرفوع ہی بنتی ہے کیونکہ حضرت حفصہ رضی اللہ عنہا کے اس فتوے کی بنیاد اپنی رائے یا قیاس نہیں، یقینا اس کی بنیاد رسول اللہ صلی اللہ علیہ وسلم کا قول ہی ہو سکتا ہے۔ مزید تفصیل کے لیے دیکھیے: (ذخیرۃ العقبیٰ شرح سنن النسائی: ۲۱/ ۲۴۷- ۲۴۹) واللہ اعلم۔ (۲)نفلی روزے کی نیت دن کے وقت بھی کی جا سکتی ہے۔ (۳)فرض روزے کی نیت صبح صادق سے پہلے کر لینا ضروری ہے۔ گویا غروب آفتاب کے بعد سے لے کر صبح صادق کے طلوع ہونے سے پہلے تک نیت کی جا سکتی ہے۔"}],[2344,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما کو کہتے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ عزوجل کو روزوں میں سب سے زیادہ محبوب اور پسندیدہ روزے داود علیہ السلام کے تھے۔ وہ ایک دن روزہ رکھتے تھے، اور ایک دن بغیر روزہ کے رہتے تھے، اور اللہ تعالی کے نزدیک سب سے محبوب نماز بھی داود علیہ السلام کی نماز تھی، وہ آدھی رات سوتے تھے اور تہائی رات قیام کرتے تھے، اور رات کے چھٹویں حصہ میں پھر سوتے تھے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمرو بن عاص رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ عزوجل کو سب سے زیادہ پسندیدہ روزے داؤد علیہ السلام کے روزے ہیں۔ وہ ایک دن روزہ رکھتے تھے اور ایک دن نہیں رکھتے تھے۔ اور اللہ تعالیٰ کو زیادہ پسندیدہ نفل نماز بھی داؤد علیہ السلام کی (رات کی) نماز ہے۔ وہ آدھی رات تک سوتے تھے، پھر ایک تہائی رات نماز پڑْتے اور آخری چھٹا حصہ پھر سو جاتے تھے۔‘‘","f2":"’’سب سے زیادہ پسندیدہ۔‘‘ کیونکہ حضرت داؤد علیہ السلام کے روزے اور نماز میں اعتدال تھا۔ جس سے حقوق اللہ کے ساتھ ساتھ حقوق العباد کی ادائیگی میں بھی فرق نہ آتا تھا۔ اگر کوئی شخص اعتدال سے ہٹ جائے گا، مثلاً وہ ان سے زیادہ روزے رکھے گا یا ہمیشہ ساری رات قیام کرے گا تو حقوق العباد کا مجرم ہوگا، بلکہ وہ اپنے نفس کا بھی مجرم ہوگا۔ یہی وجہ ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے س اعتدال سے بڑھنے کی اجازت نہیں دی بلکہ راوی حدیث صحابی رضی اللہ عنہ کو صراحتاً فرمایا کہ اس سے افضل روزے ممکن نہیں۔"}],[2345,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم حضر میں ہوں یا سفر میں ایام بیض میں بغیر روزہ کے نہیں رہتے تھے ۱؎۔\n§وضاحت\n۱؎: قمری مہینہ کی تیرھویں، چودھویں اور پندرھویں تاریخ کو ایام بیض :(روشن راتوں والے دن ) کہا جاتا ہے، کیونکہ ان راتوں میں چاند ڈوبنے کے وقت سے لے کر صبح تک پوری رات رہتا ہے۔","الألباني: ضعيف الإسناد",{"u2":"حضرت ابن عباس رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ایام بیض (جاندنی راتوں والے دنوں) کا روزہ نہیں چھوڑتے تھے، خواہ گھر میں ہوتے یا سفر میں۔","f2":"ایام بیض سے مراد تیرہ جودہ اور پندرہ تاریخ ہیں کیونکہ ان راتوں میں چاند مکمل نظر آتا ہے، اور ساری رات رہتا ہے۔"}],[2346,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم روزے رکھتے تھے یہاں تک کہ ہم کہتے: آپ روزے رکھنا بند نہیں کریں گے، اور آپ بغیر روزے کے رہتے تھے یہاں تک کہ ہم کہتے کہ آپ روزے رکھنے کا ارادہ نہیں رکھتے۔ اور آپ جب سے مدینہ آئے رمضان کے علاوہ آپ نے کسی بھی مہینہ کے مسلسل روزے نہیں رکھے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم (بسا اوقات نفل) روزے مسلسل رکھتے حتیٰ کہ ہم کہتے تھے کہ آپ چھوڑیں گے نہیں اور پھر چھوڑنا شروع فرماتے حتیٰ کہ ہم کہتے: آپ رکھیں گے نہیں، جب سے آپ مدینہ تشریف لائے آپ نے کبھی بھی رمضان المبارک کے علاوہ ایک ماہ مسلسل روزے نہیں رکھے۔"}],[2347,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم روزہ سے رہتے تھے یہاں تک کہ ہم کہتے: آپ بغیر روزہ کے رہیں گے ہی نہیں، اور بغیر روزہ کے رہتے تھے یہاں تک کہ ہم کہتے کہ آپ روزہ رکھیں گے ہی نہیں۔","الألباني: صحيح الإسناد",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم روزے رکھتے جاتے حتیٰ کہ ہم کہتے: آپ کسی بھی دن روزہ چھوڑنے کا ارادہ نہیں رکھتے۔ اور پھر چھوڑنے لگتے حتیٰ کہ ہم کہتے: آپ کسی بھی دن روزہ رکھنے کا ارادہ نہیں رکھتے۔"}],[2348,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نہیں جانتی کہ نبی اکرم صلی اللہ علیہ وسلم نے کبھی پورا قرآن ایک رات میں پڑھا ہو، اور نہ ہی میں یہ جانتی ہوں کہ آپ نے کبھی پوری رات صبح تک قیام کیا ہو، اور نہ ہی میں یہ جانتی ہوں کہ رمضان کے علاوہ آپ نے کبھی کوئی پورا مہینہ روزہ رکھا ہو۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ میرے علم میں نہیں کہ نبی صلی اللہ علیہ وسلم نے ایک رات میں سارا قرآن مجید پڑھا ہو یا ساری رات صبح تک نفل نماز پڑھتے رہے ہوں یا رمضان المبارک کے علاوہ کسی مہینے کے مکمل روزے رکھے ہوں۔"}],[2349,"عبداللہ بن شقیق کہتے ہیں کہ میں نے عائشہ رضی اللہ عنہا سے نبی اکرم صلی اللہ علیہ وسلم کے روزوں کے بارے میں پوچھا، تو انہوں نے کہا: آپ روزہ رکھتے تھے یہاں تک کہ ہم کہتے کہ آپ (برابر) روزہ ہی رکھا کریں گے، اور آپ افطار کرتے (روزہ نہ رہتے) تو ہم کہتے کہ آپ برابر بغیر روزہ کے رہیں گے، رسول اللہ صلی اللہ علیہ وسلم نے مدینہ آنے کے بعد سوائے رمضان کے کبھی کوئی پورا مہینہ روزہ نہیں رکھا۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن شقیق سے روایت ہے کہ حضرت عائشہ رضی اللہ عنہا سے نبی صلی اللہ علیہ وسلم کے (نفل) روزوں کے بارے میں پوچھا گیا تو انہوں نے فرمایا: کبھی آپ اس قدر روزے رکھتے کہ ہم کہتے: آپ روزے رکھتے ہی رہیں گے اور کبھی اس قدر ناغے فرماتے کہ ہم کہتے: آپ نے روزے مستقلاً چھوڑ دیئے ہیں۔ اور آپ جب سے مدینہ منورہ تشریف لائے، آپ نے رمضان المبارک کے علاوہ کسی بھی مہینے کے مکمل روزے نہیں رکھے۔ صلی اللہ علیہ وسلم"}],[2350,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے نزدیک روزہ رکھنے کے لیے سب سے زیادہ پسندیدہ مہینہ شعبان کا تھا، بلکہ آپ اسے رمضان سے ملا دیتے تھے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے مروی ہے کہ روزے رکھنے کے لیے رسول اللہ صلی اللہ علیہ وسلم کا سب سے زیادہ پسندیدہ مہینہ شعبان تھا۔ بلکہ آپ تقریباً اسے رمضان المبارک سے ملا ہی دیتے تھے۔"}],[2351,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم روزے سے رہتے تھے یہاں تک کہ ہم کہتے کہ آپ بغیر روزے کے نہیں رہیں گے، اور بغیر روزہ کے رہتے یہاں تک کہ ہم کہتے کہ آپ روزہ رکھیں گے ہی نہیں، اور میں نے رسول اللہ صلی اللہ علیہ وسلم کو شعبان کے مہینے سے زیادہ کسی اور مہینے میں روزہ رکھتے نہیں دیکھا۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم روزے رکھتے جاتے حتیٰ کہ ہم کہتے: آپ چھوڑیں گے نہیں۔ اور آپ روزے چھوڑنے لگتے تو ہم کہتے: رکھیں گے نہیں، اور میں نے رسول اللہ صلی اللہ علیہ وسلم کو شعبان سے زیادہ کسی مہینے میں روزے رکھتے نہیں دیکھا۔"}],[2352,"ام المؤمنین ام سلمہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سوائے شعبان اور رمضان کے مسلسل دو مہینے روزہ نہیں رکھتے تھے۔","الألباني: صحيح",{"u2":"حضرت ام سلمہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم شعبان ورمضان کے علاوہ دو مہینے مسلسل روزے نہیں رکھتے تھے۔","f2":"شعبان میں روزے رکھنے کے بارے میں پیچھے روایات گزر چکی ہیں۔ ان کو اور اس روایت کو دیکھا جائے تو ظاہر ہوتا ہے کہ دونوں ہی باتوں کا احتمال موجود ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے عمل میں تنوع تھا، کبھی پورا شعبان روزے سے رہتے اور کسی شعبان میں مکمل روزے نہ رکھتے بلکہ اکثر رکھ لیا کرتے۔ ام سلمہ رضی اللہ عنہا کی مذکورہ حدیث سے اس تطبیق کی تائید ہوتی ہے۔ المختصر تطبیق ترجیح سے بہتر ہے کہ دونوں قسم کی احادیث معمول بہ رہتی ہیں۔ واللہ اعلم"}],[2353,"ام المؤمنین ام سلمہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم سال کے کسی بھی مہینہ میں پورا روزہ نہیں رکھتے تھے سوائے شعبان کے، آپ اسے رمضان سے ملا دیتے تھے۔","الألباني: صحيح",{"u2":"حضرت ام سلمہ رضی اللہ عنہا سے مروی ہے کہ نبی صلی اللہ علیہ وسلم شعبان کے علاوہ سال بھر کے کسی مہینے میں مکمل (نفل) روزے نہیں رکھتے تھے۔ شعبان کو تو آپ تقریباً رمضان المبارک کے ساتھ ہی ملا دیتے تھے۔"}],[2354,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کسی بھی مہینے میں شعبان سے زیادہ روزہ نہیں رکھتے تھے، آپ شعبان کے پورے یا اکثر دن روزہ رہتے تھے۔","الألباني: حسن صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں رسول اللہ صلی اللہ علیہ وسلم شعبان سے زیادہ کسی مہینے میں روزے نہیں رکھتے تھے۔ شعبان کے مہینے میں اپ اکثر روزے رکھا کرتے تھے۔"}],[2355,"ام المؤمنین عائشہ رضی اللہ عنہ کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم پورے شعبان روزہ رکھتے تھے سوائے چند دنوں کے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم شعبان کے روزے رکھا کرتے تھے۔ صرف چند دن ناغہ فرماتے تھے۔"}],[2356,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم پورے شعبان روزہ رکھتے تھے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ بے شک رسول اللہ صلی اللہ علیہ وسلم (تقریباً) مکمل شعبان کے روزے رکھا کرتے تھے۔"}],[2357,"اسامہ بن زید رضی اللہ عنہ کہتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! جتنا میں آپ کو شعبان کے مہینے میں روزہ رکھتے ہوئے دیکھتا ہوں اتنا کسی اور مہینے میں نہیں دیکھتا، آپ نے فرمایا: \"رجب و رمضان کے درمیان یہ ایسا مہینہ ہے جس سے لوگ غفلت برتتے ہیں، یہ ایسا مہینہ ہے جس میں آدمی کے اعمال رب العالمین کے سامنے پیش کئے جاتے ہیں، تو میں چاہتا ہوں کہ جب میرا عمل پیش ہو تو میں روزہ سے رہوں\"۔","الألباني: حسن",{"u2":"حضرت اسامہ بن زید رضی اللہ عنہ سے منقول ہے کہ میں نے (رسول اللہ صلی اللہ علیہ وسلم سے) عرض کیا: اے اللہ کے رسول! میں نے آپ کو کسی مہینے میں اتنے روزے رکھتے نہیں دیکھا جتنے آپ شعبان میں رکھتے ہیں۔ (کیا وجہ ہے؟) آپ نے فرمایا: ’’یہ وہ مہینہ ہے کہ رب اور رمضان المبارک کے درمیان آنے کی وجہ سے لوگ اس سے غفلت کر جاتے ہیں، حالانکہ یہ وہ مہینہ ہے کہ اس میں رب العالمین کے ہاں انسانوں کے اعمال پیش کیے جاتے ہیں۔ میں چاہتا ہوں کہ میرے عمل پیش ہوں تو میں روزے سے ہوں۔‘‘","f2":"(۱) رجب اور رمضان البمارک دونوں مہینوں کا تقدس مسلمہ تھا۔ رجب کا اس لیے کہ یہ حرمت والے مہینوں میں شامل ہے اور رمضان المبارک کا روزوں کی وجہ سے۔ لوگ ان دونوں مہینوں میں نیکی کے کام خوب کرتے تھے۔ شعبان کو خالی مہینہ خیال کیا جاتا تھا، حالانکہ اس کی اپنی فضیلت ہے جو رسول اللہ صلی اللہ علیہ وسلم نے بیان فرمائی۔ (۲) ’’اعمال پیش کیے جاتے ہیں۔‘‘ اعمال تو ہر روز صبح اور عصر کے وقت بھی پیش ہوتے ہیں اور ہر ہفتے میں سوموار اور جمعرات کو بھی پیش ہوتے ہیں۔ گویا یہ سالانہ پیشی ہے اور اجمالی طور پر سارے سال کے اعمال پیش کیے جاتے ہیں۔ ان پیشیوں کی حکمت اللہ تعالیٰ ہی جانتا ہے۔ بے شک اللہ تعالیٰ تمام اعمال سے ذاتی طور پر بخوبی واقف ہے۔ (۳) ’’میں روزے سے ہوں۔‘‘ کیونکہ روزہ افضل عبادت ہے۔ اسی وجہ سے رسول اللہ صلی اللہ علیہ وسلم سوموار اور جمعرات کا روزہ بھی رکھا کرتے تھے۔"}],[2358,"اسامہ بن زید رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کیا: اللہ کے رسول! آپ روزہ رکھتے ہیں یہاں تک کہ ایسا لگتا ہے کہ آپ روزہ بند ہی نہیں کریں گے، اور بغیر روزہ کے رہتے ہیں یہاں تک کہ لگتا ہے کہ روزہ رکھیں گے ہی نہیں سوائے دو دن کے۔ کہ اگر وہ آپ کے روزہ کے درمیان میں آ گئے(تو ٹھیک ہے) اور اگر نہیں آئے تو بھی آپ ان میں روزہ رکھتے ہیں۔ آپ نے پوچھا: \"وہ دو دن کون ہیں؟\" میں نے عرض کیا: وہ پیر اور جمعرات کے دن ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ دو دن وہ ہیں جن میں اللہ رب العالمین کے سامنے ہر ایک کے اعمال پیش کئے جاتے ہیں، تو میں چاہتا ہوں کہ جب میرا عمل پیش ہو تو میں روزہ سے رہوں\"۔","الألباني: حسن صحيح",{"u2":"حضرت اسامہ بن زید رضی اللہ عنہ سے منقول ہے کہ میں نے کہا: اے اللہ کے رسول! آپ کبھی اس قدر روزے رکھتے ہیں کہ لگتا ہے آپ چھوڑیں گے نہیں اور کبھی اس قدر چھوڑتے ہیں کہ لگتا ہے رکھیں گے نہیں، مگر دو دنوں کا ضرر رکھتے ہیں۔ آپ کے (عمومی) روزوں میں آجائیں تو فبہا، ورنہ آپ ان کا روزہ خصوصاً رکھتے ہیں۔ آپ نے فرمایا: ’’کون سے دو دن؟‘‘ میں نے کہا: سوموار اور جمعرات۔ آپ نے فرمایا: ’’یہ دو دن ایسے ہیں کہ ان میں رب العالمین کے ہاں اعمال پیش ہوتے ہیں اور میں چاہتا ہوں کہ میرے عمل پیش ہوں تو میں روزے سے ہوں۔‘‘"}],[2359,"اسامہ بن زید رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم برابر روزہ رکھتے جاتے تھے، یہاں تک کہ کہا جانے لگتا کہ آپ بغیر روزہ کے رہیں گے ہی نہیں، اور (مسلسل) بغیر روزہ کے رہتے یہاں تک کہ کہا جانے لگتا کہ آپ روزہ رکھیں گے ہی نہیں۔","الألباني: حسن صحيح",{"u2":"حضرت اسامہ بن زید رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم بسا اوقات لگاتار روزے رکھتے تھے حتیٰ کہ کہا جاتا: آپ چھوڑیں گے نہیں اور کبھی چھوڑنے لگتے حتیٰ کہ کہا جاتا: آپ رکھیں گے نہیں۔"}],[2360,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم دو شنبہ (پیر) اور جمعرات کے روزہ کا اہتمام فرماتے تھے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے، انھوں نے فرمایا: تحقیق رسول اللہ صلی اللہ علیہ وسلم سوموار اور جمعرات کا روزہ قصداً رکھا کرتے تھے۔"}],[2361,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم دوشنبہ (پیر) اور جمعرات کے دن (کے روزہ) کا اہتمام فرماتے تھے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے، انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم سوموار اور جمعرات کا روزہ کوشش سے رکھا کرتے تھے۔"}],[2362,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم دوشنبہ (پیر) اور جمعرات کے دن (کے روزہ) کا اہتمام فرماتے تھے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے مروی ہے، فرمایا: رسول اللہ صلی اللہ علیہ وسلم سوموار اور جمعرات کا روزہ خصوصاً رکھتے تھے۔"}],[2363,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم دوشنبہ (پیر) اور جمعرات کے دن (کے روزہ) کا اہتمام فرماتے تھے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے منقول ہے، فرمایا: رسول اللہ صلی اللہ علیہ وسلم سوموار اور جمعرات کے دن روزہ ارادتاً رکھا کرتے تھے۔"}],[2364,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم دوشنبہ (پیر) اور جمعرات کو روزہ رکھتے تھے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے مروی ہے، انھوں نے فرمایا: نبی صلی اللہ علیہ وسلم سوموار اور جمعرات کے دن کا روزہ رکھا کرتے تھے۔"}],[2365,"ام المؤمنین ام سلمہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہر مہینے تین دن روزہ رکھتے تھے: پہلے ہفتہ کے دوشنبہ (پیر) اور جمعرات کو، اور دوسرے ہفتہ کے دوشنبہ (پیر) کو۔","الألباني: حسن لكن الأصح بلفظ وخميس",{"u2":"حضرت ام سلمہ رضی اللہ عنہا سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم ہر مہینے میں تین دن روزہ رکھتے تھے: دو ایک ہفتے میں پیر اور جمعرات کو اور اگلے ہفتے کے پیر کو۔"}],[2366,"ام المؤمنین حفصہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہر مہینے کی جمعرات اور دوشنبہ (پیر) کو اور دوسرے ہفتہ کے دوشنبہ (پیر) کو روزہ رہتے تھے۔","الألباني: حسن",{"u2":"حضرت حفصہ رضی اللہ عنہا فرماتی ہیں رسول اللہ صلی اللہ علیہ وسلم ہر مہینے جمعرات اور سوموار کو اور دوسرے جمعہ (ہفتے) سے سوموار کو روزہ رکھتے تھے۔"}],[2367,"ام المؤمنین حفصہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب اپنے بستر پر لیٹتے تو اپنی داہنی ہتھیلی اپنے دائیں گال کے نیچے رکھ لیتے، اور دوشنبہ (پیر)اور جمعرات کے دن روزہ رکھتے تھے۔","الألباني: حسن صحيح",{"u2":"حضرت حفصہ رضی اللہ عنہا سے منقول ہے، انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم جب بستر پر لیٹتے تھے تو اپنا دایاں ہاتھ مبارک (ہتھیلی) اپنے دائیں رخسار کے نیچے رکھتے تھے اور سوموار اور جمعرات کا روزہ رکھا کرتے تھے۔"}],[2368,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہر مہینے کے ابتدائی تین دنوں میں روزہ رکھتے تھے اور کم ہی ایسا ہوتا کہ آپ جمعہ کے دن روزہ سے نہ رہے ہوں ۱؎۔\n§وضاحت\n۱؎: صحیح بخاری کی ایک حدیث :(صوم/۱۹۸۴ ) میں خاص جمعہ کے دن روزہ رکھنے سے صراحت کے ساتھ ممانعت آئی ہے، تو اس حدیث کا مطلب بقول حافظ ابن حجر یہ ہے کہ اگر ان تین ایام بیض میں جمعہ آ پڑتا تو جمعہ کے دن روزہ رکھنے کی ممانعت کے وجہ سے آپ روزہ نہیں توڑتے تھے، بلکہ رکھ لیتے تھے، ممانعت تو خاص ایک دن جمعہ کو روزہ رکھنے کی ہے، یا بقول حافظ عینی: ایک دن آگے یا پیچھے ملا کر جمعہ کو روزہ رکھتے تھے، لیکن قابل قبول توجیہ حافظ ابن حجر کی ہی ہے، کیونکہ آپ تین دن ایام بیض کے روزہ تو رکھتے ہی تھے، اور پھر دو دن جمعہ کی مناسبت سے بھی رکھتے ہوں، یہ کہیں منقول نہیں ہے، یا پھر یہ کہا جائے کہ خاص اکیلے جمعہ کے دن کی ممانعت امت کے لیے ہے، اور روزہ رکھنا آپ صلی اللہ علیہ وسلم کی خصوصیت تھی۔","الألباني: حسن",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم ہر مہینے کے شروع سے تین دن کا روزہ رکھتے تھے اور جمعۃ المبارک کے دن کم ہی روزہ چھوڑتے تھے۔","f2":"(۱) ’’شروع سے‘‘ یعنی کسی مہینے میں۔ اور بعض اوقات درمیان سے تین دن روزہ رکھتے تھے اور کبھی آخر مہینے سے بھی رکھ لیتے تھے۔ (۲) ’’جمعۃ المبارک کے دن۔‘‘ یعنی جمعرات سمیت، ورنہ اکیلے جمعے کے روزے سے تو آپ نے منع فرمایا ہے۔ دیکھیے: (صحیح البخاری، الصوم، حدیث: ۱۹۸۵، وصحیح مسلم، الصیام، حدیث: ۱۱۴۴) جمعرات کا روزہ آپ کا معمول تھا۔"}],[2369,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے چاشت کی دونوں رکعتوں کا حکم دیا، اور یہ کہ میں وتر پڑھے بغیر نہ سوؤں، اور ہر مہینے میں تین دن روزہ رکھا کروں۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے ضحی (چاشت) کی دو رکعتیں پڑھا کروں اور بغیر وتر پڑھے نہ سوؤں اور ہر مہینے میں تین روزے رکھوں۔","f2":"یہ حکم استحبابی ہے وجوبی نہیں کیونکہ مذکورہ تینوں کام بالاتفاق مستحبات میں شمار ہوتے ہیں۔"}],[2370,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ ان سے عاشوراء کے روزہ کے بارے میں پوچھا گیا تھا تو انہوں نے کہا: مجھے نہیں معلوم کہ نبی اکرم صلی اللہ علیہ وسلم نے کسی دن کا روزہ اور دنوں سے بہتر جان کے رکھا ہو، سوائے اس دن کے، یعنی ماہ رمضان کے اور عاشوراء کے۔","الألباني: صحيح",{"u2":"حضرت عبیداللہ بیان کرتے ہیں کہ میں نے سنا جبکہ حضرت ابن عباس رضی اللہ عنہ سے عاشوراء کے روزے کے بارے میں پوچھا گیا، آپ نے فرمایا: میں تو نہیں جانتا کہ نبی صلی اللہ علیہ وسلم نے کسی دن کو دوسرے دنوں سے افضل سمجھ کر اس کا روزہ رکھا ہو، سوائے اس دن کے، یعنی عاشوراء اور ماہ رمضان المبارک کے۔","f2":"ماہ رمضان المبارک کی فضیلت کے بارے میں تو کوئی کلام ہی نہیں، اس کے بعد یوم عاشوراء یعنی دس محرم الحرام افضل ہے۔ اس دن بہت سے اہم کام سر انجام پائے۔"}],[2371,"حمید بن عبدالرحمٰن بن عوف کہتے ہیں کہ میں نے معاویہ رضی اللہ عنہ کو عاشوراء کے دن منبر پر کہتے سنا: \"اے مدینہ والو! تمہارے علماء کہاں ہیں؟ میں نے رسول اللہ صلی اللہ علیہ وسلم کو اس دن میں کہتے ہوئے سنا کہ میں روزہ سے ہوں تو جو روزہ رکھنا چاہے وہ رکھے\"۔","الألباني: صحيح",{"u2":"حضرت حمید بن عبدالرحمن بن عوف بیان کرتے ہیں کہ میں نے حضرت معاویہ رضی اللہ عنہ کو عاشوراء کے دن منبر نبوی پر فرماتے سنا: اے مدینے والو! کہاں گئے تمھارے علمائ؟ میں نے رسول اللہ صلی اللہ علیہ وسلم کو اس دن کے بارے میں فرماتے سنا: ’’میں نے آج روزہ رکھا ہوا ہے، تو جو روزہ رکھنا چاہے، وہ رکھ لے۔‘‘","f2":"امام نسائی رحمہ اللہ کا مقصد یہ بتلانا ہے کہ رسول اللہ صلی اللہ علیہ وسلم عاشوراء کا روزہ بھی رکھا کرتے تھے، مگر عاشوراء کا اکیلا روزہ مناسب نہیں، اس کے ساتھ نویں یا نویں کا چھوٹ جائے تو مشابہت سے بچنے کی خاطر گیارہویں کا رکھنا بھی ان شاء اللہ جائز ہوگا۔"}],[2372,"نبی اکرم صلی اللہ علیہ وسلم کی ایک زوجہ مطہرہ (ام المؤمنین رضی اللہ عنہا) کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم عاشوراء کے روز، ذی الحجہ کے نو دنوں میں، ہر مہینے کے تین دنوں میں یعنی: مہینہ کے پہلے دوشنبہ (پیر) کو اور پہلے اور دوسرے جمعرات کو روزہ رکھتے تھے۔","الألباني: صحيح",{"u2":"حضرت ہنیدہ بن خالد کی زوجہ محترمہ سے روایت ہے، انھوں نے فرمایا: مجھ سے نبی صلی اللہ علیہ وسلم کی کسی زوجہ محترمہ نے بیان فرمایا کہ نبی صلی اللہ علیہ وسلم عاشورائِ محرم، ذوالحجہ کے پہلے نو دن اور ہر مہینے کے تین دن، مہینے کا پہلا سوموار اور دو ابتدائی جمعراتیں روزہ رکھا کرتے تھے۔","f2":"مندرجہ بالا اٹھائیس روایات میں رسول اللہ صلی اللہ علیہ وسلم فداہ ابی وامی ونفسی وروحی کے نفل روزوں کی مختلف کیفیات بیان کی گئی ہیں اور ان میں کوئی تضاد نہیں۔ آپ کبھی کسی کیفیت سے روزے رکھتے تھے اور کبھی کسی کیفیت سے۔ اور یہی زیادہ مناسب ہے کیونکہ نفل روزوں میں سہولت کا خیال رکھنا چاہیے۔ کسی ایک طریقے کو اختیار کر کے اس پر اس طرح جم جانا کہ اس سے نکلنا گناہ سمجھنا، تشدد اور تکلف فی الدین کے زمرے میں آتا ہے، اس لیے نفل کا معاملہ کھلا رکھنا چاہیے کیونکہ نفل کا مدار خوشی اور نشاط پر ہے، البتہ شریعت کی ہدایات ملحوظ خاطر رہیں، مثلاً: روزہ ہمیشہ نہ رکھے۔ عیدین اور ایام تشریق میں روزہ نہ رکھے۔ شک والے دن اور شعبان کی آخری تاریخوں میں نہ رکھے۔ وغیرہ وغیرہ"}],[2373,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے ہمیشہ روزے رکھے، تو اس نے روزے ہی نہیں رکھے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس نے بلاناغہ روزہ رکھا اس کا کوئی روزہ نہیں۔‘‘","f2":"صیام داود علیہ السلام سے زائد روزے نہیں رکھنے چاہئیں کیونکہ یہ افضل ترین ہیں۔ اگر کوئی زائد رکھے گا تو بھی زائد ثواب حاصل نہ کر سکے گا۔ ایک آدھ ماہ میں ایسے ہو تو الگ بات ہے جیسا کہ نبی اکرم صلی اللہ علیہ وسلم اکثر شعبان کے روزے رکھتے تھے، مسلسل ایسا کرنا منع ہے۔"}],[2374,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے ہمیشہ روزے رکھے اس نے نہ روزے رکھے، اور نہ افطار کیا\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’۔جس نے ہمیشہ روزہ رکھا، تو (ایسے سمجھو کہ) اس نے نہ روزہ رکھا اور نہ افطار کیا (وہ بے روزہ رہا)۔‘‘","f2":"’’نہ اس نے روزہ رکھا۔‘‘ یعنی اسے کسی روزے کا ثواب نہ ملا۔ معلوم ہوا عبادات میں غلو کرنا اور ہد سے تجاوز کرنا انھیں بے اجر بنا دیتا ہے۔‘‘ ’’نہ افطار کیا۔‘‘ یعنی وہ افطار (روزہ نہ رکھنے) کے فوائد سے بھی محروم رہا۔"}],[2375,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس نے ہمیشہ روزے رکھے تو اس نے روزے ہی نہیں رکھے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس نے ہمیشہ روزہ رکھا، اس کا روزہ نہیں۔"}],[2376,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس نے ہمیشہ روزے رکھے اس نے روزے ہی نہیں رکھے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے منقول ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جس نے ہمیشہ روزہ رکھا (سمجھو) اس نے روزہ نہیں رکھا۔‘‘"}],[2377,"عبداللہ بن عمرو بن العاص رضی اللہ عنہا کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے ہمیشہ روزے رکھے اس نے نہ تو روزے ہی رکھے اور نہ ہی کھایا پیا\"۔\n§وضاحت\n۱؎: سند میں مبہم راوی ابو العباس الشاعر ہیں جن کے نام کی صراحت اگلی روایت میں آئی ہے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمرو بن عاص رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس نے ہر روز روزہ رکھا، اس نے روزہ رکھا، نہ چھوڑا۔‘‘"}],[2378,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کو خبر ملی کہ میں روزہ رکھتا ہوں، پھر مسلسل روزہ رکھتا ہوں، اور راوی نے پوری حدیث بیان کی۔ ابن جریج کہتے ہیں کہ عطاء نے کہا: مجھے یاد نہیں کہ انہوں نے «صیام ابد» کا ذکر کیسے کیا، مگر اتنا یاد ہے کہ انہوں نے یوں کہا: \"اس شخص نے«صیام» (روزے) نہیں رکھے جس نے ہمیشہ «صیام» (روزے) رکھے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمرو بن عاص رضی اللہ عنہ نے کہا: نبی صلی اللہ علیہ وسلم کو یہ بات پہنچی کہ میں لگاتار روزے رکھتا ہوں۔ اور راوی حدیث نے پوری حدیث بیان کی۔ ابن جریج بیان کرتے ہیں کہ عطاء فرماتے ہیں کہ مجھے معلوم نہیں کہ ہمیشہ روزہ رکھنے والے الفاظ اس قصہ میں کیسے آگئے (البتہ نبی صلی اللہ علیہ وسلم کا یہ فرمان مجھے یاد ہے کہ آپ نے فرمایا:) ’’جس نے ہمیشہ روزہ رکھا، اس کا روزہ نہیں ہوتا۔‘‘"}],[2379,"عمران بن حصین رضی اللہ عنہ کہتے ہیں کہ عرض کیا گیا: اللہ کے رسول! فلاں شخص کبھی دن کو افطار نہیں کرتا ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس نے نہ روزہ رکھا، نہ افطار کیا\"۔","الألباني: صحيح",{"u2":"حضرت عمران رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کو بتلایا گیا: فلاں شخص کبھی بھی روزے سے ناغہ نہیں کرتا۔ آپ نے فرمایا: ’۔نہ اس نے روزہ رکھا اور نہ چھوڑا۔‘‘","f2":"ہمیشہ روزہ رکھنا فطرت انسانی کے خلاف ہے کیونکہ اس سے حقوق العباد کی ادائیگی میں خرابی پیدا ہو گی، جسمانی کمزور ہوگی، معاش خراب ہوگا، وغیرہ وغیرہ۔ لہٰذا ہمیشہ روزہ رکھنا درست نہیں، چاہے وہ عیدین اور ایام تشریق کے روزے چھوڑ بھی دے کیونکہ مذکورہ بالا خرابیاں اس صورت میں بھی بعینہٖ موجود ہیں۔ اگرچہ فقہی طور پر اس کے جواز کی یہ کہہ کر گنجائش نکالی گئی ہے کہ پانچ ناغے ہونے سے حقیقتاً ہمیشہ کا روزہ نہ رہا۔ مگر فقہی موشگافیوں کے بجائے مصالح اور مفاسد کا لحاظ رکھنا اصل ہے۔ شریعت کے احکام میں یہ چیز صاف نظر آتی ہے، مثلا: کتے کا جوٹھا پلید ہے، بلی کا پاک۔ محفوظ پانی قلیل نجاست سے پلید ہو جاتا ہے، مگر کھلا پانی نہیں، وغیرہ۔"}],[2380,"عبداللہ بن شخیر رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا اور آپ کے سامنے ایک ایسے شخص کا ذکر کیا گیا تھا جو ہمیشہ روزہ رکھتا تھا تو آپ نے فرمایا: \"اس نے نہ روزہ رکھا اور نہ ہی افطار کیا\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن شخیر رضی اللہ عنہ سے روایت ہے، انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا جب آپ کے پاس ایک آدمی کا ذکر ہوا جو بلا ناغہ روزے رکھا کرتا تھا۔ آپ نے فرمایا: ’’اس نے نہ روزہ رکھا اور نہ چھوڑا۔‘‘"}],[2381,"عبداللہ بن شخیر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے صیام الدھر رکھنے والے کے بارے میں فرمایا: \"نہ اس نے روزہ رکھا، اور نہ ہی افطار کیا\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن شخیر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیشہ روزہ رکھنے (والے) کے بارے میں فرمایا: ’’اس نے نہ روزہ رکھا اور نہ چھوڑا۔‘‘","f2":"’’نہ رکھا اور نہ چھوڑا۔‘‘ چھوڑا تو حقیقتاً نہیں، رکھا اس لیے نہیں کہ شریعت کی نافرمانی کی، ثواب نہ ملا گویا نہ رکھا۔"}],[2382,"عمر رضی اللہ عنہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے، تو ہم سب کا گزر ایک شخص کے پاس سے ہوا، (اس کے بارے میں) لوگوں نے عرض کیا: اللہ کے نبی! یہ شخص ایسا ہے جو اتنی مدت سے افطار نہیں کر رہا ہے (یعنی برابر روزے رکھ رہا ہے) آپ صلی اللہ علیہ وسلم نے فرمایا: \"نہ اس نے روزہ رکھا، نہ ہی افطار کیا\"۔","الألباني: صحيح لغيره",{"u2":"حضرت عمر رضی اللہ عنہ بیان کرتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے کہ ہم ایک آدمی کے پاس سے گزرے۔ لوگوں نے کہا: اے اللہ کے نبی! یہ شخص اتنے عرصے سے روزے کا ناغہ نہیں کر رہا۔ آپ نے فرمایا: ’’نہ اس نے روزہ رکھا اور نہ چھوڑا۔‘‘"}],[2383,"ابوقتادہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم سے آپ کے روزوں کے بارے میں پوچھا گیا، تو آپ ناراض ہو گئے، عمر رضی اللہ عنہ نے کہا: ہم اللہ کے رب (حقیقی معبود) ہونے پر، اسلام کے دین ہونے پر، اور محمد صلی اللہ علیہ وسلم کے رسول ہونے پر، راضی ہیں، نیز آپ سے ہمیشہ روزہ رکھنے والے کے بارے میں پوچھا گیا، تو آپ نے فرمایا: \"اس نے نہ روزہ رکھا، نہ ہی افطار کیا\"۔","الألباني: سكت عنه الشيخ",{"u2":"حضرت ابو قتادہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم سے آپ کے روزوں کے بارے میں پوچھا گیا تو آپ ناراض ہوگئے۔ حضرت عمر رضی اللہ عنہ نے عرض کیا: ہم اللہ تعالیٰ کے رب ہونے، اسلام کے دین ہونے اور حضرت محمد صلی اللہ علیہ وسلم کے رسول ہونے پر راضی ہیں، پھر آپ سے اس شخص کے بارے میں پوچھا گیا جو بلا ناغہ روزے رکھتا تھا۔ آپ نے فرمایا: ’’اس نے نہ روزہ رکھا اور نہ چھوڑا۔‘‘","f2":"(۱) ’’ناراض ہوگئے۔‘‘ کیونکہ آپ نے اپنی نیکی کے اظہار کو مناسب نہ سمجھا، اس لیے ایسے سوال پر ناراض ہوئے۔ یا آپ نے خطرہ محسوس فرمایا کہ اگر میں نے بتا دیا تو سائل یا دوسرے لوگ میری اقتدا کرنے کی کوشش کریں گے اور مشقت میں پڑیں گے۔ یا اس لیے ناراض ہوئے کہ عبادت کے مسئلہ، خصوصاً روزے میں آپ کی مماثلت کرنا منع ہے، مثلاً: وصال (کئی دنوں کا روزہ) آپ کا خاصہ ہے، کسی اور شخص کو ایک دن سے زائد کا روزہ (وصال کی صورت میں) رکھنے کی اجازت نہیں۔ واللہ اعلم (۲) ’’راضی ہیں۔‘‘ یعنی ہم اللہ تعالیٰ کے آپ پر نازل کردہ دین پر سختی سے کار بند ہیں، لہٰذا ہماری غلطی معاف فرمائیے۔"}],[2384,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ حمزہ بن عمرو اسلمی رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: اللہ کے رسول! میں ایک ایسا آدمی ہوں جو مسلسل روزے رکھتا ہو، تو کیا سفر میں بھی روزہ رکھ سکتا ہوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر چاہو تو رکھو اور اگر چاہو تو نہ رکھو\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ حضرت حمزہ بن عمرو اسلمی رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: اے اللہ کے رسول! میں لگاتار روزے رکھتا ہوں تو کیا سفر میں بھی رکھ لیا کروں؟ آپ نے فرمایا: ’’اگر تو چاہے تو رکھ لے اور اگر چاہے تو نہ رکھ۔‘‘","f2":"یہاں پے در پے روزوں سے پورے سال کے مسلسل روزے رکھنا مراد نہیں کیونکہ احادیث میں اس کی سخت ممانعت ہے، شرعاً ایسے روزے ناقابل اعتبار ہیں۔ مجموعی دلائل کا جائزہ لینے سے معلوم ہوتا ہے کہ یہاں سرد الصیام سے مراد مسلسل مہینہ دو مہینے روزے رکھنا ہے اور بس۔ واللہ اعلم اور اس کے جواز میں ان شاء اللہ کوئی تردد نہیں۔"}],[2385,"عمرو بن شرجبیل ایک صحابی رضی اللہ عنہ سے روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم سے عرض کیا گیا: ایک آدمی ہے جو ہمیشہ روزے رکھتا ہے؟ آپ نے فرمایا: \"میری خواہش ہے کہ وہ کبھی کھاتا ہی نہیں\" ۱؎، لوگوں نے عرض کیا: دو تہائی ایام رکھے تو؟ ۲؎ آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ بھی زیادہ ہے\"، لوگوں نے عرض کیا: اور آدھا رکھے تو؟ ۳؎ آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ بھی زیادہ ہے\"، پھر آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا میں تمہیں اتنے روزوں نہ بتاؤں جو سینے کی سوزش کو ختم کر دیں، یہ ہر مہینے کے تین دن کے روزے ہیں\"۔\n§وضاحت\n۱؎: یعنی نہ دن میں نہ رات میں یہاں تک کہ بھوک سے مر جائے، اس سے مقصود اس کے اس عمل پر اپنی ناگواری کا اظہار ہے اور یہ بتانا ہے کہ یہ ایک ایسا مذموم عمل ہے کہ اس کے لیے بھوک سے مر جانے کی تمنا کی جائے۔ ۲؎: یعنی دو دن روزہ رکھے اور ایک دن افطار کرے تو کیا حکم ہے ؟ ۳؎: یعنی ایک دن روزہ رکھے اور ایک دن افطار کرے تو کیا حکم ہے ؟","الألباني: صحيح",{"u2":"نبی صلی اللہ علیہ وسلم کے ایک صحابی رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم سے کہا گیا کہ ایک آدمی ہمیشہ روزے رکھتا ہے۔ آپ نے فرمایا: ’’کاش وہ کبھی کھانا نہ کھانا (اور مر جاتا)۔‘‘ لوگوں نے عرض کیا: دو تہائی دنوں کے روزے کیسے ہیں؟ آپ نے فرمایا: ’۔یہ بھی بہت زیادہ ہیں۔‘‘ انھوں نے کہا: نصف دنوں کے روزے؟ آپ نے فرمایا: ’۔یہ بھی زیادہ ہی ہیں۔‘‘ پھر فرمایا: ’’میں تمھیں وہ روزے نہ بتاؤں جو سینے کا کینہ (دل کے مفاسد) دور کرنے کے لیے کافی ہیں؟ ہر ماہ میں تین دن کے روزے۔‘‘","f2":"(۱) ’’کاش وہ کبھی نہ کھاتا۔‘‘ یہ اظہار ناراضی ہے کہ اس نے ایسا کیوں کیا؟ یہ تو مرنے والی بات ہے۔ اس سے تو بہتر تھا کہ کبھی بھی کھانا نہ کھاتا اور جلدی مر جاتا۔ ظاہر الفاظ مقصود نہیں صرف ڈانٹنا مقصد ہے کہ ہمیشہ روزہ رکھنا منع ہے۔ (۲) ’’بہت زیادہ ہیں۔‘‘ گویا ہر مہینے دو تہائی (یعنی بیس) دنوں کے روزے رکھنا بھی اولیٰ نہیں کہ یہ بھی صیام داؤد علیہ السلام سے زیادتی ہے۔ اگرچہ یہ جائز ہیں مگر افضل پھر بھی نہیں۔ (۳) ’’یہ بھی زیادہ ہیں۔‘‘ کیونکہ یہ نفل روزوں کا آخری درجہ ہے، البتہ منع نہیں۔ لیکن چونکہ وہ شخص پہلے ہی زیادہ روزے رکھتا تھا، لہٰذا آپ نے اس کے لیے یہ بھی مناسب نہ سمجھے تاکہ اس کا تشدد ختم ہو۔ (۴) مہینے میں تین روزے بہترین ہیں کیونکہ ان سے روزے کا مقصد بھی بخوبی پورا ہوتا ہے، یعنی دل کی اصلاح ہو جاتی ہے اور حقوق العباد کی ادائیگی میں خلل بھی واقع نہیں ہوتا اور انسان جسمانی کمزوری سے بھی محفوظ رہتا ہے، نیز تین کا ثواب تیس، یعنی پورے مہینے کے برابر ہے، لہٰذا اسی پر عمل افضل ہے۔"}],[2386,"عمرو بن شرحبیل کہتے ہیں کہ ایک شخص رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور کہنے لگا: اللہ کے رسول! آپ اس شخص کے بارے میں کیا فرماتے ہیں جو صیام الدھر رکھے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میں تو یہ چاہوں گا کہ کبھی کچھ کھائے ہی نہ\"، اس نے کہا: اس کا دو تہائی رکھے تو؟ آپ نے فرمایا: \"زیادہ ہے\"، اس نے کہا: آدھے ایام رکھے تو؟ آپ نے فرمایا: \"زیادہ ہے\"، پھر آپ نے فرمایا: \"کیا میں تمہیں وہ چیز نہ بتاؤں جو سینے کی سوزش کو ختم کر دے\"، لوگوں نے کہا: جی ہاں (ضرور بتائیے) آپ نے فرمایا: \"یہ ہر مہینے میں تین دن کا روزہ ہے\"۔","الألباني: صحيح لغيره",{"u2":"حضرت عمرو بن شرحبیل رضی اللہ عنہ سے روایت ہے کہ ایک شخص رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور کہنے لگا: اے اللہ کے رسول! آپ اس آدمی کے بارے میں کیا فرماتے ہیں جو ہمیشہ روزہ رکھتا ہے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میں تو چاہتا ہوں کہ وہ کبھی کچھ نہ کھاتا۔‘‘ اس نے کہا: دو تہائی روزے؟ آپ نے فرمایا: ’’بہت زیادہ ہیں۔‘‘ اس نے کہا: نصف دنوں کے روزے؟ آپ نے فرمایا: ’۔یہ بھی زیادہ ہی ہیں۔‘‘ آپ نے فرمایا: ’۔میں تمہیں ایسے روزوں کی خبر نہ دوں جو دل کی خرابیوں (اخلاقی کمزوریوں) کو دور کر دیتے ہیں؟‘‘ لوگوں نے کہا: کیوں نہیں (ضرور بتائیے) آپ نے فرمایا: ’’ہر مہینے میں تین روزے۔‘‘","f2":"’’دل کی خرابیوں۔‘‘ بعض اہل علم نے خرابیوں کی بجائے دل کی بے چینی مراد لی ہے، یعنی اگر انسان (نیک) عبادت نہ کرے تو دل بے چین رہتا ہے۔ تین روزے ہر ماہ رکھ لینے سے دل کا اضطراب ختم ہو جائے گا اور اطمینان حاصل ہوگا۔"}],[2387,"ابوقتادہ رضی اللہ عنہ کہتے ہیں کہ عمر رضی اللہ عنہ نے عرض کیا: اللہ کے رسول! اس شخص کا معاملہ کیسا ہے جو صیام الدھر رکھتا ہو؟ آپ نے فرمایا: \"اس نے نہ روزے رکھے، اور نہ ہی افطار کیا\"۔ (راوی کو شک ہے «لاصيام ولا أفطر» کہا، یا «لم يصم ولم يفطر» کہا، انہوں نے عرض کیا: اللہ کے رسول! اس شخص کا معاملہ کیسا ہے جو دو دن روزہ رکھتا ہے اور ایک دن افطار کرتا ہے؟ آپ نے فرمایا: \"کیا اس کی کوئی طاقت رکھتا ہے؟\" انہوں نے عرض کیا: (اچھا) اس شخص کا معاملہ کیسا ہے جو ایک دن روزہ رکھتا ہے اور ایک دن افطار کرتا ہے؟ آپ نے فرمایا: \"یہ داود علیہ السلام کا روزہ ہے\"، انہوں نے کہا: اس شخص کا معاملہ کیسا ہے جو ایک دن روزہ رکھے اور دو دن افطار کرے؟ آپ نے فرمایا: \"میری خواہش ہے کہ میں اس کی طاقت رکھوں\"، پھر آپ صلی اللہ علیہ وسلم نے فرمایا: \"ہر مہینے میں تین دن روزہ رکھنا، اور رمضان کے روزے رکھنا یہی صیام الدھر ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوقتادہ رضی اللہ عنہ سے روایت ہے کہ حضرت عمر رضی اللہ عنہ نے عرض کیا: اے اللہ کے رسول! اس شخص کے بارے میں کیا ارشاد ہے جو ہمیشہ بلاناغہ روزہ رکھتا ہے؟ آپ نے فرمایا: ’’اس نے نہ روزہ رکھا اور نہ چھوڑا۔‘‘ انھوں نے عرض کیا: اے اللہ کے رسول! اس شخص کے بارے میں کیا حکم ہے جو دو دن روزہ رکھتا ہے، ایک دن ناغہ کرتا ہے؟ آپ نے فرمایا: ’’کیا کوئی شخص (ہمیشہ) اس کی طاقت رکھ سکتا ہے؟‘‘ انھوں نے پھر عرض کیا: اس شخص کے بارے میں کیا فرمان ہے جو ایک دن روزہ رکھتا ہے، ایک دن ناغہ کرتا ہے؟ اپ نے فرمایا: ’’یہ تو حضرت داؤد علیہ السلام کا روزہ ہے۔‘‘ انھوں نے عرض کیا: اس شخص کے بارے میں کیا رائے ہے جو ایک دن کا روزہ رکھتا ہے، دو دن افطار کرتا ہے؟ آپ نے فرمایا: ’’میری خواہش ہے کہ مجھے اس کی طاقت ہوتی۔‘‘ پھر فرمایا: ’’میری خواہش ہے کہ مجھے اس کی طاقت ہوتی۔‘‘ پھر فرمایا: ’’ہر مہینے میں تین روزے رکھ لینا اور ہر رمضان کے روزے رکھ لینا (ثواب کے لحاظ سے) زمانہ بھر کے روزے رکھ لینے کے برابر ہے۔‘‘","f2":"’’کیا کوئی شخص اس کی طاقت رکھ سکتا ہے؟‘‘ مقصد کراہت کا اظہار ہے کہ ساری زندگی طاقت نہ رکھے گا۔ آخر اس عمل کو چھوڑنا پڑے گا، لہٰذا یہ درست نہیں۔ (مزید دیکھئے حدیث: ۲۳۸۷)"}],[2388,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"روزوں میں سب سے افضل داود علیہ السلام کے روزے ہیں، وہ ایک دن روزہ رکھتے، اور ایک دن افطار کرتے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’افضل ترین روزے داؤدعلیہ السلام کے روزے ہیں۔ وہ ایک دن روزہ رکھتے اور ایک دن ناغہ فرماتے تھے۔‘‘","f2":"کہا گیا ہے کہ پابندی کے لحاظ سے یہ سخت ترین روزے ہیں مگر حضرت داؤدعلیہ السلام بڑے طاقت والے تھے۔"}],[2389,"مجاہد کہتے ہیں کہ مجھ سے عبداللہ بن عمرو رضی اللہ عنہما نے کہا: میرے والد نے میری شادی ایک اچھے خاندان والی عورت سے کر دی، چنانچہ وہ اس کے پاس آتے، اور اس سے اس کے شوہر کے بارے میں پوچھتے، تو (ایک دن) اس نے کہا: یہ بہترین آدمی ہیں ایسے آدمی ہیں کہ جب سے میں ان کے پاس آئی ہوں، انہوں نے نہ ہمارا بستر روندا ہے اور نہ ہم سے بغل گیر ہوئے ہیں، عمرو بن العاص رضی اللہ عنہ نے اس کا ذکر نبی اکرم صلی اللہ علیہ وسلم سے کیا تو آپ نے فرمایا: \"اسے میرے پاس لے کر آؤ\"، میں والد کے ساتھ آپ صلی اللہ علیہ وسلم کے پاس حاضر ہوا، تو آپ نے پوچھا: \"تم کس طرح روزے رکھتے ہو؟\" میں نے عرض کیا: ہر روز، آپ نے فرمایا:\"ہفتہ میں تین دن روزے رکھا کرو\"، میں نے کہا: میں اس سے زیادہ کی طاقت رکھتا ہوں، آپ نے فرمایا: \"اچھا دو دن روزہ رہا کرو اور ایک دن افطار کرو\"، میں نے کہا: میں اس سے زیادہ کی طاقت رکھتا ہوں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اچھا سب سے افضل روزے رکھے کرو جو داود علیہ السلام کے روزے ہیں، ایک دن روزہ اور ایک دن افطار\"۔","الألباني: صحيح",{"u2":"حضرت مجاہد بیان کرتے ہیں کہ حضرت عبداللہ بن عمرو رضی اللہ عنہ نے مجھ سے فرمایا کہ میرے والد نے ایک صاحب رتبہ (عالی نسب) خاتون سے میرا نکاح کر دیا، پھر وہ (اکثر) اس کے پاس آکر اس کے خاوند کے (یعنی میرے) بارے میں پوچھتے تو وہ خاتون کہتی: بڑے اچھے آدمی ہیں جو کبھی میرے بستر پر نہیں ائے اور جب سے میں آئی ہوں، کبھی میرا پہلو تلاش نہیں کیا۔ میرے والد نے یہ بات نبی صلی اللہ علیہ وسلم کے گوش گزار کی تو آپ نے فرمایا: ’’اسے لے کر میرے پاس آنا۔‘‘ میں ان کے ساتھ آپ صلی اللہ علیہ وسلم کے پاس حاضر ہوا تو آپ نے فرمایا: ’’تم روزے (نفل) کیسے رکھتے ہو؟‘‘ میں نے عرض کیا: ہر روز۔ آپ نے فرمایا: ’’ہر ہفتے سے تین دن روزے رکھو۔‘‘ میں نے عرض کیا: میں اس سے زیادہ کی طاقت رکھتا ہوں۔ آپ نے فرمایا: ’’دو دن روزہ رکھو اور ایک دن ناغہ کرو۔‘‘ میں نے عرض کیا: میں اس سے بھی زیادہ کی طاقت رکھتا ہوں۔ آپ نے فرمایا: ’’داؤد علیہ السلام کی طرح روزے رکھو جو افضل ترین روزے ہیں۔ ایک دن روزہ، ایک دن ناغہ۔‘‘","f2":"(۱) اس روایت میں سوال اور جواب کی ترتیب صحیح نہیں۔ کسی راوی سے غلطی ہوگئی ہے۔ اس نے یوں مخل اختصار کر دیا ہے۔ آئندہ روایات سے صحیح ترتیب معلوم ہو رہی ہے۔ (۲) ’’پہلو تلاش نہیں کیا۔‘‘ یعنی کبھی خاوند بیوی والا تعلق قائم نہیں کیا۔ حضرت عبداللہ رضی اللہ عنہ انتہائی متقی اور پرہیز گار تھے، اس لیے توجہ بیوی کی طرف نہ گئی۔ والد محترم نے خود توجہ دلانے کے بجائے رسول اللہ صلی اللہ علیہ وسلم سے رجوع کیا۔"}],[2390,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ میرے والد نے میری شادی ایک عورت سے کر دی، وہ اس سے ملاقات کے لیے آئے، تو اس سے پوچھا: تم نے اپنے شوہر کو کیسا پایا؟ اس نے کہا: کیا ہی بہترین آدمی ہیں نہ رات میں سوتے ہیں اور نہ دن میں کھاتے پیتے ہیں، ۱؎ تو انہوں نے مجھے سخت سست کہا اور بولے: میں نے تیری شادی ایک مسلمان لڑکی سے کی ہے، اور تو اسے چھوڑے رکھے ہے۔ میں نے ان کی بات پر دھیان نہیں دیا اس لیے کہ میں اپنے اندر قوت اور (نیکیوں میں) آگے بڑھنے کی صلاحیت پاتا تھا، یہ بات نبی اکرم صلی اللہ علیہ وسلم تک پہنچی تو آپ نے فرمایا: \"میں رات میں قیام بھی کرتا ہوں اور سوتا بھی ہوں، روزہ بھی رکھتا ہوں اور کھاتا پیتا بھی ہوں، تو تم بھی قیام کرو اور سوؤ بھی۔ اور روزہ رکھو اور افطار بھی کرو، ہر مہینے میں تین دن روزہ رکھا کرو\" میں نے کہا: میں اس سے زیادہ کی طاقت رکھتا ہوں، آپ نے فرمایا: \"تو پھر تم «صیام داودی» رکھا کرو، ایک دن روزہ رکھو اور ایک دن کھاؤ پیو\"، میں نے عرض کیا: میں اس سے بھی زیادہ کی طاقت رکھتا ہوں، آپ نے فرمایا: \"ہر مہینہ ایک مرتبہ قرآن پڑھا کرو\"، پھر آپ (کم کرتے کرتے) پندرہ دن پر آ کر ٹھہر گئے، اور میں کہتا ہی رہا کہ میں اس سے زیادہ کی طاقت رکھتا ہوں۔\n§وضاحت\n۱؎: یعنی رات میں قیام کرتے ہیں اور دن میں روزے سے رہتے ہیں۔","الألباني: صحيح الإسناد",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہ سے روایت ہے کہ میرے والد نے ایک خاتون سے میری شادی کر دی، پھر وہ اس سے ملنے آئے تو پوچھا: تیرا خاوند کیسا ہے؟ وہ کہنے لگی: اچھا آدمی ہے جو رات کو سوتا نہیں اور دن کو روزے سے ناغہ نہیں کرتا۔ تو والدہ محترم نے مجھے سخت سست کہا اور فرمانے لگے کہ میں نے ایک (بہترین) مسلمان عورت سے تیری شادی کی ہے اور تو نے اسے بن بیاہی بنا رکھا ہے؟ لیکن میں ان کے کہنے کی طرف توجہ نہیں دیتا تھا کیونکہ میں اپنے اندر (عبادت کی) قوت اور شوق پاتا تھا۔ یہ بات نبی صلی اللہ علیہ وسلم کو پہنچی تو آپ نے فرمایا: ’’لیکن میں تو رات کو نماز بھی پڑھتا ہوں اور سوتا بھی ہوں۔ روزہ بھی رکھتا ہوں اور ناغے بھی کرتا ہوں، چنانچہ تو نماز بھی پڑھ اور سو بھی۔ روزے بھی رکھ اور ناغے بھی کر۔‘‘ میں نے عرض کیا: مجھے اس سے زیادہ کی طاقت ہے۔ آپ نے فرمایا: ’’پھر داؤد علیہ السلام جیسے روزے رکھ۔ ایک دن روزہ رکھ اور ایک دن ناغہ کر۔‘ـ‘ میں نے کہا: مجھے اس سے زیادہ کی طاقت ہے۔ (مگر آپ نے اجازت نہ دی)، پھر آپ نے فرمایا: ’’ایک ماہ میں (تہجد کے دوران میں) ایک دفعہ قرآن ختم کیا کر۔‘‘ لیکن پھر (میرے بار بار کہنے پر) آپ پندرہ تک آگئے۔ میں اب بھی یہی کہہ رہا تھا: مجھے اس سے زائد کی طاقت ہے۔","f2":"اس حدیث میں بھی راوی نے اختصار کیا ہے۔ اسی روایت کی دوسری اسانید سے مروی الفاظ سے معلوم ہوتا ہے کہ ان کے بار بار اصرار کرنے پر رسول اللہ صلی اللہ علیہ وسلم ایک ماہ، پچیس دن، پھر بیس، پندرہ، دس، سات، پانچ سے گزرتے ہوئے تین دن پر آگئے تھے، یعنی تین راتوں میں قرآن ختم کر لیا کر۔ اس سے زائد کی اجازت نہیں دی تاکہ صحیح تلفظ، توجہ اور حضور قلب سے اسے پڑھا جائے۔"}],[2391,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم میرے حجرے میں داخل ہوئے اور فرمایا: \"کیا مجھے یہ خبر نہیں ملی ہے کہ تم رات میں قیام کرتے ہو اور دن میں روزہ رکھتے ہو؟\" انہوں نے کہا: کیوں نہیں، ہاں ایسا ہی ہے۔ آپ نے فرمایا: \"تم ایسا ہرگز نہ کرو، سوؤ بھی اور قیام بھی کرو، روزہ سے بھی رہو اور کھاؤ پیو بھی، کیونکہ تمہاری آنکھ کا تم پر حق ہے، اور تمہارے بدن کا تم پر حق ہے، تمہاری بیوی کا تم پر حق ہے، تمہارے مہمان کا تم پر حق ہے، اور تمہارے دوست کا تم پر حق ہے، توقع ہے کہ تمہاری عمر لمبی ہو، تمہارے لیے بس اتنا کافی ہے کہ ہر مہینے میں تین دن روزہ رکھا کرو، یہی صیام الدھر ہو گا کیونکہ نیکی کا ثواب دس گنا ہوتا ہے، میں نے عرض کیا: میں اپنے اندر طاقت پاتا ہوں، تو میں نے سختی چاہی تو مجھ پر سختی کر دی گئی، آپ نے فرمایا: \"ہر ہفتے تین دن روزہ رکھا کرو\"، میں نے عرض کیا: میں اس سے زیادہ کی طاقت رکھتا ہوں، تو میں نے سختی چاہی تو مجھ پر سختی کر دی گئی، آپ نے فرمایا: \"تم اللہ کے نبی داود علیہ السلام کے روزے رکھو\"، میں نے کہا: داود علیہ السلام کا روزہ کیا ہے؟ آپ نے فرمایا: \"ایک دن روزہ ایک دن افطار\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم میرے حجرے میں تشریف لائے اور فرمانے لگے: ’’کیا مجھے یہ بتایا نہیں گیا کہ تو ساری رات نماز پڑھتا رہتا ہے اور ہر دن روزہ رکھتا ہے؟‘‘ میں نے عرض کیا: جی ہاں، آپ نے فرمایا: ’’ایسے نہ کر۔ سو بھی اور قیام بھی کر۔ روزہ بھی رکھ اور ناغہ بھی کر۔ یقینا تیری آنکھ کا تجھ پر حق ہے، تیرے جسم کا تجھ پر حق ہے، تیری بیوی کا تجھ پر حق ہے، تیرے مہمان کا بھی تجھ پر حق ہے اور تیرے دوست کا بھی تجھ پر حق ہے۔ امید ہے تیری عمر لمبی ہوگی، لہٰذا تجھے یہ کافی ہے کہ ہر مہینے سے تین روزے رکھ لیا کر۔ یہ (ثواب کے لحاظ سے) زمانے بھر کے روزوں کے برابر ہو جائیں گے کیونکہ ہر نیکی کا بدلہ دس گنا ہے۔ میں نے عرض کیا: میں زیادہ طاقت رکھتا ہوں۔ میں نے اپنے آپ پر سختی کی تو مجھ پر سختی ڈال دی گئی۔ آپ نے فرمایا: ’’ہر ہفتے میں تین روزے رکھ لیا کر۔‘‘ میں نے کہا: میں اس سے زیادہ کی طاقت رکھتا ہوں۔ اس طرح میں نے اپنے آپ پر سختی کی تو مجھ پر سختی ڈال دی گئی۔ آپ نے فرمایا: ’’اللہ کے نبی حضرت داؤد علیہ السلام کی طرح روزہ رکھ لیا کر۔‘‘ میں نے کہا: حضرت داؤد علیہ السلام کے روزے کیسے تھے؟ آپ نے فرمایا: ’’نصف زمانہ۔ (یعنی ایک دن روزہ ایک دن ناغہ)۔‘‘","f2":"(۱) ’’تجھ پر حق ہے۔‘‘ لہٰذا ہر حق والے کو اس کا حق دے۔ آنکھ کا حق نیند، جسم کا حق آرام و خوراک، بیوی ک حق اس کے ساتھ شب بسری، مہمان کا حق مہمان نوازی اور اس کے ساتھ مل کر کھانا، دوست کا حق اس کے ساتھ اٹھنا بیٹھنا اور کھانا وغیرہ ہے۔ (۲) ’’تیری عمر لمبی ہوگی۔‘‘ اور بڑی عمر میں زیادہ عبادت کو قائم نہ رکھ سکے گا، لہٰذا اتنی عبادت شروع کر جسے قائم رکھ سکے۔ مگر حضرت عبداللہ رضی اللہ عنہ جوانی اور عبادت کے جوش میں سمجھ نہ سکے اور آخر عم رمیں تنگ ہوئے جسے وہ سختی ڈالنے سے تعبیر فرما رہے تھے۔"}],[2392,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سے ذکر کیا گیا کہ میں کہتا ہوں کہ میں جب تک زندہ رہوں گا ہمیشہ رات کو قیام کروں گا، اور دن کو روزہ رکھا کروں گا، تو رسول اللہ صلی اللہ علیہ وسلم نے پوچھا: تم ایسا کہتے ہو؟ میں نے آپ سے عرض کیا: اللہ کے رسول! جی ہاں میں نے یہ بات کہی ہے، آپ نے فرمایا: \"تم ایسا نہیں کر سکتے، تم روزہ بھی رکھو اور افطار بھی کرو، سوؤ بھی اور قیام بھی کرو، اور مہینے میں تین دن روزہ رکھو کیونکہ نیکی کا ثواب دس گنا ہوتا ہے، اور یہ صیام الدھر (پورے سال کے روزوں) کے مثل ہے\"، میں نے عرض کیا: میں اس سے زیادہ کی طاقت رکھتا ہوں، آپ نے فرمایا: \"ایک دن روزہ رکھو اور دو دن افطار کرو\"، پھر میں نے عرض کیا: اللہ کے رسول! میں اس سے زیادہ کی طاقت رکھتا ہوں، آپ نے فرمایا: \"اچھا ایک دن روزہ رکھو اور ایک دن افطار کرو، یہ داود علیہ السلام کا روزہ ہے، یہ بہت مناسب روزہ ہے\"، میں نے کہا: میں اس سے بھی زیادہ کی طاقت رکھتا ہوں، آپ نے فرمایا: \"اس سے بہتر کچھ نہیں\"۔ عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں: اگر میں نے مہینے میں تین دن روزہ رکھنے کی رسول اللہ صلی اللہ علیہ وسلم کی بات قبول کر لی ہوتی تو یہ میرے اہل و عیال اور میرے مال سے میرے لیے زیادہ پسندیدہ ہوتی۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمرو بن عاص رضی اللہ عنہ نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم کے سامنے میری بات ذکر کی گئی کہ میں ساری رات عبادت کیا کروں گا اور ہر دن روزہ رکھا کروں گا جب تک بھی زندہ رہا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تو یہ بات کہتا ہے؟‘‘ میں نے عرض کیا: اے اللہ کے رسول! یقینا میں نے یہ بات کہی ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تو اس کی طاقت نہیں رکھ سکے گا، لہٰذا روزہ رکھ اور ناغہ بھی کر، سو بھی اور عبادت بھی کر۔ اور ہر مہینے میں تین دن روزے رکھ لیا کر۔ چونکہ نیکی کا بدلہ دس گنا ہے، لہٰذا یہ (ثواب کے لحاظ سے) ہمیشہ روزے رکھنے کی طرح ہو جائیں گے۔‘‘ میں نے کہا: میں اس سے زیادہ کی طاقت رکھتا ہوں۔ آپ نے فرمایا: ’’پھر ایک دن رو زہ رکھ اور دو دن ناغہ کر۔‘‘ میں نے کہا: میں اس سے زیادہ کی طاقت رکھتا ہوں۔ آپ نے فرمایا: ’’پھر ایک دن روزہ رکھ اور ایک دن ناغہ کر۔ اور یہ حضرت داؤد علیہ السلام کے روزے ہیں اور یہ افضل ترین روزے ہیں۔‘‘ میں نے کہا: میں اس سے افضل کی طاقت رکھتا ہوں۔ آپ نے فرمایا: ’’اس سے افضل کوئی روزہ نہیں۔‘‘ حضرت عبداللہ بن عمرو رضی اللہ عنہ فرماتے ہیں کہ میں وہ تین روزے ہی قبول کر لیتا جو اللہ کے رسول صلی اللہ علیہ وسلم نے میرے لیے تجویز فرمائے تھے تو (اب) یہ مجھے میرے اہل ومال سے زیادہ پسند اور محبوب ہوتا۔","f2":"’’میں وہ تین روزے ہی قبول کر لیتا۔‘‘ یہ سوچ انھیں بڑھاپے میں آئی جب اس قدر سخت عبادت کو برداشت کرنا مشکل ہوگیا، مگر وہ جاری شدہ نیکی کو ختم کرنے یا کم کرنے کو بھی مناسب نہ سمجھتے تھے۔"}],[2393,"ابوسلمہ بن عبدالرحمٰن بن عوف کہتے ہیں کہ میں عبداللہ بن عمرو رضی اللہ عنہما کے پاس آیا۔ میں نے عرض کیا: چچا جان! رسول اللہ صلی اللہ علیہ وسلم نے آپ سے جو کہا تھا اسے مجھ سے بیان کیجئے۔ انہوں نے کہا: بھتیجے! میں نے پختہ عزم کر لیا تھا کہ میں اللہ کی عبادت کے لیے بھرپور کوشش کروں گا یہاں تک کہ میں نے کہہ دیا کہ میں ہمیشہ روزہ رکھوں گا، اور ہر روز دن و رات قرآن پڑھا کروں گا، رسول اللہ صلی اللہ علیہ وسلم نے اسے سنا تو میرے پاس تشریف لائے یہاں تک کہ گھر کے اندر میرے پاس آئے، پھر آپ نے فرمایا: \"مجھے یہ بات پہنچی ہے کہ تم نے کہا ہے کہ میں ہمیشہ روزہ رکھوں گا اور قرآن پڑھوں گا؟\" میں نے عرض کیا: ہاں اللہ کے رسول! میں نے ایسا کہا ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"ایسا مت کرو (بلکہ) ہر مہینے تین دن روزہ رکھ لیا کرو\"، میں نے عرض کیا: میں اس سے زیادہ رکھنے کی طاقت رکھتا ہوں، آپ نے فرمایا: \"ہر ہفتہ سے دو دن دوشنبہ (پیر) اور جمعرات کو روزہ رکھ لیا کرو\"، میں نے عرض کیا: میں اس سے بھی زیادہ رکھنے کی طاقت رکھتا ہوں، آپ نے فرمایا: \"داود علیہ السلام کا روزہ رکھا کرو کیونکہ اللہ تعالی کے نزدیک یہ سب سے زیادہ بہتر اور مناسب روزہ ہے، وہ ایک دن روزہ رکھتے اور ایک دن افطار کرتے، اور وہ جب وعدہ کر لیتے تو وعدہ خلافی نہیں کرتے تھے، اور جب دشمن سے مڈبھیڑ ہوتی تھی تو بھاگتے نہیں تھے\"۔","الألباني: منكر بزيادة الموعد",{"u2":"حضرت ابو سلمہ بن عبدالرحمن سے روایت ہے، میں حضرت عبداللہ بن عمرو رضی اللہ عنہ کے پاس گیا اور کہا: چچا جان! مجھے وہ بات بیان فرمائیے جو رسول اللہ صلی اللہ علیہ وسلم نے آپ کو ارشاد فرمائی تھی۔ وہ فرمانے لگے: اے بھتیجے! میں نے یہ عزم کیا تھا کہ میں عبادت میں سخت محنرو کروں گا حتیٰ کہ میں نے کہا: میں ہمیشہ روزے رکھوں گا اور ایک دن رات میں پورا قرآن مجید ختم کیا کروں گا۔ رسول اللہ صلی اللہ علیہ وسلم نے (کسی سے) یہ بات سن لی تو آپ میرے پاس تشریف لائے حتیٰ کہ میرے گھر میں داخل ہوگئے اور فرمانے لگے: ’’مجھے پتا چلا ہے کہ تو نے کہا ہے: میں ہمیشہ روزہ رکھا کروں گا اور (ہر روز) پورا قرآن (نماز میں) پڑھا کروں گا۔‘‘ میں نے عرض کیا: اے اللہ کے رسول! بلا شبہ میں نے یہ بات کہی ہے۔ آپ نے فرمایا: ’’ایسے نہ کرنا۔ ہر مہینے میں تین روزے رکھ لیا کر۔‘‘ میں نے عرض کیا: میں اس سے زیادہ کی طاقت رکھتا ہوں۔ آپ نے فرمایا: ’’پھر ہفتے میں دو دن، یعنی سوموار اور جمعرات کا روزہ رکھ لیا کر۔‘‘ میں نے کہا: میں اس سے بھی زیادہ کی طاقت رکھتا ہوں۔ آپ نے فرمایا: ’’پھر حضرت داؤد علیہ السلام جیسے روزے رکھا کر کیونکہ وہ اللہ تعالیٰ کے نزدیک بہترین (اور مناسب ترین) روزے ہیں۔ ایک دن روزہ اور ایک دن ناغہ اور حضرت داؤد علیہ السلام جب وعدہ فرما لیتے تھے تو خلاف ورزی نہ کرتے تھے اور جب دشمن سے مقابلہ ہوتا تو بھاگتے نہ تھے۔‘‘","f2":"’’بھاگتے نہ تھے۔‘‘ یہ دو اضافی صفات بیان فرمائیں جن کے ساتھ حضرت داؤد علیہ السلام متصف تھے۔ باوجود اس قدر روزے دار ہونے کے بہت زیادہ قوت کے مالک تھے۔ (وَاذْکُرْ عَبْدَنَا دَاوٗدَ ذَا الْاَبْدِ) (ص ۳۸: ۱۷)"}],[2394,"عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"ایک دن روزہ رکھ تمہیں باقی دنوں کا ثواب ملے گا\"۔ انہوں نے عرض کیا: میں اس سے زیادہ کی طاقت رکھتا ہوں، آپ نے فرمایا: \"دو دن روزہ رکھ تمہیں باقی دنوں کا اجر ملے گا\"، انہوں نے عرض کیا: میں اس سے بھی زیادہ کی طاقت رکھتا ہوں۔ آپ نے فرمایا: \"تین دن روزہ رکھو اور باقی دنوں کا ثواب ملے گا\"۔ انہوں نے عرض کیا: میں اس سے بھی زیادہ کی طاقت رکھتا ہوں، آپ نے فرمایا: \"چار دن روزہ رکھو اور تمہیں باقی دنوں کا بھی اجر ملے گا، انہوں نے عرض کیا: میں اس سے بھی زیادہ کی طاقت رکھتا ہوں۔ آپ نے فرمایا: تو پھر داود علیہ السلام کے روزے رکھو جو اللہ کے نزدیک سب سے افضل روزے ہیں، وہ ایک دن روزہ رکھتے تھے اور ایک دن بغیر روزہ کے رہتے تھے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا: ’’ایک روزہ رکھ لیا کر، باقی دنوں کا ثواب بھی تجھے مل جائے گا۔‘‘ میں نے کہا: مجھے اس سے زائد کی طاقت ہے۔ آپ نے فرمایا: ’’دو دن روزہ رکھ لیا کر، باقی دنوں کا ثواب بھی تجھے مل جائے گا۔‘‘ میں نے کہا: مجھے اس سے زائد کی طاقت ہے۔ آپ نے فرمایا: ’’تین دن روزہ رکھ لیا کر، باقی دنوں کا ثواب بھی تجھے مل جائے گا۔‘‘ میں نے کہا: مجھے اس سے زائد کی طاقت ہے۔ آپ نے فرمایا: ’’چار دن روزہ رکھ لیا کر، باقی دنوں کا ثواب بھی تجھے مل جائے گا۔‘‘ میں نے عرض کیا: مجھے اس سے بھی زائد کی طاقت ہے۔‘‘ آپ نے فرمایا: ’’تو حضرت داؤد علیہ السلام کے روزے رکھا کر جو اللہ تعالیٰ کے نزدیک افضل ترین روزے ہیں۔ وہ ایک دن روزہ رکھتے تھے اور ایک دن ناغہ فرماتے تھے۔‘‘","f2":"’’ایک روزہ رکھ۔‘‘ اگر پورے مہینے میں ایک روزہ مراد ہے، پھر یہ کسی راوی کی غلطی ہے کیونکہ کسی دوسری روایت سے اس کی تائید نہیں ہوتی۔ اور اگر دس دن میں سے ایک دن کا روزہ مراد ہے جیسا کہ آئندہ حدیث میں ہے تو پھر یہ درست ہے کیونکہ ایک روزے کا ثواب دس کے برابر ہے اور یہی مفہوم صحیح ہے۔ سوال اور جواب کی ترتیب بھی اس کی تائید کرتی ہے۔"}],[2395,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم سے روزہ کا ذکر کیا تو آپ نے فرمایا: \"ہر دس دن پر ایک دن روزہ رکھو، تمہیں ان باقی نو دنوں کا اجر و ثواب ملے گا\"، میں نے عرض کیا: میں اس سے زیادہ کی طاقت رکھتا ہوں، آپ نے فرمایا: \"ہر نو دن پر ایک دن روزہ رکھو اور تمہیں ان آٹھ دنوں کا بھی ثواب ملے گا\"، میں نے عرض کیا: میں اس سے بھی زیادہ کی طاقت رکھتا ہوں، آپ نے فرمایا: \"ہر آٹھ دن پر ایک دن روزہ رکھ اور تجھے باقی سات دنوں کا بھی ثواب ملے گا\"، میں نے عرض کیا: میں اس سے بھی زیادہ کی طاقت رکھتا ہوں، آپ برابر اسی طرح فرماتے رہے یہاں تک کہ آپ نے فرمایا: \"ایک دن روزہ رکھو اور ایک دن افطار کرو\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہ بیان کرتے ہیں کہ میں نے نبی صلی اللہ علیہ وسلم کے سامنے روزے کا ذکر کیا تو آپ نے فرمایا: ’’ہر دس دن میں ایک دن روزہ رکھ لیا کر، باقی نو دن کا ثواب بھی تجھے مل جائے گا۔‘‘ میں نے کہا: مجھ میں اس سے زیادہ طاقت ہے۔ آپ نے فرمایا: ’’پھر ہر نو دن میں ایک روزہ رکھ لیا کر، تجھے باقی آٹھ دنوں کا ثواب بھی مل جائے گا۔‘‘ میں نے کہا: مجھ میں مزید طاقت ہے۔ آپ نے فرمایا: ’’ہر آٹھ دن میں ایک دن روزہ رکھ لیا کر، تجھے باقی سات دن کا ثواب بھی مل جائے گا۔‘‘ میں نے کہا: مجھ میں اس سے بھی زیادہ طاقت ہے۔ آپ مزید اضافہ فرماتے رہے حتیٰ کہ آپ نے فرمایا: ’’ایک دن روزہ رکھ اور ایک دن ناغہ کر۔‘‘","f2":"دس دن میں ایک دن کا روزہ بھی اتنا ہی ثواب رکھتا ہے جتنا دو دن میں ایک دن کا مگر روزے کے اور بھی تو فوائد ہیں۔ مشقت کا اجر بھی تو روزے کے ثواب سے الگ ملتا ہے۔ ظاہر ہے تین روزوں سے پندرہ روزوں کی مشقت بہر صورت زیادہ ہے، البتہ ایک ماہ میں پندرہ سے زائد روزے رکھنے کی مستقل عادت بنا لینا درست نہیں کیونکہ اس میں نقصانات ہیں۔"}],[2396,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ مجھ سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک دن روزہ رکھ تمہیں دس دن کا ثواب ملے گا\"، میں نے عرض کیا: میرے لیے کچھ اضافہ فرما دیجئیے، آپ نے فرمایا: \"دو دن روزہ رکھ تمہیں نو دن کا ثواب ملے گا\"، میں نے عرض کیا: میرے لیے کچھ اور بڑھا دیجئیے، آپ نے فرمایا:\"تین دن روزہ رکھ لیا کرو تمہیں آٹھ دن کا ثواب ملے گا\"۔ ثابت کہتے ہیں: میں نے مطرف سے اس کا ذکر کیا، تو انہوں نے کہا: میں محسوس کرتا ہوں کہ وہ کام میں تو بڑھ رہے ہیں لیکن اجر میں گھٹتے جا رہے ہیں، یہ الفاظ محمد بن اسماعیل بن ابراہیم کے ہیں۔","الألباني: صحيح الإسناد",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہ سے مروی ہے، مجھ سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ایک دن روزہ رکھ۔ تجھے دس روزوں کا ثواب ملے گا۔‘‘ میں نے کہا: اور زیادہ کیجئے۔ آپ نے فرمایا: ’’دو دن روزہ رکھ لے، تجھے نو روزوں کا ثواب ملے گا۔‘‘ میں نے کہا: مزید زیادہ کیجئے۔ آپ نے فرمایا: ’’تین دن کے روزے رکھ لے، تجھے آٹھ روزوں کا ثواب ملے گا۔‘‘ (راوی حدیث) ثابت نے کہا: میں نے حضرت مطرف سے یہ حدیث بیان کی تو انھوں نے کہا: میرا خیال ہے عمل بڑھ رہا ہے، ثواب کم ہو رہا ہے۔ حدیث کے الفاظ محمد (بن اسماعیل) کے بیان کردہ ہیں (زکریا بن یحییٰ کے نہیں)","f2":"(۱)اس حدیث میں امام نسائی رحمہ اللہ کے دو استاد ہیں: محمد بن اسماعیل اور زکریا بن یحییٰ۔ بیان کردہ الفاظ محمد بن اسماعیل کے ہیں۔ واللفظ لمحمد کا مفہوم یہ ہے۔ (۲) ’’ثواب کم ہو رہا ہے۔‘‘ یوں سمجھ لیجئے کہ جتنا ثواب دس دن میں ایک روزے کا ہے، اتنا ہی دس دن میں دو روزوں کا اور اتنا ہی دس دن میں تین روزوں کا۔ مزید تفصیل کے لیے سابقہ حدیث کے فائدے کا مطالعہ کیجئے۔"}],[2397,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: مجھے خبر ملی ہے کہ تم رات میں قیام کرتے ہو، اور دن کو روزہ رکھتے ہو؟ میں نے عرض کیا: اللہ کے رسول! میں نے اس سے خیر کا ارادہ کیا ہے، آپ نے فرمایا: \"جس نے ہمیشہ کا روزہ رکھا اس نے روزہ ہی نہیں رکھا، لیکن میں تمہیں بتاتا ہوں کہ ہمیشہ کا روزہ کیا ہے؟ یہ مہینہ میں صرف تین دن کا روزہ ہے\"، میں نے عرض کیا: اللہ کے رسول! میں اس سے زیادہ کی طاقت رکھتا ہوں، آپ نے فرمایا: \"پانچ دن رکھ لیا کرو\"، میں نے عرض کیا: میں اس سے بھی زیادہ کی طاقت رکھتا ہوں، آپ نے فرمایا: \"تو دس دن رکھ لیا کرو\"، میں نے عرض کیا: میں اس سے بھی زیادہ کی طاقت رکھتا ہوں، آپ نے فرمایا: \"تم داود علیہ السلام کے روزے رکھا کرو\"، وہ ایک دن روزہ رکھتے تھے اور ایک دن افطار کرتے تھے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا: ’’مجھے یہ بات پہنچی ہے کہ تو ساری رات قیام کرتا ہے اور ہر روز روزہ رکھتا ہے۔‘‘ میں نے عرض کیا: اے اللہ کے رسول! میرا ارادہ تو نیکی ہی کا ہے۔ آپ نے فرمایا: ’’جو ہمیشہ روزہ رکھے، اس کا کوئی روزہ نہیں، لیکن میں تجھے ہمیشہ کے روزے کا ایک طریقہ بتاتا ہوں: مہینے میں تین روزے رکھ۔‘‘ (ثواب پورے مہینے کا برابر ہوگا۔) میں نے کہا: اے اللہ کے رسول! میں اس سے زیادہ کی طاقت طاقت رکھتا ہوں۔ آپ نے فرمایا: ’’(مہینے میں) پانچ دن روزہ رکھ۔‘‘ میں نے کہا: میں اس سے زیادہ کی طاقت رکھتا ہوں۔ آپ نے فرمایا: ’’پھر دس رکھ۔‘‘ میں نے کہا: میں اس سے زیادہ کی طاقت رکھتا ہوں۔ آپ نے فرمایا: ’’حضرت داؤد علیہ السلام کے روزے رکھا کر۔ وہ ایک دن روزہ رکھتے تھے اور ایک دن ناغہ فرماتے تھے۔‘‘"}],[2398,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا، پھر راوی نے پوری حدیث ذکر کی۔",""],[2399,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا: \"عبداللہ بن عمرو! تم ہمیشہ روزہ رکھتے ہو اور رات میں کرتے ہو، جب تم ایسا کرو گے تو آنکھیں اندر کو دھنس جائیں گی اور نفس تھک جائے گا، جو ہمیشہ روزہ رہے گا اس کا روزہ نہ ہو گا، ہر مہینے میں تین دن کا روزہ پورے سال کے روزہ کے برابر ہے\"، میں نے عرض کیا: میں اس سے زیادہ کی طاقت رکھتا ہوں، آپ نے فرمایا: \"صوم داود رکھو، وہ ایک دن روزہ رکھتے تھے اور ایک دن بغیر روزہ کے رہتے تھے، اور جب دشمن سے مڈبھیڑ ہوتی تو بھاگتے نہیں تھے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا: ’’اے عبداللہ بن عمرو! تو ہمیشہ روزے رکھتا ہے اور ساری ساری رات عبادت کرتا ہے۔ اور جب تو ایسے کرے گا، تیری آنکھیں اندر کو دھنس جائیں گی اور طبیعت تھک جائے گی۔ اس شخص کا کوئی روزہ نہیں جس نے ہمیشہ روزہ رکھا۔ ہمیشہ روزہ رکھنے کا جائز طریقہ یہ ہے کہ ہر مہینے سے تین دن روزہ رکھا جائے۔ یہ (ثواب کے لحاظ سے) زمانے بھر کا روزہ بن جائے گا۔‘‘ میں نے کہا: میں اس سے زائد کی طاقت رکھتا ہوں۔ آپ نے فرمایا: ’’حضرت داؤد علیہ السلام کے روزے رکھ۔ وہ ایک دن روزہ رکھتے تھے اور ایک دن ناغہ کرتے تھے۔ اور جب دشمن کا سامنا ہوتا تھا تو بھاگتے نہ تھے۔‘‘","f2":"روزے سے انسانی جسم کے غیر ضروری اجزاء تحلیل ہو جاتے ہیں جس سے انسان جفا کش بن جاتا ہے۔ قوت برداشت میں اضافہ ہو جاتا ہے۔ بھوک، پیاس، تکلیف اور مشقت برداشت کرنے کی عادت پڑ جاتی ہے۔ اخلاقی وروحانی طور پر انسان قوی ہو جاتا ہے۔ اور جنگ میں انھی چیزوں کی ضرورت ہوتی ہے، البتہ بلاناغہ روزہ انسان کو کمزور اور عاجز کر دیتا ہے، لہٰذا وہ جائز نہیں۔"}],[2400,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا: \"قرآن ایک مہینہ میں پڑھا کرو\"، میں نے عرض کیا: میں اس سے زیادہ کی طاقت رکھتا ہوں، اور پھر میں برابر آپ سے مطالبہ کرتا رہا، یہاں تک کہ آپ نے فرمایا: \"پانچ دن میں پڑھا کرو، اور مہینہ میں تین دن روزہ رکھو\"، میں نے عرض کیا: میں اس سے زیادہ کی طاقت رکھتا ہوں، تو میں برابر آپ سے مطالبہ کرتا رہا یہاں تک کہ آپ نے فرمایا: \"داود علیہ السلام کا روزہ رکھو، جو اللہ تعالی کو سب سے زیادہ پسند ہے، وہ ایک دن روزہ رکھتے تھے، اور ایک دن بغیر روزہ کے رہتے تھے\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہ سے منقول ہے، مجھ سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مہینے میں ایک دفعہ قرآن مجید ختم کیا کر۔‘‘ میں نے کہا: میں اس سے زائد کی طاقت رکھتا ہوں۔ اس طرح میں بار بار آپ سے مزید مطالبہ کرتا رہا حتیٰ کہ آپ نے فرمایا: ’’پانچ دن میں ختم کر لیا کر۔‘‘ آپ نے فرمایا: ’’مہینے میں تین روزے رکھا کر۔‘‘ میں نے کہا: مجھے اس سے زائد کی طاقت ہے۔ اس طرح میں آپ سے بار بار مطالبہ کرتا رہا حتیٰ کہ آپ نے فرمایا: ’’داؤد علیہ السلام کی طرح روزے رکھ جو اللہ تعالیٰ کو سب سے زیادہ پسندیدہ ہیں۔ وہ ایک دن روزہ رکھتے تھے اور ایک دن افطار کرتے تھے۔‘‘","f2":"’’پانچ دن میں۔‘‘ حدیث: ۲۳۹۲ کے تحت گزر چکا ہے کہ آخر کار آپ نے تین دن میں ختم قرآن کی اجازت دے دی تھی۔ تفصیل وہاں دیکھی جائے۔"}],[2401,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کو خبر ملی کہ میں روزہ رکھتا ہوں اور مسلسل رکھتا ہوں، اور رات میں نماز تہجد پڑھتا ہوں، تو رسول اللہ صلی اللہ علیہ وسلم نے انہیں بلا بھیجا، یا آپ ان سے ملے تو آپ نے فرمایا: \"کیا مجھے خبر نہیں دی گئی ہے کہ تم (ہمیشہ) روزہ رکھتے ہو، اور کبھی بغیر روزہ کے نہیں رہتے، اور رات میں تہجد کی نماز پڑھتے ہو، تم ایسا نہ کرو کیونکہ تمہاری آنکھ کا بھی ایک حصہ ہے، اور تمہارے نفس کا بھی ایک حصہ ہے، تمہاری بیوی کا بھی ایک حصہ ہے، تم روزہ بھی رکھو اور افطار بھی کرو، نماز بھی پڑھو اور سوؤ بھی، ہر دس دن میں ایک دن روزہ رکھو، تمہیں باقی نو دنوں کا بھی ثواب ملے گا\"، انہوں نے عرض کیا: اللہ کے رسول! میں اس سے زیادہ کی طاقت رکھتا ہوں۔ آپ نے فرمایا: \"پھر تو تم روزہ داود رکھا کرو\"، پوچھا: اللہ کے نبی! داود علیہ السلام کے روزہ کیسے ہوا کرتے تھے؟ آپ نے فرمایا: \"وہ ایک دن روزہ رکھتے تھے اور ایک دن افطار کرتے تھے، اور جب دشمن سے مڈبھیڑ ہوتی تو بھاگتے نہیں تھے\"، انہوں نے کہا: کون ایسا کر سکتا ہے؟ اللہ کے نبی!۔","الألباني: صحيح الإسناد ق نحوه دون قوله قال ومن لي",{"u2":"حضرت عبداللہ بن عمرو بن عاص رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کو یہ بات پہنچی کہ میں لگاتار روزے رکھتا ہوں اور ساری ساری رات نماز پڑھتا رہتا ہوں۔ آپ نے مجھے بلا بھیجا، یا میں آپ کو ملا (یا آپ مجھے ملے) آپ نے فرمایا: ’’کیا مجھے یہ نہیں بتایا گیا کہ تو مسلسل روزے رکھتا ہے، کب ھی ناغہ نہیں کرتا، اور ساری ساری رات نماز پڑھتا رہتا ہے؟ ایسے نہ کر۔ تیری آنکھ کو اس کا حق (نیند) ملنا چاہیے اور تیری بیوی کو بھی اس کا حق (شب بسری) ملنا چاہیے۔ روزے بھی رکھ، ناغے بھی کر، نماز بھی پڑھ اور نیند بھی پوری کر۔ ہر دس دن میں ایک دن روزہ رکھ۔ باقی نو دن (کے روزوں کا ثواب بھی تجھے مل جائے گا۔‘‘ میں نے عرض کیا: اے اللہ کے رسول! مجھ میں اس سے زیادہ طاقت ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تب حضرت داؤد علیہ السلام کی طرح روزے رکھ۔‘‘ میں نے کہا: اے اللہ تعالیٰ کے نبی! حضرت داؤد علیہ السلام کس طرح روزے رکھتے تھے؟ آپ نے فرمایا: ’’وہ ایک دن روزہ رکھتے تھے اور ایک دن ناغہ کرتے تھے اور جب دشمن سے مقابلہ ہوتا تو بھاگتے نہ تھے۔‘‘ میں کہا: اے اللہ کے نبی! میرے لیے اس (آخری) بات کا کون ضامن ہوگا؟ (یعنی یہ بہت مشکل کام ہے، روزہ بھی اور جہاد بھی)۔","f2":"’’آپ نے مجھے بھلا بھیجا۔‘‘ روایات میں مختلف الفاظ ہیں: کسی میں ہے کہ آپ نے مجھے پیغام بھیجا، میں گیا۔ کسی میں ہے کہ آپ میرے پاس تشریف لائے۔ کسی میں ہے کہ مجھے میرے والد نبی صلی اللہ علیہ وسلم کے پاس لے کر گئے۔ تطبیق یوں ممکن ہے کہ ان کے والد محترم کے کہنے پر رسول اللہ صلی اللہ علیہ وسلم نے انھیں ساتھ لانے کو کہا، نیز کسی اور کے ذریعے سے آنے کا پیغام بھی بھیج دیا، پھر باپ بیٹا دونوں آپ کے پاس آئے۔ آپ نے مختصر سی بات کی، پھر ان کے گھر جا کر تفصیلی بات چیت کی کیونکہ علیحدگی میں کوئی جھجک نہیں ہوتی۔"}],[2402,"ابوقلابۃ ابوالملیح سے روایت کرتے ہیں کہ انہوں نے کہا: میں تمہارے والد زید کے ساتھ عبداللہ بن عمرو رضی اللہ عنہما کے پاس آیا، تو انہوں نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم سے میرے روزہ کا ذکر کیا گیا تو آپ میرے پاس تشریف لائے، میں نے آپ کے لیے چمڑے کا ایک درمیانی تکیہ لا کر رکھا جس کا بھراؤ کھجور کی پیتاں تھیں، آپ زمین پر بیٹھ گئے، اور تکیہ ہمارے اور آپ کے درمیان ہو گیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا ہر مہینے میں تین دن تمہارے روزہ کے لیے کافی نہیں ہیں؟\" میں نے عرض کیا: اللہ کے رسول! (کچھ بڑھا دیجئیے) آپ نے فرمایا: \"پانچ دن کر لو\"، میں نے پھر عرض کیا: اللہ کے رسول! (کچھ بڑھا دیجئیے)آپ نے فرمایا: \"سات دن کر لو\"، میں نے پھر عرض کیا: اللہ کے رسول! کچھ اور بڑھا دیجئیے! آپ نے فرمایا: \"نو دن\"، میں نے پھر عرض کیا: اللہ کے رسول!(کچھ اور بڑھا دیجئیے) تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"گیارہ دن کر لو\"، میں نے پھر عرض کیا: اللہ کے رسول! (کچھ بڑھا دیجئیے) آپ نے فرمایا: \"داود علیہ السلام کے روزہ سے بڑھ کر کوئی روزہ نہیں ہے، اور وہ اس طرح ہے ایک دن روزہ رکھا جائے، اور ایک دن بغیر روزہ کے رہا جائے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہ سے روایت ہے، انھوں نے بیان فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم کے سامنے میرے مسلسل روزے رکھنے کا ذکر ہوا۔ آپ میرے پاس تشریف لائے۔ میں نے آپ کے لیے ایک درمیانہ سا چمڑے کا گدا بچھایا جس میں کھجور کی چھال بھری ہوئی تھی لیکن آپ زمین ہی پر بیٹھ گئے اور وہ گدا میرے اور آپ کے درمیان رہ گیا۔ آپ نے فرمایا: ’’تجھے ہر مہینے سے تین روزے کافی ہیں؟‘‘ میں نے عرض کیا: اے اللہ کے رسول! (مزید اجازت دیجئے)۔ آپ نے فرمایا: ’’پانچ روزے۔‘‘ میں نے کہا: اے اللہ کے رسول! (مزید)۔ آپ نے فرمایا: ’’سات روزے۔‘‘ میں نے کہا: اے اللہ کے رسول! (کچھ اور)۔ آپ نے فرمایا: ’’نو روزے۔‘‘ میں پھر بولا: اے اللہ کے رسول! (کچھ اور)۔ آپ نے فرمایا: ’’گیارہ روزے۔‘‘ میں نے پھر کہا: اے اللہ کے رسول! (کچھ اور)۔ تو نبی صلی اللہ علیہ وسلم نے فرمایا: ’’حضرت داؤد علیہ السلام کے روزوں سے بڑھ کر کوئی روزہ نہیں، یعنی نصف زمانہ کہ ایک دن روزہ اور ایک دن ناغہ۔‘‘"}],[2403,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا: \"مہینے میں ایک دن روزہ رکھو تمہیں باقی دنوں کا ثواب ملے گا\"، میں نے عرض کیا: میں اس سے زیادہ کی طاقت رکھتا ہوں، آپ نے فرمایا: \"دو دن رکھ لیا کر، تجھے باقی دنوں کا ثواب مل جایا کرے گا\"، میں نے کہا: میں اس سے زیادہ کی طاقت رکھتا ہوں، آپ نے فرمایا: \"تو تین دن رکھ لیا کرو تمہیں باقی دنوں کا بھی اجر ملا کرے گا\"، میں نے کہا: میں اس سے بھی زیادہ کی طاقت رکھتا ہوں، تو آپ نے فرمایا: \"چار دن رکھ لیا کرو باقی دنوں کا بھی اجر بھی تمہیں ملا کرے گا\"، میں نے عرض کیا: میں اس سے بھی زیادہ کی طاقت رکھتا ہوں تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سب سے افضل روزہ داود علیہ السلام کا روزہ ہے، وہ ایک دن روزہ رکھتے تھے اور ایک دن افطار کرتے تھے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہ کا بیان ہے کہ مجھ سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’۔مہینے میں ایک روزہ رکھ لے، تجھے باقی دنوں کا ثواب مل جائے گا۔‘‘ میں نے کہا: مجھے اس سے زیادہ کی طاقت ہے۔ فرمایا: ’’پھر دو دن روزہ رکھ لے، تجھے باقی دنوں کا ثواب مل جائے گا۔‘‘ میں نے عرض کیا: مجھے اس سے زیادہ کی طاقت ہے۔ آپ نے فرمایا: ’’پھر تین دن روزہ رکھ لے، تجھے باقی دنوں کا ثواب مل جائے گا۔‘‘ میں نے عرض کیا: مجھے اس سے زیادہ کی طاقت ہے۔ آپ نے فرمایا: ’’چار دن روزہ رکھ لے۔ تجھے باقی دنوں کا ثواب مل جائے گا۔‘‘ میں نے کہا: مجھے اس سے زیادہ کی طاقت ہے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’افضل ترین روزہ حضرت داؤد علیہ السلام کا روزہ ہے۔ وہ ایک دن روزہ رکھتے تھے اور ایک دن ناغہ کرتے تھے۔"}],[2404,"ابوذر رضی اللہ عنہ کہتے ہیں کہ میرے حبیب صلی اللہ علیہ وسلم نے مجھے تین باتوں کی وصیت کی ہے میں انہیں ان شاءاللہ کبھی چھوڑ نہیں سکتا: آپ نے مجھے صلاۃ الضحی (چاشت کی نماز) پڑھنے کی وصیت کی، اور سونے سے پہلے وتر پڑھنے کی، اور ہر مہینے تین دن روزہ رکھنے کی۔","الألباني: صحيح ق دون قوله لا أدعهن أبدا وعند خ معناه",{"u2":"حضرت ابو ذر رضی اللہ عنہ فرماتے ہیں کہ مجھے میرے پیارے حبیب صلی اللہ علیہ وسلم نے تین باتوں کی نصیحت فرمائی اور ان شاء اللہ تعالیٰ میں انھیں کبھی نہیں چھوڑوں گا: مجھے نصیحت فرمائی کہ صلاۃ ضحی پڑھا کروں، وتر پڑھ کر سوؤں اور ہر مہینے سے تین روزے رکھوں۔","f2":"(۱) ’’صلاۃ ضحی۔‘‘ چاشت کی نفل نماز تاکہ انسان کے دن کی ابتدا نماز سے ہو۔ (۲) ’’وتر پڑھ کر سوؤں۔‘‘ تاکہ وتر محفوظ ہو جائیں۔ فجر سے پہلے اٹھنا یقینی نہیں ہوتا خصوصاً نوجوان طالب علم کے لیے۔ (۳) ’’تین روزے۔‘‘ تاکہ ہمیشہ روزہ رکھنے کا ثواب مل سکے۔ کمزوری بھی نہ ہو اور اخلاقی و روحانی اور جسمانی کمال بھی حاصل ہو۔"}],[2405,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے تین چیزوں کا حکم دیا ہے: وتر پڑھ کر سونے کا، جمعہ کے دن غسل کرنے کا ۱؎، اور ہر مہینے تین دن روزہ رکھنے کا۔\n§وضاحت\n۱؎: یہی ٹکڑا منکر ہے، صحیح صلاۃ الضحی \" چاشت کی نماز \" ہے جیسا کہ اگلی روایت میں ہے۔","الألباني: منكر بذكر الغسل والمحفوظ صلاة الضحى",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ فرماتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے تین چیزوں کا حکم دیا: وتر پڑھ کر سونا۔ جمعۃ المبارک کے دن غسل کرنا اور ہر مہینے سے تین دن روزے رکھنا۔"}],[2406,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے صلاۃ الضحی (چاشت کی نماز) دو رکعتیں پڑھنے کا، اور بغیر وتر پڑھے نہ سونے کا، اور ہر مہینے تین دن روزہ رکھنے کا حکم دیا ہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ نے فرمایا: ’’مجھے رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا کہ چاشت کی دو رکعتیں پڑھا کروں اور وتر پڑھے بغیر نہ سوؤں اور ہر مہینے سے تین دن کے روزے رکھا کروں۔"}],[2407,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے وتر پڑھ کر سونے، جمعہ کے دن غسل کرنے، اور ہر مہینے تین دن روزہ رکھنے کا حکم دیا۔","الألباني: منكر",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے وتر پڑھ کر سونے، جمعۃ المبارک کے دن غسل کرنے اور ہر مہینے سے تین دن روزے رکھنے کا حکم دیا"}],[2408,"ابوعثمان سے روایت ہے کہ ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو کہتے ہوئے سنا: \"صبر کے مہینے کے، اور ہر مہینے سے تین دن کے روزے صوم الدهر ہیں\"۔\n§وضاحت\n۱؎: صبر کے مہینہ سے مراد رمضان کا مہینہ ہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا کہ صبر کا مہینہ (یعنی رمضان المبارک) اور ہر مہینے سے تین روزے (ثواب کے لحاظ سے) زمانے بھر کے روزوں کے برابر ہیں۔","f2":"رمضان المبارک کے روزے تو فرض ہیں۔ باقی ہر مہینے سے تین روزے ثواب کے لحاظ سے پورے مہینے کے برابر ہیں۔ رمضان المبارک کو صبر کا مہینہ فرمایا گیا ہے کیونکہ روزہ نام ہی صبر کا ہے۔ کھانے پینے سے صبر، شہوت سے صبر، جھگڑے اور گالی گلوچ سے صبر۔"}],[2409,"ابوذر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے مہینے کے تین دن روزہ رکھے تو گویا اس نے صوم الدهر رکھے\"، پھر آپ نے فرمایا:\"اللہ تعالی نے اپنی کتاب میں سچ فرمایا ہے: «من جاء بالحسنة فله عشر أمثالها» \"جو کوئی ایک نیکی لائے گا اسے دس گنا ثواب ملے گا\" (الانعام: ۱۶۰)۔","الألباني: صحيح",{"u2":"حضرت ابوذر رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص ہر مہینے تین روزے رکھے تو یوں سمجھو اس نے زمانہ بھر کے روزے رکھ لیے۔‘‘ پھر فرمایا: ’۔اللہ تعالیٰ نے اپنی کتاب قرآن مجید میں سچ فرمایا ہے: {مَنْ جَآئَ بِالْحَسَنَۃِ فَلَہٗ عَشْرُ أَمْثَالِھَا} ’’جو شخص نیکی کرے گا اسے (اس نیکی کا) دس گنا ثواب دیا جائے گا۔‘‘"}],[2410,"ابوعثمان ایک شخص سے روایت کرتے ہیں کہ ابوذر رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"جس نے ہر مہینے میں تین روزہ رکھے تو اس نے (گویا) پورے مہینے کے روزہ رکھے\"، یا یہ (فرمایا): \"اس کے لیے پورے مہینے کے روزہ کا ثواب ہے\"، عاصم راوی کو یہاں شک ہوا ہے۔","الألباني: ضعيف الإسناد",{"u2":"حضرت ابو ذر رضی اللہ عنہ سے مروی ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم نے فرماتے سنا: ’’جو شخص ہر مہینے سے تین روزے رکھے تو گویا مہینے بھر کے روزے ہوگئے (یا اسے مہینے بھر کے روزوں کا ثواب ملے گا)۔‘‘","f2":"۲۴۱۱ اور ۲۴۱۲ دونوں روایات کو محقق کتاب نے ضعیف قرار دیا ہے جبکہ سنن ابن ماجہ (۱۷۰۸) کی تحقیق میں روایت: ۲۴۱۱ کے متعلق لکھتے ہیں کہ اس حدیث کا صحیح شاہد سنن نسائی (حدیث: ۲۳۰۸ اور ۲۴۰۹) میں ہے۔ محقق کتاب کے کلام سے معلوم ہوتا ہے کہ مذکورہ روایت کی محقق کتاب کے نزدیک بھی کوئی نہ کوئی اصل ضرور ہے، نیز دیگر محققین نے اسے صحیح قرار دیا ہے۔ بنا بریں مذکورہ دونوں روایات قابل عمل اور قابل حجت ہیں۔ مزید تفصیل کے لیے دیکھئے: (ذخیرۃ العقبیٰ شرح سنن النسائی: ۲۱/ ۳۳۳، وارواء الغلیل: ۴/ ۱۲۰)"}],[2411,"عثمان بن ابی العاص رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"ہر مہینے کے تین دن کے روزہ بہترین روزہ ہیں\"۔","الألباني: صحيح",{"u2":"حضرت عثمان بن ابی العاص رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’اچھے روزے ہر ماہ میں تین روزے ہیں۔‘‘"}],[2412,"اس سند سے سعید بن ابی ہند نے روایت کی ہے کہ عثمان بن ابی العاص رضی اللہ عنہ نے اسی طرح کہا ہے، اور یہ مرسل ہے۔","",{"u2":"حضرت سعید بن ابی ہند بھی حضرت عثمان بن ابی العاص رضی اللہ عنہ سے مذکورہ بالا روایت کی مثل بیان کرتے ہیں۔ یہ روایت مرسل (منقطع) ہے۔","f2":"مرسل سے مراد یہاں منقطع ہے۔ منقطع اس بنا پر ہے کہ سعید اور حضرت عثمان کے درمیان واسطہ ذکر نہیں کیا گیا۔"}],[2413,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم ہر مہینے میں تین دن روزہ رکھتے تھے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم ہر ماہ تین دن روزہ رکھتے تھے۔"}],[2414,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم ہر مہینے تین دن روزے رکھتے تھے، مہینے کے پہلے دوشنبہ (پیر) کو، اور اس کے بعد کے قریبی جمعرات کو، پھر اس کے بعد کے جمعرات کو۔","الألباني: صحيح لغيره",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم ہر ماہ تین دن روزہ رکھا کرتے تھے۔ مہینے کی پہلی سوموار اور جمعرات کو اور پھر اگلی جمعرات کو۔"}],[2415,"ہنیدہ خزاعی کہتے ہیں کہ میں ام المؤمنین کے پاس آیا، اور میں نے انہیں کہتے ہوئے سنا کہ رسول اللہ صلی اللہ علیہ وسلم ہر مہینے تین دن روزہ رکھتے تھے۔ مہینے کے پہلے کہ دوشنبہ (پیر) کو، پھر جمعرات کو، پھر اس کے بعد کے آنے والے جمعرات کو۔","الألباني: صحيح",{"u2":"حضرت ہنیدہ خزاعی سے روایت ہے کہ میں ام المومنین (حضرت حفصہ رضی اللہ عنہا) کی خدمت میں حاضر ہوا۔ میں نے سنا آپ فرما رہی تھیں: رسول اللہ صلی اللہ علیہ وسلم ہر ماہ تین دن روزہ رکھا کرتے تھے: مہینے کی پہلی سوموار کو، پھر جمعرات کو، پھر اگلی جمعرات کو۔"}],[2416,"ام المؤمنین حفصہ رضی اللہ عنہا کہتی ہیں کہ چار باتیں ایسی ہیں جنہیں نبی اکرم صلی اللہ علیہ وسلم نہیں چھوڑتے تھے: ۱- عاشوراء کے روزے کو ۲- ذی الحجہ کے پہلے عشرہ کے روزے کو ۱؎ ۳- ہر مہینہ کے تین روزے ۴- اور فجر سے پہلے کی دونوں رکعتوں کو۔\n§وضاحت\n۱؎: مراد ذی الحجہ کے ابتدائی نو دن ہیں، ذی الحجہ کی دسویں تاریخ اس سے خارج ہے کیونکہ یوم النحر کو روزے رکھنا جائز نہیں۔","الألباني: ضعيف",{"u2":"حضرت حفصہ رضی اللہ عنہا فرماتی ہیں کہ چار کام نبی صلی اللہ علیہ وسلم کبھی نہیں چھوڑتے تھے: عاشوراء (۱۰محرم) کا روزہ، ذوالحجہ کے پہلے عشرے (یعنی نو دن) کے روزے، ہر مہینے سے تین دن کے روزے اور نماز فجر سے پہلے دو رکعتیں۔‘‘","f2":"’’ذوالحجہ کے روزے۔‘‘ حدیث میں دس دن کا ذکر ہے مگر مراد نو دن ہیں کیونکہ دسواں دن عید کا ہے۔ اور عید کے دن روزہ رکھنا قطعاً منع ہے۔ تغلیباً نو کو دس دن کہہ دیا جاتا ہے۔ آئندہ حدیث میں نو ہی کا ذکر ہے۔"}],[2417,"نبی اکرم صلی اللہ علیہ وسلم کی بعض بیویوں سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم ذی الحجہ کے نو روزے، عاشوراء کے دن (یعنی دسویں محرم کو) اور ہر مہینے میں تین روزے رکھتے ۱؎ ہر مہینہ کے پہلے دوشنبہ (پیر) کو، اور دوسرا اس کے بعد والی جمعرات کو، پھر اس کے بعد والی جمعرات کو۔\n§وضاحت\n۱؎: پہلی تاریخ سے لے کر نویں تاریخ تک۔","الألباني: صحيح",{"u2":"نبی صلی اللہ علیہ وسلم کی کسی زوجہ محترمہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم ذوالحجہ کے نو دن، عاشوراء کے دن اور ہر مہینے سے تین دن (یعنی پہلا سوموار اور اس کے بعد والی دو جمعراتیں) روزہ رکھتے تھے۔","f2":"’’ذوالحجہ کے نو دن۔‘‘ حضرت عائشہ رضی اللہ عنہا سے صحیح مسلم میں روایت ہے: میں نے رسول اللہ صلی اللہ علیہ وسلم کو ان دنوں کبھی روزے سے نہیں دیکھا۔ (صحیح مسلم، الاعتکاف، حدیث: ۱۱۷۶) مگر اسے تعارض کے بجائے عدم علم پر محمول کیا جائے گا، یعنی حضرت عائشہ رضی اللہ عنہا نے اپنے علم کی نفی کی ہے۔ اس سے یہ لازم نہیں آتا کہ نبی صلی اللہ علیہ وسلم روزے نہ رکھتے تھے۔ حضرت حفصہ رضی اللہ عنہا نے آپ کو روزے سے دیکھا تو روزہ بیان کردیا۔"}],[2418,"نبی اکرم صلی اللہ علیہ وسلم کی ایک بیوی کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم (ذی الحجہ کے پہلے) عشرہ میں روزے رکھتے تھے، اور ہر مہینہ میں تین دن: دوشنبہ(پیر) اور (دو) جمعرات کو۔","الألباني: صحيح بلفظ الخميسين",{"u2":"نبی صلی اللہ علیہ وسلم کی کوئی زوجہ محترمہ بیان کرتی ہیں کہ نبی صلی اللہ علیہ وسلم عشرہ ذوالحجہ (یعنی نو دن) اور ہر مہینے سے تین دن روزہ رکھتے تھے: (پہلا) سوموار کو اور اس کے بعد جمعرات کو (یعنی دو جمعراتیں)۔"}],[2419,"ام المؤمنین ام سلمہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہر مہینے میں تین دن۔ ہر مہینے کی پہلی جمعرات کو، اور دو اس کے بعد والے دو شنبہ (پیر) کو پھر اس کے بعد والے دوشنبہ (پیر) کو روزے رکھنے کا حکم دیتے تھے ۱؎۔\n§وضاحت\n۱؎: یہ حدیث اس بات پر دلالت کرتی ہے کہ آپ نے دوشنبہ :(پیر ) کو مکرر رکھنے کا حکم دیا اور اس سے پہلے ایک حدیث گزری ہے جس میں ہے کہ آپ جمعرات کو مکرر رکھتے تھے، ان دونوں روایتوں کے ملانے سے یہ بات معلوم ہوئی کہ مطلوب ان دونوں دنوں میں تین دن روزے ہیں، خواہ وہ دوشنبہ :(پیر ) کو مکرر کر کے ہوں یا جمعرات کو، واللہ اعلم۔","الألباني: شاذ",{"u2":"حضرت ام سلمہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم (ہر مہینے میں) تین دن کے روزوں کا حکم دیتے تھے، یعنی مہینے کی پہلی جمعرات اور دو سوموار۔","f2":"(۱)۔ ’’حکم دیتے تھے۔‘‘ یعنی استحباب کے طور پر۔ (۲) ’’پہلی جمعرات۔‘‘ سابقہ روایات میں پہلے سوموار کا ذکر ہے۔ مقصود یہ ہے کہ پہلے جمعرات آجاتی تو جمعرات، سوموار اور پھر اگلے سوموار کا روزہ رکھتے اور اگر مہینے کے شروع میں سوموار پہلے آجاتا تو سوموار، جمعرات اور پھر اگلی جمعرات کا روزہ رکھ لیتے، یعنی تین روزے سوموار اور جمعرات میں محصور ہوتے تھے۔ ابتدا جمعرات سے ہو یا سوموار سے، کوئی فرق نہیں۔"}],[2420,"جریر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"ہر مہینے میں تین دن کا روزے پورے سال کا روزے ہے\" (یعنی ایام بیض کے روزے) اور ایام بیض (چاند کی) تیرہویں چودہویں اور پندرہویں راتیں ہیں ۱؎۔\n§وضاحت\n۱؎: انہیں ایام بیض اس لیے کہتے ہیں کہ ان کی راتیں چاندنی کی وجہ سے سفید اور روشن ہوتی ہیں۔","الألباني: حسن",{"u2":"حضرت جریر بن عبداللہ رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’ہر مہینے تین روزے رکھنا (ثواب کے لحاظ سے) زمانے بھر کے روزوں کے برابر ہے۔ اور ایام بیض (چمکتی راتوں والے دن) تیرہ، چودہ اور پندرہ ہیں۔‘‘","f2":"ان تین راتوں میں چاند پورا ہوتا ہے اور ساری رات رہتا ہے، اس لیے ان کو چمکتی راتیں کہا۔ مقصد مہینے میں تین روزے رکھنا ہے۔ ان دنوں میں رکھے یا سوموار اور جمعرات کے لحاظ سے یا جیسے اتفاق ہو۔"}],[2421,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ ایک اعرابی رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک بھنا ہوا خرگوش لے کر آیا، اور اسے آپ کے سامنے رکھ دیا، تو رسول اللہ صلی اللہ علیہ وسلم نے اپنے آپ کو روکے رکھا خود نہیں کھایا، اور لوگوں کو حکم دیا کہ وہ کھا لیں، اور اعرابی (دیہاتی) بھی رکا رہا، تو نبی اکرم صلی اللہ علیہ وسلم نے اعرابی(دیہاتی) سے پوچھا: \"تم کیوں نہیں کھا رہے ہو؟\" اس نے کہا: میں مہینے میں ہر تین دن روزے رکھتا ہوں، آپ نے فرمایا: \"اگر تم روزے رکھتے ہو تو ان دنوں میں رکھو جن میں راتیں روشن رہتی ہیں\" ۱؎۔\n§وضاحت\n۱؎: یعنی چاند کی تیرہویں، چودہویں اور پندرہویں تاریخوں میں۔","الألباني: ضعيف",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ ایک اعرابی بھنا ہوا خرگوش لے کر نبی صلی اللہ علیہ وسلم کے پاس آیا اور اسے آپ کے سامنے رکھ دیا۔ رسول اللہ صلی اللہ علیہ وسلم نے ہاتھ روک لیا اور نہ کھایا اور لوگوں سے کہا کہ وہ کھالیں۔ اعرابی نے بھی ہاتھ روکے رکھا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تجھے کھانے میں کیا رکاوٹ ہے؟‘‘ اس نے کہا کہ میں ہر مہینے میں تین دن روزے رکھتا ہوں۔ آپ نے فرمایا: ’’اگر روزے رکھنے ہوں تو چاندنی راتوں (کے دنوں) کے (یعنی چاند کی ۱۳، ۱۴ اور ۱۵ تاریخ کو) روزے رکھا کر۔‘‘"}],[2422,"ابوذر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں حکم دیا ہے کہ ہم مہینے کے تین روشن دنوں: تیرہویں، چودہویں، اور پندرہویں کو روزے رکھا کریں۔","الألباني: حسن",{"u2":"حضرت ابوذر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں حکم دیا کہ ہم ہر مہینے میں ایام بیض (روشن راتوں کے دنوں) کے تین روزے رکھا کریں، یعنی (چاند کی) تیرہ، چودہ اور پندرہ تاریخ کو۔\nحضرت ابوذر رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں ہر ماہ تین روشن (راتوں کے) دنوں کے روزے رکھنے کا حکم دیا، یعنی تیرہ چودہ اور پندرہ کو۔","f2":"ان تین دنوں میں روزے رکھنے کی حکمت شاید یہ ہو کہ چونکہ ان کی راتیں چاند سے منور ہوتی ہیں، لہٰذا مناسب ہے کہ ان کے دن روزے کے نور سے منور ہوں۔\nان دنوں کی راتوں کے روشن ہونے کی وجہ سے ان دنوں کو بھی مجازقاً روشن کہہ دیا ورنہ دن تو سارے ہی روشن ہوتے ہیں۔ یا ایام بیض اصل میں ایام اللیالی البیض ہے، یعنی روشن راتوں والے تین دن۔"}],[2423,"ابوذر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں حکم دیا ہے کہ ہم ہر مہینے کے ایام بیض یعنی تیرہویں، چودہویں اور پندرہویں کو روزے رکھیں۔","الألباني: حسن"],[2424,"موسی بن طلحہ کہتے ہیں کہ میں نے ابوذر رضی اللہ عنہ کو مقام ربذہ میں کہتے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا: \"جب تم مہینے میں کچھ دن روزے رکھو تو تیرہویں، چودہویں، اور پندرہویں کو رکھو\"۔","الألباني: حسن",{"u2":"حضرت موسیٰ بن طلحہ بیان کرتے ہیں کہ میں نے ربذہ بستی میں حضرت ابوذر رضی اللہ عنہ سے سنا، وہ فرما رہے تھے کہ مجھ سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تو مہینے میں کچھ دنوں کے روزے رکھے تو (چاند کی) تیرہ، چودہ اور پندرہ تاریخ کو رکھ۔‘‘"}],[2425,"ابوذر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ایک شخص سے فرمایا: \"تم تیرہویں، چودہویں اور پندرہویں کے روزے کو اپنے اوپر لازم کر لو\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: یہاں (راوی سے) غلطی ہوئی ہے، یہ بیان کی روایت نہیں ہے۔ غالباً ایسا ہوا ہے کہ سفیان نے کہا «حدثنا اثنان» کہا ہو تو«اثنان» کا الف گر گیا پھر «ثنان» سے بیان ہو گیا (جیسا کہ اگلی روایت میں ہے)۔","الألباني: حسن لغيره",{"u2":"حضرت ابوذر رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے ایک آدمی سے فرمایا: (چاند کی) ’’تیرہ، چودہ اور پندرہ تاریخ کے روزے رکھا کر۔‘‘\nامام ابوعبدالرحمن (نسائی)k بیان کرتے ہیں کہ یہ غلطی ہے۔ یہ حدیث ’’بیان کی‘‘ کی نہیں ہے، ہو سکتا ہے کہ حضرت سفیان نے حَدَّثَنَا اِثْنَانِ کہا ہو، الف گر گیا اور کسی راوی نے غلطی سے اسے ’’بیان‘‘ پڑھ لیا۔","f2":"مذکورہ حدیث کی سند میں حضرت سفیان کا استاد ’’بیان‘‘ کہا گیا ہے لیکن یہ درست نہیں ہے آئندہ حدیث میں صراحت ہے کہ سفیان نے کہا: ’’مجھے دو آدمیوں نے یہ روایت بیان کی۔‘‘ دو کو عربی ـ میں اِثْنَانِ کہتے ہیں، گویا یہاں بھی اثنان تھا، غلطی سے بیان پڑھ لیا گیا۔ واللہ اعلم"}],[2426,"ابوذر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ایک شخص کو تیرہویں، چودہویں، اور پندرہویں کو روزے رکھنے کا حکم دیا۔","الألباني: حسن لغيره",{"u2":"حضرت ابوذر رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے ایک آدمی کو تیرہ، چودہ اور پندرہ تاریخ کے روزے رکھنے کا حکم دیا۔"}],[2427,"ابی بن کعب رضی اللہ عنہ کہتے ہیں کہ ایک اعرابی (دیہاتی) رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، اور اس کے ساتھ ایک بھنا ہوا خرگوش اور روٹی تھی، اس نے اسے نبی اکرم صلی اللہ علیہ وسلم کے آگے لا کر رکھا۔ پھر اس نے کہا: میں نے دیکھا ہے کہ اسے حیض آتا ہے، تو رسول اللہ صلی اللہ علیہ وسلم نے اپنے اصحاب سے فرمایا:\"کوئی نقصان نہیں تم سب کھاؤ\"، اور آپ نے اعرابی (دیہاتی) سے فرمایا: تم بھی کھاؤ، اس نے کہا: میں روزے سے ہوں، آپ نے پوچھا: \"کیسا روزے؟\" اس نے کہا: ہر مہینے میں تین دن کا روزے، آپ نے فرمایا: \"اگر تمہیں یہ روزے رکھنے ہیں تو روشن اور چمکدار راتوں والے دنوں یعنی تیرہویں، چودہویں، اور پندرہویں کو لازم پکڑو\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: صحیح «عن ابی ذر» ہے، قرین قیاس یہ ہے کہ «ذر» کاتبوں سے چھوٹ گیا۔ اس طرح وہ «ابی بن کعب» ہو گیا۔","الألباني: ضعيف",{"u2":"حضرت ابن حوتکہ سے روایت ہے کہ میرے والد (رضی اللہ عنہ) نے فرمایا کہ ایک اعرابی رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوا۔ اس کے پاس بھنا ہوا خرگوش تھا اور روٹیاں بھی تھیں۔ اس نے یہ سب کچھ نبی صلی اللہ علیہ وسلم کے سامنے رکھ دیا، پھر کہا: میں نے اسے اس حالت میں پایا تھا کہ یہ (اس کا گوشت) خون آلود تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے اپنے صحابہ سے فرمایا: ’’کوئی حرج نہیں، کھاؤ۔‘‘ اور آپ نے اعرابی سے فرمایا: ’’تو بھی کھا۔‘‘ اس نے کہا: میرا تو روزہ ہے۔ آپ نے فرمایا: ’’کیسا روزہ؟‘‘ اس نے کہا: مہینے کے تین روزے۔ آپ نے فرمایا: ’’اگر تو نے یہ روزے رکھنے ہوں تو چاندنی راتوں کے دنوں کے روزے رکھا کر، یعنی تیرہ، چودہ اور پندرہ تاریخ کو۔‘‘\nامام ابو عبدالرحمن نسائی رحمہ اللہ نے فرمایا: ’’صحیح بات یہ ہے کہ یہ روایت ابن حوتکیہ نے حضرت ابوذر رضی اللہ عنہ سے سنی ہے، شاید کسی کاتب سے لفظ ذر (لکھنے سے) رہ گیا ہے اور اس نے ابی کہہ دیا ہے۔","f2":"(۱) امام نسائی رحمہ اللہ فرماتے ہیں کہ یہ روایت حضرت ابوذر رضی اللہ عنہ سے ہے۔ غلطی سے ابی ذر کو کسی راوی نے ابی پڑھ لیا، ذر رہ گیا یا لکھنے سے ذر رہ گیا، صرف ابی لکھا گیا، اور یہ غلطی آگے منتقل ہوگئی۔ (۲) اکثر اہل علم نے تَدْمٰی کے معنی تحیض (حیض آنے) کے کیے ہیں اور اس بنا پر اس کا گوشت حلال نہیں سمجھتے۔ لیکن اول تو حیض، یعنی خون آنا حرمت کی دلیل نہیں۔ ثانیاً: اگر اس کے معنی گوشت کے خون آلود ہونے کے کر لیے جائیں تو زیادہ صحیح ہے کیونکہ اس کا گوشت ایسا ہی ہوتا ہے۔ (۳) ربذہ، یہ بستی مدینہ منورہ سے کوئی تین میل کے فاصلے پر ہے۔ حضرت ابوذر رضی اللہ عنہ اپنی خوشی سے یہاں منتقل ہوگئے تھے اور یہیں فوت ہوئے… رضی اللہ عنہ …\nیہ حضرت عثمان رضی اللہ عنہ کے دور کی بات ہے۔"}],[2428,"موسی بن طلحہ سے روایت ہے کہ ایک شخص نبی اکرم صلی اللہ علیہ وسلم کے پاس خرگوش لے کر آیا، آپ نے اس کی طرف ہاتھ بڑھایا ہی تھا کہ اس کے لانے والے نے کہا: میں نے اس کے ساتھ خون (حیض) دیکھا تھا (یہ سن کر) رسول اللہ صلی اللہ علیہ وسلم نے اپنا ہاتھ روک لیا، اور لوگوں کو حکم دیا کہ وہ کھا لیں، ایک آدمی لوگوں سے الگ تھلگ بیٹھا ہوا تھا، تو نبی اکرم صلی اللہ علیہ وسلم نے اس سے پوچھا: \"کیا بات ہے، تم الگ تھلگ کیوں بیٹھے ہو؟\" اس نے کہا: میں روزے سے ہوں، آپ نے فرمایا: \"پھر تم ایام بیض: تیرہویں، چودہویں اور پندرہویں کو کیوں نہیں رکھتے؟\"۔","الألباني: ضعيف",{"u2":"حضرت موسیٰ بن طلحہ سے روایت ہے کہ ایک شخص نبی اکرم صلی اللہ علیہ وسلم کے پاس (بھنا ہوا) خرگوش لے کر آیا۔ نبی صلی اللہ علیہ وسلم نے اس کی طرف ہاتھ بڑھایا ہی تھا کہ لانے والے شخص نے کہا کہ میں نے اس کے ساتھ خون دیکھا تھا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے اپنا ہاتھ روک لیا اور صحابہ کو کھانے کا حکم دیا۔ وہاں ایک شخص الگ بیٹھا تھا۔ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’تو کیوں نہیں کھاتا؟‘‘ اس نے کہا: میرا روزہ ہے۔ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’تو چاندنی راتوں: تیرہ، چودہ اور پندرہ (تاریخ) کے روزے کیوں نہیں رکھتا؟‘‘","f2":"نبی صلی اللہ علیہ وسلم کا ہاتھ روک لینا حرمت کی بنا پر نہیں تھا، ورنہ آپ صحابہ کو کھانے کا حکم نہ دیتے۔ طبعاً آپ نے پسند نہ کیا جیسے رسول اللہ صلی اللہ علیہ وسلم کچا لہسن وغیرہ بھی نہیں کھاتے تھے، حالانکہ وہ سب کے نزدیک حلال ہے۔"}],[2429,"موسی بن طلحہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کے پاس ایک خرگوش لایا گیا جسے ایک شخص نے بھون رکھا تھا، جب اس نے اسے آپ کے سامنے پیش کیا تو کہا: میں نے دیکھا اسے خون (حیض) آ رہا تھا، رسول اللہ صلی اللہ علیہ وسلم نے اسے چھوڑ دیا، نہیں کھایا، اور ان لوگوں سے جو آپ کے پاس موجود تھے فرمایا: \"تم کھاؤ، اگر مجھے اس کی خواہش ہوتی میں بھی کھاتا\"، اور وہ شخص (جو اسے لایا تھا) بیٹھا ہوا تھا، رسول اللہ صلی اللہ علیہ وسلم نے اس سے فرمایا: \"قریب آ جاؤ، اور تم بھی لوگوں کے ساتھ کھاؤ\"، اس نے عرض کیا: اللہ کے رسول! میں روزے سے ہوں، آپ نے فرمایا: \"تو تم نے بیض کے روزے کیوں نہیں رکھے؟\" اس نے پوچھا: وہ کیا ہیں؟ آپ نے فرمایا: \"تیرہویں، چودہویں اور پندرہویں کے روزے\"۔","الألباني: ضعيف",{"u2":"حضرت موسیٰ بن طلحہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک خرگوش لایا گیا جسے ایک شخص نے بھونا تھا۔ جب اس نے اسے آپ کے سامنے پیش کیا تو کہنے لگا: اے اللہ کے رسول! میں نے اس کے ساتھ خون دیکھا تھا تو رسول اللہ صلی اللہ علیہ وسلم نے اسے چھوڑ دیا اور نہ کھایا، البتہ حاضرین سے فرمایا: ’’تم کھاؤ۔ اگر مجھے خواہش ہوتی تو کھا لیتا۔‘‘ ایک آدمی الگ بیٹھا رہا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تو بھی قریب ہو کر لوگوں کے ساتھ کھا لے۔‘‘ اس نے کہا: اے اللہ کے رسول! میں روزے سے ہوں۔ آپ نے فرمایا: ’’تو نے چاندنی راتوں والے روزے کیوں نہ رکھ لیے۔‘‘ اس نے کہا: وہ کون سے ہیں؟ آپ نے فرمایا: ’’تیرہ، چودہ اور پندرہ (تاریخ کے)۔‘‘"}],[2430,"قتادہ بن ملحان (ابن منہال) رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم بیض کے ان تینوں دنوں کے روزے رکھنے کا حکم دیتے تھے، اور فرماتے تھے: \"یہ مہینے بھر کے روزے کے برابر ہیں\"۔","الألباني: ضعيف",{"u2":"حضرت عبدالملک اپنے والد سے بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم چاندنی راتوں والے تین دنوں کے روزے رکھنے کا حکم دیتے تھے اور فرماتے تھے: ’’یہ تین روزے (ثواب کے لحاظ سے) مہینے بھر کے روزوں کے برابر ہیں۔‘‘"}],[2431,"ابوالمنہال قتادہ بن ملحان رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے انہیں ایام بیض کے تین روزے کا حکم دیا اور فرمایا: \"یہ مہینہ بھر کے روزے کے برابر ہیں\"۔","الألباني: ضعيف",{"u2":"حضرت عبدالملک بن ابومنہال اپنے والد سے بیان کرتے تھے کہ نبی صلی اللہ علیہ وسلم نے صحابہ کرام رضی اللہ عنہم کو چاندنی راتوں والے تین دنوں کے روزے رکھنے کا حکم دیا۔ اور فرمایا: ’’یہ مہینے بھر کے روزوں کے برابر ہیں۔‘‘"}],[2432,"قدامہ (قتادہ بن ملحان) بن ملحان رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہمیں روشن چاندنی راتوں کے دنوں یعنی تیرہویں، چودہویں اور پندرہویں تاریخ کو روزے رکھنے کا حکم دیتے تھے۔","الألباني: ضعيف",{"u2":"حضرت عبدالملک بن قدامہ بن ملحان نے اپنے والد سے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم ہمیں چاندنی راتوں والے دنوں کے روزوں کا حکم دیا کرتے تھے، یعنی (چاند کی) تیرہ، چودہ اور پندرہ (تاریخ) کا۔","f2":"(۱) یہ تینوں روایات ایک ہی صاحب بیان فرماتے ہیں، البتہ ان کے والد کے نام کے بارے میں اختلاف ہے۔ علاوہ ازیں یہ تینوں روایات سنداً ضعیف اور معناً صحیح ہیں۔ شیخ البانیk نے مذکورہ تینوں روایات کو حسن قرار دیا ہے۔ دیکھیے: (ارواء الغلیل: ۴/ ۱۰۱،۱۰۲۔ رقم الحدیث: ۹۴۷، وصحیح سنن النسائی: ۲/ ۱۷۰، ۱۷۱ رقم: ۲۴۲۳، ۲۴۲۵، ۲۴۲۵) (۲) حکم ہمیشہ وجوب کے لیے نہیں ہوتا، قرائن ساتھ دیں تو حکم استحباب یا جواز کے لیے بھی ہوتا ہے، جیسے قرآن کریم میں ارشاد ہے: {وَاِذَا حَلَلْتُمْ فَاصْطَادُوْا} (المآئدۃ۵: ۲) ’’جب احرام کھول لو تو شکار کرو۔‘‘ {فَاِذَا قُضِیَتِ الصَّلٰوۃُ فَانْتَشِرُوْا فِی الْاَرْضِ} (الجمعۃ ۶۲: ۱۰) ’’جب جمعے کی نماز پڑھ لی جائے تو زمین میں پھیل جاؤ۔‘‘ اہل علم میں سے کسی کے نزدیک بھی یہ دونوں کام ضروری نہیں، کوئی بے علم شخص کہہ دے تو الگ بات ہے۔"}],[2433,"ابوعقرب رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے روزے رکھنے کے بارے پوچھا، تو آپ نے فرمایا: \"مہینہ میں ایک دن رکھ لیا کرو\"، میں نے عرض کیا: اللہ کے رسول! میرے لیے کچھ بڑھا دیجئیے، میرے لیے کچھ بڑھا دیجئیے، آپ نے فرمایا: \"تم کہتے ہو: اللہ کے رسول! کچھ بڑھا دیجئیے، کچھ بڑھا دیجئیے، تو ہر مہینے دو دن رکھ لیا کرو\"، میں نے عرض کیا: اللہ کے رسول! کچھ اور بڑھا دیجئیے، کچھ اور بڑھا دیجئیے، میں اپنے کو طاقتور پاتا ہوں، اس پر آپ نے میری بات\"کچھ اور بڑھا دیجئیے، کچھ اور بڑھا دیجئیے میں اپنے آپ کو طاقتور پاتا ہوں\" دہرائی پھر خاموش ہو گئے یہاں تک کہ میں نے خیال کیا کہ اب آپ مجھے لوٹا دیں گے، پھر آپ نے فرمایا: \"ہر مہینے تین دن رکھ لیا کرو\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابوعقرب رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے نقل روزے کے بارے میں پوچھا تو آپ نے فرمایا: ’’مہینے میں ایک روزہ رکھ لیا کر۔‘‘ میں نے عرض کیا: اے اللہ کے رسول! بڑھائیے، بڑھائیے۔ آپ نے (میری بات دوہراتے ہوئے) فرمایا: ’’اے اللہ کے رسول! بڑھائیے بڑھائیے۔ چلو مہینے میں دو دن روزہ رکھ لیا کر۔‘‘ میں نے پھر کہا: اے اللہ کے رسول! بڑھائیے بڑھائیے، میں اپنے آپ کو طاقتور محسوس کرتا ہوں۔ آپ نے (میری بات دوہراتے ہوئے) فرمایا: ’’اے اللہ کے رسول! بڑھائیے بڑھائیے، میں اپنے اپ کو طاقتور محسوس کرتا ہوں۔‘‘ پھر رسول اللہ صلی اللہ علیہ وسلم خاموش ہوگئے حتیٰ کہ میں نے سمجھا کہ آپ میری درخواست رد کر دیں گے۔ آخر آپ نے فرمایا: ’’ہر مہینے میں تین روزے رکھ لیا کر۔‘‘","f2":"رسول اللہ صلی اللہ علیہ وسلم کا حضرت ابو عقرب کی بات کو دوہرانا استہزا کے طور پر نہیں بلکہ اظہار کراہت کے لیے تھا، گویا آپ نے ان کے لیے زیادہ نفل روزے رکھنا پسند نہیں فرمایا۔ ممکن ہے وہ حقیقتاً کمزور ہوں یا مشقت والا کام کرتے ہوں۔"}],[2434,"ابوعقرب رضی اللہ عنہ کہتے ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روزے کے بارے پوچھا، تو آپ نے فرمایا: \"مہینہ میں ایک دن رکھ لیا کرو\"، انہوں نے مزید کی درخواست کی اور کہا: میرے ماں باپ آپ پر قربان ہوں، میں اپنے آپ کو طاقتور پاتا ہوں، تو آپ نے اس میں اضافہ فرما دیا، فرمایا: \"ہر مہینہ دو دن رکھ لیا کرو\"، تو انہوں نے کہا: میرے ماں باپ آپ پر قربان ہوں میں اپنے آپ کو طاقتور پاتا ہوں، تو رسول اللہ صلی اللہ علیہ وسلم نے (میری بات) \"میں اپنے کو طاقتور پاتا ہوں، میں اپنے کو طاقتور پاتا ہوں\" دہرائی، آپ اضافہ کرنے والے نہ تھے، مگر جب انہوں نے اصرار کیا تو آپ نے فرمایا: \"ہر مہینہ تین دن رکھ لیا کرو\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابوعقرب رضی اللہ عنہ سے روایت ہے، انھوں نے نبی صلی اللہ علیہ وسلم سے نفل روزے کے بارے میں پوچھا تو آپ نے فرمایا: ’’مہینے میں ایک روزہ رکھ لیا کر۔‘‘ میں نے مزید اجازت مانگی اور کہا: میرے ماں باپ آپ پر فدا ہوں! میں اپنے آپ کو طاقتور محسوس کرتا ہوں۔ آپ نے مزید اجازت دے دی۔ اور فرمایا: ’’ہر مہینے دو روزے رکھ لیا کر۔‘‘ میں نے کہا: اے اللہ کے رسول! میرے ماں باپ آپ پر قربان! میں اپنے آپ کو طاقتور سمجھتا ہوں۔ رسول اللہ صلی اللہ علیہ وسلم نے (میری بات دوہراتے ہوئے) فرمایا: ’’میں اپنے آپ کو طاقت ور سمجھتا ہوں۔ میں اپنے آپ کو طاقت ور سمجھتا ہوں۔‘‘ امید نہیں تھی کہ آپ مزید اجازت فرمائیں گے۔ جب میں نے اصرار کیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ہر مہینے تین روزے رکھ لیا کر۔‘‘","f2":"گزشتہ تمام روایات سے معلوم ہوا نفل روزے کم سے کم رکھے جائیں تاکہ پابندی ہو سکے اور حقوق العباد اور معاش میں بھی خلل واقع نہ ہو۔ مہینے میں تین روزے کافی ہیں۔ اللہ تعالیٰ اپنے فضل سے پورے مہینے کے روزوں کا ثواب عطا فرما دے گا۔ اس سے زیادہ روزے رکھنا مستحسن نہیں، جائز ہیں۔ نفل روزوں میں اپنی سہولت کا خیال رکھے۔ تینوں روزے اکٹھے رکھنا ضروری نہیں۔ ہر دس دن میں ایک روزہ رکھ لے۔ یا سوموار اور جمعرات کے حساب سے پورے کرے۔ مشقت نہ ہو تو چاندنی راتوں والے دنوں کے تین روزے اکٹھے رکھنا افضل ہے۔ مسلسل روزے رکھنا منع ہے۔ شعبان کے آخری ایک دو دن، عیدین اور ایام تشریق کے روزے رکھنا بھی منع ہے۔ صرف جمعے کے دن روزہ رکھنے سے روکا گیا ہے۔ اسی طرح ہفتے کے دن روزہ رکھنے سے بھی روکا گیا ہے۔ آگے یا پیچھے کوئی اور روزہ بھی رکھا جائے۔ مخصوص روزے، مثلاً: شوال کے چھ روزے اکٹھے رکھے جا سکتے ہیں، ذوالحجہ کے نو روزے اکٹھے رکھے جائیں گے، اس میں کوئی حرج نہیں کیونکہ یہ سارے سال میں ایک ہی دفعہ آتے ہیں۔ سفر میں مشقت نہ ہو تو رمضان المبارک کے روزے رکھ لینا بہتر ہے اور اگر مشقت ہو یا دوسروں کے لیے بوجھ بنے تو نہ رکھنا بہتر ہے۔ جہاد کے دوران میں بھی اگر لڑائی ہو رہی ہے، یا عنقریب ہونے والی ہے تو قوت کے حصول کے لیے رمضان المبارک کے روزے نہ رکھنا افضل ہے، بعد میں روزے پورے کر لے۔ اگر لڑائی دو رہے تو روزے رکھنا بہتر ہے۔ دوران سفر میں نفل روزے رکھنا یا نہ رکھنا مرضی پر موقوف ہے مگر دفوسروں کے لیے بوجھ نہ بنے۔ مشقت محسوس ہونے پر یا مہمان کی آمد پر یا انتہائی پسندیدہ کھانا میسر آنے پر نفل روزہ ختم کرنے میں کوئی حرج نہیں۔ بعد میں نفل روزے کی قضا ادا کی جا سکتی ہے، ضروری نہیں۔ نفل روزہ زوال سے پہلے دن کے وقت بھی رکھا جا سکتا ہے بشرطیکہ پہلے کچھ کھایا نہ ہو۔ معذور شخص رمضان المبارک کے دوران میں احتراماً سامنے کھانے پینے سے اجتناب کرے۔ واللہ اعلم"}],[2435,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے معاذ بن جبل رضی اللہ عنہ کو یمن بھیجتے وقت فرمایا: \"تم اہل کتاب (یہود و نصاری) کے پاس جا رہے ہو، تو جب تم ان کے پاس پہنچو تو انہیں اس بات کی دعوت دو کہ وہ اس بات کی گواہی دیں کہ اللہ کے سوا کوئی معبود برحق نہیں اور محمد صلی اللہ علیہ وسلم اللہ کے رسول ہیں، پھر اگر وہ تمہاری یہ بات مان لیں تو انہیں بتاؤ کہ اللہ تعالی نے ان پر دن و رات میں پانچ وقت کی نمازیں فرض کی ہیں، پھر اگر وہ تمہاری یہ بات مان لیں تو انہیں بتاؤ کہ اللہ عزوجل نے ان پر (زکاۃ) فرض کی ہے، جو ان کے مالداروں سے لی جائے گی اور ان کے محتاجوں میں بانٹ دیا جائے گا، اگر وہ تمہاری یہ بات بھی مان لیں تو پھر مظلوم کی بد دعا سے بچو\" ۱؎۔\n§وضاحت\n۱؎: اس طرح کہ زکاۃ کی وصولی میں ظلم و زیادتی نہ کرو، اور نہ ہی اس کی تقسیم میں، مثلاً کسی سے اس کا بہت اچھا مال لے لو یا کسی کو ضرورت سے زیادہ دے دو اور کسی کو کچھ نہ دو کہ وہ تم سے دکھی ہو کر تمہارے حق میں بد دعا کرے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے جب حضرت معاذ رضی اللہ عنہ کو یمن کی طرف (مبغل وحاکم بنا کر) بھیجا تو ان سے فرمایا: ’’تو وہاں اہل کتاب (یہودیوں) کے پاس جا رہا ہے۔ جب تو ان کے پاس پہنچے تو ان کو اس بات کی دعوت دینا کہ وہ گواہی دیں کہ اللہ تعالیٰ کے سوا کوئی لائق عبادت نہیں اور حضرت محمد صلی اللہ علیہ وسلم اللہ کے رسول وپیغمبر ہیں۔ اگر وہ تیری اس بات کو مان لیں تو انھیں بتانا کہ اللہ عزوجل نے ان پر ہر دن اور رات میں پانچ نمازیں فرض کی ہیں۔ اگر وہ تیری اس بات کو مان لیں تو ان کو بتانا کہ اللہ عزوجل نے ان پر زکاۃ فرض کی ہے جو ان کے مال دار لوگوں سے لے کر انھی کے محتاج لوگوں میں تقسیم کر دی جائے گی۔ اگر وہ تیری یہ بات تسلیم کر لیں تو (زکاۃ کی وصولی اور دیگر انتظامی معاملات میں) مظلوم کی بددعا سے بچنا۔‘‘","f2":"(۱) حضرت معاذ رضی اللہ عنہ کا یمن جانا ۹ یا ۱۰ ہجری کی بات ہے۔ حضرت عمر رضی اللہ عنہ کے دور تک وہ وہیں رہے۔ (۲) ’’اہل کتاب۔‘‘ یمن میں یہودیوں کی بڑی تعداد بستی تھی۔ (۳) ’’اگر وہ تیری اس بات کو مان لیں۔‘‘ شریعت کے تمام احکام اسلام لانے کے ساتھ ہی لاگو ہو جاتے ہیں مگر نماز دن رات میں پانچ مرتبہ فرض ہے جبکہ زکاۃ سالانہ فرض ہے، اس لیے یوں فرمایا۔ ورنہ یہ مطلب نہیں کہ اگر کوئی نماز نہ پڑھے تو اس پر زکاۃ فرض نہیں۔ (۴) ’’انھی کے محتاج‘‘ زکاۃ کے اولین حق دار اسی علاقے کے لوگ ہیں الا یہ کہ زکاۃ زائد ہو یا دوسرے لوگ ان سے زیادہ محتاج ہوں۔ (۵) کافر کو زکاۃ دینا جائز نہیں۔ (۶) بچے اور مجنون کے مال میں بھی زکاۃ واجب ہے کیونکہ حدیث عام ہے، تمام مسلمان اغنیاء کو شامل ہے۔ (۷) ’’مظلوم کی بددعا سے بچنا۔‘‘ یعنی کسی پر ظلم نہ کرنا کیونکہ مظلوم بددعا کرے گا اور اس کی بددعا ضرور قبول ہوتی ہے، چاہے وہ کود گناہ گار ہی ہو۔ گویا ظلم سب سے بڑا گناہ ہے جو دوسرے گناہوں کو مات کر دیتا ہے۔ (۸) اس روایت میں حج اور روزے کا ذکر نہیں۔ ممکن ہے کسی راوی نے مختصر کر دیا ہو یا انتہائی اہم ارکان بیان کر دیے گئے ہوں۔ نماز کے بغیر اسلام قبول نہیں۔ زکاۃ دینے سے اسلامی حکومت کی اطاعت ثابت ہوتی ہے۔ حج اور روزے کا یہ مقام نہیں کیونکہ وہ شخصی عبادات ہیں۔ قرآن مجید سے بھی تائید ہوتی ہے: ارشاد الٰہی ہے: {فَاِنْ تَابُوْا وَ اَقَامُوا الصَّلٰوۃَ وَ اٰتَوُا الزَّکٰوۃَ فَخَلُّوْا سَبِیْلَہُمْ} (التوبۃ۹: ۵) ’’پھر اگر کافر (اپنے دین سے) توبہ کر لیں، نماز قائم کریں اور زکاۃ دینے لگ جائیں تو ان کا راستہ چھوڑ دو (انھیں کچھ نہ کہو)۔‘‘"}],[2436,"بہز بن حکیم کے دادا معاویہ بن حیدہ رضی اللہ عنہ سے روایت ہے کہ میں نے عرض کیا: اللہ کے نبی! میں آپ کے پاس نہیں آیا یہاں تک کہ میں نے اپنے دونوں ہاتھوں کی انگلیوں کی تعداد سے زیادہ بار یہ قسم کھائی کہ نہ میں آپ کے قریب اور نہ آپ کے دین کے قریب آؤں گا۔ اور اب میں ایک ایسا آدمی ہوں کہ کوئی چیز سمجھتا ہی نہیں ہوں سوائے اس چیز کے جسے اللہ اور اس کے رسول نے مجھے سکھا دی ہے، اور میں اللہ کی وحی کی قسم دے کر آپ سے پوچھتا ہوں کہ اللہ تعالی نے کیا چیز دے کر آپ کو ہمارے پاس بھیجا ہے؟ آپ نے فرمایا: \"اسلام کے ساتھ\"، میں نے پوچھا: اسلام کی نشانیاں کیا ہیں؟ آپ نے فرمایا: \"یہ ہیں کہ تم کہو کہ میں نے اپنے آپ کو اللہ تعالی کے حوالے کر دیا، اور شرک اور اس کی تمام آلائشوں سے کٹ کر صرف اللہ کی عبادت کے لیے یکسو ہو گیا، اور نماز قائم کرو، اور زکاۃ دو\"۔","الألباني: حسن الإسناد",{"u2":"حضرت بہز بن حکیم کے دادا سے روایت ہے، انھوں نے کہا کہ میں نے (اسلام لاتے وقت) کہا: اے اللہ کے نبی! میں نے یہاں اپ کے پاس آنے سے پہلے اپنے ہاتھوں کی انگلیوں کی تعداد (یعنی دس) سے بھی زیادہ دفعہ قسم کھائی تھی کہ میں نہ آپ کے پاس آؤں گا اور نہ آپ کا دین قبول کروں گا۔ (لیکن اللہ تعالیٰ نے مجھے ہدایت دی ہے تو حاضر ہوگیا ہوں)۔ میں بے سمجھ آدمی ہوں۔ مجھے کچھ معلوم نہیں مگر جو اللہ عزوجل اور اس کا رسول مجھے سکھائیں گے۔ میں اللہ تعالیٰ کی وحی کے واسطے سے آپ سے سوال کرتا ہوں کہ اللہ تعالیٰ نے آپ کو کیا دے کر ہماری طرف بھیجا ہے؟ آپ نے فرمایا: ’’اسلام دے کر۔‘‘ میں نے عرض کیا: اسلام کی امتیازی باتیں کیا ہیں؟ آپ نے فرمایا: ’’یہ کہ تو کہے: میں نے اپنی ذات کو اللہ تعالیٰ کے احکامات کے لیے مطیع کر دیا ہے اور میں ہر قسم کے شرک سے لا تعلق ہوگیا ہوں۔ اور تو نماز (باجماعت) پڑھے اور زکاۃ کی ادائیگی کرے۔‘‘","f2":"(۱) راوی حدیث صحابی کا نام معاویہ بن حیدہ قشیری رضی اللہ عنہ ہے۔ (۲) ’’یہ کہ تو کہے۔‘‘ اس سے مراد کلمہ ٔ شہادتین ہے۔ یا توحید پر پختگی مراد ہے کیونکہ کلمۂ شہادتین تو وہ پہلے پڑھ چکا ہوگا۔ آپ کو اللہ کا نبی کہہ کر پکارنا اس بات کی دلیل ہے۔ (۳) اسلام مخالف تمام باتوں اور اشیاء سے براء ت اور بیزاری ہر مسلمان پر واجب ہے۔"}],[2437,"ابو مالک اشعری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کامل وضو کرنا آدھا ایمان ہے، الحمدللہ ترازو کو بھر دیتا ہے۔ اور سبحان اللہ اور اللہ اکبر آسمانوں اور زمین کو (ثواب) سے بھر دیتے ہیں۔ اور نماز نور ہے، اور زکاۃ دلیل ہے، اور صبر روشنی ہے، اور قرآن حجت (دلیل) ہے تیرے حق میں بھی، اور تیرے خلاف بھی\"۔","الألباني: صحيح",{"u2":"حضرت ابو مالک اشعری رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اچھی طرح وضو کرنا نصف ایمان ہے۔ الحمد للہ کہنا میزان (ترازو) کو بھر دیتا ہے۔ سبحان اللہ اور اللہ اکبر کہنا آسمان وزمین کو بھر دیتے ہیں۔ نماز نور ہے، زکاۃ (ایمان کی) دلیل ہے، صبر روشنی ہے اور قرآن مجید حجت ہے تیرے حق میں یا تیرے خلاف۔‘‘","f2":"(۱) ’’نصف ایمان۔‘‘ کیونکہ نماز ہی اصل دین ہے اور نماز وضو پر موقوف ہے جس نے وضو صحیح کر لیا، سمجھو نصف نماز پڑھ لی۔ یا نصف کی بجائے معنی کیے جائیں: وضو ایمان کا اہم جز ہے۔ (۲) ’’بھر دیتے ہیں۔‘‘ دونوں یا ان میں سے ہر ایک۔ بھرنے کا مطلب یہ ہے کہ ان کا ثواب پورا ہے، ناقص نہیں۔ (۳) ’’ترازو۔‘‘ ہر چیز کا حساب لگانے کے لیے کوئی نہ کوئی آلہ ہوتا ہے۔ اعمال کا حساب بتلانے کے لیے بھی کوئی آلہ ہونا چاہیے، وہی میزان ہے، اس میں کوئی عقلی اشکال نہیں۔ (۴) ’’نور ہے۔‘‘ یعنی نماز دل میں نور پیدا کرتی ہے اور بصیرت کو روشن کرتی ہے جس سے انسان زندگی کا صحیح راستہ جان سکتا ہے اور اس پر چل کر جنت تک پہنچ سکتا ہے یا قیامت کے کے دن نماز کے عوض نور نصیب ہوگا یا قبر میں نور ہوگا۔ (۵) ’’روشنی ہے۔‘‘ یعنی صبر کے ساتھ انسان مصائب سے بحفاظت گزر جاتا ہے۔ گمراہیوں میں بھٹک نہیں جاتا یا آخرت میں روشنی نصیب ہوگی۔ (۶) ’’تیرے حق میں یا تیرے خلاف۔‘‘ اگر قرآن مجید پر عمل کیا تو حق میں ورنہ خلاف کہ حق کا راستہ معلوم ہونے کے باوجود گمراہ رہا۔"}],[2438,"ابوہریرہ اور ابوسعید رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں ایک دن خطبہ دیا۔ آپ نے تین بار فرمایا: \"قسم ہے اس ذات کی جس کے ہاتھ میں میری جان ہے\"، پھر آپ نے سر جھکا لیا تو ہم سے ہر شخص سر جھکا کر رونے لگا، ہم نہیں جان سکے آپ نے کس بات پر قسم کھائی ہے، پھر آپ نے اپنا سر اٹھایا، آپ کے چہرے پر بشارت تھی جو ہمیں سرخ اونٹ پانے کی خوشی سے زیادہ محبوب تھی، پھر آپ نے فرمایا: \"جو بندہ بھی پانچوں وقت کی نماز پڑھے، روزے رمضان رکھے، اور زکاۃ ادا کرے، اور ساتوں کبائر ۱؎ سے بچے تو اس کے لیے جنت کے دروازے کھول دیے جائیں گے، اور اس سے کہا جائے گا: سلامتی کے ساتھ جنت میں داخل ہو جاؤ\"۔\n§وضاحت\n۱؎: ساتوں کبائر یہ ہیں: :(۱ ) شراب پینا :(۲ ) جادو کرنا :(۳ ) ناحق خون بہانا :(۴ ) سود کھانا :(۵ ) یتیم کا مال کھانا :(۶ ) جہاد سے بھاگنا :(۷ ) پاک دامن عورتوں پر تہمت لگانا۔","الألباني: ضعيف",{"u2":"حضرت ابوہریرہ اور حضرت ابو سعید رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے ایک دن ہمیں خطبہ ارشاد فرماتے ہوئے تین دفعہ فرمایا: ’’قسم اس ذات کی جس کے ہاتھ میں میری جان ہے!‘‘ پھر آپ نے سر جھکا لیا۔ ہم میں سے ہر شخص بھی سر جھکا کر رونے لگا۔ ہم نے جانتے تھے کہ آپ نے کس چیز پر قسم کھائی ہے؟ پھر آپ نے سر مبارک اٹھایا تو چہرے میں خوشی کے آثار تھے اور آپ کی خوشی ہمارے لیے سرخ اونٹوں سے بھی زیادہ محبوب تھی، پھر آپ نے فرمایا: ’’جو شخص پانچ فرض نمازیں پڑھے اور رمضان کے روزے رکھے، زکاۃ ادا کرے اور سات کبیرہ گناہوں سے پرہیز کرے، اس کے لیے جنت کے سب دروازے کھول دیے جائیں گے اور اسے کہا جائے گا: سلامتی کے ساتھ جنت میں داخل ہو جا۔‘‘","f2":"(۱) ’’رونے لگا۔‘‘ کیونکہ نبی صلی اللہ علیہ وسلم کا تین دفعہ قسم کھانا موقع کی اہمیت کو ظاہر کرتا تھا۔ اور نیک شخص کی روحانیت کو متاثر کرنے کے لیے اتنا ہی کافی تھا۔ (۲) ’’سرخ اونٹوں سے۔‘‘ اس ماحول میں عربوں کے نزدیک سرخ اونٹ سب سے زیادہ اہمیت اور قیمت رکھتے تھے، گویا مراد دنیا کی قیمت سے قیمتی چیز ہے، یعنی نبی صلی اللہ علیہ وسلم کی خوشی ہمارے لیے دنیا کی ہر چیز سے اہم تھی۔ (۳) ’’سات کبیرہ گناہ۔‘‘ سرک، جادو، ناحق قتل، سود خوری، یتیم کا مال کھا جانا، جہاد سے بھاگنا اور پاک دامن مومنہ عورتوں پر تہمت لگانا ہیں۔ (۴) ’’جنت کے سب دروازے۔‘‘ جنت کے کل دروازے آٹھ ہیں جبکہ جہنم کے سات دروازے ہیں۔ (۵) ’’سلامتی کے ساتھ جنت میں داخل ہو جا۔‘‘ کیونکہ کبیرہ گناہوں کے اجتناب سے صغیرہ گناہ معاف ہو جاتے ہیں اور یہ اللہ تعالیٰ کی رحمت ہے۔ ہاں، اگر کبائر سے اجتناب نہ کیا جائے تو صغائر بھی معاف نہیں ہوتے۔"}],[2439,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا کہ جو شخص اللہ کی راہ میں چیزوں میں سے کسی چیز کے جوڑے دے تو وہ جنت کے دروازے سے یہ کہتے ہوئے بلایا جائے گا کہ اللہ کے بندے! آ جا یہ دروازہ تیرے لیے بہتر ہے، تو جو شخص اہل صلاۃ میں سے ہو گا وہ صلاۃ کے دروازے سے بلایا جائے گا۔ اور جو شخص مجاہدین میں سے ہو گا وہ جہاد کے دروازے سے بلایا جائے گا، اور جو اہل صدقہ (و زکاۃ) میں سے ہوں گے تو وہ صدقہ (زکاۃ) کے دروازے سے بلایا جائے گا، اور جو روزے رکھنے والوں میں سے ہو گا وہ باب الریان (ریان کے دروازہ) سے بلایا جائے گا۔ ابوبکر رضی اللہ عنہ نے عرض کیا: جو کوئی ان دروازوں میں سے کسی ایک دروازے سے بلا لیا جائے اسے مزید کسی اور دروازے سے بلائے جانے کی ضرورت نہیں، لیکن اللہ کے رسول! کیا کوئی ایسا بھی ہے جو ان تمام دروازوں سے بلایا جائے گا؟ آپ نے فرمایا: \"ہاں، اور مجھے امید ہے کہ تم انہیں میں سے ہو گے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’جو شخص کسی چیز کا جوڑا اللہ تعالیٰ کے راستے میں خرچ کرے، اسے جنت کے دروازوں سے پکارا جائے گا، اے اللہ کے بندے! یہ (دروازہ) تیرے لیے بہتر ہے۔ اور جنت کے بہت سے دروازے ہیں۔ جو شخص نماز کا عادی ہوگا، اسے نماز والے دروازے سے بلایا جائے گا اور جو جہاد کا شائق تھا، اسے جہاد والے دروازے سے آواز دی جائے گی اور جو صدقے سے خصوصی رغبت رکھنے والا ہوگا، اسے صدقے والے دروازے سے دعوت دی جائے گی اور جو رو زے کا ریسا ہوگا، اسے باب الریان سے داخل ہونے کو کہا جائے گا۔‘‘ حضرت ابوبکر رضی اللہ عنہ نے عرض کیا: کسی شخص کوئی ضرورت تو نہیں کہ اسے ان سب دروازوں سے بلایا جائے مگر کیا کوئی ایسا شخص بھی ہوگا جسے ان سب دروازوں سے آوازیں دی جائیں گی؟ آپ نے فرمایا: ’’ہاں، اور مجھے امید ہے، اے ابوبکر! تم انھی میں سے ہوگے۔‘‘","f2":"’’کسی بھی چیز کا جوڑا۔‘‘ یعنی ایک جیسی دو چیزیں، مثلاً: دو اونٹ، دو غلم، دو روٹیاں اور دو کپڑے وغیرہ۔ یا دو متقابل چیزیں، مثلاً: روٹی کے ساتھ سالن بھی، وغیرہ۔ گویا مکمل صدقہ کرے، ناقص نہ ہو کیونکہ بالعموم جوڑے سے ہی مکمل چیز بنتی ہے۔ (مزید تفصیل کے لیے دیکھیے، فوائد حدیث: ۲۲۴۰"}],[2440,"ابوذر رضی اللہ عنہ کہتے ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، آپ خانہ کعبہ کے سایہ میں بیٹھے ہوئے تھے، جب آپ نے ہمیں آتے دیکھا تو فرمایا: \"وہ بہت خسارے والے لوگ ہیں، رب کعبہ کی قسم\"! میں نے (اپنے جی میں) کہا: کیا بات ہے؟ شاید میرے بارے میں کوئی آیت نازل ہوئی ہے، میں نے عرض کیا: کون لوگ ہیں میرے ماں باپ آپ پر قربان ہوں؟ آپ نے فرمایا: \"بہت مال والے، مگر جو اس طرح کرے، اس طرح کرے\" یہاں تک کہ آپ اپنے سامنے، اپنے دائیں، اور اپنے بائیں دونوں ہاتھ سے اشارہ کیا، پھر آپ نے فرمایا: \"قسم ہے اس ذات کی جس کے ہاتھ میں میری جان ہے جو شخص کوئی اونٹ یا بیل چھوڑ کر مرے گا جس کی اس نے زکاۃ نہ دی ہو گی تو وہ (اونٹ یا بیل) (دنیا میں) جیسا کچھ وہ تھا قیامت کے دن اس سے بڑا اور موٹا تازہ ہو کر اس کے سامنے آئے گا، اور اسے اپنے کھروں سے روندے گا اور سینگوں سے مارے گا، جب آخری جانور روند اور مار چکے گا تو پھر ان کا پہلا لوٹا دیا جائے گا، اور یہ سلسلہ جاری رہے گا یہاں تک کہ لوگوں کے درمیان فیصلہ کر دیا جائے\"۔","الألباني: صحيح",{"u2":"حضرت ابو ذر رضی اللہ عنہ سے روایت ہے کہ میں نبی صلی اللہ علیہ وسلم کے پاس آیا۔ آپ کعبے کے سائے میں بیٹھے تھے۔ جب آپ نے مجھے آتے دیکھا تو فرمانے لگے: ’’کعبے کے رب کی قسم! وہ بہت خسارے والے لوگ ہیں۔‘‘ میں نے اپنے دل میں کہا: کیا وجہ ہے؟ شاید میرے بارے میں کوئی وحی اتری ہے۔ میں نے عرض کیا: آپ پر میرے ماں باپ قربان! وہ کون (بدنصیب ہیں؟ آپ نے فرمایا: ’’زیادہ مالدار لوگ، مگر جس نے ایسے ایسے اور ایسے کیا۔‘‘ یعنی آگے، اپنے دائیں اور بائیں خرچ کیا، پھر فرمایا: ’’قسم اس ذات کی جس کے ہاتھوں میں میری جان ہے! جو آدمی بھی مرتے وقت اونٹ اور گائیں چھوڑ جائے، جن کی زکاۃ وہ نہ دیتا ہو، اس کے جانور اس جسامت اور موٹاپے سے بڑھ کر آئیں گے جو (دنیا میں تھی اور اسے اپنے پاؤں تلے روندیں گے اور اس کو اپنے سینگوں سے ٹکریں ماریں گے۔ جب ان میں سے آخری جانور گزر جائے گا تو پہلے کو دوبارہ اس کے اوپر سے گزارا جائے گا۔ (اس کے ساتھ یہ سلسلہ جاری رہے گا حتیٰ کہ لوگوں کے درمیان فیصلے کر دیے جائیں۔‘‘","f2":"(۱ ’’آگے، دائیں اور بائیں۔‘‘ یعنی ہر ضروری مصرف میں خرچ کیا، خواہ وہ فرض زکاۃ کے علاوہ بھی ہو۔ (۲ قیامت کے دن صرف انسان ہی نہیں بلکہ ہر ذی روح چیز اٹھے گی۔"}],[2441,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس شخص کے پاس مال ہو اور وہ اپنے مال کا حق ادا نہ کرے (یعنی زکاۃ نہ دے)تو وہ مال ایک گنجے زہریلے سانپ کی شکل میں اس کی گردن کا ہار بنا دیا جائے گا، وہ اس سے بھاگے گا، اور وہ (سانپ) اس کے ساتھ ہو گا\"، پھر اس کی تصدیق کے لیے آپ نے قرآن مجید کی یہ آیت پڑھی «ولا تحسبن الذين يبخلون بما آتاهم اللہ من فضله هو خيرا لهم بل هو شر لهم سيطوقون ما بخلوا به يوم القيامة» \"تم یہ مت سمجھو کہ جو لوگ اس مال میں جو اللہ نے انہیں دیا ہے بخیلی کرتے ہیں ان کے حق میں بہتر ہے، یہ بہت برا ہے ان کے لیے۔ عنقریب جس مال کے ساتھ انہوں نے بخل کیا ہو گا وہ قیامت کے دن ان کے گلے کا ہار بنا دیا جائے گا\" (آل عمران: ۱۸)۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص اپنے مال کا حق (زکاۃ ادا نہ کرتا ہو تو (قیامت کے دن وہ مال اس کے گلے میں گنجے سانپ کی صورت میں طوق بنا دیا جائے گا۔ وہ اس سے بھاگے گا، مگر وہ اس کے پیچھے دوڑے گا، پھر آپ نے اللہ تعالیٰ کی کتاب میں سے اس کی تصدیق کے لیے یہ آیت پڑھی: {وَلَا یَحْسَبَنَّ الَّذِیْنَ یَبْخَلُوْنَ… الخ} ’’جو لوگ اللہ تعالیٰ کے دیے ہوئے مال میں بخل کرتے ہیں، وہ یہ نہ سمجھیں کہ وہ مال ان کے لیے بہتر ہے، بلکہ وہ ان کے لیے بدتر ہے۔ اور جس مال کے ساتھ انھوں نے بخل کیا، قیامت کے دن وہ ان کے گلے کا طوق بنایا جائے گا۔‘‘","f2":"’’گنجا سانپ۔‘‘ سانپ کے جسم پر توبال ہوتے ہی نہیں، لہٰذا گنجے سے مراد یہ ہے کہ کثرت زہر یا درازی عمر کی وجہ سے اس کے سر پر سے چمڑا تک اڑ چکا ہوگا۔ (النھایۃ لابن الاثیر"}],[2442,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا کہ جس شخص کے پاس اونٹ ہوں اور وہ ان کی تنگی اور خوشحالی میں ان کا حق ادا نہ کرے (لوگوں نے) عرض کیا: اللہ کے رسول! «نجدتها ورسلها» سے کیا مراد ہے؟ آپ نے فرمایا: تنگی اور آسانی ۱؎ تو وہ اونٹ جیسے کچھ تھے قیامت کے دن اس سے زیادہ چست، فربہ اور موٹے تازے ہو کر آئیں گے۔ اور یہ ایک کشادہ اور ہموار چٹیل میدان میں اوندھا لٹا دیا جائے گا، وہ اسے اپنے کھروں سے روندیں گے، جب آخری اونٹ روند چکے گا تو پھر پہلا اونٹ روندنے کے لیے لوٹایا جائے گا، ایک ایسے دن میں جس کی مقدار پچاس ہزار سال کے برابر ہو گی، اور یہ سلسلہ برابر اس وقت تک چلتا رہے گا جب تک لوگوں کے درمیان فیصلہ نہ کر دیا جائے گا، اور وہ اپنا راستہ دیکھ نہ لے گا، جن کے پاس گائے بیل ہوں اور وہ ان کا حق ادا نہ کرے یعنی ان کی زکاۃ نہ دے، ان کی تنگی اور ان کی کشادگی کے زمانہ میں، تو وہ گائے بیل قیامت کے دن پہلے سے زیادہ مستی و نشاط میں موٹے تازے اور تیز رفتار ہو کر آئیں گے، اور اسے ایک کشادہ میدان میں اوندھا لٹا دیا جائے گا اور ہر سینگ والا اسے سینگوں سے مارے گا، اور ہر کھر والا اپنی کھروں سے اسے روندے گا، جب آخری جانور روند چکے گا، تو پھر پہلا پھر لوٹا دیا جائے گا، ایک ایسے دن میں جس کی مقدار پچاس ہزار سال کی ہو گی، یہاں تک کہ لوگوں کے درمیان فیصلہ کر دیا جائے اور وہ اپنا راستہ دیکھ لے، اور جس شخص کے پاس بکریاں ہوں اور وہ ان کی تنگی اور آسانی میں ان کا حق ادا نہ کرے تو قیامت کے دن وہ بکریاں اس سے زیادہ چست فربہ اور موٹی تازی ہو کر آئیں گی جتنی وہ (دنیا میں) تھیں، پھر وہ ایک کشادہ ہموار میدان میں منہ کے بل لٹا دیا جائے، تو ہر کھر والی اسے اپنے کھر سے روندیں گی، اور ہر سینگ والی اسے اپنی سینگ سے مارے گی، ان میں کوئی مڑی ہوئی اور ٹوٹی ہوئی سینگ کی نہ ہو گی، جب آخری بکری مار چکے گی تو پھر پہلی بکری لوٹا دی جائے گی، ایک ایسے دن میں جس کی مقدار پچاس ہزار سال کے برابر ہو گی، یہاں تک کہ لوگوں کے درمیان فیصلہ کر دیا جائے، اور وہ اپنا راستہ دیکھ لے۔\n§وضاحت\n۱؎: مطلب یہ ہے کہ نہ تنگی و پریشانی کے زمانے میں زکاۃ دے کہ دینے سے اونٹ کم ہو جائیں گے، اور محتاجی و تنگی مزید بڑھ جائے گی، اور نہ خوش حالی و فارغ البالی کے دنوں میں زکاۃ دے یہ سوچ کر کہ ایسے موٹے تازے جانور کی زکاۃ کون دے ؟","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے سنا: ’’جس آدمی کے پاس اونٹ ہوں اور وہ ان کی نجدہ اور ان کی رسل میں ان کا حق (یعنی زکاۃ ادا نہ کرتا ہو۔‘‘ صحابہ نے کہا: ’’اے اللہ کے رسول! نجدہ اور رسل سے کیا مراد ہے؟ آپ نے فرمایا: ’’تنگی اور خوش حالی میں (ان کی زکاۃ ادا نہ کرتا ہو تو (قیامت کے دن وہ انتہائی موٹے، تازے اور پوری مستی کی حالت میں آئیں گے اور اس (مالک کو ان کے سامنے ایک کھلے ہموار میدان میں اوندھا لٹا دیا جائے گا تو وہ اپنے کھروں سے (پاؤں تلے اسے مسلیں (روندیں گے۔ جب آخری گزر جائے گا تو پہلے کو پھر لایا جائے گا اور یہ کام اس کے ساتھ قیامت کے پورے دن میں کیا جاتا رہے گا۔ جس کی مقدار پچاس ہزار سال ہے، حتیٰ کہ لوگوں کے درمیان (جنت اور جہنم کا فیصلہ کر دیا جائے۔ اور وہ اپنا (جنت یا جہنم والا راستہ دیکھ لے۔ اور (اسی طرح جس شخص کے پاس گائیں ہوں اور وہ تنگ حالی اور خوش حالی میں ان کی زکاۃ نہ دیتا ہو تو وہ بھی قیامت کے دن انتہائی موٹی تازی اور پوری مستی کی حالت میں آئیں گی اور اس (مالک کو ان کے سامنے ایک کھلے ہموار میدان میں اوندھا لٹا دیا جائے گا اور ہر سینگ والی اپنے سینگوں سے اس کو ٹکریں مارے گی اور ہر کھر والی اپنے کھروں کے ساتھ اس کو کچلے گی۔ جب ان میں سے آخری گزر جائے گی تو پہلی کو پھر لایا جائے گا۔ اور یہ کام اس کے ساتھ قیامت کے پورے دن میں کیا جاتا رہے گا جس کی مقدار پچاس ہزار سال ہے، حتیٰ کہ لوگوں کے درمیان فیصلہ کیا جائے اور وہ اپنا (جنتی یا جہنمی راستہ دیکھ لے گا۔ اسی طرح جس آدمی کے پاس بکریاں ہوں اور وہ تنگ حالی اور خوش حالی میں ان کی زکاۃ نہ دیتا ہو تو وہ قیامت کے دن انتہائی موٹی تازی اور پوری مستی کی حالت میں آئیں گی، پھر اس (مالک کو ان کے سامنے ایک کھلے اور ہموار میدان میں اوندھا لٹا دی جائے گا۔ تو ہر کھر والی اپنے کھروں کے ساتھ اس کو مسلے گی اور ہر سینگ والی اپنے سینگوں کے ساتھ اس کو ٹکریں مارے گی۔ ان میں سے کسی کا سینگ نہ مڑا ہوا ہوگا اور نہ ٹوٹا ہوا۔ جب ان میں سے آخری گزر جائے گی تو پہلی کو واپس لایا جائے گا۔ اور اس (مالک کے ساتھ یہ کام قیامت کے پورے دن ہوتا رہے گا جس کی مقدار پچاس ہزار سال ہوگی، حتیٰ کہ لوگوں کے درمیان (جنت اور جہنم کا فیصلہ کر دیا جائے اور وہ اپنا (جنت یا جہنم والا راستہ دیکھ لے۔‘‘","f2":"(۱ ’’ایسے دن میں۔‘‘ ہمارے لحاظ سے تو دن کی مدت کا تعین سورج کے طلوع اور غروب سے ہوتا ہے مگر ظاہر ہے کہ روز محشر کا تعین سورج سے نہیں ہوگا۔ اللہ تعالیٰ جس طریقے سے چاہے گا دن کا تعین ہوگا۔ ممکن ہے مطلق مدت کو دن کہہ دیا گیا ہو۔ (۲ ’’پہلی کو واپس لایا جائے گا۔‘‘ گویا جانور اس پر سے دائرے میں گزریں گے۔ اعاذنا اللہ من ذلک"}],[2443,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم کی وفات ہو گئی اور آپ کے بعد ابوبکر رضی اللہ عنہ خلیفہ بنائے گئے، اور عربوں میں سے جنہیں کافر مرتد ہونا تھا کافر ہو گئے تو عمر رضی اللہ عنہ نے ابوبکر رضی اللہ عنہ سے کہا: آپ لوگوں سے کیسے لڑیں گے؟ جب کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: \"مجھے حکم دیا گیا ہے کہ میں لوگوں سے لڑوں یہاں تک کہ یہ لا الٰہ الا اللہ کا اقرار کر لیں، تو جس نے لا الٰہ الا اللہ کا اقرار کر لیا، اس نے مجھ سے اپنے مال اور اپنی جان کو سوائے اسلام کے حق ۱؎ کے مجھے سے محفوظ کر لیا۔ اور اس کا حساب اللہ کے سپرد ہے\" ۲؎ اس پر ابوبکر رضی اللہ عنہ نے کہا: میں اس شخص سے ضرور لڑوں گا جو نماز اور زکاۃ میں فرق کرے گا (یعنی نماز تو پڑھے اور زکاۃ دینے سے منع کرے) کیونکہ زکاۃ مال کا حق ہے، قسم اللہ کی، اگر یہ اونٹ باندھنے کی رسی بھی جو وہ رسول اللہ صلی اللہ علیہ وسلم کو ادا کیا کرتے تھے مجھ سے روکیں گے، تو میں ان سے ان کے روکنے پر لڑوں گا، عمر رضی اللہ عنہ نے فرمایا: اللہ کی قسم! زیادہ دیر نہیں ہوئی مگر مجھے یقین ہو گیا کہ اللہ تعالی نے ابوبکر رضی اللہ عنہ کو قتال کے سلسلے میں شرح صدر عطا کر دیا ہے، اور میں نے جان لیا کہ یہ (یعنی ابوبکر رضی اللہ عنہ کی رائے) حق ہے۔\n§وضاحت\n۱؎: \"سوائے اسلام کے حق کے\" کا مطلب یہ ہے کہ اگر قبول اسلام کے بعد کسی نے ایسا جرم کیا جو قابل حد ہے تو وہ حد اس پر ضرور نافذ ہو گی، مثلاً چوری کی تو اس کا ہاتھ کاٹا جائے گا، زنا کیا تو غیر شادی شدہ کو سو کوڑوں کی سزا یا رجم کی سزا، کسی کو ناحق قتل کیا تو قصاص میں قتل کی، سزا دی جائے گی۔ ۲؎: \" اور ان کا حساب اللہ کے سپرد ہے \" کا مطلب ہے اگر وہ قبول اسلام میں مخلص نہیں ہوں گے بلکہ منافقانہ طور پر اسلام کا اظہار کریں گے، یا قابل جرم کام کا ارتکاب کریں گے لیکن اسلامی عدالت اور افسران مجاز کے علم میں نہیں آ سکا، تو ان کا حساب اللہ کے سپرد ہو گا یعنی آخرت میں اللہ تعالی ان کا فیصلہ فرمائے گا۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم فوت ہوگئے اور آپ کے بعد حضرت ابوبکر رضی اللہ عنہ خلیفہ بنائے گئے اور بہت سے عرب لوگوں نے کفر کا ارتکاب کیا (اور حضرت ابوبکر رضی اللہ عنہ نے ان سے لڑنے کا اعلان فرمایا تو حضرت عمر رضی اللہ عنہ نے حضرت ابوبکر رضی اللہ عنہ سے کہا: آپ ان لوگوں سے کیسے لڑیں گے (جو زکاۃ نہیں دیتے جبکہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: ’’مجھے لوگوں کے ساتھ لڑنے کا حکم دیا گیا ہے حتیٰ کہ وہ لا الٰہ الا اللہ (کلمہ طیبہ پڑھ لیں۔ جس شخص نے لا الہ الا اللہ پڑھ لیا، اس نے مجھ سے اپنی جان ومال بچا لیا الا یہ کہ اس پر کوئی حق بنتا ہو۔ اور اس کا (اندرونی حساب اللہ تعالیٰ کے ذمے ہے۔‘‘ حضرت ابوبکر رضی اللہ عنہ نے فرمایا: ’’اللہ کی قسم! میں ان لوگوں سے ضرور لڑوں گا جو نماز اور زکاۃ میں فرق کریں گے کیونکہ زکاۃ مال کا حق ہے۔ اللہ کی قسم! اگر وہ مجھے (بالفرض اونٹ کو باندھنے والی رسی نہ دیں جو رسول اللہ صلی اللہ علیہ وسلم کو دیا کرتے تھے تو میں اس کے نہ دینے پر بھی ان سے لڑوں گا۔ حضرت عمر رضی اللہ عنہ نے (بعد میں فرمایا: اللہ کی قسم! میری سمجھ میں بھی یہ بات آگئی کہ لڑائی کے لیے حضرت ابوبکر رضی اللہ عنہ کا سینہ اللہ تعالیٰ نے کھول دیا ہے تو مجھے یقین ہوگیا کہ یہی حق ہے۔","f2":"(۱) ’’کفر کا ارتکاب کیا۔‘‘ رسول اللہ صلی اللہ علیہ وسلم کی وفات کے بعد کئی قسم کے فتنے اٹھے۔ کچھ لوگ اپنے آبائی دین کی طرف لوٹ گئے، کچھ لوگ نبوت کے جھوٹے دعوے داروں کے پیچھے لگ گئے، کچھ لوگ زکاۃ کی فرضیت کے منکر ہوگئے اور کچھ لوگ حکومت کو زکاۃ دینے سے رک گئے۔ پہلے تین گروہ تو قطعاً کافر تھے۔ ان سے لڑنے میں کوئی اختلاف نہ تھا۔ حضرت عمر رضی اللہ عنہ کو اختلاف اس آخری گروہ کے بارے میں تھا کیونکہ وہ کافر نہ تھے۔ حکومت کے باغی تھے۔ حضرت ابوبکر رضی اللہ عنہ ان سے لڑنے کے حق میں تھے جبکہ حضرت عمر رضی اللہ عنہ کو تردد تھا۔ (۲ ’’لا الٰہ الا اللہ پڑھ لیں۔‘‘ مراد پورا کلمہ شہادت ہے۔ اور یہ متفقہ بات ہے، ورنہ یہودی اور عیسائی کو بھی مسلمان کہنا پڑے گا۔ (۳ ’’الا یہ کہ اس پر کوئی حق بنتا ہو۔‘‘ یعنی اس نے کسی کے جان ومال کا نقصان کیا ہو تو اس کی سزا اسے بھگتنی ہوگی۔ (۴ ’’اندرونی حساب۔‘‘ کہ اس نے کلمہ خلوص قلب سے پڑھا ہے یا جان ومال بچانے کے لیے۔ (۵ ’’زکاۃ مال کا حق ہے۔‘‘ وہ نہ دیں تو ان سے زبردستی وصول کیا جائے گا، ورنہ حکومت کا نظام تلپٹ ہو جائے گا اور بغاوت راہ پکڑے گی۔ (۶ ’’وہ رسی نہ دیں۔‘‘ زور کلام کے لیے مبالغے سے کام لیا گیا ہے اور کلام میں ایسا عموماً ہوتا ہے۔ ورنہ زکاۃ میں رسی دینا لازم نہیں، صرف جانور دینا لازم ہے۔ (۷ منکرین زکاۃ سے بھی کافروں کی طرح قتال کرنے پر صحابہ کا اجماع ہے۔ (۸ یہ حضرت ابوبکر رضی اللہ عنہ کے علم وفضل اور شجاعت کی بہت بڑی دلیل ہے۔ آپ نے اس نازک ترین موقع پر کمال ثابت قدمی کا مظاہرہ کرتے ہوئے ایک بہت بڑے فتنے کو آغاز ہی میں اس کے عبرت ناک انجام تک پہنچا دیا۔ اس وقت ابتداء ً عمر رضی اللہ عنہ بھی آپ سے اتفگاق رائے نہ رکھتے تھے کیونکہ اپنے علمی رسوخ کی بنا پر جہاں حضرت ابوبکر رضی اللہ عنہ پہنچے ہوئے تھے وہاں ابھی عمر رضی اللہ عنہ نہ پہنچے تھے۔ یہ بات ابوبکر رضی اللہ عنہ کے علمی تفوق کی دلیل ہے۔ اس اور اس جیسے دیگر واقعات کی بنا پر اہل حق کا اجماع ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے علمی تفوق کی دلیل ہے۔ اس اور اس جیسے دیگر واقعات کی بنا پر اہل حق کا اجماع ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے بعد امت کے افضل ترین آدمی حضرت ابوبکر رضی اللہ عنہ ہیں۔ (۹ صحابہ کرام رضی اللہ عنہم قیاس جلی کے قائل تھے۔ (۱۰ بات کو موکد کرنے کے لیے قسم اٹھانا جائز ہے اگرچہ اس کا مطالبہ نہ کیا گیا ہو۔"}],[2444,"بہز بن حکیم کے دادا معاویہ بن حیدہ رضی اللہ عنہ کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم کو فرماتے سنا: \"چرائے جانے والے ہر چالیس اونٹ میں ایک بنت لبون ۱؎ ہے، اونٹوں کو (زکاۃ سے بچنے کے لیے) ان کے حساب (ریوڑ) سے جدا نہ کیا جائے۔ جو شخص ثواب کی نیت سے زکاۃ دے گا تو اسے اس کا ثواب ملے گا، اور جو شخص زکاۃ دینے سے انکار کرے گا تو ہم زکاۃ بھی لیں گے اور بطور سزا اس کے آدھے اونٹ بھی لے لیں گے، یہ ہمارے رب کی سزاؤں میں سے ایک سزا ہے۔ اس میں سے محمد صلی اللہ علیہ وسلم کے خاندان کے لیے کوئی چیز جائز نہیں ہے\"۔\n§وضاحت\n۱؎: اونٹ کا وہ بچہ جو اپنی عمر کے دو سال پورے کر چکا ہو، اور تیسرے سال میں داخل ہو چکا ہو۔","الألباني: حسن",{"u2":"حضرت بہز بن حکیم کے دادا (حضرت معاویہ بن حیدہ قشیرہ رضی اللہ عنہ سے روایت ہے، انھوں نے کہا، میں نے نبی صلی اللہ علیہ وسلم کو فرماتے سنا: ’’صحرا میں چرنے والے اونٹوں میں سے ہر چالیس اونٹوں میں ایک بنت لبون (دو سالہ اونٹنی ہے۔ (دوران وصولی اونٹوں کے حساب ومقدار سے انھیں الگ نہ کیا جائے گا۔ جو شخص (خوشی سے ثواب کی خاطر زکاۃ دے گا، اس کو اس کا ثواب ملے گا اور جو دینے سے انکار کرے گا ہم زکاۃ بھی لیں گے اور (اس کے ساتھ ساتھ اس کے نصف اونٹ بھی لیں گے۔ (کیونکہ یہ زکاۃ ہمارے رب کے فرائض میں سے ایک اہم فریضہ ہے۔ حضرت محمد صلی اللہ علیہ وسلم کے خاندان کے لیے کچھ بھی زکاۃ لینا (اپنی ذات کے لیے جائز نہیں۔","f2":"(۱ ’’چرنے والے۔‘‘ ان جانوروں میں زکاۃ فرض ہے جو سارا سال یا سال کا اکثر حصہ جنگل وغیرہ میں چر کر گزارتے ہوں، ان کو خود چارا نہ ڈالنا پڑے الا شاذ ونادر۔ (۲ ’’ہر چالیس اونٹوں میں۔‘‘ یعنی ۱۲۰ اونٹوں کے بعد کیونکہ ۱۲۰ تک تو اونٹوں کی مخصوص زکاۃ ہے جس کا بیان آگے آرہا ہے۔ (۳ ’’بنت لبون‘‘ اس سے مراد وہ اونٹنی ہے جس کی عمر دو سال ہو چکی ہو اور وہ تیسرے میں شروع ہو۔ (۴ ’’انھیں الگ نہ کیا جائے گا۔‘‘ یعنی دو شریک زکاۃ کے ڈر سے اپنے اپنے اونٹ الگ نہیں کریں گے، مثلاً: ایک کے تین اور دوسرے کے دو اونٹ ہوں تو اس طرح ایک بکری زکاۃ واجب ہوتی ہے۔ جدا جدا کر لیے جائیں تو کچھ بھی واجب نہیں ہوتا۔ یا کچھ اونٹ کمزور یا عمر کے لحاظ سے چھوٹے ہوں تو وہ گنتی میں پورے ہی شمار ہوں گے، البتہ زکاۃ میں معین عمر والا اور درمیانہ (موٹاپے کے لحاظ سے جانور لیا جائے گا۔ (۵ ’’نصف اونٹ بھی لیں گے۔‘‘ یہ اقدام بطور سزا ہے۔ اسلامی حکومت کا اہل کار زبردستی کارندوں کے ذریعے سے زکاۃ کے ساتھ ساتھ جبراً، جس مال میں زکاۃ واجب ہوئی ہو، وہ آدھا مال بھی لے سکتا ہے اور وہ بیت المال میں جمع ہوگا۔ حدیث کی روشنی میں یہی موقف راجح ہے۔ لیکن جمہور علمائے کرام مالی سزا کو غیر مشروع قرار دیتے ہیں، ان کے بقول صرف زکاۃ ہی وصول کی جائے گی، مذکورہ حدیث کو انھوں نے وقتی سزا قرار دیا ہے یا وہ اس حکم کے نسخ کے قائل ہیں لیکن یہ دونوں باتیں ہی محل نظر ہیں جبکہ مذکورہ حدیث مذکورہ سزا کی بین دلیل ہے۔ (۶ ’’جائز نہیں۔‘‘ تاکہ کسی کے ذہن میں یہ خیال تک نہ آئے کہ نبوت کا دعویٰ مال اکٹھا کرنے کے لیے کیا گیا ہے۔"}],[2445,"ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"پانچ وسق سے کم غلے میں زکاۃ نہیں ہے، اور پانچ اونٹ سے کم میں زکاۃ نہیں ہے اور پانچ اوقیہ سے کم چاندی میں زکاۃ نہیں ہے۔\n§وضاحت\n۱؎: ایک وسق ساٹھ صاع کا ہوتا ہے اور پانچ وسق تقریباً ساڑھے سات کوئنٹل بنتا ہے۔ ۲؎: ایک اوقیہ چالیس درہم کا ہوتا ہے، اس طرح پانچ اوقیہ دو سو درہم کا ہوا، اور دو سو درہم موجودہ وزن کے اعتبار سے ۸۵ گرام بنتا ہے۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’پانچ وسق سے کم غلے میں زکاۃ نہیں، نہ پانچ سے کم اونٹوں میں زکاۃ ہے اور نہ پانچ اوقیے سے کم رقم میں زکاۃ ہے۔‘‘"}],[2446,"ابوسعید خدری رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"پانچ اونٹ سے کم میں زکاۃ نہیں ہے، اور پانچ اوقیہ سے کم چاندی میں زکاۃ نہیں ہے، اور پانچ وسق سے کم غلے میں زکاۃ نہیں ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’پانچ اونٹوں سے کم میں زکاۃ نہیں اور پانچ اوقیے سے کم (چاندی یا رقم میں زکاۃ نہیں اور پانچ وسق سے کم غلے میں زکاۃ نہیں۔‘‘","f2":"(۱ ’’پانچ وسق‘‘ وسق ساٹھ صاع کا ہوتا ہے۔ صاع ایک پیمانہ ہے، وزن نہیں۔ اس میں غلے کی ہر قسم کا وزن مختلف ہوگا مگر اوسط وزن ۲ سیر ۴ چھٹانک اور موجودہ وزن کے مطابق ۰۹۹۔۲ کلو گرام ہوتا ہے۔ گویا وسق ۳ من ۱۵ سیر اور موجودہ وزن کے مطابق ۹۷۱۔۱۲۵ کلو گرام اور پانچ وسق ۸۵۵۔۶۲۹ کلو گرام (تقریباً ۱۶ من کے ہوتے ہیں۔ اگر زمین کی غلے کی پیداوار اس سے کم ہو تو اس میں زکاۃ (عشر وغیرہ نہ ہو گی۔ (۲ ’’پانچ اوقیہ‘‘ ایک اوقیہ چالیس درہم کا ہوتا ہے۔ پانچ اوقیے ۲۰۰ درہم ہوں گے۔ درہم سکہ بھی تھا اور وزن بھی۔ آج کل اکثر علماء کے نزدیک اس وزن کی چاندی کی قیمت نصاب ہے۔ اس سے کم میں زکاۃ نہیں۔ ۲۰۰ درہم کا وزن تقریباً ساڑھے باون تولے ہے۔ اور موجودہ وزن کے مطابق ۳۶۰۔۶۱۲ گرام ہوتا ہے۔ مروجہ کرنسی کی زکاۃ اسی حساب سے ہوگی۔"}],[2447,"انس بن مالک رضی اللہ عنہ سے روایت ہے کہ ابوبکر رضی اللہ عنہ نے انہیں (عاملین صدقہ کو) یہ لکھا کہ یہ صدقہ کے وہ فرائض ہیں جنہیں رسول اللہ صلی اللہ علیہ وسلم نے مسلمانوں پر فرض ٹھہرائے ہیں، جن کا اللہ عزوجل نے اپنے رسول صلی اللہ علیہ وسلم کو حکم دیا ہے، تو جس مسلمان سے اس کے مطابق زکاۃ طلب کی جائے تو وہ دے، اور جس سے اس سے زیادہ مانگا جائے تو وہ نہ دے: پچیس اونٹوں سے کم میں ہر پانچ اونٹ میں ایک بکری ہے، اور جب پچیس اونٹ ہو جائیں تو اس میں پینتیس اونٹوں تک ایک برس کی اونٹنی ہے، اگر ایک برس کی اونٹنی نہ ہو تو دو برس کا اونٹ (نر) ہے، اور جب چھتیس اونٹ ہو جائیں تو چھتیس سے پینتالیس تک دو برس کی اونٹنی ہے، اور جب چھیالیس اونٹ ہو جائیں تو چھیالیس سے ساٹھ اونٹ تک میں تین برس کی اونٹنی (یعنی جو ان اونٹنی جو نر کودانے کے لائق ہو گئی ہو) ہے، اور جب اکسٹھ اونٹ ہو جائیں تو اکسٹھ سے پچہتر اونٹوں تک میں چار برس کی اونٹنی ہے، اور جب چھہتر اونٹ ہو جائیں تو چھہتر سے نوے اونٹوں تک میں دو دو برس کی دو اونٹنیاں ہیں، اور جب اکیانوے ہو جائیں تو ایک سو بیس اونٹوں تک میں تین تین برس کی دو اونٹنیاں ہیں جو نر کے کودانے کے قابل ہو گئی ہوں۔ اور جب ایک سو بیس سے زیادہ ہو گئی ہوں تو ہر چالیس اونٹ میں دو برس کی ایک اونٹنی۔ اور ہر پچاس اونٹ میں تین برس کی ایک اونٹنی ہے، اگر اونٹوں کی عمروں میں اختلاف ہو (یعنی زکاۃ کے لائق اونٹ نہ ہو، اس سے بڑا یا چھوٹا ہو) مثلاً جس شخص پر چار برس کی اونٹنی لازم ہو اور اس کے پاس چار برس کی اونٹنی نہ ہو، تین برس کی اونٹنی ہو۔ تو تین برس کی اونٹنی ہی اس سے قبول کر لی جائے گی اور وہ ساتھ میں دو بکریاں بھی دے۔ اگر اسے بکریاں دینے میں آسانی و سہولت ہو، اور اگر دو بکریاں نہ دے سکتا ہو تو بیس درہم دے۔ اور جس شخص کو تین برس کی اونٹنی دینی پڑ رہی ہو، اور اس کے پاس تین برس کی اونٹنی نہ ہو، چار برس کی اونٹنی ہو تو چار برس کی اونٹنی ہی قبول کر لی جائے گی۔ اور عامل صدقہ (یعنی زکاۃ وصول کرنے والا) اسے بیس درہم واپس کرے گا۔ یا اسے بکریاں دینے میں آسانی ہو تو دو بکریاں دے۔ اور جس کو تین برس کی اونٹنی دینی ہو اور تین برس کی اونٹنی اس کے پاس نہ ہو اس کے پاس دو برس کی اونٹنی ہو تو وہ اس سے قبول کر لی جائے، اور وہ اس کے ساتھ دو بکریاں اور دے، اگر یہ اس کے لیے آسان ہو، یا بیس درہم دے، اور جس کو دو برس کی اونٹنی دینی ہو اور وہ اس کے پاس نہ ہو تین برس کی اونٹنی ہو تو وہ اس سے قبول کر لی جائے، اور عامل صدقہ اسے بیس درہم یا دو بکریاں واپس دے، اور جسے دو سال کی اونٹنی زکاۃ میں دینی ہو، اور دو سال کی اونٹنی اس کے پاس نہ ہو ایک سال کی اونٹنی ہو تو وہی اس سے قبول کر لی جائے، اور اس کے ساتھ وہ دو بکریاں دے اگر یہ اس کے لیے آسان ہو، یا بیس درہم دے، اور جس کے اوپر ایک برس کی اونٹنی دینی لازم ہو، اور اس کے پاس ایک برس کی اونٹنی نہ ہو۔ دو برس کا (نر) اونٹ ہو، تو دو برس کا اونٹ قبول کر لیا جائے۔ (اس کے ساتھ کچھ مزید لینا دینا نہیں ہو گا) اور جس کے پاس صرف چار اونٹ ہوں تو ان میں کوئی زکاۃ نہیں ہے سوائے اس کے کہ ان کا مالک اپنی خوشی سے کچھ دینا چاہے تو دے سکتا ہے، اور جنگل میں چرائی جانے والی بکریاں جب چالیس ہوں تو ان میں ایک سو بیس بکریوں تک میں ایک بکری زکاۃ ہے، اور ایک سو بیس سے جو ایک بکری بھی بڑھ جائے تو دو سو بکریوں تک میں دو بکریاں ہیں۔ اور دو سو سے ایک بکری بھی بڑھ جائے تو دو سو سے تین سو تک میں تین بکریاں ہیں اور جب تین سو سے بھی بڑھ جائیں تو پھر ہر ایک سو میں ایک بکری زکاۃ ہے۔ زکاۃ میں کوئی بوڑھا، کانا اور عیب دار جانور نہیں لیا جائے گا، اور نہ بکریوں کا نر جانور لیا جائے گا مگر یہ کہ صدقہ وصول کرنے والا کوئی ضرورت و مصلحت سے مجھے تو لے سکتا ہے، زکاۃ کے ڈر سے دو جدا مالوں کو یکجا نہیں کیا جا سکتا ۱؎ اور نہ یکجا مال کو جدا جدا ۲؎ اور جب آدمی کی چرائی جانے والی بکریاں چالیس سے ایک بھی کم ہوں تو ان میں کوئی زکاۃ نہیں ہے۔ ہاں ان کا مالک اپنی خوشی سے کچھ دینا چاہے تودے سکتا ہے، اور چاندی میں چالیسواں حصہ زکاۃ ہے، اور اگر ایک سو نوے درہم ہو تو اس میں کوئی زکاۃ نہیں۔ ہاں مالک اپنی خوشی سے کچھ دینا چاہے تو دے سکتا ہے۔\n§وضاحت\n۱؎: یہ حکم جانوروں کے مالکوں اور زکاۃ کے محصلین دونوں کے لیے ہے، اس کی تفسیر یہ ہے: مثلاً تین آدمیوں کی چالیس چالیس بکریاں ہوں، تو اس صورت میں ہر ایک پر ایک ایک بکری واجب ہے، جب زکاۃ لینے والا آیا تو ان تینوں نے اپنی اپنی بکریوں کو یکجا کر دیا کہ ایک ہی بکری دینی پڑے، ایسا کرنے سے منع کیا گیا ہے۔ اسی طرح اگر تین متفرق لوگوں کے پاس انتالیس انتالیس بکریاں ہوں تو ان پر الگ الگ کوئی زکاۃ نہیں، تو عامل ان کو زکاۃ لینے کے لیے یکجا نہ کر دے کہ ایک بکری زکاۃ میں لے لے۔ ۲؎: اس کی تفسیر یہ ہے کہ مثلاً دو ساجھی دار ہیں ہر ایک کی ایک سو ایک، ایک سو ایک، بکریاں ہیں، تو کل ملا کر دو سو دو بکریاں ہوئیں، ان میں تین بکریاں لازم آتی ہیں، جب زکاۃ لینے والا آیا تو ان دونوں نے اپنی اپنی بکریاں الگ الگ کر لیں تاکہ ایک ہی ایک بکری لازم آئے ایسا کرنے سے منع کیا گیا ہے، نیز اسی طرح اگر تین ساجھے داروں کے پاس ساجھا میں ایک سو بیس کی بکریاں ہوں تو اس مجموعہ پر صرف ایک بکری واجب ہو گی، تو عامل زکاۃ لینے کے لیے ان بکریوں کو تین الگ الگ حصوں میں نہ کر دے کہ تین بکریاں لے لے۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ سے روایت ہے کہ حضرت ابوبکر رضی اللہ عنہ (خلیفہ رسول صلی اللہ علیہ وسلم نے ان (عاملین زکاۃ کو یہ تحریر لکھ بھیجی: یہ وہ مقرر شدہ صدقات ہیں جو رسول اللہ صلی اللہ علیہ وسلم نے مسلمانوں پر مقرر فرمائے اور اللہ تعالیٰ نے ان کا اپنے رسول اللہ صلی اللہ علیہ وسلم کو حکم دیا۔ جس مسلمان سے یہ صدقات مقررہ طریق کار کے مطابق طلب کیے جائیں تو وہ لازماً ادا کرے اور جس سے مقررہ مقدار سے زائد مانگے جائیں، وہ نہ دے۔ (ان کی تفصیل یہ ہے: اونٹ پچیس سے کم ہوں تو ہر پانچ اونٹوں میں ایک بکری (زکاۃ ہے۔ جب اونٹ پچیس ہو جائیں تو ان میں ایک بنت مخاض (ایک برس کی اونٹنی ہے۔ پینتیس تک یہی زکاۃ ہوگی۔ اگر ایک برس کی (مادہ اونٹنی نہ ہو تو دو برس کا (نر اونٹ (زکاۃ ہے۔ جب وہ چھتیس ہو جائیں تو پینتالیس تک ان میں ایک بنت لبون (دو برس کی اونٹنی ہے۔ جب وہ چھیالیس ہو جائیںتو ساٹھ تک ایک حقہ (تین برس کی اونٹنی ہے۔ جو نر کی جفتی کے قابل ہو۔ جب اکسٹھ ہو جائیں تو پچھتّر تک ایک جذعہ (چار برس کی مادہ اونٹنی زکاۃ ہے۔ جب وہ چھہتر ہو جائیں تو نوے تک ان میں دو بنت لبون (دو دو برس کی دو اونٹنیاں زکاۃ ہیں۔ جب وہ اکانوے ہو جائیں تو ایک سو بیس تک دو حقے (تین تین برس کی دو اونٹنیاں ہیں جو نر کی جفتی کے قابل ہوں۔ جب ایک سو بیس سے زائد ہو جائیں تو ہر چالیس میں ایک بنت لبون اور ہر پچاس میں ایک حقہ (زکوٰۃ ہے۔ اگر اونٹوں کی عمریں مختلف ہوں (اور مقررہ عمر کے اونٹ نہ مل سکیں تو جس آدمی کے ذمے جذعہ ہو اور اس کو جذعہ میسر نہ ہو، البتہ اس کے پاس حقہ ہو تو اس سے حقہ ہی لی جائے گی اور اس کے ساتھ دو بکریاں لی جائیں گی، اگر اسے میسر ہوں، ورنہ بیس درہم لیے جائیں گے۔ اور جس شخص کے ذمے حقہ زکاۃ ہو مگر اس کے پاس صرف جذعہ ہے تو اس سے وہی لی جائے گی اور زکاۃ وصول کرنے والا اس کو بیس درہم یا اگر میسر ہوں تو دو بکریاں واپس کرے گا۔ اسی طرح اگر کسی آدمی کے ذمے حقہ زکاۃ بنتی ہو لیکن اس کے پاس حقہ نہ ہو بلکہ اس کے پاس بنت لبون ہو تگو وہی اس سے لی جائے گی اور اس کے ساتھ مزید دو بکریاں لی جائیں گی، اگر اسے میسر ہوں، ورنہ بیس درہم لیے جائیں گے۔ اور جس شخص کے ذمے بنت لبون زکاۃ بنتی ہو مگر اس کے پاس صرف حقہ ہو توب اس سے وہی لی جائے گی اور صدقہ وصول کرنے والا اسے بیس درہم یا دو بکریاں واپس کرے گا۔ اسی طرح جس شخص کے ذمہ بنت لبون زکاۃ بنتی ہو، مگر اس کے پاس بنت لبون نہ ہو بلکہ بنت مخاض ہو تو اس سے وہی لی جائے گی اور اس کے ساتھ مزید دو بکریاں دے گا، اگر اسے میسر ہوں، ورنہ بیس درہم دے گا۔ اور جس آدمی کے ذمے بنت مخاض زکاۃ بنتی ہو، مگر اس کے پاس صرف ابن لبون ہو تو اس سے وہی لیا جائے گا اور اس کے ساتھ کوئی اور چیز نہ لی جائے گی۔ اور جس آدمی کے پاس صرف چار اونٹ ہوں تو ان میں کوئی زکاۃ واجب نہیں مگر مالک خوشی سے دینار چاہے (تو الگ بات ہے۔ اور جنگل میں چرنے والی بکریاں ہوں اور چالیس ہو جائیں تو ایک سو بیس تک ایک بکری زکاۃ ہے۔ جب اس سے ایک بھی زائد ہو جائے تو دو سو تک دو بکریاں زکاۃ ہے۔ جب اس سے ایک بھی بڑھ جائے تو تین سو تک تین بکریاں زکاۃ ہے۔ اور جب اس سے بڑھ جائیں تو ہر سو میں ایک بکری زکاۃ ہوگی۔ زکاۃ میں بوڑھا یا کانا (عیب والا جانور یا نر بکرا نہیں لیا جائے گا۔ ہاں، اگر صدقہ وصول کرنے والا چاہے تو نر بکرا لے سکتا ہے۔ علیحدہ علیحدہ جانوروں کو (زکاۃ کے موقع پر اکٹھا نہیں کیا جائے گا، اسی طرح اکٹھے رہنے والے جانوروں کو زکاۃ کے ڈر سے الگ الگ نہیں کیا جائے گا۔ اور جو زکاۃ دو شریک مالکوں سے وصول کی جائے، وہ آپس میں اپنے جانوروں کے حساب سے تقسیم کر لیں گے۔ اور اگر جنگل اور صحرا میں چرنے والی بکریاں چالیس سے کم ہوں، خواہ ایک ہی کم ہون، ان میں کوئی زکاۃ نہیں مگر مالک خوشی سے دینا چاہے (تو الگ بات ہے۔ اور چاندی میں چالیسواں حصہ زکاۃ ہے لیکن اگر ایک سو نوے درہم ہوں (یعنی ۲۰۰ درہم سے کم ہوں۔ تو ان میں کوئی زکاۃ نہیں مگر یہ کہ مالک خود دینا چاہے۔","f2":"(۱ یہ تحریر رسول اللہ صلی اللہ علیہ وسلم نے لکھوائی تھی تاکہ سرکاری حکام کو بھیجیں مگر آپ کو موقع نہ مل سکا۔ حضرت ابوبکر رضی اللہ عنہ خلیفہ بنے تو انھوں نے یہ تحریر نقلیں کروا کر تمام حکام کو بھیجی۔ ویسے بھی اس تحریر میں حضرت ابوبکر رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم کا حوالہ دیا ہے، لہٰذا یہ تحریر مرفوع، یعنی رسول اللہ صلی اللہ علیہ وسلم کا فرمان ہے۔ (۲ ’’وہ نہ دے۔‘‘ یعنی زائد زکاۃ نہ دے یا بالکل زکاۃ نہ دے کیونکہ ظالم حاکم شرعاً معزول ہوتا ہے۔ (۳ ’’ہر پانچ میں ایک بکری۔‘‘ یعنی پانچ اونٹوں میں ایک بکری، دس میں دو، پندرہ میں تین، بیس میں چار، چوبیس تک۔ (۴ ’’بنت مخاض‘‘ ایک سال کی اونٹنی جو دوسرے سال میں شروع ہو چکی ہو۔ ’’بنت لبون‘‘ جو دو سال کی ہو اور تیسرے سال میں داخل ہو۔ ’’حقہ‘‘ تین سال کی اونٹنی جو چوتھے سال میں شروع ہو۔ اس عمر کی اونٹنی نر کی جفتی کے قابل ہو جاتی ہے، نیز وہ سواری کے بھی قابل ہو جاتی ہے۔ ’’جزغہ‘‘ چار سال کی اونٹنی جو پانچویں سال میں شروع ہو۔ یہاں یہ بات قابل ذکر ہے کہ اونٹوں کی زکاۃ میں صرف مؤنث، یعنی اونٹنی ہی لی جائے گی کیونکہ مؤنث کی قیمت زیادہ ہوتی ہے اور اس سے سواری، گوشت، دودھ اور نسل کا فائدہ حاصل ہوتا ہے جبکہ مذکر، یعنی نر اونٹ سے صرف سواری اور گوشت کا فائدہ حاصل ہوتا ہے، اس لیے اونٹنی میں فقراء کا فائدہ ہے، لہٰذا اگر مجبوراً نر لیا جائے تو وہ مقررہ زکاۃ سے ایک سال بڑی عمر کا لیا جائے گا تاکہ قیمت برابر ہو جائے۔ یا اصل جانور کی قیمت وصول کی جائے گی۔ (۵ جب ایک سو بیس سے زائد ہو جائیں، یعنی ایک سو اکیس ہو جائیں تو ہر چالیس میں ایک بنت لبون اور ہر پچاس میں ایک حقہ ہوگی، یعنی اس تعداد کو چالیس اور پچاس کے حصوں میں بانٹ لیا جائے، مثلاً: ۱۲۱ سے ۱۲۹ تک تین چالیس حصے بنتے ہیں، لہٰذا تین بنت لبون زکاۃ ہوگی۔ ۱۳۰ سے ۱۳۹ تک دو چالیس اور ایک پچاس بنتے ہیں لہٰذا دو بنت لبون اور ایک حقہ زکاۃ ہوگی۔ ۱۴۰ میں ایک چالیس اور دو پچاس بنتے ہیں، لہٰذا ایک بنت لبون اور دو حقے زکاۃ ہوگی۔ یہ بھی یاد رکھا جائے کہ ان صورتوں میں پچھلی دہائی کی زکاۃ اگلی دہائی تک چلے گی، یعنی ۱۳۰ والی زکاۃ ۱۳۹ تک، ۱۴۰ والی زکاۃ ۱۴۹ تک اور ۱۵۰ کی زکاۃ ۱۵۹ تک چلے گی۔ (۶ ’’اگر مقررہ عمر کے اونٹ نہ مل سکیں۔‘‘ ایسی صورت میں مقررہ اونٹ کی قیمت وصول کی جائے گی یا چھوٹی یا بڑی عمر کا اونٹ لے کر اور مزید کچھ لے دے کر قیمت پوری کر لی جائے گی جس کی چند صورتیں بیان کی گئی ہیں جو اصل قیمت ہے، آپ صلی اللہ علیہ وسلم نے دو بکریاں یا بیس درہم قیمت کے حساب سے مقرر فرمائی ہیں۔ مذکورہ کمی پوری کرنے کے لیے دو بکریاں ہی مانی جائیں گی، پھر جہاں ان (دو بکریوں کی جو قیمت بنتی ہو وہ قیمت مانی جائے گی۔ (۷ ’’ہر سو میں ایک بکری۔‘‘ ظاہر تو یوں معلوم ہوتا ہے کہ ۳۰۱ سے ۴۰۰ تک چار بکریاں اور ۴۰۱ سے ۵۰۰ تک پانچ بکریاں مگر جمہور اہل علم نے یہ مفہوم مراد نہیں لیا، بلکہ ان کا خیال ہے کہ چوتھی بکری ۴۰۰ بکریوں میں پڑے گی۔ اس سے کم میں تین بکریاں ہی زکاۃ ہوں گی گویا ۲۰۱ سے ۳۹۹ تک تین بکریاں ہی رہیں گی۔ واللہ اعلم (۸ ’’بوڑھا، کانا (عیب والا جانور۔‘‘ زکاۃ میں صحیح سالم جانور وصول کیا جائے گا اور موٹاپے کے لحاظ سے درمیانہ جانور لیا جائے گا، نہ بہت اچھا اور نہ بہت کمزور۔ اونٹوں میں تو عمر مقرر ہے، بکریوں میں جوان بکری لی جائے گی۔ (۹ ’’مذکر (نر۔‘‘ جو بکریوں کے لیے رکھا گیا ہو کیونکہ وہ قیمتی ہوتا ہے، اس سے مالک کو نقصان ہوگا۔ یا اس لیے کہ بکری فقراء کے لیے زیادہ مفید ہے، اس سے بچے حاصل ہوں گے، لہٰذا زکاۃ میں مؤنث ہی وصول کی جائے گی۔ الا یہ کہ صدقہ وصول کرنے والا مذکر کی ضرورت محسوس کرے اور مالک دینے پر راضی ہو۔ (۱۰ ’’اکٹھا نہیں کیا جائے گا۔‘‘ ایک شخص کے پاس پچاس بکریاں ہوں اور دوسرے کے پاس بھی پچاس تو ان کی زکاۃ ایک ایک بکری دینی پڑے گی لیکن اگر وہ دونوں ایک مالک ظاہر کر کے بکریاں اکٹھی ظاہر کر دیں تو کل سو بکریوں میں صرف ایک بکری زکاۃ ہوگی۔ یہ فائدہ حاصل کرنے کے لیے کوئی شخص یہ حیلہ کر سکتا ہے، لہٰذا اس سے منع فرمایا تاکہ زکاۃ سے فرار کا رجحان پیدا نہ ہو۔ واجب سے بچنے کے لیے ایسا حیلہ کرنا حرام ہے۔ اسی طرح کبھی اکٹھی بکریوں کو متفرق ظاہر کر کے ۳۰، ۳۰ کے ریوڑ بنا دے تو زکاۃ سے بچ سکتا ہے، مگر اس قسم کے حیلے جو حرام کو حلال کریں یا حلال کو حرام یا اسی طرح واجب کو ساقط کر دیں، شرعاً حرام ہیں اور جرم ہیں۔ اس کے برعکس زکاۃ وصول کرنے والا بھی کر سکتا ہے، لہٰزا اس کے لیے بھی منع ہے، مثلاً: دو شرکاء کے پاس مجموعی طور پر سو بکریاں ہیں، زکاۃ وصول کرنے والا زیادہ وصول کرنے کی خاطر ان سو بکریوں کو الگ الگ کر دے گا تو دو بکریاں زکاۃ مل جائے گی جبکہ یکجا رہنے میں ایک ہی ملے گی۔ یا مثلاً: دو آدمیوں کے پاس الگ الگ ۱۱۵، ۱۱۵ بکریاں ہیں جن میں صرف ایک ایک بکری زکاۃ ہے، وصول کرنے والا آکر دونوں کو یکجا کر دے تو اس کو تین بکریاں مل جائیں گی، تو اس کے لیے بھی ایسا کرنا جائز نہیں۔ غرض زکاۃ کے خوف سے جمع یا متفرق کرنے کی ممانعت مالک کو بھی ہے اور زکاۃ وصول کرنے والے (عامل کو بھی۔ (۱۱ ’’دو شریک مالکوں سے زکاۃ۔‘‘ اگر دو شخص مشترکہ طور پر جانوروں کے مالک ہیں، وہ کسی بھی تناسب سے مالک ہوں، عائد ہونے والی زکاۃ اسی تناسب سے ان کو دینی پڑے گی بشرطیکہ وہ جانور ایک ہی باڑے میں رہتے ہوں، ان کا چرواہا اور دیگر اخراجات مشترکہ طور پر ہوتے ہوں۔ گویا ظاہراً ان میں کوئی امتیاز نہ ہو تو ان کی زکاۃ مشترکہ وصول کی جائے گی۔ (۱۲ چاندی یا کرنسی کی زکاۃ کا مسئلہ حدیث: ۲۴۴۷ کے تحت بیان ہو چکا ہے۔"}],[2448,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہ اونٹ اپنے مالک کے پاس جب اس نے ان میں ان کا حق نہ دیا ہو گا اس سے بہتر حالت میں آئیں گے جس میں وہ (دنیا میں) تھے، وہ اسے اپنے کھروں سے روندیں گے، اور بکریاں اپنے مالک کے پاس جب اس نے ان میں ان کا حق نہ دیا ہو گا، اس سے بہتر حالت میں آئیں گی جس حالت میں وہ (دنیا میں) تھیں۔ وہ اسے اپنی کھروں سے روندیں گی، اور اپنی سینگوں سے ماریں گی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"ان کا حق یہ بھی ہے کہ انہیں اسی جگہ دوہا جائے جہاں انہیں پانی پلانے کا نظم ہو ۱؎، سن لو، قیامت کے دن تم میں کا کوئی اپنے اونٹ کو اپنی گردن پر لادے ہوئے نہ لائے وہ بلبلا رہا ہو، پھر وہ کہے: اے محمد! (بچائیے مجھ کو اس عذاب سے) کہ میں کہوں: میں تیرے لیے کچھ نہیں کر سکتا، میں تو تجھے بتا چکا تھا، سن لو! قیامت کے دن کوئی اپنی گردن پر بکری کو لادے ہوئے نہ آئے کہ وہ ممیا رہی ہو، پھر وہ کہے: اے محمد! (مجھے اس عذاب سے بچائیے) کہ اس وقت میں کہوں: میں تیرے لیے کچھ نہیں کر سکتا، میں تو تجھے پہلے ہی بتا چکا ہوں\"۔ آپ نے فرمایا: \"تم میں سے کسی کا خزانہ ۲؎ قیامت کے دن گنجا سانپ بن کر سامنے آئے گا، اس کا مالک اس سے بھاگے گا، اور وہ اس کا برابر پیچھا کرتا رہے گا، اور کہے گا: میں تیرا خزانہ ہوں یہاں تک کہ وہ اس کی انگلی کو اپنے منہ میں داخل کر لے گا\"۔\n§وضاحت\n۱؎: یعنی: بکریوں کو گھاٹوں پر دوہا جائے تاکہ وہاں موجود مساکین کو بھی اس میں سے کچھ دیا جائے، نہ کہ بند گھروں میں مساکین سے بچنے کے لیے دوہا جائے۔ ۲؎: جس کی وہ زکاۃ نہیں ادا کرتا تھا۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اگر اونٹوں کے مالک نے ان کا حق ادا نہیں کیا ہوگا (ان کی زکاۃ نہ دی ہوگی تو وہ اونٹ (قیامت کے دن بہترین موٹاپے کی حالت میں اس پر آئیں گے اور اسے اپنے پاؤں سے روندیں گے۔ اور اگر بکریوں کے مالک نے ان کا حق ادا نہیں کیا ہوگا (ان کی زکاۃ نہ دی ہوگی تو وہ بکریاں (قیامت کے دن بہترین موٹاپے کی حالت میں اس پر آئیں گی، اسے اپنے کھروں سے مسلیں گی اور اپنے سینگوں سے اسے ٹکریں ماریں گی۔‘‘ فرمایا: ’’اور ان جانوروں میں یہ حق بھی ہے کہ جب وہ پانی پینے جائیں تو (وہاں موجود فقراء کو ان کا دودھ دوھ کر دیا جائے۔ خبردار! ایسا نہ ہو کہ قیامت کے دن تم میں سے کوئی شخص اپنی گردن پر اونٹ اٹھائے ہوئے آئے اور وہ اونٹ بلبلا رہا ہو۔ وہ کہے: اے محمد! (میری مدد فرمائیے اور میں کہہ دوں کہ میں تیرے بارے میں کوئی اختیار نہیں رکھتا۔ میں نے تمہیں تبلیغ کر دی تھی۔ خبردار! ایسا نہ ہو کہ تم میں سے کوئی شخص قیامت کے دن اپنی گردن پر بکری اٹھا کر لائے، وہ بکری ممیار ہی ہو اور وہ کہے: اے محمد! (میری مدد فرمائیے اور میں کہہ دوں کہ میں تیرے بارے میں کوئی اختیار نہیں رکھتا۔ میں نے تمہیں تبلیغ کر دی تھی، نیز آپ نے فرمایا: ان (لوگوں کا خزانہ (جس کی زکاۃ نہ دی گئی ہو قیامت کے دن گنجے سانپ کی صورت اختیار کرے گا۔ اس کا مالک اس سے بھاگے گا لیکن وہ اسے تلاش کرے گا اور کہے گا: میں تیرا خزانہ ہوں۔ وہ اسی طرح اس کا پیچھا کرتا رہے گا حتیٰ کہ وہ اپنی انگلیاں اس (سانپ کے منہ میں ڈال دے گا۔‘‘","f2":"(۱ ’’یہ حق بھی ہے۔‘‘ اور یہ حق زکاۃ کے علاوہ ہے۔ یہ اگرچہ واجب تو نہیں مگر اس کی ادائیگی بھی اہم ہے۔ قیامت کے دن عذاب تو زکاۃ نہ دینے ہی پر ہوگا، مگر اس قسم کے حقوق کو ادا نہ کرنا بھی مروت اور انسانیت کے خلاف ہے جو دنیا میں قابل مذمت ہے، خصوصاً اگر کوئی فقیر اس قدر بھوکا ہو کہ یہ دودھ اس کی مجبوری ہو تو پھر اس کی جان بچانا فرض ہے۔ ایسے موقع پر یہ حق بھی فرض بن جائے گا۔ (۲ ’’خزانہ جس کی زکاۃ ادا نہ کی گئی ہو۔‘‘ اگر زکاۃ ادا کر دی جائے تو وہ خزانہ رکھا جا سکتا ہے بشرطیکہ دوسرے ضروری حقوق بھی پورے کیے جائیں، مثلاً: والدین سے حسن سلوک، مہمان کی خدمت، فقیر کی حاجت برآری وغیرہ۔ حضرت ابو ذر رضی اللہ عنہ کا موقف ہے کہ روز مرہ کی ضروریات سے زائد جمع شدہ بھی کنز ہی ہے جس کے بارے میں مذکورہ ب الا وعید نازل ہوئی ہے۔ ان کا اس سلسلے میں تشدد، نصوص اور صحابہ کے اجماعی طرز عمل سے مطابقت نہیں رکھتا، البتہ اسے ورع اور اولیٰ ہونے پر محمول کیا جائے گا۔"}],[2449,"بہز بن حکیم کے دادا معاویہ بن حیدہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: ہر چرنے والے چالیس اونٹوں میں دو برس کی اونٹنی ہے۔ اونٹ اپنے حساب (ریوڑ) سے جدا نہ کئے جائیں، جو ثواب کی امید رکھ کر انہیں دے گا تو اسے اس کا اجر ملے گا، اور جو دینے سے انکار کرے گا تو ہم اس سے اسے لے کر رہیں گے، مزید اس کے آدھے اونٹ اور لے لیں گے، یہ ہمارے رب کے تاکیدی حکموں میں سے ایک حکم ہے، محمد کے آل کے لیے اس میں سے کوئی چیز حلال نہیں ہے۔","الألباني: حسن",{"u2":"حضرت بہز بن حکیم کے دادا نے کہا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے سنا: ’’باہر چرنے والے اونٹوں کی زکاۃ ہر چالیس اونٹوں میں ایک بنت لبون (دو برس کی اونٹنی) ہے۔ اونٹوں کو ان کے حساب ومقدار سے ادھر ادھر نہ کیا جائے۔ جو آدمی ثواب حاصل کرنے کے لیے زکاۃ دے گا، اسے اس کا ثواب ملے گا اور جو نہ دے گا، ہم اس سے زکاۃ تو (بہر صورت) وصول کریں گے اور اس کے نصف اونٹ بھی ضبط کر لیں گے۔ زکاۃ ہمارے رب کے فرائض میں سے ایک فریضہ ہے اور محمد صلی اللہ علیہ وسلم کے خاندان کے لیے ذرہ بھر زکاۃ بھی جائز نہیں۔‘‘","f2":"(۱) امام نسائی رحمہ اللہ نے باب والا مسئلہ ’’چرنے والے اونٹوں۔‘‘ سے استنباط کیا ہے کیونکہ جو اونٹ گھریلو ضروریات کے لیے ہوتے ہیں، انھیں گھر میں رکھا جاتا ہے اور انھیں چارہ ڈالا جاتا ہے۔ اور ان میں واقعتاً زکاۃ نہیں۔ اونٹوں کے علاوہ بھی جو چیز انسان کی ذاتی ضروریات کے لیے ہو، اس میں زکاۃ نہیں، خواہ وہ کتنی ہی قیمتی کیوں نہ ہو؟ (۲) ’’ادھر ادھر نہ کیا جائے۔‘‘ اس کا دوسرا مفہوم بھی ہو سکتا ہے جو حدیث: ۲۴۴۹ کے فائدہ: ۱۰ میں بیان ہوا ہے۔ تفصیل کے لیے دیکھیے (حدیث: ۲۴۴۶)"}],[2450,"معاذ بن جبل رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے انہیں یمن بھیجا اور حکم دیا کہ ہر بالغ شخص سے ایک دینار (جزیہ) لیں یا اتنی قیمت کی یمنی چادریں، اور ہر تیس گائے بیل میں ایک برس کا بچھوا یا بچھیا لیں، اور ہر چالیس گائے اور بیل میں دو برس کی ایک گائے۔","الألباني: صحيح",{"u2":"حضرت معاذ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے انھیں (مجھے) یمن کی طرف (حاکم بنا کر) بھیجا اور حکم دیا کہ ہر غیر مسلم بالغ سے ایک دینار (بطور جزیہ) لوں یا اس کے برابر معافری کپڑا۔ اور ہر تیس گایوں میں سے تبعیۃ (دوسرے سال میں داخل بچھڑا یا بچھڑی) اور ہر چالیس گایوں میں سے دو دانت والا بچھڑایا بچھڑی (بطور زکاۃ) وصول کروں۔","f2":"(۱) چونکہ یمن میں اہل کتاب کی ایک بڑی تعداد رہائش پذیر تھی، لہٰذا ان پر جزیہ لاگو کیا گیا۔ ’’جزیہ‘‘ وہ ٹیکس ہے جو مسلمان حکومت غیر مسلم رعایا سے ان کی حفاظت اور دیگر سہولیات کے عوض وصول کرتی ہے۔ (۲) ’’معافری کپڑا۔‘‘ یہ ایک مخصوص کپڑا تھا جو یمن میں تیار ہوتا تھا۔ دھاری دار ہوتا تھا۔ پہننے کے لیے بہترین چادریں تھیں۔ اگر کوئی جزیہ رقم کی صورت میں نہ دے سکے تو اس کے عوض دینار کی قیمت کی کوئی اور چیز بھی دے سکتا تھا۔ (۳) گایوں کی زکاۃ میں مذکر اور مؤنث برابر ہیں کیونکہ دونوں اپنی اپنی خصوصیات کی بنا پر مساوی قیمت رکھتے ہیں۔ مؤنث بچے دیتی ہے تو مذکر کھیتی باڑی کا اہم کام کرتے ہیں۔ مؤنث اس سے عاجز ہے۔ بخالف اونٹوں اور بکریوں کے کہ ان میں مؤنث بچے اور دودھ دینے کے علاوہ کام کاج میں مذکر کے برابر ہیں، لہٰذا مؤنث قیمتی ہیں۔ (۴) چالیس گایوں سے اوپر ہوں تو ان کے تیس اور چالیس کے حصے بنائے جائیں گے۔ ہر تیس میں ایک سالہ اور ہر چالیس میں دو سالہ بچھڑا یا بچھڑی زکاۃ ہوگی، مثلاً: ۶۰ میں دو ایک سالہ، ۷۰ میں ایک دو سالہ اور ایک ایک سالہ، ۸۰ میں دو دو سالہ، ۹۰ میں تین ایک سالہ، ۱۰۰ میں دو ایک سالہ اور ایک دو سالہ بچھڑا یا بچھڑی زکاۃ ہوگی۔"}],[2451,"معاذ بن جبل رضی اللہ عنہ کہتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے یمن بھیجا، تو مجھے حکم دیا کہ ہر چالیس گائے میں دو برس کی ایک گائے، اور ہر تیس میں ایک سال کا ایک بچھوا لوں۔ اور ہر بالغ سے (بطور جزیہ) ایک دینار لوں، یا ایک دینار کے مساوی قیمت کی یمنی چادر۔","الألباني: صحيح لغيره",{"u2":"حضرت معاذ رضی اللہ عنہ فرماتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے یمن کی طرف (حاکم بنا کر بھیجا اور مجھے حکم دیا کہ میں ہر چالیس گایوں میں سے ایک دو سالہ (دو دانتا اور ہر تیس میں سے ایک سالہ بچھڑا یا بچھڑی زکاۃ وصول کروں، نیز ہر بالغ (یہودی وغیرہ سے ایک دینار یا اس کے برابر یمنی کپڑا (بطور جزیہ وصول کروں۔"}],[2452,"معاذ بن جبل رضی اللہ عنہ سے روایت ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم نے انہیں یمن بھیجا تو انہیں حکم دیا کہ ہر تیس گائے بیل میں ایک سال کا بچھوا یا بچھیا لیں، اور ہر چالیس گائے میں دو سال کی بچھیا۔ اور ہر بالغ سے (جزیہ میں) ایک دینار یا ایک دینار کی قیمت کی یمنی چادر۔","الألباني: صحيح",{"u2":"حضرت معاذ رضی اللہ عنہ سے مروی ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم نے انھیں (مجھے یمن کی طرف بھیجا تو حکم دیا کہ ہر تیس گایوں میں سے ایک سالہ بچھڑا یا بچھڑی اور ہر چالیس گایوں میں سے ایک دو سالہ (دو دانتا وصول کروں اور ہر (غیر مسلم بالغ سے ایک دینار یا اس کے برابر معافری کپڑا (بطور جزیہ وصول کروں۔"}],[2453,"معاذ بن جبل رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے جس وقت مجھے یمن بھیجا تو حکم دیا کہ میں گائے، بیل سے جب تک وہ تیس کی تعداد کو نہ پہنچ جائیں کچھ نہ لوں، اور جب تیس ہو جائیں تو ان میں گائے کا ایک سال کا بچہ چاہے نر ہو یا مادہ یہاں تک کہ وہ چالیس کو پہنچ جائیں، اور جب چالیس ہو جائیں تو ان میں دو سال کی ایک بچھیا ہے۔","الألباني: حسن صحيح",{"u2":"حضرت معاذ بن جبل رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے جب مجھے یمن بھیجا تو مجھے حکم دیا کہ میں گایوں سے زکاۃ نہ لوں حتیٰ کہ وہ تیس ہو جائیں جب تیس ہو جائیں تو چالیس تک ان میں سے جذعۃ (دوسرے سال میں داخل) نوجوان بچھڑا یا بچھڑی زکاۃ ہوگی۔ اور جب وہ چالیس ہوجائیں تو ان میں دو سالہ (دو دانتا) گائے (مذکر یا مؤنث) زکاۃ ہوگی۔","f2":"حضرت معاذ رضی اللہ عنہ سے مروی مذکورہ چاروں احادیث کو مہقق کتاب نے سنداً ضعیف قرار دیا ہے جبکہ دیگر محققین میں سے بعض نے حسن اور بعض نے صحیح قرار دیا ہے اور انھوں نے اس کے شواہد بھی بیان کیے ہیں جس سے معلوم ہوتا ہے کہ مذکورہ روایت سنداً ضعیف ہونے کے باوجود قابل عمل اور قابل حجت ہے۔ مذکو رہ روایات کی اسنادی بحث اور ان میں مذکورہ مسئلے کی تفصیل کے لیے دیکھیے: (ذخیرۃ العقبیٰ شرح سنن النسائی: ۲۲/ ۱۰۸-۱۱۷، والموسوعۃ الحدیثیۃ مسند الامام احمد: ۷/ ۲۱-۲۳، و ۳۶/ ۳۳۹-۲۳ وارواء الغلیل: ۳/ ۲۶۸-۲۷۱، رقم: ۷۹۵)"}],[2454,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو بھی اونٹ، گائے اور بکری والا ان کا حق ادا نہیں کرے گا، (یعنی زکاۃ نہیں ادا کرے گا) تو اسے قیامت کے دن ایک کشادہ ہموار میدان میں کھڑا کیا جائے گا، کھر والے جانور اپنے کھروں سے اسے روندیں گے، اور سینگ والے اسے اپنی سینگوں سے ماریں گے۔ اس دن ان میں کوئی ایسا نہ ہو گا جس کے سینگ ہی نہ ہو اور نہ ہی کسی کی سینگ ٹوٹی ہوئی ہو گی\"، ہم نے عرض کیا: اللہ کے رسول! ان کا حق کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"ان پر نر کودوانا، ان کے ڈول کو منگنی دینا اور اللہ کی راہ میں ان پر بوجھ اور سواری لادنا، اور جو صاحب مال اپنے مال کا حق ادا نہ کرے گا وہ مال قیامت کے دن ایک گنجے (زہریلے) سانپ کی شکل میں اسے دکھائی پڑے گا، اس کا مالک اس سے بھاگے گا، اور وہ اس کا پیچھا کرے گا، اور اس سے کہے گا: یہ تو تیرا وہ خزانہ ہے جس کے ساتھ تو بخل کرتا تھا، جب وہ دیکھے گا کہ اس سے بچنے کی کوئی صورت نہیں ہے تو (لاچار ہو کر) اپنا ہاتھ اس کے منہ میں ڈال دے گا، اور وہ اس کو اس طرح چبائے گا جس طرح اونٹ چباتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو بھی اونٹوں، گایوں یا بکریوں کا مالک ان کا حق (ان کی زکاۃ نہیں دے گا، اسے قیامت کے دن ایک ہموار کھلے میدان میں کھڑا کیا جائے گا۔ کھروں والے جانور اسے اپنے کھروں سے کچلیں گے اور سینگوں والے جانور اسے اپنے سینگوں سے ٹکریں ماریں گے۔ ان میں سے کوئی بھی بغیر سینگوں کے نہ ہوگا اور نہ کسی کے سینگ ٹوٹے ہوئے ہوں گے۔‘‘ ہم نے کہا: اے اللہ کے رسول! (زکاۃ کے علاوہ ان میں اور کیا حق ہیں؟ آپ نے فرمایا: ’’نر جفتی کے لیے دینا، پانی نکالنے کے لیے ڈول دینا اور اللہ کے راستے میں (جہاد کے لیے اور فقیر وغیرہ ضرورت مند کو بوجھ لادنے اور سواری کے لیے دینا۔ اسی طرح روپے پیسے والا اگر ان کی زکاۃ نہیں دے گا تو قیامت کے دن وہ اس کے لیے ایک گنجا سانپ بنا دیا جائے گا، مالک اس سے بھاگے گا لیکن وہ سانپ اس کے پیچھے دوڑے گا اور کہے گا: میں تیرا وہ خزانہ ہوں جس کے ساتھ تو بل کرتا تھا۔ جب مالک کو یقین ہو جائے گا کہ اس سے بچنے کا کوئی چارہ نہیں تو وہ اپنا ہاتھ اس کے منہ میں ڈال دے گا۔ وہ اس کو اس طر چبائے گا جس طر اونٹ چباتا ہے۔‘‘"}],[2455,"انس بن مالک رضی اللہ عنہ سے روایت ہے کہ ابوبکر رضی اللہ عنہ نے انہیں یہ لکھ کر دیا کہ صدقہ (زکاۃ) کے یہ وہ فرائض ہیں جنہیں رسول اللہ صلی اللہ علیہ وسلم نے مسلمانوں پر فرض ٹھہرائے ہیں جس کا اللہ تعالی نے اپنے رسول کو حکم دیا ہے، تو جس مسلمان سے اس کے مطابق زکاۃ طلب کی جائے تو وہ اسے دے، اور جس سے اس سے زیادہ مانگا جائے تو وہ اسے نہ دے۔ پچیس اونٹوں سے کم میں ہر پانچ اونٹ میں ایک بکری ہے۔ اور جب پچیس اونٹ ہو جائیں تو اس میں پنتیس اونٹوں تک ایک برس کی اونٹنی ہے، اگر ایک برس کی اونٹنی نہ ہو تو دو برس کا اونٹ (نر) ہے۔ اور جب چھتیس اونٹ ہو جائیں تو چھتیس سے پینتالیس تک دو برس کی اونٹنی ہے۔ اور جب چھیالیس اونٹ ہو جائیں تو اس میں ساٹھ اونٹ تک تین برس کی اونٹنی ہے، جو نر کودانے کے لائق ہو گئی ہو، اور جب اکسٹھ اونٹ ہو جائیں تو اس میں پچہتر اونٹ تک چار برس کی اونٹنی ہے، اور جب چھہتر اونٹ ہو جائیں تو اس میں نوے تک میں دو دو برس کی دو اونٹنیاں ہیں، اور جب اکیانوے ہو جائیں تو ایک سو بیس تک میں تین تین برس کی دو اونٹنیاں ہیں جو نر کودانے کے قابل ہو گئی ہوں، اور جب ایک سو بیس سے زیادہ ہو گئی ہوں تو ہر چالیس میں دو برس کی ایک اونٹنی ہے، اور ہر پچاس میں تین برس کی ایک اونٹنی ہے۔ اگر اونٹوں کی عمروں میں اختلاف ہو ۱؎ (مثلاً) جس شخص پر چار برس کی اونٹنی کی زکاۃ ہو اور اس کے پاس چار برس کی اونٹنی نہ ہو تین برس کی اونٹنی ہو تو اس سے تین برس کی اونٹنی ہی قبول کر لی جائے گی، اور وہ اس کے ساتھ میں دو بکریاں بھی دیدے۔ اگر وہ اسے میسر ہوں ورنہ بیس درہم دے۔ اور جسے زکاۃ میں تین برس کی اونٹنی دینی ہو۔ اور اس کے پاس چار برس کی اونٹنی ہو تو اس سے وہی قبول کر لی جائے گی، اور عامل صدقہ اسے بیس درہم دے یا دو بکریاں واپس دیدے، اور جسے تین برس کی اونٹنی دینی ہو اور یہ اس کے پاس نہ ہو اور اس کے پاس دو برس کی اونٹنی ہو تو وہی اس سے قبول کر لی جائے اور اس کے ساتھ دو بکریاں دے اگر میسر ہوں یا بیس درہم دے، اور جسے زکاۃ میں دو سال کی اونٹنی دینی ہو اور اس کے پاس صرف تین سال کی اونٹنی ہو تو وہی اس سے قبول کر لی جائے گی اور عامل زکاۃ اسے بیس درہم یا دو بکریاں واپس دے، اور جسے دو برس کی اونٹنی دینی ہو، اور اس کے پاس دو برس کی اونٹنی نہ ہو صرف ایک برس کی اونٹنی ہو تو وہی اس سے قبول کر لی جائے اور دو بکریاں دے اگر بکریاں اسے میسر ہوں بیس درہم دے۔ اور جسے ایک برس کی اونٹنی دینی ہو اور اس کے پاس ایک برس کی اونٹنی نہ ہو۔ دو برس کا (نر) کا اونٹ ہو، تو وہی اس سے قبول کر لیا جائے۔ اس کے ساتھ کوئی اور چیز لی نہ جائے، اور جس کے پاس صرف چار اونٹ ہوں تو ان میں زکاۃ نہیں ہے الا یہ کہ ان کا مالک اپنی خوشی سے کچھ دینا چاہے تو دے سکتا ہے، اور جنگل میں چرنے والی بکریوں میں جب چالیس ہوں تو ایک سو بیس تک میں ایک بکری زکاۃ ہے، اور ایک سو بیس سے جو ایک بکری بھی بڑھ جائے تو دو سو بکریوں تک میں دو بکریاں ہیں۔ اور دو سو سے ایک بکری بھی بڑھ جائے تو دو سو سے تین سو تک میں تین بکریاں ہیں، اور جب تین سو سے بھی بڑھ جائیں تو پھر ہر سو میں ایک بکری زکاۃ ہے۔ زکاۃ میں بوڑھے کانے اور عیب دار جانور نہیں لیے جائیں گے، اور نہ نر جانور لیا جائے گا الا یہ کہ صدقہ وصول کرنے والا کسی ضرورت و مصلحت سے لینا چاہے۔ زکاۃ کے ڈر سے دو جدا مال یکجا نہ کئے جائیں، اور نہ یکجا مال کو جدا جدا کیا جائے۔ اور جب آدمی کی جنگل میں چرنے والی بکریاں چالیس سے ایک بھی کم ہوں تو ان میں کوئی زکاۃ نہیں ہے، ہاں ان کا مالک اپنی خوشی سے کچھ دینا چاہے تو دے سکتا ہے، چاندی میں چالیسواں حصہ زکاۃ ہے اور اگر مال ایک سو نوے درہم ہی ہو تو ان میں کوئی زکاۃ نہیں ہے۔ ہاں مالک اپنی خوشی سے کچھ دینا چاہے تو دے سکتا ہے۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ سے روایت ہے کہ حضرت ابوبکر رضی اللہ عنہ نے انھیں لکھا کہ یہ وہ مقررہ صدقات ہیں جو رسول اللہ صلی اللہ علیہ وسلم نے مسلمانوں پر لاگو فرمائے ہیں اور جن کا اللہ تعالیٰ نے اپنے رسول صلی اللہ علیہ وسلم کو حکم دیا ہے۔ جس مسلمان سے زکاۃ صحیح حساب سے طلب کی جائے تو وہ ضرور دے اور جس سے زائد مانگی جائے تو وہ نہ دے۔ پچیس سے کم اونٹوں میں زکاۃ ہر پانچ اونٹوں میں ایک بکری ہوگی۔ جب اونٹ پچیس ہو جائیں تو پینتیس تک ان میں بنت مخاض زکاۃ آئے گی۔ اگر بنت مخاض میسر نہ ہو تو مذکر ابن لبون دیا جائے۔ جب اونٹ چھتیس ہو جائیں تو پینتالیس تک بنت لبون زکاۃ آئے گی۔ جب چھیالیس ہو جائیں تو ساٹھ تک ایک حقہ زکاۃ ہوگی جو نر کے قابل ہو۔ جب اکسٹھ ہو جائیں تو پچھتّر تک جذعہ زکاۃ ہوگی۔ جب چھہتر ہو جائیں تو نوے تک دو بنت لبون زکاۃ آئے گی۔ اور جب اکانوے ہو جائیں تو ایک سو بیس تک دو حقے زکاۃ ہوگی جو نر کے قابل ہوں۔ جب اونٹ ایک سو بیس سے بڑھ جائیں تو ہر چالیس میں بنت لبون اور ہر پچاس میں حقہ زکاۃ ہوگی۔ اور جب اونٹوں کی عمریں مختلف ہوں (مقررہ عمر کے اونٹ نہ مل سکیں تو جس شخص کے ذمے جذعہ زکاۃ بنتی ہے لیکن اس کے پاس جذعہ نہ ہو بلکہ حقہ ہو تو اس سے حقہ ہی لی جائے گی۔ اور وہ اس کے ساتھ دو بکریاں بھی دے گا، اگر اسے میسر ہوں، ورنہ بیس درہم دے گا۔ اور جس شخص کے ذمے حقہ زکاۃ بنتی ہے مگر اس کے پاس جذعہ ہی ہے تو اس سے جذعہ ہی لی جائے گی اور صدقہ وصول کرنے والا اسے بیس درہم یا دو بکریاں واپس کرے گا۔ اور جس شخص کے ذمے حقہ زکاۃ بنتی ہو مگر اس کے پاس حقہ نہ ہو بلکہ بنت لبون ہو تو وہی لی جائے گی اور اس کے ساتھ وہ دو بکریاں دے گا، اگر اسے میسر ہوں، ورنہ بیس درہم دے گا۔ اور جس شخص کے ذمے بنت لبون بنتی ہو مگر اس کے پاس حقہ ہی ہو تو اس سے وہی لی جائے گی اور صدقہ وصول کرنے والا اسے بیس درہم یا دو بکریاں دے گا۔ اور جس شخص کے ذمے بنت لبون زکاۃ بنتی ہو، لیکن اس کے پاس بنت لبون نہ ہو بلکہ بنت مخاض ہو تو اس سے وہی لے لی جائے گی اور اس کے ساتھ وہ دو بکریاں دے گا، اگر اسے میسر ہوں، ورنہ بیس درہم دے گا۔ اور جس شخص کے ذمے بنت مخاض زکاۃ بنتی ہو لیکن اس کے پاس مذکر ابن لبون ہی ہو تو وہی اس سے لیا جائے گا، البتہ اس کے ساتھ اسے کچھ نہ ملے گا۔ اور جس آدمی کے پاس صرف چار اونٹ ہوں تو ان میں کوئی زکاۃ نہیں مگر یہ کہ مالک خود دینا چاہے۔ اور بکریوں کی زکاۃ جب وہ جنگل میں چرنے والی ہوں اور چالیس ہوں تو ایک سو بیس تک ان میں ایک بکری ہوگی۔ اگر ایک بھی زائد ہو جائے تو دو سو تک دو بکریاں ہوں گی۔ جب ایک بھی بڑھ جائے تو تین سو تک تین بکریاں ہوں گی۔ جب ایک بھی زیادہ ہو جائے تو ہر سو میں ایک بکری ہوگی۔ زکاۃ میں بوڑھا یا کانا (عیب والا(جانور نہ لیا جائے گا۔ اور مذکر بکرا بھی نہیں لیا جائے گا مگر یہ کہ صدقہ وصول کرنے والا لینا چاہے۔ علیحدہ علیحدہ رہنے والے جانو روں کو زکاۃ کے ڈر سے اکٹھا نہیں کیا جائے گا اور اکٹھے رہنے والے جانوروں کو الگ الگ نہیں کیا جائے گا۔ اور جو زکاۃ دو شریک مالکوں سے وصول کی جائے گی، وہ اپنے اپنے جانوروں کے لحاظ سے تقسیم کر لیں گے۔ اور جب چرنے والی بکریاں چالیس سے ایک بھی کم ہوں تو ان میں کوئی زکاۃ نہیں مگر یہ کہ مالک خود دینا چاہے۔ اور چاندی میں چالیسواں حصہ زکاۃ ہے۔ اگر رقم صرف ایک سو نوے درہم ہو تو اس میں کوئی زکاۃ نہیں مگر یہ کہ مالک خود دینا چاہے۔","f2":"تصیلی موباحث کے لیے دیکھیے فوائد حدیث: ۲۴۴۹۔"}],[2456,"ابوذر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص اونٹ گائے اور بکریاں رکھتا ہو اور ان کی زکاۃ نہ دے تو وہ دنیا میں جیسے تھے اس سے بڑے اور موٹے تازے ہو کر آئیں گے، اور وہ اسے اپنی سینگوں سے ماریں گے، اور اپنی کھروں سے روندیں گے، جب آخری جانور مار چکے گا تو پھر پہلا جانور لوٹا دیا جائے گا، اور یہ سلسلہ جاری رہے گا یہاں تک کہ لوگوں کے درمیان فیصلہ کر دیا جائے\"۔","الألباني: صحيح",{"u2":"حضرت ابوذر رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو بھی اونٹوں، گایوں یا بکریوں کا مالک ان کی زکاۃ ادا نہیں کرے گا تو قیامت کے دن وہ جانور اس جسامت اور موٹاپے سے بڑھ کر آئیں گے جو (دنیا میں تھی۔ اپنے سینگوں سے اسے ٹکریں ماریں گے اور اپنے کھروں سے اسے روندیں گے۔ جب ان میں سے آخری گزر جائے گا تو پہلے کو دوبارہ لایا جائے گا۔ اور اس کے ساتھ یہی سلوک ہوتا رہے گا حتیٰ کہ لوگوں کے درمیان فیصلہ کر دیا جائے۔‘‘"}],[2457,"سوید بن غفلہ رحمہ اللہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کا محصل (زکاۃ) ہمارے پاس آیا، میں آ کر اس کے پاس بیٹھا تو میں نے اسے کہتے ہوئے سنا کہ میرے عہد و قرار میں یہ بات شامل ہے کہ ہم دودھ پلانے والے جانور نہ لیں۔ اور نہ الگ الگ مال کو یکجا کریں، اور نہ یکجا مال کو الگ الگ کریں۔ پھر ان کے پاس ایک آدمی اونچی کوہان کی ایک اونٹنی لے کر آیا، اور کہنے لگا: اسے لے لو، تو اس نے انکار کیا ۱؎۔\n§وضاحت\n۱؎: کیونکہ محصل زکاۃ کو بہترین مال لینے سے منع کیا گیا ہے، اسے درمیانی مال میں سے لینا چاہیئے۔","الألباني: حسن صحيح",{"u2":"حضرت سوید بن غفلہ رضی اللہ عنہ نے فرمایا: ہمارے پاس نبی صلی اللہ علیہ وسلم کی طرف سے زکاۃ وصول کرنے والا شخص آیا۔ میں اس کے پاس آیا اور بیٹھا۔ میں نے اسے یہ کہتے ہوئے سنا کہ مجھ سے یہ عہد لیا گیا ہے کہ ہم دودھ پیتا بچہ یا دودھ والا جانور زکاۃ میں نہیں لیں گے اور علیحدہ علیحدہ جانوروں کو اکٹھا نہیں کریں گے اور اکٹھے جانوروں کو علیحدہ علیحدہ نہیں کریں گے۔ ایک شخص ان کے پاس اونچی کوہان والی (بہترین اونٹنی لایا اور کہنے لگا: یہ زکاۃ میں لے لو۔ اس نے انکار کر دیا۔","f2":"(۱ مذکورہ روایت کو محقق کتاب نے سنداً ضعیف قرار دیا ہے اور مزید لکھا ہے کہ اس کے شواہد ہیں، تاہم شواہد پر صحت اور ضعف کا حکم نہیں لگایا جبکہ دیگر محققین میں سے بعض نے اس روایت کو حسن کہا ہے اور بعض نے صحیح اور اس کے متابعات اور شواہد ذکر کیے ہیں جس سے معلوم ہوتا ہے کہ مذکورہ روایت سنداً ضعیف ہونے کے باوجود قابل عمل اور قابل حجت ہے۔ تفصیل کے لیے دیکھیے (ذخیرۃ العقبیٰ شرح سنن النسائی: ۲۲/ ۱۲۵- ۱۲۷، والموسوعۃ الحدیثیۃ مسند الامام احمد: ۳۱/ ۱۳۲، ۱۳۳، وصحیح سنن ابی داؤد (مفصل للالبانی، رقم: ۱۴۰۹ (۲ زکاۃ میں درمیانہ جانور لیا جائے گا تاکہ مالک کا نقصان ہو نہ فقراء کا۔ دودھ پیتا بچہ فقراء کے لیے نقصان دہ ہے اور دودھ دینے والا جانور دینا مالک کے لیے نقصان دہ ہے۔ بعض اہل علم نے یہ معنی کیے ہیں کہ ہم اس جانور کی زکاۃ نہیں لیں گے جو دودھ کے لیے رکھا گیا ہو کیونکہ ایسا جانور چرنے والا نہیں ہوتا بلکہ اسے خصوصی چارا ڈالا جاتا ہے۔ (۳ علیحدہ جانوروں کو اکٹھا کرنا یا اکٹھے جانوروں کو الگ الگ کرنا جس طرح مالک کے لیے جائز نہیں، اسی طرح زکاۃ وصول کرنے والے کے لیے بھی جائز نہیں، مثلاً: دو بھائیوں کی الگ الگ تیس تیس بکریوں کو ملا کر زکاۃ وصول نہیں کی جائے گی۔ (۴ ’’اس نے انکار کر دیا۔‘‘ کیونکہ ایسی قیمتی چیز زکاۃ میں لینا جائز نہیں۔"}],[2458,"وائل بن حجر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص کو زکاۃ کی وصولی پر بھیجا، وہ ایک شخص کے پاس آیا، اس نے اسے اونٹ کا ایک دبلا بچہ دیا۔ تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"ہم نے اللہ اور اس کے رسول کی طرف سے محصل زکاۃ (صدقہ وصول کرنے والے) کو بھیجا، فلاں شخص نے اسے ایک دبلا کمزور، دودھ چھوڑا ہوا بچہ دیا۔ اے اللہ! تو اس میں اور اس کے اونٹوں میں برکت نہ دے\"، یہ بات اس آدمی کو معلوم ہوئی تو وہ ایک اچھی اونٹنی لے کر آیا، اور کہنے لگا: میں اللہ عزوجل سے توبہ کرتا ہوں اور اللہ کے نبی اکرم صلی اللہ علیہ وسلم کے سامنے اپنی اطاعت کا اظہار کرتا ہوں، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اے اللہ! تو اس میں اور اس کے اونٹوں میں برکت فرما\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت وائل بن حجر رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے ایک شخص کو زکاۃ وصول کرنے کے لیے بھیجا۔ وہ ایک شخص کے پاس آیا تو اس نے اسے ایک کمزور سا اونٹ کا بچہ دیا تو نبی صلی اللہ علیہ وسلم نے فرمایا: ’’ہم نے اللہ اور اس کے رسول کی طرف سے ایک شخص کو صدقہ وصول کرنے کے لیے بھیجا لیکن فلاں شخص نے اسے یہ کمزور سا اونٹ کا بچہ دیا ہے۔ اے اللہ! اس میں اور اس کے اونٹوں میں برکت نہ فرمانا۔‘‘ آپ کی یہ بات اس شخص کو پہنچی تو وہ ایک خوب صورت اونٹنی لے کر آیا اور عرض پرداز ہوا کہ میں اللہ تعالیٰ اور اس کے رسول صلی اللہ علیہ وسلم کے سامنے توبہ کرتا ہوں اور معافی مانگتا ہوں۔ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’اے اللہ! اس میں اور اس کے اونٹوں میں برکت فرما۔‘‘","f2":"محقق کتاب نے مذکورہ روایت کو سفیان ثوری کی وجہ سے سنداً ضعیف قرار دیا ہے کیونکہ سفیان ثوری مدلس ہیں جبکہ دیگر ائمہ ومحققین نے ان کی تدلیس کے باوجود ان کی روایات کو قبول کیا ہے، لہٰذا ان کی تدلیس ضرر رساں نہیں۔ اسی لیے حافظ ابن حجرk نے انھیں طبقات المدلسین، میں، مدلسین کے دوسرے طبقے میں شمار کیا ہے۔ دیکھیے: (طبقات المدلسین، ص: ۲۱، طبعہ دارالبیان بنا بریں دیگر محققین نے اس روایت کو صحیح الاسناد قرار دیا ہے۔ تفصیل کے لیے دیکھیے: (ذخیرۃ العقبیٰ شرح سنن النسائی: ۲۲/ ۱۲۷- ۱۲۹، وصحیح سنن النسائی اللالبانی، رقم: ۲۴۵۷"}],[2459,"عبداللہ بن ابی اوفی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس جب کوئی قوم اپنا صدقہ لے کر آتی تو آپ فرماتے: \"اے اللہ! فلاں کے آل(اولاد) پر رحمت بھیج\" (چنانچہ) جب میرے والد اپنا صدقہ لے کر آپ کے پاس آئے تو آپ نے فرمایا: \"اے اللہ! آل ابی اوفی پر رحمت بھیج\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن ابی اوفی رضی اللہ عنہ بیان کرتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم کے پاس کوئی قوم اپنے مالوں کی زکاۃ لے کر آتی تو آپ فرماتے ہیں: ’’اے اللہ! فلاں کی آل پر رحمت نازل فرما۔‘‘ میرے والد محترم آپ کے پاس اپنی زکاۃ لے کر گئے تو آپ نے فرمایا: ’’اے اللہ! ابو اوفیٰ کے خاندان پر رحمت نازل فرما۔‘‘","f2":"رسول اللہ صلی اللہ علیہ وسلم کی دعا چونکہ موجب رحمت تھی، اس لیے آپ کو خصوصی حکم دیا گیا کہ جب کوئی زکاۃ لے کر آئے تو اس کے لیے رحمت کی دعا فرمائیں۔ اس سے انھیں دلی سکون حاصل ہوگا۔ اور اللہ کی رحمت مستزاد ہوگی۔ آج کل یہ فریضہ حکام کے بجائے علماء پر لاگو ہوتا ہے کیونکہ حکومت زکاۃ وصول نہیں کرتی۔ ویسے بھی [اِنَّ الْعُلَمَائَ وَرَثَۃُ الْأَنْبِیَائِ] ’’علماء انبیاء کے وارث ہیں۔‘‘ (صحیح البخاری، العلم (معلقاً باب: ۱۰، وسنن ابی داود، العلم، حدیث: ۳۶۴۱"}],[2460,"جریر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس کچھ دیہات کے لوگ آئے، اور انہوں آپ سے عرض کیا: آپ کے بھیجے ہوئے کچھ محصل زکاۃ ہمارے پاس آتے ہیں جو ہم پر ظلم کرتے ہیں، تو آپ نے فرمایا: \"اپنے زکاۃ وصول کرنے والوں کو راضی و مطمئن کرو\"، انہوں نے عرض کیا: اگرچہ وہ ظلم کریں۔ آپ نے فرمایا: \"اپنے زکاۃ وصول کرنے والوں کو راضی کرو\"، انہوں نے پھر عرض کیا: اگرچہ وہ ظلم کریں؟ آپ نے فرمایا: \"اپنے زکاۃ وصول کرنے والوں کو راضی کرو\"۔ جریر رضی اللہ عنہ کہتے ہیں: جب سے میں نے رسول اللہ صلی اللہ علیہ وسلم سے یہ بات سنی اسی وقت سے کوئی محصل زکاۃ میرے پاس سے راضی ہوئے بغیر نہیں گیا۔","الألباني: صحيح",{"u2":"حضرت جریر رضی اللہ عنہ سے روایت ہے کہ کچھ اعرابی رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور کہنے لگے: اے اللہ کے رسول! آپ کی طرف سے زکاۃ وصول کرنے والے لوگ ہمارے پاس آتے ہیں اور وہ ظلم کرتے ہیں۔ آپ نے فرمایا: ’’صدقہ وصول کرنے والوں کو راضی کرو۔‘‘ انھوں نے کہا: اگرچہ وہ ظلم کرے؟ آپ نے فرمایا: ’’صدقہ وصول کرنے والوں کو راضی کرو۔‘‘ وہ پھر کہنے لگے: اگرچہ وہ ظلم کرے؟ آپ نے فرمایا: ’’صدقہ وصول کرنے والوں کو راضی کرو۔‘‘ حضرت جریر رضی اللہ عنہ نے کہا: جب سے میں نے رسول اللہ صلی اللہ علیہ وسلم سے یہ بات سنی تو میرے پاس سے کوئی صدقہ وصول کرنے والا شخص ناراض ہو کر نہیں گیا، بلکہ خوش خوش گیا۔","f2":"عام لوگ زکاۃ کی مقدار کی تفصیلات سے آگاہ نہیں ہوتے، اس لیے وہ سمجھتے ہیں کہ زکاۃ وصول کرنے والا زیادہ لے رہا ہے۔ ویسے بھی زکاۃ دیتے وقت یہ احساس غالب رہتا ہے، س لیے آپ نے زکاۃ کے تعین کا اختیار عوام الناس کو نہیں دیا بلکہ وصول کرنے والوں کو یہ اختیار دیا کیونکہ وہ زکاۃ کی تفصیلات سے بخوبی واقف ہوتے ہیں۔ لوگوں کو حکم دیا گیا کہ ان کے مطالبے کے مطابق انھیں زکاۃ ادا کریں۔ اگر کوئی شکایت ہو تو حاکم بالا کے پاس جائیں اور فیصلہ حاصل کریں۔ لیکن اگر ہر آدمی کو مزاحمت کا اختیار دے دیا جائے تو انتظامی افراتفری پھیل جائے گی اور ملک ابتری کا شکار ہو جائے گا۔ اس حدیث کا یہ مطلب نہیں کہ زکاۃ وصول کرنے والوں کے من مانی کی اجازت ہے۔"}],[2461,"جریر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب صدقہ وصول کرنے والا تمہارے پاس آئے تو وہ اس حال میں لوٹے کہ وہ تم سے راضی ہو\"۔","الألباني: صحيح",{"u2":"حضرت جریر رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب زکاۃ وصول کرنے والا (سرکاری آدمی تمہارے پاس زکاۃ لینے کے لیے آئے تو وہ تم سے خوش خوش واپس جائے۔‘‘"}],[2462,"مسلم بن ثفنہ کہتے ہیں کہ ابن علقمہ نے میرے والد کو اپنی قوم کی عرافت (نگرانی) پر مقرر کیا، اور انہیں اس بات کا حکم بھی دیا کہ وہ ان سے زکاۃ وصول کر کے لائیں۔ تو میرے والد نے مجھے ان کے کچھ لوگوں کے پاس بھیجا کہ میں ان سے زکاۃ لے کر آ جاؤں۔ تو میں (گھر سے) نکلا یہاں تک کہ ایک بوڑھے بزرگ کے پاس پہنچا انہیں «سعر» کہا جاتا تھا۔ تو میں نے ان سے کہا کہ میرے والد نے مجھے آپ کے پاس آپ کی بکریوں کی زکاۃ لانے کے لیے بھیجا ہے۔ انہوں نے کہا: بھتیجے! تم کس طرح کی زکاۃ لیتے ہو؟ میں نے کہا: ہم چنتے اور چھانٹتے ہیں یہاں تک کہ ہم بکریوں کے تھنوں کو ناپتے و ٹٹولتے ہیں (یعنی عمدہ مال ڈھونڈ کر لیتے ہیں)۔ انہوں نے کہا: بھتیجے! میں تمہیں ایک حدیث سناتا ہوں۔ میں رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں انہیں گھاٹیوں میں سے کسی ایک گھاٹی میں اپنی بکریوں کے ساتھ تھا، میرے پاس ایک اونٹ پر سوار دو شخص آئے، اور انہوں نے کہا کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے فرستادہ ہیں۔ ہم آپ کے پاس آئے ہیں کہ آپ ہمیں اپنی بکریوں کی زکاۃ ادا کریں۔ میں نے پوچھا: میرے اوپر ان بکریوں میں کتنی زکاۃ ہے؟ تو ان دونوں نے کہا: ایک بکری، میں نے دودھ اور چربی سے بھری ایک ایک موٹی تازی بکری کا قصد کیا جس کی جگہ مجھے معلوم تھی۔ میں اسے (ریوڑ میں سے) نکال کر ان کے پاس لایا تو انہوں نے کہا: «شافع» ہے :(«شافع» گابھن بکری کو کہتے ہیں) اور رسول اللہ صلی اللہ علیہ وسلم نے ہمیں گابھن جانور لینے سے روکا ہے۔ پھر میں نے ایک اور بکری لا کر پیش کرنے کا ارادہ کیا جو اس سے کمتر تھی جس نے ابھی کوئی بچہ نہیں جنا تھا لیکن حمل کے قابل ہو گئی تھی۔ میں نے اسے (گلّے سے) نکال کر ان دونوں کو پیش کیا، انہوں نے کہا: ہاں یہ ہمیں قبول ہے۔ پھر ہم نے اسے اٹھا کر انہیں پکڑا دیا۔ انہوں نے اسے اپنے ساتھ اونٹ پر لاد لیا، پھر لے کر چلے گئے۔","الألباني: ضعيف",{"u2":"حضرت مسلم بن ثفنہ بیان کرتے ہیں کہ ابن علقمہ (حاکم نے میرے والد کو ان کی قوم کا نمبردار (یا سردار بنایا اور انھیں حکم دیا کہ وہ اپنی قوم سے زکاۃ وصول کریں۔ تو میرے والد نے مجھے ایک قبیلے کی طرف بھیجا تاکہ میں ان کی زکاۃ لے کر آؤں۔ میں گیا حتیٰ کہ ایک بزرگ کے پاس پہنچا جنھیں حضرت سعر کہا جاتا تھا۔ میں نے کہا: مجھے والد محترم نے تمھاری طرف بھیجا ہے تاکہ آپ اپنی بکریوں کی زکاۃ ادا کر دیں۔ وہ فرمانے لگے: اے بھتیجے! تم کس قسم کی بکریاں لیتے ہو؟ میں نے کہا: ہم چن کر لیتے ہیں حتیٰ کہ ان کے تھن بالشت کے ساتھ ماپ کر دیکھتے ہیں۔ وہ فرمانے لگے: اے بھیجتے! میں تجھے بتاتا ہوں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے دور مبارک میں ان وادیوں میں سے کسی وادی میں رہتا تھا۔ میرے پاس بکریاں ہوتی تھیں۔ میرے پاس دو آدمی اونٹ پر سوار ہو کر آئے اور کہنے لگے: ہم آپ کی طرف رسول اللہ صلی اللہ علیہ وسلم کے قاصد ہیں تاکہ آپ اپنی بکریوں کی زکاۃ ادا کریں۔ میں نے کہا: مجھ پر ان بکریوں میں کتنی زکاۃ ہے؟ انھوں نے کہا: ایک بکری۔ ایک ایسی بکری جس کی قدر ومنزلت میں جانتا تھا، میں نے وہ خالص دودھ اور چربی سے بھری ہوئی (بہترین موٹی تازی دودھ والی بکری پکڑی اور ان کے پاس لے آیا۔ وہ کہنے لگے: یہ تو بچے والی ہے اور ہمیں رسول اللہ صلی اللہ علیہ وسلم نے بچے والی بکری لینے سے منع کیا ہے۔ میں ایک سال بھر عمر کی گابھن بکری، جس نے بچہ نہیں جنا تھا جو کہ جننے کے قریب تھی، کہ (ریوڑ سے نکال کر ان کے پاس لایا تو وہ کہنے لگے: یہ ٹھیک ہے۔ ہمیں پکڑا دو۔ انھوں نے اسے اپنے ساتھ اونٹ پر لادا اور چلے گئے۔"}],[2463,"مسلم بن ثفنہ کا بیان ہے کہ ابن علقمہ نے ان کے والد کو اپنی قوم سے زکاۃ وصول کرنے کے کام پر لگایا، اور پوری حدیث بیان کی۔","الألباني: ضعيف",{"u2":"حضرت مسلم بن ثفنہ سے روایت ہے کہ ابن علقمہ (حاکم) نے میرے والد محترم کو اپنی قوم کی زکاۃ وصول کرنے کے لیے مقرر فرمایا۔ اور پھر سابقہ روایت بیان فرمائی۔"}],[2464,"ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ عمر رضی اللہ عنہ نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے زکاۃ کا حکم کیا۔ تو آپ سے کہا گیا: ابن جمیل، خالد بن ولید، اور عباس بن عبدالمطلب (رضی اللہ عنہم) نے (زکاۃ) نہیں دی ہے، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ابن جمیل زکاۃ کا انکار اس وجہ سے کرتا ہے کہ وہ محتاج تھا تو اللہ تعالی نے اسے مالدار بنا دیا۔ اور رہے خالد بن ولید تو تم لوگ خالد پر زیادتی کر رہے ہو، انہوں نے اپنی زرہیں اور اسباب اللہ کی راہ میں وقف کر دی ہیں، اور رہے رسول اللہ صلی اللہ علیہ وسلم کے چچا عباس بن عبدالمطلب، تو یہ زکاۃ تو ان پر ہے ہی۔ مزید اتنا اور بھی دیں گے\" ۱؎۔\n§وضاحت\n۱؎: مسلم کی روایت کے الفاظ ہیں «فَھِیَ عَلَیَّ» اس کا مفہوم یہ ہے کہ رہے عباس رضی اللہ عنہ تو ان کی زکاۃ میرے ذمہ ہے اور اسی کے مثل اور، یعنی میں ان سے دو سال کی زکاۃ پہلے ہی لے چکا ہوں اس لیے اس کی ادائیگی میں کروں گا۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، حضرت عمر رضی اللہ عنہ نے فرمایا: ’’رسول اللہ صلی اللہ علیہ وسلم نے زکاۃ کی ادائیگی کا حکم دیا۔ آپ سے کہا گیا کہ ابن جمیل، حضرت خالد بن ولید اور حضرت عباس بن عبدالمطلب نے زکاۃ نہیں دی۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ابن جمیل تو اس لیے ناراض ہے کہ وہ فقیر تھا، اللہ تعالیٰ نے اسے مال دار بنا دیا۔ رہا خالد بن ولید تو تم خالد پر ظلم کرتے ہو۔ انھوں نے تو اپنی زر ہیں اور دوسرا جنگی ساز وسامان اللہ تعالیٰ کے راستے میں وقف کر رکھا ہے۔ باقی رہے رسول اللہ صلی اللہ علیہ وسلم کے چچا حضرت عباس بن عبدالمطلب تو ان کی زکاۃ رسول اللہ صلی اللہ علیہ وسلم کے ذمے ہے بلکہ اس کے ساتھ اتنی اور ہے۔‘‘","f2":"(۱) ’’ابن جمیل‘‘ یہ منافق شخض تھا۔ زکاۃ کو تاوان سمجھتا تھا، اس لیے آپ نے اس کے متعلق یہ الفاظ فرمائے۔ کہتے ہیں کہ بعد میں اس نے توبہ کر لی تھی۔ (۲)’’وقف کر رکھا ہے۔‘‘ گویا حضرت عمر رضی اللہ عنہ نے ان سے جنگی ساز وسامان کی زکاۃ طلب کی تھی کہ شاید یہ مال تجارت کے لیے ہے، حالانکہ وہ تو فی سبیل اللہ وقف تھا اور وقف مال میں زکاۃ نہیں ہوتی۔ یا نبی اکرم صلی اللہ علیہ وسلم کا مطلب یہ ہے کہ خالد تو اس مخلص ہیں کہ انھوں نے اپنا سارا جنگی سامان وقف کر رکھا ہے، وہ زکاۃ سے انکار کیسے کر سکتے ہیں؟ یہ مطلب بھی تو ہو سکتا ہے کہ انھوں نے زکاۃ کی رقم سے جنگی سامان خرید کر وقف کر دیا ہے، لہٰذا ان سے زکاۃ نہ مانگی جائے۔ (۳)بعض دوسری روایات سے یہ بات معلوم ہوتی ہے کہ حضرت عباس رضی اللہ عنہ سے رسول اللہ صلی اللہ علیہ وسلم دو سال کی زکاۃ کسی ملکی ضرورت کی وجہ سے پیشگی وصول کر چکے تھے، لہٰذا یہ صراحت فرمائی ورنہ حضرت عباس رضی اللہ عنہ زکاۃ سے کیسے انکار کر سکتے تھے؟"}],[2465,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے زکاۃ کا حکم دیا، آگے کی اوپر والی روایت کے مثل مروی ہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے صدقے کا حکم دیا۔ سابقہ حدیث کی مانند۔"}],[2466,"عبداللہ بن ہلال ثقفی رحمہ اللہ کہتے ہیں کہ ایک شخص نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، اور اس نے عرض کیا: (لوگ اتنے جھگڑالو اور نادہند ہو گئے ہیں کہ)قریب ہے کہ میں آپ کے بعد زکاۃ کی بکری کے ایک بچے یا ایک بکری کے لیے قتل کر دیا جاؤں گا، تو آپ نے فرمایا: \"اگر وہ فقراء مہاجرین کو نہ دی جاتی ہوتی تو اسے میں نہ لیتا\"۔","الألباني: ضعيف",{"u2":"حضرت عبداللہ بن ہلال ثقفی رضی اللہ عنہ سے روایت ہے کہ ایک آدمی نبی صلی اللہ علیہ وسلم کے پاس آیا اور کہنے لگا: قریب تھا کہ مجھے آپ کی عدم موجودگی میں زکاۃ کی ایک بکری کی وجہ سے قتل کر دیا جاتا۔ آپ نے فرمایا: ’’اگر فقراء اور مہاجرین (اور دوسرے مستحقین کو زکاۃ نہ دی جاتی (ان لوگوں کو زکاۃ دینے کی مجبوری ن ہوتی تو میں زکاۃ وصول ہی نہ کرتا۔‘‘"}],[2467,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مسلمان پر اس کے غلام اور گھوڑے میں زکاۃ نہیں ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مسلمان پر اس کے (خدمت والے) غلام اور (سواری والے) گھوڑے میں کوئی زکاۃ نہیں۔‘‘","f2":"یہ حدیث اور دوسری احادیث صراحتاً گھوڑوں میں زکاۃ کی نفی کرتی ہیں، لہٰذا صحیح یہی ہے کہ غلام اور گھوڑا اگر خدمت کے لیے ہوں تو ان میں کوئی زکاۃ نہیں۔ تبھی تو ان میں کوئی نصاب بھی مقرر نہیں، نیز جو چیز ذاتی ضروریات کے ضمن میں آتی ہو، اس میں زکاۃ نہ ہونا مسلمہ اصول ہے، مگر احناف نے عمومات یا ضعیف روایت سے استدلال کرتے ہوئے ان صریح احادیث کی نفی کی ہے اور گھوڑے میں (خواہ وہ ایک ہی ہو) زکاۃ ثابت کی ہے جو کسی بھی لحاظ سے مناسب نہیں، البتہ تجارت کے گھوڑے اور غلاموں میں قطعاً زکاۃ ہے کیونکہ وہ تجارتی سامان میں شامل ہیں۔ اسی طرح غلام میں صدقۃ الفطر کا ذکر بھی صحیح روایت میں ہے، الب تہ گھوڑے میں زکاۃ کے علاوہ دوسرے حقوق ہو سکتے ہیں، مثلا: جہاد میں استعمال کرنا، سواری کے لیے عارضی طور پر کسی کو دینا اور جفتی کے لیے چھوڑ دینا وغیرہ۔ دوسری روایات کو انھی حقوق پر محمول کرنا چاہیے۔"}],[2468,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مسلمان پر اس کے غلام اور گھوڑے میں زکاۃ نہیں ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مسلمان آدمی پر اس کے (خدمت والے غلام اور (سواری والے گھوڑے میں کوئی زکاۃ نہیں۔‘‘"}],[2469,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"مسلمان پر اس کے غلام میں اور اس کے گھوڑے میں زکاۃ نہیں ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم کی طرف منسوب کرتے ہوئے کہا کہ آپ نے فرمایا: ’’مسلمان پر اس کے غلام اور گھوڑے میں کوئی زکاۃ نہیں۔‘‘"}],[2470,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"آدمی پر اس کے گھوڑے اور اس کے غلام میں زکاۃ نہیں ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’کسی شخص پر اس کے گھوڑے اور غلام میں کوئی زکاۃ نہیں۔‘‘"}],[2471,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مسلمان پر اس کے غلام اور اس کے گھوڑے میں زکاۃ نہیں ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مسلمان پر اس کے (خدمت والے غلام اور (سواری والے گھوڑے میں کوئی زکاۃ نہیں۔‘‘"}],[2472,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"مسلمان پر اس کے غلام میں زکاۃ نہیں ہے اور نہ ہی اس کے گھوڑے میں\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ کا بیان ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’مسلمان پر اس کے غلام اور گھوڑے میں زکاۃ نہیں۔‘‘","f2":"غلام کے بارے میں تو احناف بھی دیگر جمہور اہل علم کے ساتھ متفق ہیں کہ خدمت والے غلام میں زکاۃ نہیں کیونکہ کسی بھی ذاتی ضروریات کی چیز میں زکاۃ نہیں ہے، البتہ تجارت کے لیے رکھے گئے غلاموں میں زکاۃ ہے کیونکہ وہ تجارتی مال ہیں۔ گھوڑے میں بھی یہی ضابطہ لاگو ہوتا ہے، مگر احناف نے بغیر کسی معقول وجہ کے گھوڑے کے حکم بدل دیا ہے۔"}],[2473,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"پانچ اوقیہ سے کم چاندی میں زکاۃ نہیں ہے، اور پانچ اونٹ سے کم میں زکاۃ نہیں ہے۔ اور پانچ وسق غلے سے کم میں زکاۃ نہیں ہے\"۔\n§وضاحت\n۱؎: ایک اوقیہ چالیس درہم کا ہوتا ہے، اس طرح پانچ اوقیہ دو سو درہم ہوا، جو موجودہ وزن کے حساب سے پانچ سو پنچانوے گرام بنتا ہے۔ ۲؎: ایک وسق ساٹھ صاع کا ہوتا ہے، اس طرح پانچ وسق تین سو صاع کے برابر ہوا جو موجودہ وزن کے حساب سے چھ سو ترپن کیلو گرام بنتا ہے۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’پانچ اوقیوں سے کم چاندی میں زکاۃ نہیں۔ نہ پانچ اونٹوں سے کم میں صدقہ ہے۔ اسی طرح پانچ وسق سے کم غلے میں بھی صدقہ (عشر نہیں۔‘‘","f2":"فوائد کے لیے دیکھیے حدیث نمبر2474۔"}],[2474,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"پانچ وسق سے کم کھجور میں زکاۃ نہیں ہے، اور پانچ اوقیہ سے کم چاندی میں زکاۃ نہیں ہے، اور پانچ اونٹ سے کم میں زکاۃ نہیں ہے\"۔","الألباني: صحيح ق وليس عند خ من التمر",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’پانچ وسق سے کم کھجوروں (یا دوسرے غلہ جات میں کوئی صدقہ (عشر نہیں اور نہ پانچ اوقیوں سے کم چاندی میں زکاۃ ہے اور نہ پانچ اونٹوں سے کم میں زکاۃ ہے۔‘‘"}],[2475,"ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"پانچ وسق سے کم کھجور میں زکاۃ نہیں ہے، اور پانچ اوقیہ سے کم چاندی میں زکاۃ نہیں ہے۔ اور نہ پانچ اونٹ سے کم میں زکاۃ ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ کا بیان ہے، انھوں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے سنا: ’’پانچ وسق سے کم کھجوروں میں کوئی صدقہ (عشر نہیں اور نہ پانچ اوقیوں سے کم چاندی میں کوئی زکاۃ ہے۔ اسی طرح پانچ اونٹوں سے کم میں بھی زکاۃ نہیں۔‘‘"}],[2476,"ابوسعید خدری رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"پانچ اوقیہ سے کم چاندی میں زکاۃ نہیں ہے، اور پانچ اونٹ سے کم میں زکاۃ نہیں ہے، اور پانچ وسق سے کم غلے میں زکاۃ نہیں ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوسعید خدری رضی اللہ عنہ نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’پانچ اوقیوں (یعنی (۲۰۰ درہم سے کم چاندی میں زکاۃ نہیں اور نہ پانچ اونٹوں سے کم میں زکاۃ ہے۔ اسی طرح پانچ وسق (یعنی ۱۶ من سے کم غلے میں بھی زکاۃ نہیں۔‘‘","f2":"یہاں بھی امام ابوحنیفہ رحمہ اللہ نے حدیث کے آخری ٹکڑے کو تسلیم نہیں کیا۔ ان کے قول کے مطابق غلہ تھوڑا پیدا ہوا ہو یا زیادہ (حتیٰ کہ ایک صاع بھی ہو تو اس میں بھی عشر لاگو ہوگا، مگر صاف نظر آرہا ہے کہ یہ صریح حدیث کے خلاف ہے، اسی لیے ان کے شاگردان رشید نے بھی ان کی اس رائے کی تائید نہیں کی۔ والحمد للہ علی ذلک"}],[2477,"علی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میں نے گھوڑے اور غلام کی زکاۃ معاف کر دی ہے، تو تم اپنے مالوں کی زکاۃ ہر دو سو میں سے پانچ یعنی چالیسواں حصہ دو\"۔","الألباني: صحيح",{"u2":"حضرت علی رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میں نے گھوڑوں اور غلاموں کی زکاۃ معاف کر دی ہے۔ اب تم اپنے مال (سونا، چاندی اور رقم کی زکاۃ دو سو درہم میں سے پانچ درہم ادا کرو۔‘‘"}],[2478,"علی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میں نے گھوڑے اور غلام کی زکاۃ معاف کر دی ہے، اور دو سو درہم سے کم میں زکاۃ نہیں ہے\"۔","الألباني: صحيح",{"u2":"حضرت علی رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میں نے (سواری کے گھوڑوں اور (خدمت کے غلاموں میں زکاۃ معاف کر دی ہے، نیز دو سو درہم سے کم میں زکاۃ نہیں۔"}],[2479,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما سے روایت ہے کہ یمن کی رہنے والی ایک عورت رسول اللہ صلی اللہ علیہ وسلم کے پاس آئی، اس کے ساتھ اس کی ایک بیٹی تھی جس کے ہاتھ میں سونے کے دو موٹے موٹے کنگن تھے۔ آپ نے فرمایا: \"کیا تم اس کی زکاۃ دیتی ہو؟\" اس نے کہا: نہیں، آپ نے فرمایا: \"کیا تجھے اچھا لگے گا کہ اللہ عزوجل ان کے بدلے قیامت کے دن تمہیں آگ کے دو کنگن پہنائے؟\" یہ سن کر اس عورت نے دونوں کنگن (بچی کے ہاتھ سے) نکال لیے۔ اور انہیں رسول اللہ صلی اللہ علیہ وسلم کے آگے ڈال دیا، اور کہا: یہ اللہ اور اس کے رسول کے لیے ہیں۔","الألباني: حسن",{"u2":"حضرت عمرو بن شعیب کے جدامجد (حضرت عبداللہ بن عمرو بن عاص رضی اللہ عنہ) سے روایت ہے کہ علاقہ یمن کی ایک عورت اپنی بیٹی سمیت رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوئی۔ اس کی بیٹی کے ہاتھ میں سونے کے دو بھاری کنگن تھے۔ آپ نے فرمایا: ’’تو ان کی زکاۃ دا کرتی ہے؟‘‘ اس نے کہا: نہیں۔ آپ نے فرمایا: ’’کیا تجھے یہ بات پسند ہے کہ قیامت کے دن اللہ عزوجل تجھے (یا تیری بیٹی کو) آگ کے دو کنگن پہنائے؟‘‘ اس عورت نے وہ کنگن فوراً اتار دیے اور رسول اللہ صلی اللہ علیہ وسلم کی طرف پھینک دیے اور کہنے لگی: یہ اللہ تعالیٰ اور اس کے رسول صلی اللہ علیہ وسلم کے لیے ہیں۔","f2":"(۱) حضرت عبداللہ بن عمرو بن عاص رضی اللہ عنہ عمرو بن شعیب کے دادا نہیں بلکہ پردادا ہیں۔ (۲) ’’یہ اللہ اور اس کے رسول صلی اللہ علیہ وسلم کے لیے ہیں۔‘‘ یعنی یہ بیت المال کے ہیں، اللہ اور اس کے رسول صلی اللہ علیہ وسلم کے دین اور مرضی کی راہ میں ہیں تاکہ صحیح مصرف میں صرف کر دیے جائیں۔ اللہ تعالیٰ اور رسول اللہ صلی اللہ علیہ وسلم کا ذکر دیناً اور تبرکاً ہے۔ آپ بیت المال کے والی تھے، اس لیے آپ کا ذکر کیا ورنہ زکاۃ اور صدقہ آپ نے نہ صرف اپنے لیے بلکہ پورے خاندان کے لیے حرام کر رکھا تھا… صلی اللہ علیہ وسلم … (۳) کیا زیورات میں زکاۃ ہے؟ اس بارے میں علماء کے دو مشہور قول ہیں، بعض علماء کا کہنا ہے کہ زیورات میں زکاۃ نہیں اور بعض کا قول یہ ہے کہ زیورات میں زکاۃ واجب ہے دونوں اقوال میں سے دوسرا قول دلائل کے لحاظ سے زیادہ قوی ہے اور اس کی تائید چند صحیح روایات سے بھی ہوتی ہے، لہٰذا درست موقف یہی ہے کہ وہ زیورات جو زکاۃ کے نصاب کو پہنچیں ان کی زکاۃ ادا کی جائے گی۔ تفصیل کے لیے دیکھیے: (ذخیرۃ العقبیٰ شرح سنن النسائی: ۲۲/ ۱۷۹-۱۸۱) سونے کا نصاب ۲۰ دینار ہے جیسا کہ مرفوع روایت میں ہے۔ اس دور میں ۲۰ دینار ۲۰۰ درہم کے برابر تھے۔ آج کل سونے چاندی کے بھاؤ میں یہ تناسب نہیں رہا۔ ۲۰ دینار کا وزن تقریباً ساڑھے سات تو لے بنتا ہے۔ اس کی قیمت چاندی کے نصاب سے بہت زیادہ ہے، اس لیے بعض محققین نے سونے میں بھی چاندی کے نصاب ہی کو معتبر سمجھا ہے، یعنی ۲۰۰ درہم یا ساڑھے باون تولے چاندی کے برابر سونا ہو تو اس میں زکاۃ ہوگی، مگر یہ موقف مرجوح ہے۔ جمہور نے اسے قبول نہیں کیا۔ واللہ اعلم۔ البتہ ان کے برعکس عصر حاضر کے بعض علماء نے کرنسی کے نصاب میں ساڑھے باون تولے چاندی کی قیمت کے بجائے ساڑھے سات تولے سونے کی قیمت کو نصاف بنانے کی رائے ظاہر کی ہے۔ یہ رائے قابل غور ہو سکتی ہے لیکن اس سے زکاۃ کا اصل مقصد فوت ہو جائے گا۔ زکاۃ کا مقصد تو غرباء ومساکین کی امداد اور جہاد اور مجاہدین کی ضروریات کا پورا کرنا ہے۔ سونے کے نصاب کو کرنسی کی زکاۃ کا نصاب مقرر کرنے سے لاکھوں اصحاب حیثیت زکاۃ سے مستثنیٰ قرار پا جائیں گے، جس کا نقصان دینی اداروں اور معاشرے کے ضرورت مندوں کو ہوگا۔"}],[2480,"عمرو بن شعیب کہتے ہیں کہ ایک عورت رسول اللہ صلی اللہ علیہ وسلم کے پاس آئی اور اس کے ساتھ اس کی ایک بچی تھی اور اس کی بچی کے ہاتھ میں دو کنگن تھے، آگے اسی طرح کی روایت ہے جیسے اوپر گزری ہے۔ اور یہ روایت مرسل ہے۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: خالد معتمر سے زیادہ ثقہ راوی ہیں (اس لیے ان کی متصل روایت معتمر کی مرسل سے زیادہ صحیح ہے)۔","الألباني: حسن لغيره",{"u2":"حضرت عمرو بن شعیب بیان کرتے ہیں کہ ایک عورت رسول اللہ صلی اللہ علیہ وسلم کے پاس آئی۔ اس کے ساتھ اس کی ایک بیٹی بھی تھی جس کے ہاتھ میں دو کنگن تھے۔ آگے پوری روایت مذکورہ بالا کی مانند۔ یہ روایت مرسل، یعنی منقطع ہے (کیونکہ عمرو بن شعیب واقعہ کے عینی شاہد نہیں)۔\nامام ابوعبدالرحمن (نسائی) رحمہ اللہ بیان فرماتے ہیں: (سابقہ حدیث: ۲۴۸۱ کا راوی) خالد (اس حدیث: ۲۴۸۲ کے راوی) معتمر سے زیادہ ثقہ ہے۔","f2":"خالد کی روایت متصل ہے جبکہ معتمر کی روایت منقطع ہے کیونکہ عمرو بن شعیب صحابی ہیں نہ تابعی بلکہ نچلے طبقے کے راوی ہیں، تاہم یہ روایت بھی سابقہ حدیث کی وجہ سے حسن درجے کی ہے۔"}],[2481,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص اپنے مال کی زکاۃ نہیں دیتا ہے، اسے قیامت کے دن اس کا مال ایسے خوفناک سانپ کی صورت میں نظر آئے گا جو گنجا ہو گا، اس کی آنکھوں پر دو سیاہ نقطے ہوں گے، وہ اس سے چمٹ جائے گا، یا اس کے گلے کا ہار بن جائے گا، اور کہے گا: میں تیرا خزانہ ہوں، میں تیرا خزانہ ہوں\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص اپنے مال (سونا، چاندی اور رقم کی زکاۃ ادا نہیں کرتا، قیامت کے دن اس کے مال کو اس کے سامنے گنجے سانپ کی صورت میں لایا جائے گا جس کی آنکھوں پر دو سیاہ نقطے ہوں گے۔ وہ اسے چمٹ جائے گا یا اس کے گلے کا طوق بن جائے گا اور کہے گا: میں تیرا خزانہ ہوں۔ میں تیرا خزانہ ہوں۔‘‘"}],[2482,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس شخص کو اللہ تعالی مال دے اور وہ اس مال کی زکاۃ ادا نہ کرے، تو قیامت کے دن اس کا مال گنجا سانپ بن جائے گا، اس کی آنکھ کے اوپر دو سیاہ نقطے ہوں گے، وہ قیامت کے دن اس کے دونوں کلّے پکڑے گا، اور اس سے کہے گا: میں تیرا مال ہوں، میں تیرا خزانہ ہوں\"۔ پھر آپ نے آیت کریمہ کی تلاوت کی: «ولا يحسبن الذين يبخلون بما آتاهم اللہ من فضله» \"اللہ تعالی نے جنہیں مال دیا ہے وہ بخیلی کر کے یہ نہ سمجھیں کہ یہ ان کے لیے بہتر ہے بلکہ وہی مال قیامت کے دن ان کے گلے کا طوق ہو گا\" (آل عمران: ۱۸۰)۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص کو اللہ تعالیٰ مال عطا فرمائے، پھر وہ اس کی زکاۃ نہ دے تو قیامت کے دن اس کے مال کو اس کے سامنے گنجے سانپ کی صورت دی جائے گی جس کی آنکھوں پر دو سیاہ نقطے ہوں گے۔ وہ اس شخص کے منہ کے دونوں کناروں کو پکڑ لے گا اور کہے گا: میں تیرا مال ہوں۔ میں تیرا خزانہ ہوں، پھر آپ صلی اللہ علیہ وسلم نے یہ آیت تلاوت فرمائی: {وَ لَا یَحْسَبَنَّ الَّذِیْنَ یَبْخَلُوْنَ بِمَآ اٰتٰہُمُ اللّٰہُ مِنْ فَضْلِہٖ} (آل عمران: ۱۸۰ ’’جو لوگ اس مال میں بخل کرتے ہیں جو ان کو اللہ تعالیٰ نے اپنے فضل وکرم سے عطا فرمایا ہے (وہ اس (بخل کو اپنے لیے ہرگز بہتر نہ سمجھیں بلکہ وہ ان کے لیے برا ہے اور قیامت کے دن وہ مال ان کے گلے کا طوق بنا دیا جائے گا۔‘‘","f2":"اس قسم کا سانپ بہت زہریلا ہوتا ہے اور اس کا ڈسا ہوا بچتا نہیں۔ ڈراؤنا بھی بہت ہوتا ہے۔ مزید دیکھیے، حدیث: ۲۴۳۳، ۲۴۵۰۔"}],[2483,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"پانچ وسق سے کم غلے یا کھجور میں زکاۃ نہیں ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’پانچ وسق سے کم کسی بھی غلے میں یا کھجور میں زکاۃ نہیں۔‘‘","f2":"فوائد کے لیے دیکھیے، حدیث: ۲۴۷۸ اور ۲۴۸۰۔"}],[2484,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"گیہوں اور کھجور میں زکاۃ نہیں یہاں تک کہ وہ پانچ وسق کو پہنچ جائے، اسی طرح چاندی میں زکاۃ نہیں یہاں تک کہ وہ پانچ اوقیہ کو پہنچ جائے۔ اور اونٹ میں زکاۃ نہیں ہے یہاں تک کہ وہ پانچ کی تعداد کو پہنچ جائیں\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’گندم اور کھجور میں زکاۃ (عشر واجب نہیں ہوتی حتیٰ کہ وہ پانچ وسق ہو جائیں۔ اور چاندی میں زکاۃ واجب نہیں ہوتی حتیٰ کہ وہ پانچ اوقیے (دو سو درہم ہو جائیں۔ اور اونٹوں میں زکاۃ واجب نہیں ہوتی حتیٰ کہ وہ پانچ ہو جائیں۔‘‘","f2":"یعنی مذکورہ مقادیر یا ان سے زائد میں زکاۃ واجب ہوگی، ان سے کم میں نہیں۔ اس سے زیادہ صریح روایت کیا ہوگی؟ مگر احناف پھر بھی غلے اور کھجور کے قلیل وکثیر میں زکاۃ کے وجوب کے قائل ہیں۔ وہ اس حدیث کے معنی کرتے ہیں کہ حکومت نہیں لے گی۔ (یعنی قلیل میں البتہ مالک خود فقراء کو ادا کریں۔ مگر باقی دو، یعنی اونٹوں اور چاندی میں وہ اس مفہوم کے قائل نہیں، لہٰذا یہ مسلک درست نہیں۔ اور یوں زکاۃ کی ادائیگی کی دو شکلیں اختراع کرنا شریعت نہیں، بلکہ ایجاد بندہ ہے۔"}],[2485,"ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"غلہ میں زکاۃ نہیں ہے اور نہ کھجور میں یہاں تک کہ یہ پانچ وسق ہو جائیں، اور نہ پانچ اونٹ سے کم میں زکاۃ ہے، اور نہ پانچ اوقیہ سے کم چاندی میں زکاۃ ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوسعید خدری رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’کسی دانے (غلے اور کھجور میں زکاۃ نہیں حتیٰ کہ وہ پانچ وسق ہو جائیں۔ اور پانچ اونٹوں سے کم میں اور پانچ اوقیوں سے کم چاندی میں بھی زکاۃ نہیں۔‘‘","f2":"مذکورہ مقادیر کی تفصیل کے لیے دیکھیے حدیث: ۲۴۴۷۔"}],[2486,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"پانچ اوقیہ سے کم چاندی میں زکاۃ نہیں ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’پانچ اوقیوں سے کم (چاندی میں زکاۃ نہیں۔‘‘"}],[2487,"ابو سعید خدری رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"پانچ اوقیہ سے کم (چاندی) میں زکاۃ نہیں، اور نہ پانچ اونٹ سے کم میں زکاۃ ہے، اور نہ پانچ وسق سے کم غلہ میں زکاۃ ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ سے مروی ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’پانچ اوقیوں (۲۰۰ درہم سے کم چاندی میں زکاۃ نہیں، نہ پانچ اونٹوں سے کم میں زکاۃ ہے اور نہ پانچ وسق سے کم غلے میں زکاۃ ہے۔‘‘"}],[2488,"عبداللہ بن عمر رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جسے نہر اور چشمے سینچیں یا جس زمین میں تری رہتی ہو ۱؎ اس میں دسواں حصہ زکاۃ ہے۔ اور جو اونٹوں سے سینچا جائے یا ڈول سے اس میں بیسواں حصہ ہے\"۔\n§وضاحت\n۱؎: یعنی اسے سینچنے کی ضرورت نہ پڑتی ہو۔","الألباني: صحيح",{"u2":"حضرت سالم اپنے والد (حضرت عبداللہ بن عمر رضی اللہ عنہ سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس فصل کو بارش، نہریں یا چشمے سیراب کریں یا وہ نمی والی ہو، اس میں دسواں حصہ زکاۃ واجب ہے۔ اور جس فصل کو اونٹوں اور ڈول (راہٹ وغیرہ کے ذریعے سے سیراب کیا جائے، اس میں بیسواں حصہ زکاۃ واجب ہے۔","f2":"(۱ اس سے ماقبل احادیث میں عشر والی فصل کا نصاب بیان کیا گیا تھا کہ کتنی فصل میں زکاۃ آئے گی؟ اس حدیث میں اس کی مقدار بیان کی گئی ہے کہ کتنی زکاۃ آئے گی؟ (۲ باقی تمام چیزوں میں زکاۃ سال کے بعد واجب ہوتی ہے، مثلاً: جانور، سونا، چاندی، رقم اور سامان تجارت، مگر غلہ اور پھلوں، یعنی فصل کی زکاۃ اس کی پیداوار کے موقع پر ہوتی ہے، اس کے لیے ایک سال کی قید نہیں۔ عموماً ہر فصل سال میں ایک دفعہ ہی ہوتی ہے، س لیے گویا اس میں بھی زکاۃ سال بعد ہی ہوئی، البتہ ادائیگی فصل کی کٹائی کے موقع ہی پر واجب ہوتی ہے۔ (۳ جانوروں کی زکاۃ مخصوص ہے جو تفصیل سے پیچھے بیان ہوئی سونا، چاندی، رقم اور سامان تجارت کی زکاۃ کل مالیت کا چالیسواں حصہ ہوتی ہے لیکن فصل کی زکاۃ دسواں اور بیسواں حصہ ہوتی ہے اور اسے عموماً عشر کہا جاتا ہے۔ (۴ فصل کی زکاۃ پانی کے لحاظ سے ہے۔ چونکہ فصل پانی کے بغیر نہیں ہوتی، لہٰذا پانی کا لحاظ ناگزیر تھا۔ اس سلسلے میں ضابطہ یہ ہے کہ جس پانی کے مہیا کرنے میں کوئی مشقت نہ ہو اور نہ اخراجات کرنے پڑتے ہوں، اس سے سیراب ہونے والی فصل کا دسواں حصہ (عشر بطور زکاۃ دینا ہوگا، مثلاً: بارش، دریاؤں، اور چشموں کا پانی اپنے آپ نظام کائنات کے تحت فصل تک پہنچتا ہے، صرف پانی کو روکنا، موڑنا اور کھولنا ہی پڑتا ہے اور یہ کوئی مشقت نہیں، کوئی زیادہ اخراجات بھی نہیں آتے، لہٰزا اس میں زکاۃ کی مقدار زیادہ رکھی گئی۔ اور جس پانی کے مہیا کرنے میں زیادہ مشقت ہو یا اخراجات کرنے پڑتے ہوں، اس سے سیراب ہونے والی فصل میں بیسواں حصہ (نصف عشر زکاۃ لاگو ہوگی، مثلاً: کنویں سے پانی نکالنا بہت مشقت کا کام ہے، خواہ ڈول کے ذریعے سے نکالا جائے یا جانور کے ذریعے سے یا ٹیوب ویلوں کے ذریعے سے۔ اسی طرح اگر پانی دور سے مشکیزوں یا برتنوں میں لا کر فصل سیراب کرنی پڑے تو بھی بہت مشقت ہے، نیز اس میں اخراجات بھی کرنے پڑتے ہیں اور جانوروں کو استعمال کرنا پڑتا ہے، لہٰذا ان میں زکاۃ کی مقدار کم رکھی گئی ہے۔ (۵ بعض علاقوں میں نہری پانی ہوتا ہے، اپنے آپ پہنچتا ہے مگر آبیانہ دینا پڑتا ہے۔ اسی طرح اگر نہری پانی کے ساتھ ساتھ ٹیوب ویل کا پانی بھی لگانا پڑتا ہو جس میں بہت اخراجات آتے ہیں یا فصل صرف ٹیوب ویل کے ذریعے سے سیراب ہوتی ہو تو ان صورتوں میں بیسواں حصہ زکاۃ ہوگی۔ ٹیوب ویل، کنویں اور رہٹ کے حکم میں ہے۔ (۶ زکاۃ کس فصل میں ہے؟ یہ کافی اختلافی مسئلہ ہے، البتہ غلہ جات پر عشر متفقہ ہے۔ امام مالکk نے ہر اس فصل پر زکاۃ واجب کی ہے جو خوراک ہو اور اسے ذخیرہ کیا جا سکے۔ احناف نے ماپی اور تولی جانے والی چیز میں زکاۃ واجب کی ہے بشرطیکہ اسے ذخیرہ کیا جا سکے، خوراک ہونا ضروری نہیں۔ جمہور اہل علم نے ذخیرہ ہو سکنے کو شرط مانا ہے۔ باقی رہے وہ پھل اور سبزیاں جو ذخیرہ نہیں ہو سکتے، جمہور کے نزدیک ان میں عشر نہیں، البتہ جن پھلوں کو کسی طریقے سے محفوظ رکھا جا سکتا ہے، ان میں عشر ہے، مثلاً: انگور کو منقیٰ کی صورت میں محفوظ کیا جا سکتا ہے۔ خوبانیوں کو بھی خشک کیا جا سکتا ہے۔ کماد کو چونکہ چینی شکر اور گڑ کی صورت میں محفوظ کیا جا سکتا ہے، لہٰذا اس پر بھی عشر ہے۔ کپاس بھی قابل ذخیرہ چیز ہے، لہٰذا اس میں بھی عشر ہے، البتہ اس کے نصاب میں اختلاف ہے۔ اجتہاد کے ذریعے سے اس کے قلیل وکثیر میں فرق کیا جا سکتا ہے۔ چارہ وغیرہ جو جانوروں کے لیے کاشت کیا جاتا ہے، عشر سے مستثنیٰ ہے کیونکہ یہ وقتی ضرورت کے لیے ہے۔ (۷ اس روایت کے ظاہر سے استدلال کرتے ہوئے امام ابوحنیفہ رحمہ اللہ نے کہا ہے کہ زمین کی ہر قلیل اور کثیر پیداوار میں عشر ہے، مگر نصاب کے بارے میں صریح روایات اس استدلال کے خلاف ہیں۔ یہ بحث پیچھے گزر چکی ہے۔ جب باقی چیزوں، مثلاً: سونے، چاندی اور جانوروں وغیرہ میں نصاب معتبر ہے تو کیا وجہ ہے کہ فصل میں نصاب معتبر نہ ہو؟"}],[2489,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو پیداوار آسمان کی بارش اور نہروں کے پانی سے ہو اس میں دسواں حصہ زکاۃ ہے، اور جو پیداوار جانوروں کے ذریعہ سینچائی کر کے ہو اس میں بیسواں حصہ ہے\"۔","الألباني: صحيح",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس فصل کو بارش، نہریں اور چشمے سیراب کریں، اس میں دسواں حصہ زکاۃ ہے۔ اور جس فصل کو اونٹوں کے ذریعے سے سیراب کیا جائے، س میں بیسواں حصہ ہے۔‘‘"}],[2490,"معاذ بن جبل رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے یمن بھیجا تو مجھے حکم دیا کہ جسے آسمان کے پانی نے سینچا ہو اس میں دسواں حصہ زکاۃ لوں، اور جو پیداوار ڈولوں کے پانی سے (سینچائی کر کے) ہو اس میں بیسواں حصہ زکاۃ لوں۔","الألباني: حسن صحيح",{"u2":"حضرت معاذ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے یمن کی طرف (حاکم بنا کر بھیجا تو مجھے حکم دیا کہ میں بارش سے سیراب ہونے والی فصل میں سے دسواں حصہ اور ڈول وراہٹ کے ذریعے سے سیراب ہونے والی فصل سے بیسواں حصہ زکاۃ وصول کروں۔"}],[2491,"سہل بن ابی حثمہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم درختوں پر پھلوں کا تخمینہ لگاؤ تو جو تخمینہ لگاؤ اسے لو، اور اس میں سے ایک تہائی چھوڑ دو ۱؎ اور اگر تم نہ لے سکو یا تہائی نہ چھوڑ سکو (شعبہ کو شک ہو گیا ہے) تو تم چوتھائی چھوڑ دو\"۔\n§وضاحت\n۱؎: یعنی اس کی زکاۃ نہ لو تاکہ اسے دوستوں اور ہمسایوں پر خرچ کرنے میں کوئی تنگی محسوس نہ ہو۔","الألباني: ضعيف",{"u2":"حضرت عبدالرحمن بن مسعود بن نیار سے روایت ہے کہ حضرت سہل بن ابی حثمہ رضی اللہ عنہ ہمارے پاس بازار میں تشریف لائے اور کہنے لگے: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: ’’جب تم (عشر وصول کرتے وقت فصل یا پھل کا اندازہ لگاؤ تو اندازے میں سے تیسرا حصہ چھوڑ دو۔ اگر تیسرا حصہ نہ چھوڑو تو چوتھا حصہ ضرور چھوڑ دو۔‘‘","f2":"(۱ حکومت جن فصلوں یا پھلوں کا عشر وصول کرتی تھی، ان میں طریقہ کار یہ تھا کہ فصل یا پھل پکنے سے پہلے سمجھ دار ماہر لوگ اندازہ لگانے کے لیے بھیجے جاتے جو یہ اندازہ لگاتے کہ فلاں آدمی کی فصل یا پھل اتنا ہونے کی توقع ہے۔ اسے ’’خرص‘‘ کہا جاتا تھا۔ (۲ خرص کا فائدہ یہ ہوتا تھا کہ پھل یا فصل پکنے کے بعد مالک کھانے کھلانے میں آزاد ہوتا تھا۔ جو چاہے کھائے، دوسروں کو کھلائے۔ حکومت کٹائی کے موقع پر اندازے (خرص کے مطابق عشر وصول کر لیتی تھی۔ اس طریقے سے نہ مالک کو تنگی ہوتی تھی اور نہ حکومت کو اعتراض کا موقع ملتا تھا۔ (۳ احناف خرص کے قائل نہیں کہ پتا نہیں اندازہ صحیح ہو یا نہ ہو۔ اس طرح کسی پر ظلم بھی ہو سکتا ہے، لہٰذا یہ سود والی علت کی بنا پر منع ہے، مگر وہ یہ بات نظر انداز کر گئے کہ اس میں فریقین کا فائدہ ہے۔ باقی رہا ظلم کا امکان تو اس کا حل رسول اللہ صلی اللہ علیہ وسلم نے اگلے الفاظ میں خود ہی تجویز فرما دیا ہے کہ اندازہ لگانے کے بعد تیسرے یا چوتھے حصے کی رعایت دی جاے، نیز خود رسول اللہ صلی اللہ علیہ وسلم اپنی حیات طیبہ میں اور خلفائے راشدین اپنے اپنے ادوار مبارکہ میں اور عام صحابہ کرام اس پر عمل کرتے رہے ہیں۔ اگر یہ سود یا جوئے کے مشابہ ہوتا تو رسول اللہ صلی اللہ علیہ وسلم اس قسم کا اقدام نہ فرماتے، اور نہ اس کی اجازت ہی مرحمت فرماتے۔ کیا مانعین رسول اللہ صلی اللہ علیہ وسلم اور صحابہ کرامe سے زیادہ دین کے خیر خواہ یا ان سے زیادہ علم والے ہیں؟ دراصل شریعت لوگوں کی تنگی کا بھی لحاظ رکھتی ہے، جیسے بلی کے جوٹھے کا پلید نہ ہونا اس کی واضح دلیل ہے۔ (۴ ’’تیسرا حصہ چھوڑ دو۔‘‘ کیونکہ ضروری نہیں اندازے کے مطابق ہی پیداوار ہو۔ جانور کھا جاتے ہیں، ناگہانی آفات سے فصل اور پھل کا نقصان ہو سکتا ہے، لوگ اور سائلین بھی کمی کا موجب بن سکتے ہیں، اس لیے مالک کو رعایت چاہیے۔ چونکہ حالات مختلف ہوتے ہیں، لہٰذا تیسرے یا چوتھے حصے یا ان کے مابین کمی کا اختیار دیا تاکہ کسی پر زیادی نہ ہو۔ اگر زیادہ نقصان ہو جائے تو اس سے زیادہ بھی رعایت دینی پڑے گی۔"}],[2492,"ابن شہاب زہری کہتے ہیں کہ ابوامامہ بن سہیل بن حنیف رضی اللہ عنہ نے اللہ عز و جل کے فرمان: «ولا تيمموا الخبيث منه تنفقون» \"اللہ کی راہ میں برا مال خرچ کرنے کا قصد نہ کرو\" (البقرہ: ۲۶۷) کے متعلق مجھ سے بیان کیا کہ «خبيث» سے مراد «جعرور» اور «لون حبیق» ہیں، رسول اللہ صلی اللہ علیہ وسلم نے زکاۃ میں خراب مال لینے سے منع فرما دیا ہے۔\n§وضاحت\n۱؎: «جعرور» اور «لون حبیق» دونوں کھجور کی گھٹیا قسموں کے نام ہیں۔","الألباني: صحيح",{"u2":"حضرت ابو امامہ بن سہل بن حنیف اللہ تعالیٰ کے فرمان: {وَلَا تَیَمَّمُوا الْخَبِیْثَ مِنْہُ تُنْفِقُوْنَ} ’’تم (اللہ تعالیٰ کے راستے میں) خرچ کرتے وقت ردی چیز نہ دیا کرو۔‘‘ کے بارے میں فرماتے ہیں کہ اس کا مصداق جعرور اور لون جبیق کھجوریں ہیں۔ رسول اللہ صلی اللہ علیہ وسلم نے زکاۃ میں ردی اور ناقص مال وصول کرنے سے منع فرمایا ہے۔","f2":"جعرور اور لون جبیق کھجوروں کی ردی قسمیں ہیں۔ چھوٹی چھوٹی کھجوریں ہوتی تھیں جن کی کوئی وقعت نہ تھی، البتہ یاد ہے کہ اگر پیداوار ہی اس قسم کی ہے تو ظاہر ہے کہ زکاۃ میں بھی وہی دی جائیں گی۔ حدیث کا مطلب یہ ہے کہ اگر پیداوار میں اچھی قسم کی یا ملی جلی کھجوریں ہوں تو زکاۃ میں ردی کھجوریں نہ لی جائیں جیسی پیداوار ہو، اس کے مطابق ہی زکاۃ چاہیے تاکہ بیت المال کا نقصان ہو، نہ مالک کا۔"}],[2493,"عوف بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نکلے اور آپ کے ہاتھ میں ایک چھڑی تھی (مسجد میں پہنچے) وہاں ایک شخص نے سوکھی خراب کھجور کا ایک گچھا لٹکا رکھا تھا ۱؎ آپ اس گچھے میں (لاٹھی سے) کوچتے جاتے تھے، اور فرماتے جاتے تھے: \"یہ صدقہ دینے والا اگر چاہتا تو اس سے اچھی کھجوریں دے سکتا تھا، یہ صدقہ دینے والا قیامت میں اسی طرح کی سوکھی خراب کھجوریں کھائے گا\"۔\n§وضاحت\n۱؎: کیونکہ دستور تھا کہ لوگ مسجد نبوی میں محتاجوں اور ضرورت مندوں کے کھانے کے لیے کھجوریں لٹکا دیا کرتے تھے۔","الألباني: حسن",{"u2":"حضرت عوف بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ ایک دفعہ رسول اللہ صلی اللہ علیہ وسلم تشریف لائے، آپ کے ہاتھ میں عصا تھا۔ کوئی شخص (مسجد میں بطور صدقہ) ردی قسم کی کھجور کا ایک خوشہ لٹکا گیا تھا۔ آپ اس خوشے پر اپنی لاٹھی مارنے لگے اور فرمایا: ’’اگر اس صدقے والا چاہتا تو اس سے اچھی کھجور کا صدقہ کر سکتا تھا۔ بلا شبہ اس قسم کا صدقہ کرنے والا قیامت کے دن ردی کھجوریں ہی کھائے گا۔‘‘","f2":"(۱) یہ صدقہ نفل تھا کیونکہ فرض عشر تو حکومتی عمال خود وصول کرتے تھے۔ (۲) ’’ردی کھجوریں ہی کھائے گا۔‘‘ یعنی اسے ردی کھجوروں ہی کا ثواب ملے گا کیونکہ اللہ تعالیٰ سے دھوکا نہیں کیا جا سکتا۔ یا یہ کہ اسے وہاں کھانے کو ردی کھجوریں ہی ملیں۔ دوسرا مفہوم ظاہر الفاظ کے زیادہ قریب ہے۔"}],[2494,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سے راستہ میں پڑی ہوئی چیز کے بارے میں سوال کیا گیا تو آپ نے فرمایا: \"جو چیز چالو راستے میں ملے یا آباد بستی میں، تو سال بھر اسے پہنچواتے رہو، اگر اس کا مالک آ جائے (اور پہچان بتائے) تو اسے دے دو، ورنہ وہ تمہاری ہے، اور جو کسی چالو راستے یا کسی آباد بستی کے علاوہ میں ملے تو اس میں اور جاہلیت کے دفینوں میں پانچواں حصہ ہے\" (یعنی: زکاۃ نکال کر خود استعمال کر لے)۔","الألباني: حسن",{"u2":"حضرت عمرو بن شعیب کے پردادا (حضرت عبداللہ بن عمرو رضی اللہ عنہ) بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سے گری پڑی چیز کے بارے میں پوچھا گیا تو آپ نے فرمایا: ’’جو چیز آمد و رفت والے راستے سے یا آباد بستی سے ملے تو اس کا ایک سال تک اعلان کرو۔ اگر اس کا مالک آجائے تو ٹھیک ہے ورنہ وہ تمہارے لیے جائز ہے۔ اور جو چیز آمد ورفت والے راستے سے یا آباد بستی سے نہ ملے تو ایسی چیز اور مدون خزانہ (ملنے کی صورت) میں پانچواں حصہ ہے۔‘‘","f2":"(۱) اس روایت میں کان (معدنی) کا ذکر نہیں۔ شاید امام نسائی رحمہ اللہ نے کان کو لقطہ کا حکم دیا ہے کیونکہ کان بھی عموماً بے آباد جگہ پر اور راستے سے دور مقامات میں ہوتی ہے۔ اس صورت میں کان سے نکلنے والی معدنیات میں سے پانچواں حصہ بیت المال کا ہوگا، باقی کان دریافت کرنے والے کا ہوگا۔ احناف کا بھی یہی موقف ہے مگر اس کی کوئی صریح دلیل نہیں سوائے قیاس کے۔ لقطہ پر قیاس کیا جائے یا مدفون خزانے پر یا مال غنیمت پر۔ جمہور اہل علم، جیسے مالک، شافعی، احمد اور امام بخاری رحمہم اللہ نے اسے مال تجارت سمجھ کر اس پر چالیسواں حصہ زکاۃ عائد کی ہے۔ مناسب بھی یہی ہے کیونکہ صریح حکم کے بغیر سخت زکاۃ، یعنی پانچواں حصہ مناسب نہیں جیسا کہ احناف کا خیال ہے۔ (۲) آمد ورفت والے راستے سے یا آباد بستی کے لقطہ (گری پڑی چیز جو کسی کو مل جائے) میں مالک کے ملنے کا امکان زیادہ بلکہ یقینی ہوتا ہے، اس لیے اعلان کا حکم دیا اور وہ بھی ایک سال تک کیونکہ سال میں عموماً سفر دوبارہ ہو ہی جاتا ہے۔ غیر آباد راستے یا آبادی سے دور ملنے والی چیز کے مالک کے ملنے کا امکان کم ہوتا ہے، لہٰذا اعلان کی ضرورت محسوس نہ فرمائی، البتہ اس میں حکومت کا حصہ پانچواں رکھ دیا کیونکہ یہ مال اسے بغیر محنت کے ملا ہے۔ امام صاحب نے معدنی کان کو بھی اس پر قیاس کر لیا کہ وہ بھی بغیر محنت کے ملتی ہے، حالانکہ کان دریافت کرنے کے لیے بہت محنت بلکہ اخراجات کرنے پڑتے ہیں اور پھر کان سے معدنیات نکالنے میں بھی بہت محنت اور اخراجات کی ضرورت پڑتی ہے، لہٰذا یہ قیاس مناسب نہیں۔ واللہ اعلم (۳) ’’ورنہ تیرے لیے جائز ہے۔‘‘ احناف نے اسے فقیر کے ساتھ خاص کیا ہے، حالانکہ اگر ایسی بات ہوتی تو رسول اللہ صلی اللہ علیہ وسلم ضرور بیان فرماتے ہیں کیونکہ آپ صلی اللہ علیہ وسلم کا فرمان تو مستقل حجت ہے۔ اس کے لیے صرف یہ امکان کافی نہیں کہ سائل فقیر ہوگا۔ بعض روایات میں آپ نے یہی اجازت حضرت ابی بن کعب رضی اللہ عنہ کو فرمائی تھی، حالانکہ وہ مشہور غنی تھے۔"}],[2495,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جانور کا زخمی کرنا رائیگاں ہے، کنوئیں میں گر کر کوئی مر جائے تو وہ بھی رائیگاں ہے، کان میں کوئی دب کر مر جائے تو وہ بھی رائیگاں ہے ۱؎ اور جاہلیت کے دفینے میں پانچواں حصہ ہے\" ۲؎۔\n§وضاحت\n۱؎: یعنی ان چیزوں کے مالکوں سے دیت نہیں لی جائے گی۔ ۲؎: اور باقی چار حصے پانے والے کے ہیں۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جانور کا کیا ہوا نقصان رائیگاں ہے، کنویں کا نقصان رائیگاں ہے اور معدنی کان کا نقصان بھی رائیگاں ہے۔ اور مدفون خزانے میں پانچواں حصہ ہے۔‘‘","f2":"(۱) عجماء کے معنی ہیں: گونگا۔ چونکہ جانور ہمارے لحاظ سے بے زبان ہیں، لہٰذا انھیں عجماء یا گونگے ہی کہا جاتا ہے۔ جانور مالک سے بھاگ جائے یا چرتے پھرتے کوئی نقصان کر دے، مثلاً کسی کو سینگ مار دے یا ٹانگ لگا دے یا کوئی اس سے گر پڑے اور زخم آجائے تو جانور کے مالک پر کوئی تاوان نہ ڈالا جائے گا کیونکہ جانور ان مسائل میں بے سمجھ ہیں اور مالک پاس نہیں، یا اگر ہو بھی تو اس کا کوئی قصور نہیں، البتہ اگر اس نقصان میں مالک کا کوئی دخل ہو، مثلاً اس نے خود جانور کو کسی کے پیچھے لگایا یا روکنے کی کوشش ہی نہیں کی یا عادی نقصان پہنچانے والا جانور قصداً کھلا چھوڑا (مثلاً: کاٹنے والا کتا یا کوئی درندہ رکھا اور کھلا چھوڑا) تو اس پر نقصان کا تاوان ڈالا جا سکتا ہے ہے۔ اسی طرح اگر جانور رات کو کھلا چھوڑ دے اور وہ کسی کی فصل پر چر جائے یا دن کے وقت اس کی موجودگی میں جانور کسی کی فصل چر جائے تو وہ نقصان بھی جانور کے مالک کے ذمے ہوگا۔ (۲) کان یا کنواں کھودتے وقت یا اس میں کام کرتے وقت کوئی شخص کان یا کنواں گرنے سے زخمی ہو جائے یا مر جائے تو مالک پر کوئی تاوان نہ ہوگا۔ اسی طرح کوئی شخص کان یا کنویں میں گر کر زخمی ہو جائے یا مر جائے تو مالک سے کوئی تاوان وصول نہیں کیا جا سکتا الا یہ کہ اس کا کوئی جرم ثابت ہوا۔ (۳) بعض کا کہنا ہے کہ مدفون خزانہ کسی سرکاری جگہ سے ملے تو بیت المال کو خمس ادا کیا جائے گا، باقی اس کو جسے ملا۔ اگر اپنی ذاتی جگہ سے ملا تو اس میں حکومت کا کوئی حصہ نہیں۔ لیکن راجح یہ ہے کہ جونسی بھی زمین ہو، مدفون خزانہ ملنے پر خمس ادا کیا جائے گا۔ حدیث میں کسی خاص زمین کا تعین نہیں۔ واللہ اعلم"}],[2496,"اس سند سے بھی ابوہریرہ رضی اللہ عنہ کے واسطے سے رسول اللہ صلی اللہ علیہ وسلم سے اسی کے مثل مروی ہے۔","",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے ایسی ہی روایت نقل کی ہے۔"}],[2497,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جانور کا زخمی کرنا رائیگاں ہے، کنویں میں گر کر مر جانا رائیگاں ہے، اور کان میں دب کر مر جانا رائیگاں ہے، اور جاہلیت کے دفینہ میں پانچواں حصہ ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جانور کا لگایا ہوا زخم رائیگاں ہے اور کنویں کی وجہ سے ہونے والا نقصان رائیگاں ہے۔ اور معدنی کان کی وجہ سے ہونے والا نقصان بھی رائیگاں ہے اور مدفون خزانہ (ملنے کی صورت) میں پانچواں حصہ (بیت المال کا) ہے۔‘‘"}],[2498,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کنویں میں گر کر مر جانا لغو و رائیگاں ہے۔ جانور کا زخمی کرنا رائیگاں ہے۔ کان میں دب کر مر جانا رائیگاں ہے، اور جاہلیت کے دفینوں میں پانچواں حصہ ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کنویں کی وجہ سے ہونے والا نقصان رائیگاں ہے، جانور کا لگایا ہوا زخم رائیگاں ہے اور کان (معدنی) کی وجہ سے ہونے والا نقصان بھی رائیگاں ہے، اور مدفون شدہ خزانہ (مل جائے تو اس) میں سے پانچواں حصہ (بیت المال کا) ہوگا۔‘‘"}],[2499,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما کہتے ہیں کہ ہلال رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کے پاس اپنے شہد کا دسواں حصہ لے کر آئے، اور آپ سے درخواست کی کہ آپ اس وادی کو جسے سلبہ کہا جاتا ہے ان کے لیے خاص کر دیں (اس پر کسی اور کا دعوی نہ رہے) تو رسول اللہ صلی اللہ علیہ وسلم نے یہ مذکورہ وادی ان کے لیے مخصوص فرما دی۔ پھر جب عمر بن خطاب رضی اللہ عنہ خلیفہ ہوئے تو سفیان بن وھب نے عمر بن خطاب رضی اللہ عنہ کو لکھا، وہ ان سے پوچھ رہے تھے (کہ یہ وادی ہلال رضی اللہ عنہ کے پاس رہنے دی جائے یا نہیں) تو عمر رضی اللہ عنہ نے جواب لکھا: اگر وہ اپنے شہد کا دسواں حصہ جو وہ رسول اللہ صلی اللہ علیہ وسلم کو دیتے تھے ہمیں دیتے ہیں تو \"سلبہ\" کو انہیں کے پاس رہنے دیں، ورنہ وہ برسات کی مکھیاں ہیں (پھول و پودوں کا رس چوس کر شہد بناتی ہیں) جو چاہے اسے کھائے۔","الألباني: حسن",{"u2":"حضرت عمرو بن شعیب کے پردادا (حضرت عبداللہ بن عمرو رضی اللہ عنہ) بیان کرتے ہیں کہ حضرت بلال رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کے پاس اپنے شہد کی زکاۃ لے کر آئے اور آپ سے عرض کیا کہ آپ (شہد والی) وادی سلبہ ان کے لیے مخصوص فرما دیں۔ رسول اللہ صلی اللہ علیہ وسلم نے وہ وادی ان کے لیے مخصوص فرما دی، پھر جب حضرت عمر بن خطاب رضی اللہ عنہ خلیفہ بنے تو (وہاں کے حاکم) سفیان بن وہب نے حضرت عمر بن خطاب رضی اللہ عنہ سے اس بارے میں دریافت کرنے کے لیے خط لکھا تو حضرت عمر رضی اللہ عنہ نے جواباً لکھا کہ اگر وہ تجھے اپنے شہد کا عشر ادا کرتے رہیں جو رسول اللہ صلی اللہ علیہ وسلم کو ادا کیا کرتے تھے تو وادی سلبہ ان کے لیے مخصوص رکھو ورنہ یہ بارشی مکھی (کا شہد) ہے، جو چاہے اسے کھائے۔","f2":"(۱) شہد میں زکاۃ اختلافی مسئلہ ہے۔ امام ابوحنیفہ، امام احمد بن حنبلL شہد میں عشر کے قائل ہیں کیونکہ اس بارے میں کچھ احادیث منقول ہیں، اگرچہ بعض میں کلام ہے مگر مجموعی طور پر قوی ہو جاتی ہیں، لہٰذا وہ قابل حجت ہیں۔ شیخ البانی رحمہ اللہ وغیرہ نے شہد میں عشر کی روایت کو صحیح قرار دیا ہے۔ مزید تفصیل اور طرق وشواہد کے لیے ملاحظہ فرمائیے: (ارواہ الغلیل، رقم الحدیث: ۸۱۰) امام ابوحنیفہ رحمہ اللہ تو ہر قلیل وکثیر شہد میں عشر کے قائل ہیں۔ لیکن یہ موقف درست نہیں کیونکہ انھی احادیث میں اس کا نصاب بھی دس مشکیزے بتایا گیا ہے۔ اور یہی راجح ہے۔ امام مالک، امام شافعی اور امام بخاری رحمہم اللہ شہد میں عشر کے قائل نہیں کیونکہ ان کے نزدیک مذکورہ روایات ضعیف ہیں، نیز اس باب میں مذکورہ حدیث میں ایک علاقہ حضرت ہلال رضی اللہ عنہ کے لیے مخصوص کرنے کے عوض شہد کا ایک حصہ وصول کرنے کا ذکر ہے۔ جس سے لگتا ہے کہ اگر علاقہ مخصوص نہ کیا جاتا تو عشر کا مطالبہ نہ ہوتا جیسا کہ حضرت عمر رضی اللہ عنہ کے فرمان سے معلوم ہوتا ہے۔ لیکن اس کا جواب یہ ہو سکتا ہے کہ چونکہ علاقہ مخصوص کرنے کی وجہ سے ان کے پاس شہد کی کثیر مقدار جمع ہو جاتی تھی، لہٰذا ان پر زکاۃ واجب تھی جبکہ معمولی مقدار میں شہد حاصل کرنے والے پر زکاۃ (عشر) واجب نہیں، جس طرح دوسری عشری چیزیوں میں ہے۔ بہرحال تجارتی بنیادوں پر شہد کا وسیع کاروبار کرنے والوں پر زکاۃ لاگو ہوگی۔ (۲) ’’بارشی مکھی۔‘‘ کیونکہ بارش کا اس کی افزائش سے گہرا تعلق ہے، اسی لیے بارشی موسم میں مکھی زیادہ ہوتی ہے، یا جن چیزوں پر اس مکھی کا گزارہ ہوتا ہے، وہ بارش ہی سے اگتی اور بڑھتی ہیں۔"}],[2500,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے آزاد، غلام، مرد اور عورت ہر ایک پر رمضان کی زکاۃ (صدقہ فطر) ایک صاع کھجور یا ایک صاع جَو فرض کی ہے، پھر اس کے برابر لوگوں نے نصف صاع گیہوں کو قرار دے لیا ۱؎۔\n§وضاحت\n۱؎: کیونکہ اس وقت :(عہد معاویہ رضی اللہ عنہ میں ) نصف صاع گیہوں قیمت میں جو کے ایک صاع کے برابر ہو گیا تھا۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے رمضان المبارک کا صدقہ (صدقۃ الفطر) ہر آزاد، غلام، مذکر اور مؤنث پر کھجور اور جو کا ایک صاع مقرر فرمایا تھا۔ بعد میں لوگوں نے اس کی جگہ گندم کا نصف صاع ٹھہرا لیا۔","f2":"(۱) اس صدقے کو زکاۃ رمضان اس لیے کہا گیا ہے کہ یہ رمضان المبارک کے روزوں کی وجہ سے واجب ہوتا ہے اور صدقۃ الفطر، اس لیے کہا جاتا ہے کہ اس کی ادائیگی افطار، یعنی رمضان المبارک کے اختتام پر واجب ہوتی ہے، جیسے اس عید کو عید الفطر کہتے ہیں۔ (۲) غلام پر بھی صدقۃ الفطر واجب ہے، البتہ غلام کی طرف سے ادائیگی اس کا مالک کرے گا بشرطیکہ مالک مسلمان ہو۔ اگر مالک ادا نہیں کرتا اور غلام استطاعت رکھتا ہے تو وہ خود ادا کر دے گا۔ اگر مالک کافر ہے اور غلام استطاعت نہیں رکھتا تو پھر اسے معاف ہے کیونکہ {لَا یُکَلِّفُ اللّٰہُ نَفْسًا اِلَّا وُسْعَہَا} (۳) ’’کھجور اور جو کا ایک صاع‘‘ اس دور میں عرب میں عام خوراک یہی دو چیزیں تھیں، لہٰذا ان میں ایک صاع مقرر فرما دیا۔ گندم کا عام رواج نہ تھا، بعد میں رفاہیت کا دور آیا تو لوگوں نے عموماً گندم کھانی شروع کر دی لیکن گندم کھجور اور جو کی نسبت بہت مہنگی تھی، اس لیے قیمت کا حساب لگاتے ہوئے گندم کے نصف صاع کو کھجور اور جو کے ایک صاع کے برابر قرار دیا گیا۔ یہ ایک لحاظ سے گنجائش تھی اور اسے گنجائش ہی سمجھنا چاہیے کیونکہ فی زمانہ ہمارے ہاں گندم کھجور سے کافی سستی ہے، اس لیے اب اس کا ایک صاع نکالنا ہی افضل ہے اور یہ حکمت کے عین موافق بھی ہے۔"}],[2501,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے صدقہ فطر ہر مرد و عورت، آزاد اور غلام پر ایک صاع کھجور یا ایک صاع جَو فرض کیا ہے، پھر لوگوں نے آدھا صاع گیہوں کو اس کے برابر ٹھہرا لیا۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے صدقۃ الفطر ہر مذکر، مونث، آزاد اور غلام پر کھجور یا جو کا ایک صاع مقرر فرمایا ہے۔ بعد میں لوگوں نے گندم کے نصف صاع کو اختیار کر لیا۔","f2":"(۱) صدقۃ الفطر ہر امیر اور غریب پر واجب ہے، جو خود فقیر ونادار ہے وہ اگرچہ لینے کا مستحق ہے لیکن اس کے پاس جو صدقۃ الفطر جمع ہو جائے اس میں سے اپنا صدقہ نکالے، نیز اس کے وجوب کے لیے روزے رکھنا شرط نہیں۔ اگر کسی نے شرعی عذر کی بنا پر روزے نہ رکھے ہوں تو صدقۃ الفطر اس پر بھی واجب ہے حتیٰ کہ نومولود بچے پر بھی اور کھوسٹ بوڑھے پر بھی، مریض پر بھی اور مسافر پر بھی۔ (۲) ایک صاع ۲ کلو ۱۰۰ گرام ہے جسے تقریباً اڑھائی کلو کہتے ہیں۔ تفصیل ان شاء اللہ آگے (حدیث: ۲۵۱۵ کے) فوائد میں آئے گی۔"}],[2502,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے صدقہ فطر ہر چھوٹے، بڑے، آزاد اور غلام اور مرد اور عورت پر ایک صاع کھجور یا ایک صاع جَو مقرر کی ہے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے رمضان کی زکاۃ (صدقۃ الفطر) ہر چھوٹے، بڑے، آزاد، غلام اور مذکر ومونث پر کھجور اور جو کا ایک صاع مقرر فرمایا ہے۔"}],[2503,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے رمضان کا صدقہ فطر مسلمان لوگوں پر ہر آزاد، غلام مرد اور عورت پر ایک صاع کھجور، یا ایک صاع جو فرض ٹھہرایا ہے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے رمضان المبارک کا صدقہ فطر ہر آزاد، غلام، مذکر ومونث مسلمان پر کھجور اور جو سے ایک صاع مقرر فرمایا ہے۔","f2":"(۱) صدقہ فطر ایک عبادت ہے۔ روزوں کی بنا پر واجب ہوتا ہے۔ ادائیگی عید الفطر سے پہلے کی جاتی ہے۔ یہ سب چیزیں مسلمانوں کے ساتھ خاص ہیں، لہٰذا مسلمان ہی پر واجب ہوگا، کسی کافر پر واجب نہ ہوگا۔ من المسلمین کے الفاظ اس کی واضہ دلیل ہیں۔ مگر احناف کے نزدیک کافر غلام پر بھی واجب ہے۔ ان کی دلیل یہ حدیث ہے: [لَیْسَ فِی الْعَبْدِ صَدَقَۃٌ اِلَّا صَدَقَۃَ الْفِطْرِ] ’’مسلمان پر اس کے غلام میں صرف صدقہ فطر ہی واجب ہے۔‘‘ (صحیح مسلم، الزکاۃ، حدیث: ۱۰۹۸۲) حدیث میں ’’عبد‘‘ عام ہے، خواہ مسلم ہو یا کافر، لیکن یہ حدیث عام ہے اس کا مفہوم دوسری صریح حدیث کی روشنی میں متعین ہوگا اور وہ یہی مذکورہ بالا حدیث ہے جس میں یہ وضاحت ہے کہ جن کی طرف سے نکالا جائے وہ مسلم ہو، اور زیر بحث حدیث خاص بھی ہے، اصول ہے کہ عام کو خاص پر محمول کیا جاتا ہے، اس طرح دونوں احادیث کا مفہوم برقرار رہتا ہے اور ان میں تعارض بھی پیدا نہیں ہوتا۔ امام طحاوی اس مذکورہ بالا حدیث کا جواب دیتے ہوئے فرماتے ہیں کہ من المسلمین کی شرط کا تعلق مخرجین، یعنی صدقہ نکالنے والوں کے ساتھ ہے،نہ کہ ان سے جن کی طرف سے صدقہ دیا جاتا ہے، لیکن یہ تاویل بلا دلیل اور دیگر دلائل وروایات کی روشنی میں بے معنی ہے، اس لیے کہ اس حدیث میں غلام کا اور ایک دوسری صحیح حدیث میں بچے کا بھی ذکر آتا ہے کیا یہ بھی مخرجین میں شمار ہوتے ہیں، نیز صحیح مسلم کی حدیث سے واضح ہوتا ہے کہ من المسلمین کی شرط کا تعلق ان لوگوں سے ہے جن کی طرف سے صدقہ فطر نکالا جائے گا۔ [عَلٰی کُلِّ نَفْسٍ مِنَ الْمُسْلِمِیْنَ، حُرٍّ اَوْ عَبْدٍ…] ’’مسلمانوں کے ہر فرد پر (فرض کیا ہے) خواہ وہ آزاد ہو یا غلام۔‘‘ (صحیح مسلم، الزکاۃ، حدیث: ۹۸۴/ ۱۶) جب کافر وجوب کا اہل ہی نہیں تو اس کی طرف سے ادائیگی کیسی؟ (۲) ہر مسلمان کے لفظ سے معلوم ہوتا ہے کہ فقیر اور محتاج بھی صدقہ فطر ادا کرے گا۔ (۳) ’’رمضان کی زکاۃ۔‘‘ ایک دوسری روایت میں رسول اللہ صلی اللہ علیہ وسلم نے صدقۃ الفطر کے دو مقاصد بیان فرمائے ہیں: [طُھْرَۃً لِلصِّیَامِ… وَطُعْمَۃً لِلْمَسَاکِیْن] (سنن ابی داود، الزکاۃ، حدیث: ۱۶۰۹) یعنی یہ ادا شدہ روزوں کو پاکیزہ بنائے گا اور یا وہ گوئی کی آلودگی سے روزے کو صاف کرے گا، نیز مساکین کے لیے کھانے کا انتظام ہو جائے گا، اس لیے صدقۃ الفطر کو روزوں یا رمضان کی زکاۃ کہنا مناسب ہے۔ یہاں زکاۃ کے معنی پاکیزگی ہیں۔ (باقی مباحث کے لیے دیکھیے، حدیث: ۲۵۱۰)"}],[2504,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے زکاۃ فطر مسلمانوں میں سے ہر آزاد، غلام مرد، عورت چھوٹے اور بڑے پر ایک صاع کھجور یا ایک صاع جو فرض کیا ہے، اور حکم دیا ہے کہ اسے لوگوں کے (عید کی) نماز کے لیے (گھر سے) نکلنے سے پہلے ادا کر دیا جائے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے صدقہ فطر ہر چھوٹے، بڑے، مذکر، مونث، آزاد اور غلام مسلمان پر کھجور اور جو سے ایک صاع مقرر فرمایا ہے اور حکم دیا ہے کہ اس کی ادائیگی نماز عید کے لیے جانے سے پہلے کی جائے۔","f2":"(۱) صدقہ فطر کی ادائیگی نماز عید فطر سے قبل واجب ہے نماز کے بعد ادا کیا ہوا صدقہ، صدقہ فطر نہیں ہوگا اور تاخیر کرنے والا شخص اس واجب کی ادائیگی سے محروم رہے گا۔ سنن ابوداؤد میں حدیث ہے کہ جس نے صدقہ فطر عید سے پہلے ادا کیا تو وہ مقبول ہے اور اگر عید کے بعد ادا کیا گیا تو وہ عام صدقات میں سے ایک صدقہ متصور ہوگا۔ دیکھیے (سنن ابی داؤد، الزکاۃ، حدیث: ۱۶۰۹) (۲) صدقۃ الفطر وقت سے پہلے بھی دیا جا سکتا ہے کیونکہ مقصد تو فقیر کی حاجت برآری ہے، خصوصاً اگر صدقۃ الفطر اجتماعی طور پر جمع کر کے تقسیم کرنا مقصود ہو تو لازماً وقت سے پہلے ہی اکٹھا کیا جائے گا۔ اس میں کوئی حرج نہیں۔ بعض صحابہ سے چند دن قبل صدقۃ الفطر جمع کرنے کا ثبوت ملتا ہے۔"}],[2505,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے صدقہ فطر ایک صاع کھجور یا ایک صاع جو، ہر چھوٹے، بڑے، مرد، عورت، آزاد اور غلام پر فرض کیا ہے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے صدقۃ الفطر ہر چھوٹے، بڑے، مذکر، مؤنث، آزاد اور غلام پر کھجور اور جو سے ایک صاع فرض (مقرر) کیا ہے۔","f2":"صدقۃ الفطر کی مقدار کے لیے دیکھیے حدیث: ۲۵۰۲۔"}],[2506,"قیس بن سعد بن عبادہ رضی اللہ عنہما کہتے ہیں کہ ہم عاشورہ کا روزہ رکھتے تھے، اور عید الفطر کا صدقہ ادا کرتے تھے، پھر جب رمضان کے روزے فرض ہوئے، اور زکاۃ کی (فرضیت) اتری، تو نہ ہمیں ان کا حکم دیا گیا نہ ہی ان کے کرنے سے روکا گیا، اور ہم (جیسے کرتے تھے) اسے کرتے رہے۔","الألباني: صحيح",{"u2":"حضرت قیس بن سعد بن عبادہ سے مروی ہے کہ ہم عاشوراء (۱۰ محرم الحرام) کا روزہ رکھتے تھے اور صدقۃ الفطر ادا کیا کرتے تھے۔ جب رمضان المبارک کے روزوں اور زکاۃ کی فرضیت نازل ہوئی تونہ ہمیں اس کا نیا حکم دیا گیا اور نہ اس سے روکا گیا۔ ویسے ہم یہ کام کرتے رہے۔","f2":"اس روایت سے عض حضرات نے استدلال کیا ہے کہ صدقۃ الفطر فرض نہیں رہا، حالانکہ اس قول میں ایسی کوئی صراحت نہیں کیونکہ ایک نئی چیز کی فرضیت سے پرانی چیز کی فرضیت منسوخ نہیں ہو جاتی ہے۔ اور نہ اس کے لیے کسی نئے حکم ہی کی ضرورت ہوتی ہے جبکہ دوسری صریح روایات میں اس کی فرضیت ثابت ہے۔ زکاۃ کی فرضیت تو ۲ ہجری کی ہے۔ بعد میں مسلمان ہونے والے حضرات نے اس کی فرضیت ذکر کی ہے، مثلاً: حضرت ابن عباس رضی اللہ عنہ (دیکھیے، حدیث: ۲۵۱۰، ۲۵۱۷) لہٰذا صدقۃ الفطر زکاۃ کی فرضیت کے باوجود فرض ہے، البتہ احناف نے اسے واجب کہا ہے مگر عملاً واجب اور فرض میں کوئی فرق نہیں ہوتا۔ باقی رہا عاشوراء کا روزہ تو اس کے بارے میں صراحتاً مذکور ہے کہ نبی صلی اللہ علیہ وسلم نے اسے رکھنے نہ رکھنے کا اختیار دے دیا تھا۔"}],[2507,"قیس بن سعد رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں زکاۃ کی فرضیت اترنے سے پہلے صدقہ فطر کا حکم دیا تھا، پھر جب زکاۃ کی فرضیت اتری تو رسول اللہ صلی اللہ علیہ وسلم نے ہمیں نہ کرنے کا حکم دیا اور نہ ہی روکا، اور ہم اسے کرتے رہے۔ ابوعبدالرحمٰن کہتے ہیں: ابوعمار کا نام عریب بن حمید ہے۔ اور عمرو بن شرحبیل کی کنیت ابومیسرہ ہے، اور سلمہ بن کہیل نے اپنی سند میں حکم کی مخالفت کی ہے اور حکم سلمہ بن کہیل سے زیادہ ثقہ راوی ہیں ۱؎۔\n§وضاحت\n۱؎: یعنی: سند میں \"عمرو بن شرحبيل\" ہونا بمقابلہ \"أبي عمار الهمداني\" اثبت ہے، حالانکہ اصل راوی \" عمرو بن شرحبیل بن سعید بن سعد بن عبادہ \" ہونا زیادہ قرین قیاس ہے، کیونکہ حدیث \" قیس بن سعد بن عبادہ\" سے مروی ہے، اور یہ عمرو \"لین الحدیث\" ہیں، اور اگر یہ حدیث \"عمرو بن شرحبیل ابو میسرۃ\" ہی سے مروی ہو تب بھی یہ صحیحین کی حدیث \"فرض صدقۃ الفطر\" کے مخالف ہے، اس لیے شاذ ہے۔","الألباني: صحيح",{"u2":"حضرت قیس بن سعد رضی اللہ عنہ فرماتے ہیں کہ ہمیں رسول اللہ صلی اللہ علیہ وسلم نے صدقۃ الفطر (کی ادائیگی) کا حکم زکاۃ (کی فرضیت) اترنے سے پہلے دیا تھا۔ جب زکاۃ (کی فرضیت) نازل ہوئی تو نہ آپ نے اس کا (نیا) حکم دیا اور نہ اس سے منع فرمایا۔ ہم اس (صدقۂ فطر) کو ادا کرتے رہے۔\nامام ابوعبدالرحمن (نسائی)رحمہ اللہ بیان کرتے ہیں کہ ابو عمار کا نام عریب بن حمید ہے، عمرو بن شرحبیل کی کنیت ابو میسرہ ہے۔ سلمہ بن کہیل نے اس حدیث کی سند کے بیان میں حکم کی مخالفت کی ہے، لیکن حکم سلمہ بن کہیل سے زیادہ ثقہ ہیں۔","f2":"سابقہ روایت میں حضرت حکم نے قاسم بن مخیمرۃ کا استاد عمرو بن شرحبیل بتلایا ہے جبکہ سلمہ بن کہیل نے ابو عمار ہمدانی بتلایا ہے۔"}],[2508,"حسن بصری کہتے ہیں کہ ابن عباس رضی اللہ عنہما نے رمضان کے مہینے کے آخر میں کہا (جب وہ بصرہ کے امیر تھے): تم اپنے روزوں کی زکاۃ نکالو، تو لوگ ایک دوسرے کو تکنے لگے تو انہوں نے پوچھا: مدینہ والوں میں سے یہاں کون کون ہے (جو بھی ہو) اٹھ جاؤ، اور اپنے بھائیوں کو بتاؤ، کیونکہ یہ لوگ نہیں جانتے کہ اس زکاۃ کو رسول اللہ صلی اللہ علیہ وسلم نے ہر مرد، عورت، آزاد اور غلام پر ایک صاع جو یا کھجور، یا آدھا صاع گی ہوں فرض کیا ہے، تو لوگ اٹھے (اور انہوں نے لوگوں کو بتایا)۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: ہشام نے حمید کی مخالفت کی ہے، انہوں نے «عن محمد بن سيرين» کہا ہے۔","الألباني: ضعيف الإسناد",{"u2":"حضرت ابن عباس رضی اللہ عنہ نے، جب وہ بصرہ کے حاکم تھے، ماہ رمضان المبارک کے آخر میں (خطبہ دیا) فرمایا: اپنے روزوں کی زکاۃ (صدقۃ الفطر) نکالو۔ لوگ ایک دوسرے کی طرف دیکھنے لگے۔ آپ نے فرمایا: یہاں جو مدینہ منورہ کے لوگ ہیں اٹھیں اور اپنے (بصری) بھائیوں کو تعلیم دیں کیونکہ وہ نہیں جانتے کہ رسول اللہ صلی اللہ علیہ وسلم نے یہ صدقہ ہر مذکر و مؤنث اور آزاد وغلام پر کھجور اور جو کا ایک صاع اور گندم کا آدھا صاع فرض کیا ہے۔ تولوگ اٹھے۔\nہشام نے حمید کی مخالفت کی ہے، اسے نے (حسن کے بجائے) ابن سیرین کا نام لیا ہے۔","f2":"(۱) مذکورہ روایت کی صحت اور ضعف کی بابت تحقیق حدیث: ۱۵۸۱ کے فوائد میں تفصیل سے گزر چکی ہے۔ جس کا خلاصہ یہ ہے کہ مذکورہ روایت میں بیان کردہ مسئلہ درست اور صحیح ہے۔ (۲) بصرے میں سب لوگ اتنے تعلیم یافتہ نہ تھے جبکہ مدینے کے لوگ عالم تھے کیونکہ مدینہ منورہ علم کا مرکز تھا۔ (۳) حضرت ابن عباس رضی اللہ عنہ حضرت علی رضی اللہ عنہ کے دور خلافت میں بصرے کے حاکم رہے۔ (۴) اس روایت سے ظاہراً یہ معلوم ہوتا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے گندم سے نصف صاع مقرر فرمایا تھا۔ لیکن یہ روایت ضعیف ہے۔ جبکہ بعض دیگر روایات سے تصدیق ہوتی ہے کہ نصف صاع بھی خود رسول اللہ صلی اللہ علیہ وسلم نے مقرر فرمایا تھا۔ یہ صرف سیدنا معاویہ رضی اللہ عنہ ہی کا اجتہاد نہ تھا، نہ یہ کہا جا سکتا ہے کہ عہد نبوی میں گندم کا وجود نہ تھا، نصف صاع گندم کی روایات مجموعی اعتبار سے واقعی قابل استناد ہیں۔ دیکھیے: (الصحیحۃ: ۳/ ۱۷۱) لہٰذا نصف صاع گندم کی ادائیگی بھی درست ہے۔ بہرحال اس سب کے باوجود، خصوصاً ہمارے خطے پاک وہند میں، ایک صاع گندم دینا ہی اولیٰ وافضل ہے کیونکہ اس پر صحابہ کرام رضی اللہ عنہم کا عمل تھا، رسول اللہ صلی اللہ علیہ وسلم کے عہد مبارک میں اور اس کے بعد بھی۔ (واللہ اعلم)"}],[2509,"ابن سیرین کہتے ہیں کہ ابن عباس رضی اللہ عنہما نے صدقہ فطر کا ذکر کیا۔ تو کہا: گیہوں سے ایک صاع، یا کھجور سے ایک صاع، یا جو سے ایک صاع، یا سلت (جَو کی ایک قسم ہے) سے ایک صاع ہے۔","الألباني: شاذ",{"u2":"حضرت ابن عباس رضی اللہ عنہ نے صدقۃ الفطر کا ذکر کرتے ہوئے فرمایا: صدقۃ الفطر گندم، کھجور، جو یا سُلت سے ایک صاع ادا کرو۔","f2":"سُلْت جو کی ایک قسم ہے جو گندم سے قریب تر ہے، اس حدیث میں حضرت ابن عباس رضی اللہ عنہ نے تمام غلہ جات میں صدقہ فطر ایک صاع ہی فرمایا ہے اور یہی افضل ہے۔"}],[2510,"ابورجاء کہتے ہیں کہ میں نے ابن عباس رضی اللہ عنہما کو تمہارے منبر سے یعنی بصرہ کے منبر سے خطبہ دیتے ہوئے سنا، وہ کہہ رہے تھے: صدقہ فطر گی ہوں سے ایک صاع ہے۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: یہ یعنی ایوب تینوں میں زیادہ ثقہ ہیں (یعنی: حسن بصری اور ابن سیرین سے)۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابو رجاء سے روایت ہے انھوں نے کہا: میں نے حضرت ابن عباس رضی اللہ عنہ کو تمہارے، یعنی بصرے کے منبر پر خطبہ ارشاد فرماتے سنا کہ صدقۃ الفطر ہر کھائی جانے والی چیز سے ایک صاع ہے۔\nامام ابوعبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ (اس حدیث کا راوی ایوب) تینوں میں سے زیادہ قوی ہے۔","f2":"یہ روایت تین حضرات نے بیان کی ہے، حمید، ہشام، ایوب۔ حمید نے ابن عباس رضی اللہ عنہ کا شاگرد حسن بتلایا ہے، ہشام نے ابن سیرین اور ایوب نے ابو رجائ۔ امام نسائی رحمہ اللہ ایوب کی روایت کو ترجیح دے رہے ہیں کیونکہ وہ زیادہ ثقہ ہے۔ اس کا مطلب یہ نہیں کہ باقی دو حضرات کی روایات درست نہیں، عجب نہیں تینوں (حسن، ابن سیرین، ابو رجائ) نے حضرت ابن عباس رضی اللہ عنہ کا یہ فرمان سنا اور بیان کیا ہو۔"}],[2511,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے صدقہ فطر جَو یا کھجور یا پنیر سے ایک صاع فرض کیا ہے۔","الألباني: حسن صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے صدقۃ الفطر جو، خشک کھجور یا پنیر سے ایک صاع مقرر فرمایا ہے۔"}],[2512,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب ہمارے درمیان موجود تھے تو ہم صدقہ فطر گی ہوں سے ایک صاع، یا جو سے، یا کھجور سے، یا کشمش سے، یا پنیر سے ایک صاع نکالتے تھے۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ سے مروی ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم ہم میں موجود تھے تو ہم صدقۃ الفطر طعام (گندم یا ہر خوراک والا غلہ) جو، خشک کھجور، کشمش یا پنیر سے ایک صاع دیا کرتے تھے۔","f2":"(۱) لفظ طعام سے مراد گندم بھی ہو سکتی ہے کیونکہ باقی چیزوں کا الگ بیان ہے مگر لغت کے لحاظ سے ہر مطعوم (خوراک والی چیز) کو طعام کہا جا سکتا ہے۔ اور اس میں گندم بھی داخل ہوگی۔ سیدنا ابو سعید خدری رضی اللہ عنہ گندم میں ایک صاع ہی کے قائل تھے، نیز حضرت معاویہ رضی اللہ عنہ کی رائے کہ آدھا صاع گندم بھی دی جا سکتی ہے، وہ سخت مخالف تھے مگر یہ صرف سیدنا معاویہ ہی کی رائے نہ تھی بلکہ بعض دیگر صحابہ کرام رضی اللہ عنہم بھی اس رائے کے حامل تھے، جیسے سیدنا جابر بن عبداللہ رضی اللہ عنہ وغیرہ۔ دیکھیے (سنن الدارقطنی: ۲/ ۳۴۶، والروضہ الندیۃ مع التعلیقات الرضیۃ: ۱/ ۵۴۹) مزید برآں یہ کہ یہ صرف صحابہ کرام رضی اللہ عنہم کی رائے یا ان کا اجتہاد ہی نہ تھا بلکہ رسول اللہ صلی اللہ علیہ وسلم سے اس بارے میں مروی حدیث بھی ہے جیسا کہ حدیث: ۲۵۱۰ کے فوائد میں گزرا۔ ممکن ہے حضرت ابو سعید خدری رضی اللہ عنہ کو وہ حدیث معلوم نہ ہو، اور یہ بعید از قیاس بھی نہیں۔ جس سے ان کے موقف میں مزید سختی پیدا ہوگئی۔ واللہ اعلم (۲) کشمش انگور سے تیار ہوتی ہے۔ چونکہ انگور زیادہ دیر تک رکھا نہیں جا سکتا، لہٰذا صدقۃ الفطر میں انگور دینا درست نہیں بلکہ اسے خشک کر کے کشمش کی صورت میں دیا جائے۔"}],[2513,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب ہم میں تھے تو ہم صدقہ فطر گی ہوں سے، کھجور سے، یا جو سے، یا پنیر سے ایک صاع نکالتے تھے، اور ہم برابر اسی طرح نکالتے رہے۔ یہاں تک کہ معاویہ رضی اللہ عنہ شام سے آئے، اور انہوں نے جو باتیں لوگوں کو بتائیں ان میں ایک بات یہ بھی تھی کہ شامی گی ہوں کے دو مد (مدینہ کے) ایک صاع کے برابر ہیں، تو لوگوں نے اسی کو اختیار کر لیا۔","الألباني: سكت عنه الشيخ",{"u2":"حضرت ابوسعید رضی اللہ عنہ بیان کرتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم ہم میں تشریف فرما تھے تو ہم صدقۃ الفطر طعام، کھجور، جو یا پنیر سے ایک صاع نکالا کرتے تھے۔ ہم اسی طرح نکالتے رہے حتیٰ کہ حضرت معاویہ رضی اللہ عنہ شام سے (مدینہ منورہ) آئے تو جو باتیں انھوں نے لوگوں کو سکھائیں، ان میں سے ایک یہ بھی تھی کہ انھوں نے فرمایا: میں سمجھتا ہوں شامی گندم کے دو مد قیمت میں کھجور وغیرہ کے صاع کے برابر ہیں۔ تو لوگوں نے اس پر عمل شروع کر دیا۔","f2":"صاع چار مد کا ہوتا ہے گویا گندم کا نصف صاع قیمت کے لحاظ سے کھجور وغیرہ کے صاع کے برابر تھا۔ صاع دراصل برتن کی صورت میں ایک پیمانہ ہے، وزن نہیں۔ ظاہر ہے برتن کے اندر ہر جنس برابر وزن کی نہیں ہوتی۔ گندم کا الگ وزن ہوگا، کھجوروں کا الگ، جو کا الگ اور کشمش کا الگ، لہٰذا اصل تو یہی ہے کہ صاع بھر کر غلہ دیا جائے جو بھی ہو، مگر وہ صاع ہر جگہ مہیا نہیں۔ بعض علماء نے حجاز کا پرانا صاع نبوی مہیا ہونے کا دعویٰ کیا ہے۔ اور یہ بھی کہا ہے کہ اس میں تقریباً ڈھائی کلو گندم آتی ہے۔ (مد کا پیمانہ تو میں نے بھی سعیدی خاندان کے ہاں دیکھا ہے) عام طور پر صاع کا جو وزن کتابوں میں مرقوم ہے، وہ بھی کوئی ڈھائی کلو بنتا ہے کیونکہ رطل نوے مثقال کا ہوتا ہے اور ہر مثقال ساڑھے چار ماشے کا، لہٰذا رطل: 405=41/2x90 ماشے کا ہوا۔ اور ایک صاع 5 رطل کا ہوتا ہے، لہٰذا صاع 2150=51/3x405 ماشے کا ہوا جو 180 تولے بنتے ہیں اور ایک تولہ 11.664 گرام کا ہوتا ہے، لہٰذا 2099.52=11.664x180 گرام ہوا، لہٰذا صدقہ فطر میں احتیاطاً ڈھائی کلو غلہ دیا جائے۔ (دیکھئے، حدیث: ۲۴۴۷)"}],[2514,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کے زمانہ میں صدقہ فطر کھجور سے، یا جو سے، یا کشمش سے، یا آٹا یا پنیر سے، یا بے چھلکے والی جو سے ایک صاع ہی نکالا ہے۔ سفیان کو شک ہوا تو انہوں نے «من دقیق أوسلت» شک کے ساتھ روایت کی ہے۔","الألباني: حسن صحيح دون ذكر الدقيق",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے دورِ مبارک میں ہم کھجور، جَو، کشمش، آٹا، پنیر یا سلت وغیرہ سے ایک صاع ہی (صدقۃ الفطر) دیتے تھے، پھر راوی سفیان کو شک ہوا اور انھوں نے کہا: آٹا یا سلت۔","f2":"شیخ البانی رحمہ اللہ کی تحقیق کے مطابق حدیث میں ’’دقیق‘‘ ’’آٹے‘‘ کا ذکر درست نہیں۔ متقدمین اکثر محدثین نے بھی اسے غیر محفوظ قرار دیا ہے۔ دیکھیے (ذخیرۃ العقبی، شرح سنن النسائی: ۲۲/ ۳۰۲۔۳۰۳(باقی ساری حدیث حسن صحیح ہے۔ مزید دیکھیے: (ارواہ الغلیل: ۳/ ۳۳۸) لیکن چونکہ یہ ہماری عام خوراک ہے، نیز حدیث میں گندم کا صریح ذکر بھی آیا ہے، اس لیے اس کا صدقہ فطر میں دینا جائز ہے۔"}],[2515,"حسن (حسن بصری) سے روایت ہے کہ ابن عباس رضی اللہ عنہما نے بصرہ میں خطبہ دیا، تو انہوں نے کہا: تم لوگ اپنے روزوں کی زکاۃ دو (یعنی صدقہ فطر نکالو) تو لوگ ایک دوسرے کو تکنے لگے۔ تو انہوں نے کہا: یہاں اہل مدینہ میں سے کون کون ہیں؟ تم لوگ اٹھو، اور اپنے بھائیوں کے پاس جاؤ، انہیں بتاؤ، کیونکہ وہ لوگ نہیں جانتے کہ رسول اللہ صلی اللہ علیہ وسلم نے صدقہ فطر چھوٹے، بڑے، آزاد اور غلام، مذکر اور مونث پر آدھا صاع گی ہوں، یا ایک صاع کھجور، یا جو فرض کیا ہے۔ حسن کہتے ہیں: علی رضی اللہ عنہ نے کہا: رہی بات جب اللہ نے تمہیں وسعت و فراخی دے رکھی ہو تو تم بھی وسعت و فراخی کا مظاہرہ کرو۔ گیہوں وغیرہ (نصف صاع کے بجائے) ایک صاع دو۔","الألباني: ضعيف الإسناد صحيح المرفوع منه",{"u2":"حضرت حسن بصری سے روایت ہے کہ حضرت ابن عباس رضی اللہ عنہ نے بصرے میں خطبہ ارشاد فرمایا، جس میں کہا: اپنے روزوں کی زکاۃ ادا کرو۔ لوگ (تعجب سے) ایک دوسرے کو دیکھنے لگے تو آپ نے فرمایا: یہاں جو لوگ مدینہ منورہ سے آئے ہوئے ہیں، وہ اپنے (بصری) بھائیوں کی طرف اٹھ کر جائیں اور انھیں تعلیم دیں کیونکہ وہ نہیں جانتے کہ رسول اللہ صلی اللہ علیہ وسلم نے صدقۃ الفطر ہر چھوٹے، بڑے، آزاد، غلام اور مذکر ومؤنث پر گندم کا نصف صاع اور کھجور یا جو کا ایک صاع مقرر فرمایا ہے۔ حضرت حسن بصری نے کہا کہ حضرت علی رضی اللہ عنہ نے فرمایا: جب اللہ تعالیٰ نے تمہیں مال کی وسعت عطا فرمائی ہے تو تم بھی وسعت اختیار کرو، یعنی گندم ہو یا کوئی اور غلہ، سب میں سے پورا صاع ہی دو۔","f2":"فوائد کے لیے دیکھیے حدیث نمبر 2510-"}],[2516,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کے زمانہ میں لوگ صدقہ فطر ایک صاع جَو یا کھجور یا سُلت (بے چھلکے کا جو) یا کشمش نکالتے تھے۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابن عمر رضی اللہ عنہ بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم کے دور مقدس میں لوگ صدقۃ الفطر جو، کھجور، سلت یا کشمش سے ایک صاع دیا کرتے تھے۔"}],[2517,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے زمانہ میں صدقہ فطر ایک صاع جَو یا کھجور یا انگور یا پنیر نکالتے تھے۔ اور ہم برابر ایسا ہی کرتے چلے آ رہے تھے یہاں تک کہ معاویہ رضی اللہ عنہ کا زمانہ آیا۔ تو انہوں نے کہا: میں سمجھتا ہوں کہ شامی گیہوں کے دو مد (یعنی نصف صاع) جو کے ایک صاع کے برابر ہیں۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ہم (صدقۃ الفطر) جو، کھجور، کشمش یا پنیر سے ایک صاع نکالا کرتے تھے۔ اور (بعد میں بھی) ہم اسی طرح نکالتے رہے حتیٰ کہ حضرت معاویہ رضی اللہ عنہ کا دور آگیا تو انھوں نے فرمایا: ’’میں سمجھتا ہوں کہ شام کی گندگی کے دو مد (نصف صاع) جو کے ایک صاع کے برابر ہیں۔","f2":"یہ رائے صرف سیدنا معاویہ رضی اللہ عنہ ہی کی نہ تھی بلکہ کچھ دیگر صحابہ کرام رضی اللہ عنہم بھی اس رائے کے حامل تھے۔ دیکھئے حدیث: ۲۵۱۴ کے فوائد ومسائل۔"}],[2518,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے زمانہ میں (صدقہ فطر) کھجور یا جو یا پنیر سے ایک صاع نکالتے تھے۔ اس کے علاوہ کچھ نہ نکالتے تھے۔","الألباني: حسن",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ فرماتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے دور میں (صدقۃ الفطر) کھجور یا جو یا پنیر سے ایک صاع ہی دیا کرتے تھے۔ ہم ان کے علاوہ اور کوئی چیز نہ دیا کرتے تھے۔","f2":"(۱) حضرت ابو سعید رضی اللہ عنہ ہی کی دوسری روایت میں کشمش اور طعام کا بھی ذکر ہے، بلکہ سلت کا بھی ذکر ہے۔ گندم کا صراحتاً ذکر نہیں الا یہ کہ طعام سے گندم مراد لی جائے۔ (۲) پنیر دودھ کو گرم کر کے تیار کیا جاتا ہے۔ جمہور اہل علم کے نزدیک پنیر بھی ایک صاع دیا جائے گا جبکہ امام ابوحنیفہ رحمہ اللہ کے نزدیک قیمت کے لحاظ سے دیا جائے گا، مگر احادیث میں صراحتاً پنیر کے بھی صاع ہی کا ذکر ہے اور یہی صحیح ہے۔"}],[2519,"سائب بن یزید رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانہ میں ایک صاع تمہارے آج کے مد سے ایک مد اور ایک تہائی مد اور کچھ زائد کا تھا۔ اور ابوعبدالرحمٰن فرماتے ہیں: اس حدیث کو مجھ سے زیاد بن ایوب نے بیان کیا ہے۔\nأَخْبَرَنَا أَحْمَدُ بْنُ سُلَيْمَانَ، قَالَ: حَدَّثَنَا أَبُو نُعَيْمٍ، قَالَ: حَدَّثَنَا سُفْيَانُ، عَنْ حَنْظَلَةَ، عَنْ طَاوُسٍ، عَنِ ابْنِ عُمَرَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: \"الْمِكْيَالُ مِكْيَالُ أَهْلِ الْمَدِينَةِ، وَالْوَزْنُ وَزْنُ أَهْلِ مَكَّةَ\".\n§وضاحت\n۱؎: امام مالک، امام شافعی اور جمہور علماء کے نزدیک ایک صاع پانچ رطل اور تہائی رطل کا ہوتا ہے، اور امام ابوحنیفہ اور صاحبین کے نزدیک ایک صاع آٹھ رطل کا ہوتا ہے، لیکن جب امام ابویوسف کا امام مالک سے مناظرہ ہوا اور امام مالک نے انہیں اہل مدینہ کے وہ صاع دکھلائے جو موروثی طور سے نبی اکرم صلی اللہ علیہ وسلم کے زمانے سے چلے آ رہے تھے تو انہوں نے جمہور کے قول کی طرف رجوع کر لیا۔ اور موجودہ وزن سے ایک صاع لگ بھگ ڈھائی کیلو کا ہوتا ہے مدینہ کے بازاروں میں جو صاع اس وقت بنتا ہے، یا مشائخ سے بالسند جو صاع متوارث ہے اس میں گی ہوں ڈھائی کیلو ہی آتا ہے۔\nعبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"پیمانہ اہل مدینہ کا پیمانہ ہے اور وزن اہل مکہ کا وزن ہے\" ۱؎۔\n۱؎: اس سے مراد سونا اور چاندی وزن کرنے کے بانٹ ہیں کیونکہ ان کا وزن دراہم سے کیا جاتا تھا اور اس وقت مختلف شہروں کے دراہم مختلف وزن کے ہوتے تھے اس لیے کہا گیا کہ زکاۃ کے سلسلہ میں اہل مکہ کے دراہم کا اعتبار ہو گا، اور ایک قول یہ ہے کہ چوں کہ اہل مدینہ کاشتکار تھے اس لیے وہ پیمائش اور ناپ کے احوال کے زیادہ جانکار تھے اور مکہ والے عام طور سے تاجر تھے اس لیے وہ تول کے احوال کے زیادہ واقف کار تھے اس لیے ایسا کہا گیا ہے۔","الألباني: صحيح — الألباني: صحيح",{"u2":"حضرت سائب بن یزید بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے دور میں صاع تمھارے آج کل کے حساب سے ایک مد اور ایک تہائی مد کے برابر تھا۔ اب اس (مد کی مقدار) میں اضافہ کر دیا گیا ہے۔\nامام ابوعبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ مجھے یہ حدیث زیاد بن ایوب نے بھی بیان کی ہے۔","f2":"پیمانے اور وزن ہمیشہ بدلتے رہتے ہیں، ایک جیسے نہیں رہتے، مد، صاع، درہم اور مثقال بھی چھوٹے بڑے ہوتے رہے ہیں۔ ظاہر ہے شریعت میں معتبر پیمانہ اور وزن تو وہی ہے جو رسول اللہ صلی اللہ علیہ وسلم کے دور میں تھا۔ آپ کے دور میں صاع چار مد کا تھا اور ایک مد وزن کے لحاظ سے ایک اور تہائی رطل 11/3 کا تھا۔ اسی طرح صاع پانچ رطل اور تہائی رطل کا تھا، یعنی 51/3 رطل۔ اور رطل 90 مثقال کا۔ اس لحاظ سے صاع کے وزن کی تفصیل حدیث 2515 میں گزر چکی ہے جو تقریباً ڈھائی کلو بنتا ہے۔ بعد میں مد اور صاع بڑا بنا دیا گیا۔ مد بجائے 11/3 رطل کے 23 رطل کا کر دیا گیا۔ اسی طرح صاع آٹھ رطل کا ہوگیا۔ احناف نے اس صاع کو اختیار کیا ہے، حالانکہ وہ صاع نبوی نہیں۔ یہی وجہ ہے کہ امام ابو یوسف رحمہ اللہ جب مدینہ منورہ گئے اور ان کا امام مالک رحمہ اللہ سے اس سلسلے میں مباحثہ ہوا تو انھوں نے اپنے مسلک سے رجوع کر لیا کیونکہ امام مالک رحمہ اللہ نے ان کو مدینہ منورہ کے مختلف گھروں سے رسول اللہ صلی اللہ علیہ وسلم کے دور کے صاع منگوا کر دکھائے جو ایک دوسرے کے برابر تھے۔ اور یہ صاع اہل مدینہ نے وراثتاً اپنے آباؤ اجداد سے حاصل کیے تھے۔ اور یہی صاع صحیح ہے۔ جمہور اہل علم اسی کے قائل ہیں۔ امام ابو یوسف نے فرمایا تھا کہ اگر میرے استاد امام ابوحنیفہ رحمہ اللہ یہ صاع دیکھ لیتے تو وہ بھی اس کے قائل ہو جاتے۔ گویا حنفیہ کا صاع شرعی صاع نہیں ے، لہٰذا عشر اور صدقۃ الفطر میں مدنی صاع ہی معتبر ہوگا نہ کہ حنفیہ والا صاع جو بعد میں بنایا گیا۔"}],[2521,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا کہ صدقہ فطر نماز کے لیے لوگوں کے نکلنے سے پہلے ادا کر دیا جائے (ابن بزیع کی روایت میں «بصدقة الفطر» کے بجائے «بزكاة الفطر» ہے)۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا کہ صدقۃ الفطر عید کی نماز کے لیے جانے سے پہلے ادا کر دیا جائے۔\n(امام نسائی رحمہ اللہ کے استاد) محمد بن عبداللہ بن بزیع نے (اپنی روایت میں بصدقۃ الفطر کے بجائے) بزکاۃ الفطر کے الفاظ بیان کیے ہیں۔","f2":"تفصیل کے لیے دیکھیے روایت نمبر ۲۵۰۶۔"}],[2522,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے معاذ بن جبل رضی اللہ عنہ کو یمن بھیجا تو فرمایا: \"تم ایک ایسی قوم کے پاس جا رہے ہو جو اہل کتاب ہیں، تم انہیں اس بات کی گواہی کی دعوت دو کہ اللہ کے علاوہ کوئی حقیقی معبود نہیں، اور میں اللہ کا رسول ہوں۔ اگر وہ تمہاری یہ بات مان لیں تو انہیں بتاؤ کہ اللہ عزوجل نے ان پر ہر دن اور رات میں پانچ (وقت کی) نمازیں فرض کی ہیں، اگر وہ تمہاری یہ بات (بھی) مان لیں تو انہیں بتاؤ کہ اللہ عزوجل نے ان کے مالوں میں زکاۃ فرض کی ہے جو ان کے مالداروں سے لی جائے گی، اور ان کے محتاجوں میں تقسیم کر دی جائے گی، اگر وہ تمہاری یہ بات (بھی) مان لیں تو ان کے اچھے و عمدہ مال لینے سے بچو، اور مظلوم کی بد دعا سے بچو کیونکہ اس کے اور اللہ کے درمیان کوئی حجاب نہیں\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے حضرت معاذ بن جبل رضی اللہ عنہ کو یمن کی طرف (حاکم بنا کر) بھیجا اور فرمایا: ’’تو وہاں اہل کتاب (یہودیوں) کی کثیر جماعت کی طرف جا رہا ہے، لہٰذا انھیں دعوت دینا کہ وہ گواہی دیں کہ اللہ تعالیٰ کے سوا کوئی معبود نہیں اور میں (محمد صلی اللہ علیہ وسلم) اللہ تعالیٰ کا رسول ہوں۔ اگر وہ تیری یہ بات مان لیں تو انھیں بتانا کہ اللہ تعالیٰ نے ان پر پانچ نمازیں ہر دن رات میں فرض کی ہیں۔ اگر وہ تیری یہ بات بھی مان لیں تو بتانا کہ اللہ عزوجل نے ان پر ان کے مالوں میں زکاۃ فرض کی ہے جو ان کے مال دار لوگوں سے لی جائے گی اور ان کے فقیر لوگوں میں تقسیم کی جائے گی۔ اور اگر وہ تیری یہ بات بھی مان لیں تو ان کے عمدہ مال نہ لینا۔ اور مظلوم کی بددعا سے بچنا کیونکہ اللہ تعالیٰ تک پہنچنے میں اس کے سامنے کوئی رکاوٹ نہیں۔ـ‘‘","f2":"اصل یہی ہے کہ زکاۃ کو اسی علاقے میں تقسیم کیا جائے الا یہ کہ وہ زائد ہو یا دوسرے لوگ زیادہ مستحق ہوں۔ خصوصاً صدقۃ الفطر تو اپنے علاقے ہی میں تقسیم ہونا چاہیے کیونکہ اس کی مقدار کم ہوتی ہے۔ اس علاقے کے مستحقین کی ضروریات کے لیے کافی نہ ہوگا، نیز یہ وقتی صدقہ ہے تاکہ فقراء بھی بے فکر ہو کر عید میں شامل ہو جائیں۔ بخلاف اس کے زکاۃ ایک مستقل فنڈ ہے اور اس کے مصارف بھی زیادہ ہیں، مثلاً: فی سبیل اللہ، لہٰذا اسے منتقل کرنا ہی پڑتا ہے۔ (باقی مباحث کے لیے دیکھیے، حدیث: ۲۴۳۷)"}],[2523,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک شخص نے کہا: میں ضرور صدقہ دوں گا، تو وہ اپنا صدقہ لے کر نکلا اور اس نے اسے ایک چور کے ہاتھ میں رکھ دیا، صبح کو لوگ باتیں کرنے لگے کہ ایک چور کو صدقہ دیا گیا ہے، اس نے کہا: اللہ تیرا شکر ہے چور کے ہاتھ میں چلے جانے پر بھی ۱؎، میں اور بھی صدقہ دوں گا چنانچہ (دوسرے دن بھی) وہ اپنا صدقہ لے کر نکلا اور اس نے اسے لے جا کر ایک زانیہ عورت کے ہاتھ پر رکھ دیا۔ صبح کو لوگ باتیں کرنے لگے کہ آج رات ایک زانیہ کو صدقہ دیا گیا ہے۔ تو اس نے پھر کہا: اللہ تیرا شکر ہے زانیہ کے ہاتھ میں چلے جانے پر بھی، میں پھر صدقہ دوں گا، چنانچہ (تیسرے دن) پھر وہ صدقہ کا مال لے کر نکلا، اور ایک مالدار شخص کو تھما آیا، پھر صبح کو لوگ باتیں کرنے لگے کہ ایک مالدار شخص کو صدقہ کیا گیا ہے، اس نے کہا: اللہ تیرا شکر ہے، زانیہ، چور اور مالدار کو دے دینے پر بھی۔ تو خواب میں اس کے پاس آ کر کہا گیا: رہا تیرا صدقہ تو وہ قبول کر لیا گیا ہے، رہی زانیہ تو (صدقہ پا کر) شاید وہ زناکاری سے باز آ جائے اور رہا چور تو صدقہ پا کر شاید وہ اپنی چوری سے باز آ جائے، اور رہا مالدار آدمی (تو صدقہ پا کر) شاید وہ اس سے سبق سیکھے اور اللہ عزوجل نے اسے جو دولت دے رکھی ہے اس میں سے خرچ کرنے لگے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’(بنی اسرائیل میں سے) ایک آدمی نے کہا: میں آج ضرور صدقہ کروں گا۔ وہ (رات کے وقت) اپنا صدقہ لے کر نکلا اور جا کر ایک چور کے ہاتھ پر رکھ دیا، تو صبح لوگ یہ کہنے لگے کہ چور پر صدقہ کیا گیا ہے۔ اس نے کہا: اے اللہ! تیرا شکر ہے (اگرچہ) چور پر صدقہ ہوگیا۔ آج میں پھر صدقہ کروں گا۔ وہ صدقہ لے کر نکلا تو کسی زانیہ کے ہاتھ پر رکھ آیا۔ صبح لوگ یہ کہنے لگے کہ رات ایک بدکار عورت پر صدقہ کیا گیا۔ اس آدمی نے کہا: اے اللہ تیرا شکر ہے (اگرچہ) زانیہ پر صدقہ ہوگیا ہے۔ آج پھر میں صدقہ کروں گا، پھر وہ اپنا صدقہ لے کر نکلا۔ ایک غنی کو دے آیا۔ صبح لوگ چہ میگوئیاں کرنے لگے کہ (تعجب ہے) مالدار پر صدقہ کیا گیا ہے۔ وہ شخص کہنے لگا، اے اللہ تیرا! شکر ہے (عجیب بات ہے) کبھی بدکار عورت پر صدقہ ہو جاتا ہے، کبھی چور پر اور کبھی مال دار پر، پھر خواب میں اس سے کہا گیا: تیرا صدقہ تو یقینا قبول ہو چکا۔ رہی زانیہ! (یعنی اس پر کیا ہوا صدقہ) تو (وہ اس لیے قبول ہے کہ) شاید اس صدقے کی وجہ سے وہ بدکاری سے باز آجائے۔ اور چور! شاید وہ اس (صدقے) کی وجہ سے چوری کرنے سے باز آجائے اور مال دار! شاید وہ عبرت ونصیحت حاصل کرے اور اللہ تعالیٰ کے دیے ہوئے مال سے خرچ کرنے لگے۔‘‘","f2":"(۱) مندرجہ بالا واقعہ بنی اسرائیل کا ہے۔ جب تک ہماری شریعت پہلی شریعتوں کی کسی بات کی تردید نہ کرے، اس وقت تک پہلی بات بھی حجت ہے۔ مذکورہ واقعہ بھی نبی صلی اللہ علیہ وسلم نے بیان فرما کر تصدیق فرما دی، لہٰذا حجت ہے۔ اسی طرح کسی کا خواب حجت تو نہیں ہوتا مگر نبی کریم صلی اللہ علیہ وسلم کی تصدیق سے یہ بھی حجت بن گیا۔ (۲) اس واقعے سے معلوم ہوا کہ اگر غلطی یا لا علمی سے زکاۃ کسی ایسے شخص کو دے دی گئی ہو جو مستحق نہیں تھا تو ادا کرنے والے شخص پر کوئی ملامت نہیں، نیز وہ بریٔ الذمہ ہو جاتا ہے، اگرچہ لینے والے کے لیے جائز نہیں، البتہ اس واقعے میں یہ صراحت نہیں کہ وہ صدقہ فرض تھا یا نفل۔ ہاں، اگر جان بوجھ کر غیر مستحق کو ادا کرے تو وہ بریٔ الذمہ نہ ہوگا۔ (۳) چور اور زانیہ اگر فقیر تھے تو وہ صدقے کے مستحق تھے۔ ہو سکتا ہے کہ چور فقر کی وجہ سے چوری کرتا ہو اور زانیہ بھی فقر کی وجہ سے زنا کا ارتکاب کرتی ہو۔ اگرچہ اس صورت میں بھی یہ جرائم ان کے لیے جائز نہ تھے مگر ان جرائم کے باوجود وہ فقر کی وجہ سے زکاۃ کے مستحق تھے۔ صدقہ کرنے والے کا اظہار افسوس عرف کے طور پر تھا کیونکہ عموماً جرائم پیشہ لوگوں کو صدقہ نہیں دیا جاتا، مگر شرعاً ایسی کوئی پابندی نہیں۔ ممکن ہے ان سے تعاون ان کی اصلاح کا سبب بن جائے۔"}],[2524,"ابوالملیح کے والد اسامہ بن عمیر رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"اللہ عزوجل بغیر پاکی کے کوئی نماز قبول نہیں کرتا، اور نہ ہی حرام مال سے کوئی صدقہ قبول کرتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابو ملیح کے والد سے مروی ہے، وہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے سنا: ’’اللہ تعالیٰ طہارت کے بغیر نماز قبول نہیں کرتا اور حرام مال سے صدقہ قبول نہیں کرتا۔‘‘","f2":"قبولیت کا مطلب ثواب ہے، یعنی حرام مال دے صقہ کرنے والے کو ثواب نہ ملے گا، البتہ اس سے فقر کو فائدہ ہو جائے گا۔ یاد رہے کہ حرام مال اس شخص کے لیے ناجائز ہے جس نے ناحق حاصل کیا، تاہم فقیر چونکہ اس بات سے ناواقف ہے کہ صدقہ کرنے والے نے صدقہ حرام مال سے کیا ہے یا حلال مال سے، اس لیے اس کے لیے اس کا استعمال جائز ہوگا، لیکن علم رکھتے ہوئے کسی حرام کی کمائی سے صدقہ لینا اس کے لیے جائز نہ ہوگا۔"}],[2525,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص بھی اپنے پاکیزہ مال سے صدقہ دیتا ہے (اور اللہ پاکیزہ مال ہی قبول کرتا ہے) تو رحمن عزوجل اسے اپنے داہنے ہاتھ میں لیتا ہے گو وہ ایک کھجور ہی کیوں نہ ہو، پھر وہ رحمن کے ہاتھ میں بڑھتا رہتا ہے یہاں تک کہ وہ بڑھتے بڑھتے پہاڑ سے بھی بڑا ہو جاتا ہے، جیسے کہ تم میں سے کوئی اپنے گھوڑے کے بچھڑے یا اونٹنی کے چھوٹے بچے کو پالتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب بھی کوئی شخص حلال مال سے صدقہ کرتا ہے، اور اللہ تعالیٰ قبول بھی حلال مال ہی فرماتا ہے، تو اللہ تعالیٰ اسے اپنے دائیں ہاتھ میں وصول کرتا ہے، اگرچہ وہ صدقہ ایک کھجور ہی ہو، پھر وہ کھجور رب رحمان کی ہتھیلی میں بڑھتی رہتی ہے حتیٰ کہ وہ پہاڑ سے بھی بڑی ہو جاتی ہے، جیسے تم میں سے کوئی شخص اپنے گھوڑے یا اونٹ کے بچے کو پالتا پوستا ہے۔‘‘","f2":"اللہ تعالیٰ کی صفات جس طرح قرآن وحدیث میں وارد ہیں ان پر اسی طرح ایمان لانا واجب ہے۔ ان میں تشبیہ و تمثیل اور تاویل و تعیطل سے کام لینا جائز نہیں سلف کا اس پر اجماع ہے۔ بعض نے ان صفات کی تاویلات کی ہیں جو کہ قابل التفات نہیں۔"}],[2526,"عبداللہ بن حبشی خثعمی رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم سے پوچھا گیا: کون سے کام افضل ہیں؟ آپ نے فرمایا: \"ایسا ایمان جس میں شبہ نہ ہو، جہاد جس میں خیانت نہ ہو، اور حج مبرور\"، پوچھا گیا: کون سی نماز افضل ہے؟ آپ نے فرمایا: \"لمبے قیام والی نماز\"، پوچھا گیا: کون سا صدقہ افضل ہے؟ آپ نے فرمایا: \"وہ صدقہ جو کم مال والا اپنی محنت کی کمائی سے دے\"، پوچھا گیا: کون سی ہجرت افضل ہے؟ آپ نے فرمایا: \"ایسی ہجرت جو اللہ کی حرام کی ہوئی چیزوں کو چھوڑ دے\"، پوچھا گیا: کون سا جہاد افضل ہے، آپ نے فرمایا: \"اس شخص کا جہاد جو مشرکین سے اپنی جان و مال کے ساتھ جہاد کرے\"، پوچھا گیا: کون سا قتل افضل ہے؟ آپ نے فرمایا: \"جس میں آدمی کا خون بہا دیا گیا ہو، اور اس کا گھوڑا ہلاک کر دیا گیا ہو\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن حبشی خثعمی رضی اللہ عنہ سے منقول ہے کہ نبی کریم صلی اللہ علیہ وسلم سے پوچھا گیا: کون سا عمل افضل ہے؟ آپ نے فرمایا: ’’ایسا ایمان جس میں کوئی شک نہ رہے۔ اور ایسا جہاد جس میں کوئی خیانت نہ کی جائے اور نیکی والا صاف ستھرا حج۔‘‘ پوچھا گیا: کون سی نماز افضل ہے؟ آپ نے فرمایا: ’’لمبے قیام والی (نفل نماز)۔‘‘ پوچھا گیا: صدقہ کون سا افضل ہے؟ آپ نے فرمایا: ’’کم مال والے کا مشقت سے کمایا ہوا مال۔‘‘ پوچھا گیا: ہجرت کون سی افضل ہے؟ فرمایا: ’’اس شخص کی جو اللہ تعالیٰ کی حرام کردہ چیزوں کو چھوڑ دے۔‘‘ عرض کیا گیا: جہاد کون سا افضل ہے؟ آپ نے فرمایا: ’’اس شخص کا جس نے اپنے جان ومال کے ساتھ مشرکین سے جہاد کیا۔‘‘ عرض کیا گیا: کون سا قتل (مارا جانا) زیادہ شرف والا ہے؟ آپ نے فرمایا: ’’اس آدمی کی شہادت جس کا اپنا خون بھی بہا دیا گیا اور اس کا گھوڑا بھی مار دیا گیا ہو۔‘‘","f2":"(۱) ضروری نہیں کہ ایک سوال کا جواب ہر شخص کو ایک سا ہی ملے۔ مخاطب کی حالت اور موقع محل کے لحاظ سے جواب مختلف ہو سکتا ہے، نیز ہو سکتا ہے کہ ایک عمل حقوق اللہ میں سے افضل ہو دوسرا حقوق العباد میں سے۔ کوئی عبادات میں افضل ہو، کوئی معاملات میں۔ اسی لیے دیگر روایات میں افضل عمل کا جواب اس سے مختلف بھی آیا ہے۔ اس میں کوئی تناقض نہیں۔ (۲) ’’ایمان‘‘ جس میں کوئی تذبذب یا حیص بیص نہ ہو، ورنہ وہ معتبر ہی نہیں، جیسے منافقین کا ایمان۔ (۳) خیانت، یعنی مال غنیمت میں۔ (۴) ’’نیکی والا حج۔‘‘ جس میں کوئی شہوانی بات نہ کی گئی ہو، کسی کبیرہ گناہ کا ارتکاب اور کسی سے جھگڑا وغیرہ نہ کیا گیا ہو۔ (۵) ’’لمبے قیام والی۔‘‘ یعنی رات کی نفل نماز، ورنہ فرض نماز تو مختصر قیام والی چاہیے۔ (۶) ’’چھوڑ دے۔‘‘ کیونکہ ہجرت کا مقصد تو اللہ تعالیٰ کے دین پر عمل کرنا ہے، ورنہ گھر اور شہر چھوڑنے کی کیا ضرورت تھی؟"}],[2527,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک درہم ایک لاکھ درہم سے بڑھ گیا\"، لوگوں نے (حیرت سے) پوچھا: یہ کیسے؟ آپ نے فرمایا: \"ایک شخص کے پاس دو درہم تھے، ان دو میں سے اس نے ایک صدقہ کر دیا، اور دوسرا شخص اپنی دولت (کے انبار کے) ایک گوشے کی طرف گیا اور اس (ڈھیر) میں سے ایک لاکھ درہم لیا، اور اسے صدقہ کر دیا\" ۱؎۔\n§وضاحت\n۱؎: مطلب یہ ہے کہ ثواب میں دینے والے کی حالت کا لحاظ کیا جاتا ہے نہ کہ دیئے گئے مال کا، اللہ کے نزدیک قدر و قیمت کے اعتبار ایک لاکھ درہم اس غریب کے ایک درہم کے برابر نہیں ہے جس کے پاس صرف دو ہی درہم تھے، اور ان دو میں سے بھی ایک اس نے اللہ کی راہ میں دے دیا۔","الألباني: حسن",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’(کبھی) ایک درہم (کا ثواب) لاکھ درہم سے بڑھ جاتا ہے۔ صحابہ نے پوچھا: وہ کیسے؟ آپ نے فرمایا: ’’ایک آدمی کے پاس کل دو درہم ہوں، اس نے ان میں سے ایک صدقہ کر دیا۔ اور دوسرا شخص اپنے مال کے ایک کونے میں گیا۔ اس میں سے ایک لاکھ درہم اٹھایا اور صدقہ کر دیا۔‘‘","f2":"مذکورہ روایت اور اگلی روایت کو محقق کتاب نے سنداً ضعیف قرار دیا ہے جبکہ دیگر محققین میں سے بعض نے حسن قرار دیا ہے، بعض نے صحیح اور بعض نے اسنادہ قوی کا حکم لگایا ہے، نیز انھوں نے ان احادیث پر تحقیقی بحث کرتے ہوئے ان کے شواہد اور متابعات کا بھی تذکرہ کیا ہے۔ جس سے معلوم ہوتا ہے کہ یہ روایت سنداً ضعیف ہونے کے باوجود قابل عمل اور قابل حجت ہے۔ مزید تفصیل کے لیے دیکھیے: (ذخیرۃ العقبیٰ شرح سنن النسائی: ۲۲/ ۳۴۹- ۳۵۱، والموسوعۃ الحدیثیۃ مسند الامام احمد: ۱۴/ ۴۹۸، وصحیح سنن النسائی للالبانی: ۲/ ۲۰۳، رقم: ۲۵۲۶، ۲۵۲۷) علاوہ ازیں اللہ تعالیٰ گنتی کو نہیں دیکھتا بلکہ خرچ کرنے والے کے جذبے اور اس کے دل کی حالت کو دیکھتا ہے۔ ارشاد ربانی ہے: {لَنْ یَّنَالَ اللّٰہَ لُحُوْمُہَا وَ لَا دِمَآؤُہَا وَ لٰکِنْ یَّنَالُہُ التَّقْوٰی مِنْکُمْ} (الحج: ۳۷) ’’اللہ تعالیٰ کے پاس قربانی کے گوشت اور ان (قربانی والے جانوروں) کے خون نہیں پہنچتے، بلکہ اس کے پاس تمہارا تقویٰ اور خلوص پہنچتا ہے۔‘‘ یاد رہے اجر بھی اسی چیز کا ہے۔"}],[2528,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک درہم ایک لاکھ درہم سے آگے نکل گیا\"، لوگوں نے عرض کیا: اللہ کے رسول! یہ کیسے؟ آپ نے فرمایا: \"ایک شخص کے پاس دو درہم ہیں، اس نے ان دونوں میں سے ایک لیا اور اسے صدقہ کر دیا۔ دوسرا وہ آدمی ہے جس کے پاس بہت زیادہ مال ہے، اس نے اپنے مال (خزانے) کے ایک کنارے سے ایک لاکھ درہم نکالے، اور انہیں صدقہ میں دیدے\"۔","الألباني: حسن",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’(کبھی) ایک درہم (کا ثواب) لاکھ درہم سے بڑھ جاتا ہے۔ صحابہ نے پوچھا: وہ کیسے؟ آپ نے فرمایا: ’’ایک آدمی کے پاس کل دو درہم ہوں، اس نے ان میں سے ایک صدقہ کر دیا۔ اور دوسرا شخص اپنے مال کے ایک کونے میں گیا۔ اس میں سے ایک لاکھ درہم اٹھایا اور صدقہ کر دیا۔‘‘"}],[2529,"ابومسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہمیں صدقہ کرنے کا حکم فرماتے تھے، اور ہم میں بعض ایسے ہوتے تھے جن کے پاس صدقہ کرنے کے لیے کچھ نہ ہوتا تھا، یہاں تک کہ وہ بازار جاتا اور اپنی پیٹھ پر بوجھ ڈھوتا، اور ایک مد لے کر آتا اور اسے رسول اللہ صلی اللہ علیہ وسلم کو دے دیتا۔ میں آج ایک ایسے شخص کو جانتا ہوں جس کے پاس ایک لاکھ درہم ہے، اور اس وقت اس کے پاس ایک درہم بھی نہ تھا۔","الألباني: صحيح",{"u2":"حضرت ابو مسعود رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہمیں صدقہ کرنے کا حکم فرمایا کرتے تھے۔ ہم میں سے کچھ لوگ کوئی چیز نہ پاتے تھے کہ صدقہ کریں تو وہ بازار جاتے اور اپنی پیٹھ پر بوجھ اٹھاتے (بار برداری کا کام کرتے) او ر ایک مد لے کر آتے اور اللہ کے رسول صلی اللہ علیہ وسلم کو دے دیتے، لیکن آج میں ایسے لوگ دیکھتا ہوں جن کے پاس لاکھوں درہم ہیں مگر ان دنوں ان کے پاس ایک درہم بھی نہیں ہوتا تھا۔","f2":"یقینا اس دور کا ایک درہم ثواب کے لحاظ سے آج کے ایک لاکھ درہم سے بڑھ جائے گا۔ واللہ اعلم"}],[2530,"ابومسعود رضی اللہ عنہ کہتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم نے ہمیں صدقہ کا حکم دیا تو ابوعقیل رضی اللہ عنہ نے آدھا صاع صدقہ دیا، اور ایک اور شخص اس سے زیادہ لے کر آیا، تو منافقین اس (پہلے شخص) کے صدقہ کے بارے میں کہنے لگے کہ اللہ تعالی ایسے صدقے سے بے نیاز ہے، اور اس دوسرے نے محض دکھاوے کے لیے دیا ہے، تو (اس موقع پر) آیت کریمہ: «الذين يلمزون المطوعين من المؤمنين في الصدقات والذين لا يجدون إلا جهدهم» \"جو لوگ دل کھول کر خیرات کرنے والے مومنین پر اور ان لوگوں پر جو صرف اپنی محنت و مزدوری سے حاصل کر کے صدقہ دیتے ہیں طعن زنی کرتے ہیں\" (التوبہ: ۷۹) نازل ہوئی۔","الألباني: صحيح",{"u2":"حضرت ابو مسعود رضی اللہ عنہ بیان کرتے ہیں کہ جب ہمیں رسول اللہ صلی اللہ علیہ وسلم نے صدقہ کرنے کا حکم دیا تو حضرت ابو عقیل رضی اللہ عنہ نے نصف صاع صدقہ کیا۔ ایک اور صحابی اس سے بہت زیادہ مال لے کر آئے۔ منافقین کہنے لگے: اللہ تعالیٰ اس شخص (حضرت ابو عقیل) کے اس قلیل صدقے سے بے نیاز ہے اور اس دوسرے شخص نے صرف ریاکاری کے لیے دقہ کیا ہے۔ تو یہ آیت اتری: {اَلَّذِیْنَ یَلْمِزُوْنَ الْمُطَّوِّعِیْنَ… الآیۃ} ’’منافق لوگ خوشی سے کثیر صدقہ کرنے والے ایمان والوں کو بھی عیب لگاتے ہیں اور ان غریب مسلمانوں کو بھی جن کے پاس مشقت سے کمایا ہوا تھوڑا سا مال ہے۔‘‘","f2":"’’ایک اور صحابی۔‘‘ یہ حضرت عبدالرحمن بن عوف رضی اللہ عنہ تھے۔ مال دار صحابہ کرام رضی اللہ عنہم میں شمار ہوتے تھے۔ اس دن یہ چار ہزار اور ایک روایت کے مطابق آٹھ ہزار درہم لے کر آئے تھے۔ دیکھیے: (ذخیرۃ العقبیٰ شرح سنن النسائی: ۲۲/ ۳۵۶) منافقوں نے ان پر ریا کاری کا الزام لگا دیا اور حضرت ابو عقیل رضی اللہ عنہ کے نصف صاع صدقہ کرنے کو ویسے مذاق بنا لیا اور تحقیر کی۔"}],[2531,"حکیم بن حزام رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے مانگا تو آپ نے مجھے دیا، پھر مانگا پھر آپ نے دیا، پھر مانگا، تو فرمایا: \"یہ مال سرسبز و شیریں چیز ہے، جو شخص اسے فیاضی نفس کے ساتھ لے گا تو اس میں برکت دی جائے گی، اور جو شخص اسے حرص و طمع کے ساتھ لے گا تو اسے اس میں برکت نہ ملے گی، اور اس شخص کی طرح ہو گا جو کھاتا ہے مگر آسودہ نہیں ہوتا (یعنی مانگنے والے کا پیٹ نہیں بھرتا)۔ اوپر والا ہاتھ، نیچے والے ہاتھ سے بہتر ہے\"۔","الألباني: صحيح",{"u2":"حضرت حکیم بن حزام رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے (مال) مانگا، آپ نے مجھے دیا۔ میں نے پھر مانگا، آپ نے پھر دیا۔ میں نے پھر مانگا، آپ نے پھر دیا۔ ساتھ ہی فرمایا: ’’بلا شبہ یہ مال سبز وشیریں ہے۔ جو شخص اسے دل کی پاکیزگی کے ساتھ لے گا، اس کے لیے اس میں برکت ہوگی اور جو دل کے طمع وحرص کے ساتھ لے گا، اس کے لیے اس میں برکت نہ ہوگی اور وہ اس شخص کی طرح ہوگا جو کھاتا ہے مگر سیر نہیں ہوتا اور اوپر والا ہاتھ نیچے والے ہاتھ سے بہتر ہے۔‘‘","f2":"(۱) ’’سبز وشیریں‘‘ سبز چارہ جانوروں کو بہت مرغوب ہوتا ہے اور میٹھی چیز عموماً انسانوں کو بہت پسند ہوتی ہے، اس لیے مال کو دو چیزوں سے تشبیہ دی گئی۔ (۲) ’’دل کی پاکیزگی۔‘‘ یعنی دل میں طمع اور لالچ نہ ہو اور نہ اس نے مانگا ہی ہو۔ یا دینے والے نے اسے خوشی سے دیا ہو، نہ کہ مجبوراً یا بغیر مانگے دیا ہو۔ (۳) ’’دل کے طمع وحرص۔‘‘ یعنی لینے والے کی یہ حالت ہو یا دینے والے نے طمع اور لالچ سے دیا ہو کہ مجھے زیادہ واپس ملے گا۔ (۴) ’’سیر نہیں ہوتا۔‘‘ کیونکہ دل غنی نہیں۔ دل غنی ہو تو تھوڑا بھی کافی محسوس ہوتا ہے ورنہ ڈھیر بھی مطمئن نہیں کر سکتے۔ (۵) ’’اوپر والا ہاتھ۔‘‘ یعنی دینے والا کیونکہ وہ بلند رہتا ہے۔ کسی کے سامنے ذلیل نہیں ہوتا۔ (۶) ’’نیچے والے ہاتھ‘‘ یعنی مانگنے والا۔ وہ حقیقتاً بھی دینے والے کے ہاتھ کے نیچے ہوتا ہے اور رتبے کے لحاظ سے بھی کم ہوتا ہے۔ (۷) حدیث کا مقصود یہ ہے کہ انتہائی حاجت کے بغیر نہیں مانگنا چاہیے اور اگر خود بخود ملے تو پھر بھی دل میں حرص وطمع نہیں ہونا چاہیے اور جب ضرورت پوری ہو جائے تو مانگنے سے رک جانا چاہیے بلکہ کسی کا دیا بھی قبول نہ کرے۔ اس میں عزت ہے۔"}],[2532,"طارق محاربی رضی اللہ عنہ کہتے ہیں کہ ہم مدینہ آئے تو کیا دیکھتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم منبر پر کھڑے خطبہ دے رہے ہیں آپ فرما رہے ہیں: دینے والے کا ہاتھ اوپر والا ہے، اور پہلے انہیں دو جن کی کفالت و نگہداشت کی ذمہ داری تم پر ہو: پہلے اپنی ماں کو، پھر اپنے باپ کو، پھر اپنی بہن کو، پھر اپنے بھائی کو، پھر اپنے قریبی کو، پھر اس کے بعد کے قریبی کو۔ یہ حدیث ایک لمبی حدیث کا اختصار ہے۔","الألباني: صحيح",{"u2":"حضرت طارق محاربی رضی اللہ عنہ سے مروی ہے کہ ہم مدینہ منورہ آئے تو رسول اللہ صلی اللہ علیہ وسلم منبر پر کھڑے لو گوں سے خطاب فرما رہے تھے۔ آپ فرما رہے تھے: ’’دینے والے کا ہاتھ اونچا ہوتا ہے اور سب سے پہلے تو اسے دے جس کا تو ذمے دار ہے۔ اپنی ماں کو دے، اپنے باپ کو دے، اپنی بہن کو دے، اپنے بھائی کو دے، پھر اپنے قریبی رشتے دار کو دے، پھر اپنے پڑوسی کو دے۔‘‘ یہ حدیث مختصر ہے۔","f2":"عقلاً بھی یہی ترتیب ہے کیونکہ جس کا خرچہ ذمے ہو، اس کا تو حق ہے۔ دنیا میں بھی پرسش ہوگی اور آخرت میں بھی، پھر تعلق، رشتہ داری اور قرب کا لحاظ رکھا جائے گا۔"}],[2533,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا (اس وقت آپ صدقہ و خیرات اور مانگنے سے بچنے کا ذکر کر رہے تھے): اوپر والا ہاتھ بہتر ہے نیچے والے ہاتھ سے، اور اوپر والا ہاتھ خرچ کرنے والا ہاتھ ہے، اور نیچے والا ہاتھ مانگنے والا ہاتھ ہے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے صدقہ کرنے اور مانگنے سے بچنے کا ذکر کرتے ہوئے فرمایا: ’’اوپر والا ہاتھ نیچے والے ہاتھ سے بہتر ہے۔ اوپر والا ہاتھ دینے والا ہاتھ ہے اور نیچے والا ہاتھ مانگنے والا ہے۔‘‘"}],[2534,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بہتر صدقہ وہ ہے جو مالداری کی برقراری اور دل کی بے نیازی کے ساتھ ہو، اور اوپر والا ہاتھ بہتر ہے نیچے والے ہاتھ سے۔ اور پہلے صدقہ انہیں دو جن کی کفالت و نگرانی تمہارے ذمہ ہے۔\n§وضاحت\n۱؎: ایسا نہ ہو کہ سارا مال صدقہ کر دے اور خود محتاج ہو جائے۔","الألباني: حسن صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بہترین صدقہ وہ ہے جس کے بعد بھی صدقہ کرنے والا غنی رہے۔ اور اوپر والا ہاتھ نیچے والے ہاتھ سے بہتر ہے۔ اور سب سے اسے پہلے دے جس کا تو ذمے دار ہے۔‘‘","f2":"’’غنی ہے۔‘‘ خواہ وہ قلبی غنا ہو یا مالی۔ ایسا نہ ہو کہ صدقہ کرنے کے بعد وہ خود مانگنا شروع کر دے یا اس کے اہل خانہ محتاج ہو جائیں۔ ہر آدمی حضرت ابوبکر صدیق رضی اللہ عنہ جیسا ایمان ویقین اور توکل نہیں رکھتا کہ سارا مال صدقہ کر دے۔ یہ رتبہ بلند ملا جس کو مل گیا۔ بعض اہل علم نے معنی یہ کیے ہیں کہ بہترین صدقہ وہ ہے جس کے ساتھ لینے والا غنی ہو جائے اور سوال کی حاجت نہ رہے۔ واللہ اعلم"}],[2535,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"صدقہ دو\"، ایک آدمی نے عرض کیا: اللہ کے رسول! میرے پاس ایک دینار ہے، آپ نے فرمایا: \"اسے اپنی ذات پر صدقہ کرو\" ۱؎ اس نے کہا: میرے پاس ایک اور ہے۔ آپ نے فرمایا: \"اپنی بیوی پر صدقہ کرو\"، اس نے کہا: میرے پاس ایک اور ہے۔ آپ نے فرمایا: \"اسے اپنے بیٹے پر صدقہ کرو\"، اس نے کہا: میرے پاس ایک اور بھی ہے۔ آپ نے فرمایا: \"اپنے خادم پر صدقہ کر دو\"، اس نے کہا: میرے پاس ایک اور ہے۔ آپ نے فرمایا: آپ بہتر سمجھنے والے ہیں (جیسی ضرورت سمجھو ویسا کرو\")۔\n§وضاحت\n۱؎: یعنی خود اپنی ضروریات میں صدقہ کرو۔","الألباني: حسن صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’صدقہ کرو۔‘‘ ایک آدمی نے عرض کیا: اے اللہ کے رسول! میرے پاس ایک دینار ہے۔ آپ نے فرمایا: ’’اپنے آپ پر خرچ کر۔‘‘ اس نے کہا: میرے پاس ایک اور ہے۔ آپ نے فرمایا: ’’اپنی بیوی پر خرچ کر۔‘‘ اس نے عرض کیا: میرے پاس ایک اور ہے۔ فرمایا: ’’اپنی اولاد پر خرچ کر۔‘‘ وہ عرض پر داز ہوا: میرے پاس ایک اور ہے۔ آپ نے فرمایا: ’’اپنے نوکر پر خرچ کر۔‘‘ وہ بولا: میرے پاس ایک اور ہے۔ آپ نے فرمایا: ’’پھر تو زیادہ جانتا ہے (کہ کہاں خرچ کرے)۔‘‘","f2":"(۱) اس حدیث میں تَصَدَّقُوْا کا لفظ ہے، مگر مراد فرض یا نفل صدقہ نہیں بلکہ مطلق خرچ کرنا مراد ہے۔ اس لفظ میں نکتہ یہ ہے کہ مومن کو اپنے واجب اخراجات پر بھی ثواب ملتا ہیے بشرطیکہ حلال مال سے کرے اور اس میں اللہ تعالیٰ کی اطاعت اور ثواب کی نیت رکھے۔ (۲) بعض احادیث میں اولاد کو بیوی سے پہلے بیان کیا گیا ہے۔ کوئی فرق نہیں کیونکہ دونوں کے اخراجات یکساں واجب ہیں۔ (۳) بیان کردہ ترتیب سے معلوم ہوتا ہے کہ جب تک فرض اخراجات پورے نہ ہوں، آگے صدقہ نہیں کرنا چاہیے۔ اول خویش بعد درویش۔ الا یہ کہ اختیار نہ رہے، مثلاً: مہمان گھر آجائے تو گھر والوں کو بھوکا رکھ کر بھی مہمان نوازی کی جا سکتی ہے۔ گویا یہاں اختیاری صدقے کا بیان ہے۔ (۴) ’’تو زیادہ جانتا ہے۔‘‘ یعنی پھر تیری مرضی۔ جہاں مناسب سمجھتا ہے خرچ کر۔"}],[2536,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ ایک شخص جمعہ کے دن مسجد میں داخل ہوا، رسول اللہ صلی اللہ علیہ وسلم جمعہ کا خطبہ دے رہے تھے، تو آپ نے فرمایا: \"تم دو رکعتیں پڑھو\"، پھر وہ شخص دوسرے جمعہ کو بھی آیا اور نبی اکرم صلی اللہ علیہ وسلم خطبہ دے رہے تھے، تو آپ نے فرمایا: \"تم دو رکعتیں پڑھو\"، پھر وہ تیسرے جمعہ کو (بھی) آیا، آپ نے فرمایا: \"دو رکعتیں پڑھو\"، پھر آپ نے لوگوں سے فرمایا: \"صدقہ دو\"، تو لوگوں نے صدقہ دیا، تو آپ نے اس شخص کو دو کپڑے دئیے، پھر آپ نے پھر فرمایا: \"لوگو صدقہ دو\"، تو اس شخص نے اپنے ان دونوں کپڑوں میں سے ایک کو آپ کے سامنے ڈال دیا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: کیا تم لوگوں نے اس شخص کو نہیں دیکھا؟ یہ خستہ حالت میں مسجد میں آیا، میں نے امید کی کہ تم لوگ اسے دیکھ کر اس کی خستہ حالی کو تاڑ لو گے اور اسے صدقہ دو گے، لیکن تم لوگوں نے ایسا نہیں کیا، تو مجھ ہی کو کہنا پڑا کہ تم صدقہ دو، تو تم لوگوں نے صدقہ دیا تو میں نے اسے دو کپڑے دئیے، پھر لوگوں سے کہا: \"صدقہ دو\"، تو اس نے ان کپڑوں میں سے (جو ہم نے اسے دیے تھے) ایک (ہمارے آگے) ڈال دیا، (ارے بیوقوف) تم اپنا کپڑا لے لو، آپ نے اسے ڈانٹا ۱؎۔\n§وضاحت\n۱؎: یہ ڈانٹ ازراہ شفقت تھی، مطلب یہ تھا کہ میں تو تمہارے لیے انتظام میں لگا ہوا ہوں، تمہیں صدقہ کرنے کی کیا ضرورت ہے۔","الألباني: حسن الإسناد",{"u2":"حضرت ابو سعید رضی اللہ عنہ سے روایت ہے کہ ایک آدمی جمعے کے دن مسجد میں داخل ہوا جب کہ رسول اللہ صلی اللہ علیہ وسلم خطبہ ارشاد فرما رہے تھے۔ آپ نے فرمایا: ’’دو رکعتیں پڑھ۔‘‘ پھر وہ دوسرے جمعے کو آیا تو (اس وقت بھی) رسول اللہ صلی اللہ علیہ وسلم خطبہ ارشاد فرما رہے تھے۔ آپ نے فرمایا: ’’دو رکعتیں پڑھی۔‘‘ پھر وہ تیسرے جمعے کو آیا تو (اس وقت بھی آپ خطبہ فرما رہے تھے) آپ نے پھر فرمایا: ’’دو رکعتیں پڑھ۔‘‘ پھر فرمایا: ’’صدقہ کرو۔‘‘ لوگوں نے صدقہ کیا۔ اپ نے اسے دو کپڑے دیے۔ پھر آپ نے فرمایا: ’’صدقہ کرو۔‘‘ اس نے اپنے دو کپڑوں میں سے ایک کپڑا پھینک دیا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم اسے نہیں دیکھتے؟ یہ خراب حالت میں مسجد میں داخل ہوا۔ مجھے امید تھی کہ تم خود ہی سمجھ جاؤ گے اور اس پر صدقہ کرو گے لیکن تم نے نہ دیا تو میں نے خود کہا کہ صدقہ کرو۔ تم نے صدقہ کیا تو میں نے اسے دو کپڑے دیے، پھر میں نے کہا: صدقہ کرو تو اس نے بھی اپنا ایک کپڑا پھینک دیا۔ اٹھا اپنا کپڑا۔‘‘ اور آپ نے اسے ڈانٹا۔‘‘","f2":"(۱) دو رکعتیں پڑھ۔‘‘ ہر جمعے آپ کا اسے دو رکعات پڑھنے کا حکم دینا دلیل ہے کہ دوران خطبہ میں آنے والا شخص لازماً دو رکعات پڑھے۔ اسے یہ کہہ کر رد نہیں کیا جا سکتا کہ آپ نے اس لیے نماز کا حکم دیا تھا کہ لوگ اس کی حالت دیکھ کر اس پر صدقہ کریں کیونکہ یہ بات تو تیسرے جمعے میں ہوئی۔ اگر پہلے دو جمعوں میں یہ مقصد ہوتا تو اپ موقع پر صدقے کا حکم دیتے جس طرح تیسرے جمعے کو دیا، نیز صدقے کا حکم عام تھا، تبھی تو اس آنے والے کو صرف دو کپڑے دیے اور پھر بعد میں بھی صدقے کا حکم دیا گیا۔ گویا یہ صدقہ صرف اس شخص کے لیے نہ تھا۔ (۲) ’’ڈانٹا۔‘‘ معلوم ہوا محتاج کا صدقہ کرنا ضروری نہیں بلکہ اسے روکا جائے گا۔"}],[2537,"عمیر مولی آبی اللحم کہتے ہیں کہ میرے مالک نے مجھے گوشت بھوننے کا حکم دیا، اتنے میں ایک مسکین آیا، میں نے اس میں سے تھوڑا سا اسے کھلا دیا، میرے مالک کو اس بات کی خبر ہو گئی تو اس نے مجھے مارا، میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، آپ نے اسے بلوایا اور پوچھا: تم نے اسے کیوں مارا ہے؟ اس نے کہا: یہ میرا کھانا(دوسروں کو) بغیر اس کے کہ میں اسے حکم دوں کھلا دیتا ہے۔ اور دوسری بار راوی نے کہا: بغیر میرے حکم کے کھلا دیتا ہے، تو آپ نے فرمایا: \"اس کا ثواب تم دونوں ہی کو ملے گا\"۔","الألباني: صحيح",{"u2":"حضرت عمیر مولیٰ آبی اللحم رضی اللہ عنہ سے مروی ہے کہ مجھے میرے مالک نے حکم دیا کہ میں کچھ گوشت تیار کروں۔ اتفاقاً ایک مسکین آگیا۔ میں نے کچھ اسے کھلا دیا۔ میرے مالک کو اس کا علم ہوا تو اس نے مجھے مارا۔ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا (اور شکایت کی)۔ آپ نے اسے بلایا اور فرمایا: ’’تو نے اسے کیوں مارا؟‘‘ اس نے کہا: یہ میری اجازت کے بغیر میرا کھانا (فقراء کو) کھلاتا ہے۔ آپ نے فرمایا: ’’(پھر کیا ہوا؟) ثواب تم دونوں کو ملے گا۔‘‘","f2":"(۱) ’’آبی اللحم‘‘ یہ ان کا لقب تھا۔ نام خلف بتایا جاتا ہے۔ اور بھی اقوال ہیں اس کے لفظی معنی ہیں: گوشت کا انکار کرنے والا۔ ان کا یہ لقب اس لیے تھا کہ وہ گوشت نہیں کھاتے تھے۔ بعض اہل علم نے کہا ہے کہ دور جاہلیت میں وہ بتوں کے لیے ذبح شدہ گوشت نہیں کھاتے تھے۔ مذکورہ حدیث میں گوشت تیار کرنے کے حکم سے معلوم ہوتا ہے کہ وہ عام گوشت کھاتے تھے۔ ممکن ہے مہمانوں یا اہل خانہ کے لیے تیار کروایا ہو۔ مالک سے مراد یہی ہیں۔ (۲) ’’ثواب دونوں کو ملے گا۔‘‘ البتہ مالک کی اجازت ضروری ہے الا یہ کہ بہت ہی معمولی چیز ہو۔ مالک کو حکم یا رضا مندی کا ثواب اور غلام کو ادائیگی کا ثواب، لیکن ضروری نہیں کہ برابر ہو۔"}],[2538,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"ہر مسلمان پر صدقہ ہے\"، عرض کیا گیا: اگر کسی کو ایسی چیز نہ ہو جسے صدقہ کر سکے؟ آپ نے فرمایا: \"اپنے ہاتھوں سے کام کرے اور اپنی ذات کو فائدہ پہنچائے، اور صدقہ کرے\"، کہا گیا: اگر ایسا بھی نہ کر سکے؟ آپ نے فرمایا: \"محتاج و پریشان حال کی مدد کرے\"، کہا گیا: اگر ایسا بھی نہ کر سکے؟ آپ نے فرمایا: \"بھلائی اور نیک باتوں کا حکم کرے\"، کہا گیا: اگر یہ بھی نہ کر سکے؟ آپ نے فرمایا: \"برائیوں سے باز رہے\"، یہ بھی ایک صدقہ ہے۔","الألباني: صحيح",{"u2":"حضرت ابو موسیٰ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’ہر مسلمان کے ذمے صدقہ (واجب) ہے۔‘‘ پوچھا گیا کہ آپ بتائیں، اگر اس کے پاس کچھ نہ ہو تو؟ آپ نے فرمایا: ’’اپنے ہاتھ سے کمائی کرے۔ اپنے آپ کو فائدہ پہنچائے اور صدقہ بھی کرے۔‘‘ کہا گیا: آپ بتائیں اگر وہ ایسے نہ کر سکے تو؟ آپ نے فرمایا: ’’کسی حاجت مند، ستم رسیدہ (مظلوم یا عاجز) کی مدد کر دے۔‘‘ عرض کیا گیا کہ اگر وہ ایسے بھی نہ کر سکے تو؟ آپ نے فرمایا: ’’پھر نیکی کا حکم دے۔‘‘ عرض کیا گیا: اگر وہ یہ بھی نہ کر سکے تو؟ آپ نے فرمایا: ’’برائی سے باز رہے۔ یہ بھی ایک صدقہ ہے۔‘‘","f2":"صدقے سے مراد کار خیر، یعنی ثواب کا کام ہے کیونکہ ملی صدقے سے مقصود بھی تو ثواب ہی ہے، لہٰذا ہر مسلمان اپنی حیثیت کے مطابق کوئی نہ کوئی نیکی کرتا رہے۔"}],[2539,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب عورت اپنے شوہر کے مال سے صدقہ دے تو اسے ثواب ملے گا، اور اس کے شوہر کو بھی۔ اور خازن کو بھی اتنا ہی ثواب ملے گا، اور ان میں سے کوئی دوسرے کا ثواب کم نہ کرے گا، شوہر کو اس کے کمانے کی وجہ سے ثواب ملے گا، اور بیوی کو اس کے خرچ کرنے کی وجہ سے\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جب کوئی عورت اپنے خاوند کے گھر سے صدقہ کرتی ہے تو اسے بھی ثواب ملتا ہے، خاوند کو بھی اور خزانچی کو بھی۔ لیکن ان میں سے کوئی کسی کے ثواب سے کمی نہیں کرتا۔ خاوند کو اس لیے کہ اس نے یہ مال کمایا تھا اور عورت کو اس لیے کہ اس نے خرچ کیا۔‘‘","f2":"(۱) ’’کمی نہیں کرتا۔‘‘ کیونکہ ہر کسی کو اپنے حصے کا ثواب ملتا ہے، اس لیے ضروری نہیں کہ سب کا ثواب برابر ہو۔ ثواب تو خلوص، محنت ومشقت اور حسن نیت کی بنیاد پر ملتا ہے اور اس میں لوگ مختلف ہوتے ہیں۔ (۲) عورت اپنے خاوند کے گھر سے صدقہ کر سکتی ہے بشرطیکہ خاوند کی طرف سے صراحتاً یا عرفاً اجازت ہو۔ عرفاً اجازت سے مراد رضا مندی ہے۔ اس کے لیے علم ہونا کوئی ضروری نہیں۔"}],[2540,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم نے مکہ فتح کر لیا، تو تقریر کے لیے کھڑے ہوئے، آپ نے (منجملہ اور باتوں کے) اپنی تقریر میں فرمایا: \"کسی عورت کا اپنے شوہر کی اجازت کے بغیر عطیہ دینا جائز نہیں\"، یہ حدیث مختصر ہے۔","الألباني: حسن صحيح",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہ بیان کرتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم نے مکہ مکرمہ فتح کیا تو خطبے کے لیے کھڑے ہوئے اور آپ نے اپنے خطبے میں ارشاد فرمایا: ’’کسی عورت کے لیے جائز نہیں کہ خاوند کی اجازت کے بغیر کوئی تحفہ یا عطیہ دے۔‘‘ یہ روایت مختصر ہے۔","f2":"اس سے مراد خاوند کے گھر سے عطیہ ہے ورنہ اگر عورت اپنے مال سے عطیہ دے تو خاوند کی اجازت ضروری نہیں۔ لیکن پھر بھی حسن معاشرت اور خاوند کو اعتماد میں لینے کے لیے اس سے صلاح مشورہ کرل ینا ہی بہتر ہے۔"}],[2541,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم کی محترم بیویاں (ازواج مطہرات) آپ کے پاس اکٹھا ہوئیں، اور پوچھنے لگیں کہ ہم میں کون آپ سے پہلے ملے گی؟ آپ نے فرمایا: \"تم میں سب سے لمبے ہاتھ والی\"، ازواج مطہرات ایک بانس کی کھپچی لے کر ایک دوسرے کا ہاتھ ناپنے لگیں، تو وہ ام المؤمنین سودہ رضی اللہ عنہا تھیں جو سب سے پہلے آپ سے ملیں، وہی سب میں لمبے ہاتھ والی تھیں، یہ ان کے بہت زیادہ صدقہ و خیرات کرنے کی وجہ سے تھا ۱؎۔\n§وضاحت\n۱؎: یعنی آپ کی بیویوں میں سب سے پہلے انہیں کا انتقال ہوا، وہ لمبے ہاتھ والی اس معنی میں تھیں کہ وہ بہت زیادہ صدقہ و خیرات کرتی تھیں، بعض روایتوں میں سودہ کے بجائے زینب کا نام آیا ہے اور یہی زیادہ صحیح ہے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ نبی صلی اللہ علیہ وسلم کی ازواج مطہرات آپ کے پاس اکٹھی ہوئیں اور کہنے لگیں: ہم میں سے کون آپ سے جلدی ملے گی؟ آپ نے فرمایا: ’’جس کے ہاتھ سب سے لمبے ہوں گے۔‘‘ انھوں نے ایک بانس سے ہاتھ ماپنے شروع کر دیے (وہ آپ کی مراد یہی سمجھیں جس کا ہاتھ لمبا ہو)۔ (اس لحاظ سے) حضرت سودہ رضی اللہ عنہا آپ سے جلدی ملنے والی تھیں کیونکہ ان کے ہاتھ ان سب سے لمبے تھے۔ (دراصل) اس سے مراد صدقے کی کثرت تھی۔","f2":"(۱) یہ رسول اللہ صلی اللہ علیہ وسلم کے مرض وفات کی بات ہے۔ اور یہ سوال کرنے والی حضرت عائشہ رضی اللہ عنہا خود تھیں۔ (۲) یہ روایت مختصر ہے۔ اصل صورت واقعہ یہ ہے کہ ہاتھ ماپنے سے معلوم ہوا کہ حضرت سودہ رضی اللہ عنہا کے ہاتھ لمبے ہیں، لہٰذا سب کا خیال تھا کہ وہی پہلے فوت ہوں گی۔ ویسے بھی وہ عمر کے لحاظ سے سب سے بڑی تھیں، مگر اتفاق ایسا ہوا کہ حضرت زینب بنت جحش رضی اللہ عنہا پہلے فوت ہوگئیں۔ تو غور کرنے سے پتا چلا کہ ہاتھوں کی طوالت سے مراد ظاہری طوالت نہیں بلکہ صدقے کی کثرت تھی۔ (جس طرح ہم سخی شخص کو کھلے ہاتھوں والا کہہ دیتے ہیں) حضرت زینب رضی اللہ عنہا سخی کاتون تھیں۔ ویسے وہ قد کے لحاظ سے چھوٹی تھیں جبکہ حضرت سودہ رضی اللہ عنہا بڑے قد کاٹھ کی مالک تھیں۔ اللہ تعالیٰ ان سب سے راضی ہو۔ ترجمے میں قوسین وغیرہ کے ذریعہ سے کوشش کی گئی ہے کہ روایت اصل صورت حال کے مطابق ہو جائے ورنہ روایت کے ظاہر الفاظ سے معلوم ہوتا ہے کہ حضرت سودہ رضی اللہ عنہا سب سے پہلے فوت ہوگئیں، حالانکہ یہ بات تاریخی لحاظ سے غلط ہے۔ حضرت سودہ رضی اللہ عنہا تو حضرت معاویہ رضی اللہ عنہ کے دور خلافت میں ۵۴ہجری میں فوت ہوئیں اور حضرت زینب رضی اللہ عنہا حضرت عمر رضی اللہ عنہ کے دور خلافت میں ۳۰ ہجری میں ازواج مطہرات میں سب سے پہلے فوت ہوئیں۔ یہ بات تاریخی طور پر متفق عطیہ ہے۔ اور بعض احادیث میں بھی یہ تفصیل ہے۔"}],[2542,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کیا: کون سا صدقہ افضل ہے؟ آپ نے فرمایا: تمہارا اس وقت کا صدقہ دینا افضل ہے جب تم تندرست ہو اور تمہیں دولت کی حرص ہو اور تم عیش و راحت کی آرزو رکھتے ہو اور محتاجی سے ڈرتے ہو۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم سے ایک آدمی نے پوچھا: اے اللہ کے رسول! کون سا صدقہ افضل ہے؟ آپ نے فرمایا: ’’تو اس حال میں صدقہ کرے کہ تو تندرست ہو اور مال کا خواہش مند ہو۔ زندگی کی امید رکھتا ہو اور فقر سے ڈرتا ہو۔‘‘","f2":"جب انسان خود مال کی خواہش رکھتا ہو، ضرورت مند بھی ہو اور زندگی کی بھی امید ہو تو اس وقت صدقہ کرنا افضل ہے، لیکن جب مال زیادہ ہو یا زندگی کی امید نہ ہو، قریب الوفات ہو تو خرچ کرنے کی وہ فضیلت نہیں۔ گویا اللہ کے نزدیک گنتی کے بجائے وہ دلی حالت معتبر ہے جس کے ساتھ صدقہ کیا جاتا ہے۔"}],[2543,"حکیم بن حزام رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بہترین صدقہ وہ ہے جو مالداری کی پشت سے ہو (یعنی مالداری باقی رکھتے ہوئے ہو)، اور اوپر والا ہاتھ (دینے والا ہاتھ) نیچے والے ہاتھ (لینے والا ہاتھ) سے بہتر ہے، اور پہلے صدقہ انہیں دو جن کی تم کفالت کرتے ہو\"۔","الألباني: صحيح",{"u2":"حضرت حکیم بن حزام رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’افضل صدقہ وہ ہے جس کے بعد غنا باقی رہے اور اوپر والا ہاتھ نیچے والے ہاتھ سے بہتر ہے۔ اور سب سے پہلے اس شخص کو دے جس کا تو ذمے دار ہے۔‘‘"}],[2544,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: \"بہترین صدقہ وہ ہے جو مالداری کی پشت سے ہو ۱؎، اور ان سے شروع کرو جن کی کفالت تمہارے ذمہ ہے\"۔\n§وضاحت\n۱؎: یعنی آدمی صدقہ دے کر محتاج نہ ہو جائے، بلکہ اس کی مالداری برقرار رہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بہترین صدقہ وہ ہے جس کے بعد غنا باقی رہے اور پہلے اس شخص کو دے جس کا تو ذمے دار (کفیل) ہے۔‘‘","f2":"پہلی حدیث میں افضل صدقے سے پہلی حالت کا بیان ہے اور اس میں افضل صدقے کے بعد والی حالت کا بیان ہے۔"}],[2545,"ابومسعود رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب آدمی اپنی بیوی پر خرچ کرے اور اس سے ثواب کی امید رکھتا ہو تو یہ اس کے لیے صدقہ ہو گا\"۔","الألباني: صحيح",{"u2":"حضرت ابو مسعود رضی اللہ عنہ سے منقول ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: ’’جب آدمی اپنے گھر والوں پر ثواب کی نیت سے خرچ کرے تو وہ اس کے لیے صدقہ ہے۔‘‘","f2":"گھر والوں کی ضروریات کے لیے خرچ کرنا بھی صدقہ ہے، یعنی اس سے بھی ثواب حاصل ہوگا بشرطیکہ نیت رکھے۔"}],[2546,"جابر رضی اللہ عنہ کہتے ہیں کہ بنی عذرہ کے ایک شخص نے اپنے غلام کو مدبر کر دیا ۱؎، یہ خبر رسول اللہ صلی اللہ علیہ وسلم کو پہنچی تو آپ نے اس شخص سے پوچھا: \"کیا تمہارے پاس اس غلام کے علاوہ بھی کوئی مال ہے؟\" اس نے کہا: نہیں، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اسے مجھ سے کون خرید رہا ہے؟\" تو نعیم بن عبداللہ عدوی نے اسے آٹھ سو درہم میں خرید لیا، تو رسول اللہ صلی اللہ علیہ وسلم ان درہموں کو لے کر آئے اور انہیں اس کے حوالہ کر دیا، اور فرمایا: \"پہلے خود سے شروع کرو اسے اپنے اوپر صدقہ کرو اگر کچھ بچ رہے تو تمہاری بیوی کے لیے ہے، اور اگر تمہاری بیوی سے بھی بچ رہے تو تمہارے قرابت داروں کے لیے ہے، اور اگر تمہارے قرابت داروں سے بھی بچ رہے تو اس طرح اور اس طرح کرو، اور آپ اپنے سامنے اور اپنے دائیں اور بائیں اشارہ کر رہے تھے\" ۲؎۔\n§وضاحت\n۱؎: یعنی یہ کہہ دیا ہو کہ تم میرے مرنے کے بعد آزاد ہو۔ ۲؎: مطلب یہ ہے کہ اپنے پاس پڑوس کے محتاجوں اور غریبوں کو دے۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ بیان کرتے ہیں کہ بنو عذرہ (قبیلے) کے ایک آدمی نے اپنے غلام کو اپنی موت کے بعد آزاد کر دیا۔ یہ بات رسول اللہ صلی اللہ علیہ وسلم کو پہنچی تو آپ نے فرمایا: ’’تیرے پاس اس کے علاوہ کوئی اور مال ہے؟‘‘ اس نے کہا: نہیں۔ آپ نے فرمایا: ’’اسے مجھ سے کون خریدے گا؟‘‘ تو حضرت نعیم بن عبداللہ عدوی رضی اللہ عنہ نے اسے آٹھ سو درہم مین خرید لیا اور وہ یہ رقم لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے۔ آپ نے یہ رقم اس شخص کے سپرد کی، پھر فرمایا: ’’سب سے پہلے اپنے آپ پر خرچ کر۔ اگر کچھ بچ جائے تو وہ تیرے گھر والوں کے لیے ہے۔ اگر گھر والوں (کی ضروریات) سے کچھ بچ جائے تو وہ تیرے قرابت داروں کے لیے ہے۔ اور اگر تیرے قرابت داروں سے بھی بچ جائے تو پھر تو اسے اپنے آگے اور اپنے دائیں بائیں صدقہ کر۔‘‘","f2":"(۱) کوئی شخص اپنی زندگی کی حالت میں کہے کہ یہ غلام میرے مرنے کے بعد آزاد ہوگا۔ اسے عربی زبان میں تدبیر کہتے تھے اور اس کا عام رواج تھا۔ شریعت نے بھی اسے تسلیم کیا ہے۔ اس صورت میں اس کی موت کے بعد واقعتا وہ غلام آزاد ہوگا، لیکن اس کی حیثیت وصیت جیسی ہے جس کا نفاذ صرف ایک تہائی ملکیت میں ہو سکتا ہے۔ (۲) مذکورہ شخص کے پاس صرف وہ غلام ہی کل مال تھا۔ ظاہر ہے وصیت ایک تہائی مال سے زائد نہیں ہو سکتی، لہٰذا نبی صلی اللہ علیہ وسلم نے اس کے عمل تدبیر کو اپنے حکم سے توڑ دیا بلکہ اس غلام کو فروخت کر دیا تاکہ اس شخص کی موت کی صورت میں وہ آزاد نہ ہو سکے۔ (۳) ایسے غلام کو بیچنا جائز نہیں ہوتا مگر مخصوص حالات میں (جب تدبیر غلط ہو) اسے فروخت کیا جا سکتا ہے۔ حکومت بیچنے یا وہ شخص خود، مگر اس سے یہ استدلال درست نہیں کہ ہر مدبر کو بیچنا درست ہے۔ تفصیل ان شاء اللہ آگے آئے گی۔ (۴) ’’آگے اور دائیں بائیں۔‘‘ یعنی جہاں مناسب سمجھے صدقہ کر۔ یہ ایک محاورہ ہے ظاہر الفاظ مراد نہیں۔"}],[2547,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"صدقہ کرنے والے فیاض اور بخیل کی مثال ان دو آدمیوں کی سی ہے جن پر لوہے کے دو کرتے یا دو ڈھال ان دونوں کی چھاتیوں سے لے کر ان کی ہنسلی کی ہڈیوں تک ہوں، جب فیاض خرچ کرنے کا ارادہ کرتا ہے تو اس کی زرہ اس کے بدن پر کشادہ ہو جاتی ہے، پھیل کر اس کی انگلیوں کے پوروں کو ڈھانپ لیتی ہے، اور اس کے نشان قدم کو مٹا دیتی ہے، اور جب بخیل خرچ کرنے کا ارادہ کرتا ہے تو وہ سکڑ جاتی ہے اور اس کی کڑیاں اپنی جگ ہوں پر چمٹ جاتی ہیں یہاں تک کہ وہ اس کی ہنسلی یا اس کی گردن پکڑ لیتی ہے\"۔ ابوہریرہ رضی اللہ عنہ کہتے ہیں: میں گواہی دیتا ہوں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ اسے کشادہ کر رہے تھے، اور وہ کشادہ نہیں ہو رہی تھی۔ طاؤس کہتے ہیں: میں نے ابوہریرہ رضی اللہ عنہ کو کہتے سنا کہ آپ اپنے ہاتھ سے کشادہ کرنے کے لیے اشارہ کر رہے تھے، اور وہ کشادہ نہیں ہو رہی تھی۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’صدقہ کرنے والے کی اور کنجوس شخص کی مثال ان دو آدمیوں کی طرح ہے جن کے جسم پر لوہے کے کرتے یا زرہیں ہوں، جنھوں نے ان کے سینوں کو ڈھانپ رکھا ہو۔ جب سخی خرچ کرنے کا ارادہ کرتا ہے تو اس کی زرہ کھل جاتی ہے اور وسیع ہو جاتی ہے حتیٰ کہ اس کی انگلیوں کے پوروں کو ڈھانپ لیتی ہے اور اس کے نشانات قدم کو مٹا دیتی ہے۔ اور جب بخیل خرچ کرنے کا ارادہ کرتا ہے تو اس کی زرہ سکڑ جاتی ہے اور ہر کڑی اپنی جگہ سمٹ جاتی ہے حتیٰ کہ اس کے حلق یا گلے کو پکڑ لیتی ہے۔‘‘ حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں گواہی دیتا ہوں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا (جیسے) آپ اسے کھول رہے ہیں اور وہ کھلتی نہیں۔ (حضرت ابوہریرہ کے شاگرد) طاؤس نے کہا: حضرت ابوہریرہ رضی اللہ عنہ بھی اپنے ہاتھ سے اسے کھولنے کا اشارہ کرتے تھے لیکن وہ کھلتی نہ تھی۔","f2":"(۱) ’’لوہے کے کُرتے یا زرہیں۔‘‘ زرہ چمڑے کی بھی ہوتی ہے، اس لیے لوہے کی صراحت فرمائی کہ تاکہ آئندہ مثال میں زور پیدا ہو۔ (۲) ’’سینوں کو۔‘‘ ویسے بھی زرہ سینے کے لیے ہوتی ہے۔ یہاں خصوصاً سینے کا ذکر اس لیے ہے کہ انسان کا دل، جس سے سخاوت اور کنجوسی کا تعلق ہے، سینے میں ہوتا ہے۔ اس مثال میں زرہ سے مراد نفس کا شکنجہ ہے جو وہ روح پر چڑھائے رکھتا ہے جو روحانی کمالات کے ظہور سے مانع ہوتا ہے۔ (۳) ’’کھل جاتی ہے۔‘‘ یعنی سخی کا دل اس شکنجے کو کھول دیتا ہے حتیٰ کہ سخاوت کا اثر پورے جسم پر نمایاں ہوتا ہے اور اس کے ہاتھ بھی کھل کر سخاوت کرتے ہیں۔ نشانات قدم کو مٹانے سے مراد اس کی غلطیوں کو ختم کرنا ہے۔ یا مطلب یہ ہے کہ جس طرح یہ زرہ اس کے سارے جسم کو ڈھانپ لیتی ہے، اسی طرح قیامت کے دن اللہ تعالیٰ اس کے عیوب کی پردہ پوشی فرمائے گا۔ (۴) ’’سکڑ جاتی ہے۔‘‘ یعنی اس کا دل تنگ ہو جاتا ہے اور وہ صدقہ کرنے کی ہمت نہیں پاتا حتیٰ کہ اس کے لیے صدقہ کرنا اپنا گلا گھونٹنے والی بات بن جاتی ہے۔ جس طرح زرہ اس کے گلے تک سکڑ گئی، اسی طرح اس کا دل تنگ ہو جااتا ہے اور اسے صدقے کی توفیق نہیں ہو پاتی۔"}],[2548,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"بخیل اور صدقہ دینے والے (سخی) کی مثال ان دو شخصوں کی ہے جن پر لوہے کی زرہیں ہوں، اور ان کے ہاتھ ان کی ہنسلیوں کے ساتھ چمٹا دیئے گئے ہوں، تو جب جب صدقہ کرنے والا صدقہ کرنے کا ارادہ کرتا ہے تو اس کی زرہ اس کے لیے وسیع و کشادہ ہو جاتی ہے یہاں تک کہ وہ اتنی بڑی ہو جاتی ہے کہ چلتے وقت اس کے پیر کے نشانات کو مٹا دیتی ہے، اور جب بخیل صدقہ کرنے کا ارادہ کرتا ہے تو ہر کڑی دوسرے کے ساتھ پیوست ہو جاتی اور سکڑ جاتی ہے، اور اس کے ہاتھ اس کی ہنسلی سے مل جاتے ہیں\" میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: \"وہ(بخیل) کوشش کرتا ہے کہ اسے کشادہ کرے لیکن وہ کشادہ نہیں ہوتی\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کنجوس کی اور صدقہ کرنے والے کی مثال ان دو آدمیوں کی طرح ہے جن پر لوہے کی زرہیں ہیں اور ان کے ہاتھ ان کے سینے کے اوپر بندھے ہوئے ہیں۔ صدقہ کرنے والا شخص جب صدقہ کرنے کا ارادہ کرتا ہے تو اس کی زرہ کھل جاتی ہے۔ حتیٰ کہ اس کے نشانات قدم تک کو مٹا ڈالتی ہے۔ اور جب بخیل آدمی صدقے کا ارادہ کرتا ہے تو زرہ کی ہر کڑی دوسری کڑی سے جڑ جاتی (اس میں پیوست ہو جاتی) ہے اور زرہ سکڑ جاتی ہے اور اس کے ہاتھ سینے سے بندھے رہتے ہیں۔‘‘ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’وہ زرہ کو کھولنے کی پوری کوشش کرتا ہے لیکن وہ کھلتی نہیں۔‘‘","f2":"سخی آدمی صدقہ کرنے کا ارادہ کرتا ہے تو اس کا دل فراخ ہو جاتا ہے، ہاتھ کھل جاتے ہیں اور تمام رکاوٹیں دور ہو جاتی ہیں۔ اور کنجوس شخص صدقے کا ارادہ کرے بھی تو اس کا دل مزید تنگ ہو جاتا ہے، گویا کہ ہاتھ بندھے ہوئے ہیں۔ وہ زنجیروں میں جکڑے شخص کی طرح لا چار ہو جاتا ہے اور صدقہ نہیں کر پاتا۔ أَعَاذَنَا اللّٰہُ مِنْہ"}],[2549,"ابوامامہ بن سہل بن حنیف رضی اللہ عنہ کہتے ہیں کہ ہم لوگ ایک دن مسجد میں بیٹھے ہوئے تھے ہمارے ساتھ کچھ مہاجرین و انصار بھی تھے، ہم نے ایک شخص کو ام المؤمنین عائشہ رضی اللہ عنہا کے پاس ملاقات کی اجازت حاصل کرنے کے لیے بھیجا، (انہوں نے اجازت دے دی، ہم ان کے پاس پہنچی تو انہوں نے کہا: ایک بار میرے پاس ایک مانگنے والا آیا اس وقت رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف فرما تھے، میں نے (خادمہ کو) اسے کچھ دینے کا حکم دیا، پھر میں نے اسے بلایا اسے دیکھنے لگی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کیا آپ چاہتی ہیں کہ بغیر آپ کے علم میں آئے تمہارے گھر میں کچھ نہ آئے اور تمہارے گھر سے کچھ نہ جائے؟\" میں نے کہا: جی ہاں، آپ نے فرمایا: \"عائشہ! ٹھہر جاؤ، گن کر نہ دو کہ اللہ عزوجل بھی تمہیں بھی گن کر دے\"۔","الألباني: حسن",{"u2":"حضرت ابو امامہ بن سہل بن حنیف رضی اللہ عنہ سے مروی ہے کہ ہم ایک دن مہاجرین وانصار کی ایک جماعت کے ساتھ مسجد نبوی میں بیٹھے تھے کہ ہم نے حضرت عائشہ رضی اللہ عنہا کے پاس ایک شخص کو بھیجا تاکہ وہ ہمارے لیے (ان کے ہاں حاضر ہونے کی) اجازت طلب کرے۔ (اجازت ملنے پر) ہم ان کی خدمت میں حاضر ہوئے تو انھوں نے فرمایا کہ ایک دفعہ ایک سائل میرے پاس آیا۔ میرے پاس رسول اللہ صلی اللہ علیہ وسلم بھی تشریف فرما تھے۔ میں نے (لونڈی سے) اسے کچھ دینے کو کہا، پھر میں نے وہ چیز منگوا کر دیکھی (کہ وہ کس قدر ہے؟) رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’عائشہ! تو چاہتی ہے کہ تیرے گھر میں کوئی چیز تیرے علم کے بغیر نہ آئے اور نہ (وہاں سے) جائے؟‘‘ میں نے عرض کیا: جی ہاں! آپ نے فرمایا: ’’عائشہ ایسے نہ کرو۔ گن گن کر صدقہ نہ کیا کرو، ورنہ اللہ تعالیٰ بھی تجھے گن گن کر دے گا۔‘‘","f2":"جس طرح ہم چاہتے ہیں کہ اللہ تعالیٰ ہمیں بے حساب رزق دے، اسی طرح ہمیں گنے بغیر صدقات کرتے رہنا چاہیے کیونکہ افعال کا بدلہ ان کی مثل ہوتا ہے۔ اس حدیث میں اللہ تعالیٰ کے گننے کا ذکر تشاکل کے طور پر ہے ورنہ اللہ تعالیٰ گننے سے بے نیاز ہے۔ وہ گنے بغیر ہر چیز کو جانتا ہے۔ دراصل یہاں گننے سے مراد کم دینا ہے کیونکہ تھوڑی چیز ہی گنی جاتی ہے۔ زیادہ چیز تو بے حساب ہی دی جاتی ہے۔ یاد رہے یہ نفل صدقے کی بات ہے ورنہ فرض صدقات تو حساب کر کے ہی دیے جاتے ہیں اور وہ حساب خود شریعت نے مقرر کیا ہے۔"}],[2550,"اسماء بنت ابی بکر رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ان سے فرمایا: \"گن کر نہ دو کہ اللہ عزوجل بھی تمہیں گن کر دے\"۔","الألباني: صحيح",{"u2":"حضرت اسماء بنت ابی بکر رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا تھا: ’’گن گن کر اللہ کے راستے میں نہ دے ورنہ اللہ تعالیٰ بھی تجھے گن گن کر دے گا۔‘‘"}],[2551,"اسماء بنت ابی بکر رضی اللہ عنہا سے روایت ہے کہ وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس آئیں، اور کہنے لگیں: اللہ کے نبی! میرے پاس تو کچھ ہوتا نہیں ہے سوائے اس کے کہ جو زبیر (میرے شوہر) مجھے (کھانے یا خرچ کرنے کے لیے) دے دیتے ہیں، تو کیا اس دیے ہوئے میں سے میں کچھ (فقراء و مساکین کو) دے دوں تو مجھ پر گناہ ہو گا؟ آپ نے فرمایا: \"تم جو کچھ دے سکو دو، اور روکو نہیں کہ اللہ عزوجل بھی تم سے روک لے\"۔","الألباني: صحيح",{"u2":"حضرت اسماء بنت ابی بکر رضی اللہ عنہ سے مروی ہے کہ میں نبی صلی اللہ علیہ وسلم کے پاس حاضر ہوئی اور عرض کیا: اے اللہ کے نبی! میرے پاس ذاتی مال تو کوئی نہیں مگر جو (میرے خاوند) حضرت زبیر رضی اللہ عنہ مجھے لا کر دیتے ہیں، کیا مجھے گناہ ہوگا اگر میں اس سے عطیہ وغیرہ دوں؟ آپ نے فرمایا: ’’جتنی گنجائش ہو، عطیے دے اور باندھ باندھ کر نہ رکھ ورنہ اللہ تعالیٰ بھی تجھ پر باندھ دے گا۔‘‘","f2":"(۱) باندھ کر رکھنے سے مراد کنجوسی ہے کہ اگر تو اللہ تعالیٰ کے راستے میں نہ دے گی تو اللہ تعالیٰ بھی تجھ سے رزق روک لے گا۔ اللہ تعالیٰ کے لیے باندھنے کا ذکر تشاکل (علم معانی کی ایک اصطلاح) کے طور پر ہے اور اس میں کوئی حرج نہیں۔ (۲) اس روایت میں عطیات سے مراد وہ چھوٹے چھوٹے عطیات ہیں جن کی عرفاً ہر گھر میں اجازت ہوتی ہے۔ اگر زیادہ مال دینا ہو تو خاوند کی اجازت ضروری ہے کیونکہ وہ مال کا اصل مالک ہے۔ اگرچہ ہر چیز اللہ ہی کی ہے۔"}],[2552,"عدی بن حاتم رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"آگ سے بچو، اگرچہ کھجور کا ایک ٹکڑا اللہ کی راہ میں دے کر سہی\"۔","الألباني: صحيح",{"u2":"حضرت عدی بن حاتم رضی اللہ عنہ سے منقول ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’آگ سے بچو اگرچہ کھجور کے ایک ٹکڑے ہی کے ذریعے سے۔‘‘","f2":"یہ ایک فرضی بات ہے، یعنی جو میسر ہے صدقہ کرو۔ غریب اپنے تھوڑے مال سے اور امیر زیادہ مال سے، نیز چھوٹی نیکی کو حقیر نہ سمجھا جائے۔ ممکن ہے وہی نیکی خلوص کی وجہ سے نجات اور کامیابی کا ذریعہ بن جائے۔"}],[2553,"عدی بن حاتم رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے جہنم کا ذکر کیا، اور نفرت سے اپنا منہ پھیر لیا، اور اس سے پناہ مانگی۔ شعبہ نے ذکر کیا کہ آپ نے تین دفعہ ایسا کیا، پھر فرمایا: \"آگ سے بچو اگرچہ کھجور کا ایک ٹکڑا ہی اللہ کی راہ میں دے کر سہی۔ اور اگر اسے نہ پاس کو تو بھلی بات کے ذریعہ معذرت کر کے سہی\"۔","الألباني: صحيح",{"u2":"حضرت عدی بن حاتم رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے آگ کا ذکر فرمایا، پھر آپ نے (نفرت وکراہت سے) اپنا منہ پھیرا اور آگ سے اللہ کی پناہ طلب کی۔ شعبہ (راوی) نے کہا کہ آپ نے تین دفعہ ایسے ہی کیا، پھر آپ نے فرمایا: ’’(جہنم کی) آگ سے بچو اگرچہ کھجور کے ایک ٹکڑے ہی کے ذریعے سے۔ اگر یہ بھی نہ ملے تو اچھی بات ہی کر کے(آگ سے بچو)۔‘‘","f2":"(۱) یعنی جہنم سے بچاؤ اور جنت میں دخول صرف مالداروں ہی کے لیے خاص نہیں۔ فقیر لوگ بھی حسن نیت کے ساتھ معمولی چیز خرچ کر کے سخاوت کا درجہ حاصل کر سکتے ہیں۔ اگر بالفرض کسی کے پاس کچھ بھی نہ ہو تب بھی اس کے پاس اللہ تعالیٰ کی نعمت زبان تو ہے ہی۔ اس کے ساتھ بھی یہ مقصود حاصل ہو سکتا ہے۔ نیک کلمہ منہ سے نکالیں، کسی کو برا نہ کہیں، امر بالمعروف اور نہی عن المنکر کریں، مسکرا کر ملیں، پاکیزہ بات کریں، شر سے زبان بند رکھیں، نجات اور کامیابی میسر ہوگی۔ ان شاء اللہ (۲) راوی حدیث حصرت عدی رضی اللہ عنہ عرب کے ایک مشہور اور سخی شخص حاتم طائی کے فرزند تھے۔"}],[2554,"جریر بن عبداللہ رضی اللہ عنہ کہتے ہیں کہ ہم دن کے ابتدائی حصہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس بیٹھے ہوئے تھے، کچھ لوگ ننگے بدن، ننگے پیر، تلواریں لٹکائے ہوئے آئے، زیادہ تر لوگ قبیلہ مضر کے تھے، بلکہ سبھی مضر ہی کے تھے۔ ان کی فاقہ مستی دیکھ کر رسول اللہ صلی اللہ علیہ وسلم کے چہرے کا رنگ بدل گیا، آپ اندر گئے، پھر نکلے، تو بلال رضی اللہ عنہ کو حکم دیا، انہوں نے اذان دی، پھر اقامت کہی، آپ نے نماز پڑھائی، پھر آپ نے خطبہ دیا، تو فرمایا: \"لوگو! ڈرو، تم اپنے رب سے جس نے تم کو ایک جان سے پیدا کیا، اور اسی جان سے اس کا جوڑا بنایا۔ اور انہیں دونوں (میاں بیوی) سے بہت سے مرد اور عورتیں پھیلا دیئے۔ اور اس اللہ سے ڈرو جس کے واسطے سے تم سب ایک دوسرے سے مانگتے ہو۔ قرابت داریوں کا خیال رکھو کہ وہ ٹوٹنے نہ پائیں، بیشک اللہ تمہارا نگہبان ہے، اور اللہ سے ڈرو، اور تم میں سے ہر شخص یہ (دھیان رکھے اور) دیکھتا رہے کہ آنے والے کل کے لیے اس نے کیا آگے بھیجا ہے، آدمی کو چاہیئے کہ اپنے دینار میں سے، اپنے درہم میں سے، اپنے کپڑے میں سے، اپنے گیہوں کے صاع میں سے، اپنے کھجور کے صاع میں سے صدقہ کرے\"، یہاں تک کہ آپ نے فرمایا: \"اگرچہ کھجور کا ایک ٹکڑا ہی سہی\"، چنانچہ انصار کا ایک شخص (روپیوں سے بھری) ایک تھیلی لے کر آیا جو اس کی ہتھیلی سے سنبھل نہیں رہی تھی بلکہ سنبھلی ہی نہیں۔ پھر تو لوگوں کا تانتا بندھ گیا۔ یہاں تک کہ میں نے دیکھا کہ کھانے اور کپڑے کے دو ڈھیر اکٹھے ہو گئے۔ اور میں نے دیکھا کہ رسول اللہ صلی اللہ علیہ وسلم کا چہرہ انور کھل اٹھا ہے گویا وہ سونے کا پانی دیا ہوا چاندی ہے (اس موقع پر) رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص اسلام میں کوئی اچھا طریقہ جاری کرے گا، اس کے لیے دہرا اجر ہو گا: ایک اس کے جاری کرنے کا، دوسرا جو اس پر عمل کریں گے ان کا اجر، بغیر اس کے کہ ان کے اجر میں کوئی کمی کی جائے۔ اور جس نے اسلام میں کوئی برا طریقہ جاری کیا، تو اسے اس کے جاری کرنے کا گناہ ملے گا اور جو اس اس پر عمل کریں گے ان کا گناہ بھی بغیر اس کے کہ ان کے گناہ میں کوئی کمی کی جائے\"۔","الألباني: صحيح",{"u2":"حضرت جریر رضی اللہ عنہ بیان کرتے ہیں کہ ہم دن کے آغاز میں رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر تھے کہ کچھ لوگ آئے، ننگے بدن، ننگے پاؤں، تلواریں لٹکائے ہوئے۔ وہ اکثر بلکہ سب کے سب مضر قبیلے سے تھے۔ ان کی تنگ حالی اور بھوک دیکھ کر رسول اللہ صلی اللہ علیہ وسلم کا چہرہ انور متغیر (مغموم) ہوگیا۔ آپ اندر (گھر) گئے (مگر کچھ نہ ملا تو) پھر باہر تشریف لے آئے اور بلال رضی اللہ عنہ کو اذان دینے کا حکم دیا۔ انھوں نے اذان واقامت کہی۔ آپ نے جماعت کروائی، پھر آپ نے خطبہ ارشاد فرمایا: {یٰٓاَیُّھَا النَّاسُ اتَّقُوْا… رَقِیْبًا} ’’اے لوگو! اپنے رب سے ڈرو جس نے تم سب کو ایک جان سے پیدا فرمایا اور اس سے اس کی بیوی پیدا کی اور پھر ان دونوں سے بہت سے مرد اور عورتیں پھیلائے۔ اور اللہ تعالیٰ سے ڈرتے رہو جس کا نام لے کر ایک دوسرے سے مانگتے ہو اور رشتے توڑنے سے (بھی) ڈرو۔ یقینا اللہ تعالیٰ تم پر نگران ہے۔‘‘ {وَاتَّقُوْا اللّٰہَ… لِغَدٍ} ’’اللہ تعالیٰ سے ڈرو اور ہر شخص دیکھے کہ اس نے کل (اگلی زندگی) کے لیے کیا آگے بھیجا ہے۔‘‘ آدمی اپنے دینار سے صدقہ کرے، اپنے درہم سے صدقہ کرے، اپنے کپڑے سے صدقہ کرے، گندم کا صاع دے، کھجور کا صاع دے۔‘‘ حتی کہ آپ نے فرمایا: ’’چاہے کھجور کا ٹکڑا ہی صدقہ کرے۔‘‘ انصار میں سے ایک آدمی اتنی بھاری تھیلی اٹھا کر لایا کہ اس کی ہتھیلی اس سے عاجز ہو رہی تھی بلکہ عاجز ہو ہی گئی تھی، پھر تو لوگوں کا تانتا بندھ گیا حتیٰ کہ میں نے دو ڈھیر دیکھے۔ ایک غلے کا اور ایک کپڑوں کا، حتیٰ کہ رسول اللہ صلی اللہ علیہ وسلم کا چہرۂ انور یوں (خوشی سے) دمکنے لگا گویا کہ اس پر سونا چڑھا دیا گیا ہو۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص نے اسلام میں کوئی اچھا طریقہ جاری کیا، اسے اپنا ثواب بھی ملے گا اور جتنے لوگ اسے دیکھ کر وہ کام کریں گے، ان کے اجر میں سے بھی اسے حصہ ملے گا، بغیر اس کے کہ ان کے ثواب میں کوئی کمی ہو۔ اسی طرح جو شخص اسلام میں برا کام جاری کر دے، اس پر اس کا اپنا گناہ بھی ہوگا اور ان لوگوں کا بھی جو اسے دیکھ کر وہ کام کریں گے، لیکن اس سے ان کے گناہوں میں کوئی کمی نہ ہوگی۔‘‘","f2":"’’اچھا طریقہ جاری کیا۔‘‘ بشرطیکہ وہ کام شریعت میں موجود ہو، جیسے مندرجہ بالا واقعہ میں انصاری نے نیک کام میں پہل کی اور لوگوں نے اسے دیکھ کر صدقات کیے۔ اور صدقہ شریعت میں مشروع ہے۔ اگر کوئی شخص ایسا کام جاری کرے جو شریعت میں موجود نہ ہو تو یہ بدعت ہوگی، خواہ وہ ظاہر میں نیک کام ہی نظر آئے کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص دین میں ایسا کام رائج کرے جو دین سے نہ ہو تو وہ مردود ہے۔‘‘ (صحیح البخاری، الصلح، حدیث: ۲۶۹۷، وصحیح مسلم، الاقضیۃ، حدیث: ۱۷۱۸) کیونکہ اس طرح دین میں تحریف ہو جائے گی اور دین کی اصل شکل وصورت قائم نہ رہے گی۔"}],[2555,"حارثہ بن وہب رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا کہ صدقہ کرو کیونکہ تم پر ایک زمانہ ایسا آئے گا کہ آدمی اپنا صدقہ لے کر دینے چلے گا تو جس شخص کو وہ دینے جائے گا وہ شخص کہے گا: اگر تم کل لے کر آئے ہوتے تو میں لے لیتا، لیکن آج تو آج نہیں لوں گا ۱؎۔\n§وضاحت\n۱؎: کیونکہ آج میں مالدار ہو گیا ہوں۔","الألباني: صحيح",{"u2":"حضرت حارثہ رضی اللہ عنہ سے مروی ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’صدقہ کرو اس لیے کہ ایک ایسا زمانہ آنے والا ہے کہ آدمی صدقہ لے کر چلے گا۔ (کہ کسی کو دے) مگر جسے وہ صدقہ دیا جائے گا، وہ کہے گا: اگر تو کل لے آتا تو میں قبول کر لیتا، آج نہیں۔‘‘","f2":"(۱) ’’ایسا زمانہ‘‘ واقعتا رسول اللہ صلی اللہ علیہ وسلم کی وفات کے بعد ایسا زمانہ آیا۔ قرب قیامت بھی ایسی صورت حال پیدا ہوجائے گی کہ دولت عام ہو جائے گی۔ صدقہ تو ایک طرف رہا، کوئی دولت (سونا وغیرہ) نہ اٹھائے گا۔ دیکھیے: (صحیح مسلم، الزکاۃ، حدیث: ۱۰۱۳) (۲) ’’کل‘‘ ضروری نہیں حقیقتاً گزشتہ کل ہی مراد ہو، بلکہ مراد اس سے پہلے کا زمانہ بھی ہو سکتا ہے، چاہے وہ سال دو سال یا اس سے کم و بیش ہی ہو۔"}],[2556,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"سفارش کرو تمہاری سفارش قبول کی جائے گی، اللہ اپنے نبی کریم صلی اللہ علیہ وسلم کی زبان سے جو چاہے فیصلہ فرمائے\"۔","الألباني: صحيح",{"u2":"حضرت ابو موسیٰ رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’سفارش کرو۔ تمہاری سفارش قبول کی جائے گی۔ اور اللہ تعالیٰ اپنے نبی صلی اللہ علیہ وسلم کی زبانی جو چاہے گا، فیصلہ فرمائے گا۔‘‘","f2":"(۱) ’’سفارش کرو۔‘‘ یعنی جب کوئی حاجت مند مانگنے آئے تو تم اس کے حق میں سفارش کر دیا کرو۔ (۲) ’’تمہاری سفارش قبول ہوگی۔‘‘ اگر وہ قابل تسلیم ہوئی، یا مطلب ہے کہ تمہیں سفارش کا ثواب ملے گا جیسا کہ ایک دوسری روایت میں اس مفہوم کی صراحت ہے: [اِشْفَعُوا تُؤْجَرُوا] (صحیح البخاری، الزکاۃ، حدیث: ۱۴۳۲، وصحیح مسلم، البروالصلۃ، حدیث: ۲۶۲۷) یعنی معنی زیادہ مناسب ہیں۔ (۳) ’’فیصلہ فرمائے گا۔‘‘ یعنی فیصلہ تو نبی صلی اللہ علیہ وسلم کے ہاتھ میں ہے جو وہ الٰہی تعلیمات کی روشنی میں فرمائیں گے۔ تم سفارش کر کے ثواب حاصل کر لیا کرو۔"}],[2557,"معاویہ بن ابی سفیان رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"آدمی کوئی چیز مجھ سے مانگتا ہے تو میں نہیں دیتا، تاکہ تم اس سلسلہ میں سفارش کرو، اور سفارش کرنے کا اجر پاؤ\"، نیز رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سفارش کرو تمہیں سفارش کا اجر (ثواب) دیا جائے گا\"۔","الألباني: صحيح",{"u2":"حضرت معاویہ بن ابی سفیان رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ایک آدمی مجھ سے کوئی چیز مانگتا ہے اور میں انکار کر دیتا ہوں تاکہ تم سفارش کر کے ثواب حاصل کرو۔‘‘ تحقیق رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سفارش کیا کرو، تمھیں ثواب ملے گا۔‘‘"}],[2558,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک غیرت وہ ہے جسے اللہ تعالی پسند کرتا ہے، اور ایک غیرت وہ ہے جسے اللہ ناپسند کرتا ہے،(ایسے ہی) ایک فخر وہ ہے جسے اللہ تعالی پسند کرتا ہے، اور ایک فخر وہ ہے جسے اللہ تعالی ناپسند کرتا ہے، تو جس غیرت کو اللہ پسند کرتا ہے وہ تہمت کی جگہ کی غیرت ہے، اور وہ غیرت ۱؎ جو اللہ عزوجل کو ناپسند ہے تو وہ غیر تہمت کی جگہ کی غیرت ہے ۲؎ رہا فخر جو اللہ کو پسند ہے تو وہ آدمی کا لڑائی کے وقت یا صدقہ دیتے وقت اپنی ذات پر فخر ہے ۳؎ اور وہ فخر جو اللہ کو ناپسند ہے وہ یہ ہے کہ آدمی لغو اور بیہودہ کاموں پر فخر کرے\"۔\n§وضاحت\n۱؎: یعنی ایسی جگہوں میں جانے سے غیرت آئے جہاں بدنامی کا ڈر ہو جیسے غیر محرم کے ساتھ خلوت میں رہنے کی غیرت یا شراب خانہ میں جانے سے غیرت وغیرہ۔ ۲؎: یعنی ایسی جگہ میں غیرت کرے جہاں تہمت اور بدنامی کا خوف نہ ہو۔ ۳؎: اس لیے کہ اس سے دوسروں میں جہاد کرنے اور صدقہ و خیرات کرنے کا شوق پیدا ہو گا۔","الألباني: حسن",{"u2":"حضرت جابر رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ایک غیرت وہ ہے جسے اللہ عزوجل پسند فرماتا ہے اور ایک غیرت وہ ہے جسے اللہ تعالیٰ ناپسند فرماتا ہے۔ اسی طرح ایک فخر وہ ہے جسے اللہ تعالیٰ پسند فرماتا ہے اور ایک فخر وہ ہے جسے اللہ تعالیٰ ناپسند فرماتا ہے۔ پسندیدہ غیرت وہ ہے جو تہمت کے مقام پر ہو اور ناپسندیدہ غیرت وہ ہے جو بلا وجہ ہو۔ اسی طرح اللہ تعالیٰ کا پسندیدہ فخر وہ ہے جو آدمی لڑائی کے وقت کرے یا صدقہ کرتے وقت۔ اور ناپسندیدہ فخر وہ ہے جو باطل میں ہو۔‘‘","f2":"(۱) ’’تہمت کے مقام پر۔‘‘ یعنی جس کام سے انسان شرعاً یا عرفاً متہم قرار پاتا ہو اس کام کو غیرت کی بنا پر چھوڑ دیا جائے، مثلاً: بدنام لوگوں کے ساتھ میل جول رکھنا۔ مے خانے اور جوا خانے میں بیٹھنا اور اسی طرح غیر محرم عورت کے ساتھ تنہائی اور خلوت اختیار کرنا وغیرہ۔ (۳) ’’پسندیدہ فخر۔‘‘ لڑائی کے وقت فخریہ ہے کہ اپنی قوت و جرأت کا اظہار کرے تاکہ کفار مرعوب ہوں۔ فخریہ اشعار پڑھنا بھی اس میں داخل ہے۔ اور صدقے کے وقت فخریہ ہے کہ خوب دل کھول کر صدقہ کرے، بلکہ صدقے میں ایک دوسرے سے آگے بڑھے، کبھی کبھار دوسرے کو اپنے سے آگے بڑھنے کا چیلنج کرے۔ یاد رکھیے! اس سے ریا کاری یا وسائل پر فخر کرنا مراد نہیں کہ وہ تو گناہ کبیرہ ہے۔ ناجائز کام پر خرچ کرنا حرام ہے، خواہ ایک پیسہ ہو۔"}],[2559,"عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کھاؤ، صدقہ کرو، اور پہنو، لیکن اسراف (فضول خرچی) اور غرور (گھمنڈ و تکبر) سے بچو\"۔","الألباني: حسن",{"u2":"حضرت عمرو بن شعیب کے پردادا سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کھاؤ اور صدقہ کرو اور لباس پہنو مگر فضول خرچی اور تکبر نہ ہو۔‘‘","f2":"(۱) مذکورہ روایت کو محقق کتاب نے سنداً ضعیف قرار دیا ہے اور مزید لکھا ہے کہ اسے امام بخاری رحمہ اللہ نے کتاب اللباس سے پہلے معلق بیان کیا ہے جبکہ دیگر محققین نے اسے شواہد اور متابعات کی بنا پر حسن قرر دیا ہے۔ بنا بریں دلائل کی رو سے اصولی طور پر یہ روایت حسن درجے کی ہے۔ تفصیل کے لیے دیکھیے: (ذخیرۃ العقبی شرح سنن النسائی: ۲۳/ ۵۹، ۶۰، والموسوعۃ الحدیثیۃ مسند الامام احمد: ۱۱/ ۲۹۴، ۲۹۵، ۳۱۲، ۳۱۳ وھدایۃ الرواۃ: ۴/ ۲۱۷، ۲۱۸) (۲) فضول خرچی سے مراد ضرورت سے زائد خرچ کرنا یا حرام میں خرچ کرنا ہے۔ اور تکبر سے مراد یہ ہے کہ دوسروں کو حقیر سمجھے جو کھانے، پینے اور لباس وغیرہ میں اس سے کم درجے میں ہو۔"}],[2560,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مومن، مومن کے لیے عمارت کی طرح ہے جس کا ایک حصہ دوسرے حصے کو مضبوط کرتا ہے\"، نیز فرمایا: \"امانت دار خازن جو خوش دلی سے وہ چیز دے جس کا اسے حکم دیا گیا ہو تو وہ بھی صدقہ دینے والوں میں سے ایک ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوموسیٰ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ایک مومن دوسرے مومن کے لیے عمارت کی طرح ہے کہ اس کا ایک حصہ دوسرے حصے کو مضبوط کرتا ہے۔‘‘ نیز فرمایا: ’’امانت دار خازن جو خوش دلی سے وہ چیز (اللہ کے راستے میں) دیتا ہے، جس کا اسے حکم دیا گیا ہو، وہ بھی صدقے کرنے والوں میں شمار ہوتا ہے۔‘‘","f2":"(۱) اکیلی اکیلی اینٹ کوئی وقعت نہیں رکھتی مگر جب ایک دوسرے سے مل جائیں تو مضبوط دیوار بن جاتی ہے۔ اور دیواریں مل کر چار دیواری اور چھت کے ساتھ مکمل مکان بن جاتا ہے جو ہر قسم کے طوفانوں کا بلا کھٹکے مقابلہ کر سکتا ہے۔ مسلمانوں کو بھی ایک دوسرے کے ساتھ ایسے ہی ہونا چاہیے۔ (۲) ’’صدقہ کرنے والوں میں۔‘‘ کیونکہ ظاہراً تو صدقہ وہی کر رہا ہے۔ صدقہ کرنے والوں سے مراد سب صدقہ کرنے والے یا یہ دو شخص مالک اور خزانچی ہیں۔ یاد رہے کہ مالک کو اس کی ملکیت کی بنا پر ثواب ملے گا اور خزانچی کو اس کے فعل پر ضروری نہین کہ دونوں ثواب میں برابر ہوں۔"}],[2561,"عقبہ بن عامر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بلند آواز سے قرآن پڑھنے والا اعلانیہ صدقہ کرنے والے کی طرح ہے، اور دھیرے سے قرآن پڑھنے والا چھپا کر صدقہ دینے والے کی طرح ہے\"۔","الألباني: صحيح",{"u2":"حضرت عقبہ بن عامر رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بلند آواز سے قرآن مجید پڑھنے والا، علانیہ صدقہ کرنے والے کی طرح ہے اور آہستہ قرآن پڑھنے والا چھپا کر صدقہ کرنے والے کی طرح۔‘‘","f2":"قرآن مجید میں چھپا کر صدقہ کرنے کو افضل کہا گیا ہے۔ اگرچہ علانیہ صدقہ کرنے والے کو بھی اچھا کہا گیا ہے کیونکہ دونوں میں الگ الگ فوائد ہیں۔ چونکہ علانیہ میں ریا کاری کا خطرہ قوی ہے، لہٰذا وہ افضل نہیں۔ لیکن بعض اوقات علانیہ صدقہ بھی افضل ہو سکتا ہے، جبکہ اس سے دوسروں کو ترغیب و تشویش دینا مقصود ہو۔ بعض اہل علم نے یوں تطبیق دی ہے کہ فرض صدقہ علانیہ کیا جائے کیونکہ وہ اتہام والزام سے بچ جائے گا۔ دوسروں کو رغبت بھی ہوگی۔ اس میں ریا کاری کا امکان بھی کم ہے کیونکہ فرض کام تو بہرحال کرنا ہی پڑتا ہے، البتہ نفل صدقہ چھپا کر ہی دیا جائے کیونکہ یہ اللہ اور بندے کا معاملہ ہے۔ اسے پوشیدہ ہی رہنا چاہیے جبکہ فرض تو پوشیدہ نہیں رہ سکتا، جیسے فرض نماز سب کے سامنے (باجماعت) پڑھنا فرض ہے جبکہ نفل نماز گھر ہی میں افضل ہے تا کہ ریا کا شائبہ نہ رہے۔"}],[2562,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تین طرح کے لوگ ہیں جن کی طرف اللہ تعالی قیامت کے دن نہ دیکھے گا، ایک ماں باپ کا نافرمان، دوسری وہ عورت جو مردوں کی مشابہت اختیار کرے، تیسرا دیوث (بے غیرت) اور تین شخص ایسے ہیں جو جنت میں نہ جائیں گے۔ ایک ماں باپ کا نافرمان، دوسرا عادی شرابی، اور تیسرا دے کر احسان جتانے والا\"۔","الألباني: حسن صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’۔تین شخص ایسے ہیں کہ اللہ تعالیٰ قیامت کے دن ان کی طرف نہیں دیکھے گا: والدین کا نامفرنا، مردوں کی مشابہت اختیار کرنے والی عورت اور بے غیرت خاوند، نیز تین شخص جنت میں داخل نہ ہوں گے: ماں باپ کا نافرمان، ہمیشہ شراب پینے والا اور دے کر احسان جتلانے والا۔‘‘","f2":"(۱) ’’نہیں دیکھے گا۔‘‘ یعنی رحمت اور پیار ومحبت سے نہیں دیکھے گا کیونکہ اصل دیکھنا تو یہی ہوتا ہے، ورنہ کوئی شخص اللہ تعالیٰ سے چھپا ہوا ہے، نہ چھپ ہی سکتا ہے۔ یاد رہے کہ یہ سزا بھی اولاً ہے ورنہ آخر کار یہ بھی اگر مومن ہوئے تو اللہ تعالیٰ کی رحمت بے کنار میں آہی جائیں گے۔ (۲) ’’والدین کا نافرمان۔‘‘ یعنی ان کے حقوق ادا نہ کرنے والا۔ (۳) ’’مردوں سے مشابہت کرنے والی عورت۔‘‘ یعنی ان معاملات میںجو مردوں کے ساتھ خاص ہیں، مثلاً: لباس، حجامت وغیرہ۔ یا مردوں جیسے کام کرے، مثلاً: کھیتوں میں ہل چلانا، حکومت اور سیاست کرنا وغیرہ، جن کاموں میں مردوں سے اختلاط ہو۔ (۴) دیوث بے غیرت جسے اپنی بیوی، بیٹی یا بہن کے غیروں کے ساتھ ناجائز تعلقات پر کوئی اعتراض نہ ہو۔ (۵) ’’جنت میں نہیں جائیں گے۔‘‘ یعنی اولاً، ورنہ سزا بھگتنے کے بعد تو ہر ایمان والا جنت میں جائے گا۔ صحیح روایات میں صراحت ہے۔ (۶) ’’ہمیشہ شراب پینے والا۔‘‘ یعنی شراب پیتا رہا اور بغیر توبہ کیے مر گیا، خواہ زندگی کے آخر میں شراب شروع کی ہو۔"}],[2563,"ابوذر رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تین شخص ایسے ہیں جن سے اللہ تعالی قیامت کے دن نہ بات کرے گا، نہ ان کی طرف دیکھے گا، نہ ان کو پاک کرے گا، اور ان کے لیے درد ناک عذاب ہو گا\"، پھر رسول اللہ صلی اللہ علیہ وسلم نے یہی آیت پڑھی۔ تو ابوذر رضی اللہ عنہ نے کہا: وہ لوگ نامراد ہوئے، گھاٹے میں رہے، آپ نے فرمایا: \"(وہ تین یہ ہیں) اپنا تہبند ٹخنے کے نیچے لٹکانے والا، جھوٹی قسمیں کھا کھا کر اپنے سامان کو رواج دینے والا، اپنے دیے ہوئے کا احسان جتانے والا\"۔","الألباني: صحيح",{"u2":"حضرت ابو ذر رضی اللہ عنہ سے مروی ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’تین شخص ایسے (بدنصیب) ہیں کہ اللہ تعالیٰ قیامت کے دن انھیں (نظر رحمت سے) نہیں دیکھے گا۔ نہ ان سے (رضا مندی والا) کلام فرمائے گا اور نہ انھیں پاک فرمائے گا اور ان کے لیے دردناک عذاب ہوگا۔‘‘ رسول اللہ صلی اللہ علیہ وسلم نے آیت کا یہ ٹکڑا قراء ت فرمایا تو حضرت ابوذر رضی اللہ عنہ نے عرض کیا: وہ تو ناکام ہوئے اور خسارے میں پڑے۔ (وہ کون لوگ ہیں؟) رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’(وہ یہ ہیں:) اپنے تہبند کو ٹخنے سے نیچے لٹکانے والا، جھوٹی قسم کھا کر اپنا سامان بیچنے والا اور اپنے عطیے پر احسان جتلانے والا۔‘‘","f2":"(۱) ’’نہ کلام فرمائے گا۔‘‘ البتہ ڈانٹ ڈپٹ ہوگی لیکن عرفاً اسے کلام کرن نہیں کہتے۔ یہ تو دشمنوں میں بھی ہوتا ہے۔ (۲) ’’نہ پاک فرمائے گا۔‘‘ سزا یہی ہے مگر اللہ تعالیٰ معاف فرما دے تو کیا اعتراض؟ سزا کے بعد تو ہر مومن کو معافی ہو ہی جائے گی۔"}],[2564,"ابوذر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تین شخص ایسے ہیں جن سے قیامت کے دن اللہ عزوجل نہ بات کرے گا، نہ ان کی طرف دیکھے گا، نہ انہیں پاک و صاف کرے گا، اور انہیں درد ناک عذاب ہو گا: اپنے دئیے ہوئے کا احسان جتانے والا، اپنے تہبند کو ٹخنوں سے نیچے لٹکانے والا، اپنے سامان کو جھوٹی قسمیں کھا کر رواج دینے والا\"۔","الألباني: صحيح",{"u2":"حضرت ابو ذر رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تین شخص ایسے (بدنصیب) ہیں کہ قیامت کے دن اللہ تعالیٰ ان سے کلام نہیں فرمائے گا اور نہ ان کی طرف دیکھے گا اور نہ انھیں پاک فرمائے گا اور ان کے لیے دردناک عذاب ہے: اپنے عطیے کا احسان جتلانے والا، اپنے تہبند کو ٹخنے سے نیچے لٹکانے والا اور جھوٹی قسم کھا کر سامان بیچنے والا۔‘‘"}],[2565,"ابن بجید انصاری اپنی دادی سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مانگنے والے کو کچھ دے کر لوٹایا کرو اگرچہ کھر ہی سہی\"۔ ہارون کی روایت میں «محرق» (جلی ہوئی) کا اضافہ ہے۔","الألباني: صحيح",{"u2":"حضرت ابن بجید انصاری کی دادی بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سوالی کو کچھ نہ کچھ دے کر واپس کرو، خواہ جلا ہوا کھر ہی ہو۔‘‘","f2":"مقصد مبالغہ ہے، نیز یہ حکم تب ہے جب سائل حق دار ہو اور مسئول کے پاس گنجائش ہو، ورنہ پیشہ ور گداگروں کو (بشرطیکہ معلوم ہو) دینا تو گناہ ہی کے زمرے میں آسکتا ہے کیونکہ اس طرح گداگری کی حوصلہ افزائی ہوتی ہے جبکہ اسلام نے اس کی سختی کے ساتھ ممانعت فرمائی ہے۔"}],[2566,"بہز بن حکیم اپنے دادا معاویہ بن حیدہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"آدمی اپنے مالک کے پاس اس کی ضرورت سے زائد و فاضل چیز مانگنے آئے، اور وہ اسے نہ دے تو اس کے لیے قیامت کے دن ایک گنجا (زہریلا) سانپ بلایا جائے گا، جو اس کے فاضل مال کو جسے اس نے دینے سے انکار کر دیا تھا چاٹتا پھرے گا\" ۱؎۔\n§وضاحت\n۱؎: وہ فاضل و زائد مال اس کے کچھ کام نہ آئے گا الٹا اس کے لیے وبال بن جائے گا۔","الألباني: حسن",{"u2":"حضرت بہز بن حکیم کے دادا نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’جب کوئی شخص اپنے مالک کے پاس جائے اور اس سے اس کی ضرورت سے زائد کوئی چیز مانگے اور وہ اسے نہ دے تو اس مالک کے لیے قیامت کے دن ایک گنجا سانپ بلایا جائے گا جو اس کے زائد مال کو چبائے گا، جو اس نے نہیں دیا۔‘‘","f2":"’’چبائے گا۔‘‘ یہ معنی بھی بن سکتے ہیں: ’’قیامت کے دن ایک گنجا سانپ بلایا جائے گا جو اس مالک کو چبائے گا اور یہ سانپ اس کا وہ زائد مال ہوگا جو اس نے مانگنے پر نہیں دیا تھا۔‘‘ بظاہر یہ معنی زیادہ مناسب لگتے ہیں مگر الفاظ ان کا ساتھ نہیں دیتے، اس لیے ظاہر معنی کو متن میں لکھا گیا ہے۔"}],[2567,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص اللہ تعالی کی پناہ مانگے اسے پناہ دو، اور جو شخص تم سے اللہ تعالی کے نام پر سوال کرے اسے دو، اور جو شخص اللہ کے نام پر تم سے امان چاہے تو امان دو، اور جو شخص تمہارے ساتھ کوئی بھلائی کرے تو تم اسے اس کا بدلہ دو، اور اگر تم بدلہ نہ دے سکو تو اس کے لیے دعا کرو یہاں تک کہ تم جان لو کہ تم نے اس کا بدلہ چکا دیا ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص اللہ تعالیٰ کا واسطہ دے کر پناہ طلب کرے، اسے پناہ دو۔ جو شخص اللہ تعالیٰ کے نام پر مانگے، اسے دو۔ اور جو شخص اللہ تعالیٰ کے نام پر امن مانگے، اسے امن دو۔ اور جو شخص تم سے حسن سلوک کرے، اسے اس کا بدلہ دو اور اگر تمھیں بدلہ دینے کو کچھ نہ ملے تو اس کے لیے دعا کرو (اور کرتے رہو) حتیٰ کہ تمھیں یقین ہو جائے کہ تم نے اس کے احسان کا بدلہ چکا دیا ہے۔‘‘","f2":"(۱) مذکورہ روایت کو مہقق کتاب نے سنداً ضعیف قرار دیا ہے جبکہ دیگر محققین نے شواہد اور متابعات کی بنا پر اسے صحیح قرار دیا ہے۔ مسند احمد کے مہققین نے اس پر سیر حاصل بحث کی ہے جس سے تصحیح حدیث والی رائے ہی اقرب الی الصواب معلوم ہوتی ہے۔ واللہ اعلم تفصیل کے لیے دیکھیے: (ذخیرۃ العقبیٰ شرح سنن النسائی: ۲۳/ ۸۴-۸۷، والموسوعۃ الحدیثیۃ مسند الامام احمد: ۹/ ۲۶۶، ۲۶۷ والصحیحۃ للالبانی: ۱/ ۵۱۰، ۵۱۱۔ رقم الحدیث: ۲۵۴) (۲) اللہ تعالیٰ ہی عزت والا ہے۔ تمام بزرگی اور عظمت اللہ ہی کے لائق ہے۔ اس کی عظمت کا تقاضا ہے کہ جب اس کا مقدس نام آجائے تو انسان سر تسلیم خم کر دے۔ اور بساط بھر اس نام کی حرمت قائم رکھے،بشرطیکہ وہ غلط مطالبہ نہ ہو، یعنی شریعت کے خلاف نہ ہو اور اس سے کسی پر ظلم نہ ہوتا ہو اور نہ کسی کی حق تلفی۔"}],[2568,"معاویہ بن حیدہ رضی اللہ عنہ کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم سے عرض کیا: اللہ کے نبی! میں اپنے دونوں ہاتھوں کی انگلیوں کی تعداد سے بھی زیادہ بار یہ قسم کھانے کے بعد کہ میں نہ آپ کے پاس آؤں گا اور نہ آپ کا دین قبول کروں گا۔ آپ کے پاس آیا ہوں، میں ایک بے عقل اور ناسمجھ انسان ہوں (اب بھی کچھ نہیں سمجھتا) سوائے اس کے جو اللہ اور اس کے رسول نے مجھے سکھا دیا ہے۔ میں اللہ کی ذات کا حوالہ دے کر آپ سے پوچھتا ہوں: اللہ نے آپ کو ہمارے پاس کیا چیزیں دے کر بھیجا ہے؟ آپ نے فرمایا: \"اسلام دے کر\"، میں نے عرض کیا: \"اسلام کی نشانیاں کیا ہیں؟\" تو آپ نے فرمایا: \"یہ ہے کہ تم کہو: میں نے اپنی ذات کو اللہ تعالی کے سپرد کر دیا اور اپنے آپ کو کفر و شرک کی آلائشوں سے پاک کر لیا ہے، اور تم نماز قائم کرو، زکاۃ دو۔ ہر مسلمان دوسرے مسلمان پر حرام ہے ۱؎۔ ہر ایک دوسرے کا بھائی و مددگار ہے، اللہ تعالی مشرک کا کوئی عمل اس کے بعد کہ وہ اسلام لے آیا ہو قبول نہیں کرتا، یا وہ مشرکین کو چھوڑ کر مسلمانوں سے آ ملے ۲؎۔\n§وضاحت\n۱؎: یعنی ہر مسلمان کی جان، مال عزت و آبرو دوسرے مسلمان پر حرام ہے۔ ۲؎: اس حدیث سے معلوم ہوتا ہے کہ دار الشرک سے دار السلام کی طرف ہجرت واجب ہے۔","الألباني: حسن",{"u2":"حضرت بہز بن حکیم کے دادا (حضرت معاویہ بن حیدہ قشیرہ رضی اللہ عنہ) بیان کرتے ہیں کہ میں نے عرض کیا: اے اللہ کے نبی! میں نے آپ کے پاس آنے سے قبل اپنے ہاتھ کی انگلیوں کی تعداد سے بھی زیادہ قسمیں کھائی تھیں کہ نہ میں آپ کے پاس آوں گا اور نہ آپ کا دین قبول کروں گا۔ اور میں دین کی کوئی سمجھ نہیں رکھتا مگر جو اللہ تعالیٰ اور اس کے رسول مجھے سکھائیں۔ اور میں آپ سے اللہ تعالیٰ کی ذات کے واسطے سے سوال کرتا ہوں کہ اللہ تعالیٰ نے آپ کو کیا چیز دے کر ہمارے پاس بھیجا ہے؟ اپ نے فرمایا: ’’اسلام دے کر۔‘‘ میں نے عرض کیا: اسلام کی علامات کیا ہیں؟ آپ نے فرمایا: ’’یہ کہ تو کہے: میں نے اپنی ذات کو اللہ تعالیٰ کے تابع کر دیا ہے اور (اس کے علاوہ ہر چیز سے) علیحدہ ہو جائے اور نماز قائم کرے اور زکاۃ ادا کرے۔ ہر مسلمان دوسرے مسلمان کے لیے قابل احترام ہے۔ وہ دونوں ایک دوسرے کے مددگار بھائی ہوتے ہیں۔ اللہ تعالیٰ کسی مشرک سے اس کے اسلام لانے کے بعد بھی کوئی عمل قبول نہیں فرماتا حتیٰ کہ وہ مشرکین کو چھوڑ کر مسلمانوں سے آملے۔‘‘","f2":"’’مسلمانوں سے آملے۔‘‘ یعنی ہجرت کر لے۔ نبی صلی اللہ علیہ وسلم کے دور میں مسلمانوں کی قوت مجتمع کرنے کی ضرورت تھی، نیز اہل کفر سے اس قدر مخاصمت تھی کہ دونوں کا اکٹھا رہنا اور دین پر عمل کرنا ناممکن تھا، اس لیے ہجرت فرض تھی۔ جب اسلام پھیل گیا اور کفر سکڑ گیا تو آپ نے اعلان فرما دیا کہ اب مکہ سے ہجرت کی ضرورت نہیں رہی۔ گویا ہجرت، لازمہ اسلام نہیں بلکہ اس کا فیصلہ حالات کے جائزے سے ہوگا۔ نہ ہر دارالکفر میں رہنا جائز ہے اور نہ ہر دارلکفر سے ہجرت واجب ہے۔"}],[2569,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کیا میں تمہیں لوگوں میں مرتبہ کے اعتبار سے بہترین شخص کے بارے میں نہ بتاؤں؟ ہم نے عرض کیا: کیوں نہیں، ضرور بتائیے اللہ کے رسول! آپ نے فرمایا: \"وہ شخص ہے جو اللہ کی راہ میں اپنے گھوڑے کا سر تھامے رہے یہاں تک کہ اسے موت آ جائے، یا وہ قتل کر دیا جائے، اور میں تمہیں اس شخص کے بارے میں بتاؤں جو مرتبہ میں اس سے قریب تر ہے\"۔ ہم نے عرض کیا: جی ہاں، اللہ کے رسول! بتائیے، آپ نے فرمایا: \"یہ وہ شخص ہے جو لوگوں سے کٹ کر کسی وادی میں (گوشہ نشین ہو جائے) نماز قائم کرے، زکاۃ دے اور لوگوں کے شر سے الگ تھلگ رہے، اور میں تمہیں لوگوں میں برے شخص کے بارے میں بتاؤں؟\"، ہم نے عرض کیا: جی ہاں، اللہ کے رسول! ضرور بتائیے، آپ نے فرمایا: \"وہ شخص ہے جس سے اللہ کے نام پر مانگا جائے اور وہ نہ دے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’۔کیا میں تمہیں نہ بتاؤں کہ لوگوں میں سے بہترین رتبے والا کون شخص ہے؟‘‘ ہم نے عرض کیا: کیوں نہیں، اے اللہ کے رسول! (ضرور بتائیں!) آپ نے فرمایا: ’’وہ آدمی جو اللہ تعالیٰ کے راستے میں اپنا گھوڑا لیے پھرتا ہے حتیٰ کہ اسے موت آجاتی ہے یا وہ شہید ہو جاتا ہے۔ اور میں تمھیں وہ شخص بتاؤں جو اس کے قریب ہے؟‘‘ ہم نے کہا: جی ہاں! اے اللہ کے رسول! آپ نے فرمایا: ’’وہ شخص جو کسی پہاڑ کی گھاٹی میں علیحدہ رہتا ہے، نماز قائم کرتا ہے، زکاۃ ادا کرتا ہے اور لوگوں کے شر سے علیحدہ رہتا ہے، نیز بتاؤں، بدترین شخص کون ہے؟‘‘ ہم نے کہا: جی ہاں اے اللہ کے رسول! آپ نے فرمایا: ’’جو اللہ کے نام پر خود تو (لوگوں سے) مانگے، لیکن اس کے نام پر (کسی کو) نہ دے۔‘‘","f2":"(۱) ’’گھوڑا لیے پھرتا ہے۔‘‘ یعنی جہاد کرتا ہے۔ جہاد فی سبیل اللہ مطلقاً اعلیٰ عمل ہے۔ اور پہاڑ کی گھاٹی میں علیحدہ رہنا صرف اس وقت افضل ہے جب دین کی حفاظت مقصود ہو اور لوگوں میں رہ کر دین پر قائم رہنا انتہائی مشکل ہو جائے، ورنہ لوگوں میں رہنا اور امر بالمعروف ونہی عن المنکر کرنا ہی افضل ہے۔ رہبانیت کی اجازت نہیں۔ (۲) ’’لوگوں کے شر سے۔‘‘ یعنی اپنے دین کو محفوظ کر لیتا ہے، یا یہ مطلب ہے کہ لوگوں کو تکلیف نہیں پہنچاتا۔ اپنے شر سے لوگوں کو محفوظ رکھنا بھی بڑی فضیلت ہے۔ (۳) [اَلَّذِیْ یَسْأَلُ بِاللّٰہِ] کویُسْأَلُ (مجہول) بھی پڑھا گیا ہے، جس کا ترجمہ ہوگا: جس سے اللہ کے نام پر سوال کیا جائے لیکن وہ نہ دے۔ پہلے مفہوم میں دو قباحتیں جمع ہوجاتی ہیں: لوگوں سے مانگنا بھی اور خود نہ دینا بھی، جبکہ دوسرے مفہوم میں صرف ایک قباحت ہے۔ الفاظ حدیث دونوں مفہوم کے متحمل ہیں۔ واللہ اعلم"}],[2570,"ابوذر رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تین آدمی ایسے ہیں جن سے اللہ عزوجل محبت کرتا ہے، اور تین آدمی ایسے ہیں جن سے اللہ عزوجل بغض رکھتا ہے، رہے وہ جن سے اللہ محبت کرتا ہے تو وہ یہ ہیں: ایک شخص کچھ لوگوں کے پاس گیا، اور اس نے ان سے اللہ کے نام پر کچھ مانگا، اور مانگنے میں ان کے اور اپنے درمیان کسی قرابت کا واسطہ نہیں دیا۔ لیکن انہوں نے اسے نہیں دیا۔ تو ایک شخص ان لوگوں کے پیچھے سے مانگنے والے کے پاس آیا۔ اور اسے چپکے سے دیا، اس کے اس عطیہ کو صرف اللہ عزوجل جانتا ہو اور وہ جسے اس نے دیا ہے۔ اور کچھ لوگ رات میں چلے اور جب نیند انہیں اس جیسی اور چیزوں کے مقابل میں بہت بھلی لگنے لگی، تو ایک جگہ اترے اور اپنا سر رکھ کر سو گئے، لیکن ایک شخص اٹھا، اور میرے سامنے گڑگڑانے لگا اور میری آیتیں پڑھنے لگا۔ اور ایک وہ شخص ہے جو ایک فوجی دستہ میں تھا، دشمن سے مڈبھیڑ ہوئی، لوگ شکست کھا کر بھاگنے لگے مگر وہ سینہ تانے ڈٹا رہا یہاں تک کہ وہ مارا گیا، یا اللہ تعالی نے اسے فتح مند کیا۔ اور تین شخص جن سے اللہ تعالی بغض رکھتا ہے یہ ہیں: ایک بوڑھا زنا کار، دوسرا گھمنڈی فقیر، اور تیسرا ظالم مالدار\"۔","الألباني: ضعيف",{"u2":"حضرت ابو ذر رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تین شخص ایسے ہیں کہ اللہ تعالیٰ ان سے محبت فرماتا ہے اور تین شخص ایسے ہیں کہ اللہ تعالیٰ ان سے بغض رکھتا ہے۔ جن سے اللہ تعالیٰ محبت فرماتا ہے (وہ یہ ہیں:) ایک آدمی کسی قوم کے پاس آیا۔ ان سے اللہ تعالیٰ کے نام پر سوال کیا۔ کسی باہمی قرابت کی بنا پر سوال نہیں کیا، لیکن انھوں نے اسے کچھ نہ دیا۔ ایک شخص (ان میں سے اٹھا اور) ان لوگوں کو پیچھے چھوڑ کر آگے نکل گیا اور اسے خفیہ طور پر دیا۔ اس کے اس عطیے کو اللہ تعالیٰ نے جانا یا اس شخص نے جسے اس نے دیا۔ (دوسرا یہ کہ) کچھ لوگ ساری رات چلتے رہے، حتی کہ جب نیند انھیں ہر اس چیز سے اچھی لگنے لگی جو نیند کے برابر ہو سکتی ہے تو وہ سواریوں سے اتر پڑے اور سو گئے، لیکن ایک شخص (نماز میں) کھڑا ہو کر میرے سامنے گڑ گڑانے لگا اور میری آیات تلاوت کرنے لگا۔ تیسرا وہ شخص جو ایک لشکر میں تھا۔ ان کا دشمن سے مقابلہ ہوا۔ سب بھاگ کھڑے ہوئے مگر وہ ڈٹا رہا، حتیٰ کہ شہید ہوگیا یا اسے فتح مل گئی۔ اور وہ تین شخص جن سے اللہ عزوجل بغض رکھتا ہے، یہ ہیں: بوڑھا زنا کار، فقیر متکبر اور مال دار ظالم۔‘‘","f2":"(۱) محبت اور بغض اللہ تعالیٰ کی صفات ہیں جن کا قرآن وحدیث میں بکثرت ذکر ملتا ہے، مگر کچھ لوگ فلسفے کے بعض غیر مسلم اصولوں سے متاثر ہو کر ان صفات کی نفی کرتے ہیں اور ان سے صرف انعام وانتقام مراد لیتے ہیں، حالانکہ یہ الگ دو صفات ہیں جو اللہ تعالیٰ میں پائی جاتی ہیں۔ ان لوگوں کو سوچنا چاہیے کہ کیا وہ اللہ تعالیٰ اور اس کے رسول صلی اللہ علیہ وسلم سے بڑھ کر اللہ تعالیٰ کی ذات وصفات سے واقفیت رکھتے ہیں؟ لفظ سے وہی معنی مراد لینے چاہئیں جو ایک سادہ سننے والے کی سمجھ میں آتے ہیں، حقیقت ہو یا مجاز۔ اگر ان صفات کا عام مفہوم اللہ تعالیٰ کے لائق نہ ہوتا تو ضرور بیان کر دیا جاتا۔ (۲) جن تین آدمیوں سے اللہ تعالیٰ کے محبت فرمانے کا تعلق ہے۔ ان میں ایک قدر مشترک ہے اور وہ ہے خلوص۔ تینوں ریا کاری سے کوسوں دور ہیں اور صرف اللہ تعالیٰ کے لیے اپنا مال، آرام اور جان قربان کرتے ہیں۔ (۳) زنا، تکبر اور ظلم ہر حال میں کبیرہ گناہ ہیں اور اللہ تعالیٰ کو ناپسند ہیں۔ اور ان کا فاعل اللہ تعالیٰ کے نزدیک مبغوض ہے مگر جب ان کے فاعل کے پاس ذرہ بھر بھی عذر نہ ہو حتیٰ کہ عرفاً بھی نہ ہو تو یہ کام اکبر الکبائر بن جاتے ہیں۔ نوجوان کے پاس شہوت، مالدار کے پاس مال اور فقیر کے ہاں فقر ان جرائم کا عذر عرفاً بن سکتے ہیں مگر بوڑھے کے پاس زنا اور فقیر کے پاس تکبر اور اکڑفوں اور مال دار کے پاس کسی کی حق تلفی کا کیا عذر ہو سکتا ہے؟ جسے شرعاً نہیں تو عرفاً ہی پیش کیا جا سکے۔ أَعَاذَنَا اللّٰہُ عَنْھَا۔"}],[2571,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مسکین وہ نہیں ہے جسے ایک کھجور یا دو کھجور ایک لقمہ یا دو لقمے (در در) گھماتے اور (گھر گھر) چکر لگواتے ہیں۔ بلکہ مسکین سوال سے بچنے والا ہے ۱؎ اگر تم چاہو تو پڑھو «لا يسألون الناس إلحافا» \"وہ لوگوں سے گڑگڑا کر نہیں مانگتے\"(البقرہ: ۲۷۳)۔\n§وضاحت\n۱؎: جو ضرورت مند ہوتے ہوئے بھی نہیں مانگتا۔","الألباني: شاذ بزيادة اقرؤوا",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’۔مسکین وہ نہیں جس کو ایک کھجور، دو کھجوریں یا ایک لقمہ، دو لقمے واپس کر دیں، بلکہ مسکین وہ ہے جو حاجت مند ہونے کے باوجود مانگنے سے پرہیز کرے۔ تم چاہو تو یہ آیت پڑھ لو: {لَا یَسْئَلُوْنَ النَّاسَ اِلْحَافًا} ’’(صدقات کے مستحق وہ لوگ ہیں) جو مانگتے وقت لوگوں کے گلے نہیں پڑ جاتے۔‘‘","f2":"’’مسکین وہ نہیں‘‘ کیونکہ اس قسم کے لوگ عموماً پیشہ ور بھکاری ہوتے ہیں اور دوسروں سے زیادہ امیر ہوتے ہیں۔ یا مطلب یہ ہے کہ قابل تعریف مسکین نہیں، اگرچہ مسکین تو ہیں۔ یا یہ اس قدر مستحق نہیں جس قدر سوال نہ کرنے والے حاجت مند لوگ مستحق ہیں۔"}],[2572,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مسکین وہ نہیں ہے جو اس طرح لوگوں کے پاس چکر لگائے کہ ایک لقمہ دو لقمے یا ایک کھجور دو کھجوریں اسے در در پھرائیں\"، لوگوں نے پوچھا: پھر مسکین کون ہے؟ فرمایا: \"مسکین وہ ہے جس کے پاس اتنا مال و دولت نہ ہو کہ وہ اپنی ضرورت کی تکمیل کے لیے دوسروں کا محتاج نہ رہے، اور وہ محسوس بھی نہ ہو سکے کہ وہ مسکین ہے کہ اسے ضرورت مند سمجھ کر صدقہ دیا جائے۔ اور نہ ہی وہ لوگوں کے سامنے مانگنے کے لیے ہاتھ پھیلائے کھڑا ہوتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’یہ گھومنے پھرنے والا شخص مسکین نہیں جسے ایک دو لقمے یا ایک دو کھجوریں پلٹا دیتی ہیں۔‘‘ صحابہ نے عرض کیا: تو پھر مسکین کون ہے؟ آپ نے فرمایا: ’’جس کے پاس اتنا مال نہ ہو کہ گزارا کر سکے۔ نہ اس (کے فقر) کا کسی کو پتا ہی چلتا ہے کہ اس پر صدقہ کیا جائے اور نہ وہ خود کھڑا ہو کر لوگوں سے مانگتا ہے۔‘‘"}],[2573,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مسکین وہ نہیں ہے جسے ایک لقمے دو لقمے اور ایک کھجور، دو کھجور در در پھرائیں\"۔ لوگوں نے کہا: پھر مسکین کون ہے؟ اللہ کے رسول! آپ نے فرمایا: \"مسکین وہ ہے: جو مالدار نہ ہو، اور لوگ اس کی محتاجی و حاجت مندی کو جان بھی نہ سکیں کہ اسے صدقہ دیں\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مسکین وہ نہیں جسے ایک دو لقمے یا ایک دو کھجوریں پلٹا دیتی ہیں۔‘‘ لوگوں نے کہا: تو اے اللہ کے رسول! پھر مسکین کون ہے؟ آپ نے فرمایا: ’’جو شخص اتنا مال نہیں رکھتا جو کفایت کر سکے اور لوگوں کو اس (کے فقر) کا پتا نہیں چلتا کہ اس پر صدقہ ہو سکے۔‘‘","f2":"مذکورہ روایت معناً صحیح ہے جیسا کہ محقق کتاب نے لکھا ہے کہ بخاری ومسلم کی روایت اس سے کفایت کرتی ہے۔ بنا بریں مذکورہ روایت قابل عمل اور قابل حجت ہے۔ واللہ اعلم"}],[2574,"ام بجید رضی اللہ عنہا (جو ان عورتوں میں سے ہیں جن ہوں نے رسول اللہ صلی اللہ علیہ وسلم سے بیعت کی تھی) کہتی ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کیا: (کبھی ایسا ہوتا ہے) کہ مسکین میرے دروازے پر آ کھڑا ہوتا ہے، اور میں اسے دینے کے لیے کوئی چیز موجود نہیں پاتی؟ آپ نے فرمایا: \"اگر تم اسے دینے کے لیے صرف جلی ہوئی کھر ہی پاؤ تو اسے وہی دے دو\"۔","الألباني: صحيح",{"u2":"حضرت ام بجید رضی اللہ عنہا سے روایت ہے۔ اور انھیں رسول اللہ صلی اللہ علیہ وسلم سے بیعت کرنے کا شرف حاصل ہے۔ انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا کہ کبھی کوئی مسکین سائل میرے دروازے پر آکھڑا ہوتا ہے مگر میرے پاس اسے دینے کے لیے کچھ نہیں ہوتا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اگر اسے دینے کے لیے تیرے پاس کچھ بھی نہ ہو سوائے جلے ہوئے کھر کے، تو وہی اسے دے دے۔‘‘","f2":"سائل دروازے سے محروم نہیں جانا چاہیے۔ استحقاق اور عدم استحقاق کو تو اللہ تعالیٰ ہی بہتر جانتا ہے الا یہ کہ اس کا پیشہ ور ہونا معلوم ہو اور وہ حقیقتاً محتاج نہ ہو۔ (نیز دیکھیے، حدیث: ۲۵۶۶)"}],[2575,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تین طرح کے لوگ ہیں جن سے اللہ عزوجل قیامت کے دن بات نہیں کرے گا: بوڑھا زنا کار، گھمنڈی فقیر، جھوٹا امام\"۔","الألباني: حسن صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’۔تین شخص ایسے ہیں کہ اللہ تعالیٰ قیامت کے دن ان سے کلام نہیں فرمائے گا۔ بوڑھا بدکار، مغرور ومتکبر فقیر اور جھوٹا بادشاہ۔‘‘","f2":"بادشاہ بہر حال حاکم اعلیٰ ہے، اسے کوئی خوف وخطر نہیں کہ جھوٹ بولے، نیز اس کا جھوٹ بہت بڑے فریب پر مبنی ہوگا اور عوام الناس کے اعتماد کو ٹھیس پہنچائے گا، نیز وہ پوری رعایا کے لیے نقصان دہ ہے، اس لیے اس کا جھوٹ بہت بڑا گناہ ہے اور اللہ تعالیٰ کے غضب کو دعوت دینا ہے۔"}],[2576,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"چار طرح کے لوگ ہیں جن سے اللہ بغض رکھتا ہے: قسمیں کھا کھا کر بیچنے والا، گھمنڈی فقیر، بوڑھا زنا کار، ظالم امام (حاکم)\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جار اشخاص سے اللہ تعالیٰ بغض رکھتا ہے: جھوٹی قسمیں کھا کر سامان بیچنے والا، مغرور و متکبر فقیر، بوڑھا زنا کار اور ظالم بادشاہ۔‘‘"}],[2577,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بیوہ عورت اور مسکین پر خرچ کرنے کے لیے محنت کرنے والا اللہ کی راہ میں جہاد کرنے والے کے مانند ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بیوہ اور مسکین کے لیے دوڑ دھوپ کرنے والا اس شخص کی طرح ہے جو اللہ تعالیٰ کے راستے میں جہاد کرتا ہے۔‘‘","f2":"(۱) بیوہ کے لیے بھاگ دوڑ کرنا یقینا فضیلت والا کام ہے بشرطیکہ ذاتی منفعت، مثلاً: نکاح کے لیے مائل کرنا مقصود نہ ہو اور نہ اس کے عوض اس سے اپنے گھریلو کام ہی کروائے۔ (۲) جہاد فی سبیل اللہ افضل عمل ہے کیونکہ اس میں انسان اپنی جان تک کو خطرے میں ڈال دیتا ہے، اس لیے اس کا ثواب سب سے زیادہ ہے۔ اسی طرح بیوہ اور مسکین جیسے بے سہارا افراد سے تعاون بھی عظیم نیکی ہے۔"}],[2578,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ علی رضی اللہ عنہ نے یمن سے رسول اللہ صلی اللہ علیہ وسلم کے پاس مٹی ملا ہوا غیر صاف شدہ سونے کا ایک ڈلا بھیجا تو آپ صلی اللہ علیہ وسلم نے اسے چار افراد: اقرع بن حابس حنظلی، عیینہ بن بدر فرازی، اور علقمہ بن علاثہ جو عامری تھے پھر وہ بنی کلاب کے ایک فرد بن گئے، اور زید جو طائی تھے پھر بنی نبہان میں سے ہو گئے، کے درمیان تقسیم کر دیا۔ (یہ دیکھ کر) قریش کے لوگ غصہ ہو گئے۔ راوی نے دوسری بار کہا: قریش کے سرکردہ لوگ غصہ ہو گئے، اور کہنے لگے کہ آپ نجد کے سرداروں کو دیتے ہیں اور ہم کو چھوڑ دیتے ہیں؟ آپ نے فرمایا: \"میں نے ایسا اس لیے کیا ہے تاکہ ان کی تالیف قلب کروں (یعنی انہیں رجھا سکوں)\"، اتنے میں گھنی داڑھی والا، ابھرے گالوں والا دھنسی آنکھوں والا، ابھری پیشانی والا، منڈے سر والا ایک شخص آیا اور کہنے لگا: محمد اللہ سے ڈرو، آپ نے فرمایا: \"اگر میں ہی اللہ تعالی کی نافرمانی کرنے لگوں گا تو پھر اللہ عزوجل کی تابعداری کون کرے گا؟ وہ مجھے سارے زمین والوں میں اپنا امین (معتمد) سمجھتا ہے، اور تم مجھے امین نہیں سمجھتے\"، پھر وہ شخص پیٹھ پھیر کر چلا تو حاضرین میں سے ایک شخص نے اس کے قتل کی اجازت طلب کی (لوگوں کا خیال ہے کہ وہ خالد بن ولید رضی اللہ عنہ تھے) تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اس کی نسل سے ایسے لوگ پیدا ہوں گے جو قرآن پڑھیں گے لیکن وہ ان کے حلق سے نیچے نہیں اترے گا ۱؎، اہل اسلام کو قتل کریں گے، اور بت پرستوں کو چھوڑ دیں گے۔ یہ لوگ اسلام سے ایسے ہی نکل جائیں گے جیسے تیر شکار کے جسم کو چھیدتا ہوا نکل جاتا ہے۔ اگر میں نے انہیں پایا، تو میں انہیں قوم عاد کی طرح قتل کر دوں گا\"۔\n§وضاحت\n۱؎: یہ خارجی لوگ ہیں جن کا ظہور علی رضی اللہ عنہ کی خلافت میں ہوا۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ حضرت علی رضی اللہ عنہ نے، جب وہ یمن کے امیر تھے، رسول اللہ صلی اللہ علیہ وسلم کے پاس غیر صاف شدہ سونے کی ڈلی بھیجی۔ رسول اللہ صلی اللہ علیہ وسلم نے اسے چار آدمیوں کے درمیان تقسیم فرما دیا: اقرع بن حابس حنظلی، عیینہ بن بدر فزاری، علقمہ بن علاثہ عامری جو بنو عامر کی ایک شاخ بنی کلاب میں سے تھے اور زید طائی جو بنو طے کی ایک شاخ بنو نبہان سے تھے۔ اس پر قریش کے (نو مسلم) سردار ناراض ہوگئے اور کہنے لگے: آپ نجد کے (نو مسلم) سرداروں کو دے رہے ہیں اور ہمیں محروم رکھ رہے ہیں (حالانکہ ہم آپ کے قریبی ہیں؟) نبی صلی اللہ علیہ وسلم نے فرمایا: ’’میں نے ایسا اس لیے کیا ہے کہ ان کی تالیف قلب کروں۔ ایک شخص آیا جس کی داڑھی گھنی، رخسار ابھرے ہوئے، آنکھیں گہری، ماتھا آگے کو بڑھا ہوا اور سر منڈا ہوا تھا، وہ کہنے لگا: اے محمد! اللہ سے ڈر۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اگر میں اللہ تعالیٰ کا نافرمان ہوں تو اللہ تعالیٰ کا فرمانبردار کون ہوگا؟ اللہ تعالیٰ تو مجھے زمین والوں (تمام انسانوں جنوں) پر امین جانتا ہے اور تم مجھے امین نہیں جانتے۔‘‘ پھر وہ شخص پیٹھ پھیر کر چلا گیا۔ حاضرین میں سے ایک شخص نے آپ سے اس کے قتل کی اجازت طلب کی۔ اہل علم کا خیال ہے کہ وہ حضرت خالد بن ولید رضی اللہ عنہ تھے۔ رسول اللہ صلی اللہ علیہ وسلم نے (اجازت تو نہ دی مگر) فرمایا: ’’یقینا اس کی نسل (قبیلے) میں ایسے لوگ ہوں گے جو قرآن پڑھیں گے مگر وہ ان کے حلق سے نیچے نہیں اترے گا۔ وہ مسلمانوں کو قتل کریں گے اور بت پرستوں کو چھوڑ دیں گے (انھیں کچھ نہیں کہیں گے)۔ وہ اسلام سے یوں نکل جائیں گے جیسے تیز تیر اپنے نشانے کو پھاڑ کر نکل جاتا ہے۔ واللہ! اگر میں نے ان کو پا لیا تو انھیں قوم عاد کی طرح قتل کروں گا۔‘‘","f2":"(۱) مؤلفۃ القلوب کئی قسم کے ہوتے ہیں:\nوہ لوگ جو اپنی قوم میں با اثر سردار ہوں اور ان کے اسلام لانے کی امید ہو۔ انھیں عطیات دیے جائیں تاکہ ان کے دل سے بُعد ختم ہو اور وہ مسلمان ہو جائیں۔ بعد میں اسلام خود بخود ان کے دلوں میں گھر کر جائے گا۔ ان کی وجہ سے ان کی قوم بھی مسلمان ہو جائے گی۔\nوہ نومسلم لوگ جن کے دلوں تک اسلام نہیں پہنچا مگر وہ اپنی قوم کے بااثر سردار ہیں۔ اگر انھیں نہ دیا گیا تو وہ کوئی فتنہ کھڑا کر سکتے ہیں، اس لیے انھیں عطیات دیے جائیں تاکہ وہ اسلام پر پکے ہو جائیں۔\nوہ با اثر لوگ جن کے ساتھ مسلمانوں کے علاقے ملتے ہیں اور وہ مشکل وقت میں مسلمانوں کے محافظ بن سکتے ہیں۔\n(۲) رسول اللہ صلی اللہ علیہ وسلم نے مؤلفۃ القلوب کو مال دیا ہے۔ قرآن مجید میں بھی زکاۃ کے مصارف میں ان کا ذکر ہے۔ مگر احناف کا خیال ہے کہ اب اسلام مضبوط ہو چکا ہے۔ ہم ایسے لوگوں کے محتاج نہیں رہے، لہٰذا اب ان کا حصہ ساقط ہو چکا ہے، جبکہ دیگر اہل علم ضرورت پڑنے پر انھیں اب بھی مصرف سمجھتے ہیں اور یہی بات درست ہے۔ کیونکہ یہ ضروری نہیں کہ ہر جگہ اسلام غالب ہی آچکا ہو۔ بعض علاقوں میں نبی صلی اللہ علیہ وسلم کے دور والی صورت حال بھی ہو سکتی ہے۔\n(۳) جن چار سرداروں کے مابین آپ نے وہ سونا تقسیم کیا تھا، وہ مؤلفۃ القلوب کی دوسری قسم میں داخل تھے۔\n(۴) ’’قریش کے نو مسلم سردار‘‘ جو فتح مکہ کے بعد مسلمان ہوئے۔ یہ اطمینان قلب میں مہاجرین وانصار کے درجے میں نہ تھے۔\n(۵) ’’ایک شخص‘‘ گویا اس کی ظاہری شکل وصورت بھی قبیح تھی اور بات اس سے بھی قبیح کی۔ ظاہر یہی ہے کہ یہ کوئی منافق شخص تھا جو صرف مال کے لالچ میں مسلمان ہوا تھا۔ نہ ملنے پر بکواس کرنے لگا۔\n(۶) ’’اجازت نہ دی۔‘‘ کیونکہ وہ ظاہراً مسلمان تھا۔ اور منافقوں کے قتل کی اجازت نہ تھی۔ اس نے صراحتاً کوئی الزام بھی نہ لگایا تھا۔\n(۷) ’’اس کی نسل سے۔‘‘ واقعتا یہ پیش گوئی پوری ہوئی۔ حضرت علی رضی اللہ عنہ کے دور میں یہ ظاہر ہوئے۔ قرآن بہت پڑھتے تھے مگر پڑھنا اور بات ہے، سمجھنا اور بات۔ ان کی بے وقوفی یہ تھی کہ قرآن مجید صحابہ رضی اللہ عنہم سے پڑھتے تھے مگر مطلب انھیں بتاتے تھے۔\n(۸) ’’حلق سے تجاوز۔‘‘ یعنی قرآن مجید کو سمجھ نہ سکیں گے، لہٰذا ثواب کے بھی حق دار نہ ہوں گے۔\n(۹) ’’مسلمانوں کو قتل۔‘‘ واقعتا انھوں نے بہت صحابہ کرام رضی اللہ عنہم کو شہید کیا۔ خلیفہ برحق حضرت علی اور حضرت عثمان رضی اللہ عنہ کو صراحتاً کافر کہا۔ نعوذ باللہ من ذلک۔ خلیفہ وقت سے لڑائی کی اور اپنی تمام توانائیاں اہل اسلام کے خلاف صرف کیں۔ یہ لوگ اپنے خیال میں مخلص مسلمان تھے۔ مگر حقیقتاً مسلمانوں کے لیے کافروں سے زیادہ نقصان دہ ثابت ہوئے۔ ظاہراً بہت نیک تھے۔ نماز روزے کے سختی سے پابند تھے مگر دین کے صحیح فہم سے نابلد تھے۔ ایسے لوگ کفار اور شیطان کے ہاتھوں آسانی سے کھلونا بن جاتے ہیں۔ انھیں دنیا ’’خوارج‘‘ کے نام سے یاد رکھتی ہے۔\n(۱۰) ’’وہ اسلام سے نکل جائیں گے۔‘‘ ظاہراً تو معلوم ہوتا ہے کہ وہ کافر تھے، کچھ اور نصوص سے بھی ان کے کفر کا اثبات ہوتا ہے۔ اسی لیے محدثین کا ایک گروہ ان کے کافر ہونے کا قائل ہے۔ لیکن فقہاء نے انھیں گمراہ فرقوں میں داخل کیا ہے۔ گویا ان کے نزدیک رسول اللہ صلی اللہ علیہ وسلم کے مندرجہ بالا الفاظ زجر و تغلیظ پر محمول ہیں۔ واللہ اعلم (۱۱) ’’قتل کروں گا۔‘‘ یہ فریضہ حصرت علی رضی اللہ عنہ نے سر انجام دیا اور ان کا خاتمہ فرمایا۔ اگرچہ وہ بعد میں بھی عرصہ دراز تک امت مسلمہ کے لیے کسی نہ کسی علاقے میں آفت بنے رہے۔ آہستہ آہستہ وہ سیاسی اور مذہبی طور پر ختم ہوگئے۔ والحمد للہ"}],[2579,"قبیصہ بن مخارق رضی اللہ عنہ کہتے ہیں کہ میں نے ایک قرض اپنے ذمہ لے لیا، تو میں نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، اور آپ سے اس سلسلہ میں سوال کیا، تو آپ نے فرمایا: \"مانگنا صرف تین لوگوں کے لیے جائز ہے، ان میں سے ایک وہ شخص ہے جس نے قوم کے کسی شخص کے قرض کی ضمانت لے لی ہو (پھر وہ ادا نہ کر سکے)، تو وہ دوسرے سے مانگے یہاں تک کہ اسے ادا کر دے، پھر رک جائے\"۔","الألباني: صحيح",{"u2":"حضرت قبیصہ بن مخارق رضی اللہ عنہ سے منقول ہے، انھوں نے کہا: میں نے کوئی تاوان اپنے ذمے لے لیا، پھر میں نبی صلی اللہ علیہ وسلم کے پاس حاضر ہوا اور آپ سے اس کی (ادائیگی میں تعاون کی) بابت سوال کیا تو آپ نے فرمایا: ’’مانگنا صرف تین قسم کے لوگوں کے لیے جائز ہے۔ ان میں سے ایک وہ شخص ہے جس نے کسی قوم میں (صلح کروانے کے لیے) کوئی تاوان اپنے ذمے لے لیا۔ وہ اس سلسلے میں لوگوں سے مدد مانگ سکتا ہے۔ حتیٰ کہ تاوان اتار دے اور پھر مانگنے سے رک جائے۔‘‘","f2":"قرآن مجید میں بھی اس جیسے لوگوں کو زکاۃ کا حق دار ٹھہرایا گیا ہے: {وَالْغَارِمِیْنَ} (التوبۃ۹: ۶۰) اس سے مراد وہ شخص ہے جو کسی کی لڑائی ختم کرنے کے لیے متنازعہ رقم اپنے ذمے لے لیتا ہے مگر اتنی وسعت نہیں کہ خود ادا کر سکے۔ وہ زکاۃ کا مال لے کر تاوان ادا کر سکتا ہے۔"}],[2580,"قبیصہ بن مخارق رضی اللہ عنہ سے روایت ہے کہ میں نے ایک قرض اپنے ذمہ لے لیا، میں رسول اللہ صلی اللہ علیہ وسلم کے پاس (ادائیگی کے لیے روپے) مانگنے آیا، تو آپ نے فرمایا: \"اے قبیصہ رکے رہو۔ (کہیں سے) صدقہ آ لینے دو، تو ہم تمہیں اس میں سے دلوا دیں گے\"، وہ کہتے ہیں ـ: پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اے قبیصہ! صدقہ تین طرح کے لوگوں کے سوا کسی کے لیے جائز نہیں ہے: وہ شخص جو کسی کا بوجھ خود اٹھا لے ۱؎ تو اس کے لیے مانگنا درست ہے، یہاں تک کہ اس سے اس کی ضرورت پوری ہو جائے، اور (دوسرا) وہ شخص جو کسی ناگہانی آفت کا شکار ہو جائے، اور وہ اس کا مال تباہ کر دے، تو اس کے لیے مانگنا جائز ہے یہاں تک کہ وہ اسے پا لے، پھر رک جائے، (تیسرا) وہ شخص جو فاقہ کا شکار ہو گیا ہو یہاں تک کہ اس کی قوم کے تین سمجھ دار افراد گواہی دیں کہ ہاں واقعی فلاں شخص فاقہ کا مارا ہوا ہے، تو اس کے لیے مانگنا جائز ہے یہاں تک کہ اس کے گزارہ کا انتظام ہو جائے، ان کے علاوہ مانگنے کی جو بھی صورت ہے حرام ہے، اے قبیصہ! اور جو کوئی مانگ کر کھاتا ہے حرام کھاتا ہے\"۔\n§وضاحت\n۱؎: یعنی کسی کا قرض وغیرہ اپنے ذمہ لے لے۔","الألباني: صحيح",{"u2":"حضرت قبیصہ بن مخارق رضی اللہ عنہ بیان کرتے ہیں کہ میں نے ایک مالی بوجھ اپنے ذمے لے لیا، پھر اس کی (ادائیگی میں تعاون کی) بابت سوال کرنے لیے میں رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوا۔ آپ نے فرمایا: ’’قبیصہ! ہمارے پاس ٹھہرو۔ کوئی صدقہ آگیا تو تمھیں دینے کا حکم دیں گے۔‘‘ پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اے قبیصہ! زکاۃ مانگنا صرف تین آدمیوں کے لیے جائز ہے: ایک تو وہ شخص جس نے (جھگڑا نمٹانے کے لیے) کوئی (مالی) بوجھ اپنے ذمے لے لیا، تو اس کے لیے زکاۃ و صدقات لینا جائز ہے، حتیٰ کہ اس کی ضرورت پوری ہو جائے۔ اور دوسرا وہ شخص جس پر کوئی ناگہانی آفت آگئی جس نے اس کا مال ختم کر دیا۔ اس کے لیے بھی مانگنا جائز ہے حتیٰ کہ اس کا گزارا ہونے لگے، پھر وہ مانگنے سے رک جائے۔ اور تیسرا وہ شخص جسے فاقوں کی نوبت آگئی حتیٰ کہ اس کی قوم کے تین سمجھ دار (معتبر) آدمی گواہی دیں کہ واقعتا فلاں شخص فاقہ زدہ ہے، تو اس کے لیے بھی مانگنا جائز ہے حتیٰ کہ وہ زندگی گزارنے کے قابل ہو جائے۔ اے قبیصہ! ان حالات کے علاوہ مانگنا حرام ہے اور مانگنے والا حرام کھاتا ہے۔‘‘","f2":"(۱) ’’ناگہانی آفت‘‘ مثلاً: سیلاب، آگ، فصلوں کی بیماری اور طوفان وغیرہ۔ (۲) ’’گواہی دیں۔‘‘ یہ تب ہے جب وہ کمائی کے قابل ہو اور اس کے باوجود فاقہ زدہ ہو۔ ورنہ اگر وہ کمائی کے قابل ہی نہیں، مثلاً: دائمی مریض وغیرہ تو پھر گواہی کی کیا ضرورت ہے؟ الا یہ کہ وہ لوگ اسے جانتے ہی نہ ہوں، تو پھر گواہ کی ضرورت پڑے گی۔"}],[2581,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم منبر پر بیٹھے، ہم بھی آپ کے اردگرد بیٹھے، آپ نے فرمایا: \"اپنے بعد میں تمہارے متعلق دنیا کی رونق و شادابی جس کی تمہارے اوپر بہتات کر دی جائے گی سے ڈر رہا ہوں\"، پھر آپ نے دنیا اور اس کی زینت کا ذکر کیا۔ تو ایک شخص کہنے لگا: کیا خیر شر لے کر آئے گا؟ یہ سن کر رسول اللہ صلی اللہ علیہ وسلم خاموش رہے۔ تو اس سے کہا گیا: تیرا کیا معاملہ ہے کہ تو رسول اللہ صلی اللہ علیہ وسلم سے بات کرتا ہے، اور وہ تجھ سے بات نہیں کرتے؟ اس وقت ہم نے دیکھا کہ آپ پر وحی اتاری جا رہی تھی۔ پھر وحی موقوف ہوئی تو آپ پسینہ پوچھنے لگے، اور فرمایا: \"کیا پوچھنے والا موجود ہے؟ بیشک خیر شر نہیں لاتا ہے، مگر خیر اس سبزہ کی طرح ہے جسے موسم ربیع (بہار) اگاتا ہے، (جانور کو بدہضمی سے) مار ڈالتا ہے، یا مرنے کے قریب کر دیتا ہے مگر اس گھاس کو کھانے والے کو (نقصان نہیں پہنچاتا) جو کھائے یہاں تک کہ جب اس کی دونوں کوکھیں بھر جائیں تو وہ دھوپ میں جا کر سورج کا سامنا کرے، اور پائخانہ پیشاب کرے، پھر (جب بھوک محسوس کرے تو) پھر چرے (اس طرح) یقیناً یہ مال بھی ایک سرسبز و شیریں چیز ہے۔ وہ مسلمان کا کیا ہی بہترین ساتھی ہے اگر وہ اس سے یتیموں، مسکینوں اور مسافروں کو دے، اور جو شخص ناحق مال حاصل کرتا ہے وہ اس شخص کی طرح ہے جو کھاتا ہے لیکن آسودہ نہیں ہوتا، اور یہ قیامت کے دن اس کے خلاف گواہ ہو گا\" ۲؎۔\n§وضاحت\n۱؎: یعنی میرے بعد جو فتوحات کا سلسلہ شروع ہو گا اور جو مال و دولت اس سے تمہیں حاصل ہو گی، اس سے مجھے اندیشہ ہے کہ کہیں تم دنیا کی رنگینیوں اور عیش و عشرت میں پڑ کر اللہ تعالی سے غافل نہ ہو جاؤ، اور آخرت کو بھول بیٹھو۔ ۲؎: کہ اس نے مجھے ناحق حاصل کیا تھا۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ (ایک دفعہ) رسول اللہ صلی اللہ علیہ وسلم منبر پر تشریف فرما ہوئے اور ہم آپ کے اردگرد بیٹھ گئے۔ آپ نے فرمایا: ’’مجھے تمہارے بارے میں اس بات کا ڈر ہے کہ میرے بعد تمہارے لیے دنیا کی زیب وزینت عام کر دی جائے گی۔‘‘ ایک آدمی نے عرض کیا: کیا خیر بھی شر کو لاتا ہے؟ رسول اللہ صلی اللہ علیہ وسلم خاموش ہوگئے۔ اس شخص سے کہا گیا کہ کیا بات ہے کہ تو رسول اللہ صلی اللہ علیہ وسلم سے بات کر رہا ہے اور رسول اللہ صلی اللہ علیہ وسلم تجھ سے بات نہیں کر رہے ہیں؟ پھر ہمیں اندازہ ہوا کہ رسول اللہ صلی اللہ علیہ وسلم پر وحی اتر رہی ہے۔ حالت وحی ختم ہوئی تو آپ نے پسینہ پونچھتے ہوئے فرمایا: ’’کیا وہ شخص موجود ہے جس نے پوچھا تھا؟ واقعتا خیر شر کو نہیں لاتا مگر موسم بہار کا اگایا ہوا سبزہ بھی کبھی جانور کو مار دیتا ہے یا قریب المرگ کر دیتا ہے۔ مگر وہ جانور جو چارہ کھائے حتیٰ کہ جب اس کی کوکھیں ابھر جائیں (اس کا پیٹ بھر جائے) تو وہ عین سورج کی طرف منہ کر کے بیٹھ جائے (جگالی کرے) گوبر کرے، پیشاب کرے، پھر (جب بھوک لگے تو) چرنے لگے۔ یقینا یہ مال سبز اور میٹھا ہے۔ بلا شبہ یہ مومن کا اچھا ساتھی ہے بشرطیکہ وہ اس سے یتیم، مسکین اور مسافر کو دے۔ جو شخص اس مال کو ناحق لیتا ہے، وہ اس (بیماری) شخص کی طرح ہے جو کھاتا رہتا ہے، مگر سیر نہیں ہوتا۔ اور یہ مال قیامت کے دن اس شخص کے خلاف گواہی دے گا۔‘‘","f2":"(۱) ’’مجھے تو اس بات کا ڈر ہے۔‘‘ معلوم ہوتا ہے کہ لوگوں نے فقر کی شکایت کی تو آپ نے فرمایا: مجھے فقر کا کوئی خطرہ نہیں، یعنی اگر تم فقیر رہو تو کوئی خطرے کی بات نہیں بلکہ خطرہ مال دار ہونے میں ہے کہ کہیں فتنے میں نہ پڑ جاؤ۔ یا یہ مطلب ہے کہ مجھے یہ خطرہ نہیں کہ تم فقیر رہو گے بلکہ خطرہ ہے، تم مال دار ہو جاؤ گے۔ (۲) ’’کیا خیر بھی… الخ‘‘ یعنی مال تو اچھی چیز ہے۔ یہ کون سی خطرناک چیز ہے جو آپ اسے خطرہ قرار دے رہے ہیں۔ (۳) ’’موسم بہار کا اگایا ہوا سبزہ۔‘‘ حالانکہ یہ جانوروں کے لیے بہترین غزا ہوتا ہے مگر اس کا غلط استعمال موت کا سبب بن جاتا ہے۔ اسی طرح مال کا غلط حصول یا استعمال بھی دین کے لیے خطرناک ہے۔ (۴) ’’سبز اور میٹھا ہے۔‘‘ سبزہ جانور کو اور میٹھی چیز انسان کو مرغوب ہوتی ہے، اس لیے ان میں بے اعتدالی ہو جاتی ہے۔ نتیجہ نقصان کی صورت میں نکلتا ہے۔ یہی حالت مال کی ہے۔ (۵) ’’مگر سیر نہیں ہوتا۔‘‘ یہ بھی ایک بیماری ہوتی ہے حتیٰ کہ وہ شخص زیادہ کھانے کی وجہ سے مر جاتا ہے۔ (۶) یتیم صدقے کا حق دار ہے بشرطیکہ وہ فقیر بھی ہو۔ اسی طرح مسافر بھی۔ (۷) مسکین وہ ہے جس کے پاس کچھ مال ہے مگر ضرورت سے کم۔"}],[2582,"سلمان بن عامر رضی اللہ عنہ نبی اکرم صلی اللہ علیہ وسلم سے روایت کرتے ہیں کہ آپ نے فرمایا: \"مسکین کو صدقہ کرنا صرف صدقہ ہے، اور رشتہ دار مسکین کو صدقہ کرنا صدقہ بھی ہے، اور صلہ رحمی بھی\"۔","الألباني: صحيح",{"u2":"حضرت سلمان بن عامر رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’مسکین آدمی کو صدقہ دینا صرف صدقہ ہے جبکہ قرابت دار کو صدقہ دینا صدقہ بھی ہے اور صلہ رحمی بھی۔‘‘","f2":"فقیر قرابت دار اپنے قرب کی وجہ سے زیادہ مستحق ہے، لہٰذا اسے دینے میں دگنا ثواب ہے۔ صدقے کا بھی اور صلہ رحمی کا بھی، مگر جس قرابت دار کے اخراجات کی ذمہ داری زکاۃ دینے والے پر ہے، اسے وہ زکاۃ نہیں دے سکتا، مثلاً: بیوی، بچے، ماں، باپ، البتہ بہن بھائیوں کو، جو الگ رہتے ہوں، زکاۃ دے سکتا ہے۔"}],[2583,"عبداللہ بن مسعود رضی اللہ عنہ کی بیوی زینب رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے عورتوں سے فرمایا: \"تم صدقہ دو اگرچہ اپنے زیوروں ہی سے سہی\"، وہ کہتی ہیں: عبداللہ بن مسعود رضی اللہ عنہ (میرے شوہر) تنگ دست و مفلس تھے، تو میں نے ان سے پوچھا: کیا میرے لیے یہ گنجائش ہے کہ میں اپنا صدقہ آپ کو اور اپنے یتیم بھتیجوں کو دے دیا کروں؟ عبداللہ بن مسعود رضی اللہ عنہ نے کہا: اس بارے میں تم رسول اللہ صلی اللہ علیہ وسلم سے پوچھو۔ زینب رضی اللہ عنہا کہتی ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کے پاس آئی تو کیا دیکھتی ہوں کہ انصار کی ایک عورت اسے بھی زینب ہی کہا جاتا تھا آپ کے دروازے پر کھڑی ہے، وہ بھی اسی چیز کے بارے میں پوچھنا چاہتی تھی جس کے بارے میں میں پوچھنا چاہتی تھی۔ اتنے میں بلال رضی اللہ عنہ اندر سے نکل کر ہماری طرف آئے، تو ہم نے ان سے کہا: آپ رسول اللہ صلی اللہ علیہ وسلم کے پاس جائیں، اور آپ سے اس کے بارے میں پوچھیں، اور آپ کو یہ نہ بتائیں کہ ہم کون ہیں، چنانچہ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس گئے (اور آپ سے پوچھا) آپ نے پوچھا: یہ دونوں کون ہیں؟ انہوں نے کہا: زینب، آپ نے فرمایا: کون سی زینب؟ انہوں نے کہا: ایک زینب تو عبداللہ بن مسعود رضی اللہ عنہ کی بیوی، اور ایک زینب انصار میں سے ہیں۔ آپ نے فرمایا: \"ہاں (درست ہے) انہیں دوہرا ثواب ملے گا ایک رشتہ داری کا اور دوسرا صدقے کا\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ کی بیوی حضرت زینب رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے (ایک دفعہ) عورتوں سے فرمایا: ’’صدقہ کرو چاہے زیورات ہی سے ہو۔‘‘ حضرت عبداللہ بن مسعود رضی اللہ عنہ تقریباً خالی ہاتھ تھے۔ ان کی بیوی زینب ان سے کہنے لگیں: کیا اس بات کی گنجائش ہے کہ میں اپنا صدقہ آپ کو اور اپنے بھائی کے یتیم بچوں کو دے دوں؟ حضرت عبداللہ کہنے لگے: اس بارے میں رسول اللہ صلی اللہ علیہ وسلم سے پوچھو۔ وہ کہتی ہیں، میں نبی صلی اللہ علیہ وسلم کے گھر آئی تو آپ کے دروازے پر ایک انصاری عورت کھڑی تھی۔ اس کا نام بھی زینب تھا۔ اس کا مطلوب بھی وہی تھا جو میرا تھا۔ اتنے میں حضرت بلال رضی اللہ عنہ نکلے۔ ہم نے ان سے عرض کیا کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس جائیں اور آپ سے یہ مسئلہ پوچھیں لیکن آپ کو یہ نہ بتانا کہ ہم کون ہیں؟ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس گئے (اور پوچھا) تو آپ نے فرمایا: ’’وہ کون عورتیں ہیں؟‘‘ انھوں نے کہا: زینب۔ آپ نے فرمایا: ’’کون سی زینب؟‘‘ انھوں نے عرض کیا: ایک زینب تو حضرت عبداللہ بن مسعود رضی اللہ عنہ کی بیوی اور دوسری زینب انصاری عورت ہے۔ آپ نے فرمایا: ’’ہاں! انھیں دو اجر ملیں گے: قرابت (صلہ رحمی) کا اجر اور صدقے کا اجر۔‘‘","f2":"(۱) اس حدیث سے ثابت ہوتا ہے کہ بیوی اپنے خاوند کو زکاۃ دے سکتی ہے اگر وہ فقیر ہے تو، کیونکہ خاوند کے اخراجات کی ذمہ داری بیوی نہیں۔ مگر احناف اسے جائز نہیں سمجھتے، وہ اسے نفلی صدقے پر محمول کرتے ہیں لیکن حدیث کے الفاظ سے اس موقف کی تائید نہیں ہوتی۔ حدیث کے الفاظ عام ہیں جو دونوں قسم کے صدقات (نفلی اور فرضی زکاۃ دونوں) کو شامل ہیں۔ (۲) ’’یہ نہ بتانا کہ ہم کون ہیں؟‘‘ یہ ایک روایتی بات تھی ورنہ ممکن نہیں تھا کہ متعلقہ افراد کا تعارف کروائے بغیر سوال کا صحیح جواب لیا جا سکے۔ اسی لیے حضرت بلال رضی اللہ عنہ نے آپ کے پوچھنے پر فوراً بتا دیا کہ وہ کون ہیں، نیز انھوں نے نہ بتانے کا وعدہ بھی نہیں کیا تھا۔ علاوہ ازیں رسول للہ صلی اللہ علیہ وسلم کا فرمان عورتوں کی گزارش پر مقدم تھا۔"}],[2584,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اگر تم میں سے کوئی لکڑیوں کا ایک گٹھا اپنی پیٹھ پر لاد کر لائے، پھر اسے بیچے تو یہ اس سے بہتر ہے کہ وہ کسی آدمی سے مانگے، تو اسے دے یا نہ دے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مذکور ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم میں سے ایک شخص لکڑیوں کا گٹھا اپنی پیٹھ پر اٹھائے اور اسے فروخت کرے (اور منافع حاصل کرے) یہ اس بات سے بہتر ہے کہ وہ کسی آدمی سے مانگے۔ وہ اسے کچھ دے یا نہ دے۔‘‘","f2":"محنت اور مشقت کر کے اپنی عزت نفس محفوظ رکھنا مانگنے کی ذلت سے بدرجہا بہتر ہے۔"}],[2585,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"آدمی برابر مانگتا رہتا ہے یہاں تک کہ وہ قیامت کے روز ایسی حالت میں آئے گا کہ اس کے چہرے پر کوئی لوتھڑا گوشت نہ ہو گا\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’آدمی ہمیشہ مانگتا رہتا ہے حتیٰ کہ وہ قیامت کے دن اس حال میں (لوگوں کے سامنے) آئے گا کہ اس کے چہرے میں گوشت کا ٹکڑا بھی نہ ہوگا۔‘‘","f2":"قیامت کی جزا و سزا دنیوی عمل کے مماثل ہوگی۔ اس شخص نے مانگ مانگ کر اپنے چہرے کو ذلیل کیا حتیٰ کہ کسی کے نزدیک بھی اس کی وقعت نہ رہی اور کوئی شخص اسے احترام سے دیکھنا گوارا نہ کرتا تھا۔ قیامت کے دن بھی اس کا چہرہ اس حال میں ہوگا کہ اس کی عزت ہوگی، نہ کوئی اسے دیکھنا گوارا کرے گا۔ أَعَاذَنَا اللّٰہُ، البتہ یہ اس شخص کی سزا ہے جو پیشہ ور بھکاری ہے۔ جو مجبوری اور ضرورت سے مانگے اور لاچار ہو اسے معافی ہوگی۔"}],[2586,"عائذ بن عمرو رضی اللہ عنہ سے روایت ہے کہ ایک شخص نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، اور اس نے آپ سے مانگا تو آپ نے اسے دیا۔ جب (وہ لوٹ کر چلا اور) اس نے اپنا پیر دروازے کے چوکھٹ پر رکھا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اگر تم لوگ جان پاتے کہ بھیک مانگنے میں کیا (برائی) ہے تو کوئی کسی کے پاس کچھ بھی مانگنے نہ جاتا\"۔","الألباني: حسن",{"u2":"حضرت عائذ بن عمرو رضی اللہ عنہ سے منقول ہے کہ ایک آدمی نبی صلی اللہ علیہ وسلم کے پاس آیا اور آپ سے کچھ مانگنے لگا۔ آپ نے اسے دے دیا۔ جب اس نے اپنا پاؤں دروازے کی دہلیز پر رکھا تو آپ نے فرمایا: ’’اگر تم مانگنے کی قباحت (یا سزا و گناہ) جان لو تو تم میں سے کوئی کسی کے پاس کچھ بھی مانگنے نہ جائے۔‘‘"}],[2587,"فراسی رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: اللہ کے رسول! میں مانگوں؟ آپ نے فرمایا: \"نہیں، اور اگر تمہیں مانگنا ضروری ہو تو نیکو کاروں سے مانگو\"۔","الألباني: ضعيف",{"u2":"ابن فراسی سے روایت ہے کہ میرے والد حضرت فراسی رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کیا: اے اللہ کے رسول! کیا میں کسی سے کچھ مانگ لیا کروں؟ آپ نے فرمایا: ’’نہیں۔ اور اگر تجھے مجبوراً مانگنا پڑے تو نیک لوگوں سے مانگ۔‘‘"}],[2588,"ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ انصار میں سے کچھ لوگوں نے رسول اللہ صلی اللہ علیہ وسلم سے سوال کیا، تو آپ نے انہیں دیا، ان لوگوں نے پھر سوال کیا، تو آپ نے انہیں پھر دیا یہاں تک کہ آپ کے پاس جو کچھ تھا ختم ہو گیا، تو آپ نے فرمایا: \"میرے پاس جو ہو گا اسے میں ذخیرہ بنا کر نہیں رکھوں گا، اور جو پاک دامن بننا چاہے گا اللہ تعالی اسے پاک دامن بنا دے گا، اور جو صبر کرے گا اللہ تعالی اسے صبر کی توفیق دے گا، اور صبر سے بہتر اور بڑی چیز کسی کو نہیں دی گئی ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ سے مروی ہے کہ کچھ انصار نے رسول اللہ صلی اللہ علیہ وسلم سے (مال) مانگا۔ آپ نے انھیں عطا کیا۔ انھوں نے پھر مانگا۔ آپ نے پھر دیا حتیٰ کہ جب آپ کے پاس جو کچھ تھا ختم ہوگیا، تو آپ نے فرمایا: ’’میرے پاس جو بھی مال ہوگا، میں وہ تم سے چھپا کر نہ رکھوں گا۔ اور جو شخص سوال سے پرہیز کرے گا، اللہ تعالیٰ اسے مانگنے سے محفوظ رکھے گا۔ اور جو شخص صبر کرے گا، اللہ تعالیٰ اسے صابر بنائے گا۔ اور کسی شخص کو صبر سے زیادہ اچھا اور وسیع عطیہ نہیں دیا گیا۔‘‘","f2":"(۱) ’’محفوظ رکھے گا۔‘‘ یعنی جو شخص سوال سے (مانگنے سے) بچنا چاہے گا تو اللہ تعالیٰ اسے ایسا موقع ہی نہیں آنے دے گا کہ اسے مانگنا پڑے۔ اللہ تعالیٰ اس کی ضروریات پوری فرماتا رہے گا مگر وہ حوصلہ رکھے اور لوگوں سے مانگنے میں جلدی نہ کرے۔ (۲) ’’صابر بنائے گا۔‘‘ یعنی صبر کے حصول کے لیے عزم کی بھی ضرورت ہے۔ ہمت کرے انسان تو کیا نہیں ہو سکتا۔ (۳) ’’وسیع عطیہ‘‘ یعنی صبر بہت بڑا عطیہ ہے مگر مصیبت زدہ کے لیے۔ ویسے اللہ تعالیٰ سے صبر کے اسباب نہیں مانگنے چاہئیں۔ ہاں! اگر کوئی مصیبت سر پر آن پڑے تو صبر مانگے۔ صبر کا مفہوم بہت وسیع ہے۔ دین پر پختگی، حرام اور گناہ سے پرہیز، حوصلہ مندی اور مصیبت میں نہ گھبرانا یہ سب صبر ہی کے معانی ہیں۔"}],[2589,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"قسم ہے اس ذات کی جس کے ہاتھ میں میری جان ہے، ایک شخص کا اپنی رسی لے کر لکڑیوں کا گٹھا باندھ کر پیٹھ پر لادنا اس سے بہتر ہے کہ وہ کسی ایسے شخص کے پاس جائے جسے اللہ تعالی نے اپنے فضل (مال) سے نوازا ہو، وہ اس سے مانگے، تو وہ اسے دے یا نہ دے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’قسم اس ذات کی جس کے ہاتھ میں میری جان ہے! تم میں سے ایک شخص اپنی رسی پکڑے اور اپنی پشت پر لکڑیوں کا گٹھا لاد کر لائے (اور اسے بیچ کر گزارا کرے) اس بات سے کہیں زیادہ بہتر ہے کہ وہ کسی ایسے آدمی کے پاس جائے جسے اللہ تعالیٰ نے اپنے فضل سے نواز رکھا ہے اور اس سے جا کر مانگے، پھر وہ اسے دے یا نہ دے۔‘‘","f2":"’’اپنے فضل‘‘ قرآن وحدیث میں عموماً فضل سے مراد دنیوی رزق ہوتا ہے اور رحمت سے مراد اخروی ثواب۔ کسی آدمی سے دنیوی چیز ہی مانگی جا سکتی ہے۔"}],[2590,"ثوبان رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص مجھے ایک بات کی ضمانت دے تو اس کے لیے جنت ہے\" (یحیی کہتے ہیں: یہاں ایک لفظ تھا جس کا مفہوم یہ ہے کہ) \"وہ لوگوں سے کچھ نہ مانگے\"۔","الألباني: صحيح",{"u2":"حضرت ثوبان رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص مجھے ایک بات کی ضمانت دے دے، اس کے لیے جنت ہے۔ اور وہ بات یہ ہے کہ وہ کسی انسان سے کچھ نہ مانگے گا۔‘‘","f2":"جنت کا وعدہ معمولی بات نہیں مگر کسی سے کچھ نہ مانگنے کی پابندی بھی بہت مشکل امر ہے۔ اس کے لیے جس حوصلے اور ضبط و توکل کی ضرورت ہے وہ ہر کسی کے بس کی بات نہیں۔ خال خال ہی لوگ ایسے ل سکتے ہیں۔"}],[2591,"قبیصہ بن مخارق رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: تین شخصوں کے علاوہ کسی اور کے لیے سوال کرنا درست نہیں ہے: ایک وہ شخص جس کا مال کسی آفت کا شکار ہو گیا ہو تو وہ مانگ سکتا ہے یہاں تک کہ وہ گزارے کا کوئی ایسا ذریعہ حاصل کر لے جس سے اس کی ضرورتیں پوری ہو سکیں، پھر رک جائے، (دوسرا) وہ شخص جو کسی کا قرض اپنے ذمہ لے لے تو وہ قرض لوٹانے تک مانگ سکتا ہے، پھر (جب قرض ادا ہو جائے) تو مانگنے سے رک جائے۔ اور(تیسرا) وہ شخص جس کی قوم کے تین سمجھدار افراد اللہ کے نام کی قسم کھا کر اس کی محتاجی و تنگ دستی کی گواہی دیں کہ فلاں شخص کے لیے مانگنا جائز ہے تو وہ مانگ سکتا ہے، یہاں تک کہ وہ گزارے کا کوئی ایسا ذریعہ نہ حاصل کر لے جس سے اس کی ضرورتیں پوری ہو سکیں، ان (تین صورتوں) کے علاوہ مانگنا حرام ہے\"۔","الألباني: صحيح",{"u2":"حضرت قبیصہ بن مخارق رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’مانگنا صرف تین آدمیوں کے لیے جائز ہے: ایک وہ شخص جس کے مال پر کوئی ناگہانی آفت آگئی تو وہ مانگ سکتا ہے حتیٰ کہ گزارا ہو سکے، پھر وہ مانگنے سے باز آجائے۔ اور ایک وہ شخص جس نے کوئی تاوان اپنے ذمے لے لیا، وہ مانگ سکتا ہے حتیٰ کہ وہ تاوان ادا کرے، پھر وہ مانگنے سے باز آجائے۔ اور ایک وہ شخص جس کی قوم کے تین سمجھ دار (معزز) اشخاص اللہ تعالیٰ کے نام کی قسم اٹھائیں کہ فلاں شخص (کی حالت یہ ہوگئی ہے کہ اس) کے لیے مانگنا حلال ہوگیا ہے۔ تو وہ مانگ سکتا ہے حتیٰ کہ مناسب گزارا کر سکے، پھر وہ مانگنے سے باز آجائے۔ ان تین صورتوں کے علاوہ مانگنا حرام ہے۔‘‘","f2":"دیکھیے حدیث: ۲۵۸۰، ۲۵۸۱۔"}],[2592,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو مانگے اور اس کے پاس ایسی چیز ہو جو اسے مانگنے سے بے نیاز کرتی ہو، تو وہ قیامت کے دن اپنے چہرے پر خراشیں لے کر آئے گا\"، عرض کیا گیا: اللہ کے رسول! کتنا مال ہو تو اسے غنی (مالدار) سمجھا جائے گا؟ آپ نے فرمایا: \"پچاس درہم، یا اس کی قیمت کا سونا ہو\"۔ یحیی بن آدم کہتے ہیں: سفیان ثوری نے کہا کہ میں نے زبید سے بھی سنا ہے، وہ محمد بن عبدالرحمٰن بن یزید کے واسطہ سے (یہ حدیث) بیان کر رہے تھے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص مانگے، حالانکہ اس کے پاس اتنا مال ہے جو اسے کفایت کر سکتا ہے، تو قیامت کے دن اس کا چہرہ نوچا ہوا ہوگا۔‘‘ پوچھا گیا: اے اللہ کے رسول! کتنا مال ایک شخص کو کفایت کر سکتا ہے؟ آپ نے فرمایا: ’’پچاس درہم یا اس (کے برابر) مالیت کا سونا۔‘‘\nیحییٰ کہتے ہیں کہ سفیان ثوری نے کہا، میں نے زبید کو سنا وہ اسے محمد بن عبدالرحمن بن یزید سے بیان کر رہے تھے۔","f2":"(۱) مذکورہ روایت کو محقق کتاب نے سنداً ضعیف قرار دیا ہے جبکہ دیگر محققین نے شواہد و متابعات کی بنا پر حسن قرار دیا ہے۔ بنا بریں مذکورہ روایت سنداً ضعیف ہونے کے باوجود شواہد اور متابعات کی بنا پر قابل عمل ہے۔ واللہ اعلم۔ تفصیل کے لیے دیکھیے: (الموسوعۃ الحدیثیۃ مسند الامام احمد: ۶/ ۱۹۴، ۱۹۷ والصحیحۃ للالبانی: ۱/ ۸۹۹، رقم الحدیث: ۴۹۹) (۲) ’’پچاس درہم۔‘‘ یہ تقریباً ۵۲۵۰ روپے کی مالیت کے برابر ہیں، لہٰذا جس شخص کی ملکیت میں اتنا مال ہو اس کے لیے لوگوں سے سوال کرنا درست نہیں۔ بعض روایات میں چالیس درہم کا ذکر ہے، یہ حالات کے مطابق ہے۔ واللہ اعلم"}],[2593,"معاویہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"چمٹ کر مت مانگو، اور تم میں سے کوئی مجھ سے کوئی چیز اس لیے نہ مانگے کہ میں اسے جو دوں اس میں اسے برکت دی جائے، اور حال یہ ہو کہ میں اسے نہ دینا چاہوں\"۔","الألباني: صحيح",{"u2":"حضرت معاویہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اصرار کے ساتھ (چمٹ کر) نہ مانگا کرو۔ تم میں سے جو شخص بھی مجھ سے کچھ مانگے گا جبکہ میں اسے دینا پسند نہ کروں (اور وہ مجھے تنگ کر کے کچھ مال لے جائے) تو اس کے لیے اس میں برکت نہ ہوگی جو میں اسے دوں گا۔‘‘","f2":"اصرار، یعنی چمٹ کر مانگنا یہ ہے کہ سائل مسئول کا پیچھا اس وقت تک نہ چھوڑے جب تک وہ اس سے مطلوبہ چیز حاصل نہ کر لے۔ جس شخص کے لیے مانگنا جائز ہے، اصرار اس کے لیے بھی منع ہے۔ ’’میں اسے دینا پسند نہ کروں۔‘‘ آپ تو سب سے بڑھ کر سخی تھے۔ آپ کا پسند نہ کرنا دلیل ہے کہ وہ مستحق نہیں ہے، لہٰذا وہ کچھ لے بھی جائے (اصرار کر کے) تو منجانب اللہ اس میں برکت نہ ہوگی کیونکہ غیر مستحق کبھی آسودہ نہیں ہوتا وہ ہمیشہ فقیر ہی رہتا ہے۔"}],[2594,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس کے پاس چالیس درہم ہوں اور وہ مانگے تو وہ «ملحف» (چمٹ کر مانگنے والا) ہے\"۔","الألباني: حسن صحيح",{"u2":"حضرت عمرو بن شعیب کے پردادا سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو آدمی چالیس درہم ہونے کے باوجود مانگے تو وہ اصرار کے ساتھ (چمٹ کر) مانگنے والا ہے۔‘‘","f2":"تشبیہ کا مقصد عدم جواز ہے، یعنی اس کے لیے مانگنا جائز نہیں۔ اس روایت میں چالیس درہم کو غنیٰ کی حد بتلایا گیا ہے۔ یہ اس وقت کے حالات کے مطابق ہے۔ اس میں حالات کے مطابق کمی بیشی ہو سکتی ہے۔"}],[2595,"ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ میری ماں نے مجھے رسول اللہ صلی اللہ علیہ وسلم کے پاس (کچھ مانگنے کے لیے) بھیجا، میں آیا، اور بیٹھ گیا، آپ نے میری طرف منہ کیا، اور فرمایا: \"جو بے نیازی چاہے گا اللہ عزوجل اسے بے نیاز کر دے گا اور جو شخص سوال سے بچنا چاہے گا اللہ تعالی اسے بچا لے گا، اور جو تھوڑے پر قناعت کرے گا اللہ تعالی اسے کافی ہو گا۔ اور جو شخص مانگے اور اس کے پاس ایک اوقیہ (یعنی چالیس درہم) کے برابر مال ہو تو گویا اس نے چمٹ کر مانگا\"، تو میں نے(اپنے دل میں) کہا: میری اونٹنی یاقوتہ ایک اوقیہ سے بہتر ہے، چنانچہ میں آپ سے بغیر کچھ مانگے واپس چلا آیا۔","الألباني: حسن صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ سے مروی ہے کہ مجھے میری والدہ نے رسول اللہ صلی اللہ علیہ وسلم کے پاس بھیجا۔ میں آپ کے پاس آکر بیٹھ گیا۔ آپ نے اپنا چہرہ انور میری طرف فرمایا اور گویا ہوئے: ’’جو شخص اپنے آپ کو مستغنی ظاہر کرے، اللہ تعالیٰ اسے غنی فرما دیتا ہے۔ اور جو شخص سوال سے پرہیز کرے، اللہ تعالیٰ اسے سوال سے بچا لیتا ہے۔ اور جو شخص صرف کفایت کا طالب ہو، اللہ تعالیٰ اسے کفایت فرماتا ہے۔ اور جو شخص ایک اوقیہ (چالیس درہم) کی مالیت والی چیز کے ہوتے ہوئے مانگے تو گویا وہ اصرار کے ساتھ مانگ رہا ہے۔‘‘ (ابو سعید نے فرمایا:) میں نے (دل میں) کہا کہ میری اونٹنی یاقوتہ ایک اوقیے سے زیادہ قیمتی ہے، لہٰذا میں آپ سے مانگے بغیر واپس آگیا۔","f2":"(۱) ’’بھیجا‘‘ کوئی چیز مانگنے کے لیے جیسا کہ حدیث کے آخر سے معلوم ہوتا ہے۔ (۲) ’’مستغنی ظاہر کرے۔‘‘ یعنی باوجود فقیر ہونے کے اپنے فقر کا اظہار نہ کرے۔ (۳) ’’کفایت کا طالب ہو۔‘‘ یعنی وہ حریص نہیں بلکہ ضرورت کے مطابق طلب کرتا ہے۔ یا اللہ تعالیٰ سے کفایت کی دعا کرے۔ (۴) یاقوتہ ان کی اونٹنی کا نام تھا۔"}],[2596,"قبیلہ بنی اسد کے ایک شخص کہتے ہیں کہ میں اور میری بیوی دونوں بقیع الغرقد میں اترے، میری بیوی نے مجھ سے کہا کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس جا کر ہمارے لیے کھانے کی کوئی چیز مانگ کر لائیے، تو میں رسول اللہ صلی اللہ علیہ وسلم کے پاس گیا۔ مجھے آپ کے پاس ایک شخص ملا جو آپ سے مانگ رہا تھا، اور آپ اس سے فرما رہے تھے: \"میرے پاس (اس وقت) تمہیں دینے کے لیے کچھ نہیں ہے\"۔ وہ شخص آپ کے پاس سے پیٹھ پھیر کر غصے کی حالت میں یہ کہتا ہوا چلا: قسم ہے میری زندگی کی! آپ تو اسی کو دیتے ہیں جسے چاہتے ہیں، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"(خواہ مخواہ) مجھ پر اس بات پر غصہ ہو رہا ہے کہ میرے پاس اسے دینے کے لیے کچھ نہیں ہے، (ہوتا تو اسے دیتا ویسے تم لوگ جان لو کہ) تم میں سے جس کے پاس چالیس درہم ہو یا چالیس درہم کی قیمت کے برابر کا مال ہو، اور اس نے مانگا تو اس نے چمٹ کر مانگا\"، اسدی (جو اس حدیث کے راوی ہیں) کہتے ہیں: میں نے (دل میں) کہا: ہماری دو دھاری اونٹنی ایک اوقیہ سے تو بہتر ہی ہے، اوقیہ چالیس درہم کا ہوتا ہے، چنانچہ میں آپ سے بغیر کچھ مانگے لوٹ آیا۔ پھر آپ کے پاس جَو اور کشمش آئے، تو آپ نے ہم کو بھی اس میں سے حصہ دیا، یہاں تک کہ اللہ عزوجل نے ہم کو مالدار کر دیا۔","الألباني: صحيح",{"u2":"بنو اسد کے ایک شخص سے روایت ہے کہ میں اور میری بیوی بقیع الغرقد میں فروکش ہوئے (آئے) تو مجھے میری بیوی کہنے لگی: رسول اللہ صلی اللہ علیہ وسلم کے پاس جاؤ اور کھانے کی کوئی چیز مانگ لاؤ۔ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس گیا تو میں نے آپ کے پاس ایک اور آدمی بیٹھا پایا جو آپ سے مانگ رہا تھا اور رسول اللہ صلی اللہ علیہ وسلم فرما رہے تھے: ’’میرے پاس کوئی ایسی چیز نہیں جو میں تجھے دے سکوں۔‘‘ وہ آدمی غصے کی حالت میں اٹھ کر چلا گیا اور کہنے لگا: میری زندگی کی قسم! جس کو آپ کی مرضی ہو، دے دیتے ہیں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’یہ مجھ پر اس لیے ناراض ہے کہ میرے پاس کوئی ایسی چیز نہیں جو میں اسے دے سکوں (یاد رکھو!) تم میں سے جس شخص نے ایک اوقیہ یا اس کے مساوی دولت کی چیز کا مالک ہونے کے باوجود مانگا تو گویا اس نے اصرار کے ساتھ مانگا (جو کہ مذموم ہے۔‘‘) اسدی شخص نے کہا کہ میں نے (اپنے دل میں) کہا: ہماری دودھ والی اونٹنی یقینا ایک اوقیے سے بڑھ کر ہے۔ اور اوقیہ چالیس درہم کا ہوتا ہے۔ تو میں مانگے بغیر اٹھ آیا۔ کچھ دیر بعد رسول اللہ صلی اللہ علیہ وسلم کے پاس کچھ جو اور کشمش آگئی۔ آپ نے وہ ہم میں تقسیم فرما دیے حتیٰ کہ اللہ تعالیٰ نے ہمیں غنی کر دیا۔","f2":"(۱) ’’جس کو آپ کی مرضی ہو۔‘‘ یعنی آپ استحقاق کی بنا پر نہیں، اپنی ذاتی پسند کی بنا پر دیتے ہیں۔ ممکن ہے وہ شخص منافق ہو یا شاید جذبات کی رو میں بہہ کر کہہ بیٹھا ہو۔ (۲) ’’بقیع الغرقد‘‘ مدینہ منورہ سے متصل وسیع خالی میدان ہے جہاں قبرستان بھی ہے۔ بیرونی قافلے وہاں اترتے تھے۔ اس حدیث کے راوی اسدی بھی باہر ہی سے آئے تھے۔"}],[2597,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"صدقہ کسی مالدار، طاقتور اور صحیح سالم شخص کے لیے درست نہیں\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’زکاۃ وصدقات کسی مال دار شخص یا کسی طاقت ور تندرست شخص کے لیے جائز نہیں۔‘‘","f2":"طاقت ور سے مراد وہ ہے جو کمائی کر سکے، نہ کہ پہلوان۔ اور تندرست سے مراد ہے کہ اس کے ہاتھ پاؤں صحیح ہوں، معذور نہ ہو، البتہ ایسا شخص اگر باوجود محنت کے فقیر ہو تو وہ مستحق ہوگا کیونکہ رسول اللہ صلی اللہ علیہ وسلم کا مقصد یہ ہے کہ زکاۃ نکھٹوؤں کے لیے جائز نہیں۔"}],[2598,"عبیداللہ بن عدی بن خیار رضی اللہ عنہ سے روایت ہے کہ دو شخصوں نے ان سے بیان کیا کہ وہ دونوں رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، دونوں آپ سے صدقہ مانگ رہے تھے، تو آپ نے نگاہ الٹ پلٹ کر انہیں دیکھا (محمد کی روایت میں (نگاہ کے بجائے) اپنی نگاہ ہے تو دونوں کو ہٹا کٹا پایا، تو آپ نے فرمایا: \"اگر چاہو تو لے لو، (لیکن یہ جان لو) کہ مالدار اور کما سکنے والے شخص کے لیے اس میں کوئی حصہ نہیں ہے\"۔","الألباني: صحيح",{"u2":"حضرت عبیداللہ بن عدی بن خیار سے روایت ہے کہ دو آدمیوں نے مجھ سے بیان کیا کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس زکاۃ و صدقات مانگنے آئے۔ آپ صلی اللہ علیہ وسلم نے انھیں غور سے دیکھا تو انھیں موٹا تازہ پایا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اگر تم مجبور کرو تو میں تمہیں دے دیتا ہوں لیکن مال دار، کما سکنے والے طاقت ور شخص کا زکاۃ میں کوئی حصہ نہیں۔‘‘","f2":"دیکھیے حدیث: ۲۶۰۰۔"}],[2599,"سمرہ بن جندب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مانگنا خراش (زخم کی ہلکی لکیر) ہے جسے آدمی اپنے چہرے پر لگاتا ہے، تو جو چاہے اپنے چہرے پر (مانگ کر) خراش لگائے، اور جو چاہے نہ لگائے، مگر یہ کہ آدمی حاکم سے مانگے، یا کوئی ایسی چیز مانگے جس سے چارہ نہ ہو\"۔","الألباني: صحيح",{"u2":"حضرت سمرہ بن جندب رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بلا شبہ مانگنا خراشیں ہیں۔ آدمی اپنے چہرے کو ان کے ذریعے سے نوچتا ہے۔ اب جو چاہے اپنا چہرہ نوچے اور جو چاہے رہنے دے۔ الا یہ کہ کوئی شخص صاحب اقتدار سے مانگے یا ایسی چیز مانگے جس کے بغیر چارہ نہ ہو۔‘‘","f2":"(۱) ’’نوچتا ہے۔‘‘ یعنی دنیا میں ذلت ہے اور آخرت میں تو واقعتا چہرہ نوچا ہوا ہوگا۔ (۲) ’’اپنا چہرہ نوچے۔‘‘ یہ اجازت نہیں بلکہ ڈانٹ ہے، جیسے قرآن کریم میں ارشاد ربانی ہے: {فَمَنْ شَآئَ فَلْیُؤْمِنْ وَّ مَنْ شَآئَ فَلْیَکْفُرْ} (الکھف: ۲۹) ’’چنانچہ جو چاہے ایمان لائے اور جو چاہے کفر کرے۔‘‘ روایت نمبر ۲۵۹۹ میں بھی ڈانٹ ہی ہے کہ تم چاہو تو تمھیں زکاۃ دے دیتا ہوں ورنہ تم مستحق نہیں۔ اگرچہ یہاں کہا جا سکتا ہے کہ ان کی وقتی فقیری کے پیش نظر انھیں دیا جا سکتا تھا کیونکہ کمائی تو وہ بعد میں ہی کر سکتے ہیں۔ (۳) ’’صاحب اقتدار سے مانگے۔‘‘ کیونکہ اس کے پاس مال اپنا ذاتی نہیں بلکہ عوام الناس کا ہے اور اس میں ہر شخص کا حق ہو سکتا ہے۔ حکومت کی ذمہ داری ہے کہ وہ عوام الناس کو ان کی بنیادی ضروریات فراہم کرے۔ (۴) ’’جس کے بغیر چارہ نہ ہو۔‘‘ مثلاً: بھوکا آدمی خوراک مانگ سکتا ہے اور مریض علاج کے لیے تعاون لے سکتا ہے۔"}],[2600,"سمرہ بن جندب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مانگنا خراش ہے جس سے آدمی اپنے چہرے کو زخمی کرتا ہے مگر یہ کہ آدمی حاکم سے مانگے، یا کوئی ایسی چیز مانگے جس کے بغیر چارہ نہیں\"۔","الألباني: صحيح",{"u2":"حضرت سمرہ بن جندب رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مانگنا تو اپنے آپ کو زخمی کرنا ہے۔ اس طریقے سے آدمی اپنے چہرے کو نوچتا ہے، مگر یہ کہ حاکم سے مانگے یا ایسی چیز مانگے جس کے بغیر چارہ نہ ہو۔‘‘"}],[2601,"حکیم بن حزام رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے مانگا تو آپ نے دیا، پھر مانگا تو پھر دیا، پھر آپ نے فرمایا: \"یہ مال ہری بھری اور میٹھی چیز ہے، جو شخص اسے دل کی پاکیزگی کے ساتھ لے گا تو اسے اس میں برکت ملے گی، اور جو شخص اسے نفس کی حرص و طمع سے لے گا تو اس میں اسے برکت نہیں دی جائے گی۔ وہ اس شخص کی طرح ہو گا جو کھائے لیکن اس کا پیٹ نہ بھرے۔ (جان لو) اوپر والا (یعنی دینے والا) ہاتھ نیچے والے (یعنی لینے والے) ہاتھ سے بہتر ہے\"۔","الألباني: صحيح",{"u2":"حضرت حکیم بن حزام رضی اللہ عنہ بیان کرتے ہیں کہ میں نے (ایک دفعہ) رسول اللہ صلی اللہ علیہ وسلم سے مانگا، آپ نے دے دیا۔ میں نے پھر مانگا، آپ نے پھر دے دیا، میں نے پھر مانگا، آپ نے پھر دیا مگر ساتھ ہی فرمایا: ’’اے حکیم! بلا شبہ یہ مال سبز وشیریں ہے۔ جو شخص اسے نفس کی پاکیزگی کے ساتھ لے گا، اس کے لیے اس میں برکت ہوگی۔ اور جو اسے لالچ اور طمع کے ساتھ لے گا، اس کے لیے اس میں برکت نہ ہوگی۔ اور وہ اس شخص کی طرح ہوگا جو کھاتا ہے لیکن سیر نہیں ہوتا۔ اور اوپر والا ہاتھ نیچے والے ہاتھ سے بہتر ہے۔‘‘","f2":"برکت سے مراد یہ ہے کہ تھوڑا مال بھی کفایت کر جائے گا اور برکت نہ ہونے سے مراد یہ ہے کہ کثیر مال کے باوجود بھی وہ فقیر رہے گا۔ یا تو حقیقتاً کہ اللہ تعالیٰ اس پر ناگہانی آفات طاری کرتا رہے گا جس سے مال ضائع ہوتا رہے گا یا ظاہراً کہ وہ فقیروں جیسا کردار ظاہر کرے گا، مثلاً: لوگوں کے مال پر نظر رکھے گا، وغیرہ۔ (تفصیل کے لیے دیکھیے حدیث: ۲۵۳۲)"}],[2602,"حکیم بن حزام رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے مانگا تو آپ نے مجھے دیا، پھر مانگا تو آپ نے پھر دیا، پھر مانگا تو آپ نے پھر دیا، پھر آپ نے فرمایا: \"حکیم! یہ مال ہری بھری اور میٹھی چیز ہے۔ جو اسے طبیعت کی فیاضی کے ساتھ لے گا تو اسے اس میں برکت دی جائے گی، اور جو نفس کی حرص و لالچ کے ساتھ لے گا تو اسے اس میں برکت نہیں دی جائے گی۔ اور وہ اس شخص کی طرح ہو گا جو کھاتا ہو لیکن آسودہ نہ ہوتا ہو، اور اوپر والا ہاتھ بہتر ہے نیچے والے ہاتھ سے\"۔","الألباني: صحيح",{"u2":"حضرت حکیم بن حزام رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے (مال) مانگا، آپ نے دے دیا۔ میں نے پھر مانگا، آپ نے پھر دے دیا۔ میں نے پھر مانگا، آپ نے پھر دیا۔ اور فرمایا: ’۔اے حکیم! بلا شبہ یہ مال سبز وشیریں ہے۔ جو شخص اسے قناعت قلب کے ساتھ لے گا، اس کے لیے اس میں برکت ہوگی۔ اور جو شخص اسے دلی طمع ولالچ کے ساتھ لے گا، اس کے لیے اس میں برکت نہ ہوگی۔ اور وہ اس شخص کی طرح ہوگا جو کھاتا ہے مگر سیر نہیں ہوتا۔ اور اوپر والا ہاتھ نیچے والے ہاتھ سے (بہر صورت) بہتر ہے۔‘‘"}],[2603,"حکیم بن حزام رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے مانگا تو آپ نے مجھے دیا، میں نے پھر مانگا تو آپ نے پھر دیا۔ پھر آپ نے فرمایا: \"اے حکیم! یہ مال میٹھی چیز ہے، جو شخص اسے نفس کی فیاضی کے ساتھ لے گا تو اس میں اسے برکت دی جائے گی، اور جو شخص اسے حرص و طمع کے ساتھ لے گا تو اسے اس میں برکت نہیں دی جائے گی۔ اور وہ اس شخص کی طرح ہو گا جو کھائے تو لیکن اس کا پیٹ نہ بھرے۔ اور (جان لو) اوپر والا ہاتھ بہتر ہے نیچے والے سے\"۔ میں نے کہا: اللہ کے رسول! قسم ہے اس ذات کی جس نے آپ کو حق کے ساتھ بھیجا ہے آپ کے بعد اب کسی سے کچھ نہ لوں گا یہاں تک کہ دنیا سے رخصت ہو جاؤں۔","الألباني: صحيح",{"u2":"حضرت حکیم بن حزام رضی اللہ عنہ سے مروی ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے کچھ مانگا۔ آپ نے دیا۔ میں نے پھر مانگا، آپ نے پھر دیا۔ پھر فرمایا: ’’اے حکیم! بلاشبہ یہ مال شیریں (چیز کی طرح اچھا لگتا) ہے لیکن جو شخص اسے بے نیازی سے حاصل کرے گا، اس کے لیے اس میں برکت ہوگی۔ اور جو لالچ کے ساتھ حاصل کرے گا، اس کے لیے اس میں برکت نہ ہوگی۔ اور وہ اس شخص کی طرح ہوگا جو کھاتا ہے مگر سیر نہیں ہوتا۔ اور اوپر والا ہاتھ نیچے والے ہاتھ سے بہتر ہے۔‘‘ میں نے کہا: اے اللہ کے رسول! قسم اس ذات کی جس نے آپ کو حق کے ساتھ بھیجا ہے! میں آپ (کے اس فرمان) کے بعد کبھی کسی سے کچھ نہ لوں گا حتیٰ کہ میں دنیا چھوڑ جاؤں۔","f2":"حضرت حکیم بن حزام رضی اللہ عنہ اس قسم وعہد پر اس قدر پختہ رہے کہ بعد میں خلفائے راشدین انھیں بیت المال سے ان کا وظیفہ دیتے تو اسے بھی قبول نہ فرماتے۔ فاروق اعظم حضرت عمر رضی اللہ عنہ نے اسی بنا پر فرمایا تھا: ’’اے مسلمانوں (صحابہ کرام رضی اللہ عنہم) کی جماعت! تم گواہ رہو کہ میں حکیم کو ان کا حق دیتا ہوں لیکن وہ اپنا حق لینے سے انکار کرتے ہیں۔‘‘ (صحیح البخاری، الزکاۃ، حدیث: ۱۴۷۲) اسی حال میں خالق حقیقی سے جاملے۔"}],[2604,"عبداللہ بن ساعدی مالکی کہتے ہیں کہ عمر بن خطاب رضی اللہ عنہ نے مجھے صدقہ پر عامل بنایا، جب میں اس سے فارغ ہوا اور اسے ان کے حوالے کر دیا، تو انہوں نے اس کام کی مجھے اجرت دینے کا حکم دیا، میں نے ان سے عرض کیا کہ میں نے یہ کام صرف اللہ عزوجل کے لیے کیا ہے، اور میرا اجر اللہ ہی کے ذمہ ہے، تو انہوں نے کہا: ـ میں تمہیں جو دیتا ہوں وہ لے لو، کیونکہ میں نے بھی رسول اللہ صلی اللہ علیہ وسلم کے زمانہ میں ایک کام کیا تھا، اور میں نے بھی آپ سے ویسے ہی کہا تھا جو تم نے کہا ہے، تو رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا: \"جب تمہیں کوئی چیز بغیر مانگے ملے تو (اسے) کھاؤ، اور (اس میں سے) صدقہ کرو\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن ساعدی مالکی سے منقول ہے کہ مجھے حضرت عمر بن خطاب رضی اللہ عنہ نے صدقہ وزکاۃ جمع کرنے پر مقرر فرمایا۔ جب میں اس ذمے داری سے فارغ ہوا اور میں نے (جمع شدہ) مال ان کی خدمت میں پیش کیا تو آپ نے مجھے میری خدمت کا معاوضہ دینے کا حکم جاری فرمایا۔ میں نے کہا: میں نے یہ کام اللہ تعالیٰ کی رضا مندی کے لیے کیا ہے۔ اس کا معاوضہ مجھے اللہ تعالیٰ ہی دے گا۔ آپ نے فرمایا: جو میں تمھیں دے رہا ہوں، لے لو۔ میں نے بھی رسول اللہ صلی اللہ علیہ وسلم کے دور مبارک میں (ایسی ہی) خدمت سرانجام دی تھی اور میں نے بھی آپ سے تیری طرح ہی کہا تھا تو مجھ سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’۔جب تجھے کوئی چیز تیرے مانگے بغیر ملے تو (اسے لے لے اور) کھا۔ اور (چاہے تو) صدقہ کر دے۔‘‘","f2":"ہر سرکاری کارندہ اس پوزیشن میں نہیں ہوتا کہ وہ سرکاری کام بلا معاوضہ کر سکے کیونکہ معاشی مجبوریاں ہوتی ہیں، اس لے ضروری ہے کہ حکومت ہر سرکاری کارندے کو معاوضہ دے اور سرکاری کارندہ اسے وصول کرے کیونکہ اگر بعض وصول کریں، بعض نہ کریں تو وصول کرنے والے شرمندگی ہی محسوس کریں گے۔ ہو سکتا ہے وہ احساس کمتری کا شکار ہو جائیں۔ وصول نہ کرنے کی صورت میں اظہار ہوگا جس سے ذہن میں تکبر و فخر پیدا ہو سکتا ہے۔"}],[2605,"عبداللہ بن السعدی القرشی رضی اللہ عنہ کہتے ہیں کہ وہ شام سے عمر بن خطاب رضی اللہ عنہ کے پاس آئے تو انہوں نے کہا: کیا مجھے یہ خبر نہیں دی گئی ہے کہ تم مسلمانوں کے کاموں میں سے کسی کام پر عامل بنائے جاتے ہو، اور اس پر جو تمہیں اجرت دی جاتی ہے تو اسے تم قبول نہیں کرتے، تو انہوں نے کہا: ہاں یہ صحیح ہے، میرے پاس گھوڑے ہیں، غلام ہیں اور میں ٹھیک ٹھاک ہوں (اللہ کا شکر ہے کوئی کمی نہیں ہے) میں چاہتا ہوں کہ میرا کام مسلمانوں پر صدقہ ہو جائے۔ تو عمر رضی اللہ عنہ نے کہا: جو تم چاہتے ہو وہی میں نے بھی چاہا تھا۔ نبی اکرم صلی اللہ علیہ وسلم مجھے مال دیتے تو میں عرض کرتا: اسے آپ اس شخص کو دے دیجئیے جو مجھ سے زیادہ اس کا ضرورت مند ہو، ایک بار آپ نے مجھے مال دیا تو میں نے عرض کیا: آپ اسے اس شخص کو دے دیجئیے جو اس کا مجھ سے زیادہ ضرورت مند ہو، تو آپ نے فرمایا:\"اللہ عزوجل اس مال میں سے جو تمہیں بغیر مانگے اور بغیر لالچ کئے دے، اسے لے لو، چاہو تم (اسے اپنے مال میں شامل کر کے) مالدار بن جاؤ، اور چاہو تو اسے صدقہ کر دو۔ اور جو نہ دے اسے لینے کے پیچھے مت پڑو\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن سعدی سے روایت ہے کہ مین علاقہ شام سے حضرت عمر بن خطاب رضی اللہ عنہ کی خدمت میں حاضر ہوا۔ انھوں نے فرمایا: مجھے بتایا گیا ہے کہ تم مسلمانوں کے کام (سرکاری خدمات) سر انجام دیتے ہو اور پھر جب تمہیں معاوضہ دیا جاتا ہے تو تم قبول نہیں کرتے؟ میں نے عرض کیا: جی ہاں! میرے پاس بہت سے گھوڑے اور غلام ہیں۔ میں مال دار ہوں اور چاہتا ہوں کہ میری تنخواہ مسلمانوں پر صدقہ ہو جائے۔ حضرت عمر رضی اللہ عنہ نے فرمایا: (رسول اللہ صلی اللہ علیہ وسلم کے دور میں) میں نے بھی ایسا ہی کرنا چاہا تھا جس طرح تو نے کرنا چاہا ہے کہ رسول اللہ صلی اللہ علیہ وسلم مجھے مال وغیرہ (بصورت معاوضہ) عطا فرماتے تو میں کہہ دیتا کہ یہ کسی ایسے شخص کو دے دیجئے جو مجھ سے زیادہ ضرورت مند ہو۔ ایک دفعہ آپ نے مجھے کچھ مال عطا فرمایا تو میں نے عرض کیا کہ یہ ایسے شخص کو دے دیں جو مجھ سے زیادہ مہتاج ہو، تو آپ نے فرمایا: ’۔جو مال تجھے اللہ تعالیٰ تیرے مانگے اور لالچ و طمع کے بغیر دے، اسے لے لیا کر، پھر چاہے تو اپنے پاس رکھ، چاہے صدقہ کر دے۔ اور جو مال اس طرح اپنے آپ نہ ملے اس کے پیچھے اپنے آپ کو نہ لگا۔‘‘","f2":"(۱) ’’اللہ تعالیٰ دے۔‘‘ انسان کو جو کچھ بھی میسر ہے، وہ اللہ تعالیٰ ہی کی طرف سے ہے، خواہ ظاہراً کسی آدمی کے ہاتھوں ملے کیونکہ ہر چیز کا خالق ومالک اللہ تعالیٰ ہے۔ دینے والے کے دل میں دینے کا خیال بھی اللہ تعالیٰ کی طرف سے ہوتا ہے۔ جن صلاحیتوں کی وجہ سے مال ملتا ہے، وہ بھی اللہ تعالیٰ کا عطیہ ہیں۔ حساب بھی اللہ تعالیٰ ہی لے گا۔ (۲) ان احادیث میں تنخواہ اور معاوضے کا ذکر ہے۔ تحفے اور صدقے میں بھی یہی اصول ہے کہ اگر بغیر مانگے حاصل ہو تو انکار نہیں کرنا چاہیے، البتہ صدقے کی صورت میں مستحق زکاۃ ہونا ضروری ہے۔ (۳) تحفے کا بدلہ دینا چاہیے۔"}],[2606,"عبداللہ بن السعدی رضی اللہ عنہ کہتے ہیں کہ وہ عمر بن خطاب رضی اللہ عنہ کے پاس ان کی خلافت کے زمانہ میں آئے، تو عمر رضی اللہ عنہ نے ان سے کہا: کیا مجھے یہ نہیں بتایا گیا ہے کہ تم عوامی کاموں میں سے کسی کام کے ذمہ دار ہوتے ہو اور جب تمہیں مزدوری دی جاتی ہے تو قبول نہیں کرتے لوٹا دیتے ہو؟ میں نے کہا: جی ہاں(صحیح ہے) اس پر عمر رضی اللہ عنہ نے کہا: اس سے تم کیا چاہتے ہو؟ میں نے کہا: میرے پاس گھوڑے، غلام ہیں اور میں ٹھیک ٹھاک ہوں (مجھے کسی چیز کی محتاجی نہیں ہے) میں چاہتا ہوں کہ میرا کام مسلمانوں پر صدقہ ہو۔ تو عمر رضی اللہ عنہ نے ان سے کہا: ایسا نہ کرو کیونکہ میں بھی یہی چاہتا تھا جو تم چاہتے ہو (لیکن اس کے باوجود)رسول اللہ صلی اللہ علیہ وسلم مجھے عطیہ (بخشش) دیتے تھے تو میں عرض کرتا تھا: اسے میرے بجائے اس شخص کو دے دیجئیے جو مجھ سے زیادہ اس کا ضرورت مند ہو، تو آپ فرماتے: \"اسے لے کر اپنے مال میں شامل کر لو، یا صدقہ کر دو، سنو! تمہارے پاس اس طرح کا جو بھی مال آئے جس کا نہ تم حرص رکھتے ہو اور نہ تم اس کے طلب گار ہو تو وہ مال لے لو، اور جو اس طرح نہ آئے اس کے پیچھے اپنے آپ کو نہ ڈالو\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن سعدی نے بتایا کہ میں حضرت عمر بن خطاب رضی اللہ عنہ کے دور خلافت میں ان کے پاس حاضر ہوا تو حضرت عمر رضی اللہ عنہ نے مجھ سے فرمایا: کیا یہ بات درست ہے کہ تم سرکاری کام کرتے ہو اور جب تمھیں حق الخدمت دیا جاتا ہے تو تم واپس کر دیتے ہو؟ میں نے کہا: جی ہاں۔ حضرت عمر رضی اللہ عنہ فرمانے لگے: تمھارا مقصد کیا ہوتا ہے؟ میں نے کہا: میرے پاس بہت سے گھوڑے اور غلام ہیں۔ میں مال دار ہوں۔ (میرے پاس اللہ تعالیٰ کا دیا بہت کچھ ہے۔) میں چاہتا ہوں کہ میری تنخواہ مسلمانوں پر صدقہ ہو جائے۔ حضرت عمر رضی اللہ عنہ نے فرمایا: ایسے نہ کیا کرو۔ میں نے بھی (رسول اللہ صلی اللہ علیہ وسلم کے دور مبارک میں) ایسا ہی کرنا چاہا تھا جس طرح تو نے کرنا چاہا ہے۔ رسول اللہ صلی اللہ علیہ وسلم مجھے کوئی عطیہ وغیرہ دیتے تو میں کہہ دیتا کہ یہ کسی ایسے شخص کو دے دیجئے جسے اس کی مجھ سے زیادہ ضرورت ہو۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’۔لے لیا کر، پھر جی چاہے تو رکھ لے، نہیں تو صدقہ کر دیا کر۔ اس قسم کا مال جو تیرے پاس بغیر تیری طمع اور خواہش کے آئے، وہ لے لیا کر اور جو اس طرح نہ ملے اس کے پیچھے اپنے آپ کو نہ لگا۔‘‘"}],[2607,"عبداللہ بن السعدی رضی اللہ عنہ کہتے ہیں کہ وہ عمر بن خطاب رضی اللہ عنہ کے زمانہ خلافت میں ان کے پاس آئے تو عمر رضی اللہ عنہ نے کہا: کیا مجھے یہ خبر نہیں دی گئی ہے کہ تم عوامی کاموں میں سے کسی کام کے والی ہوتے ہو تو جب تمہیں اجرت دی جاتی ہے تو تم اسے ناپسند کرتے ہو؟ وہ کہتے ہیں: میں نے کہا: کیوں نہیں (ایسا تو ہے) انہوں نے کہا: اس سے تم کیا چاہتے ہو؟ میں نے کہا: میرے پاس گھوڑے اور غلام ہیں اور میں ٹھیک ٹھاک ہوں، میں چاہتا ہوں کہ میرا کام مسلمانوں پر صدقہ ہو جائے، اس پر عمر رضی اللہ عنہ نے کہا: ایسا نہ کرو، کیونکہ میں بھی وہی چاہتا تھا جو تم چاہتے ہو۔ نبی اکرم صلی اللہ علیہ وسلم مجھے عطایا (بخشش) دیتے تھے، تو میں عرض کرتا تھا: آپ اسے دے دیں جو مجھ سے زیادہ اس کا ضرورت مند ہو، یہاں تک کہ ایک بار آپ نے مجھے کچھ مال دیا، میں نے کہا: آپ اسے اس شخص کو دے دیں جو مجھ سے زیادہ اس کا ضرورت مند ہو، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اسے لے کر اپنے مال میں شامل کر لو، نہیں تو صدقہ کر دو۔ (سنو!) اس مال میں سے جو بھی تمہیں بغیر کسی لالچ کے اور بغیر مانگے ملے اس کو لے لو، اور جو نہ ملے اس کے پیچھے نہ پڑو\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن سعدی نے خبر دی کہ میں حضرت عمر بن خطاب رضی اللہ عنہ کے دور حکومت میں آپ کے پاس آیا تو آپ فرمانے لگے: مجھے پتا چلا ہے کہ تو لوگوں کی خدمات سر انجام دیتا ہے لیکن جب تجھے تنخواہ دی جاتی ہے تو تو اسے ناپسند کرتا ہے؟ میں نے کہا: ہاں! (ایسے ہی ہے)۔ تو انھوں نے فرمایا: تمہارا مقصد کیا ہوتا ہے؟ میں نے کہا: میرے پاس بہت سے گھوڑے اور غلام ہیں اور میں مال دار ہوں (اچھا گزارا کر رہا ہوں)۔ میں چاہتا ہوں کہ میری تنخواہ مسلمانوں پر صدقہ ہو جائے۔ حضرت عمر رضی اللہ عنہ نے فرمایا ایسے نہ کر۔ میں نے بھی ایسا ہی کرنا چاہا تھا جس طرح تو نے کرنا چاہا ہے۔ نبی صلی اللہ علیہ وسلم مجھے تنخواہ وغیرہ دیتے تو میں کہہ دیتا کہ یہ کسی زیادہ حاجت مند کو دے دیجئے، حتیٰ کہ ایک دفعہ آپ نے مجھے کچھ مال دیا۔ میں نے (حسب عادت) کہہ دیا کہ یہ مجھ سے زیادہ محتاج کو دے دیجئے۔ تو نبی صلی اللہ علیہ وسلم فرمانے لگے: ’’لے لے، پھر رکھ یا صدقہ کر۔ اس قسم کا مال تیرے پاس آئے جبکہ تجھے نہ لالچ ہو اور نہ تو نے مانگا ہو تو وہ لے لیا کر اور جو خود بخود نہ ملے، اس کے پیچھے اپنے آپ کو نہ لگا۔"}],[2608,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ میں نے عمر رضی اللہ عنہ کو کہتے سنا کہ نبی اکرم صلی اللہ علیہ وسلم مجھے عطیہ دیتے تو میں کہتا: آپ اسے اس شخص کو دے دیجئیے جو مجھ سے زیادہ ضرورت مند ہو۔ یہاں تک کہ ایک بار آپ نے مجھے کچھ مال دیا تو میں نے آپ سے عرض کیا: اسے اس شخص کو دے دیجئیے جو مجھ سے زیادہ اس کا حاجت مند ہو، تو آپ نے فرمایا: \"تم لے لو، اور اس کے مالک بن جاؤ، اور اسے صدقہ کر دو، اور جو مال تمہیں اس طرح ملے کہ تم نے اسے مانگا نہ ہو اور اس کی لالچ کی ہو تو اسے قبول کر لو، اور جو اس طرح نہ ملے اس کے پیچھے اپنے آپ کو نہ ڈالو\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے حضرت عمر رضی اللہ عنہ کو فرماتے ہوئے سنا کہ نبی صلی اللہ علیہ وسلم مجھے کوئی عطیہ عنایت فرماتے تو میں کہہ دیا کرتا تھا کہ یہ کسی ایسے شخص کو دے دیجئے جسے مجھ سے زیادہ اس کی ضرورت ہو، حتیٰ کہ ایک دفعہ آپ نے مجھے کچھ مال دیا تو میں نے کہہ دیا: کسی ایسے شخص کو دے دیجئے جو مجھ سے زیادہ فقیر ہے۔ آپ نے فرمایا: ’’لے لے۔ اسے استعمال بھی کر اور صدقہ بھی کر۔ یہ مال اگر تیرے پاس خود بخود آئے، تجھے نہ تو اس کی طمع ہو اور نہ تو نے مانگا ہو تو اسے لے لیا کر اور جو اپنے آپ نہ ملے، اس کے پیچھے اپنے آپ کو نہ لگا۔‘‘"}],[2609,"عبدالمطلب بن ربیعہ رضی اللہ عنہ سے روایت ہے کہ ان کے والد ربیعہ بن حارث نے عبدالمطلب بن ربیعہ اور فضل بن عباس رضی اللہ عنہم سے کہا کہ تم دونوں رسول اللہ صلی اللہ علیہ وسلم کے پاس جاؤ، اور آپ سے کہو کہ اللہ کے رسول! آپ ہمیں صدقہ پر عامل بنا دیں، ہم اسی حال میں تھے کہ علی رضی اللہ عنہ آ گئے تو انہوں نے ان دونوں سے کہا کہ رسول اللہ صلی اللہ علیہ وسلم تم دونوں میں سے کسی کو بھی صدقہ پر عامل مقرر نہیں فرمائیں گے۔ عبدالمطلب کہتے ہیں: (ان کے ایسا کہنے کے باوجود بھی) میں اور فضل دونوں چلے یہاں تک کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس پہنچے، تو آپ نے ہم سے فرمایا: \"یہ صدقہ جو ہے یہ لوگوں کا میل ہے، یہ محمد صلی اللہ علیہ وسلم کے لیے اور محمد صلی اللہ علیہ وسلم کے آل کے لیے جائز نہیں\"۔","الألباني: صحيح",{"u2":"حضرت عبدالمطلب بن ربیعہ بن حارث بن عبدالمطلب رضی اللہ عنہم نے بتایا کہ میرے والد ربیعہ بن حارث نے مجھے اور حضرت فضل بن عباس بن عبدالمطلب رضی اللہ عنہ سے کہا کہ تم رسول اللہ صلی اللہ علیہ وسلم کے پاس جاؤ اور آپ سے عرض کرو کہ ہمیں بھی صدقات اکٹھے کرنے کی خدمت پر مقرر فرمائیں۔ ابھی ہم یہ باتیں کر ہی رہے تھے کہ حضرت علی بن ابی طالب رضی اللہ عنہ تشریف لے آئے اور فرمانے لگے کہ رسول اللہ صلی اللہ علیہ وسلم تم میں سے کسی کو صدقات پر مقرر نہیں فرمائیں گے۔ میں اور فضل بن عباس پھر بھی چل پڑے اور رسول اللہ صلی اللہ علیہ وسلم کے پاس پہنچ کر عرض کیا تو آپ نے فرمایا: ’’یہ زکاۃ و صدقات لوگوں کا میل کچیل ہیں، اس لیے یہ حضرت محمد(صلی اللہ علیہ وسلم) اور آل محمد صلی اللہ علیہ وسلم کے لیے حلال نہیں۔‘‘","f2":"(۱) آل نبی صلی اللہ علیہ وسلم صدقات جمع کرنے کی خدمت تو سر انجام دے سکتے ہیں مگر اس کام کی اجرت نہیں لے سکتے کیونکہ اجرت بھی تو زکاۃ و صدقات ہی کا حصہ ہے۔ حضرت عبدالمطلب اور حضرت فضل بن عباس رضی اللہ عنہ کا مقصد چونکہ اجرت ہی تھا، لہٰذا آپ نے انھیں مقرر نہ فرمایا۔ (۲) صدقات جمع کرنے کی اجرت حقیقتاً صدقہ نہیں ہے، اس لیے اغنیاء بھی یہ خدمت سر انجام دے کر اجرت لے سکتے ہیں مگر آل محمد صلی اللہ علیہ وسلم کی رفعت شان اس بات کی متقاضی ہے کہ وہ ایسی چیز بھی نہ لیں جس میں صدقے کا شبہ بھی ہو اور اجرت صدقات میں صدقے کا شبہ تو ہے کیونکہ وہ صدقات کا حصہ ہے۔ (۳) رفعت شان کے علاوہ آل محمد صلی اللہ علیہ وسلم کے لیے صدقات کی حرمت کا سبب یہ بھی ہے کہ کوئی یہ نہ کہہ سکے کہ دعوائے نبوت کا مقصد اپنے خاندان کے لیے مال جمع کرنا ہے۔ نعوذ باللہ\n(۴) زکاۃ و صدقات چونکہ مال کو پاک کرتے ہیں، جس طرح پانی جسم کو پاک کرتا ہے، لہذا زکاۃ وصدقات کی حیثیت اس پانی کی سی ہے جس کے ساتھ کسی چیز کو دھو کر صاف کیا گیا ہو، اس لیے اسے ’’لوگوں کا میل کچیل‘‘ کہا گیا۔ اختیاری حالت میں ماء مستعمل کو لینا کوئی پسند نہیں کرتا، اس لیے زکاۃ وصدقات بھی مجبور ومضطر لوگوں ہی کے لیے جائز ہیں۔ (۵) فرض دصقات تو نبی صلی اللہ علیہ وسلم پر اور آپ کی آل پر قطعاً حرام ہیں، البتہ نفل صدقات کے بارے میں جمہور اہل علم کا خیال ہے کہ وہ آل محمد کے لیے جائز ہیں، البتہ رسول اللہ صلی اللہ علیہ وسلم کی مقدس ہستی کے لیے نفل صدقات بھی حرام ہیں کہ آپ کی شان انتہائی بلند ہے۔ (۶) آل نبی صلی اللہ علیہ وسلم سے مراد امام ابوحنیفہ اور امام مالکL کے نزدیک صرف بنو ہاشم ہیں اور امام شافعی وغیرہ نے بنو ہاشم اور بنو مطلب دونوں خاندان مراد لیے ہیں۔ بنو ہاشم سے مراد حضرت علی، عقیل، جعفر، عباس اور حارث رضی اللہ عنہم کی نسل ہیں۔"}],[2610,"شعبہ کہتے ہیں کہ میں نے ابوایاس معاویہ بن قرہ سے پوچھا: کیا آپ نے انس بن مالک رضی اللہ عنہ کو کہتے سنا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"لوگوں کا بھانجا بھی انہیں میں سے ہوتا ہے\"، انہوں نے کہا: جی ہاں (میں نے سنا ہے)۔","الألباني: صحيح",{"u2":"حضرت شعبہ بیان کرتے ہیں کہ میں نے حضرت ابو ایاس معاویہ بن قرہ سے پوچھا: کیا تم نے حضرت انس بن مالک رضی اللہ عنہ سے سنا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کسی قوم کا بھانجا بھی اس قوم میں شامل ہے؟‘‘ انھوں نے کہا: ہاں۔","f2":"امام نسائی رحمہ اللہ کا مقصد یہ ہے کہ بنو ہاشم کا بھانجا بھی زکاۃ کا مستحق نہیں کیونکہ وہ بھی بنو ہاشم میں شامل ہے۔ اسی طرح اس روایت سے بعض حضرات نے بھانجے کی وراثت پر بھی استدلال کیا ہے، حالانکہ یہاں وراثت کی بحث ہی نہیں۔ آپ کا مطلب تو یہ ہے کہ بھانجے کا اپنے ماموؤں کے ساتھ قوی تعلق ہوتا ہے، لہٰذا اسے ان سے غیر متعلق نہیں سمجھا جا سکتا۔ یہ ارشاد آپ نے اس وقت فرمایا تھا جب آپ نے صرف انصار کو بلایا تھا۔ آپ کو بتلایا گیا کہ آنے والوں میں ان کا بھانجا بھی ہے۔ دیکھیے: (صحیح البخاری، المناقب، حدیث: ۳۵۲۸)"}],[2611,"انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"لوگوں کا بھانجا بھی انہیں میں سے ہوتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کسی قوم کا بھانجا بھی ان میں سے ہی ہے۔‘‘"}],[2612,"ابورافع رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بنی مخزوم کے ایک شخص کو صدقہ پر عامل مقرر فرمایا، تو ابورافع نے بھی اس کے ساتھ جانا چاہا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"صدقہ ہمارے لیے حلال نہیں ہے، لوگوں کا غلام بھی انہیں میں سے شمار ہوتا ہے\"۔\n§وضاحت\n۱؎: ابورافع رسول اللہ صلی اللہ علیہ وسلم کے غلام تھے۔","الألباني: صحيح",{"u2":"حضرت ابو رافع رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بنو مخزوم کے ایک شخص کو صدقات جمع کرنے پر مقرر فرمایا۔ ابو رافع (یعنی میں) نے بھی اس کے ساتھ جانے کی خواہش کی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’صدقات ہمارے لیے حلال نہیں اور کسی خاندان کا آزاد کردہ غلام بھی ان میں شامل ہے۔‘‘","f2":"یہ ابو رافع رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کے آزاد کردہ غلام تھے، بلکہ انھیں اس نسبت سے ہاشمی بھی کہہ دیا جاتا تھا۔ مذکورہ حدیث سے بھی تائید ہوتی ہے کہ کسی قوم کے آزاد کردہ غلام یا بھانجے کو ان کی طرف منسوب کیا جا سکتا ہے، اگرچہ وہ نسباً ان سے نہیں کیونکہ محض نسبت کے لیے اتنا تعلق بھی کافی ہے۔ ابو رافع کا زکاۃ کا اہل قرار نہ دینے سے بھانجے کے بارے میں امام نسائی رحمہ اللہ کے استنباط کو قوت پہنچتی ہے کیونکہ جب آزاد کردہ غلام بنو ہاشم کا حکم رکھتا ہے تو بھانجا کیوں نہ رکھے گا؟"}],[2613,"بہز بن حکیم کے دادا (معاویہ بن حیدہ) رضی اللہ عنہ کہتے ہیں کہ جب نبی اکرم صلی اللہ علیہ وسلم کے پاس (کھانے کی) کوئی چیز لائی جاتی تو آپ پوچھتے: \"یہ ہدیہ ہے یا صدقہ؟\" اگر کہا جاتا کہ یہ صدقہ ہے تو آپ نہ کھاتے اور اگر کہا جاتا یہ ہدیہ ہے تو آپ (کھانے کے لیے) اپنا ہاتھ بڑھاتے۔","الألباني: حسن صحيح",{"u2":"حضرت بہز بن حکیم کے دادا بیان کرتے ہیں کہ جب نبی صلی اللہ علیہ وسلم کے پاس کوئی چیز لائی جاتی تو آپ اس کے بارے میں پوچھتے کہ یہ تحفہ ہے یا صدقہ؟ اگر کہا جاتا: صدقہ ہے، تو آپ نہیں کھاتے تھے اور اگر کہا جاتا ہے: تحفہ ہے، تو آپ تناول فرما لیتے تھے۔","f2":"صدقات سے پرہیز میں آپ ہی تو اصل ہیں تاکہ کسی نابکاری کے لیے اعتراض کی گنجائش نہ رہے۔ آل نبی تو آپ کی فرع ہونے کی وجہ سے اس حکم میں داخل ہیں۔ ممکن ہے باب کا مقصد یہ ہو کہ نبی صلی اللہ علیہ وسلم کے لیے نفل صدقات بھی حلال نہ تھے، البتہ ازواج مطہرات رضی اللہ عنہم کے لیے نفل صدقات حلال تھے جیسا کہ بہت سی احادیث سے ثابت ہے۔"}],[2614,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ انہوں نے بریرہ رضی اللہ عنہا کو خرید کر آزاد کر دینا چاہا، لیکن ان کے مالکان نے ولاء (ترکہ) خود لینے کی شرط لگائی۔ تو انہوں نے اس کا تذکرہ رسول اللہ صلی اللہ علیہ وسلم سے کیا، تو آپ نے فرمایا: \"اسے خرید لو، اور آزاد کر دو، ولاء (ترکہ) اسی کا ہے جو آزاد کرے\"، اور جس وقت وہ آزاد کر دی گئیں تو انہیں اختیار دیا گیا کہ وہ اپنے شوہر کی زوجیت میں رہیں یا نہ رہیں۔ (اسی درمیان) رسول اللہ صلی اللہ علیہ وسلم کے پاس گوشت لایا گیا، کہا گیا کہ یہ ان چیزوں میں سے ہے جو بریرہ رضی اللہ عنہا پر صدقہ کیا جاتا ہے، تو آپ نے فرمایا: \"یہ اس کے لیے صدقہ ہے، اور ہمارے لیے ہدیہ ہے\"، ان کے شوہر آزاد تھے۔","الألباني: صحيح دون قوله حر المحفوظ عبد",{"u2":"حضرت عائشہ رضی اللہ عنہا سے منقول ہے کہ میں نے ارادہ کیا کہ بریرہ رضی اللہ عنہا کو خرید کر آزاد کر دوں لیکن اس کے مالکوں نے اس کے وَلَا کی شرط لگا لی۔ میں نے یہ بات رسول اللہ صلی اللہ علیہ وسلم سے ذکر کی تو آپ نے فرمایا: ’’خرید کر آزاد کر دے۔ وَلَا اسی کا حق ہے جو آزاد کرے۔‘‘ (اسی طرح) جب وہ آزاد ہوئی تو اسے (خاوند کے پاس رہنے یا نہ رہنے کا) اختیار دیا گیا۔ (اسی طرح) رسول اللہ صلی اللہ علیہ وسلم کے پاس گوشت لایا گیا اور بتایا گیا کہ یہ اس (گوشت) میں سے ہے جو بریرہ رضی اللہ عنہا پر صدقہ کیا گیا ہے۔ آپ نے فرمایا: ’’وہ اس کے لیے صدقہ ہے، ہمارے لیے ہدیہ (تحفہ) ہے۔‘‘ (یاد رہے کہ) حضرت بریرہ رضی اللہ عنہا کا خاوند آزاد تھا۔","f2":"(۱) حضرت بریرہ رضی اللہ عنہا کسی اور خاندان کی لونڈی تھیں۔ حضرت عائشہ رضی اللہ عنہا کے پاس خدمت کے لیے آتی جاتی رہتی تھیں۔ انھوں نے اپنے مالکوں سے آزادی کا معاہدہ کیا کہ میں قسط وار اپنی قیمت خود ادا کر دوں گی، مجھے آزاد کر دو۔ وہ مان گئے۔ حضرت عائشہ رضی اللہ عنہا کو پتہ چلا تو انھوں نے پیش کش کی کہ میں پوری قیمت دے کر ابھی خرید لیتی ہوں اور آزاد کر دیتی ہوں۔ مالک راضی ہوگئے مگر کہنے لگے: وَلَا کا حق ہمارا ہوگا، حالانکہ مولیٰ وہی ہوتا ہے جو آزاد کرے۔ حضرت عائشہ رضی اللہ عنہا نے یہ مسئلہ رسول اللہ صلی اللہ علیہ وسلم کے سامنے پیش کیا تو اپ نے مذکورہ جواب ارشاد فرمایا۔ (۲) ’’وَلَا‘‘ سے مراد وہ حق ہے جو آزاد کرنے والے کو آزاد کردہ غلام پر ہوتا ہے، مثلاً: وہ اس کا مولیٰ کہلاتا ہے۔ اگر غلام فوت ہو جائے اور اس کا کوئی نسبی وارث نہ ہو تو مالک کو وراثت ملتی ہے، وغیرہ۔ (۳) اگر منکوحہ لونڈی آزاد ہو جائے تو آزادی کے بعد اسے اختیار ہوتا ہے کہ چاہے تو سابقہ خاوند سے نکاح قائم رکھے، چاہے تو نکاح فسخ کر دے۔ لیکن جمہور اہل علم کے نزدیک یہ اختیار تب ہے اگر اس کا خاوند غلام ہو۔ اگر وہ آزاد ہو تو عورت کو باوجود آزاد ہونے کے نکاح ختم کرنے کا اختیار نہیں۔ حضرت بریرہ رضی اللہ عنہا کے خاوند غلام تھے، نام ان کا مغیث تھا۔ البتہ احناف کے نزدیک خاوند آزاد ہو یا غلام، آزاد ہونے والی کو نکاح ختم کرنے کا اختیار حاصل ہے۔ (۴) ’’گوشت لایا گیا۔‘‘ یہ گوشت صدقے کا تھا۔ کسی نے حضرت بریرہ رضی اللہ عنہا کو بھیجا تھا۔ انھوں نے کچھ گوشت بطور تحفہ حضرت عائشہ رضی اللہ عنہا کے پاس بھیج دیا۔ ظاہر ہے گوشت جس کو صدقے میں دے دیا جائے اس کی ملک ہوگیا، اب وہ جسے صدقے کے طور پر دے، اس کے لیے صدقہ ہے۔ جسے تحفے کے طور پر دے، اس کے لیے تحفہ ہے۔ اسی لیے نبی صلی اللہ علیہ وسلم نے وہ گوشت تناول فرمایا۔ (۵) ’’آزاد تھا۔‘‘ دوسری روایات میں صراحت ہے کہ یہ حضرت اسود کا قول ہے، نہ کہ حضرت عائشہ رضی اللہ عنہا کا۔ اور اسود تابعی ہیں۔ دوسری روایات میں حضرت عائشہ اور حضرت ابن عباس رضی اللہ عنہم کا صریح فرمان ہے کہ بریرہ کا خاوند غلام تھا۔ (صحیح البخاری، الطلاق، حدیث: ۵۲۸۲، وصحیح مسلم، العتق، حدیث: ۱۵۰۴) اگر وہ غلام نہ ہوتا تو اسے اختیار نہ دیا جاتا کیونکہ عورت آزاد ہونے کے باوجود خاوند سے بلند رتبہ نہیں ہوتی۔ (۶) تفصیلی روایات میں صراحت ہے کہ حضرت بریرہ رضی اللہ عنہا نے باوجود حضرت مغیث کی منت سماجت کے نکاح ختم کر دیا تھا۔ دیکھیے: (صحیح البخاری، الطلاق، حدیث: ۲۵۸۳)"}],[2615,"اسلم کہتے ہیں کہ میں نے عمر رضی اللہ عنہ کو کہتے سنا کہ میں نے (ایک آدمی کو) ایک گھوڑا اللہ کی راہ میں سواری کے لیے دیا تو اسے اس شخص نے برباد کر دیا، تو میں نے سوچا کہ میں اسے خرید لوں، خیال تھا کہ وہ اسے سستا ہی بیچ دے گا، میں نے اس بارے میں رسول اللہ صلی اللہ علیہ وسلم سے سوال کیا، تو آپ نے فرمایا: \"تم اسے مت خریدو گرچہ وہ تمہیں ایک ہی درہم میں دیدے، کیونکہ صدقہ کر کے پھر اسے لینے والا کتے کی طرح ہے جو قے کر کے اسے چاٹتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت عمر رضی اللہ عنہ فرماتے ہیں کہ میں نے ایک گھوڑا اللہ تعالیٰ کے راستے (جہاد) میں کسی (مجاہد) کو دیا۔ اس نے گھوڑے (کی خاطر تواضع نہ کی اور اس) کو ضائع (کمزور) کر دیا۔ میرا ارادہ ہوا کہ اس سے دوبارہ خرید لوں۔ میرا خیال تھا وہ سستا ہی بیچ دے گا۔ میں نے اس بارے میں رسول اللہ صلی اللہ علیہ وسلم سے پوچھا تو آپ نے فرمایا: ’’تو اسے مت خرید۔ چاہے وہ ایک درہم ہی کا تجھے دے کیونکہ جو شخص اپنے صدقے کو (کسی بھی صورت میں) واپس لیتا ہے، وہ اس کتے کی طرح ہے جو اپنے قے چاٹتا ہے۔‘‘","f2":"صدقہ کرنے والے کو اپنا صدقہ قیمتاً بھی لینا منع ہے۔ ممکن ہے وہ شخص اس کا لحاظ کرتے ہوئے اسے قیمت میں رعایت کرے، البتہ کوئی دوسرا شخص کسی دوسرے کا صدقہ خرید سکتا ہے کیونکہ اس کے لیے یہ صدقہ نہیں بلکہ خریدی ہوئی چیز ہے۔ گویا چیز کی حیثیت بدل جانے سے اس کا حکم بھی بدل جاتا ہے، جیسے پچھلی حدیث میں ہے۔"}],[2616,"عمر رضی اللہ عنہ کہتے ہیں کہ انہوں نے ایک گھوڑا اللہ کی راہ میں سواری کے لیے دیا، پھر دیکھا کہ وہ گھوڑا بیچا جا رہا ہے، تو انہوں نے اسے خریدنے کا ارادہ کیا، تو نبی اکرم صلی اللہ علیہ وسلم نے ان سے فرمایا: \"تم اپنے صدقے میں آڑے نہ آؤ\"۔","الألباني: صحيح",{"u2":"حضرت عمر رضی اللہ عنہ سے روایت ہے کہ انھوں نے ایک گھوڑا فی سبیل اللہ صدقہ کیا، پھر انھیں پتا چلا کہ وہ گھوڑا فروخت ہو رہا ہے تو انھوں نے خود ہی خریدنے کا ارادہ کر لیا۔ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’اپنے کیے ہوئے صدقے (کی واپسی) کا خیال بھی نہ کر۔‘‘","f2":"کیونکہ بہر صورت یہ اپنے ہی صدقے کو استعمال کرنے والی بات ہے جو مناسب نہیں۔ باقی رہی قیمت تو اس میں بھی رعایت کا احتمال ہے، نیز اس میں حیلہ بھی ممکن ہے، اس لیے اسے حتماً منع فرما دیا۔"}],[2617,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ عمر رضی اللہ عنہ نے ایک گھوڑا اللہ کی راہ میں صدقہ کیا، اس کے بعد انہیں معلوم ہوا کہ وہ بیچا جا رہا ہے۔ تو انہوں نے اسے خریدنے کا ارادہ کیا، وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، اور آپ سے اس بارے میں اجازت طلب کی تو آپ نے فرمایا: \"اپنا صدقہ واپس نہ لو\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہ بیان فرماتے ہیں کہ حضرت عمر رضی اللہ عنہ نے ایک گھوڑا اللہ تعالیٰ کے راستے میں صدقہ کیا۔ کچھ عرصے کے بعد حضرت عمر رضی اللہ عنہ نے دیکھا کہ وہ گھوڑا فروخت کیا جا رہا ہے تو انھوں نے ارادہ فرمایا کہ میں ہی اسے خرید لوں، پھر وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوئے اور اس بارے میں آپ سے مشورہ طلب کیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اپنا کیا ہوا صدقہ دوبارہ نہ لے۔‘‘","f2":"اپنا کیا ہوا صدقہ اپنے اختیار سے، مثلاً: خرید کر یا رجوع کر کے تو واپس نہیں لے سکتا، البتہ اگر غیر اختیاری طور پر اس کے پاس آجائے، مثلاً: جسے صدقہ دیا تھا وہ فوت ہوگیا اور یہ صدقہ کرنے والا اس کا وارث بنتا ہے اور وراثت میں وہی صدقہ اسے واپس مل جائے تو پھر کوئی حرج نہیں۔ حدیث میں اس کی صراحت موجود ہے۔ دیکھیے: (صحیح مسلم، الصیام، حدیث: ۱۱۴۹) بعض اہل علم نے اس حدیث سے یہ استنباط بھی کیا ہے: ’’جس لونڈی کو آزاد کرے، اس سے پھر نکاح نہ کرے کیونکہ یہ بھی صدقے میں رجوع ہی کی صورت ہے۔‘‘ حالانکہ یہ تو احسان پر احسان ہے اور حدیث صحیح میں اسے دگنے ثواب کا سبب بھی قرار دیا ہے۔ دیکھیے: (صحیح البخاری:، العلم، حدیث: ۹۷) خود رسول اللہ صلی اللہ علیہ وسلم نے حضرت صفیہ رضی اللہ عنہا کو آزاد کر کے ان سے نکاح فرمایا، لہٰذا یہ استنباط درست نہیں۔ دیکھیے: (صحیح البخاری، النکاح، حدیث: ۵۰۸۶، وصحیح مسلم، النکاح، حدیث: ۱۳۶۵)"}],[2618,"تابعی سعید بن مسیب سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے عتاب بن اسید کو (درخت پر لگے) انگور کا تخمینہ لگانے کا حکم دیا تاکہ اس کی زکاۃ کشمش سے ادا کی جا سکے، جیسے درخت پر لگی کھجوروں کی زکاۃ پکی کھجور سے ادا کی جاتی ہے ۱؎۔\nكتاب مناسك الحج\n§وضاحت\n۱؎: بظاہر اس حدیث کا تعلق اس کے باب \"صدقہ خریدنے کا بیان\" سے نظر نہیں آتا، ممکن ہے کہ مؤلف کی مراد یہ ہو کہ \"جب درخت پر لگے پھل کا تخمینہ لگا کر مالک کے گھر میں موجود کھجور سے اس کی زکاۃ لے لی گئی تو گویا یہ بیع ہو گئی\"، اور تب عمر رضی اللہ عنہ کے واقعہ میں ممانعت تنزیہ پہ محمول کی جائے گی، واللہ اعلم۔","الألباني: حسن الإسناد مرسل",{"u2":"حضرت سعید بن مسیب سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے (مکہ مکرمہ کے گورنر) حضرت عتاب بن اسید رضی اللہ عنہ کو حکم دیا تھا کہ انگوروں کی فصل کا اندازہ لگا کر ان کی زکاۃ کشمش کی صورت میں ادا کی جائے جس طرح کھجوروں کی زکاۃ خشک کھجوروں (چھوہاروں) کی صورت میں ادا کی جاتی ہے۔","f2":"زکاۃ کی بحث تو پیچھے گزر چکی ہے کہ عشر وغیرہ اس صورت میں وصول کیا جائے گا جس صورت میں اس کا ذخیرہ کیا جا سکے مگر یہاں بحث طلب امر یہ ہے کہ اس حدیث کا باب سے کیا تعلق ہے، جبکہ اس میں صدقہ خریدنے کا کوئی ذکر نہیں؟ کہا جا سکتا ہے کہ جب کا شتکار نے انگور رکھ کر کشمش کی صورت میں عشر دیا تو گویا اس نے صدقے کے انگوروں کو کشمش سے خرید لیا۔ گویا اپنا صدقہ خریدنا جائز ہوگیا۔ اس صورت میں اوپر والی روایات میں اپنا صدقہ خریدنے سے روکنا تنزیہ اور احتیاط کے طور پر ہوگا۔ واللہ اعلم۔ مگر یہ نرالا استنباط ہی ہے۔ دینے والے نے تو صدقے ہی کے انگوروں کو خشک کر کے کشمش بنا کر دیا۔ اپنے مال سے بدلا نہیں ہے کہ اس پر بیچنے کے معنی کسی بھی طرح صادق آسکیں۔ کشمش ہی سے صدقے کی ابتدا ہوئی۔ ویسے یہ روایت مرسل ہے۔ حضرت سعید بن مسیب تابعی ہیں۔ انھوں نے یہ نہیں بتایا کہ انھوں نے یہ روایت کس صحابی سے سنی ہے۔ اس سے روایت کی حیثیت کم ہو جاتی اور ضعیف قرار پاتی ہے، تاہم یہ مسئلہ دیگر صحیح روایات سے بھی ثابت ہے۔ تفصیل کے لیے دیکھیے: (ذخیرۃ العقبیٰ شرح سنن النسائی: ۲۳/ ۲۵۹-۲۶۶)"}],[2619,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے لوگوں کے سامنے خطبہ دیا تو فرمایا: \"اللہ عزوجل نے تم پر حج فرض کیا ہے\" ایک شخص نے پوچھا: کیا ہر سال؟ آپ خاموش رہے یہاں تک اس نے اسے تین بار دہرایا تو آپ نے فرمایا: \"اگر میں کہہ دیتا ہاں، تو وہ واجب ہو جاتا، اور اگر واجب ہو جاتا تو تم اسے ادا نہ کر پاتے، تم مجھے میرے حال پر چھوڑے رہو جب تک کہ میں تمہیں تمہارے حال پر چھوڑے رکھوں ۱؎، تم سے پہلے لوگ بکثرت سوال کرنے اور اپنے انبیاء سے اختلاف کرنے کے سبب ہلاک ہوئے، جب میں تمہیں کسی بات کا حکم دوں تو جہاں تک تم سے ہو سکے اس پر عمل کرو۔ اور جب کسی چیز سے روکوں تو اس سے باز آ جاؤ\"۔\n§وضاحت\n۱؎: مطلب یہ ہے کہ غیر ضروری سوال نہ کیا کرو۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے لوگوں کو خطبہ ارشاد فرمایا اور کہا: ’’یقینا اللہ تعالیٰ نے تم پر حج فرض کیا ہے۔‘‘ ایک آدمی کہنے لگا: ہر سال؟ آپ خاموش رہے، حتیٰ کہ اس نے تین دفعہ یہ سوال دہرایا۔ آپ نے فرمایا: ’’اگر میں ’’ہاں‘‘ کہہ دیتا تو ہر سال واجب ہو جاتا اور اگر ہر سال واجب ہو جاتا تو تم اسے ادا نہ کر سکتے۔ جب تک میں تمھیں چھوڑے رہوں، تم بھی مجھے چھوڑے رہا کرو۔ تم سے پہلے کے لوگ اپنے انبیاء سے اختلاف کرنے اور زیادہ سوالات کرنے کی وجہ ہی سے ہلاک ہوئے۔ جب میں تمھیں کسی کام کا حکم دوں تو اپنی طاقت کے مطابق اس کی پابندی کرو اور جب تمھیں کسی چیز سے روک دوں تو اسے چھوڑ دو۔‘‘","f2":"(۱) حج کی فرضیت تو اجماعی اور قطعی مسئلہ ہے، اختلاف ہے یہ کہ کب فرض ہوا۔ مشہور قول ۵ یا ۶ ہجری کا ہے مگر محقق بات یہ معلوم ہوتی ہے کہ ۹ ہجری میں فرض ہوا، ورنہ آپ ۶ہجری میں عمرے کی بجائے حج کو جاتے۔ ۸ہجری میں بھی فتح مکہ کے بعد آپ عمرہ کر کے واپس تشریف لے آئے، حالانکہ حج کے دن قریب تھے۔ (۲) ’’ایک آدمی۔‘‘ یہ حضرت اقرع بن حابس تمیمی رضی اللہ عنہ تھے۔ (۳) ’’واجب ہو جاتا۔‘‘ گویا حج کا حکم مطلق اترا تھا۔ اس میں ایک دفعہ یا ہر سال کی صراحت نہیں تھی۔ اس کا فیصلہ مصلحت مسلمین پر موقوف تھا۔ اگر آپ ’’ہر سال‘‘ میں مصلحت محسوس فرماتے تو ہر سال فرض ہو جاتا مگر یہ بات مصلحت کے خلاف تھی، اس لیے آپ نے اس شخص کی تائید نہ کی۔ (۴) بعض مسائل میں شارع علیہ السلام نے جان بوجھ کر خاموشی اختیار فرمائی ہے تاکہ مسلمانوں کو سہولت رہے۔ ایسے مسائل میں سوال کے ذریعے سے تنگی پیدا کرنا بری بات ہے۔ اسی طرح شریعت کی عطا کردہ وسعت کوختم کر دینا بھی بے جا تشدد ہے۔ جن مسائل میں شریعت نے معاملہ کھلا چھوڑا ہے، اسے کھلا ہی رکھنا چاہیے۔ اپنی طرف سے پابندیاں نہ لگائی جائیں، مثلاً: لباس، حجامت، بود وباش اور دیگر عادات۔ اسی طرح نفلی عبادات میں شریعت کے صریح احکام ہی کو کافی سمجھا جائے اور لوگوں کو خواہ مخواہ تنگ نہ کیا جائے۔ کسی قوم کے رسوم و رواج جب تک صراحتاً شریعت کے خلاف نہ ہوں، ان پر پابندی نہ لگائی جائے اور نہ ان کا ثبوت ہی شریعت سے تلاش کیا جائے کیونکہ ثبوت کی ضرورت عبادات میں ہے نہ کہ عادات میں۔ عادات میں پابندی کا نہ ہونا ہی کافی ہے۔ (۵) ’’طاقت کے مطابق‘‘ معلوم ہوا کہ ایک آدمی اپنی بساط اور طاقت کے مطابق ایک مامور بہ کام کرنے کی کوشش کرتا ہے مگر مکمل طور پر بجا نہیں لا پاتا، تو جتنے کام سے وہ عاجز آگیا ہو، وہ اس سے ساقط ہو جائے گا۔ یہ بات نیکی کے کاموں کی ہے جنھیں کرنے کا شریعت نے حکم دیا ہے، البتہ جن کاموں سے روکا گیا ہے، ان میں استطاعت کی قید نہیں، ان سے ہر صورت میں مکمل طور پر بچنا ضروری ہے۔ واللہ اعلم (۶) امر ہر جگہ تکرار کا تقاضا نہیں کرتا اور نہ ہر جگہ عدم تکرار کا تقاضا کرتا ہے بلکہ موقع محل، سیاق، قرائن یا دلائل سے تعین کیا جائے گا۔"}],[2620,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوئے اور فرمایا: \"بیشک اللہ تعالی نے تم پر حج فرض کیا ہے\"، تو اقرع بن حابس تمیمی رضی اللہ عنہ نے پوچھا: ہر سال؟ اللہ کے رسول! آپ خاموش رہے، پھر آپ نے بعد میں فرمایا: \"اگر میں ہاں کہہ دیتا تو ہر سال (حج) فرض ہو جاتا، پھر نہ تم سنتے اور نہ اطاعت کرتے، لیکن حج ایک بار ہی ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم (خطبے کے لیے) کھڑے ہوئے اور فرمایا: ’’اللہ تعالیٰ نے تم پر حج فرض فرما دیا ہے۔‘‘ حضرت اقرع بن حابس تمیمی رضی اللہ عنہ کہنے لگے: اے اللہ کے رسول! کیا ہر سال؟ آپ خاموش ہوگئے، پھر فرمایا: ’’اگر مین ’’ہاں‘‘ کہہ دیتا تو ہر سال واجب ہو جاتا، پھر نہ تم سنتے اور نہ اطاعت کرتے۔ حج صرف ایک ہی (دفعہ فرض) ہے۔‘‘","f2":"’’نہ سنتے اور نہ اطاعت کرتے۔‘‘ یعنی اس پر عمل کرنا تمھاری طاقت میں نہ ہوتا۔"}],[2621,"ابورزین رضی اللہ عنہ سے روایت ہے کہ انہوں نے عرض کیا: اللہ کے رسول! میرے والد بوڑھے ہیں، نہ حج کر سکتے ہیں نہ عمرہ اور نہ سفر؟ آپ نے فرمایا: \"اپنے والد کی طرف سے تم حج و عمرہ کر لو\" ۱؎۔\n§وضاحت\n۱؎: اس میں بطور نیابت حج و عمرہ کرنے کی تاکید ہے لیکن نائب کے لیے ضروری ہے کہ پہلے وہ خود حج کر چکا ہو۔","الألباني: صحيح",{"u2":"حضرت عمرو بن اوس رضی اللہ عنہ سے روایت ہے کہ حضرت ابو رزین رضی اللہ عنہ نے کہا: اے اللہ کے رسول! میرے والد بہت بوڑھے ہو چکے ہیں۔ وہ حج و عمرہ بلکہ سفر تک کی طاقت نہیں رکھتے۔ آپ نے فرمایا: ’’تم اپنے والد کی طرف سے حج اور عمرہ کرو۔‘‘","f2":"(۱) عمرے کا وجوب مختلف فیہ مسئلہ ہے۔ امام نسائی رحمہ اللہ اور دوسرے محدثین، مثلاً: امام شافعی اور امام احمدL حج کی طرح عمرے کو واجب سمجھتے ہیں کیونکہ اس حدیث میں حج اور عمرے کا اکٹھا ذکر ہے۔ قرآن مجید میں بھی وہ اکٹھے مذکور ہیں۔ ارشاد باری تعالیٰ ہے: {وَ اَتِمُّوا الْحَجَّ وَ الْعُمْرَۃَ لِلّٰہِ} (البقرۃ: ۱۹۶) ’’حج اور عمرہ اللہ تعالیٰ کے لیے مکمل کرو۔‘‘ لہٰذا دونوں فرض ہیں۔ مگر احناف اور مالکی حضرات عمرے کو نفل سمجھتے ہیں کیونکہ نبی صلی اللہ علیہ وسلم نے ارکان اسلام بتاتے وقت حج کا ذکر فرمایا ہے عمرے کا نہیں۔ لیکن یہ دلیل انتہائی کمزور ہے کیونکہ دیگر بہت سے ایسے فرائض وواجبات ہیں جن کی حیثیت ارکان کی نہیں اور نہ وہ اس حدیث کے تحت ذکر ہی ہوئے ہیں جبکہ حقیقت میں وہ واجب ہی ہیں، لہٰذا اس سے ان کی عدم فرضیت یا عدم وجوب لازم نہیں آتا، نیز دونوں کے اعمال ومناسک کا بھی خاصا فرق ہے۔ جب فرق ہے تو ایک کے اس حدیث میں ذکر نہ ہونے سے کیا ہوتا ہے۔ (۲) جو شخص مالی طاقت رکھتا ہو مگر جسمانی طور پر معذور ہو تو وہ کسی کو اپنی جگہ حج کے لیے بھیجے۔ اسی طرح جس شخص پر حج فرض ہو مگر ادائیگی کے بغیر فوت ہوگیا ہو تو اس کی طرف سے اس کے ورثاء حج کریں یا کسی کو بھیجیں۔"}],[2622,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مبرور و مقبول حج کا بدلہ جنت کے سوا اور کچھ نہیں اور ایک عمرہ دوسرے عمرہ کے درمیان تک کے گناہوں کا کفارہ ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’حج مبرور کا بدلہ جنت کے سوا کچھ نہیں۔ اور ایک عمرہ دوسرے عمرے تک کے درمیانی گناہوں کا کفارہ بن جاتا ہے۔‘‘","f2":"(۱) حج مبرور سے مراد وہ حج ہے جس میں شہوانی باتیں، فسق اور لڑائی جھگڑا نہ ہو جیسا کہ قرآن مجید میں اس کی طرف اشارہ ہے۔ بعض نے حج مبرور کے معنی مقبول حج کے کیے ہیں مگر مقبول مبرور کا معنی نہیں بلکہ لازم ہے، یعنی جو حج ان مفاسد سے پاک ہوگا، وہ لازماً قبول ہوگا۔ حج مبرور کی نشانی یہ بھی ہے کہ حج کرنے والا حج کے بعد پہلے سے بہترین جائے اور کبائر کا مرتکب نہ ہو۔ بعض نے حج مبرور سے مراد وہ حج لیا ہے جس میں ریا کاری نہ ہو۔ (۲) ’’جنت‘‘ یعنی وہ اولین طور پر جنت میں جائے گا۔ گویا حچ سے اس کے تمام پہلے گناہ معاف ہو جائیں گے۔ (۳) ’’کفارہ‘‘ یعنی صغائر معاف ہو جائیں گے بشرطیکہ کبائر سے اجتناب کرے۔ بعض نے صغائر وکبائر دونوں مراد لیے ہیں کیونکہ صرف صغائر تو کبائر کے اجتناب سے بھی معاف ہو جاتے ہیں اور وضو سے بھی، نماز سے بھی، پھر حج کی کیا خصوصیت ہے؟ (۴) حج کی فضیلت عمرے سے زیادہ ہے۔ (۵) ایک سال میں کئی عمرے کیے جا سکتے ہیں لیکن حج سال میں ایک ہی دفعہ کیا جا سکتا ہے۔"}],[2623,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"حج مبرور (مقبول) کا ثواب جنت کے سوا اور کچھ نہیں ہے\"، اس سے آگے پہلے کی حدیث کے مثل ہے، مگر فرق یہ ہے کہ اس میں «كفارة لما بينهما» کے بجائے «تكفر ما بينهما» کا لفظ آیا ہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’حج مبرور کا ثواب صرف جنت ہے۔‘‘ باقی روایت تقریباً سابقہ روایت ہی کی طرح ہے۔ مگر اس روایت میں فرق صرف یہ ہے کہ آپ نے فرمایا: ’’ایک عمرہ دوسرے عمرے تک کے درمیانی گناہوں کو ختم کر دیتا ہے۔‘‘"}],[2624,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ ایک شخص نے نبی اکرم صلی اللہ علیہ وسلم سے پوچھا: اللہ کے رسول! اعمال میں سب سے افضل عمل کون سا ہے؟ آپ نے فرمایا:\"اللہ پر ایمان لانا\"، اس نے پوچھا: پھر کون سا؟ آپ نے فرمایا: \"اللہ کی راہ میں جہاد کرنا\"، اس نے پوچھا: پھر کون سا عمل؟ آپ نے فرمایا: \"پھر حج مبرور(مقبول)\" ۱؎۔\n§وضاحت\n۱؎: حج مبرور وہ حج ہے جس میں کوئی گناہ سرزد نہ ہوا ہو بعض کہتے ہیں کہ حج مبرور وہ حج ہے جس میں حج کے جملہ شرائط و آداب کا التزام کیا گیا ہو اور ایک قول یہ ہے کہ حج مبرور سے مراد حج مقبول ہے اور اس کی علامت یہ ہے کہ حج کے بعد وہ انسان عبادت گزار بن جائے جب کہ اس سے پہلے وہ غافل تھا۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں ایک آدمی نے نبی صلی اللہ علیہ وسلم سے پوچھا: اے اللہ کے رسول! کون سا عمل سب سے افضل ہے؟ آپ نے فرمایا: ’’اللہ تعالیٰ پر ایمان۔‘‘ اس نے کہا: پھر کون سا؟ آپ نے فرمایا: ’’اللہ تعالیٰ کے راستے میں جہاد۔‘‘ اس نے پوچھا: پھر کون سا؟ آپ نے فرمایا: ’’پھر حج مبرور۔‘‘","f2":"(۱) افضل عمل کے بارے میں روایات مختلف ہیں۔ دراصل احوال واشخاص کے لحاظ سے افضل کام مختلف ہو سکتا ہے۔ بعض حالات میں ذکر اللہ افضل ہے اور بعض حالات میں جہاد۔ اسی طرح کسی شخص کے لحاظ سے صدقہ افضل ہے اور کسی شخص کے لحاظ سے نماز بروقت پڑھنا وغیرہ، لہٰذا اسے اختلاف نہ سمجھا جائے۔ (۲) ایمان بھی ایک عمل ہے کیونکہ صحابی نے پوچھا تھا کہ افضل عمل کون سا ہے؟ تو آپ صلی اللہ علیہ وسلم نے جواب دیا: ’’اللہ تعالیٰ پر ایمان لانا۔‘‘"}],[2625,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ کے وفد میں تین لوگ ہیں: ایک غازی، دوسرا حاجی اور تیسرا عمرہ کرنے والا\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تین شخص اللہ تعالیٰ کے خصوصی مہمان ہیں: جہاد کو جانے والا، حج کے لیے سفر کرنے والا اور عمرے کو جانے والا۔‘‘","f2":"’’خصوصی مہمان‘‘ یہ ایک اعزاز ہے جو ان کو اللہ کی راہ میں نکلنے اور مصائب وآلام اٹھانے پر دیا گیا ہے۔"}],[2626,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بوڑھے، بچے، کمزور اور عورت کا جہاد حج اور عمرہ ہے\"۔","الألباني: حسن وفقرة المرأة صحيحة من حديث عائشة",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بوڑھے، بچے، کمزور اور عورت کا جہاد حج اور عمرہ کرنا ہے۔‘‘","f2":"ظاہر ہے یہ چاروں اشخاص جہاد، یعنی قتال نہیں کر سکتے۔ ان کے لیے جہاد کی فضیلت حاصل کرنے کا طریقہ یہ ہے کہ وہ حج اور عمرہ کریں۔ انھیں جہاد کا ثواب مل جائے گا۔ ہر آدمی اس چیز کا مکلف ہے جس کی وہ استطاعت رکھتا ہے۔"}],[2627,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے اس گھر (یعنی خانہ کعبہ) کا حج کیا، نہ بیہودہ بکا ۱؎ اور نہ ہی کوئی گناہ کیا، تو وہ اس طرح (پاک و صاف ہو کر) ۲؎ لوٹے گا جس طرح وہ اس وقت تھا جب اس کی ماں نے اسے جنا تھا\"۔\n§وضاحت\n۱؎: «رفث»: کے اصل معنی ہیں جماع کرنا یہاں مراد فحش گوئی، بیہودگی، اور بیوی سے زبان سے جنسی خواہش کی آرزو کرنا ہے دوران حج چونکہ بیوی سے ہمبستری ممنوع ہے اس لیے اس موضوع پر بیوی سے گفتگو اور دل لگی کی بات بھی ناپسندیدہ ہے اور «فسق» سے نافرمانی اور لوگوں سے لڑائی جھگڑا کرنا مراد ہے۔ ۲؎: یہ پاگیزگی صرف ان صغیرہ گناہوں سے ہوتی ہے جن کا تعلق حقوق اللہ سے ہے ورنہ حقوق اللہ سے متعلق بڑے بڑے گناہ اور اسی طرح حقوق العباد سے متعلق کوتاہیاں خالص توبہ اور ادائیگی حقوق کے بغیر معاف نہیں ہوں گی۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’۔جس نے اس گھر (بیت اللہ) کا حج کیا اور اس دوران میں کوئی شہوانی بات کی نہ فسق (کبیرہ گناہ کا ارتکاب) کیا، وہ (گناہوں سے) اس طرح (پاک صاف ہو کر) پلٹتا ہے جیسے اس دن تھا جب اسے اس کی ماں نے جنا تھا۔‘‘","f2":"(۱) گویا اس کے سب صغیرہ و کبیرہ گناہ معاف ہو جاتے ہیں، البتہ حقوق العباد کا مسئلہ مختلف ہے کیونکہ ان کی معافی تو متعلقین ہی کی طرف سے ہو سکتی ہے لیکن اگر اللہ تعالیٰ متعلقہ شخص کو اپنی طرف سے دے کر راضی کر دے تو اللہ کی رحمت سے بعید نہیں اور نہ اس پر کوئی اعتراض ہی ہے۔ (۲) فسق ویسے تو ہر حال میں منع ہے لیکن حج میں بطور خاص منع کیا گیا ہے۔"}],[2628,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نے عرض کیا: اللہ کے رسول! کیا ہم نکل کر آپ کے ساتھ جہاد نہ کریں کیونکہ میں قرآن میں جہاد سے زیادہ افضل کوئی عمل نہیں دیکھتی؟ آپ نے فرمایا: \"نہیں، لیکن (تمہارے لیے) سب سے بہتر اور کامیاب جہاد بیت اللہ کا حج مبرور (مقبول) ہے\"۔","الألباني: صحيح",{"u2":"ام المومنین حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ میں نے گزارش کی: اے اللہ کے رسول! کیا ہم عورتیں بھی آپ کے ساتھ جہاد کے لیے نہ جایا کریں؟ کیونکہ میں تو قرآن مجید میں کوئی عمل جہاد سے افضل نہیں پاتی۔ آپ نے فرمایا: ’’نہیں تم عورتوں کے لیے افضل اور خوب صورت ترین جہاد بیت اللہ کا حج مبرور ہے۔‘‘","f2":"جہاد کی مشقت عورت کے بس کی بات نہیں ہے، اس لیے وہ جہاد نہیں کر سکتیں۔ ویسے بھی خطرہ ہے کہ عورتیں دشمن کے ہاتھوں قید ہوگئیں تو وہ ان کی بے حرمتی کرے گا جو مسلمان مردوں کے لیے ذلت و رسوائی کی بات ہوگی۔ ابتدائی طور پر عورتیں زخمیوں کو پانی پلانے، میدان جنگ سے منتقل کرنے اور ابتدائی مرہم پٹی کرنے کے لیے لشکر کے ساتھ چلی جایا کرتی تھیں مگر جب مرد زیادہ ہوگئے تو مندرجہ بالا مقاصد کے لیے بھی عام طور پر عورتوں کا میدان جنگ میں جانا بند ہوگیا۔ بلکہ رسول اللہ صلی اللہ علیہ وسلم نے بھی ان کے جانے کو پسند نہیں فرمایا۔"}],[2629,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک عمرہ دوسرے عمرے کے درمیان کے گناہوں کا کفارہ ہے ۱؎، اور حج مبرور کا بدلہ جنت کے سوا کچھ نہیں\"۔\n§وضاحت\n۱؎: اس سے مراد صغیرہ گناہوں کا کفارہ ہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ایک عمرہ دوسرے عمرے تک (کے درمیانی گناہوں) کے لیے کفارہ بن جاتا ہے، اور حج مبرور کی تو جنت کے سوا کوئی جزا ہی نہیں۔‘‘","f2":"فوائد کے لیے دیکھیے، حدیث: ۲۶۶۳۔"}],[2630,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"حج و عمرہ ایک ساتھ کرو، کیونکہ یہ دونوں فقر اور گناہ کو اسی طرح دور کرتے ہیں جس طرح بھٹی لوہے کی میل کو دور کر دیتی ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’پے در پے حج اور عمرہ کرتے رہو کیونکہ یہ دونوں فقر اور گناہوں کو اس طرح زائل کرتے ہیں جیسے آگ کی بھٹی لوہے کے زنگ اور میل کچیل کو دور کرتی ہے۔‘‘","f2":"(۱) ’’پے در پے‘‘ سے مراد یہ ہے کہ حج کے بعد عمرہ اور عمرے کے بعد حج، یعنی کبھی حج، کبھی عمرہ۔ (۲) ’’گناہوں کو زائل کرتے ہیں۔‘‘ یعنی ان کا ثواب گناہوں کے اثرات ختم کرتا رہتا ہے۔ یا حج اور عمرے کی برکت سے انسان گناہوں کو چھوڑ دیتا ہے۔ جس قدر زیادہ حج اور عمرے ہوں گے اتنا ہی وہ گناہوں سے زیادہ دور ہوگا۔ (۳) فقر دور ہونے کی وجہ یہ ہے کہ ان عبادات پر کافی رقم خرچ ہوتی ہے اور اللہ تعالیٰ کا وعدہ ہے کہ جو شخص میرے راستے میں خرچ کرے گا، میں اسے زیادہ دوں گا۔ اللہ تعالیٰ ایسے شخص کے لیے رزق کے معنوی دروازے کھول دے گا۔ ممکن ہے فقر سے مراد فقر قلب ہو، یعنی حج اور عمرہ پے در پے کرنے سے دل سخی بن جائے گا، دل میں بخل نہیں رہے گا۔ واللہ اعلم"}],[2631,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"حج و عمرہ ایک ساتھ کرو، کیونکہ یہ دونوں فقر اور گناہ کو اسی طرح دور کر دیتے ہیں جس طرح بھٹی لوہے، اور سونے چاندی کے میل کچیل کو دور کر دیتی ہے۔ اور حج مبرور کا ثواب جنت کے سوا اور کچھ نہیں ہے\"۔","الألباني: حسن صحيح",{"u2":"حضرت عبداللہ رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’۔حج اور عمرہ مسلسل کرتے رہو۔ یقینا یہ فقر اور گناہوں کو اس طرح زائل کر دیتے ہیں جس طرح آگ کی بھٹی لوہے، سونے اور چاندی کے میل کچیل کو زائل کر دیتی ہے۔ اور حج مبرور کا ثواب تو جنت سے کم نہیں۔‘‘"}],[2632,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ ایک عورت نے حج کی نذر مانی، پھر (حج کئے بغیر) مر گئی، اس کا بھائی نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، اور آپ سے اس بارے میں مسئلہ پوچھا تو آپ فرمایا: \"بتاؤ اگر تمہاری بہن پر قرض ہوتا تو کیا تم ادا کرتے؟\" اس نے کہا: ہاں میں ادا کرتا، آپ نے فرمایا: \"تو اللہ کا قرض ادا کرو وہ تو اور بھی ادائیگی کا زیادہ مستحق ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے مروی ہے کہ ایک عورت نے حج کی نذر مانی تھی لیکن وہ (حج کے بغیر) فوت ہوگئی۔ اس کا بھائی نبی صلی اللہ علیہ وسلم کے پاس حاضر ہوا اور اس بارے میں پوچھنے لگا۔ آپ نے فرمایا: ’’تیرا کیا خیال ہے کہ اگر تیری بہن کے ذمے قرض ہوتا تو کیا تو اسے ادا کرتا؟‘‘ اس نے عرض کیا: جی ہاں۔ آپ نے فرمایا: ’’اللہ کا قرض بھی ادا کرو کیونکہ اللہ تعالیٰ زیادہ حق رکھتا ہے کہ اس کا قرض ادا کیا جائے۔‘‘","f2":"(۱) معلوم ہوا حقوق اللہ کی ادائیگی کا درجہ حقوق العباد کی ادائیگی سے اہم اور بلند ہے اگرچہ حقوق العباد کی معافی مشکل ہے۔ (۲) میت کے ذمے حج واجب ہو (خواہ شرعاً یا نذراً) اور وہ زندگی میں ادا نہ کر سکا ہو تو اس کے مال سے اس کی طرف سے حج کروایا جائے۔ اسی طرح کفارہ، زکاۃ اور قرض بھی ادا کیا جائے گا، خواہ میت کا سارا مال ہی صرف ہو جائے۔ ثلث کا لحاظ نہیں رکھا جائے گا کیونکہ ان کی حیثیت محض وصیت کی سی نہیں۔ (۳) اس روایت سے قیاس کے جواز پر استدلال کیا گیا ہے مگر حقیقت یہ ہے کہ نبی صلی اللہ علیہ وسلم کو تو قیاس کی ضرورت ہی نہیں تھی۔ وحی جاری تھی، نیز قیاس تو غیر منصوص چیز میں ہوتا ہے۔ آپ کا فرمان تو خود نص ہے۔ قیاس تو امتی کر سکتا ہے جس کے پاس نص (اللہ اور اس کے رسول کا صریح فرمان) نہ ہو۔ (۴) آدمی حج کی نذر مان سکتا ہے اگرچہ اس نے فرض حج نہ کیا ہو، پھر جب وہ حج کرے گا تو اس کا فرض حج ادا ہو جائے گا۔ بعد میں نذر کا حج کرے گا۔ یہ رائے جمہور کی ہے۔ ایک رائے اس کے برعکس بھی ہے، یعنی اس کا پہلا حج نذر کا شمار ہوگا اور دوسرا فرض اور ایک رائے یہ بھی ہے کہ اس کا حج دونوں سے کفایت کر جائے گا، لیکن یہ رائے درست معلوم نہیں ہوتی۔ (۵) یہ حدیث جمہور اہل علم کی دلیل ہے کہ اگر آدمی عمداً نماز ترک کر دیتا ہے تو اس پر اس کی قضا ضروری ہے کیونکہ یہ اس پر اللہ کا قرض ہے۔ (۶) عالم اور مفتی کو مسئلہ سمجھانے کا ایسا انداز اپنانا چاہیے کہ سائل کو پو ری طرح سمجھ میں آجائے اور اسے کسی قسم کی تشنگی باقی نہ رہے اور وہ بالکل مطمئن ہو جائے۔"}],[2633,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ ایک عورت نے سنان بن سلمہ جہنی رضی اللہ عنہ سے کہا کہ وہ رسول اللہ صلی اللہ علیہ وسلم سے پوچھیں کہ میری ماں مر گئی ہے اور اس نے حج نہیں کیا ہے تو کیا میں اس کی طرف سے حج کروں تو اسے کافی ہو گا؟ آپ نے فرمایا: \"ہاں، اگر اس کی ماں پر قرض ہوتا اور وہ اس کی جانب سے ادا کرتی تو کیا یہ اس کی طرف سے کافی نہ ہو جاتا؟ لہٰذا اسے اپنی ماں کی طرف سے حج کرنا چاہیئے\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ ایک عورت نے حضرت سنان بن سلمہ جہنی رضی اللہ عنہ سے کہا: رسول اللہ صلی اللہ علیہ وسلم سے پوچھیں کہ اس کی ماں (فرض) حج کیے بغیر فوت ہوگئی ہے۔ اگر وہ عورت اپنی ماں کی طرف سے حج کر لے تو وہ اسے کفایت کر جائے گا؟ آپ نے فرمایا: ’’ہاں۔ اگر اس کی ماں کے ذمے قرض ہوتا اور وہ عورت اس کی طرف سے ادا کر دیتی تو کیا اسے کفایت نہ کرتا؟ اسے چاہیے کہ وہ اپنی ماں کی طرف سے حج کرے۔‘‘","f2":"قرض کی مثال مسئلہ سمجھانے کے لیے ذکر فرمائی نہ یہ کہ حج کو قرض پر قیاس فرمایا۔"}],[2634,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ ایک عورت نے نبی اکرم صلی اللہ علیہ وسلم سے اپنے والد کے بارے میں جو مر گئے تھے اور حج نہیں کیا تھا پوچھا: آپ نے فرمایا: \"تم اپنے والد کی طرف سے حج کر لو\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے کہ ایک عورت نے نبی صلی اللہ علیہ وسلم سے اپنے والد کے بارے میں پوچھا جو (فرض) حج کیے بغیر فوت ہوگیا تھا۔ آپ نے فرمایا: ’’تو اپنے والد کی طرف سے حج کر لے۔‘‘","f2":"اگر میت پر حج فرض ہو چکا ہو اور وہ نہ کر سکے تو پھر اس کی طرف سے حج کیا جائے گا، ورنہ اگر اس پر حج فرض ہی نہیں تھا تو اس کی طرف سے حج کرنے کی ضرورت نہیں۔"}],[2635,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ قبیلہ خثعم کی ایک عورت نے مزدلفہ (یعنی دسویں ذی الحجہ) کی صبح کی کو رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: اللہ کے رسول! حج کے سلسلہ میں اللہ تعالی نے اپنے بندوں پر جو فریضہ عائد کیا ہے اس نے میرے والد کو اس حال میں پایا کہ وہ بہت بوڑھے ہیں، سواری پر ٹک نہیں سکتے، کیا میں ان کی طرف سے حج کر لوں؟ آپ نے فرمایا: \"ہاں (کر لو)\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے کہ بنو خثعم (قبیلے) کی ایک عورت نے مزدلفہ کی صبح رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: اے اللہ کے رسول! اللہ تعالیٰ کی طرف سے لوگوں پر فرض کیے گئے حج نے میرے والد کو اس حال میں پایا ہے کہ وہ انتہائی بوڑھے ہیں، سواری پر بھی نہیں بیٹھ سکتے، تو کیا میں ان کی طرف سے حج کر سکتی ہوں؟ آپ نے فرمایا: ’’ہاں۔‘‘","f2":"(۱) مزدلفہ کی صبح، یعنی جس صبح حاجی مزدلفہ سے منیٰ روانہ ہوتے ہیں۔ گویا ۱۰ ذی الحجہ۔ یہ حجۃ الوداع کی بات ہے۔ (۲) ’’سواری پر نہیں بیٹھ سکتے۔‘‘ معلوم ہوا کہ وجوب حج کے لیے جسمانی قوت شرط نہیں بلکہ مالی استطاعت (یعنی آنے جانے اور کھانے پینے کا خرچ) کافی ہے ورنہ آپ فرما دیتے کہ تیرے باپ پر حج واجب ہی نہیں۔ مالی استطاعت ہونے کی صورت میں خود حج کرے۔ اگر جسمانی قوت نہ ہو تو کسی سے کروائے۔ (۳) ’’فرمایا: ہاں۔‘‘ یعنی اگلے سال یا اس سے بعد کیونکہ یہ حج تو وہ اپنی طرف سے کر رہی تھی بلکہ کر چکی تھی کیونکہ یہ وقوف عرفہ سے بعد کی بات ہے اور وقوف عرفہ ہی حاصل حج ہے۔ (۴) جمہور اہل علم کے نزدیک حج بدل (جو کسی کی طرف سے کیا جائے) صرف وہی شخص کر سکتا ہے جو اپنا حج پہلے کر چکا ہو۔ ابوداؤد کی ایک روایت میں آپ نے صراحتاً ایک شخص کو اپنا حج کرنے سے پہلے شبرمہ نامی شخص کی طرف سے حج کرنے سے روک دیا تھا۔ (۵) مرد اور عورت دونوں ایک دوسرے کی طرف سے حج بدل کر سکتے ہیں اگرچہ مرد، عورت کے احکام میں کچھ فرق ہے مگر وہ فرق احرام وغیرہ میں ہے۔ افعال حج ایک جیسے ہی ہیں۔ (۶) عورت کی آواز پردہ نہیں ہے۔ تعلیم و تعلم، استفادہ وافتا اور اس قسم کی دیگر ضروریات کے مواقع پر اجنبی عورت کی آواز سننے میں کوئی حرج نہیں لیکن عورت کو چاہیے اجنبی سے بات کرتے وقت اس طرح نرم لہجہ اختیار نہ کرے جس سے فتنے کا اندیشہ ہو۔ (۷) والدین کے ساتھ نیکی کا برتاؤ کرنا چاہیے اور ان سے حسن سلوک سے پیش آنا چاہیے۔ اگر ان کی وفات کے بعد ان پر کوئی حج یا قرض وغیرہ کا فریضہ ہو جسے وہ کسی عذر کی بنا پر ادا نہ کر سکے ہوں تو اولاد کو چاہیے کہ ان کی طرف سے وہ فریضہ انجام دیں۔ واللہ اعلم"}],[2636,"اس سند سے بھی ابن عباس رضی اللہ عنہما سے اسی کے مثل مروی ہے۔","الألباني: سكت عنه الشيخ"],[2637,"ابورزین عقیلی رضی اللہ عنہ سے روایت ہے کہ انہوں نے عرض کیا: اللہ کے رسول! میرے والد بہت بوڑھے ہیں، نہ وہ حج و عمرہ کرنے کی طاقت رکھتے ہیں، اور نہ ہی سواری پر چڑھ سکتے ہیں، آپ نے فرمایا: \"تم اپنے والد کی طرف سے حج و عمرہ کر لو\"۔","الألباني: صحيح",{"u2":"حضرت ابو رزین عقیلی رضی اللہ عنہ بیان کرتے ہیں کہ میں نے کہا: اے اللہ کے رسول! میرے والد بہت بوڑھے ہو چکے ہیں، حج وعمرہ بلکہ سفر بھی نہیں کر سکتے۔ آپ نے فرمایا: ’’تم اپنے والد کی طرف سے حج اور عمرہ کرو۔‘‘","f2":"مذکورہ حدیث سے معلوم ہوتا ہے کہ عمرہ بھی فرض ہے۔ تبھی بیٹے کو عمرہ کرنے کا بھی حکم دیا الا یہ کہ کہا جائے کہ عمرہ، نذر وغیرہ کی بنا پر بھی تو واجب ہو سکتا ہے۔ مگر یہاں نذر کا ادنیٰ ترین اشآرہ بھی نہیں ہے بلکہ حج اور عمرے کو ایک ساتھ ذکر کرنا اور جسمانی معذوری کا عذر کرنا دونوں کو ایک ہی حیثیت دیتا ہے۔ صحابہ کرامe اور جمہور اہل علم فرضیت ہی کے قائل ہیں۔ مزید تفصیل کے لیے دیکھیے: (ذخیرۃ العقبیٰ شرح سنن النسائی: ۲۳/ ۲۹۳)\nمذکورہ حدیث سے معلوم ہوتا ہے کہ عمرہ بھی فرض ہے۔ تبھی بیٹے کو عمرہ کرنے کا بھی حکم دیا الا یہ کہ کہا جائے کہ عمرہ، نذر وغیرہ کی بنا پر بھی تو واجب ہو سکتا ہے۔ مگر یہاں نذر کا ادنیٰ ترین اشآرہ بھی نہیں ہے بلکہ حج اور عمرے کو ایک ساتھ ذکر کرنا اور جسمانی معذوری کا عذر کرنا دونوں کو ایک ہی حیثیت دیتا ہے۔ صحابہ کرامe اور جمہور اہل علم فرضیت ہی کے قائل ہیں۔ مزید تفصیل کے لیے دیکھیے: (ذخیرۃ العقبیٰ شرح سنن النسائی: ۲۳/ ۲۹۳)"}],[2638,"عبداللہ بن زبیر رضی اللہ عنہما کہتے ہیں کہ قبیلہ خثعم کا ایک شخص رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور عرض کیا: میرے والد بہت بوڑھے ہیں وہ سواری پر چڑھ نہیں سکتے، اور حج کا فریضہ ان پر عائد ہو چکا ہے، میں ان کی طرف سے حج کر لوں تو کیا وہ ان کی طرف سے ادا ہو جائے گا؟ آپ نے فرمایا: \"کیا تم ان کے بڑے بیٹے ہو؟\" اس نے کہا: جی ہاں (میں ان کا بڑا بیٹا ہوں) آپ نے فرمایا: \"تمہارا کیا خیال ہے اگر ان پر قرض ہوتا تو تم اسے ادا کرتے؟\" اس نے کہا: ہاں (میں ادا کرتا) آپ نے فرمایا: \"تو تم ان کی طرف سے حج ادا کرو\"۔","الألباني: ضعيف الإسناد",{"u2":"حضرت عبداللہ بن زبیر رضی اللہ عنہ سے روایت ہے کہ خثعم قبیلے کا ایک آدمی رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوا اور کہنے لگا: میرے والد انتہائی بوڑھے ہیں۔ وہ سوار نہیں ہو سکتے۔ اور اللہ کے فریضہ حج نے انھیں آ لیا ہے۔ کیا ان کی طرف سے حج کرنا ان کو کفایت کر جائے گا؟ آپ نے فرمایا: ’’کیا تو اس کا سب سے بڑا بیٹا ہے؟‘‘ اس نے کہا: جی ہاں۔ آپ نے فرمایا: ’’تو بتا اگر تیرے والد کے ذمے قرض ہوتا تو کیا تو اسے ادا کرتا؟‘‘ اس نے کہا: جی ہاں۔ آپ نے فرمایا: ’’پھر تو اس کی طرف سے حج بھی کر۔‘‘","f2":"(۱) محقق کتاب نے مذکورہ روایت کو سنداً ضعیف قرار دیا ہے اور مزید لکھا ہے کہ اس کی اصل صحیح ہے جس سے معلوم ہوتا ہے کہ ان کے نزدیک بھی روایت معناً صحیح ہے، تاہم راجح اور درست بات یہ ہے کہ [اَنْتَ اَکْبَرُ وَلَدِہِ] کے علاوہ باقی روایت شواہد کی بنا پر صحیح ہے۔ تفصیل کے لیے دیکھیے: (الموسوعۃ الحدیثیۃ مسند الامام احمد: ۲۶/ ۴۷،۴۸) (۲) حج بدل کے لیے یہ ضروری نہیں کہ بڑا بیٹا ہی کرے بلکہ کوئی بیٹا بھی بلکہ بھائی حتیٰ کہ عام قرابت دار بھی حج بدل کر سکتا ہے۔ جیسا کہ اس بارے میں آنے والی دیگر روایات سے صاف معلوم ہوتا ہے۔ (دیگر مباحث کے لیے دیکھیے، روایات: ۲۶۳۳، ۲۲۳۶"}],[2639,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ ایک شخص نے پوچھا: اللہ کے رسول! میرے والد انتقال کر گئے اور انہوں نے حج نہیں کیا، کیا میں ان کی طرف سے حج کر لوں؟ آپ نے فرمایا: \"کیا خیال ہے اگر تمہارے والد پر کچھ قرض ہوتا تو تم ادا کرتے؟\" اس نے کہا: ہاں (میں ادا کرتا) تو آپ نے فرمایا: \"تو اللہ تعالی کا قرض ادا کئے جانے کا زیادہ مستحق ہے\"۔\n§وضاحت\n۱؎: عبداللہ بن عباس رضی اللہ عنہما کی روایت میں صحیح بات یہ ہے کہ مسئلہ پوچھنے والی عورت تھی، اور اپنے باپ کے بارے میں پوچھا تھا جو زندہ مگر کمزور تھا، اور اس واقعہ کے وقت یا تو دونوں بھائی :(عبداللہ اور فضل ) موجود تھے یا فضل نے یہ واقعہ عبداللہ بن عباس سے بیان کیا، روایت کی صحت میں اس سے کوئی فرق نہیں پڑتا، ابن عباس رضی اللہ عنہما کی روایت کے سوا دیگر صحابہ کی روایتوں میں دیگر واقعات بھی اسی طرح کے سوال و جواب کے ممکن ہیں، پوچھنے والے مرد و عورت بھی ہو سکتے ہیں، اور جن کے بارے میں پوچھا گیا وہ بھی مرد و عورت ہو سکتے ہیں، اور یہ کوئی ایسی بات نہیں، جس کو بنیاد بنا کر حدیث کی حجیت کے سلسلے میں شکوک و شبہات پیدا کئے جائیں۔","الألباني: ضعيف الإسناد",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے منقول ہے کہ ایک آدمی نے کہا: اے اللہ کے رسول! میرے والد حج کیے بغیر فوت ہوگئے ہیں، تو کیا میں ان کی طرف سے حج کر سکتا ہوں؟ آپ نے فرمایا: ’’بتاؤ اگر تمھارے والد پر قرض ہوتا تو کیا تم اسے ادا کرتے؟‘‘ اس نے کہا: جی ہاں۔ آپ نے فرمایا: ’’تو اللہ کا قرض ادائیگی کا زیادہ حق دار ہے۔‘‘"}],[2640,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ ایک شخص نے نبی اکرم صلی اللہ علیہ وسلم سے پوچھا: میرے باپ کو (فریضہ) حج نے اس حال میں پایا کہ وہ بہت بوڑھے ہو چکے ہیں اپنی سواری پر ٹک نہیں سکتے، اگر میں انہیں سواری پر بٹھا کر باندھ دوں تو ڈرتا ہوں کہ کہیں مر نہ جائیں۔ کیا میں ان کی طرف سے حج کر لوں؟ آپ نے فرمایا: \"تمہارا کیا خیال ہے اگر ان پر قرض ہوتا تو اسے ادا کرتے، تو وہ کافی ہو جاتا\"؟ اس نے کہا: ہاں (کافی ہو جاتا) آپ نے فرمایا: \"پھر اپنے باپ کی طرف سے حج کرو\"۔","الألباني: شاذ أو منكر بذكر الرجل والمحفوظ أن السائل امرأة",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے، ایک آدمی نے نبی صلی اللہ علیہ وسلم سے پوچھا کہ میرے باپ پر حج فرض ہے مگر وہ انتہائی بوڑھے ہیں۔ سواری پر نہیں بیٹھ سکتے۔ اور اگر میں انھیں (پالان پر) باندھ دوں تو خطرہ ہے کہ وہ مر جائیں گے، تو کیا میں ان کی طرف سے حج کر سکتا ہوں؟ فرمایا: ’’بتاؤ اگر اس پر قرض ہوتا اور تم ادا کرتے تو کیا اسے کفایت کرتا؟‘‘ اس نے کہا: جی ہاں۔ آپ نے فرمایا: ’’پھر تم اپنے باپ کی طرف سے حج بھی کرو۔‘‘","f2":"مذکورہ روایت میں ہے کہ سوال کرنے والا مرد تھا جبکہ اس سے قبل حدیث نمبر: ۲۶۳۸، ۲۶۳۶ اور اس کے بعد حدیث: ۲۶۶۲، ۲۶۴۳ وغیرہ میں مذکورہ ہے کہ سوال کرنے والی عورت تھی، تاہم راجح اور درست بات یہ ہے کہ سوال کرنے والی عورت ہی تھی اور [الرجل] ’’مرد‘‘ کے الفاظ شاذ یا منکر ہیں۔ تفصیل کے لیے دیکھیے: (ضعیف سنن النسائی للالبانی، حدیث: ۲۶۳۹)"}],[2641,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ فضل بن عباس رضی اللہ عنہما رسول اللہ صلی اللہ علیہ وسلم کے پیچھے سواری پر تھے، تو قبیلہ خثعم کی ایک عورت رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک مسئلہ پوچھنے آئی، تو فضل اسے دیکھنے لگے، اور وہ فضل کو دیکھنے لگی، اور آپ فضل کا چہرہ دوسری طرف پھیرنے لگے، تو اس عورت نے پوچھا: اللہ کے رسول! اپنے بندوں پر اللہ کے عائد کردہ فریضہ حج نے میرے باپ کو اس حال میں پایا: انتہائی بوڑھے ہو چکے ہیں، سواری پر ٹک نہیں سکتے، کیا میں ان کی طرف سے حج کر لوں؟ آپ نے فرمایا: \"ہاں کر لو\"، یہ واقعہ حجۃ الوداع کا ہے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عباس رضی اللہ عنہ بیان کرتے ہیں کہ (میرے بھائی) فضل بن عباس رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کے پیچھے اونٹنی ہی پر سوار تھے کہ خثعم قبیلے کی ایک عورت آکر آپ سے مسئلہ پوچھنے لگی۔ فضل اسے دیکھنے لگے اور وہ انھیں دیکھنے لگی۔ رسول اللہ صلی اللہ علیہ وسلم نے فضل کا چہرہ دوسری طرف پھیر دیا۔ وہ عورت کہنے لگی: اے اللہ کے رسول! اللہ تعالیٰ کے فریضہ حج نے، جو اس نے اپنے بندوں پر عائد کیا ہے، میرے والد کو بہت بڑھاپے کی حالت میں پایا ہے۔ وہ سواری پر بیٹھ بھی نہیں سکتے۔ تو کیا میں ان کی طرف سے حج کر سکتی ہوں؟ آپ نے فرمایا: ’’ہاں۔‘‘ (ابن عباس رضی اللہ عنہ نے فرمایا:) یہ حجۃ الوداع کی بات ہے۔","f2":"(۱) معلوم ہوا اگر جانور طاقتور ہو تو ایک سے زیادہ آدمی اس پر سوار ہو سکتے ہیں لیکن کمزور جانور پر ضرورت سے زیادہ بوجھ ڈالنا ظلم ہے۔ (۲) نبی اکرم صلی اللہ علیہ وسلم کی تواضع اور شفقت اور فضل بن عباس رضی اللہ عنہ کی فضیلت ومنقبت معلوم ہوئی۔ (۳) اجنبی عورت کی طرف دیکھنا منع ہے۔ (۴) ہر مسلمان پر بالعموم اور عالم وامام پر بالخصوص لازم ہے کہ وہ برائی دیکھ کر ہر ممکن اسے ختم کرنے کی کوشس کرے۔ مزید دیکھیے، روایت: ۲۶۳۶۔"}],[2642,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ حجۃ الوداع کے موقع پر قبیلہ خثعم کی ایک عورت رسول اللہ صلی اللہ علیہ وسلم کے پاس مسئلہ پوچھنے آئی اور فضل بن عباس رضی اللہ عنہما رسول اللہ صلی اللہ علیہ وسلم کے پیچھے اونٹ پر سوار تھے، اس عورت نے عرض کیا: اللہ کے رسول! اپنے بندوں پر عائد کردہ اللہ کے فریضہ حج نے میرے والد کو اس حال میں پایا کہ وہ بہت بوڑھے ہو چکے ہیں وہ سواری پر سیدھے نہیں رہ سکتے، تو کیا اگر میں ان کی طرف سے حج کروں تو ان کی طرف سے پورا ہو جائے گا؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہاں ہو جائے گا\"، تو فضل بن عباس رضی اللہ عنہما اسے مڑ کر دیکھنے لگے، وہ ایک خوبصورت عورت تھی تو رسول اللہ صلی اللہ علیہ وسلم نے فضل بن عباس کو پکڑ کر ان کا چہرہ دوسری جانب پھیر دیا۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ نے خبر دی کہ حجۃ الوداع میں خثعم قبیلے کی ایک عورت نے رسول اللہ صلی اللہ علیہ وسلم سے مسئلہ پوچھا، حضرت فضل بن عباس رضی اللہ عنہ آپ کے پیچھے سواری پر بیٹھے تھے۔ وہ کہنے لگی: اے اللہ کے رسول! اللہ تعالیٰ کے اپنے بندوں پر فریضہ حج نے میرے والد کو بہت بڑھاپے کی حالت میں پایا ہے۔ وہ سواری پر بیٹھ بھی نہیں سکتے۔ اگر میں ان کی طرف سے حج کروں تو کیا ان کی طرف سے کفایت ہو جائے گا؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ہاں۔‘‘ فضل بن عباس رضی اللہ عنہ اس عورت کو دیکھنے لگے (کیونکہ) وہ خوش شکل تھی۔ رسول اللہ صلی اللہ علیہ وسلم نے فضل کا چہرہ پکڑ کر دوسری طرف پھیر دیا۔"}],[2643,"فضل بن عباس رضی اللہ عنہما سے روایت ہے کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے پیچھے سواری پر سوار تھے تو آپ کے پاس ایک شخص آیا اور اس نے عرض کیا: اللہ کے رسول! میری ماں بہت بوڑھی ہو چکی ہیں، اگر میں انہیں سواری پر چڑھا دوں تو وہ بیٹھی نہیں رہ سکتیں، اور اگر میں انہیں (سواری پر بٹھا کر) باندھ دوں تو ڈرتا ہوں کہ کہیں ان کی جان نہ لے بیٹھوں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کیا خیال ہے اگر تمہاری ماں پر قرض ہوتا تو تم اسے ادا کرتے؟\" اس نے کہا: جی ہاں (میں ادا کرتا) آپ نے فرمایا: \"تو تم اپنی ماں کی جانب سے حج کرو\"۔","الألباني: شاذ",{"u2":"حضرت ابن عباس رضی اللہ عنہ نے خبر دی کہ حجۃ الوداع میں خثعم قبیلے کی ایک عورت نے رسول اللہ صلی اللہ علیہ وسلم سے مسئلہ پوچھا، حضرت فضل بن عباس رضی اللہ عنہ آپ کے پیچھے سواری پر بیٹھے تھے۔ وہ کہنے لگی: اے اللہ کے رسول! اللہ تعالیٰ کے اپنے بندوں پر فریضہ حج نے میرے والد کو بہت بڑھاپے کی حالت میں پایا ہے۔ وہ سواری پر بیٹھ بھی نہیں سکتے۔ اگر میں ان کی طرف سے حج کروں تو کیا ان کی طرف سے کفایت ہو جائے گا؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’ہاں۔‘‘ فضل بن عباس رضی اللہ عنہ اس عورت کو دیکھنے لگے (کیونکہ) وہ خوش شکل تھی۔ رسول اللہ صلی اللہ علیہ وسلم نے فضل کا چہرہ پکڑ کر دوسری طرف پھیر دیا۔"}],[2644,"عبداللہ بن زبیر رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ایک شخص سے فرمایا: \"تم اپنے باپ کا بڑے بیٹے ہو تو تم ان کی طرف سے حج کرو\"۔","الألباني: ضعيف الإسناد",{"u2":"حضرت ابن زبیر رضی اللہ عنہ سے منقول ہے، نبی صلی اللہ علیہ وسلم نے ایک آدمی سے فرمایا: ’’تو اپنے والد کا سب سے بڑا بیٹا ہے، لہٰزا ترو اس کی طرف سے حج کر۔‘‘","f2":"حدیث میں مذکور مسئلے کی وضاحت حدیث: ۲۶۳۹ کے فوائد میں گزر چکی ہے۔ وہاں ملاحظہ فرمائیے۔ (۲) گزشتہ تیرہ روایات جو حج بدل کے بارے میں ہیں، ان میں کسی جگہ سائل مرد ہے کہیں عورت۔ بعض روایات میں زندہ کے بارے میں سوال ہے، بعض میں میت کے بارے میں۔ کسی روایت میں باپ کا ذکر ہے، کسی میں ماں کا اور کسی میں بہن کا، تاہم جن روایات میں شذوذ تھا اس کی وضاحت کر دی گئی ہے۔ بنا بریں یہ کوئی پریشانی کی بات نہیں کیونکہ ایک ہی مسئلہ کئی اشخاص کو پیش آسکتا ہے۔ خصوصاً، اس لیے کہ حجۃ الوداع میں تمام علاقوں کے لوگ موجود تھے۔ فرضیت کے بعد عملاً یہ پہلا حج تھا۔ عموماً لوگ حج کے مسائل سے واقف نہ تھے، لہٰذا بہت سے لوگوں نے اپنے اپنے حالات کے مطابق سوالات کیے، اس لیے سب روایات اپنی اپنی جگہ صحیح ہیں۔ کوئی اشکال نہیں۔ واللہ اعلم"}],[2645,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ ایک عورت نے اپنے بچے کو رسول اللہ صلی اللہ علیہ وسلم کے سامنے اٹھایا اور پوچھا: اللہ کے رسول! کیا اس کا بھی حج ہے؟ آپ نے فرمایا: \"ہاں (اس کا بھی حج ہے) اور تمہیں اس کا اجر ملے گا\" ۱؎۔\n§وضاحت\n۱؎: مطلب یہ ہے کہ چھوٹے بچے کو حج کرانا جائز ہے اس کا اجر ماں باپ کو ملے گا لیکن کوئی بچہ بالغ ہونے کے بعد صاحب استطاعت ہو جائے تو اس کے لیے دوبارہ فریضہ حج کی ادائیگی ضروری ہو گی بچپن کا کیا ہوا حج کافی نہیں ہو گا۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے کہ ایک عورت نے اپنا بچہ رسول اللہ صلی اللہ علیہ وسلم کی طرف ہاتھوں پر بلند کیا اور کہنے لگی: اے اللہ کے رسول! کیا اس کا بھی حج ہے؟ آپ نے فرمایا: ’’ہاں، اور ثواب تجھے ملے گا۔‘‘","f2":"(۱) کم سن اور نابالغ پر فرائض کی ادائیگی ضروری نہیں لیکن اگر وہ کسی فرض کی ادائیگی کرے یا اسے ادائیگی کروا دی جائے تو وہ صحیح اور باعث اجر ہوگی، مثلاً: والدین کا شیر خوار بچے کو حج کروانا، تو ایسی صورت میں حج کا احرام اور اس کی پابندیاں والدین کی ذمہ داری ہوگی کہ وہ ان کا خیال رکھیں، اسی لیے انھیں بچے کے نیک کاموں کا ثواب ملے گا۔ اسی طرح سات سال کے بچے کا نمازروزہ ادا کرنا، لیکن اسے شرائط کا لحاظ بھی رکھنا ہوگا، مثلاً: نماز کے لیے طہارت اور وضو وغیرہ کا اہتمام کرنا۔ لیکن اس کا یہ مطلب ہرگز نہیں کہ بچے کو ثواب ملے گا ہی نہیں، بلکہ بچے کو بھی ثواب ملے گا اور اولیاء چونکہ اسے محنت مشقت سے وہ کام کراتے ہیں، اس لیے انھیں اس مشقت کے باعث ثواب ملے گا۔ (۲) اس بات پر قریباً اجماع ہے کہ بلوغت سے پہلے کا حج فرض حج کی جگہ کفایت نہیں کرے گا بلکہ وہ بلوغت کے بعد ادا کرنا ہوگا۔ راوی حدیث حضرت عبداللہ بن عباس رضی اللہ عنہ اور دیگر صحابہ کے فتوے اس کی مضبوط دلیل ہیں۔ (۳) اس حدیث میں مذکور جس بچے کی بابت سوال کیا گیا ہے وہ بچہ تو بہت ہی چھوٹا معلوم ہوتا ہے کہ اسے اس عورت نے ہاتھ پر اٹھا لیا تھا۔ بہرحال والدہ کے لیے ثواب تو ہے ہی کیونکہ وہ اسے اٹھائے پھرتی ہے۔"}],[2646,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ ایک عورت نے اپنے بچے کو ہودج سے اوپر اٹھایا اور کہنے لگی: اللہ کے رسول! کیا اس کا بھی حج ہے؟ آپ نے فرمایا: \"ہاں(اس کا بھی حج ہے) اور تمہیں اس کا اجر ملے گا۔\"","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ ایک عورت نے اپنا بچہ ہودج سے اٹھایا اور (رسول اللہ صلی اللہ علیہ وسلم کو دکھا کر آپ سے) کہنے لگی: اے اللہ کے رسول! کیا اس کا بھی حج ہوگا؟ آپ نے فرمایا: ’’ہاں۔ اور ثواب تجھے ملے گا۔‘‘"}],[2647,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ ایک عورت نے ایک بچے کو نبی اکرم صلی اللہ علیہ وسلم کے سامنے اٹھایا اور پوچھنے لگی: کیا اس کا بھی حج ہے؟ آپ نے فرمایا:\"ہاں (اس کا بھی حج ہے) اور تمہیں اس کا اجر ملے گا\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے مروی ہے کہ ایک عورت نے نبی صلی اللہ علیہ وسلم کی طرف ایک بچہ اٹھایا اور کہنے لگی: کیا اس کا بھی حج ہوگا؟ آپ نے فرمایا: ’’ہاں۔ اور ثواب تیرے لیے ہے۔‘‘","f2":"’’ثواب تجھے ملے گا۔‘‘ بہت ہی چھوٹا ہونے کی صورت میں نیت ثواب بھی ضروری ہے۔ اگر وہ صاحب تمیز ہوگا تو پھر تو افعال بھی ادا کرے گا۔"}],[2648,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم چلے جب روحاء پہنچے تو کچھ لوگوں سے ملے تو آپ نے پوچھا: \"تم کون لوگ ہو؟\" ان لوگوں نے کہا: ہم مسلمان ہیں، پھر ان لوگوں نے پوچھا: آپ کون ہیں؟ لوگوں نے بتایا: \"آپ اللہ کے رسول ہیں\"، یہ سن کر ایک عورت نے کجاوے سے ایک بچے کو نکالا، اور پوچھنے لگی: کیا اس کے لیے حج ہے؟ آپ نے فرمایا: \"ہاں اور ثواب تمہیں ملے گا\"۔\n§وضاحت\n۱؎: مکہ کے راستے میں مدینہ سے ۳۶ میل :(۷۵ کلومیٹر ) کی دوری پر ایک مقام کا نام ہے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم (حج سے) واپس (مدینہ منورہ کو) تشریف لا رہے تھے۔ جب مقام روحاء پر پہنچے تو کچھ لوگوں سے ملے۔ اپ نے فرمایا: ’’تم کون ہوں؟‘‘ انھوں نے عرض کیا: ہم مسلمان ہیں، پھر وہ کہنے لگے: آپ کون ہو؟ حاضرین نے بتایا کہ یہ اللہ کے رسول ہیں۔ تو ان کی ایک عورت نے ڈولی سے ایک بچہ اٹھایا اور کہنے لگی: کیا اس کے لیے حج ہے؟ آپ نے فرمایا: ’’ہاں۔ اور ثواب تیرے لیے ہے۔‘‘","f2":"یہ لوگ بھی حج ہی سے واپس آرہے تھے۔ ’’روحائ‘‘ مکہ اور مدینہ کے راستے میں ایک جگہ کا نام ہے جو کہ مدینہ منورہ سے تقریباً چالیس میل کے فاصلے پر ہے۔"}],[2649,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ایک عورت کے پاس سے گزرے وہ پردے میں تھی اور اس کے ساتھ ایک چھوٹا بچہ تھا، اس نے کہا: کیا اس کے لیے حج ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"ہاں، اور ثواب تمہیں ملے گا\"۔","الألباني: صحيح م دون ذكر الخدر",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے مذکور ہے کہ رسول اللہ صلی اللہ علیہ وسلم (حج سے واپسی کے دوران میں) ایک عورت کے پاس سے گزرے۔ وہ پردے میں تھی اور اس کے ساتھ اس کا ایک بچہ تھا۔ وہ کہنے لگی: کیا اس کے لیے حج ہے؟ آپ نے فرمایا: ’’ہاں۔ اور ثواب تیرے لیے ہے۔‘‘","f2":"یہ ایک حدیث پانچ سندوں سے ذکر کی گئی ہے جس کا سب سے بڑا فائدہ یہ ہے کہ تمام سندیں ملانے سے واقعے کی پوری تفصیل معلوم ہو جاتی ہیں، نیز پتا چل جاتا ہے کہ یہ حدیث شاذ اور غریب نہیں۔"}],[2650,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ذی قعدہ کی پانچ تاریخیں رہ گئی تھیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ (مدینہ سے) سے نکلے، ہمارے پیش نظر صرف حج تھا، یہاں تک کہ جب ہم مکہ کے قریب پہنچے تو رسول اللہ صلی اللہ علیہ وسلم نے ان لوگوں کو جن کے پاس ہدی (قربانی کا جانور) نہیں تھا حکم دیا کہ وہ طواف کر چکیں تو احرام کھول دیں۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ (حج کے لیے) چلے تو ذوالقعدہ کے پانچ دن باقی تھے۔ ہم (عموماً) حج ہی کی نیت رکھتے تھے مگر جب ہم مکہ مکرمہ کے قریب ہوئے تو آپ نے حکم فرمایا: ’’جن کے ساتھ قربانی کا جانور نہیں، وہ جب بیت اللہ کا طواف کر چکیں تو احرام ختم کر دیں (حلال ہو جائیں۔","f2":"(۱) رسول اللہ صلی اللہ علیہ وسلم مدینے سے ہفتے کے دن نکلے جبکہ ماہ ذوالقعدہ کے پانچ دن باقی تھے اور آپ نے وقوف عرفہ جمعے کے دن فرمایا۔ مختلف تاریخوں کا ذکر ہے لیکن یہی قول اقرب الی الصواب ہے۔ واللہ اعلم (۲) ’’حج کی نیت رکھتے تھے۔‘‘ اکثر صحابہ کی نیت یہی تھی مگر بعض صحابہ حتی کہ خود حضرت عائشہ رضی اللہ عنہا بھی عمرے کا احرام باندھے ہوئے تھیں۔ (۳) ’’احرام ختم کر دیں۔‘‘ یعنی عمرہ کر کے حلال ہو جائیں، خواہ احرام حج ہی کا ہو۔ اس بات میں اختلاف ہے کہ کیا اب بھی ایسے جائز ہے کہ حج کے احرام کو عمرے کے احرام میں بدل دیں؟ بظاہر یہ اب بھی جائز ہے جیسا کہ مذکورہ حدیث سے اخذ ہوتا ہے۔ اس موقف کی مزید تائید اس سے بھی ہوتی ہے کہ اس موقع پر بعض صحابہ کرامe نے دریافت کیا کہ آیا یہ اس سال کے ساتھ ہی خاص ہے یا یہ اجازت ہمیشہ کے لیے ہے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے اس کے جواب میں اسے قیامت تک کے لیے جائز قرار دیتے ہوئے فرمایا: [دَخَلَتِ الْعُمْرَۃُ فِی الْحَجِ ّ اِلَی یَوْمِ الْقِیَامَۃِ، لَا بَلْ لِأَبَدٍ اَبَدٍ، لَابَلْ لِأَبَدٍ اَبَدٍ] ’’تا قیامت عمرہ حج میں داخل ہوگیا، نہیں بلکہ یہ ہمیشہ ہمیشہ کے لیے، نہیں بلکہ یہ اجازت ہمیشہ ہمیش کے لیے ہے۔‘‘ مزید تفصیل کے لیے دیکھیے: (حجۃ النبی للالبانی، ص: ۱۵) لیکن جمہو اہل علم اب اس کے جواز کے قائل نہیں۔ ان کے بقول یہ حکم صرف اس سال کے لیے تھا کیونکہ حج کے دنوں میں عمرہ کرنے کی اجازت تازہ تازہ ملی تھی۔ پہلے لوگ حج کے دنوں میں عمرہ کرنا گناہ سمجھتے تھے، اس لیے وضاحت کے لیے آپ نے یہ حکم دیا۔ لیکن صریح حدیث کی روشنی میں یہ توجیہ محل نظر ہے۔ (۷) ’’جب بیت اللہ کا طواف کر چکیں۔‘‘ یعنی مکمل عمرہ کر لیں۔ طواف کے بعد سعی بھی کر چکیں۔ یہ مسئلہ متفقہ ہے۔"}],[2651,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مدینے والے ذوالحلیفہ سے تلبیہ پکاریں، اور اہل شام حجفہ سے اور نجد والے قرن المنازل سے\"۔ عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ مجھے یہ اطلاع بھی ملی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یمن والے یلملم سے تلبیہ پکاریں\"۔\n§وضاحت\n۱؎: مواقیت: میقات کی جمع ہے میقات اس مقام کو کہتے ہیں جہاں سے حاجی یا عمرہ کرنے والے کو تلبیہ پکارنا اور احرام باندھنا ضروری ہو جاتا ہے البتہ حاجی یا عمرہ کرنے والے مکہ میں ہوں یا میقات کے اندر رہتے ہوں تو ان کے لیے گھر سے نکلتے وقت احرام باندھ لینا اور تلبیہ پکارنا ہی کافی ہے میقات پر جانا ضروری نہیں۔ ۲؎: ذوالحلیفہ مدینہ مکہ روڈ پر مسجد نبوی سے :(۹ ) کلو میٹر کی دوری پر واقع ہے، افسوس ہے کہ شیعی روایات کی بنا پر یہ مشہور ہے کہ علی رضی اللہ عنہ کا جنوں سے مقابلہ ہوا اور آپ نے ان کو اس مقام کے کنوؤں میں بند کر دیا، اور اس سے اس جگہ کو \" ابیار علی \" کہا جانے لگا، شیخ الاسلام ابن تیمیہ نے اپنے منسک حج میں اس خرافات پر تنبیہ فرمائی ہے۔ ۳؎: مکہ مدینہ روڈ پر جُحفہ مکہ سے پانچ یا چھ مراحل کی دوری پر رابغ کے قریب ایک بستی کا نام ہے۔ ۴؎: قرن طائف کے قریب ایک بستی کا نام ہے یا پوری وادی کا نام ہے، اسے قرن المنازل اور قرن التعالب بھی کہا جاتا ہے۔ ۵؎: یلملم مکہ سے دو مرحلے کی دوری پر ایک جگہ کا نام ہے جس کے محاذاۃ میں مشرق جیسے ریاض، اور دمام نیز ہندوستان اور پاکستان وغیرہ سے آنے والے حجاج کرام کو جہاز میں باخبر کیا جاتا ہے کہ اب یلملم کی میقات کی محاذاۃ سے جہاز گزرنے والا ہے، حجاج احرام باندھنے اور تلبیہ پکارنے کے لیے تیار ہو جائیں۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مدینے والے ذوالحلیفہ سے شام والے جحفہ سے اور نجد والے قرن المنازل سے احرام باندھیں۔‘‘ حضرت عبداللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ مجھے یہ بات پہنچی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: ’’اور یمن والے یلملم سے احرام باندھیں۔‘‘","f2":"(۱) ’’یہ بات پہنچی ہے۔‘‘ گویا یہ ٹکڑا حضرت عبداللہ بن عمر رضی اللہ عنہ نے براہ راست رسول اللہ صلی اللہ علیہ وسلم سے نہیں سنا۔ لیکن دیگر روایات میں یہ ٹکڑآ بھی رسول اللہ صلی اللہ علیہ وسلم سے بلا شک وشبہ صحیح وثابت ہے۔ دیکھیے: (صحیح البکاری، الحج، حدیث: ۱۵۲۴، وصحیح مسلم، الحج، حدیث: ۱۱۸۱) (۲) ذوالحلیفہ مدینے سے چھ میل اور مکہ مکرمہ سے تقریباً ۴۵۰ کلو میٹر کے فاصلے پر ہے، اسے وادی عقیق بھی کہتے ہیں۔ آج کل اسے بئر علی یا ابیار علی کہتے ہیں۔ یہ میقات تمام مواقیت میں سے مکہ سے زیادہ دور ہے۔ (۲۳) حج کے ارادے سے جانے والوں کے لیے ان جگہوں سے بغیر احرام کے گزرنا جائز نہیں۔ (۴) یہ حدیث اعلام نبوت میں سے ہے۔ آپ نے جو میقات مقرر کیے، وہ اور ان کے آس پاس کے علاقوں والے ابھی مسلمان نہیں ہوئے تھے۔ لیکن آپ نے یہ میقات مقرر فرمائے کیونکہ آپ دیکھ رہے تھے کہ یہ علاقے مسلمان ہوں گے اور حج کے لیے بیت اللہ کی طرف رخت سفر باندھیں گے اور انھیں احرام باندھنے کی ضرورت پیش آئے گی۔ صلی اللہ علیہ وسلم (۵) چاروں طرف میقات مقرر کرنا امت کی سہولت کے لیے ہے۔ اگر ایک ہی میقات مقرر کیا جاتا تو یہ بہت زیادہ مشقت کا باعث ہوتا۔"}],[2652,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ ایک شخص مسجد (نبوی) میں کھڑا ہوا اور پوچھنے لگا: اللہ کے رسول! آپ ہمیں کہاں سے تلبیہ پکارنے کا حکم دیتے ہیں؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اہل مدینہ ذوالحلیفہ سے تلبیہ پکاریں گے، اور اہل شام حجفہ سے اور اہل نجد قرن سے۔ عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ لوگوں کا خیال ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے (یہ بھی) فرمایا: \"اہل یمن یلملم سے تلبیہ پکاریں گے\"، ابن عمر رضی اللہ عنہما کہتے تھے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے اسے نہیں سنا ہے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہ سے مروی ہے کہ ایک آدمی مسجد میں کھڑا ہوا اور کہنے لگا: اے اللہ کے رسول! آپ ہمیں کہاں سے احرام باندھنے کا حکم دیتے ہیں؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مدینہ منورہ والے ذوالحلیفہ سے، شام والے جحفہ سے اور نجد والے قرن منازل سے احرام باندھیں۔‘‘ حضرت ابن عمر رضی اللہ عنہ بیان کرتے ہیں کہ لوگ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے یہ بھی فرمایا تھا: ’’یمن والے یلملم سے احرام باندھیں۔‘‘ میں یہ جملہ رسول اللہ صلی اللہ علیہ وسلم سے نہیں سمجھ سکا (یعنی براہ راست آپ سے اخذ نہیں کیا بلکہ دوسرے صحابہ سے اخذ کیا ہے","f2":"جحفہ شام، مصر، ترکی، شمالی افریقہ، یورپ، امریکہ اور ادھر سے گزرنے والوں کا میقات ہے۔ یہ ایک ویران سی آبادی تھی۔ مکہ مکرمہ سے تقریباً ۱۸۷ کلو میٹر کے فاصلے پر رابغ کے قریب ہے۔ اس کا اصل نام مَھْیَعَہ تھا۔ سیلاب کی تباہ کاری کی وجہ سے اسے جحفہ کہنے لگے۔ یہ بھی مدینے سے جانے والوں کی راہ میں پڑتا ہے۔"}],[2653,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم اہل مدینہ کے لیے ذوالحلیفہ کو۔ اہل شام و مصر کے لیے حجفہ کو، اہل عراق کے لیے ذات عرق کو، اور اہل یمن کے لیے یلملم کو میقات مقرر کی ہے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مدینہ منورہ والوں کے لیے ذوالحلیفہ، شام اور مصر والوں کے لیے جحفہ عراق والوں کے لیے ذات عرق اور یمن والوں کے لیے یلملم میقات مقرر فرمائے۔","f2":"مصر والے اگر خشکی کے راستے سے مکہ مکرمہ آئیں تو شام والے راستے سے گزرتے ہیں، لہٰذا ان کا میقات شام والوں کا میقات جحفہ ہی ہوگا۔"}],[2654,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اہل مدینہ کے لیے ذوالحلیفہ کو، اہل شام کے لیے جحفہ کو، اہل نجد کے لیے قرن کو اور اہل یمن کے لیے یلملم کو میقات مقرر کی اور فرمایا: \"یہ یہاں کے لوگوں کی میقات ہیں اور ان تمام لوگوں کی بھی جو یہاں سے ہو کر گزریں چاہے جہاں کہیں کے بھی رہنے والے ہوں۔ اور جو لوگ ان میقاتوں کے اندر کے رہنے والے ہیں تو ان کی میقات وہیں سے ہے جہاں سے وہ چلیں یہاں تک کہ مکہ والوں کی میقات مکہ ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مدینہ منورہ والوں کے لیے ذوالحلیفہ، شام والوں کے لیے جحفہ، نجد والوں کے لیے قرن منازل اور یمن والوں کے لیے یلملم میقات مقرر فرمائے، نیز فرمایا: ’’یہ میقات ان علاقوں (کے لوگوں) کے لیے ہیں اور ان کے لیے بھی جو ان مواقیت سے گزریں، چاہے وہ دوسرے علاقوں سے تعلق رکھتے ہیں۔ اور جس شخص کی رہائش ان مواقیت کے اندر ہو تو وہ جہاں سے (عمرے اور حج کا) سفر شروع کریں، وہیں سے احرام باندھیں حتیٰ کہ یہ حکم مکے والوں پر بھی لاگو ہو گا، یعنی اہل مکہ، مکہ مکرمہ ہی سے احرام باندھیں گے۔‘‘","f2":"یلملم مکہ مکرمہ سے تقریباً ۹۲ کلو میٹر کے فاصلے پر ہے۔ آج کل اس کا نام سعدیہ ہے۔ پاکستان اور بھارت کے لوگ سمندری یا فضائی راستے سے جاتے ہیں تو یمن کی طرف سے ہو کر گزرتے ہیں اور یلملم کی سیدھ معلوم کر کے جہاز ہی میں احرام باندھ لیتے ہیں۔"}],[2655,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مدینہ والے ذوالحلیفہ سے تلبیہ پکاریں گے، شام والے حجفہ سے، اور نجد والے قرن (المنازل) سے\"، اور میں نے تو نہیں سنا ہے لیکن مجھ سے ذکر کیا گیا ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اور یمن والے یلملم سے تلبیہ پکاریں گے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے منقول ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’مدینے والے ذوالحلیفہ سے، شام والے جحفہ سے اور نجد والے قرن (المنازل) سے احرام باندھیں۔‘‘ اور مجھے بتایا گیا ہے، میں نے خود نہیں سنا کہ آپ نے فرمایا تھا: ’’یمن والے یلملم سے احرام باندھیں۔‘‘","f2":"(۱) اہل نجد اور نجد کے راستے سے آنے والوں کا میقات قرن منازل ہے، اسے قرن الثعالب بھی کہا جاتا ہے۔ مندرجہ بالا احادیث میں صرف لفظ قرن آیا ہے۔ بالاتفاق اس سے قرن المنازل مراد ہے۔ قرن المنازل مکہ مکرمہ سے مشرق کی طرف طائف کے قریب تقریباً ۹۴ کلو میٹر کے فاصلے پر ایک بستی یا وادی ہے۔ پہاڑ بھی کہا گیا ہے۔ کوئی اختلاف نہیں، تینوں اسی نام سے مشہور ہیں۔ آج کل اسے السَّیْل کہا جاتا ہے۔ (۲) نجد ہر اونچے علاقے کو کہتے ہیں۔ عرب میں تقریباً دس نجد ہیں۔ یہاں مراد وہ علاقہ ہے جو مکہ مکرمہ سے مشرقی جانب یمن اور تہامہ سے لے کر عراق اور شام تک پھیلا ہوا ہے۔"}],[2656,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مدینہ والوں کے لیے ذوالحلیفہ کو میقات مقرر کیا، اور شام و مصر والوں کے لیے حجفہ کو، اور عراق والوں کے لیے ذات عرق کو، اور نجد والوں کے لیے قرن (المنازل) کو، اور یمن والوں کے لیے یلملم کو۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مدینہ منورہ والوں کے لیے ذوالحلیفہ، شام اور مصر والوں کے لیے جحفہ عراق والوں کے لیے ذات عرق، نجد والوں کے لیے قرن اور یمن والوں کے لیے یلملم کو میقات مقرر فرمایا ہے۔","f2":"عراق والوں یا ادھر سے آنے والوں کا میقات ذات عرق ہے اور یہ متفقہ بات ہے۔ یہ مکہ مکرمہ سے تقریباً ۹۴ کلو میٹر کے فاصلے پر ہے۔ آج کل الضریبۃ (الخریبات) سے احرام باندھتے ہیں۔ بعض روایات میں ’’عقیق‘‘ کا ذکر بھی آیا ہے مگر اس روایت میں کچھ ضعف ہے۔ مندرجہ بالا روایات سے معلوم ہوتا ہے کہ ذات عرق کو رسول اللہ صلی اللہ علیہ وسلم نے عراق کا میقات قرار دیا ہے مگر بعض روایات میں اس تقرر کو حضرت عمر رضی اللہ عنہ کی طرف منسوب کیا گیا ہے۔ ممکن ہے۔ حضرت عمر رضی اللہ عنہ کو مندرجہ بالا روایات نہ ملی ہوں اور انھوں نے اپنے اجتہاد سے ذات عرق کو میقات مقرر فرمایا ہو کیونکہ عراق کے مشہور شہر کوفہ، بصرہ انھی کے دور میں آباد ہوئے۔ ان کا یہ اجتہاد رسول اللہ صلی اللہ علیہ وسلم کے فرمان کے موافق ہوگیا جس طرح ان کے دوسرے اجتہادات قرآن مجید کے موافق ہوئے۔ واللہ اعلم"}],[2657,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مدینہ والوں کے لیے ذوالحلیفہ کو میقات مقرر کیا، اور شام والوں کے لیے جحفہ، اور نجد والوں کے لیے قرن (قرن المنازل) کو، اور یمن والوں کے لیے یلملم کو اور فرمایا: \"یہ سب یہاں کے رہنے والوں کے میقات ہیں، اور ان لوگوں کے میقات بھی جو حج کا ارادہ رکھتے ہوں اور ان پر سے ہو کر گزریں۔ اور جو لوگ اس میقات کے اندر رہتے ہوں تو وہ جہاں سے شروع کریں وہیں سے وہیں سے تلبیہ پکاریں یہاں تک کہ یہی حکم مکہ والوں کو بھی پہنچے گا\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مدینہ منورہ والوں کے لیے ذوالحلیفہ، شام والوں کے لیے جحفہ، نجد والوں کے لیے قرن اور یمن والوں کے لیے یلملم کو میقات مقرر فرمایا۔ آپ نے فرمایا: ’’یہ مواقیت ان (علاقوں کے لوگوں) کے لیے ہیں۔ اور ان لوگوں کے لیے بھی جو دوسرے علاقوں سے ہوں لیکن ان مواقیت سے گزریں بشرطیکہ وہ حج و عمرہ کے ارادے سے آئیں۔ اور جو لوگ ان مواقیت کے اندر رہتے ہوں تو وہ ان جگہوں سے احرام باندھیں جہاں سے چلیں، حتیٰ کہ یہ حکم مکے والوں پر بھی لاگو ہوگا (کہ وہ مکے ہی سے حج کا احرام باندھیں)۔‘‘","f2":"(۱) ’’حج و عمرے کے ارادے سے آئیں‘‘ یہی بات صحیح ہے۔ احناف کا خیال ہے کہ جو شخص بھی مکہ جائے، خواہ کسی اور کام سے جائے، اس پر میقات سے احرام لازم ہے جیسے کہ تحیۃ المسجد ہے۔ لیکن الفاظ حدیث سے اس موقف کی تائید نہیں ہوتی، نیز مسجد میں آنے والے ہر شخص کے لیے تحیۃ المسجد ضروری نہیں بلکہ صرف اس شخص کے لیے ہے جو وہاں بیٹھنے کا ارادہ رکھتا ہو۔ یہی بات حج وعمرہ کے ارادے سے آنے والوں کے لیے ہے، اس لیے ہر ہر فرد احرام کا مکلف نہیں۔ (۲) ’’جہاں سے چلیں‘‘ یعنی اپنے گھر ہی سے احرام باندھیں۔ احناف کا خیال ہے کہ میقات کے اندر رہنے والے لوگ حدود حرم میں داخل ہونے سے پہلے پہلے جہاں سے مرضی ہو، احرام باندھیں لیکن احادیث کی رو سے اپنے گھر ہی سے احرام باندھنا چاہیے۔ (۳) ان احادیث سے یہ بھی معلوم ہوتا ہے کہ یہ مواقیت حج اور عمرہ دونوں کے لیے ہیں نہ کہ صرف حج کے لیے لہٰذا مکے والے عمرے کا احرام بھی اپنے گھر ہی سے باندھیں گے۔ لیکن جمہور اہل علم کے نزدیک مکے والے یا جو فی الوقت مکہ میں ہوں‘ عمرے کا احرام حدود حرم سے باہر آکر حل سے باندھیں۔ ان کی دلیل حضرت عائشہ رضی اللہ عنہا کی حدیث ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے انھیں عمرے کا احرام تنعیم (حرم کی قریب ترین حد مدینہ منورہ کی طرف) سے باندھنے کا حکم دیا تھا، حالانکہ وہ مکے میں تھیں۔ (صحیح البخاری، العمرۃ، حدیث: ۷۱۸۴، وصحیح مسلم، الحج، حدیث: ۱۲۱۱) ممکن ہے مکے سے بھی جائز ہو مگر حدود حرم سے افضل ہو۔ واللہ اعلم"}],[2658,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مدینہ والوں کے لیے ذوالحلیفہ کو میقات مقرر کیا، اور شام والوں کے لیے جحفہ کو اور یمن والوں کے لیے یلملم کو، اور نجد والوں کے لیے قرن المنازل کو۔ یہ جگہیں یہاں کے لوگوں کے لیے میقات ہیں اور ان کے علاوہ لوگوں کے لیے بھی جو ان پر سے ہو کر گزریں، اور حج و عمرہ کا ارادہ رکھنے والوں میں سے ہوں اور جو لوگ ان جگہوں کے اندر رہتے ہوں تو وہ اپنے گھر ہی سے تلبیہ پکاریں یہاں تک کہ مکہ والے مکہ ہی سے تلبیہ پکاریں گے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے مدینہ منورہ والوں کے لیے ذوالحلیفہ، شام والوں کے لیے جحفہ، یمن والوں کے لیے یلملم اور نجد والوں کے لیے قرن (منازل) کو میقات مقرر فرمایا۔ یہ مواقیت ان لوگوں کے لیے ہیں اور ان کے لیے جو دوسرے علاقوں سے آکر یہاں سے گزریں، بشرطیکہ وہ حج یا عمرے کا ارادہ رکھتے ہوں۔ اور جو لوگ ان مواقیت کے اندر رہتے ہوں، وہ اپنے گھر ہی سے احرام باندھیں حتیٰ کہ مکہ مکرمہ والے مکہ مکرمہ ہی سے احرام باندھیں۔","f2":"(۱) حج یا عمرے کو جانے کے لیے ضروری نہیں کہ وہ عین ان مواقیت ہی سے گزرے بلکہ کسی اور جگہ سے بھی گزر سکتا ہے مگر جب وہ اپنے قریبی میقات کے برابر سے گزرے تو وہیں سے احرام باندھ لے۔ (۲) اپ کے مقرر کردہ مواقیت میں سے ذوالحلیفہ مکہ مکرمہ سے شمال کی جانب، جحفہ بھی شمال کی جانب، یلملم جنوب کی جانب، قرن المنازل مشرق کی جانب اور ذات عرق بھی مشرق کی جانب ہیں اور جو لوگ دو میقاتوں کے درمیان سے گزریں تو وہ قریب ترین میقات کے برابر سے احرام باندھیں۔"}],[2659,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ذوالحلیفہ کے شروع ہونے کی جگہ میں رات گزاری اور اس کی مسجد میں نماز پڑھی۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ابتداء ً ذوالحلیفہ میں رات گزاری اور اس کی مسجد میں نماز پڑھی۔","f2":"(۱) یہاں سے احرام کا طریقہ بیان کرنا مقصود ہے۔ مدینہ منورہ والوں کا میقات ذوالحلیفہ ہے، لہٰذا آپ نے وہاں رات گزاری۔ صبح احرام باندھا۔ وہاں رات گزارنا کوئی ضروری نہیں۔ اس زمانے میں سفر کئی دنوں پر محیط ہوتا تھا، اس لیے رات گزارنے کی گنجائش تھی، اب تیز رفتار سفر کا دور ہے۔ (۲) ابتداء ً سے مراد یہ ہے کہ مکہ مکرمہ کو جاتے ہوئے ابتدائے سفر میں، نہ کہ واپسی کے وقت۔ (۳) ’’مسجد‘‘ رسول اللہ صلی اللہ علیہ وسلم کے دور میں وہاں کوئی مسجد نہیں تھی، بعد میں بنائی گئی۔ عین اسی جگہ جہاں آپ نے نماز پڑھی تھی۔"}],[2660,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کو خواب میں آیا گیا اور آپ ذوالحلیفہ کے پڑاؤ کی جگہ میں تھے اور کہا گیا کہ آپ بابرکت بطحاء میں ہیں۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم ذوالحلیفہ میں اپنے پڑاؤ کی جگہ میں تھے کہ آپ کو خواب آیا۔ آپ سے کہا گیا: آپ ایک بابرکلت وادی میں ہیں۔","f2":"’’بابرکت وادی میں ہیں۔‘‘ کیونکہ یہ وادی دوران سفر حج میں بہت سے انبیاء کی فرود گاہ رہی تھی۔ شام اور فلسطین انبیاء علیہم السلام کے علاقے ہیں۔ وہاں سے مکہ مکرمہ آتے ہوئے یہ وادی راستے میں پڑتی تھی۔"}],[2661,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بطحاء میں اپنا اونٹ بٹھایا جو ذوالحلیفہ میں ہے اور اسی جگہ آپ نے نماز پڑھی۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ذوالحلیفہ کی وادی مقدس میں پڑاؤ ڈالا اور وہاں نماز پڑھی"}],[2662,"انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ظہر کی نماز بیداء میں پڑھی، پھر سوار ہوئے اور بیداء پہاڑ پر چڑھے، اور ظہر کی نماز پڑھ کر حج و عمرے کا احرام باندھا۔\n§وضاحت\n۱؎: بیداء چٹیل میدان کو کہتے ہیں اور یہاں ذوالحلیفہ کے قریب ایک مخصوص جگہ مراد ہے آگے بھی اس لفظ سے یہی جگہ مراد ہو گی، اور جہاں تک آپ کے بیداء میں ظہر کی نماز پڑھنے کا معاملہ ہے تو کسی راوی سے وہم ہو گیا ہے، انس رضی اللہ عنہ ہی سے بخاری :(کتاب الحج، ۲۷ ) میں مروی ہے کہ آپ نے ظہر مدینہ میں چار پڑھی اور عصر ذوالحلیفہ میں دو پڑھی، اور نماز کے بعد ہی احرام باندھ لیا، یعنی حج و عمرہ کی نیت کر کے تلبیہ پکارنا شروع کر دیا تھا، اور ہر جگہ پکارتے رہے، اب جس نے جہاں پہلی بار سنا اس نے وہیں سے تلبیہ پکارنے کی روایت کر دی، سنن ابوداؤد :(کتاب الحج، ۲۱ ) میں عبداللہ بن عباس رضی اللہ عنہما کی مفصل روایت ان تمام اختلافات و اشکالات کو دور کر دیتی ہے۔","الألباني: ضعيف",{"u2":"حضرت انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ظہر کی نماز بیداء میں پڑھی، پھر سوار ہوئے اور بیداء کے پہاڑ پر چڑھے۔ اور نماز ظہر کے بعد حج و عمرے کا احرام باندھا۔","f2":"بیداء کے لفظی معنی تو بے آب و گیاہ میدان ہیں مگر یہاں ایک مخصوص مقام مراد ہے جو ذوالحلیفہ کی وادی سے نکلتے ہی آجاتا ہے۔ یہ اونچی جگہ ہے، اسی لیے اسے بعض روایات میں ٹیلہ اور بعض میں پہاڑ کہا گیا ہے۔ علاوہ ازیں یہ روایت بھی ضعیف ہے۔"}],[2663,"اسماء بنت عمیس رضی اللہ عنہا سے روایت ہے کہ انہوں نے محمد بن ابی بکر صدیق کو بیداء میں جنا تو ابوبکر رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے اس بات کا ذکر کیا تو آپ نے فرمایا: \"ان سے کہو کہ غسل کر لیں پھر لبیک پکاریں\"۔\n§وضاحت\n۱؎: یہ غسل نظافت کے لیے ہے طہارت کے لیے نہیں۔","الألباني: صحيح",{"u2":"حضرت اسماء بن عمی رضی اللہ عنہا سے روایت ہے کہ مقام بیداء میں انھوں نے محمد بن ابوبکر صدیق کو جنا۔ حضرت ابوبکر رضی اللہ عنہ نے اس بات کا تذکرہ رسول اللہ صلی اللہ علیہ وسلم سے کیا تو آپ نے فرمایا: ’’اسماء سے کہو وہ غسل کرے اور احرام باندھ لے۔‘‘","f2":"(۱) حضرت اسماء بنت عمیس رضی اللہ عنہا حضرت ابوبکر رضی اللہ عنہ کی زوجہ محترمہ تھیں۔ یہ واقعہ سفر حجۃ الوادع کا ہے۔ احرام سے قبل اسی وادی میں محمد بن ابوبکر پیدا ہوئے۔ (۲) حضرت اسمائ رضی اللہ عنہا کو غسل کا حکم طہارت کے لیے نہیں تھا کیونکہ یہ تو نفاس کا وقت تھا بلکہ یہ غسل احرام کے لیے تھا۔ معلوم ہوا غسل احرام کی سنت ہے ورنہ رسول اللہ صلی اللہ علیہ وسلم نفاس والی عورت کو غسل کا حکم نہ دیتے، البتہ یہ واجب نہیں۔ غسل کی جگہ وضو بھی کفایت کر سکتا ہے مگر افضل غسل ہی ہے۔"}],[2664,"ابوبکر صدیق رضی اللہ عنہ سے روایت ہے کہ حجۃ الوداع کے موقع پر وہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ حج کے لیے نکلے اور ان کے ساتھ ان کی اہلیہ اسماء بنت عمیس خثعمیہ رضی اللہ عنہا بھی تھیں۔ جب وہ لوگ ذوالحلیفہ میں پہنچے تو وہاں اسماء نے محمد بن ابوبکر کو جنا۔ تو ابوبکر رضی اللہ عنہ نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے، اور آپ کو اس بات کی خبر دی، تو انہیں رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا کہ وہ اسے حکم دیں کہ وہ غسل کر لیں پھر حج کا احرام باندھ لیں، اور وہ سب کام کریں جو دوسرے حاجی کرتے ہیں سوائے اس کے کہ وہ بیت اللہ کا طواف نہ کریں۔","الألباني: صحيح",{"u2":"حضرت ابوبکر رضی اللہ عنہ سے روایت ہے کہ وہ حجۃ الوداع کے موقع پر رسول اللہ صلی اللہ علیہ وسلم کے ساتھ حج کے لیے نکلے۔ ان کے ساتھ ان کی بیوی اسماء بنت عمیس رضی اللہ عنہا بھی تھیں جن کا تعلق خشعم قبیلے سے تھا۔ جب وہ ذوالحلیفہ میں تھے تو اسماء نے محمد بن ابوبکر کو جنم دیا۔ (یہ دیکھ کر) ابوبکر نبی صلی اللہ علیہ وسلم کے پاس آئے اور صورت حال سے مطلع کیا۔ رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا کہ اسماء سے کہو، وہ غسل کرے، پھر حج کا احرام باندھ لے اور جو کچھ لوگ کریں، وہ بھی کرتی رہے مگر بیت اللہ کا طواف نہ کرے۔","f2":"(۱) ذوالحلیفہ اور بیداء تقریباً ایک ہی مقام ہے، لہٰذا اس روایت میں پیدائش کا مقام بیداء کے بجائے ذوالحلیفہ بتایا گیا ہے۔ مجمع بڑا ہو تو وہ ایک مقام پر پورا بھی نہیں آتا۔ قریبی جگہ میں بھی پڑاؤ ڈال لیا جاتا ہے۔ اصل پڑاؤ ذوالحلیفہ ہی میں تھا۔ (۲) حیض اور نفاس والی عورت حج کے تمام افعال بجا لا سکتی ہے مگر طواف نہیں کر سکتی۔ البتہ صفا مروہ کی سعی کی بابت اختلاف ہے۔ بعض علماء سعی کے جواز کا فتوی دیتے ہیں، تاہم احوط اور افضل یہی ہے کہ حائضہ اور نفاس والی عورت صفا مروہ کی سعی نہ کرے۔ واللہ اعلم"}],[2665,"عبداللہ بن عباس اور مسور بن مخرمہ رضی اللہ عنہم سے روایت ہے کہ ان دونوں کے درمیان مقام ابواء میں (محرم کے سر دھونے اور نہ دھونے کے بارے میں)اختلاف ہو گیا۔ ابن عباس رضی اللہ عنہما نے کہا: محرم اپنا سر دھوئے گا اور مسور نے کہا: نہیں دھوئے گا۔ تو ابن عباس رضی اللہ عنہما نے مجھے ابوایوب انصاری رضی اللہ عنہ کے پاس بھیجا کہ میں ان سے اس بارے میں سوال کروں، چنانچہ میں گیا تو وہ مجھے کنویں کی دونوں لکڑیوں کے درمیان غسل کرتے ہوئے ملے اور وہ کپڑے سے پردہ کئے ہوئے تھے، میں نے انہیں سلام کیا اور کہا: مجھے عبداللہ بن عباس رضی اللہ عنہما نے آپ کے پاس بھیجا ہے کہ میں آپ سے سوال کروں کہ رسول اللہ صلی اللہ علیہ وسلم حالت احرام میں اپنا سر کس طرح دھوتے تھے ۱؎۔ (یہ سن کر) ابوایوب رضی اللہ عنہ نے اپنا ہاتھ کپڑے پر رکھا، اور اسے جھکایا یہاں تک کہ ان کا سر دکھائی دینے لگا، پھر ایک شخص سے جو پانی ڈالتا تھا کہا: سر پر پانی ڈالو، پھر انہوں نے اپنے دونوں ہاتھوں سے اپنے سر کو حرکت دی، (صورت یہ رہی کہ) کہ دونوں ہاتھ کو آگے لائے اور پیچھے لے گئے، اور کہا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو ایسا ہی کرتے دیکھا ہے۔\n§وضاحت\n۱؎: یہاں ایک اشکال یہ ہے کہ دونوں میں اختلاف غسل کرنے یا نہ کرنے میں تھا نہ کہ کیفیت کے بارے میں پھر انہوں نے ابوایوب رضی اللہ عنہ سے جا کر غسل کی کیفیت کے بارے کیوں سوال کیا ؟ اس اشکال کا جواب یہ ہے کہ ان دونوں نے انہیں دونوں باتیں پوچھنے کے لیے بھیجا تھا لیکن وہاں پہنچ کر جب انہوں نے خود انہی کو حالت احرام میں غسل کرتے دیکھا تو اس سے انہوں نے اس کے جواز کو خودبخود جان لیا اب بچا مسئلہ صرف کیفیت کا تو اس بارے میں انہوں نے پوچھ لیا۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن حنین سے مروی ہے کہ حضرت عبداللہ بن عباس رضی اللہ عنہ اور حضرت مسور بن مخرمہ رضی اللہ عنہ کا ابواء کے مقام پر اختلاف ہوگیا۔ حضرت ابن عباس رضی اللہ عنہ نے فرمایا: ’’اپنا سر دھو سکتا ہے۔ اور حضرت مسور رضی اللہ عنہ نے فرمایا: وہ سر نہیں دھو سکتا۔ مجھے حضرت ابن عباس رضی اللہ عنہ نے حضرت ابو ایوب انصاری رضی اللہ عنہ کے پاس بھیجا کہ ان سے اس بارے میں پوچھوں۔ (میں آیا) تو میں نے انھیں کنویں کی دو لکڑیوں کے درمیان غسل کرتے پایا۔ انھوں نے ایک کپڑے کے ساتھ پردہ کیا ہوا تھا۔ میں نے انھیں سلام کیا اور کہا: مجھے حضرت عبداللہ بن عباس رضی اللہ عنہ نے آپ کے پاس بھیجا ہے کہ آپ سے پوچھوں کہ رسول اللہ صلی اللہ علیہ وسلم احرام کی حالت میں اپنا سر کیسے دھوتے تھے؟ حضرت ابو ایوب نے کپڑے پر ہاتھ رکھ کر اسے نیچے کیا حتی کہ ان کا سر نظر آنے لگا، پھر اس شخص سے کہنے لگے: جو ان کے سر پر پانی بہا رہا تھا: پانی بہاؤ، پھر انھوں نے اپنے سر کو اپنے دونوں ہاتھ سے حرکت دی، اپنے دونوں ہاتھوں کو آگے لائے اور پیچھے لے گئے۔ اور فرمایا: میں نے اللہ کے رسول صلی اللہ علیہ وسلم کو ایسے کرتے دیکھا ہے۔","f2":"(۱) محرم احتلام کے علاوہ بھی حسب منشا غسل کر سکتا ہے جیسا کہ مذکورہ حدیث میں ہے، نیز سر کو اچھی طرح دھویا اور ملا بھی جا سکتا ہے۔ بعض لوگ بال ٹوٹنے یا اترنے کے خدشے سے غسل سے روکتے ہیں اور اگر نہاتے ہوئے کوئی بال ٹوٹ جائے تو دم لازم کرتے ہیں۔ یہ محض احتیاط ہے جو دلیل سے عاری ہے۔ نبی اکرم صلی اللہ علیہ وسلم نے احرام کی حالت میں سینگی بھی لگوائی ہے، اس کی وجہ سے یقینا بال بھی کاٹنے پڑتے ہیں لیکن آپ صلی اللہ علیہ وسلم سے اس موقع پر دم دینا ثابت نہیں، اگر دیا ہوتا تو دیگر مناسک کی طرح جم غفیر میں سے کوئی نہ کوئی اسے ضرور نقل کرتا۔ بنا بریں عدم نقل عدم ثبوت کی دلیل ہے، تاہم اگر بلا وجہ قصداً کچھ بال کاٹے یا سارا سر ہی مونڈھ لے تو پھر دم دینا حدیث سے ثابت ہے۔ (۲) ’’سلام کیا۔‘‘ وہ ننگے نہیں نہا رہے تھے بلکہ تہبند باندھا ہوا تھا۔ پردے والا کپڑا اس کے علاوہ تھا۔ (۳) اختلاف کے وقت نص کی طرف رجوع کرنا چاہیے، اپنا قیاس اور اجتہاد چھوڑ دینا چاہیے۔ (۴) خبر واحد حجت ہے، صحابہ کرام رضی اللہ عنہم میں اسے قبول کرنا اور اس پر عمل کرنا عام تھا۔"}],[2666,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا ہے کہ محرم زعفران اور ورس میں رنگے ہوئے کپڑے پہننے۔\n§وضاحت\n۱؎: ورس ایک خوشبودار پیلی گھاس ہے جس سے کپڑے رنگے جاتے تھے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا کہ محرم زعفران یا درس سے رنگے ہوئے کپڑے پہنے۔","f2":"محرم کے لیے خوشبو کا استعمال ممنوع ہے، زعفران بھی خوشبو ہے، لہٰذا اس سے رنگے ہوئے کپڑے بھی ممنوع ہیں لیکن یہ حکم بحالت احرام ہے۔ احرام سے قبل خوشبو لگائی جا سکتی ہے۔ بعد ازاں اس کے اثرات ختم نہ بھی ہوں تو کوئی حرج نہیں۔ ورس ایک خوشبو دار گھاس ہے۔ اس سے معلوم ہوا کہ محرم رنگین احرام پہن سکتا ہے۔ ویسے احرام کے لیے سادہ اور سفید کپڑے ہی زیادہ مناسب ہیں، البتہ عورت ہر رنگ کے کپڑے پہن سکتی ہے زعفران اور ورس سے نہ رنگے ہوں"}],[2667,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سے پوچھا گیا کہ محرم کون سے کپڑے پہنے؟ آپ نے فرمایا: \"محرم قمیص (کرتا) ٹوپی، پائجامہ، عمامہ (پگڑی) اور ورس اور زعفران لگا کپڑا نہ پہنے ۱؎، اور موزے نہ پہنے اور اگر جوتے میسر نہ ہوں تو چاہیئے کہ دونوں موزوں کو کاٹ ڈالے یہاں تک کہ انہیں ٹخنوں سے نیچے کر لے\" ۲؎۔\n§وضاحت\n۱؎: اس بات پر اجماع ہے کہ حالت احرام میں عورت کے لیے وہ تمام کپڑے پہننے جائز ہیں جن کا اس حدیث میں ذکر کیا گیا ہے صرف ورس اور زعفران لگے ہوئے کپڑے نہ پہنے، نیز اس بات پر بھی اجماع ہے کہ حالت احرام میں مرد کے لیے حدیث میں مذکور یہ کپڑے پہننے جائز نہیں ہیں قمیص اور سراویل میں تمام سلے ہوئے کپڑے داخل ہیں اسی طرح عمامہ اور خفین سے ہر وہ چیز مراد ہے جو سر اور قدم کو ڈھانپ لے، البتہ پانی میں سر کو ڈبونے یا ہاتھ یا چھتری سے سر کو چھپانے میں کوئی حرج نہیں۔ ۲؎: جمہور نے اس حدیث سے استدلال کرتے ہوئے موزوں کے کاٹنے کی شرط لگائی ہے لیکن امام احمد نے بغیر کاٹے موزہ پہننے کو جائز قرار دیا ہے کیونکہ ابن عباس کی روایت «من لم یجدنعلین فلیلبس خفین» جو بخاری میں آئی ہے مطلق ہے لیکن اس کا جواب یہ دیا گیا ہے کہ یہاں مطلق کو مقید پر محمول کیا جائے گا، حنابلہ نے اس روایت کے کئی جواب دیئے ہیں جن میں ایک یہ ہے کہ ابن عمر رضی اللہ عنہما کی یہ روایت منسوخ ہے کیونکہ یہ احرام سے قبل مدینہ کا واقعہ ہے اور ابن عباس رضی اللہ عنہما کی روایت عرفات کی ہے اس کا جواب یہ دیا گیا ہے کہ ابن عمر رضی اللہ عنہما کی روایت حجت کے اعتبار سے ابن عباس رضی اللہ عنہما کی روایت سے بڑھی ہوئی ہے، کیونکہ وہ ایسی سند سے مروی ہے جو اصح الاسانید ہے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سے پوچھا گیا: محرم کون سے کپڑے پہن سکتا ہے؟ آپ نے فرمایا: ’۔وہ قمیص، برانڈی (ٹوپی دار کرتا)، شلوار، پگڑی، ایسا کپڑا جسے ورس یا زعفران لگا ہو اور موزے نہیں پہن سکتا مگر یہ کہ اس کے پاس جوتے نہ ہوںتو وہ موزے پہن لے مگر انھیں ٹخنوں سے نیچے کاٹ (کر جوتوں کی طرح بنا) لے۔‘‘","f2":"(۱) محرم کے لیے ضابطہ یہ ہے کہ سر نہ ڈھانپے اور سلا ہوا کپڑا نہ پہنے، خوشبو والا کپڑا بھی نہ پہنے۔ باقی کپڑے پہن سکتا ہے۔ (۲) ’’برانڈی‘‘ وہ کوٹ یا کرتا جس کے ساتھ ٹوپی بھی ہوتی ہے۔ (۳) ’’موزے‘‘ یعنی چمڑے کے موزے۔ صحیح قول کے مطابق موزوں کا پہننا جائز ہے، خواہ وہ کٹے ہوئے نہ بھی ہوں۔ دراصل احرام کی حالت میں موزے پہننے کی بابت دو قسم کی روایات آتی ہیں: ایک یہ کہ انھیں کاٹ کر پہنا جائے اور دوسری یہ کہ موزوں کو ان کی اصل حالت میں پہنا جائے، البتہ جس حدیث میں موزے کاٹنے کا حکم ہے وہ ابتدائے احرام کا ہے جبکہ دوسرا حکم عرفے کے دن کا ہے۔ اس سے یہ بات ثابت ہوتی ہے کہ کاٹنے کا حکم منسوخ ہے۔ واللہ اعلم! دیکھیے: (صحیح البخاری، جزاء الصید، حدیث: ۱۸۴۱، وصحیح مسلم، الحجد، حدیث: ۱۱۷۸) (۴) سوال تھا کیا پہنے؟ جواب ملا، فلاں فلاں چیز نہ پہنے۔ کیونکہ یہ پہنی جانے والی چیزیں قلیل ہیں اور پہنی جانے والی کثیر، لہٰذا اختصار کی خاطر ایسے جواب دیا۔ یہ بھی بلاغت کی ایک بہترین صورت ہے کہ جواب کے ساتھ ساتھ سوال کی تصحیح کر دی جائے۔ (۵) حدیث میں مذکور لباس کی ممانعت اور دو سادہ ان سلے کپڑے پہننے میں حکمت یہ ہے کہ آدمی خشوع وتذلل کی صفت سے متصف اور رفاہیت سے دور رہے تاکہ اسے یاد دہانی رہے کہ وہ محرم ہے، اس لیے وہ کثرت اذکار اور عبادت کی طرف متوجہ رہے اور ممنوعات کے ارتکاب سے باز رہے، نیز اس سے مساوات اور اتحاد کا درس ملے۔"}],[2668,"یعلی بن امیہ رضی اللہ عنہ کہتے ہیں: کاش میں رسول اللہ صلی اللہ علیہ وسلم پر وحی نازل ہوتے ہوئے دیکھتا، پھر اتفاق ایسا ہوا کہ ہم جعرانہ میں تھے، اور نبی اکرم صلی اللہ علیہ وسلم اپنے خیمے میں تھے کہ آپ پر وحی نازل ہونے لگی، تو عمر رضی اللہ عنہ نے مجھے اشارہ کیا کہ آؤ دیکھ لو۔ میں نے اپنا سر خیمہ میں داخل کیا تو کیا دیکھتا ہوں کہ آپ کے پاس ایک شخص آیا ہوا ہے وہ جبہ میں عمرہ کا احرام باندھے ہوئے تھا، اور خوشبو سے لت پت تھا اس نے عرض کیا: اللہ کے رسول! آپ ایسے شخص کے بارے میں کیا فرماتے ہیں جس نے جبہ پہنے ہوئے احرام باندھ رکھا ہے کہ یکایک آپ پر وحی اترنے لگی، اور نبی اکرم صلی اللہ علیہ وسلم خراٹے لینے لگے۔ پھر آپ کی یہ کیفیت جاتی رہی، تو آپ نے فرمایا: \"وہ شخص کہاں ہے جس نے ابھی مجھ سے (مسئلہ) پوچھا تھا\" تو وہ شخص حاضر کیا گیا، آپ نے (اس سے) فرمایا: \"رہا جبہ تو اسے اتار ڈالو، اور رہی خوشبو تو اسے دھو ڈالو پھر نئے سرے سے احرام باندھو۔ ابوعبدالرحمٰن نسائی کہتے ہیں کہ \"نئے سرے سے احرام باندھ\" کا یہ فقرہ نوح بن حبیب کے سوا کسی اور نے روایت کیا ہو یہ میرے علم میں نہیں اور میں اسے محفوظ نہیں سمجھتا، واللہ سبحانہ وتعالی اعلم۔\n§وضاحت\n۱؎: جعرانہ مکہ کے قریب ایک جگہ ہے۔","الألباني: صحيح دون قوله ثم أحدث إحراما فإنه شاذ والمحفوظ دونها",{"u2":"حضرت یعلیٰ بن امیہ رضی اللہ عنہ سے منقول ہے کہ میں نے کہا: کاش! میں رسول اللہ صلی اللہ علیہ وسلم کو نزول وحی کی حالت میں دیکھوں۔ ایک بار ہم (دوران سفر میں) جعرانہ کے مقام پر تھے جبکہ رسول اللہ صلی اللہ علیہ وسلم اپنے خیمے میں تھے کہ آپ پر وحی اترنے لگی۔ حضرت عمر رضی اللہ عنہ نے مجھے اشارہ فرمایا کہ آجاؤ۔ میں نے اپنا سر خیمے میں داخل کیا۔ دراصل ایک آدمی رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا تھا جس نے جبے میں عمرے کا احرام باندھ لیا تھا۔ اس آدمی نے خوشبو بھی لگائی ہوئی تھی۔ اس نے آپ سے پوچھا: اے اللہ کے رسول! آپ اس شخص کے بارے میں کیا فرماتے ہیں جس نے جبے ہی میں احرام باندھ لیا ہو؟ تو آپ پر وحی اترنے لگی۔ نبی صلی اللہ علیہ وسلم اس کی وجہ سے خراٹے لینے لگے۔ کچھ دیر بعد آپ سے یہ حالت دور ہوئی تو آپ نے فرمایا: ’’کہاں ہے وہ شخص جس نے ابھی مجھ سے سوال کیا تھا؟‘‘ اس آدمی کو لایا گیا۔ آپ نے فرمایا: ’’جبہ اتار دے اور خوشبو دھو ڈال، پھر نئے سرے سے احرام باندھ۔‘‘\nابو عبدالرحمن (امام نسائیk) بیان کرتے ہیں کہ [ثُمَّ أَحْدِثْ اِحْرَامًا] ’’پھر نئے سرے سے احرام باندھ۔‘‘ کے الفاظ میرے علم کے مطابق نوح بن حبیب کے علاوہ کسی راوی نے بیان نہیں کیے، اس لیے میں ان الفاظ کو محفوظ نہیں سمجھتا۔ واللہ سبحانہ و تعالیٰ اعلم","f2":"(۱) امام نسائی رحمہ اللہ بیان کرتے ہیں کہ آخری جملہ ’’پھر نئے سرے سے احرام باندھ۔‘‘ درست نہیں۔ باقی راوی یہ جملہ بیان نہیں کرتے، یعنی امام صاحب رحمہ اللہ کے نزدیک یہ اضافہ معلول ہے۔ (۲) صحیح یہ ہے کہ چونکہ وہ ناواقف تھا، اس لیے اسے معذور سمجھا اور کفارہ نہیں ڈالا۔ آج کل بھی اگر کوئی شخص واقعی عدم علم کی بنا پر سلہ ہوا کپڑا پہن لے، یا دوران احرام میں خوشبو لگا لے اور پتا چلنے پر فوراً ازالہ کر دے تو اس پر کوئی کفارہ نہیں ہے۔ جمہور اہل علم کا یہی مذہب ہے اور یہی راجح ہے۔ آخری جملے کا ایک مطلب یہ بھی ہو سکتا ہے کہ اپنے آپ کو محرم ہی سمجھ۔ ورنہ میقات سے آگے جا کر تو احرام باندھنا درست نہیں اور جعرانہ تو کوئی میقات نہیں بلکہ یہاں سے قریب ہی حرم شروع ہوتا ہے۔ (۳) جو شخص بھی بھول کر مذکورہ کاموں میں سے کوئی کام کر لے تو اس کا بھی یہی حکم ہے بشرطیکہ یاد آنے پر وہ فوراً اس کا ازالہ کرے۔ (۴) میقات سے پہلے حج کا لباس پہنا جا سکتا ہے لیکن نیت میقات ہی سے کی جائے گی، لہٰذا افضل یہی ہے کہ میقات ہی سے حج و عمرے کا احرام باندھا جائے الا یہ کہ کوئی مجبوری ہو، مثلاً: ہوائی جہاز کا سفر۔"}],[2669,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: محرم کون سے کپڑے پہنے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم نہ قمیص پہنو نہ عمامے نہ پائجامے، نہ ٹوپیاں اور نہ موزے البتہ اگر کسی کو جوتے نہ مل پائیں تو موزے پہن لے، اور انہیں کاٹ کر ٹخنوں سے نیچے سے کر لے، اور نہ کوئی ایسا کپڑا پہنو جس میں زعفران یا ورس لگی ہو\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہ سے منقول ہے کہ ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: محرم کون سے کپڑے پہن سکتا ہے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’قمیص، پگڑی، پاجامہ (شلوار) ٹوپی دار کرتا (برانڈی) اور موزے نہ پہنے، ہاں اگر اس کے پاس جوتے نہ ہوں تو چمڑے کے موزے پہن سکتا ہے مگر انھیں ٹخنوں کے نیچے سے کاٹ لے۔ اور ایسے کپڑے نہ پہنو جنھیں زعفران یا ورس لگی ہوئی ہو۔‘‘\nحضرت عبداللہ بن عمر رضی اللہ عنہ سے پوچھا: محرم کون سے کپڑے پہن سکتا ہے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’۔قمیص، پگڑی، شلوار (پاجامہ وغیرہ)، ٹوپی دار کرتا اور موزے نہ پہنو، ہاں اگر کسی کے پاس جوتے نہ ہوں تو وہ موزوں کو ٹخنوں سے نیچے کاٹ کر پہن لے۔ اور کوئی ایسا کپڑا نہ پہنو جسے زعفران یا ورس لگی ہو۔‘‘","f2":"جمہور اہل علم کے نزدیک محرم کے لیے قد اور اعضاء کے مطابق پیمائش کر کے سلے ہوئے کپڑے پہننا منع ہے۔ یاد رہے کہ مذکورہ کپڑے منع ہیں، خواہ سلے ہوئے ہوں یا ان سلے۔ اور ان کے علاوہ چادریں جائز ہیں، خواہ سلی ہوئی ہوں یا ان سلی۔ موزے کاٹنے والا حکم منسوخ ہے۔ (مزید تفصیل کے لیے دیکھیے، حدیث: ۲۶۶۷، ۲۶۶۸)"}],[2670,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ ایک شخص نے عرض کیا: اللہ کے رسول! جب ہم احرام باندھ لیں تو کون سے کپڑے پہنیں؟ آپ نے فرمایا: \"نہ قمیص پہنو، (عمرو بن علی نے دوسری بار قمیص کے بجائے جمع کے صیغے کے ساتھ قمص کہا) نہ عمامے، نہ پائجامے اور نہ موزے، البتہ اگر کسی کے پاس جوتے نہ ہوں تو موزوں کو کاٹ کر ٹخنوں سے نیچے کر لے، اور نہ ایسا کپڑا جس میں ورس اور زعفران لگی ہو\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے مروی ہے کہ ایک آدمی نے کہا: اے اللہ کے رسول! جب ہم احرام باندھیں تو ہم کون سے کپڑے پہنیں؟ اپ نے فرمایا: ’’قمیص، پگڑی، شلوار اور موزے نہ پہنو مگر یہ کہ کسی کے پاس جوتے نہ ہوں تو وہ موزوں کو ٹخنوں سے نیچے کاٹ لے۔ اور ایسے کپڑے نہ پہنو جن کو ورس یا زعفران لگی ہوئی ہو۔‘‘"}],[2671,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو خطبہ دیتے ہوئے سنا آپ فرما رہے تھے: \"پائجامہ اس شخص کے لیے ہے جسے تہبند میسر نہ ہو، اور موزہ اس شخص کے لیے ہے جسے جوتے میسر نہ ہوں\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ میں نے نبی صلی اللہ علیہ وسلم کو خطبہ دیتے سنا، آپ فرما رہے تھے: ’’جس شخص کے پاس تہبند نہ ہو، وہ شلوار پہن سکتا ہے اور جس کے پاس جوتے نہ ہوں، وہ موزے پہن سکتا ہے۔","f2":"یہ حدیث، حدیث: ۲۶۶۸ میں موزے کاٹنے کے حکم کی ناسخ ہے۔ امام احمد بن حنبلk کا بھی یہی موقف ہے کہ اب موزے کاٹے بغیر ہی پہنے جائیں گے۔ جمہور کاٹ کر پہننے کے قائل ہیں۔ وہ اس مطلق حدیث کو ابن عمر رضی اللہ عنہ کی مقید حدیث پر محمول کرتے ہیں۔ لیکن مطلق کو مقید پر محمول کرنا یہاں محل نظر ہے کیونکہ حدیث کا مخرج ایک نہیں بلکہ مختلف ہے۔ پہلی حدیث ابن عمر رضی اللہ عنہ کی ہے اور یہ ابن عباس رضی اللہ عنہ کی۔ یہ اصول اس وقت قابل عمل ہے جب مخرج (حدیث بیان کرنے والا صحابی) ایک ہو۔ لیکن اس کے طرق واسانید مختلف ہوں۔ امام ابن جوزیk فرماتے ہیں کہ قطع کا حکم اباحت پر محمول کیا جائے گا، لہٰذا نہ کاٹنا بھی جائز ہے۔ پہلا موقف راجح معلوم ہوتا ہے جیسا کہ پیچھے گزر چکا۔ واللہ اعلم"}],[2672,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا کہ جو شخص (احرام کے موقع پر) تہبند نہ پائے تو وہ پائجامہ پہن لے اور جو جوتے نہ پائے تو وہ موزے پہن لے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ’’جس شخص (محرم) کے پاس تہبند نہ ہو، وہ شلوار پہن سکتا ہے اور جس شخص کے پاس جوتے نہ ہوں، وہ موزے پہن سکتا ہے۔‘‘"}],[2673,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ ایک شخص کھڑا ہوا اور اس نے عرض کیا: اللہ کے رسول! آپ ہمیں احرام میں کس طرح کے کپڑے پہننے کا حکم دیتے ہیں؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"نہ قمیص پہنو، نہ پائجامے، نہ عمامہ، نہ ٹوپیاں سوائے اس کے کہ کسی کے پاس جوتے موجود نہ ہوں تو وہ ایسے موزے پہنے جو ٹخنوں سے نیچے ہوں، اور کوئی ایسا کپڑا نہ پہنو جس میں زعفران یا ورس لگے ہوں اور محرم عورت نہ نقاب پہنے اور نہ ہی دستانے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ بیان کرتے ہیں کہ ایک آدمی کھڑا ہو کر کہنے لگا: اے اللہ کے رسول! احرام کی حالت میں آپ ہمیں کن کپڑوں کے پہننے کا حکم دیتے ہیں؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’قمیص، شلوار، پگڑی، برانڈی (اوور کوٹ اور ٹوپی دار کرتا) اور موزے نہ پہنو مگر یہ کہ کسی کے پاس جوتے نہ ہوں تو وہ موزے ٹخنوں کے نیچے سے کاٹ کر پہن سکتا ہے۔ اور کوئی ایسا کپڑا نہ پہنو جس کو زعفران یا ورس لگی ہو، نیز محرم عورت نہ نقان باندھے اور نہ دستانے پہنے۔‘‘","f2":"(۱) ’’نقاب نہ باندھے‘‘ اس کا مطلب یہ ہے کہ عورت اپنا چہرہ ننگا رکھے، بلکہ یہ ایک مخصوص قسم کا نقاب تھا جو اس زمانے میں رائج تھا، اس سے فوری طور پر چہرے کا پردہ کرنا مشکل ہوتا تھا، اس لیے مخصوص نقاب سے روک دیا گیا تاکہ مردوں کے سامنے آتے ہی فوراً پردہ کرنا آسان رہے، چنانچہ حضرت عائشہ رضی اللہ عنہا بیان فرماتی ہیں کہ مرد سامنے آتے تو ہم فوراً چہرہ ڈھانپ لیتیں۔ اب اس نقاب کا رواج بھی ختم ہوگیا ہے۔ علاوہ ازیں اب مردوں کا ہجوم ہر وقت اور ہر جگہ رہتا ہے، اس لیے اب حجاب کا اہتمام ہر وقت ہی کرنا چاہیے، سوائے ان جگہوں کے جہاں مرد نہ ہوں۔ بعض لوگ عورت کے لیے چہرہ ننگا رکھنے پر سنن دارقطنی کی اس روایت سے استدلال کرتے ہیں کہ ’’عورت کا احرام اس کے چہرے میں اور مرد کا احرام اس کے سر میں ہے۔‘‘ اسے سنن دارقطنی میں مرفوعاً بیان کیا گیا ہے لیکن اس کا مرفوع ہونا ثابت نہیں ہے۔ یہ حضرت ابن عمر رضی اللہ عنہ کا قول، یعنی موقوف روایت ہے۔ دیکھیے: (سنن الدارقطنی: ۲/ ۵۵۴۔ بتحقیق الشیخ عادل والشیخ علی محمد، دارالمعرفۃ، بیروت) اس لیے اس سے استدلال صحیح نہیں ہے۔ بشرطِ صحت اس موقوف روایت کا بھی وہی مفہوم لیا جائے گا جس کی وضاحت ہم نے کی ہے۔ (۲) ’’دستانے نہ پہنے‘‘ مقصد یہ ہے کہ وہ ہاتھ ننگے رکھے تاکہ دوران حج و عمرہ میں کوئی تنگی نہ ہو۔ معلوم ہوا اس دور میں خواتین پردے کے لیے دستانے بھی استعمال کرتی تھیں۔ مشہور تو یہی ہے کہ دستانے ہاتھوں کو سردی، گرمی یا پانی سے بچانے کے لیے ہوتے ہیں مگر بعض اہل لغت نے اس سے زیور بھی مراد لیا ہے جس کے ساتھ ہاتھ چھپ جاتے ہیں۔ خیر! احرام میں ہاتھ ننگے رہنے چاہئیں۔"}],[2674,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: محرم کون سے کپڑے پہنے؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"نہ قمیص پہنو، نہ عمامہ، نہ پائجامے پہنو، نہ ٹوپیاں، اور نہ موزے پہنو، البتہ اگر کسی کو جوتے میسر نہ ہوں تو موزے پہن لے، اور انہیں کاٹ کر ٹخنوں سے نیچے کر لے، اور نہ کوئی ایسا کپڑا پہنو جس میں زعفران یا ورس لگی ہو\"۔","الألباني: صحيح"],[2675,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم سے سوال کیا: جب ہم احرام باندھیں تو کون سے کپڑے پہنیں؟ آپ نے فرمایا: نہ قمیص پہنو، نہ پائجامے، نہ عمامے، نہ ٹوپیاں، نہ موزے، البتہ کسی کے پاس جوتے نہ ہوں تو وہ ایسے موزے پہنے جو ٹخنوں سے نیچے ہو، اور نہ کوئی ایسا کپڑا پہنو جس میں ورس زعفران لگے ہوں۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے کہ ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا کہ جب ہم احرام باندھیں تو کون سے کپڑے پہنیں؟ آپ نے فرمایا: ’’قمیص، شلوار، پگڑی، برانڈی (ٹوپی دار کرتا) اور موزے نہ پہنو مگر یہ کہ کسی کے پاس جوتے نہ ہوں تو ٹخنوں سے نیچے موزے پہن لے (یعنی اوپر سے کاٹ دے) اور کوئی ایسا کپڑا نہ پہنو جسے ورس یا زعفران لگی ہو۔‘‘","f2":"تفصیل کےلیے دیکھیے حدیث نمبر 2668۔"}],[2676,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ ایک شخص نے نبی اکرم صلی اللہ علیہ وسلم کو آواز دی اور پوچھا: ہم جب محرم ہوں تو کیا پہنیں؟ آپ نے فرمایا \"نہ قمیص پہنو، نہ عمامہ (پگڑی)، نہ پائجامہ، نہ ٹوپی اور نہ موزے البتہ جس کو جوتے میسر نہ ہو تو وہ موزے ٹخنوں سے نیچے پہنے اور اسے نیچے کر لے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے مروی ہے کہ ایک آدمی نے بلند آواز سے نبی صلی اللہ علیہ وسلم کو پکارا اور کہا: جب ہم احرام باندھیں تو کون سے کپڑے پہنیں؟ آپ نے فرمایا: ’’قمیص، پگڑی، شلوار، برانڈی اور موزے نہ پہن، ہاں اگر تمھیں جوتے نہ ملیں تو موزوں کو ٹخنوں سے نیچے نیچے پہن لو۔ (یعنی اوپر سے کاٹ دو)۔‘‘"}],[2677,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ ایک شخص نے نبی اکرم صلی اللہ علیہ وسلم کو آواز دی اور اس نے پوچھا: جب ہم محرم ہوں تو کیا پہنیں؟ تو آپ نے فرمایا: \"نہ قمیص پہنو، نہ عمامے (پگڑیاں)، نہ ٹوپیاں، نہ پائجامے، نہ موزے البتہ اگر جوتے نہ ہوں تو ایسے موزے پہنو جو ٹخنوں سے نیچے ہوں، اور نہ ورس اور زعفران لگے ہوئے کپڑے پہنو\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ فرماتے ہیں کہ ایک آدمی نے نبی صلی اللہ علیہ وسلم کو بلند آواز سے پکارا اور کہا: جب ہم احرام باندھیں تو کیا پہنیں؟ آپ نے فرمایا: ’’قمیص، پگڑی، برانڈی (ٹوپی دار کرتا)، شلوار (پاجامہ وغیرہ) اور موزے نہ پہنو الا یہ کہ جوتے نہ ہوں۔ ایسی صورت میں ٹخنوں سے نیچے موزے پہنے جا سکتے ہیں۔ اور کوئی ایسا کپڑا بھی نہ پہنو جو ورس یا زعفران سے رنگا ہوا ہو۔‘‘","f2":"یہ پابندی صرف مرد کے لیے ہے کیونکہ دوران احرام مرد کے لیے سر ننگا رکھنا ضروری ہے۔ پگڑی کے تحت ٹوپی، ہیٹ اور رومال وغیرہ بھی آجائیں گے۔"}],[2678,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم کو فرماتے سنا ہے: \"احرام میں نہ قمیص پہنو، نہ پائجامے، نہ عمامے (پگڑیاں) نہ ٹوپیاں، نہ موزے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے مروی ہے کہ میں نے نبی صلی اللہ علیہ وسلم کو فرماتے سنا: ’’تم احرام کی حالت میں قمیص، شلوار، پگڑی، برانڈی اور موزے نہ پہنو۔‘‘","f2":"یہ پابندی بھی صرف مردوں کے لیے ہے، نیز موزوں کے تحت جرابیں وغیرہ بھی داخل ہیں۔"}],[2679,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم فرماتے سنا: \"جب کسی کو تہبند نہ ملے تو پائجامہ پہن لے، اور جب جوتیاں نہ پائے تو موزے پہن لے، اور انہیں کاٹ کر ٹخنوں سے نیچے کر لے\"۔","الألباني: صحيح دون وليقطعهما فإنه شاذ",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے مروی ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے سنا: ’’جب کوئی شخص (محرم) تہبند نہ پائے تو شلوار پہن سکتا ہے اور جب جوتے نہ پائے تو موزے پہن سکتا ہے لیکن وہ انھیں ٹخنوں کے نیچے سے کاٹ لے۔‘‘"}],[2680,"عبداللہ بن عمر رضی اللہ عنہما نبی اکرم صلی اللہ علیہ وسلم سے روایت کرتے ہیں آپ نے فرمایا: \"جب محرم جوتے نہ پائے تو موزے پہن لے، اور انہیں کاٹ کر ٹخنوں سے نیچے کر لے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ’۔جب محرم کے پاس جوتے نہ ہوں تو وہ موزے پہن لے مگر انھیں ٹخنوں کے نیچے سے کاٹ لے۔‘‘","f2":"تفصیل کے لیے دیکھیے، حدیث: ۲۶۷۲۔"}],[2681,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ ایک شخص کھڑا ہوا اور اس نے عرض کیا: اللہ کے رسول! احرام میں آپ ہمیں کون سے کپڑے پہننے کا حکم دیتے ہیں؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"نہ قمیص پہنو، نہ پائجامے، نہ موزے، البتہ اگر کسی کے پاس جوتے نہ ہوں تو وہ ایسے موزے پہن لے جو ٹخنوں سے نیچے سے ہوں اور کوئی ایسا کپڑا نہ پہنے جس میں زعفران یا ورس لگا ہو، اور محرمہ عورت نہ نقاب پہنے، اور نہ دستانے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے منقول ہے کہ ایک آدمی کھڑا ہو کر کہنے لگا: اے اللہ کے رسول! آپ ہمیں احرام کی حالت میں کس قسم کے کپڑے پہننے کا حکم دیتے ہیں؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم قمیص، شلوار اور موزے نہ پہنو مگر کسی آدمی کے پاس جوتے نہ ہوں تو وہ ٹخنوں سے نیچے موزے پہن لے۔ (اور ٹخنوں سے اوپر والا حصہ کاٹ دے)۔ اور کوئی ایسا کپڑا نہ پہنے جسے زعفران یا ورس لگی ہو۔ محرم عورت نقاب نہ باندھے اور دستانے بھی نہ پہنے۔‘‘","f2":"احناف نے دستانے نہ پہننے کو مستحب کہا ہے مگر اس کی تائید دلائل سے نہیں ہوتی۔ نقلاً، نہ عقلاً۔ واللہ اعلم (تفصیل کے لیے دیکھیے فوائد حدیث: ۲۶۷۴)"}],[2682,"ام المؤمنین حفصہ رضی اللہ عنہا کہتی ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم سے عرض کیا: اللہ کے رسول! کیا بات ہے لوگوں نے احرام کھول دیا ہے اور آپ نے اپنے عمرہ کا احرام نہیں کھولا؟ آپ نے فرمایا: \"میں نے اپنے سر کی تلبید ۱؎، اور اپنے ہدی کی تقلید ۲؎ کر رکھی ہے، تو میں احرام نہیں کھولوں گا جب تک کہ حج سے فارغ نہ ہو جاؤں\"۔\n§وضاحت\n۱؎: تلبید: بالوں کو گوند وغیرہ سے جما لینے کو کہتے ہیں تاکہ وہ بکھریں نہیں اور گرد و غبار سے محفوظ رہیں۔ ۲؎: قربانی کے جانور کے گلے میں قلادہ یا اور کوئی چیز لٹکانے کو تقلید کہتے ہیں تاکہ لوگوں کو یہ معلوم ہو جائے کہ یہ ہدی کا جانور ہے اس کا فائدہ یہ تھا کہ عرب ایسے جانور کو لوٹتے نہیں تھے۔","الألباني: صحيح",{"u2":"ام المومنین حضرت حفصہ رضی اللہ عنہا فرماتی ہیں کہ میں نے نبی صلی اللہ علیہ وسلم سے حلال ہوگئے ہیں مگر آپ عمرہ کر کے حلال نہیں ہوئے؟ آپ نے فرمایا: ’’میں نے اپنے سر کے بالوں کو گوند سے چپکایا ہے اور قربانی کے جانور کو قلادہ (ہار) پہنا دیا ہے، اس لیے میں حلال نہیں ہو سکتا حتیٰ کہ حج سے حلال ہو جاؤں۔‘‘","f2":"(۱) بال بڑے ہوں اور احرام لمبے عرصے کے لیے ہو تو بالوں کو مٹی اور جوؤں سے، نیز زیادہ پراگندگی سے بچانے کے لیے کچھ گوند وغیرہ لگا لینا جس سے بالوں کو تہہ جم جائے تلبید کہلاتا ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے چونکہ عمرے اور حج کا اخٹھا احرام باندھا تھا جو دو ہفتے تک جاری رہنا تھا، اس لیے آپ نے تلبید فرمائی۔ اکثر صحابہ کا احرام صرف عمرے کا تھا، لہٰذا انھیں تلبید کی ضرورت نہ تھی۔ (۲) تلبید، واجب ہے نہ منع، محرم کی مرضی پر موقوف ہے۔ (۳) سوال کے جواب میں آپ نے تلبید اور قربانی کا ذکر فرمایا۔ تلبید تو نشانی تھی احرام کے طویل ہونے کی اور قربانی کا جانور اگر ساتھ ہو تو محرم حلال نہیں ہو سکتا، خواہ عمرے کا احرام ہی ہو جب تک وہ جانور ذبح نہیں ہو جاتا۔ قلادہ انھی جانوروں کو ڈالا جاتا تھا جو ساتھ لے جائے جاتے تھے۔ موقع پر خریدے گئے جانوروں کو قلادے کی ضرورت نہیں تھی۔ (۴) حج سے حلال ہونے سے مراد قربانی کا ذبح کرنا ہے۔ اس سے احرام ختم ہو جاتا ہے، اگرچہ حج کے بعض افعال بعد میں بھی ہوتے رہتے ہیں۔ (۵) یہ حدیث اس بات کی دلیل ہے کہ آپ صلی اللہ علیہ وسلم نے حج قران کیا ہے۔"}],[2683,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ بالوں کو جمائے ہوئے لبیک پکار رہے تھے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو تلبید کی حالت میں لبیک پکارتے دیکھا۔"}],[2684,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو احرام باندھنے کے وقت جس وقت آپ نے احرام باندھنے کا ارادہ کیا اور احرام کھولنے کے وقت اس سے پہلے کہ آپ احرام کھولیں اپنے دونوں ہاتھوں سے خوشبو لگائی۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو اپنے ہاتھوں سے خوشبو لگائی آپ کے احرام کے وقت جب آپ نے احرام کا ارادہ فرمایا اور حلال ہونے (احرام کھولنے) کے وقت (خوشبو لگائی) پہلے اس سے کہ آپ مکمل حلال ہوں۔","f2":"(۱) ’’اپنے ہاتھوں سے۔‘‘ یعنی خوشبو اپنے ہاتھوں میں لگا کر وہ خوشبو آپ کے جسم اطہر پر لگا دی۔ (۲) احرام کے وقت خوشبو لگانے کا مطلب یہ ہے کہ احرام کے غسل کے بعد خوشبو لگائی جائے۔ پھر احرام کا لباس پہن لیا جائے۔ جمہور اہل علم اس کا یہی مفہوم بیان کرتے ہیں، تاہم اہل علم کا ایک گروہ اس بات کا قائل ہے کہ اس کا مطلب یہ ہے کہ احرام کے غسل سے قبل خوشبو لگائی جائے، پھر غسل کر کے احرام باندھا جائے۔ دلائل کی رو سے جمہور اہل علم کا موقف راجح ہے۔ تفصیل کے لیے دیکھیے: (ذخیرۃ العقبیٰ شرح سنن النسائی: ۲۴/۹۰-۹۳) (۳) ’’حلال ہونے کے وقت۔‘‘ یعنی قربانی اور حجامت کے بعد کیونکہ اس وقت احرام ختم ہو جاتا ہے، لہٰذا خوشبو جائز ہے مگر طواف زیارت (جو اسی دن کیا جاتا ہے) کرنے سے پہلے جماع جائز نہیں۔ یہی مطلب ہے ان الفاظ کا: ’’پہلے اس سے کہ مکمل حلال ہوں۔‘‘ کیونکہ مکمل حلال تو طواف زیارت کی ادائیگی کے بعد ہی ہوں گے۔ وضاحت آئندہ حدیث میں ہے۔"}],[2685,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو آپ کے احرام کے لیے اس سے پہلے کہ آپ احرام باندھیں، اور آپ کے احرام کھولنے کے لیے اس سے پہلے کہ آپ طواف کریں خوشبو لگائی۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو خوشبو لگائی آپ کے احرام کے وقت احرام باندھنے سے پہلے اور آپ کے حلال ہونے (احرام کھولنے) کے وقت طواف زیارت کرنے سے پہلے۔"}],[2686,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو آپ کے احرام کے لیے اس سے پہلے کہ آپ احرام باندھیں اور آپ کے احرام کھولنے کے لیے جس وقت آپ نے احرام کھولا خوشبو لگائی۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو آپ کے احرام کے وقت احرام باندھنے سے پہلے اور حلال ہونے کے وقت خوشبو لگائی۔"}],[2687,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو آپ کے احرام کے لیے خوشبو لگائی جس وقت آپ نے احرام باندھا، اور آپ کے احرام کھولنے کے لیے خوشبو لگائی اس کے بعد کہ آپ نے جمرہ عقبہ کی رمی کر لی، اور اس سے پہلے کہ آپ بیت اللہ کا طواف کریں۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو آپ کے احرام کے وقت خوشبو لگائی جب آپ نے احرام باندھا۔ اور جب آپ جمرۂ عقبہ کو رمی کرنے کے بعد حلال ہوئے اس وقت بھی خوشبو لگائی اس سے پہلے کہ آپ بیت اللہ کا طواف فرمائیں۔","f2":"’’جمرۂ عقبہ کو رمی کرنے کے بعد۔‘‘ بلکہ قربانی اور حجامت وغیرہ کے بعد، یعنی طواف زیارت سے پہلے خوشبو لگائی جیسا کہ روایت میں ہے۔ یہ چیزیں چونکہ عقلاً مفہوم ہیں، لہٰذا ان کا ذکر نہیں فرمایا۔"}],[2688,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو آپ کے احرام کھولنے کے لیے خوشبو لگائی، اور آپ کے احرام باندھنے کے لیے خوشبو لگائی جو تمہاری اس خوشبو کے مشابہ نہیں تھی، یعنی یہ خوشبو دیرپا نہ تھی۔","الألباني: صحيح الإسناد",{"u2":"حضرت عائشہ رضی اللہ عنہا سے مروی ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو حلال ہوتے وقت خوشبو لگائی اور احرام باندھنے کے وقت بھی ایسی خوشبو لگائی جو تمھاری اس خوشبو کی طرح نہیں تھی، یعنی جو باقی نہیں رہتی۔","f2":"’’جو باقی نہیں رہتی۔‘‘ یعنی تمھاری خوشبو سے وہ خوشبو بہت بڑھیا اور اعلیٰ تھی۔ تمھاری خوشبو تو باقی نہیں رہتی مگر آپ کی خوشبو تو تادیر باقی رہتی تھی جیسا کہ آئندہ احادیث میں اس بات کا صراحتاً ذکر ہے۔ بعض لوگوں نے اس سے مراد رسول اللہ صلی اللہ علیہ وسلم کی خوشبو لی ہے، یعنی آپ کی خوشبو باقی نہیں رہتی تھی۔ مگر یہ مفہوم آئندہ احادیث کے صریح الفاظ سے متصادم ہے۔ ویسے بھی یہ الفاظ: ’’جو باقی نہیں رہتی۔‘‘ کسی نچلے راوی کے ہیں، حضرت عائشہ رضی اللہ عنہا کے نہیں۔ لفظ تعنی اس پر دلالت کر رہا ہے۔ اور کسی نچلے راوی کے فہم کو صریح مرفوع روایات پر ترجیح نہیں دی جا سکتی۔ واللہ اعلم"}],[2689,"عروہ کہتے ہیں کہ میں نے ام المؤمنین عائشہ رضی اللہ عنہا سے پوچھا کہ آپ نے رسول اللہ صلی اللہ علیہ وسلم کو کون سی خوشبو لگائی تھی؟ تو انہوں نے کہا: سب سے عمدہ خوشبو تھی جو آپ کے احرام باندھتے وقت اور احرام کھولتے وقت میں نے لگائی۔","الألباني: صحيح",{"u2":"حضرت عروہ بیان کرتے ہیں کہ میں نے حضرت عائشہ رضی اللہ عنہا سے پوچھا: آپ نے رسول اللہ صلی اللہ علیہ وسلم کو کون سی خوشبو لگائی تھی؟ انھوں نے فرمایا: میں نے آپ کو سب سے بہترین خوشبو لگائی، احرام باندھنے کے وقت بھی اور حلال ہونے کے وقت بھی۔"}],[2690,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ مجھے جو اچھی سے اچھی خوشبو مل سکتی تھی وہی میں آپ کو احرام باندھتے وقت لگاتی تھی۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے مروی ہے کہ میں رسول اللہ صلی اللہ علیہ وسلم کو آپ کے احرام باندھنے کے وقت بہترین خوشبو لگایا کرتی تھی جو میرے پاس ہوتی تھی۔"}],[2691,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں رسول صلی اللہ علیہ وسلم کو آپ کے احرام باندھتے اور کھولتے وقت اور جس وقت آپ بیت اللہ کی زیارت کا ارادہ کرتے بہترین خوشبو جو میں پا سکتی لگاتی تھی۔","الألباني: صحيح الإسناد",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو آپ کے احرام باندھنے کے وقت اور حلال ہونے کے وقت اور جب آپ بیت اللہ کا طوافِ زیارت کرنے چلے، اپنے پاس موجود بہترین خوشبو لگائی۔"}],[2692,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو احرام باندھنے سے پہلے اور ذی الحجہ کی دسویں تاریخ کو بیت اللہ کا طواف کرنے سے پہلے ایسی خوشبو لگائی جس میں مشک کی آمیزش تھی۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے مروی ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو آپ کے احرام باندھنے سے قبل اور قربانی والے دن طواف بیت اللہ کرنے سے پہلے خوشبو لگائی جس میں کستوری شامل تھی۔","f2":"(۱) ’’قربانی والے دن۔‘‘ سے مراد ذوالحجہ کی دس تاریخ ہے۔ (۲) معلوم ہوا کہ رسول اللہ صلی اللہ علیہ وسلم کو لگائی جانے والی خوشبو انتہائی اچھی تھی جس کی مہک عرصہ دراز تک باقی رہتی تھی۔ کستوری بہترین خوشبو ہے۔ (۳) کستوری پاک ہے۔"}],[2693,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں: گویا کہ میں آپ صلی اللہ علیہ وسلم کے سر میں خوشبو کی چمک دیکھ رہی ہوں، اور آپ احرام باندھے ہوئے ہیں۔ احمد بن نصر نے اپنی روایت میں «وبيص الطيب في رأس رسول اللہ صلى اللہ عليه وسلم» کے بجائے «وبيص طيب المسك في مفرق رسول اللہ صلى اللہ عليه وسلم» (رسول اللہ صلی اللہ علیہ وسلم کی مانگ میں مشک کی خوشبو کی چمک) روایت کی ہے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ مجھے یوں محسوس ہو رہا ہے کہ میں رسول اللہ صلی اللہ علیہ وسلم کے سر مبارک میں خوشبو کی چمک دیکھ رہی ہوں جبکہ آپ حالت احرام میں ہیں۔ (استاد) احمد بن نصر کی حدیث میں ہے: رسول اللہ صلی اللہ علیہ وسلم کی مانگ میں (دوران احرام) کستوری کی خوشبو کی چمک دیکھ رہی ہوں۔"}],[2694,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کی مانگ میں اس حال میں کہ آپ محرم ہوتے خوشبو کی چمک دیکھی جاتی تھی۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ دوران احرام رسول اللہ صلی اللہ علیہ وسلم کی مانگ مبارک میں خوشبو کی چمک صاف نظر آتی تھی۔","f2":"معلوم ہوا کہ رسول اللہ صلی اللہ علیہ وسلم کی خوشبو کے اثرات احرام کے دوران میں بھی محسوس ہوتے تھے اگرچہ وہ احرام سے قبل لگائی جاتی تھی۔ یہی بات صحیح ہے۔ مگر بعض حنفی اور مالکی حضرات نے اسے عوام الناس کے لیے جائز نہیں سمجھا کیونکہ خوشبو بھی جماع کے اسباب میں سے ہے اور احرام کے دوران میں جماع کے اسباب بھی منع ہیں۔ مگر شاید وہ اس بات کو نظر انداز کر گئے کہ یہ خوشبو احرام سے قبل کی ہے نہ کہ دوران احرام لگائی گئی۔ خوبصورتی بھی تو جماع کے اسباب سے ہے، تو کیا احرام کے بعد خوبصورتی کا باقی رہنا گنا ہے؟ ہاں احرام کے کے دوران میں زیب وزینت منع ہے، اسی طرح یہ مسئلہ ہے۔"}],[2695,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں: گویا کہ میں رسول اللہ صلی اللہ علیہ وسلم کے سر میں اس حال میں کہ آپ محرم ہیں خوشبو کی چمک دیکھ رہی ہوں۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ مجھے یوں لگتا ہے کہ میں جبکہ آپ احرام کی حالت میں ہیں، رسول اللہ صلی اللہ علیہ وسلم کے سر مبارک میں خوشبو کی چمک دیکھ رہی ہوں۔","f2":"(۱) رسول اللہ صلی اللہ علیہ وسلم کی وفات کے بعد وہ اس منظر کو بیان فرما رہی ہیں جو انھوں نے اپنے ذہن میں محفوظ کر لیا تھا، اس لیے یہ پیرایۂ بیان اختیار فرمایا۔ (۲) ’’خوشبو کی چمک‘‘ گویا خوشبو کو کسی تیل وغیرہ میں شامل کر کے لگایا گیا ہو گا یا پھر کسی خوشبو دار پھول کا تیل نکالا گیا ہوگا۔ وہ چمک اس تیل کی تھی جومکمل طور پر زائل نہ ہوا تھا۔ ظاہر ہے خوشبو بھی آتی تھی۔ (۳) ممکن ہے باب کا مقصد یہ ہو کہ ایسی جگہ خوشبو لگائی جائے جو کپڑوں کو نہ لگے یا مقصد یہ ہو کہ خوشبو بدن کو لگائی جائے، کپڑوں کو نہیں۔"}],[2696,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے بالوں کی جڑوں میں اس حال میں کہ آپ محرم ہوتے خوشبو کی چمک دیکھتی تھی۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے مروی ہے کہ میں رسول اللہ صلی اللہ علیہ وسلم کے بالوں کی جڑوں میں خوشبو کی چمک دیکھا کرتی تھی جبکہ آپ محرم ہوتے تھے۔","f2":"رسول اللہ صلی اللہ علیہ وسلم یہ خوشبو احرام سے قبل لگاتے تھے۔ احرام کے بعد بھی اس کے کچھ اثرات بای رہ جاتے تھے۔"}],[2697,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں: گویا کہ میں رسول اللہ صلی اللہ علیہ وسلم کے سر کی مانگ میں اس حال میں کہ آپ محرم ہوتے خوشبو کی چمک دیکھ رہی ہوں۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ مجھے ایسے محسوس ہوتا ہے کہ میں رسول اللہ صلی اللہ علیہ وسلم کے سر مبارک کی مانگ میں خوشبو کی چمک دیکھ رہی ہوں جبکہ آپ احرام کی حالت میں ہیں۔"}],[2698,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کے سر میں اس حال میں کہ آپ محرم خوشبو کی چمک دیکھی ہے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا نے فرمایا: تحقیق میں نے رسول اللہ صلی اللہ علیہ وسلم کے سر مبارک میں خوشبو کی چمک دیکھی جبکہ آپ احرام کی حالت میں تھے۔"}],[2699,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں: گویا کہ میں رسول اللہ صلی اللہ علیہ وسلم کی مانگ میں خوشبو کی چمک دیکھ رہی ہوں، اور آپ لبیک پکار رہے ہیں۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں: گویا کہ میں رسول اللہ صلی اللہ علیہ وسلم کی مانگ مبارک میں خوشبو کی چمک دیکھ رہی ہوں جبکہ آپ لبیک پکار رہے تھے۔"}],[2700,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں: نبی اکرم صلی اللہ علیہ وسلم جب احرام باندھنے کا ارادہ کرتے (ہناد کی روایت میں ہے جب رسول اللہ صلی اللہ علیہ وسلم احرام باندھنے کا ارادہ کرتے) تو اچھے سے اچھا عطر جو آپ کو میسر ہوتا لگاتے یہاں تک کہ میں اس کی چمک آپ کے سر اور داڑھی میں دیکھتی۔ امام نسائی کہتے ہیں: اس بات پر ابواسحاق کی اسرائیل نے متابعت کی ہے انہوں نے اسے «عن عبدالرحمٰن بن الأسود عن أبيه عن عائشة» \" کے طریق سے روایت کیا ہے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے مروی ہے کہ نبی صلی اللہ علیہ وسلم، ہناد (راوی) نے (نبی صلی اللہ علیہ وسلم کے بجائے) کہا: رسول اللہ صلی اللہ علیہ وسلم، جب احرام باندھنے کا ارادہ فرماتے تو اپنے پاس موجود بہترین خوشبو لگاتے حتیٰ کہ میں اس کی چمک آپ کے سر اور داڑھی مبارک میں دیکھا کرتی تھی۔"}],[2701,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کو اچھی سے اچھی خوشبو جو مجھے میسر ہوتی لگاتی تھی یہاں تک کہ احرام سے پہلے میں آپ کے سر اور داڑھی میں خوشبو کی چمک دیکھتی تھی۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے مروی ہے کہ میں رسول اللہ صلی اللہ علیہ وسلم کو احرام سے قبل اپنے پاس موجود بہترین خوشبو لگاتی تھی حتیٰ کہ میں اس خوشبو کی چمک آپ کے سر اور داڑھی مبارک میں دیکھتی تھی۔","f2":"رسول اللہ صلی اللہ علیہ وسلم کو خوشبو تو حضرت عائشہ رضی اللہ عنہا ہی لگاتی تھیں مگر حدیث نمبر ۲۷۰۱ میں مجازاً نسبت آپ کی طرف کر دی ہے۔ یہ بھی بلاغت کلام کا ایک انداز ہے۔"}],[2702,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کی مانگوں میں خوشبو کی چمک تین دن بعد (بھی) دیکھی ہے۔","الألباني: صحيح الإسناد",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ تحقیق میں نے (احرام باندھنے سے) تین دن بعد رسول اللہ صلی اللہ علیہ وسلم کی مانگ مبارک میں خوشبو کی چمک دیکھی۔"}],[2703,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کی مانگ میں تین دن بعد (بھی) خوشبو کی چمک دیکھتی تھی۔","الألباني: صحيح لغيره",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ میں (احرام باندھنے سے) تین دن بعد بھی رسول اللہ صلی اللہ علیہ وسلم کی مانگ مبارک میں خوشبو کی چمک دیکھا کرتی تھی۔"}],[2704,"محمد بن منتشر کہتے ہیں کہ میں نے ابن عمر رضی اللہ عنہما سے احرام کے وقت خوشبو کے متعلق پوچھا، تو انہوں نے کہا: تارکول لگا لینا میرے نزدیک اس سے زیادہ بہتر ہے۔ تو میں نے اس بات کا ذکر عائشہ رضی اللہ عنہا سے کیا، تو انہوں نے کہا: اللہ تعالی ابوعبدالرحمٰن پر رحم فرمائے، میں خود رسول اللہ صلی اللہ علیہ وسلم کو خوشبو لگاتی تھی، پھر آپ اپنی بیویوں کا چکر لگاتے، پھر آپ اس حال میں صبح کرتے تو آپ کے جسم سے خوشبو پھوٹ رہی ہوتی۔","الألباني: صحيح ق وليس عند خ ذكر الإطلاء",{"u2":"حضرت محمد بن منتشر سے روایت ہے کہ میں نے حضرت عبداللہ بن عمر رضی اللہ عنہ سے احرام باندھتے وقت خوشبو لگانے کے بارے میں پوچھا تو انھوں نے فرمایا: اس سے تو اچھا یہ ہے کہ میں گندھک مل لوں۔ میں نے یہ بات حضرت عائشہ رضی اللہ عنہا سے ذکر کی تو وہ فرمانے لگیں: اللہ تعالیٰ ابو عبدالرحمن (ابن عمر رضی اللہ عنہ) پر رحم فرمائے! میں رسول اللہ صلی اللہ علیہ وسلم کو خوشبو لگایا کرتی تھی، پھر آپ اپنی بیویوں کے پاس جاتے، پھر صبح ہوتی جبکہ آپ سے خوشبو کی مہک آرہی ہوتی تھی (اور آپ صبح کو احرام باندھتے)۔"}],[2705,"محمد بن منتشر کہتے ہیں کہ میں نے ابن عمر رضی اللہ عنہما کو کہتے ہوئے سنا کہ مجھ پر تار کول مل دیا جائے تو یہ مجھے اس سے زیادہ پسند ہے کہ میں احرام کی حالت میں صبح کروں اور میرے جسم سے خوشبو بکھر رہی ہو۔ تو میں عائشہ رضی اللہ عنہا کے پاس گیا، اور میں نے انہیں ان کی بات بتائی تو انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو خوشبو لگائی پھر آپ اپنی بیویوں کے پاس پھرے، آپ نے صبح کیا اس حال میں کہ آپ محرم تھے۔","الألباني: صحيح",{"u2":"حضرت محمد بن منتشر بیان کرتے ہیں کہ میں نے حضرت ابن عمر رضی اللہ عنہ کو فرماتے سنا کہ میں گندھک مل لوں تو زیادہ اچھا ہے بجائے اس کے کہ مجھ سے احرام کی حالت میں خوشبو کی مہک آئے۔ میں حضرت عائشہ رضی اللہ عنہا کے پاس گیا اور انھیں یہ بات بتائی تو انھوں نے فرمایا: میں نے خود رسول اللہ صلی اللہ علیہ وسلم کو خوشبو لگائی۔ آپ اپنی بیویوں کے پاس گئے، پھر آپ نے احرام باندھا (اور آپ سے مہک آتی تھی)۔","f2":"چونکہ حضرت ابن عمر رضی اللہ عنہ کو اس حدیث کا علم نہیں تھا، اس لیے وہ اس کے قائل نہیں تھے۔ بسا اوقات جلیل القدر صحابہ کسی مسئلے سے ناواقف ہوتے ہیں، مثلاً: حضرت عبداللہ بن مسعود، حضرت عمر، حضرت ابوہریرہ رضی اللہ عنہم ان کے علاوہ بھی بعض صحابہ سے ایسی مثالیں ملتی ہیں، لہٰذا یہ کوئی تعجب کی بات نہیں۔ {وَفَوْقَ کُلِّ ذِیْ عِلْمٍ عَلِیْمٌ} (یوسف۱۲: ۷۶)"}],[2706,"انس رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے منع فرمایا ہے کہ آدمی (حالت احرام میں) زعفران لگا۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مرد کو زعفران لگانے سے منع فرمایا۔","f2":"چونکہ زعفران خوشبو کے ساتھ ساتھ رنگ بھی ہے اور مرد کے لیے رنگ والی چیز بطور زینت لگانا درست نہیں، لہٰذا مرد کے لیے کسی بھی حال میں زعفران استعمال کرنا درست نہیں۔ احرام میں تو بدرجۂ اولیٰ منع ہوگا۔ اسی طرح زعفران سے رنگے ہوئے کپڑے پہننا بھی مرد کے لیے ہر حال میں منع ہیں۔ احرام میں بدرجۂ اولیٰ ناجائز ہوں گے۔ اس بارے میں صریح روایات پیچھے گزر چکی ہیں۔"}],[2707,"انس بن مالک رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے منع فرمایا ہے کہ آدمی (حالت احرام میں) زعفران لگائے۔","الألباني: صحيح لغيره",{"u2":"حضرت انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے (مرد کو) زعفران لگانے سے منع فرمایا ہے۔","f2":"عورت احرام کے علاوہ زعفران لگا سکتی ہے، جسم کو بھی اور کپڑوں کو بھی۔ احرام کی حالت میں اس کے لیے بھی منع ہے۔ کیونکہ یہ خوشبو ہے اور احرام کی حالت میں مرد اور عورت دونوں کے لیے خوشبو کا استعمال منع ہے۔"}],[2708,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے زعفران استعمال کرنے سے روکا ہے۔ حماد (جو اس حدیث کے راوی ہیں) کہتے ہیں: یعنی مردوں کے لیے ممانعت ہے۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے زعفران لگانے سے منع فرمایا ہے۔ حماد راوی کہتے ہیں: یعنی مردوں کو۔"}],[2709,"یعلی بن امیہ رضی اللہ عنہ سے روایت ہے کہ ایک شخص عمرہ کا احرام باندھے ہوئے، سلے ہوئے کپڑے پہنے ہوئے اور خلوق لگائے ہوئے نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، وہ عمرہ کا احرام باندھے اور سلے ہوئے کپڑے پہنے ہوئے تھا، اور خلوق میں لت پت تھا، تو اس نے عرض کیا: میں نے عمرے کا احرام باندھ رکھا ہے تو میں کیا کروں؟ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"وہی کرو جو حج میں کرتے ہو\"، اس نے کہا: میں (حج میں) اس سے بچتا تھا، اور اسے دھو ڈالتا تھا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"جو تم حج میں کرتے تھے وہی اپنے عمرہ میں بھی کرو\"۔\n§وضاحت\n۱؎: \"خلوق\" ایک معروف خوشبو ہے جو زعفران ملا کر بنائی جاتی ہے۔","الألباني: صحيح",{"u2":"حضرت یعلیٰ رضی اللہ عنہ سے روایت ہے کہ ایک آدمی نبی صلی اللہ علیہ وسلم کے پاس آیا۔ اس نے عمرے کا احرام باندھ رکھا تھا لیکن اس نے سلے ہوئے کپڑے پہنے ہوئے تھے اور خلوق (خوشبو) لگا رکھی تھی۔ اس نے آپ سے کہا: میں نے عمرے کا احرام باندھا ہے تو میں کیا کروں؟ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’تو حج میں کیا کرتا تھا؟‘‘ اس نے کہا: میں اس (سلے ہوئے کپڑے) سے بچتا تھا اور اس (خوشبو) کو دھو دیا کرتا تھا۔ اپ نے فرمایا: ’’جو تو حج میں کرتا تھا، وہی عمرے میں کر۔‘‘","f2":"(۱) اس شخص کا خیال تھا کہ یہ پابندیاں صرف حج میں ہیں، عمرے میں نہیں کیونکہ یہ اس کے مقابلے میں کم مرتبے والا ہے۔ آپ نے فرمایا: کہ دونوں کے احرام میں کوئی فرق نہیں۔ دونوں میں پابندیاں ایک جیسی ہیں۔ احرام، حج اور عمرہ وغیرہ شریعت اسلامیہ سے پہلے بھی عرب میں رائج تھے۔ اور یہ پابندیاں بھی معروف تھیں اور یہ سابقہ انبیا ء علیہم السلام کی تعلیمات تھیں۔ (۲) ’’خلوق‘‘ یہ بھی ایک رنگ دار خوشبو ہے زعفران کی طرح لہٰذا اس کا حکم ہر لحاظ سے زعفران کی طرح ہے، یعنی مردوں کے لیے ہر حال میں منع ہے اور عورتوں کے لیے صرف احرام میں ممنوع ہے۔ اس کے علاوہ جائز ہے۔ (۳) ’’وہی عمرے میں کر۔‘‘ یہاں حج اور عمرے کے افعال مراد نہیں بلکہ صرف احرام مراد ہے، یعنی دونوں کا احرام ایک جیسا ہوتا ہے۔ (۴) چونکہ وہ شخص شرعی احکام سے ناواقف تھا، اس لیے اسے معذور تصور فرمایا۔ اب بھی کسی سے لا علمی کی بنا پر اس قسم کی کوئی غلطی سر زد ہو جائے تو ان شاء اللہ معذور ہوگا۔ واللہ اعلم"}],[2710,"یعلی بن امیہ رضی اللہ عنہ کہتے ہیں کہ ایک شخص رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، اور آپ جعرانہ میں تھے، وہ جبہ پہنے ہوئے تھا، اور اپنی داڑھی اور سر کو(زعفران سے) پیلا کیے ہوئے تھا۔ اس نے عرض کیا: اللہ کے رسول! میں نے عمرے کا احرام باندھ رکھا ہے اور میں جس طرح ہوں آپ مجھے دیکھ رہے ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"جبہ اتار دو اور زردی اپنے سے دھو ڈالو، اور جو حج میں کرتے ہو وہی اپنے عمرہ میں بھی کرو\"۔","الألباني: صحيح",{"u2":"حضرت یعلیٰ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک آدمی آیا جبکہ آپ جعرانہ میں تشریف فرما تھے۔ اس آدمی نے جبہ پہنا ہوا تھا اور اپنی ڈاڑھی اور سر کو زرد رنگ کی خوشبو لگا رکھی تھی۔ وہ کہنے لگا: اے اللہ کے رسول! میں نے عمرے کا احرام باندھا ہے اور میری حالت آپ دیکھ رہے ہیں۔ آپ نے فرمایا: ’’جبہ اتار دے اور رنگ دار خوشبو دھو دے اور جس طرح تو حج (کے احرام) میں کرتا تھا، اسی طرح عمرے (کے احرام) میں کر۔‘‘","f2":"جبہ بھی قمیص ہی کی ایک صورت ہے۔ یہ بھی سلا ہوا ہوتا ہے، لہٰذا محرم کے لیے منع ہے۔"}],[2711,"عثمان رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے محرم کے بارے میں فرمایا: \"جب اس کے سر میں درد ہو یا آنکھیں دکھیں تو ایلوا کا لیپ کر لے\" ۱؎۔\n§وضاحت\n۱؎: یعنی ایسی دوا لگا لے جس میں خوشبو نہ ہو۔","الألباني: صحيح",{"u2":"حضرت عثمان رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے محرم کے بارے میں فرمایا: ’’جب اسے سر یا آنکھوں میں تکلیف ہو تو اپنی آنکھوں پر ایلوے کا لیپ کرے۔‘‘","f2":"’’لیپ کرے‘‘ یعنی سرمہ ڈالنے کے بجائے ایلوے کا لیپ کرے کیونکہ سرمہ رنگ والی زینت ہے اور احرام میں ہر قسم کی زینت منع ہے۔ ایلوے کے لیپ سے تکلیف دور ہو جائے گی اور زینت سے بھی بچت ہو جائے گی۔"}],[2712,"محمد الباقر کہتے ہیں کہ ہم جابر (جابر بن عبداللہ رضی اللہ عنہما) کے پاس آئے، اور ان سے نبی اکرم صلی اللہ علیہ وسلم کے حج کے متعلق پوچھا تو انہوں نے ہم سے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اگر مجھے پہلے معلوم ہو گیا ہوتا جو اب معلوم ہوا تو میں ہدی (کا جانور) لے کر نہ آتا اور اسے عمرہ میں تبدیل کر دیتا (اور طواف و سعی کر کے احرام کھول دیتا) تو جس کے پاس ہدی نہ ہو وہ احرام کھول ڈالے، اور اسے عمرہ قرار دے لے\" (اسی موقع پر) علی رضی اللہ عنہ یمن سے ہدی(کے اونٹ) لے کر آئے اور رسول اللہ صلی اللہ علیہ وسلم مدینہ سے لے کر گئے۔ اور فاطمہ رضی اللہ عنہا نے جب رنگین کپڑے پہن لیے اور سرمہ لگا لیا علی رضی اللہ عنہ کہتے ہیں کہ میں تو غصہ میں رسول اللہ صلی اللہ علیہ وسلم سے فتوی پوچھنے گیا۔ میں نے کہا: اللہ کے رسول! فاطمہ نے تو رنگین کپڑے پہن رکھے ہیں اور سرمہ لگا رکھا ہے اور کہتی ہیں: میرے ابا جان صلی اللہ علیہ وسلم نے مجھے اس کا حکم دیا ہے؟، آپ نے فرمایا: \"اس نے سچ کہا، اس نے، سچ کہا، میں نے ہی اسے حکم دیا ہے\"۔","الألباني: صحيح",{"u2":"حضرت محمد (باقر) رحمہ اللہ بیان کرتے ہیں کہ ہم حضرت جابر رضی اللہ عنہ کے پاس حاضر ہوئے اور ہم نے ان سے نبی صلی اللہ علیہ وسلم کے حج (حجۃ الوداع) کے بارے میں پوچھا تو انھوں نے ہم سے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا: ’’اگر مجھے اس بات کا پہلے پتا چل جاتا جس کا بعد میں پتا چلا ہے تو میں قربانی کے جانور ساتھ نہ لاتا اور حج کے بجائے عمرے کا احرام باندھتا، لہٰذا جس شخص کے ساتھ قربانی کا جانور نہیں، وہ حج کے احرام کو عمرے کے احرام میں بدل دلے۔‘‘ حضرت علی رضی اللہ عنہ بھی یمن سے قربانی کے جانور لے کر آئے تھے اور رسول اللہ صلی اللہ علیہ وسلم مدینہ منورہ سے قربانی کے جانور لائے تھے۔ حضرت فاطمہ رضی اللہ عنہا نے رنگ دار کپڑے پہنے ہوئے تھے اور سرمہ لگا رکھا تھا۔ حضرت علی رضی اللہ عنہ نے فرمایا: میں بھڑکانے (غصہ دلانے) کے لیے رسول اللہ صلی اللہ علیہ وسلم کے پاس مسئلہ پوچھنے گیا۔ میں نے کہا: اے اللہ کے رسول! فاطمہ نے رنگ دار کپڑے پہنے ہوئے ہیں اور سرمہ لگا رکھا ہے اور وہ کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے ان کاموں کا حکم دیا ہے؟ آپ نے فرمایا: ’’اس نے سچ کہا۔ وہ سچ کہتی ہے، وہ سچی ہے، میں نے ہی اسے حکم دیا ہے۔‘‘","f2":"(۱) ’’اگر مجھے پہلے پتا چل جاتا۔‘‘ روایت کا ابتدائی حصہ حذف ہے۔ دراصل حجۃ الوداع میں رسول اللہ صلی اللہ علیہ وسلم اور صحابہ کرام رضی اللہ عنہم نے حج ہی کا احرام باندھا تھا، مگر پھر اللہ تعالیٰ کی طرف سے حکم آگیا کہ حج کے دنوں میں عمرہ بھی کیا جائے۔ دور جاہلیت میں لوگ حج کے دنوں میں عمرہ کرنے کو بہت بڑا گناہ سمجھتے تھے۔ آپ نے اعلان عام فرمایا کہ جن لوگوں کے ساتھ قربانی کا جانور نہیں، وہ حج کے احرام کو عمرے کے احرام میں بدل لیں اور عمرہ کر کے حلال ہو جائیں۔ حج کے لیے بعد میں نیا احرام باندھیں۔ قربانی کے جانور ساتھ لانے والے چونکہ قربانی ذبح ہونے سے پہلے حلال نہیں ہو سکتے تھے، اس لیے انھیں ہدایت کی گئی کہ وہ عمرہ تو کریں مگر حج کا احرام قائم رکھیں اور قربانی ذبح ہونے کے بعد حلال ہوں۔ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ بھی قربانی کے جانور تھے، لہٰذا آپ عمرہ کر کے حلال نہ ہوئے۔ دوسرے لوگوں کے لیے جن کے پاس قربانیاں نہیں تھیں، عمرے کے بعد حلال ہونا بڑا شاق تھا کیونکہ ان کی اصل نیت حج کی تھی۔ حج کے دن بھی قریب تھے۔ صرف تین دن کا فاصلہ تھا، لہٰذا انھیں درمیان میں حلال ہونا پسند نہ تھا۔ اسی لیے آپ نے یہ الفاظ ارشاد فرمائے۔ (۲) ’’جو بعد میں پتا چلا۔‘‘ یعنی عمرے کا حکم۔ (۳) حضرت فاطمہ رضی اللہ عنہا کے ساتھ قربانی کے جانور نہیں تھے، لہٰذا وہ عمرہ کر کے حلال ہوگئیں۔ انھوں نے رنگ دار کپڑے پہنے اور سرمہ لگایا۔ حضرت علی رضی اللہ عنہ کے ساتھ چونکہ قربانی کے جانور تھے، لہٰذا وہ حلال نہ ہوئے، اس لیے انھیں اشکال پیدا ہوا۔ (۴) امام نسائی رحمہ اللہ کا استدلال یہ ہے کہ اگر احرام کی حالت میں رنگ دار کپڑے درست ہوتے یا سرمہ لگانا جائز ہوتا تو حضرت علی رضی اللہ عنہ اعتراض کیوں کرتے؟ معلوم ہوا احرام کی حالت میں رنگ دار کپڑے یا سرمہ جائز نہیں، البتہ رنگ دار کپڑوں سے مراد وہ ہیں جنھیں بعد میں رنگا گیا ہو یا زعفران وغیرہ سے رنگے ہوں، ورنہ پہلے سے رنگ والے کپڑے عورت احرام میں استعمال کر سکتی ہے۔ ان کپڑوں کی کراہت کی وجہ زینت یا خوشبو ہے۔ (۵) اس حدیث سے ثابت ہوا کہ کسی دینی نقصان پر اظہار افسوس کرتے ہوئے کلمہ ’’لَوْ‘‘ کہنا جائز ہے۔ صحیح مسلم کی حدیث میں جو ممانعت وارد ہے وہ دنیاوی امور کے متعلق ہے۔ (۶) اپنے اہل خانہ اور بال بچوں کی خوب نگرانی کرنی چاہیے اور خیال رکھنا چاہیے کہ کہیں وہ کسی خلاف شرع کام کے مرتکب تو نہیں ہو رہے۔ (۷) اگر ممکن ہو تو قربانی کے جانور دور دراز علاقے سے لائے جا سکتے ہیں۔ یہ مشروع ہے، اس میں کوئی حرج نہیں۔"}],[2713,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ ایک شخص اپنی سواری سے گر پڑا تو سواری نے اسے کچل کر ہلاک کر دیا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"اسے پانی اور بیر کے پتوں سے غسل دو، اور اسے دو کپڑوں میں کفنایا جائے، اور اس کا سر اور چہرہ کھلا رکھا جائے کیونکہ وہ قیامت کے دن لبیک کہتا ہوا اٹھایا جائے گا\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے کہ ایک آدمی (احرام کی حالت میں) اپنی سواری سے گر پڑا۔ اس (سواری) نے اسے فوراً مار ڈالا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اسے پانی اور بیری کے پتوں سے غسل دو اور اسے (احرام والے) دو کپڑوں میں کفن دیا جائے۔ سر اور چہرہ ننگا رہے کیونکہ یہ قیامت کے دن لبیک کہتا ہوا اٹھے گا۔‘‘","f2":"(۱) مرد کو احرام کی حالت میں چہرہ ننگا رکھنا چاہیے۔ تفصیل کے لیے دیکھیے حدیث: ۲۶۷۴۔ (۲) روایت سے معلوم ہوتا ہے کہ محرم فوت ہو جائے تو اس کی احرام والی حالت قائم رکھی جائے۔ اسے یا کفن کو خوشبو لگائی جائے۔ اور سر اور چہرہ ننگا رکھا جائے۔ وہ قیامت کے دن بھی احرام کی حالت میں اٹھے گا۔ مگر احناف اسے ہر محرم کے لیے درست نہیں سمجھتے کیونکہ موت سے اعمال ختم ہو جاتے ہیں، احرام کیسے باقی رہ گیا؟ لیکن یہ صریح فرمان نبوی کے مقابلے میں قیاس ہے جو بہت بری بات ہے، نیز میت کا ایمان باقی رہ سکتا ہے تو احرام کیوں نہیں؟ احناف اس حکم کو صرف اس شخص کے ساتھ خاص رکھتے ہیں کہ اس کے بارے میں خاص وحی آئی ہو گی۔ مگر یہ بات بلا دلیل ہے۔ ’’ہوگا، ہوگی‘‘ سے کوئی مسئلہ ثابت نہیں ہوتا۔ حدیث کے آخری الفاظ: ’’وہ قیامت کے دن لبیک کہتا ہوا اٹھے گا۔‘‘ بھی اس حکم کو عام کرتے ہیں کیونکہ لبیک کہنا اس شخص کے ساتھ خاص نہیں تھا۔ پھر دیگر احادیث بھی دلالت کرتی ہیں کہ کوئی شخص جس حالت میں فوت ہوگا، اسی حالت میں اٹھے گا، مثلاً شہید اور خود کشی کرنے والا وغیرہ۔ (۳) اس روایت میں سر کے ساتھ چہرہ ننگا رکھنے کا بھی حکم ہے جس سے یہی معلوم ہوتا ہے کہ احرام کی حالت میں چہرہ ننگا رکھنا مرد کے لیے ضروری ہے، مگر امام شافعی کا خیال ہے کہ چہرہ ننگا رکھنا صرف سر ننگا رکھنے کے لیے ہے ورنہ احرام میں مرد کے لیے چہرہ ننگا رکھنا ضروری نہیں۔ بہر صورت احتیاط یہی ہے کہ چہرہ بھی ننگا رکھا جائے۔ اہل ظاہر اس مسئلے میں امام شافعی رحمہ اللہ کے ساتھ ہیں مگر میت محرم کی صورت میں چہرہ ننگا رکھنے کے قائل ہیں۔"}],[2714,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ ایک شخص (حالت احرام میں) مر گیا تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اسے پانی اور بیر کے پتے سے غسل دو اور اسے اس کے کپڑوں ہی میں کفنا دو، اور اس کے سر اور چہرے کونہ ڈھانپو کیونکہ قیامت کے دن وہ لبیک کہتا ہوا اٹھایا جائے گا۔\"","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے مروی ہے کہ ایک (محرم) آدمی فوت ہوگیا تو نبی صلی اللہ علیہ وسلم نے فرمایا: ’’اسے پانی اور بیری کے پتوں سے غسل دو اور اس کے (احرام کے) کپڑوں میں اسے کفنا دو۔ اور اس کے چہرے اور سر کو نہ ڈھانپو۔ یہ قیامت کے دن لبیک کہتا ہوا اٹھے گا۔‘‘"}],[2715,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے حج افراد کیا ۱؎۔\n§وضاحت\n۱؎: حج کی تین قسمیں ہیں: افراد، قران اور تمتع، حج افراد: یہ ہے کہ صرف حج کی نیت سے احرام باندھے اور حج قران یہ ہے کہ حج اور عمرہ دونوں کی ایک ساتھ نیت کرے اور ساتھ میں ہدی کا جانور بھی لے اور حج تمتع یہ ہے کہ حج کے مہینے میں میقات سے صرف عمر ے کی نیت کرے پھر مکہ میں جا کر عمرہ کی ادائیگی کے بعد احرام کھول دے اور پھر آٹھویں تاریخ کو مکہ سے نئے سرے سے حج کا احرام باندھے۔","الألباني: ضعيف شاذ",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے صرف حج کا احرام باندھا تھا۔","f2":"احرام کی تین صورتیں ہیں: (۱) صرف حج کا احرام (۲)صرف عمرے کا احرام (۳) عمرے اور حج دونوں کا بیک وقت احرام۔ پہلی صورت کو افراد دوسری کو (اگر اس کے بعد الگ احرام سے حج بھی کیا جائے تو) تمتع اور تیسری صورت کو قران کہتے ہیں۔ (اور اگر دوسری صورت میں صرف عمرہ ہی کیا جائے بعد میں حج نہ کیا جائے تو یہ بھی افراد ہی ہے مگر یہ افراد بالعمرہ ہے)۔ رسول اللہ صلی اللہ علیہ وسلم کے بارے میں اس بات پر تو اتفاق ہے کہ آپ نے فرضیت حج کے بعد صرف ایک ہی حج کیا تھا، البتہ اس بات میں اختلاف ہے کہ آپ نے صرف حج کیا یا حج اور عمرہ دونوں اکٹھے کیے۔ صحیح بات یہ ہے کہ آپ نے حج اور عمرہ دونوں اکٹھے کیے ہیں جیسا کہ بہت سی احادیث سے مفہوم اخذ ہوتا ہے لیکن مذکورہ روایت میں ہے کہ آپ نے صرف حج کیا یا صرف حج کا احرام باندھا۔ تطبیق یوں ہے کہ ابتدا میں نبی صلی اللہ علیہ وسلم نے صرف حج کا احرام باندھا تھا، بعد میں عمرے کا حکم نازل ہوا تو آپ نے حج کے احرام میں عمرے کو بھی داخل فرما لیا لیکن چونکہ آپ کے ساتھ قربانی کے جانور تھے، لہٰذا آپ عمرے کے بعد حلال نہ ہوئے بلکہ حج کے بعد ہی حلال ہوئے، لہٰذا آپ کے عمرہ کرنے کا پتہ نہیں چلا۔ جن لوگوں نے آپ کو آخر وقت میں لبیک پکارتے سنا، انھیں پتا چل گیا کہ آپ حج کے ساتھ عمرے کی لبیک بھی پکار رہے ہیں۔ جنھوں نے صرف اول وقت میں لبیک پکارتے سنا، انھوں نے کہا کہ آپ نے صرف حج کیا۔"}],[2716,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے حج کے لیے لبیک پکارا۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے صرف حج کی لبیک کہی۔"}],[2717,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ اس حال میں نکلے کہ (چند دنوں کے بعد) ہم ذی الحجہ کا چاند دیکھنے ہی والے تھے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو حج کا احرام باندھنا چاہے حج کا احرام باندھ لے، اور جو عمرہ کا احرام باندھنا چاہے عمرہ کا احرام باندھ لے\" ۱؎۔\n§وضاحت\n۱؎: مدینہ سے یہ روانگی ذی قعدہ کی پچیسویں تاریخ کو ہوئی تھی۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے مروی ہے کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ذوالحجہ کا چاند طلوع ہونے سے چند دن قبل (حج کو) نکلے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم میں سے جو شخص صرف حج کا احرام باندھنا چاہے، وہ حج کا احرام باندھے اور جو عمرے کا احرام باندھنا چاہے، وہ عمرے کا احرام باندھے۔‘‘","f2":"ابتداء میں تو ایسے ہی تھا کہ حج اور عمرے کے احرام میں اختیار تھا۔ بعد میں آپ نے وحی کی بنا پر عمرہ لازم فرما دیا کہ جن لوگوں نے صرف حج کا احرام باندھ رکھا ہے اگر ان کے پاس قربانی کا جانور نہیں تو حج کا احرام عمرے سے بدل کر عمرہ کرنے کے بعد حلال ہو جائیں اور جن کے ساتھ قربانی کے جانور ہیں، وہ حج کے ساتھ عمرہ بھی داخل کر لیں لیکن عمرہ کرنے کے بعد حلال نہ ہوں۔"}],[2718,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نکلے اور ہمارے پیش نظر صرف حج تھا۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے مروی ہے کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نکلے تو ہمارا ارادہ یہی تھا کہ یہ صرف حج ہے۔","f2":"یہ اکثریت کی بات ہے ورنہ بعض صحابہ کا احرام تو شروع ہی سے عمرے کا تھا جیسا کہ روایت: ۲۷۱۸ میں ہے، نیز یہ بات ابتدا کی ہے، بعد میں عمرے کا حکم آیا تو صورت حال بدل گئی۔ وضاحت اوپر گزر چکی ہے۔"}],[2719,"صبی بن معبد رضی اللہ عنہ کہتے ہیں کہ میں ایک نصرانی بدوی تھا تو میں مسلمان ہو گیا اور جہاد کا حریص تھا، مجھے پتہ لگا کہ حج و عمرہ دونوں مجھ پر فرض ہیں، تو میں اپنے خاندان کے ایک شخص کے پاس آیا جسے ھریم بن عبداللہ کہا جاتا تھا، میں نے اس سے پوچھا (کیا کریں) تو اس نے کہا: دونوں ایک ساتھ کر لو۔ پھر جو ہدی (قربانی)بھی تمہیں میسر ہو اسے ذبح کر ڈالو، تو میں نے (حج و عمرہ) دونوں کا احرام باندھ لیا، پھر جب میں عذیب ۱؎ پہنچا، تو وہاں مجھے سلمان بن ربیعہ اور زید بن صوحان ملے، میں اس وقت حج و عمرہ دونوں کے نام سے لبیک پکار رہا تھا ۲؎ ان دونوں میں سے ایک نے دوسرے سے کہا: یہ شخص اپنے اونٹ سے زیادہ سمجھدار نہیں، (یہ سن کر)میں عمر رضی اللہ عنہ کے پاس آیا اور میں نے اُن سے کہا: امیر المؤمنین! میں مسلمان ہو گیا ہوں، اور میں جہاد کا حریص ہوں، اور میں نے حج و عمرہ دونوں کو اپنے اوپر فرض پایا، تو میں ہریم بن عبداللہ کے پاس آیا، اور میں نے ان سے کہا: حج و عمرہ دونوں مجھ پر فرض ہیں، انہوں نے کہا: دونوں ایک ساتھ کر ڈالو، اور جو جانور تمہیں میسر ہو اس کی قربانی کر لو، تو میں نے دونوں کا احرام باندھ لیا، جب میں عذیب پہنچا تو مجھے سلمان بن ربیعہ اور زید بن صوحان ملے، تو ان میں سے ایک دوسرے سے کہنے لگا: یہ اپنے اونٹ سے زیادہ سمجھ دار نہیں ہے، اس پر عمر رضی اللہ عنہ نے کہا: تمہیں اپنے نبی کی سنت کی توفیق ملی ہے ۳؎۔\n§وضاحت\n۱؎: \"عذیب\" بنی تمیم کے ایک چشمہ کا نام ہے جو کوفہ سے ایک مرحلہ کی وادی پر ہے۔ ۲؎: یعنی «لبیک بحجۃ وعمرۃ» کہہ رہا تھا۔ ۳؎: یعنی جو تم نے کیا ہے یہی تمہارے نبی کی سنت ہے۔","الألباني: صحيح",{"u2":"حضرت عبسی بن معبد بیان کرتے ہیں کہ میں اعرابی اور عیسائی تھا، پھر میں مسلمان ہوگیا۔ مجھے جہاد کا بہت شوق تھا لیکن مجھے پتا چلا کہ مجھ پر تو حج اور عمرہ فرض ہیں۔ میں اپنے قبیلے کے ایک آدمی کے پاس آیا جن کا نام ہریم بن عبداللہ تدا۔ میں نے ان سے اس بارے میں پوچھا تو انھوں نے کہا: دونوں بیک وقت کر لو، پھر قربانی کا جو جانور میسر ہو ذبح کر دینا۔ میں نے دونوں کا احرام باندھ لیا۔ جب ہم عذیب مقام پر پہنچے تو مجھے سلمان بن ربیعہ اور حضرت زید بن صوحان ملے۔ میں حج اور عمرے کی لبیک کہہ رہا تھا تو ان میں سے ایک نے دوسرے سے کہا کہ یہ شخص تو اپنے اونٹ سے زیادہ سمجھ دار معلوم نہیں ہوتا۔ میں حضرت عمر رضی اللہ عنہ کے پاس حاضر ہوا اور عرض کی: اے امیرالمومنین! میں نے اسلام قبول کیا ہے۔ مجھے جہاد کا بہت شوق ہے لیکن میں نے حج اور عمرہ اپنے آپ پر فرض پایا ہے۔ میں ہریم بن عبداللہ کے پاس گیا۔ میں نے کہا: اے وہ (ہُریم)! میں نے اپنے آپ پر حج اور عمرہ دونوں کو فرض پایا ہے (تو میں کیا کروں؟) انھوں نے کہا: دونوں کا احرام اکٹھا باندھ لو، پھر جو قربانی میسر ہو، ذبح کر دینا۔ میں نے دونوں کا احرام باندھ لیا۔ جب میں عذیب مقام پر پہنچا تو مجھے حضرت سلمان بن ربیعہ اور زید بن صوحان ملے تو ان میں سے ایک نے دوسرے سے کہا: یہ اپنے اونٹ سے زیادہ سمجھ دار نہیں۔ حضرت عمر رضی اللہ عنہ نے فرمایا: تمھیں تمھارے نبی صلی اللہ علیہ وسلم کی سنت کی توفیق ملی ہے۔","f2":"(۱) ’’حج اور عمرہ فرض ہیں۔ شاید انھوں نے یہ بات ارشاد باری تعالیٰ: {وَاَتِمُّوا الْحَجَّ وَالْعُمْرَۃَ لِلّٰہِ} (البقرہ۲: ۱۹۶) سے اخذ کی ہو یا شاید کسی نے انھیں فتویٰ دیا ہو۔ (۲) ’’جانور ذبح کر دینا۔‘‘ کیونکہ حج کے ساتھ عمرہ کیا جائے تو ایک جانور ذبح کرنا لازم ہو جاتا ہے۔ (۳) ’’اونٹ سے زیادہ سمجھ دار نہیں‘‘ کیونکہ وہ لوگ حج اور عمرے کو اکٹھا کرنا صحیح نہیں سمجھتے تھے۔ انھیں علم نہیں تھا۔ (۴) ’’سنت کی توفیق ملی ہے۔‘‘ حضرت عمر رضی اللہ عنہ صرف تمتع سے روکتے تھے، قران سے نہیں۔ گویا وہ عمرے اور حج کے دوران میں حلال ہونے کو جائز نہیں سمجھتے تھے کیونکہ رسول اللہ صلی اللہ علیہ وسلم درمیان میں حلال نہیں ہوئے تھے۔ (۵) مسئلے کا علم نہ ہو تو اہل علم سے پوچھ لینا چاہیے۔"}],[2720,"ابووائل شقیق کہتے ہیں کہ ہمیں صبی بن معبد رضی اللہ عنہ مجھ نے خبر دی پھر راوی نے اسی کے مثل بیان کی اس میں ہے کہ میں عمر رضی اللہ عنہ کے پاس آیا، اور میں نے انہیں پورا واقعہ سنایا، مگر ان میں اس کے قول «یا ھناہ» کا ذکر نہیں ہے۔","الألباني: صحيح",{"u2":"حضرت عبسی نے (مذکورہ بالا) کے مثل حدیث بیان کی۔ کہا: پھر میں حضرت عمر رضی اللہ عنہ کی خدمت میں حاضر ہوا، پھر پورا قصہ (واقعہ) بیان کیا لیکن یَا ھَنَّاہُ! ’’اے وہ ہریم!‘‘ کے الفاظ بیان نہیں کیے۔"}],[2721,"شقیق بن سلمہ ابووائل نامی ایک عراقی سے روایت ہے کہ بنی تغلب کا ایک شخص جسے صبی بن معبد کہا جاتا تھا اور وہ نصرانی تھا مسلمان ہو گیا، تو وہ اپنے حج کے شروع ہی میں حج اور عمرے دونوں کا ایک ساتھ تلبیہ پکارتے ہوئے چلا تو وہ اسی طرح کا تلبیہ پکارتا سلمان بن ربیعہ اور زید بن صوحان کے پاس سے گزرا، تو ان دونوں میں سے ایک نے کہا: تم تو اپنے اونٹ سے بھی زیادہ گمراہ ہے، صبی نے کہا: تو برابر یہ بات میرے دل میں رہی یہاں تک میری ملاقات عمر بن خطاب رضی اللہ عنہ سے ہوئی تو میں نے ان سے اس بات کا ذکر کیا تو انہوں نے کہا: تمہیں اپنے نبی اکرم صلی اللہ علیہ وسلم کی سنت کی ہدایت و توفیق ملی ہے۔ شقیق (جو اس حدیث کے راوی ہیں) کہتے ہیں: میں اور مسروق بن اجدع دونوں صبی بن معبد رضی اللہ عنہ کے پاس آیا جایا کرتے تھے اور ان سے تبادلہ خیالات کرتے رہتے تھے تو میں اور مسروق بن اجدع دونوں متعدد بار ان کے پاس گئے۔","الألباني: صحيح",{"u2":"حضرت شقیق بن سلمہ ابو وائل سے روایت ہے کہ بنو تغلب کے ایک شخص جنھیں عبسی بن معبد کہا جاتا تھا اور وہ پہلے عیسائی تھے، پھر وہ مسلمان ہوگئے، اپنے پہلے حج کو آئے تو انھوں نے حج اور عمرے کی بیک وقت لبیک کہی۔ وہ اسی طرح دونوں کی بیک وقت لبیک کہتے جا رہے تھے کہ ان کا گزر سلمان بن ربیعہ اور زید بن صوحان کے قریب سے ہوا تو ان میں سے ایک نے کہا: تو تو اپنے اس اونٹ سے بھی کم عقل ہے۔ حضرت عبسی نے کہا: مجھے اس بات سے بہت پریشانی ہوئی حتیٰ کہ میں حضرت عمر بن خطاب رضی اللہ عنہ سے ملا تو میں نے یہ ساری بات ان کے گوش گزار کی۔ وہ فرمانے لگے: تمھیں تمھارے نبی صلی اللہ علیہ وسلم کی سنت مطہرہ کی توفیق ملی ہے۔ حضرت شقیق نے کہا: میں اور حضرت مسروق بن اجدع حضرت عبسی بن معبد کے پاس بکثرت آتے جاتے تھے اور ان سے یہ واقعہ سنانے کی گزارش کرتے تھے۔","f2":"حج اور عمرے کی بیک وقت لبیک یوں ہوگی: لَبَّیْکَ بَحَجَّۃٍ وَّ عُمْرَۃٍ۔"}],[2722,"مروان بن حکم سے روایت ہے، وہ کہتے ہیں کہ میں عثمان کے پاس بیٹھا تھا کہ انہوں نے علی کو عمرہ و حج دونوں کا تلبیہ پکارتے ہوئے سنا تو کہا: کیا ہم اس سے روکے نہیں جاتے تھے۔ انہوں نے کہا: کیونکہ نہیں، لیکن میں نے رسول اللہ صلی اللہ علیہ وسلم کو ان دونوں (حج و عمرہ) کا ایک ساتھ تلبیہ پکارتے ہوئے سنا ہے، تو میں رسول اللہ صلی اللہ علیہ وسلم کے قول کو آپ کے قول کے لیے نہیں چھوڑ سکتا۔","الألباني: صحيح",{"u2":"حضرت مروان بن حکم سے روایت ہے کہ میں حضرت عثمان کے پاس بیٹھا ہوا تھا کہ انھوں نے حضرت علی رضی اللہ عنہ کو حج اور عمرے کی اکٹھی لبیک کہتے سنا: حضرت عثمان فرمانے لگے: کیا آپ کو علم نہیں کہ اس سے روکا گیا ہے؟ حضرت علی رضی اللہ عنہ فرمانے لگے: یقینا علم ہے مگر میں نے رسول اللہ صلی اللہ علیہ وسلم کو دونوں کی اکٹھی لبیک کہتے سنا ہے۔ میں تمھارے حکم کی وجہ سے نبی صلی اللہ علیہ وسلم کا فرمان نہیں چھوڑ سکتا۔","f2":"(۱) حضرت عثمان رضی اللہ عنہ بھی حضرت عمر رضی اللہ عنہ کی طرح حج وعمراہ اکٹھا کرنے سے روکتے تھے۔ کیونکہ وہ حج افراد کو افضل سمجھتے تھے اور اسی بنا پر اس کا حکم بھی دیتے تھے۔ اور یہ ان کا ذاتی اجتہاد تھا۔ بہرحال اگر کوئی حج قران یا تمتع کرنا چاہے تو اس میں کوئی حرج نہیں۔ احادیث کی روشنی میں یہ موقف صحیح ہے۔ واللہ اعلم (۲) عالم کو اپنے علم کی اشاعت اور اس کا اظہار کرنا چاہیے۔ امراء سے ڈر کر مسئلے کو چھپانا جائز نہیں، لیکن یہ اظہار مسلمانوں کی اصلاح اور خیر خواہی کی نیت سے ہو نہ کہ کسی فتنے کی بنیاد ڈالنے کے لیے۔ (۳) ایک مجتہد دوسرے مجتہد کو اپنی تقلید یا حمایت پر مجبور نہیں کر سکتا۔"}],[2723,"مروان سے روایت ہے کہ عثمان رضی اللہ عنہ نے متعہ سے اور اس بات سے کہ آدمی حج و عمرہ دونوں کو ایک ساتھ جمع کرے منع کیا تو علی نے حج و عمرہ دونوں کا ایک ساتھ تلبیہ پکارا، عثمان رضی اللہ عنہ نے کہا: کیا تم اسے کر رہے ہو؟ اور حال یہ ہے کہ میں اس سے منع کر رہا ہوں، اس پر علی رضی اللہ عنہ نے کہا: میں رسول اللہ صلی اللہ علیہ وسلم کی سنت کو کسی بھی شخص کے کہنے سے نہیں چھوڑ سکتا۔","الألباني: صحيح",{"u2":"حضرت مروان سے روایت ہے کہ حضرت عثمان رضی اللہ عنہ نے تمتع اور قران سے روکا تو حضرت علی رضی اللہ عنہ نے علانیہ حج اور عمرے کی اکٹھی لبیک پڑھی۔ حضرت عثمان رضی اللہ عنہ نے فرمایا: آپ ایسا کرتے ہیں جبکہ میں نے اس سے روک رکھا ہے؟ حضرت علی رضی اللہ عنہ نے فرمایا: لوگوں میں سے کسی شخص کے کہنے سے میں رسول اللہ صلی اللہ علیہ وسلم کی سنت نہیں چھوڑ سکتا۔","f2":"’’تمتع‘‘ یہ ہے کہ حج کے مہینوں میں میقات سے صرف عمرے کا احرام باندھا جائے، پھر عمرہ کر کے حلال ہو جائے اور حج کے دنوں میں دوبارہ حج کا احرام باندھا جائے۔ اور ’’قران‘‘ یہ ہے کہ میقات ہی سے عمرے اور حج کا اکٹھا احرام باندھا جائے، پھر عمرہ اور حج دونوں کی ادائیگی کے بعد حلال ہو۔ دونوں صورتوں میں قربانی واجب ہوگی، نیز حرم میں رہنے والے یہ دونوں صورتیں، یعنی تمتع اور قران نہیں کر سکتے۔ ان کی اجازت صرف ان لوگوں کو ہے، جو میقات سے گزریں اور احرام باندھیں۔ یا میقات اور حرم کے درمیان رہنے والے اپنی جگہ سے احرام باندھ کر روانہ ہوں۔"}],[2724,"اس سند سے بھی شعبہ سے اسی کے مثل مروی ہے۔","",{"u2":"نضر نے شعبہ سے اسی سند سے اس جیسی روایت کی ہے۔"}],[2725,"براء بن عازب رضی اللہ عنہما کہتے ہیں کہ میں علی بن ابی طالب رضی اللہ عنہ کے ساتھ تھا جس وقت رسول اللہ صلی اللہ علیہ وسلم نے انہیں یمن کا حاکم بنایا، پھر جب وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے، علی رضی اللہ عنہ نے کہا: تو میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، تو آپ نے مجھ سے پوچھا: \"تم نے کیسے کیا ہے؟\"یعنی کس چیز کا تلبیہ پکارا ہے، میں نے کہا: میں نے آپ کا تلبیہ پکارا ہے (یعنی آپ کے احرام کے مطابق احرام باندھا ہے)، آپ نے فرمایا: \"میں تو ہدی ساتھ لایا ہوں، اور میں نے قِران کیا ہے\"، اور رسول اللہ صلی اللہ علیہ وسلم نے اپنے اصحاب سے فرمایا: \"اگر مجھے پہلے وہ باتیں معلوم ہوئی ہوتیں جواب معلوم ہوئی ہیں تو میں بھی ویسے ہی کرتا جیسے تم نے کیا ہے ۱؎ لیکن میں ہدی ساتھ لایا ہوں، اور میں نے حج قِران کا احرام باندھ رکھا ہے\"۔\n§وضاحت\n۱؎: یعنی میں بھی احرام کھول کر حلال ہو جاتا۔","الألباني: صحيح",{"u2":"حضرت براء رضی اللہ عنہ سے مروی ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم نے حضرت علی رضی اللہ عنہ کو یمن کا امیر بنایا تو میں بھی ان کے ساتھ تھا۔ جب وہ (حجۃ الوداع کے موقع پر یمن سے) رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے تو حضرت علی رضی اللہ عنہ نے فرمایا: میں آیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تو نے احرام کیسے باندھا ہے؟‘‘ میں نے عرض کیا: میں نے تو آپ کے احرام کی طرح احرام باندھا ہے۔ آپ نے فرمایا: ’’میں تو قربانی کے جانور بھی ساتھ لایا ہوں اور میں نے حج و عمرے کا اکٹھا احرام باندھا ہے۔‘‘ آپ صلی اللہ علیہ وسلم نے اپنے صحابہ سے فرمایا تھا: ’’اگر مجھے اس حکم کا پہلے پتا چل جاتا جس کا بعد میں پتا چلا (یعنی عمرے کے وجوب کا) تو میں اسی طرح کرتا جیسے تم نے کیا، لیکن میں تو قربانی کے جانور ساتھ لایا ہوں، لہٰذا میرا حج وعمرہ اکٹھا ہوگا۔‘‘","f2":"(۱) اس حدیث کی سند میں ابو اسحاق مدلس راوی ہے جو عن سے بیان کر رہا ہے لیکن اس کے صحیح شواہد موجود ہیں۔ جن کا محقق کتاب نے بھی ذکر کیا ہے۔ ان میں سے ایک شاہد حضرت علی رضی اللہ عنہ کی سابقہ حدیث بھی ہے، لہٰذا یہ حدیث شواہد کی بنا پر صحیح ہے اور ابو اسحاق کا عنعنہ یہاں مضر نہیں۔ واللہ اعلم۔ تفصیل کے لیے دیکھیے: (ذخیرۃ العقبیٰ شرح سنن النسائی: ۲۴/ ۱۵۹-۱۶۲) (۲) ’’کیسے احرام باندھا ہے؟‘‘ یعنی صرف حج کا یا صرف عمرے کا یا دونوں کا؟ (۲) ’’آپ کے احرام کی طرح۔‘‘ یعنی میں نے احرام باندھتے وقت کہا تھا کہ میرا احرام رسول اللہ صلی اللہ علیہ وسلم کے احرام کی طرح ہوگا۔ اگرچہ اس وقت انھیں علم نہ تھا۔ کہ رسول اللہ صلی اللہ علیہ وسلم نے احرام کیسے باندھا ہے لیکن چونکہ ان کے ساتھ بھی قربانی کے جانور تھے، لہٰذا عملاً بھی ان کا احرام رسول اللہ صلی اللہ علیہ وسلم کے احرام کی طرح ہوگیا۔ (۳) ’’میں اسی طرح کرتا۔‘‘ یعنی قربانی ساتھ نہ لاتا (بلکہ موقع پر خریدتا) اور عمرہ کر کے حلال ہو جاتا۔ (۴) ثابت ہوا تمتع اور قران شرعاً جائز ہیں، بلکہ تمتع افضل ہے اور آسانی کا باعث بھی۔"}],[2726,"مطرف کہتے ہیں کہ مجھ سے عمران بن حصین رضی اللہ عنہما نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے حج و عمرہ دونوں کو ایک ساتھ جمع کیا پھر اس سے پہلے کہ آپ اس سے منع فرماتے یا اس کے حرام ہونے کے سلسلے میں آپ پر کوئی آیت اترتی آپ کی وفات ہو گئی۔","الألباني: صحيح",{"u2":"حضرت عمران بن حصین رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے حج اور عمرہ اکٹھا کیا، پھر آپ فوت ہوگئے، نہ تو آپ نے (اس سے) روکا اور نہ قرآن میں اس کی حرمت کا حکم نازل ہوا۔"}],[2727,"عمران رضی اللہ عنہ سے روایت کہ رسول اللہ صلی اللہ علیہ وسلم نے حج اور عمرہ دونوں کو ایک ساتھ جمع کیا پھر اس سلسلے میں کوئی آیت نازل نہیں ہوئی اور نہ ہی ان دونوں کو جمع کرنے سے نبی اکرم صلی اللہ علیہ وسلم نے روکا، لیکن ایک شخص نے ان دونوں کے بارے میں اپنی رائے سے جو چاہا کہا ۱؎۔\n§وضاحت\n۱؎: اشارہ عمر رضی اللہ عنہ کی طرف سے، کیونکہ وہ حج و عمرہ دونوں کو جمع کرنے سے روکتے تھے، جیسے عثمان رضی اللہ عنہ روکتے تھے جیسا کہ امام مسلم نے اپنی صحیح ۲/۸۹۸ میں اس کی تصریح کی ہے۔","الألباني: صحيح",{"u2":"حضرت عمران رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے حج و عمرہ اکٹھا کیا، پھر (اس سے روکنے کے بارے میں) کوئی حکم نازل نہیں ہوا، نہ رسول اللہ صلی اللہ علیہ وسلم نے اس سے منع فرمایا۔ (بعد میں) ایک شخص (حضرت عمر رضی اللہ عنہ) نے اپنی رائے سے اس کے بارے میں جو چاہا، کیا۔","f2":"(۱) ایک شخص سے مراد حضرت عمر رضی اللہ عنہ ہیں کیونکہ وہ اس صورت سے روکا کرتے تھے۔ باقی بالتبع آتے ہیں۔ (۲) یہ حدیث دلیل ہے کہ قرآن کا حکم حدیث سے منسوخ ہو سکتا ہے۔"}],[2728,"مطرف بن عبداللہ کہتے ہیں کہ مجھ سے عمران بن حصین رضی اللہ عنہما نے کہا کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ (حج) تمتع کیا، ابوعبدالرحمٰن (نسائی)کہتے ہیں کہ اسماعیل بن مسلم نام کے تین لوگ ہیں، یہ اسماعیل بن مسلم (جو اس حدیث کے ایک راوی ہیں) انہیں تینوں میں سے ایک ہیں، ان سے روایت کرنے میں کوئی حرج نہیں ہے اور (دوسرے) اسماعیل بن مسلم ایک شیخ ہیں جو ابوالطفیل سے روایت کرتے ہیں ان سے بھی حدیث لینے میں کوئی حرج نہیں ہے۔ اور تیسرے اسماعیل بن مسلم ہیں جو زہری اور حسن سے روایت کرتے ہیں یہ متروک الحدیث ہیں۔","الألباني: صحيح",{"u2":"حضرت عمران بن حصین رضی اللہ عنہ بیان کرتے ہیں کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تمتع کیا۔\nامام ابو عبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ اسماعیل بن مسلم نام کے تین راوی حدیث ہیں۔ ان میں سے ایک تو یہی ہیں۔ ان پر کوئی اعتراض نہیں۔ دوسرے بزرگ وہ ہیں جو ابو الطفیل سے بیان کرتے ہیں۔ ان میں بھی کوئی خرابی نہیں۔ تیسرے اسماعیل بن مسلم حضرت زہری اور حضرت حسن سے بیان کرتے ہیں۔ وہ محدثین کے نزدیک متروک الحدیث (غیر معتبر) ہیں۔","f2":"اکثر صحابہ نے رسول اللہ صلی اللہ علیہ وسلم کے حکم سے تمتع کیا تھا۔ خود آپ نے قران فرمایا تھا، لہٰذا دونوں جائز ہیں۔ البتہ اس بات میں اختلاف ہے کہ ان میں سے افضل کون سا طریقہ ہے۔ (تفصیل ان شاء اللہ آگے آئے گی)"}],[2729,"انس رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو «لبيك عمرة وحجا لبيك عمرة وحجا» کہتے سنا ہے۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے مروی ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو [لَبَّیْکَ عُمْرَۃً وَّ حَجًّا] ’’اے اللہ! میں تیرے سامنے حج و عمرے کے لیے حاضر ہوں۔‘‘ فرماتے ہوئے سنا۔","f2":"معلوم ہوا آپ نے قران کیا تھا اور یہی صحیح ہے۔ آپ اس وقت یہی کر سکتے تھے۔ صرف حج، ابتدا میں تھا۔ تمتع کی ترغیب دی۔"}],[2730,"انس رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو (حج و عمرہ) دونوں کا تلبیہ پکارتے ہوئے سنا۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو حج اور عمرہ دونوں کی بیک وقت لبیک کہتے سنا۔"}],[2731,"انس رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو حج و عمرہ دونوں کا ایک ساتھ تلبیہ پکارتے ہوئے سنا ہے تو میں نے اسے ابن عمر رضی اللہ عنہما سے بیان کیا، تو انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے صرف حج کا تلبیہ پکارا تھا، پھر میری ملاقات انس سے ہوئی تو میں نے ان سے ابن عمر رضی اللہ عنہما کی بات بیان کی، اس پر انس رضی اللہ عنہ نے کہا: تم لوگ ہمیں بچہ ہی سمجھتے ہو، میں نے رسول اللہ صلی اللہ علیہ وسلم کو ایک ساتھ «لبيك عمرة وحجا» کہتے ہوئے سنا ہے۔","الألباني: صحيح",{"u2":"حضرت بکر بن عبداللہ مزنی رحمہ اللہ نے بیان کیا کہ میں نے حضرت انس رضی اللہ عنہ کو فرماتے سنا: میں نے نبی صلی اللہ علیہ وسلم کو عمرہ وحج کی اکٹھی لبیک فرماتے سنا۔ میں نے یہ بات حضرت ابن عمر رضی اللہ عنہ سے بیان کی تو وہ کہنے لگے: آپ نے صرف حج کی لبیک کہی تھی۔ میں پھر حضرت انس رضی اللہ عنہ کو ملا اور ان سے حضرت ابن عمر رضی اللہ عنہ کی بات بیان کی۔ آپ فرمانے لگے: تم ہمیں بچے ہی سمجھتے ہو۔ میں نے خود رسول اللہ صلی اللہ علیہ وسلم کو [لَبَّیْکَ عُمْرَۃً وَّ حَجًّا مَعًا] فرماتے سنا ہے۔","f2":"(۱) حضرت ابن عمر رضی اللہ عنہ ابتدائی حالت بیان کرتے ہیں اور حضرت انس رضی اللہ عنہ آخری۔ ظاہر ہے آخری بات ہی معتبر ہوتی ہے۔ (۲) ’’تم ہمیں بچے ہی سمجھتے ہو۔‘‘ یعنی گویا ہم نے بچوں کی طرح معاملہ ضبط نہیں کیا۔ ویسے حجۃ الوداع کے موقع پر حضرت انس رضی اللہ عنہ بیس سال کے تھے۔ تقریباً یہی عمر حضرت ابن عمر رضی اللہ عنہ کی تھی۔ اور بیس سال کی عمر والے کو بچہ نہیں کہتے۔"}],[2732,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے حجۃ الوداع میں تمتع کیا ۱؎ یعنی پہلے عمرہ کیا پھر حج کیا اور ہدی بھیجی، بلکہ اپنے ساتھ ذوالحلیفہ سے ہدی لے گئے (وہاں) رسول اللہ صلی اللہ علیہ وسلم نے پہلے عمرہ کا تلبیہ پکارا پھر حج کا تلبیہ پکارا اور رسول اللہ صلی اللہ علیہ وسلم کے ساتھ لوگوں نے بھی تمتع کیا، یعنی عمرے کا احرام باندھا پھر حج کا۔ البتہ ان میں کچھ ایسے لوگ بھی تھے جنہوں نے ہدی بھیجی اور اپنے ساتھ بھی لیے گئے، اور کچھ لوگ ایسے تھے جو ہدی نہیں لے گئے تھے۔ تو جب رسول اللہ صلی اللہ علیہ وسلم مکہ پہنچ گئے تو آپ نے لوگوں سے فرمایا: \"جو لوگ اپنے ساتھ ہدی لے کر آئے ہیں وہ جب تک حج پورا نہ کر لیں کسی بھی چیز سے جو ان پر حرام ہیں حلال نہ ہو) اور جو ہدی ساتھ لے کر نہیں آئے ہیں تو وہ خانہ کعبہ کا طواف کریں اور صفا و مروہ کی سعی کریں، اور بال کتروائیں اور احرام کھول ڈالیں۔ پھر (اٹھویں ذی الحجہ کو) حج کا احرام باندھے پھر ہدی دے اور جسے ہدی میسر نہ ہو تو وہ حج میں تین دن روزے رکھے، اور سات دن اپنے گھر واپس پہنچ جائیں تب رکھیں\"، چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے مکہ پہنچ کر طواف کیا، اور سب سے پہلے حجر اسود کا بوسہ لیا پھر سات پھیروں میں سے پہلے تین پھیروں میں دوڑ کر چلے ۲؎، باقی چار پھیرے عام رفتار سے چلے۔ پھر جس وقت بیت اللہ کا طواف پورا کر لیا، تو مقام ابراہیم کے پاس دو رکعتیں پڑھیں پھر سلام پھیرا۔ اور نماز سے فارغ ہو کر صفا آئے اور صفا اور مروہ کے درمیان سات پھیرے کیے۔ پھر جو چیزیں حرام ہو گئی تھیں ان میں سے کسی چیز سے بھی حلال نہیں ہوئے یہاں تک کہ اپنے حج کو مکمل کیا اور یوم النحر (دسویں ذی الحجہ) کو اپنے ہدی کی نحر کی (جانور ذبح کئے) اور منی سے لوٹ کر مکہ آئے، پھر خانہ کعبہ کا طواف کیا پھر جو چیزیں حرام ہو گئی تھیں ان سب سے حلال ہو گئے، اور لوگوں میں سے جو ہدی (کا جانور) لے کر گئے تھے، انہوں نے بھی ویسے ہی کیا جیسے رسول اللہ صلی اللہ علیہ وسلم نے کیا۔\n§وضاحت\n۱؎: یعنی حج و عمرہ دونوں کو ایک ساتھ کرنے کا فائدہ اٹھایا یہاں تمتع سے لغوی تمتع مراد ہے نہ کہ اصطلاحی کیونکہ یہ بات ثابت ہے کہ رسول اللہ صلی اللہ علیہ وسلم حجۃ الوداع میں قارن تھے۔ ۲؎: یعنی مونڈھے ہلاتے ہوئے تیز چال سے چلے اسے رمل کہتے ہیں۔","الألباني: صحيح ق لكن قوله وبدأ رسول الله صلی اللہ علیہ وسلم فأهل بالعمرة ثم أهل بالحج شاذ",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے حجۃ الوداع میں حج سے پہلے عمرے کا فائدہ اٹھایا تھا اور قربانی بھی کی تھی۔ آپ ذوالحلیفہ ہی سے اپنے ساتھ قربانی کے جانور لے کرچلے تھے۔ رسول اللہ صلی اللہ علیہ وسلم نے پہلے عمرے کی لبیک پکاری، پھر حج کی لبیک پکاری۔ اور لوگوں نے بھی رسول اللہ صلی اللہ علیہ وسلم کے ساتھ حج سے پہلے عمرہ کرنے کا فائدہ اٹھایا۔ کچھ لوگ قربانی کے جانور ساتھ لائے تھے، کچھ نہیں لائے تھے۔ جب رسول اللہ صلی اللہ علیہ وسلم مکہ مکرمہ میں داخل ہونے کے قریب تھے، آپ نے لوگوں سے فرمایا: ’’تم میں سے جو شخص قربانی لایا ہے، اس پر کوئی حرام چیز حلال نہیں ہوگی (اس کا احرام ختم نہیں ہوگا) حتیٰ کہ وہ اپنا حج پورا کرے۔ اور جو شخص قربانی کا جانور نہیں لایا، وہ بیت اللہ کا طواف کرے، صفا مروہ کی سعی کرے اور بال کٹوا کر حلال ہو جائے، پھر (حج کے دنوں میں) حج کا احرام باندھے۔ اور پھر قربانی بھی ذبح کرے۔ اور اگر وہ قربانی کی طاقت نہ رکھتا ہو تو وہ دوران حج تین روزے رکھے اور جب اپنے گھر واپس جائے تو سات روزے رکھے۔‘‘ رسول اللہ صلی اللہ علیہ وسلم جب مکہ مکرمہ تشریف لائے تو آپ نے طواف فرمایا۔ سب سے پہلے حجر اسود کو بوسہ دیا، پھر طواف کے ساتھ چکروں میں سے پہلے تین چکر قدرے دوڑ کر پورے کیے اور باقی چار چکر آرام سے چلے، پھر جب بیت اللہ کا طواف پورا فرما لیا تو مقام ابراہیم کے پاس دو رکعت نماز پڑھی، پھر سلام پھیر کر مڑے اور صفا پر آئے اور صفا مروہ کے بھی سات چکر لگائے، پھر آپ کسی حرام چیز سے حلال نہ ہوئے حتیٰ کہ آپ نے اپنا حج پورا فرمایا اور نحر (دس ذی الحجہ) والے دن اپنے قربانی کے جانور ذبح فرمائے اور واپس آکر بیت اللہ کا طواف فرمایا، پھر آپ پر ہر وہ چیز حلال ہوگئی جو (احرام کی وجہ سے) حرام ہوئی تھی۔ جو لوگ قربانی کے جانور ساتھ لائے تھے، انھوں نے بھی ایسے ہی کیا جیسے رسول اللہ صلی اللہ علیہ وسلم نے کیا تھا۔","f2":"(۱) حج تمتع کے جواز میں کوئی اختلاف نہیں۔ اختلاف اس بات میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے حج تمتع فرمایا یا قران؟ صحیح بات یہ ہے کہ آپ نے قران فرمایا تھا۔ اور تمتع، قران کو بھی کہہ سکتے ہیں کیونکہ لغوی طور پر تمتع کے معنی فائدہ اٹھانا ہیں۔ تمتع اور قران دونوں میں حج کے ساتھ عمرے کا فائدہ اٹھایا جاتا ہے، لہٰذا دونوں کو لغوی طور پر تمتع کہا جا سکتا ہے ورنہ اصل تمتع یہی ہے کہ عمرہ کر کے حلال ہو، پھر الگ احرام کے ساتھ حج کرے۔ اس حدیث میں بھی تمتع لغوی معنی میں استعمال ہوا ہے۔ (۲) ’’پہلے عمرے کی لبیک پکاری‘‘ یہ بات مشہور روایات کے خلاف ہے۔ سابقہ روایت میں حضرت ابن عمر رضی اللہ عنہ ہی سے بیان ہے کہ آپ نے حج کی لبیک پکاری۔ صحیح یہ ہے کہ آپ نے حج پر عمرہ داخل فرمایا۔ (۳) ہر حرام چیز حلال ہونے سے مراد احرام کا ختم ہوناہے۔"}],[2733,"سعید بن مسیب کہتے ہیں: علی اور عثمان رضی اللہ عنہما نے حج کیا تو جب ہم راستے میں تھے تو عثمان رضی اللہ عنہ نے تمتع سے منع کیا، علی رضی اللہ عنہ نے کہا: جب تم لوگ انہیں دیکھو کہ وہ (عثمان) کوچ کر گئے ہیں تو تم لوگ بھی کوچ کرو، علی رضی اللہ عنہ اور ان کے ساتھیوں نے عمرہ کا تلبیہ پکارا (یعنی تمتع کیا) تو عثمان رضی اللہ عنہ نے انہیں منع نہیں کیا، علی رضی اللہ عنہ نے کہا: کیا مجھے یہ اطلاع نہیں دی گئی ہے کہ آپ تمتع سے روکتے ہیں؟ انہوں نے کہا: کیوں نہیں (صحیح اطلاع دی ہے) تو علی رضی اللہ عنہ نے ان سے کہا: کیا آپ نے سنا نہیں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے تمتع کیا ہے؟ انہوں نے کہا: کیوں نہیں، ضرور سنا ہے ۱؎۔\n§وضاحت\n۱؎: اس بات چیت کا خلاصہ یہ ہے کہ عمر اور عثمان رضی اللہ عنہما دونوں کی رائے یہ تھی کہ نبی اکرم صلی اللہ علیہ وسلم کے وقت میں لوگوں نے جو تمتع کیا اس کی کوئی خاص وجہ تھی، اور اب اس کا نہ کرنا افضل ہے، اس کے برخلاف علی رضی اللہ عنہ کی رائے یہ تھی کہ یہی سنت اور افضل ہے :(واللہ تعالی اعلم )۔","الألباني: صحيح",{"u2":"حضرت سعید بن مسیب بیان کرتے ہیں کہ حضرت علی اور حضرت عثمان رضی اللہ عنہ دونوں حج کو گئے۔ ابھی راستے ہی میں تھے کہ حضرت عثمان رضی اللہ عنہ نے (بحیثیت خلیفہ) تمتع سے منع فرما دیا۔ حضرت علی رضی اللہ عنہ فرمانے لگے: جب تم حضرت عثمان کو کوچ کرتے دیکھو تو تم بھی ساتھ ہی کوچ کرنا۔ حضرت علی اور ان کے دوسرے ساتھیوں نے (کوچ کے وقت) عمرے کی لبیک (بلند آواز سے) کہی تو حضرت عثمان رضی اللہ عنہ نے انھیں نہ روکا۔ حضرت علی رضی اللہ عنہ نے (حضرت عثمان رضی اللہ عنہ سے) کہا: مجھے تو بتایا گیا تھا کہ آپ تمتع سے روکتے ہیں؟ حضرت عثمان رضی اللہ عنہ نے فرمایا: ضرور۔ حضرت علی رضی اللہ عنہ نے فرمایا: کیا آپ کو علم نہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے تمتع فرمایا۔ انھوں نے کہا: کیوں نہیں؟","f2":"’’تمتع فرمایا‘‘ یعنی اجازت دی یا لغوی معنی میں تمتع فرمایا۔ باقی تفصیل پیچھے گزر چکی ہے۔ حضرت علی رضی اللہ عنہ کی جلالت قدر اور اپنی طبعی نرمی کی وجہ سے حضرت عثمان رضی اللہ عنہ نے انھیں اپنے حکم پر مجبور نہیں فرمایا ورنہ حضرت عمر رضی اللہ عنہ کے دور میں کسی کو مخالفت کی جرأت نہ ہوئی۔ وہ بھی تمتع سے روکتے تھے۔"}],[2734,"محمد بن عبداللہ بن حارث بن عبدالمطلب کہتے ہیں کہ انہوں نے سعد بن ابی وقاص اور ضحاک بن قیس رضی اللہ عنہما کو جس سال معاویہ بن ابی سفیان رضی اللہ عنہما نے حج کیا تمتع کا یعنی عمر رضی اللہ عنہ کے بعد حج کرنے کا ذکر کرتے سنا، ضحاک رضی اللہ عنہ نے کہا: اسے وہی کرے گا، جو اللہ کے حکم سے ناواقف ہو گا، اس پر سعد رضی اللہ عنہ نے کہا: میرے بھتیجے! بری بات ہے، جو تم نے کہی، تو ضحاک رضی اللہ عنہ نے کہا: عمر بن خطاب رضی اللہ عنہ نے تو اس سے روکا ہے اس پر سعد رضی اللہ عنہ نے کہا: اسے رسول اللہ صلی اللہ علیہ وسلم نے کیا ہے اور آپ کے ساتھ ہم لوگوں نے بھی کیا ہے۔","الألباني: ضعيف الإسناد",{"u2":"حضرت محمد بن عبداللہ بن حارث بیان کرتے ہیں کہ میں نے حضرت سعد بن ابی وقاص رضی اللہ عنہ اور ضحاک بن قیاس کو حج سے پہلے عمرے کا فائدہ اٹھانے کا تذکرہ کرتے سنا۔ یہ اس سال کی بات ہے جس سال حضرت معاویہ بن ابی سفیان رضی اللہ عنہ حج کے لیے تشریف لائے تھے۔ ضحاک کہنے لگے: یہ کام (تمتع) تو وہی کر سکتا ہے جو اللہ تعالیٰ کے احکام سے ناواقف ہو۔ حضرت سعد فرمانے لگے: اے بھتیجے! تو نے بری بات کہی ہے۔ ضحاک نے کہا: حضرت عمر بن خطاب رضی اللہ عنہ نے تو اس سے روکا تھا۔ سعد رضی اللہ عنہ فرمانے لگے: یہ اللہ کے رسول نے کیا ہے اور ہم نے بھی آپ کے ساتھ کیا تھا۔","f2":"(۱) حضرت عمر رضی اللہ عنہ کے حکم سے بہت سے لوگوں کو غلط فہمی ہوئی اور انھوں نے اسے شرعی امر سمجھ لیا، مگر صحابہ نے اور بعد میں ائمہ کرام نے وضاحت کی تمتع شرعاً جائز ہے بلکہ بہت سے ائمہ کے نزدیک افضل ہے۔ (۲) حاکم وقت یا کسی کی بھی بات شریعت کے خلاف ہو اور اس کی تردید مقصود ہو تو احسن انداز میں کرنی چاہیے جو زیادہ مؤثر ہو اور س میں وہ اپنی ہتک محسوس نہ کرے۔"}],[2735,"ابوموسی اشعری رضی اللہ عنہ سے روایت ہے کہ وہ تمتع کا فتوی دیتے تھے، تو ایک شخص نے ان سے کہا: آپ اپنے بعض فتاوے کو ملتوی رکھیں ۱؎ آپ کو امیر المؤمنین (عمر بن خطاب رضی اللہ عنہ) نے اس کے بعد حج کے سلسلے میں جو نیا حکم جاری کیا ہے وہ معلوم نہیں، یہاں تک کہ میں ان سے ملا، اور میں نے ان سے پوچھا، تو عمر رضی اللہ عنہ نے کہا: مجھے معلوم ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ایسا کیا ہے، لیکن میں یہ اچھا نہیں سمجھتا کہ لوگ «اراک» میں اپنی بیویوں سے ہمبستر ہوں، پھر وہ صبح ہی حج کے لیے اس حال میں نکلیں کہ ان کے سروں سے پانی ٹپک رہا ہو۔\n§وضاحت\n۱؎: کیونکہ ہو سکتا ہے کہ آپ کا یہ فتوی امیر المؤمنین کے جاری کردہ حکم کے خلاف ہو اور وہ تم پر ناراض ہوں۔","الألباني: صحيح",{"u2":"حضرت ابو موسیٰ اشعری رضی اللہ عنہ تمتع کے جواز کا فتویٰ دیا کرتے تھے۔ ایک آدمی نے ان سے کہا: اس قسم کا فتویٰ دینے سے رک جاؤ۔ شاید آپ کو پتا نہیں کہ تمھارے بعد امیرالمومنین (حضرت عمر رضی اللہ عنہ) نے اس کے بارے میں کیا نیا حکم جاری فرمایا ہے۔ (حضرت ابو موسیٰ نے کہا:) میں حضرت عمر رضی اللہ عنہ سے ملا تو میں نے ان سے پوچھا۔ وہ فرمانے لگے: تحقیق! مجھے بھی معلوم ہے کہ نبی صلی اللہ علیہ وسلم نے یہ کیا ہے مگر میں نے اچھا نہ سمجھا کہ لوگ رات کو پیلو کے درختوں کے نیچے بیویوں کے ساتھ جماع کرتے رہیں اور پھر حج کو جائیں تو ان کے سروں سے (غسل جنابت کے) پانی کے قطرے گر رہے ہوں۔","f2":"(۱) اس روایت سے حقیقت حال واضح ہو جاتی ہے کہ حضرت عمر رضی اللہ عنہ اسے شرعاً جائز سمجھتے تھے مگر مذکورہ علت کی وجہ سے حج تمتع کو بہتر نہ سمجھا جو کہ آپ کی ایک اجتہادی غلطی تھی، تاہم درست یہی ہے کہ حج تمتع افضل ہے۔ واللہ اعلم (۲) ’’نبی اکرم صلی اللہ علیہ وسلم نے یہ کیا ہے۔‘‘ یعنی آپ نے یہ حکم دیا تھا ورنہ آپ حلال نہ ہوئے تھے۔ یا لغوی معنی میں آپ نے تمتع کیا ہے۔ اور اس معنی میں تو حضرت عمر بھی تمتع (قران) کو ناپسند نہیں فرماتے تھے۔ (۳) ’’پیلو کے درختوں کے نیچے‘‘ ان دنوں وہاں یہ درخت عام ہوں گے، اس لیے اتفاقاً ان کا ذکر فرمایا۔"}],[2736,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ میں نے عمر رضی اللہ عنہ کو کہتے ہوئے سنا: قسم اللہ کی! میں تمہیں متعہ سے یعنی حج میں عمرہ کرنے سے روک رہا ہوں، حالانکہ وہ کتاب اللہ میں موجود ہے، اور رسول اللہ صلی اللہ علیہ وسلم نے اسے کیا ہے۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے مروی ہے کہ میں نے حضرت عمر رضی اللہ عنہ کو فرماتے سنا کہ اللہ کی قسم! میں تمھیں تمتع سے روکتا ہوں، حالانکہ میں جانتا ہوں کہ اس کا ذکر اللہ کا کتاب میں ہے اور اللہ کے رسول صلی اللہ علیہ وسلم نے یہ کیا ہے، یعنی حج سے پہلے عمرہ کرنا۔","f2":"’’یعنی حج سے پہلے عمرہ کرنا۔‘‘ یہ وضاحت اس لیے کی گئی کہ لفظ تمتع کے دوسرے معنی عورتوں سے متعہ کرنا ہے اور وہ حرام ہے۔ کوئی شخص وہ معنی مراد لے کر کہیں اسے جائز نہ سمجھ لے یا جواز کی نسبت حضرت عمر یا حضرت ابن عباس رضی اللہ عنہم کی طرف نہ کر دے جیسا کہ بعض لوگوں کو غلط فہمی ہوئی۔"}],[2737,"طاؤس کہتے ہیں کہ معاویہ رضی اللہ عنہ نے ابن عباس رضی اللہ عنہما سے کہا: کیا آپ کو معلوم ہے کہ مروہ کے پاس میں نے رسول اللہ صلی اللہ علیہ وسلم کے بال کترے تھے (میں یہ اس لیے بیان کر رہا ہوں تاکہ) ابن عباس رضی اللہ عنہما یہ نہ کہہ سکیں کہ یہ معاویہ ہیں جو لوگوں کو تمتع سے روکتے ہیں حالانکہ نبی اکرم صلی اللہ علیہ وسلم نے تمتع کیا ہے ۱؎۔\n§وضاحت\n۱؎: یہاں روایت میں ایک اشکال ہے اس روایت سے معلوم ہوتا ہے کہ حجۃ الوداع میں رسول اللہ صلی اللہ علیہ وسلم متمتع تھے حالانکہ صحیح یہ ہے کہ آپ قارن تھے، آپ نے اپنے بال میں سے کوئی چیز نہیں کتروائی اور نہ کوئی چیز اپنے لیے حلال کی یہاں تک کہ یوم النحر کو منی میں آپ نے حلق کرائی اس لیے اس کی تاویل یہ کی جاتی ہے کہ شاید حج سے معاویہ کی مراد عمرہ جعرانہ ہو کیونکہ اسی موقع پروہ اسلام لائے تھے۔","الألباني: صحيح ق دون قول ابن عباس هذا معاوية",{"u2":"حضرت طاؤس سے منقول ہے کہ حضرت معاویہ رضی اللہ عنہ نے حضرت ابن عباس رضی اللہ عنہ سے پوچھا: کیا آپ کو پتا ہے کہ میں نے مروہ کے پاس رسول اللہ صلی اللہ علیہ وسلم کے سر کے بال کاٹے تھے؟ ابن عباس رضی اللہ عنہ نے کہا: نہیں۔ ابن عباس رضی اللہ عنہ فرماتے ہیں کہ یہ معاویہ رضی اللہ عنہ لوگوں کو تمتع سے روکتے ہیں، حالانکہ نبی صلی اللہ علیہ وسلم نے تمتع کیا تھا۔","f2":"(۱) مروہ پر سر کے بال کاٹنا کسی عمرے ہی کے موقع پر ہو سکتا ہے کیونکہ حجۃ الوداع میں تو آپ نے حجامت منیٰ میں بنوائی تھی، پھر یہ عمرہ جعرانہ کی بات ہوگی جو ۸ ہجری میں فتح مکہ کے بعد ہوا۔ امام نووی اور ابن القیمL وغیرہ نے اسے اس پر محمول کیا ہے۔ اس وقت تک حضرت معاویہ رضی اللہ عنہ مسلمان ہو چکے تھے اور اس بات پر اتفاق ہے کہ رسول اللہ صلی اللہ علیہ وسلم حجۃ الوداع میں عمرہ کر کے حلال نہیں ہوئے بلکہ حج کے بعد حلال ہوئے تھے۔ (۲) ’’ابن عباس نے کہا: نہیں۔‘‘ یعنی میں نہیں جانتا۔ لیکن صحیح مسلم کی روایت میں ابن عباس رضی اللہ عنہ کے الفاظ یہ ہیں: [لَاأَعْلَمُ ھِٰہِ اِلَّا حُجّقۃً عَلَیْکَ] (صحیح مسلم، الحج، حدیث: ۱۲۴۶) میں تو اسے آپ کے موقف کے خلاف سمجھتا ہوں کیونکہ آپ تمتع سے روکتے ہیں۔ اور مروہ پر آپ کا رسول اللہ صلی اللہ علیہ وسلم کی حجامت بنانا دلیل ہے کہ رسول اللہ صلی اللہ علیہ وسلم عمرے کے بعد حلال ہوئے تھے، لہٰذا رسول اللہ صلی اللہ علیہ وسلم کا حج تمتع ہوا تو پھر تم کیوں روکتے ہو؟ باب والی روایت کے آخری الفاظ بھی اسی معنی (صحیح مسلم والی روایت کے معنی) کی تائید کرتے ہیں۔ گویا حضرت ابن عباس رضی اللہ عنہ نے حضرت معاویہ رضی اللہ عنہ کے حجامت بنانے والے واقعے کو حجۃ الوداع سے قبل عمرے پر محمول کیا ہے۔ مگر صریح روایات میں ان کے خلاف ہیں، اس لیے بعض محققین نے مروہ پر حجامت بنانے کو حضرت معاویہ رضی اللہ عنہ کی غلط فہمی یا نسیان وخطا پر محمول کیا ہے۔ واللہ اعلم (۳) حضرت معاویہ رضی اللہ عنہ کا تمتع سے روکنا حضرت عمر اور حضرت عثمان رضی اللہ عنہ کی اقتدا کے طور پر تھا۔ (۴) خلاف سنت کام کی تردید ضروری ہے چاہے کرنے والا کوئی بھی ہو کیونکہ حق سب سے بڑا ہے۔"}],[2738,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، آپ بطحاء میں تھے۔ آپ نے فرمایا: \"تم نے کس چیز کا تلبیہ پکارا ہے؟\" میں نے عرض کیا: میں نے نبی اکرم صلی اللہ علیہ وسلم کے تلبیہ پر تلبیہ پکارا ہے، پوچھا: \"کیا تم کوئی ہدی لے کر آئے ہو\"، میں نے کہا: نہیں، آپ نے فرمایا: خانہ کعبہ کا طواف کرو اور صفا و مروہ کے درمیان سعی کرو پھر احرام کھول کر حلال ہو جاؤ\"، تو میں نے خانہ کعبہ کا طواف کیا، صفا و مروہ کے درمیان سعی کی، پھر میں اپنے خاندان کی ایک عورت کے پاس آیا تو اس نے میرے بالوں میں کنگھی کی اور میرا سر دھویا۔ چنانچہ میں ابوبکر اور عمر رضی اللہ عنہما کی خلافت میں لوگوں کو اسی کا فتوی دیتا رہا۔(ایک بار ایسا ہوا کہ) میں حج کے موسم میں کھڑا تھا کہ یکایک ایک شخص میرے پاس آ کر کہنے لگا: آپ اس چیز کو نہیں جانتے جو امیر المؤمنین نے حج کے سلسلے میں نیا حکم دیا ہے؟ تو میں نے کہا: لوگو! میں نے جس کسی کو بھی کوئی فتوی دیا ہو وہ اس پر عمل کرنے میں ذرا توقف کرے، کیونکہ امیر المؤمنین تمہارے پاس آنے والے ہیں، تو وہ جو فرمائیں اس کی پیروی کرو۔ تو جب وہ آئے تو میں نے کہا: امیر المؤمنین! یہ کیا ہے جو حج کے سلسلے میں آپ نے نئی بدعت نکالی ہے؟ انہوں نے کہا: اگر ہم کتاب اللہ پر عمل کریں تو اللہ عزوجل نے فرمایا ہے: «وأتموا الحج والعمرة لله» اور اگر ہم اپنے نبی اکرم صلی اللہ علیہ وسلم کی سنت کی پیروی کریں، تو آپ حلال نہیں ہوئے جب تک کہ آپ نے ہدی کی قربانی نہیں کر لی۔","الألباني: صحيح",{"u2":"حضرت ابو موسیٰ رضی اللہ عنہ بیان کرتے ہیں کہ میں (یمن سے) رسول اللہ صلی اللہ علیہ وسلم کے پاس (حجۃ الوداع کے موقع پر) بطحاء میں حاضر ہوا تو آپ نے فرمایا: ’’تو نے کیا احرام باندھا ہے؟‘‘ میں نے کہا: میں نے تو نبی صلی اللہ علیہ وسلم کے احرام کی طرح احرام باندھا ہے۔ آپ نے فرمایا: ’’قربانی کا کوئی جانور ساتھ لایا ہے؟‘‘ میں نے کہا: نہیں۔ آپ نے فرمایا: ’’پھر بیت اللہ کا طواف کر اور صفا مروہ کی سعی کر اور حلال ہو جا۔‘‘ میں نے بیت اللہ کا طواف کیا۔ صفا مروہ کی سعی کی، پھر میں اپنی قوم کی ایک عورت کے پاس آیا۔ اس نے میرے سر میں کنگھی کی اور میرا سر دھویا۔ میں حضرت ابوبکر اور حضرت عمر رضی اللہ عنہ کے دور میں یہی فتویٰ دیا کرتا تھا (کہ حج تمتع جائز ہے)۔ ایک دفعہ میں موسم حج میں کھڑا (یہ فتویٰ دے رہا) تھا کہ میرے پاس ایک آدمی آیا اور کہنے لگا: شاید آپ کو معلوم نہیں کہ امیر المومنین (حضرت عمر) رضی اللہ عنہ نے حج کے بارے میں ایک نیا حکم جاری کر دیا ہے (کہ تمتع قسم کا) کوئی فتویٰ دیا ہے، وہ ذرا ٹھہر جائے (اس پر عمل نہ کرے) حضرت امیرالمومنین تمہارے پاس آنے ہی والے ہیں تو ان کی اقتدا کرنا۔ جب حضرت عمر رضی اللہ عنہ تشریف لائے تو میں نے عرض کیا: امیرالمومنین! کیا (عجیب) حکم ہے جو آپ نے حج کے بارے میں جاری کیا ہے؟ وہ فرمانے لگے: ’’حج اور عمرہ اللہ تعالیٰ کے لیے پورا کرو۔‘‘ (یعنی درمیان حلال نہ ہو) اور اگر ہم نبی صلی اللہ علیہ وسلم کی سنت کو لیں تو نبی صلی اللہ علیہ وسلم حلال نہیں ہوئے تھے حتیٰ کہ آپ نے قربانی ذبح فرمائی۔","f2":"(۱) ’’نبی صلی اللہ علیہ وسلم کے احرام کی طرح‘‘ یعنی میں نے احرام باندھتے وقت کہا تھا کہ میں احرام باندھتا ہوں نبی صلی اللہ علیہ وسلم کے احرام کی طرح۔ ورنہ انھیں اس وقت پتا نہ تھا کہ نبی صلی اللہ علیہ وسلم نے کیا احرام باندھا ہے۔ (۲) حضرت ابو موسیٰ رضی اللہ عنہ کو خود نبی اکرم صلی اللہ علیہ وسلم نے یمن بھیجا تھا کیونکہ یہ بھی یمنی تھے، پھر یہ حجۃ الوداع کی اطلاع پر یمن سے مکہ پہنچے۔ (۳) حضرت عمر رضی اللہ عنہ کا استدلال یہ ہے کہ قرآن مجید بھی اتمام کا حکم دیتا ہے۔ ظاہر ہے حج کی نیت رکھنے والے کا عمرہ کر کے حلال ہو جانا حج کے اتمام کے خلاف ہے کیونکہ ابھی حج تو ہوا ہی نہیں، وہ حلال بھی ہوگیا۔ ہاں جو آدمی جائے ہی عمرے کی نیت سے، وہ عمرے کا احرام باندھے اور عمرہ کر کے حلال ہو مگر حج کی نیت والا عمرے کا احرام کیوں باندھے؟ اور رسول اللہ صلی اللہ علیہ وسلم نے بھی حج ہی کا احرام باندھا تھا۔ باوجود عمرہ داخل ہونے کے پھر بھی حلال حج کی تکمیل کے بعد ہی ہوئے تھے۔ باقی رہا آپ کا صحابہ کو یہ حکم دینا کہ حج کے احرام کو عمرے کے احرام میں بدل کر عمرہ کر کے حلال ہو جاؤ، یہ مخصوص حکم تھا جو مخصوص حالت میں وحی کی بنا پر ہنگامی طور پر جاری کیا گیا۔ یہ ہمیشہ کے لیے ہے، لہٰذا جو حج کرنا چاہتا ہے وہ حج ہی کا احرام باندھے یا پھر حج اور عمرے کا اکٹھا احرام باندھے اور حج کی تکمیل کے بعد ہی احرام ختم کرے۔ سیدنا عمر فاروق رضی اللہ عنہ کے اس اجتہاد میں کوئی شک نہیں لیکن صاحب قرآن کا عمل اور تمتع کے لیے آپ کا حکم یقینا مقدم ہے کیونکہ آپ ہی شارع ہیں، نیز یہ کوئی وقتی حکم نہ تھا جیسا کہ سیدنا عمر و غیرہ نے سمجھا بلکہ یہ استحباب ہمیشہ کے لیے ہے جیسا کہ ایک سائل کے جواب میں آپ صلی اللہ علیہ وسلم نے فرمایا کہ عمرہ حج میں تا قیامت داخل ہوگیا۔ اس سے تخصیص کا موقف کمزور ٹھہرتا ہے۔ واللہ اعلم"}],[2739,"مطرف کہتے ہیں کہ مجھ سے عمران بن حصین رضی اللہ عنہما نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے (حج) تمتع کیا، اور ہم نے بھی آپ کے ساتھ (حج) تمتع کیا(لیکن) کہنے والے نے اس سلسلے میں اپنی رائے سے کہا ۱؎۔\n§وضاحت\n۱؎: لہٰذا صریح سنت کے مقابلہ میں قائل کی رائے کا کوئی اعتبار نہیں۔","الألباني: صحيح",{"u2":"حضرت مطرف فرماتے ہیں کہ حضرت عمران بن حصین رضی اللہ عنہ نے مجھ سے کہا: رسول اللہ صلی اللہ علیہ وسلم نے تمتع فرمایا۔ ہم نے بھی آپ کے ساتھ تمتع کیا، پھر ایک کہنے والے نے اپنی رائے سے کہا (کہ تمتع نہیں کرنا چاہیے)۔"}],[2740,"ابو جعفر محمد بن علی باقر کہتے ہیں کہ ہم جابر بن عبداللہ رضی اللہ عنہما کے پاس آئے، اور ہم نے ان سے نبی اکرم صلی اللہ علیہ وسلم کے حج کے متعلق پوچھا، تو انہوں نے ہم سے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نو سال تک مدینہ میں رہے پھر لوگوں میں اعلان کیا گیا کہ امسال رسول اللہ صلی اللہ علیہ وسلم حج کو جانے والے ہیں، تو بہت سارے لوگ مدینہ آ گئے، سب یہ چاہتے تھے کہ وہ رسول اللہ صلی اللہ علیہ وسلم کی اقتداء کریں اور وہی کریں جو آپ کرتے ہیں۔ تو جب ذی قعدہ کے پانچ دن باقی رہ گئے تو رسول اللہ صلی اللہ علیہ وسلم حج کے لیے نکلے اور ہم بھی آپ کے ساتھ نکلے۔ رسول اللہ صلی اللہ علیہ وسلم ہمارے درمیان تھے آپ پر قرآن اتر رہا تھا اور آپ اس کی تاویل (تفسیر) جانتے تھے اور جو چیز بھی آپ نے کی ہم نے بھی کی۔ چنانچہ ہم نکلے ہمارے پیش نظر صرف حج تھا۔","الألباني: صحيح",{"u2":"حضرت محمد (باقر) رحمہ اللہ بیان کرتے ہیں کہ ہم حضرت جابر بن عبداللہ رضی اللہ عنہ کے پاس آئے اور ان سے نبی صلی اللہ علیہ وسلم کے حج کے بارے میں پوچھا تو انھوں نے بیان فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم کو مدینے میں رہتے ہوئے نو سال ہو چکے تھے، پھر (دسویں سال) تمام لوگوں میں اعلان کر دیا گیا کہ اس سال رسول اللہ صلی اللہ علیہ وسلم حج کے لیے تشریف لے جائیں گے، لہٰذا بہت زیادہ لوگ مدینہ منورہ آگئے۔ ہر ایک کی خواہش تھی کہ وہ رسول اللہ صلی اللہ علیہ وسلم کی اقتدا میں حج کرے اور جس طرح آپ حج کریں، وہ بھی اسی طرح کرے۔ رسول اللہ صلی اللہ علیہ وسلم حج کے لیے نکلے تو ذوالقعدہ کے پانچ دن باقی تھے۔ ہم بھی آپ کے ساتھ نکلے۔ رسول اللہ صلی اللہ علیہ وسلم ہمارے درمیان تھے۔ آپ پر وحی اترتی تھی اور آپ ہی قرآن مجید کی صحیح تفسیر جانتے تھے، لہٰذا جو آپ نے کیا، ہم نے بھی کیا۔ ہم (مدینہ منورہ سے) نکلے تو ہماری نیت حج ہی کی تھی۔","f2":"(۱) ’’نو سال‘‘ آپ نے اس دوران میں عمرے تو تین کیے مگر حج نہیں فرمایا۔ (۲) ’’اعلان کروایا گیا۔‘‘ تاکہ تمام موجود مسلمانوں کو رسول اللہ صلی اللہ علیہ وسلم کی زیارت، صحابیت اور اقتدا کا شرف حاصل ہو۔ حج کے افعال براہ راست آپ سے سیکھیں۔ آپ سے شریعت کے دیگر مسائل کا علم حاصل کریں اور مسلمانوں کی اجتماعیت اور شان وشوکت کا اظہار ہو۔ (۳) ’’نیت حج کی تھی۔‘‘ یعنی مدینے سے نکلتے وقت ورنہ احرام کے وقت تو بعض لوگوں نے عمرے کا احرام بھی باندھا تھا جیسا کہ پیچھے گزرا۔ یا اکثریت کی بات ہے۔ (۴) امام نسائی رحمہ اللہ نے شاید نیت کے الفاظ سے یہ استنباط کیا ہے کہ حج یا عمرے کی صراحت ضروری نہیں۔ ویسے اس حدیث میں متعلقہ مسئلے کی وضاحت نہیں۔ بہت سی روایات میں [لَبَّیْکَ بِعُمْرَۃٍ وَّ بَحَجَّۃٍ] کے الفاظ صراحتاً رسول اللہ صلی اللہ علیہ وسلم سے مذکور ہیں۔ دیکھیے: (صحیح البخاری، الحج، حدیث: ۱۵۶۳، وصحیح مسلم، الحج، حدیث: ۱۲۳۲) ویسے اس بات پر اتفاق ہے کہ نیت کافی ہے۔ لبیک کے ساتھ حج یا عمرے کی صراحت ضروری نہیں، البتہ ابتدائی لبیک میں ذکر ہو تو اچھی بات ہے۔"}],[2741,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ہم نکلے ہمارے پیش نظر صرف حج تھا۔ جب ہم سرف میں پہنچے تو میں حائضہ ہو گئی، تو رسول اللہ صلی اللہ علیہ وسلم میرے پاس آئے اور میں رو رہی تھی، آپ نے پوچھا: \"کیا تجھے حیض آ گیا ہے\" میں نے کہا: جی ہاں، آپ نے فرمایا: \"یہ تو ایسی چیز ہے جسے اللہ تعالی نے آدم زادیوں(عورتوں) پر لکھ دی ہے، تم وہ سب کام کرو جو احرام باندھنے والے کرتے ہیں، البتہ بیت اللہ طواف نہ کرنا\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ ہم (حجۃ الوداع میں) نکلے تو ہماری نیت صرف حج کی تھی۔ جب ہم سرف کے مقام پر پہنچے تو مجھے حیض شروع ہوگیا۔ رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف لائے تو میں رو رہی تھی۔ آپ نے فرمایا: ’’کیا تجھے حیض شروع ہوگیا ہے؟‘‘ میں نے کہا: جی ہاں۔ آپ نے فرمایا: ’’(کوئی بات نہیں) یہ ایسی چیز ہے جو آدم کی بیٹیوں پر اللہ تعالیٰ کی طرف سے مقرر ے، لہٰذا جو دوسرے محرم کریں، تو بھی کرتی رہ مگر بیت اللہ کا طواف نہ کرنا۔‘‘","f2":"(۱) ’’سرف کے مقام پر پہنچے۔‘‘ یہاں حدیث میں اختصار ہے کہ ہماری نیت تو حج کی تھی مگر آپ نے قربانی نہ لانے والے افراد کو حج کا احرام عمرے میں تبدیل کرنے کا حکم دیا۔ میں نے بھی حج کا احرام عمرے میں تبدیل کر لیا مگر اب حیض شروع ہوگیا۔ اس وجہ سے سیدہ عائشہ رضی اللہ عنہا کو پریشانی لاحق ہوئی تو رسول اللہ صلی اللہ علیہ وسلم نے مذکورہ طریقے کی وضاحت فرما کر پریشانی دور فرما دی۔ (۲) ’’جو دوسرے محرم کریں‘‘ دوسرے معنی یہ بھی ہو سکتے ہیں کہ جو محرم کرتا ہے، وہ تو بھی کر۔"}],[2742,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ میں یمن سے آیا، اور نبی اکرم صلی اللہ علیہ وسلم بطحاء میں جہاں کہ آپ نے حج کیا تھا اونٹ بٹھائے ہوئے تھے، آپ نے(مجھ سے) پوچھا: \"کیا تم نے حج کا ارادہ کیا ہے؟\" میں نے کہا: جی ہاں، آپ نے پوچھا: \"تم نے کیسے کہا؟\" انہوں نے کہا: میں نے یوں کہا: «لبيك بإهلال كإهلال النبي صلى اللہ عليه وسلم» \"میں حاضر ہوں اس تلبیہ کے ساتھ جو نبی اکرم صلی اللہ علیہ وسلم کا تلبیہ ہے\" آپ نے فرمایا: \"بیت اللہ کا طواف کر لو، اور صفا و مروہ کے درمیان سعی کر لو، پھر احرام کھول کر حلال ہو جاؤ\"، میں نے ایسے ہی کیا، پھر میں ایک عورت کے پاس آیا، اس نے میرے سر سے جوئیں نکالیں۔ تو میں اسی کے مطابق لوگوں کو فتوی دینے لگا یہاں تک کہ عمر رضی اللہ عنہ کے دور خلافت میں مجھ سے ایک شخص کہنے لگا: ابوموسی! تم اپنے بعض فتوے دینے بند کر دو، کیونکہ تمہیں معلوم نہیں ہے کہ تمہارے بعد امیر المؤمنین نے حج کے سلسلے میں کیا نیا حکم جاری کیا ہے۔ (یہ سن کر) ابوموسی اشعری رضی اللہ عنہ نے کہا: لوگو! جس کو بھی میں نے فتوی دیا ہو وہ توقف کرے کیونکہ امیر المؤمنین تمہارے پاس آنے والے ہیں (وہ جیسا بتائیں) ان کی پیروی کرو۔ (اور جب عمر رضی اللہ عنہ کے سامنے یہ بات آئی تو) انہوں نے کہا: اگر ہم اللہ کی کتاب (قرآن) کو لیں تو وہ (حج اور عمرہ کو) پورا کرنے کا حکم دے رہی ہے اور اگر ہم نبی اکرم صلی اللہ علیہ وسلم کی سنت کو لیں تو آپ کی سنت یہ رہی ہے کہ آپ نے اپنا احرام نہیں کھولا جب تک کہ ہدی اپنے ٹھکانے پر نہیں پہنچ گئی۔","الألباني: صحيح",{"u2":"حضرت ابو موسیٰ رضی اللہ عنہ سے مروی ہے کہ میں (حجۃ الوداع کے موقع پر) یمن سے آیا تو نبی صلی اللہ علیہ وسلم نے بطحاء (مکہ) میں پڑاؤ ڈال رکھا تھا۔ آپ نے فرمایا: ’’تو نے احرام باندھا ہے؟‘‘ میں نے عرض کیا: جی ہاں۔ آپ نے فرمایا: ’’کیسے باندھا ہے؟‘‘ انھوں نے کہا: میں نے کہا تھا: اس احرام کے ساتھ جو نبی صلی اللہ علیہ وسلم کا احرام ہے، لبیک کہتا ہوں۔ آپ نے فرمایا: ’’بیت اللہ کا طواف کرو اور صفا مروہ کی سعی کرو اور حلال ہو جاؤ۔‘‘ میں نے اسی طرح کیا، پھر میں (اپنے قبیلے کی) ایک عورت کے پاس آیا تو اس نے میرے سر سے جوئیں نکالیں۔ میں لوگوں کو اسی بات کا فتویٰ دیا کرتا تھا (کہ تمتع جائز ہے) حتیٰ کہ حضرت عمر رضی اللہ عنہ کی خلافت کا دور آگیا تو ایک آدمی نے مجھ سے کہا: اے ابو موسیٰ! اپنا یہ فتویٰ روک لو۔ شاید تم نہیں جانتے کہ امیرالمومنین نے تمھارے بعد حج کے بارے میں کیا نیا حکم جاری کیا ہے؟ میں نے کہا: اے لوگو! جس شخص کو ہم نے یہ فتویٰ دیا ہو، وہ ذرا انتظار کر لے (یعنی اس پر عمل نہ کرے)، حضرت امیرالمومنین تمھارے پاس تشریف لانے والے ہیں تو تم ان کے حکم کی پابندی کرنا۔ حضرت عمر رضی اللہ عنہ (آئے تو میرے استفسار پر) کہنے لگے: اگر ہم اللہ کی کتاب کو لیں تو وہ ہمیں مکمل کرنے کا حکم دیتی ہے اور اگر ہم نبی صلی اللہ علیہ وسلم کی سنت مبارکہ کو لیں تو نبی صلی اللہ علیہ وسلم حلال نہیں ہوئے تھے حتیٰ کہ قربانیاں ذبح ہوگئیں۔","f2":"باب کا مقصد یہ ہے کہ احرام باندھتے وقت کوئی ضروری نہیں کہ حج یا عمرے کی معین نیت کی جائے بلکہ کسی دوسرے کی نیت سے انھیں معلق بھی کیا جا سکتا ہے۔ البتہ افعال شروع کرنے سے قبل تعین ہو جانا ضروری ہے جیسا کہ مذکو رہ بالا صورت میں ہوا کہ حضرت ابو موسیٰ رضی اللہ عنہ نے ابتداء ً تو احرام مبہم رکھا (کَاِھْلَالِ النَّنِیِّ)، پھر افعال شروع ہونے سے قبل آپ نے وضاحت فرما دی کہ عمرہ کر کے حلال ہوجاؤ۔ آئندہ حدیث میں بھی یہی صورت ہے۔ (تفصیل کے لیے دیکھیے، حدیث: ۲۷۳۹)"}]]);
